        private static void WriteSelfTestDiagnostic(string text)
        {
            try
            {
                string diagnosticPath = Environment.GetEnvironmentVariable("YOMI_SELFTEST_DIAGNOSTIC");
                if (!String.IsNullOrWhiteSpace(diagnosticPath))
                    File.WriteAllText(diagnosticPath, text ?? "", new UTF8Encoding(false));
            }
            catch { }
        }

        private static int StagedSelfTestFailure(string detail)
        {
            string message =
                "YOMI staged WPF self-test failed" + Environment.NewLine +
                "exit_code=3" + Environment.NewLine +
                "phase=post-xaml-load-semantic-probe" + Environment.NewLine +
                "detail=" + (detail ?? "");
            WriteSelfTestDiagnostic(message);
            return 3;
        }

        private static int StartupSelfTestFailure(int code, string testName, ControllerHost controller)
        {
            string detail = "";
            try { detail = controller == null ? "" : controller.SelfTestFailureDetail; } catch { }
            string message =
                "YOMI startup self-test failed" + Environment.NewLine +
                "exit_code=" + code.ToString(CultureInfo.InvariantCulture) + Environment.NewLine +
                "test=" + (testName ?? "") + Environment.NewLine +
                "detail=" + (detail ?? "");
            WriteSelfTestDiagnostic(message);
            return code;
        }

        [STAThread]
        public static int Main(string[] args)
        {
            bool installProbe = args != null && args.Any(a => String.Equals(a, "--install-probe", StringComparison.OrdinalIgnoreCase));
            bool selfTest = args != null && args.Any(a => String.Equals(a, "--self-test", StringComparison.OrdinalIgnoreCase));
            bool startupSelfTest = args != null && args.Any(a => String.Equals(a, "--startup-self-test", StringComparison.OrdinalIgnoreCase));
            bool startupSelfTestAll = args != null && args.Any(a => String.Equals(a, "--startup-self-test-all", StringComparison.OrdinalIgnoreCase));
            bool anySelfTest = installProbe || selfTest || startupSelfTest || startupSelfTestAll;
            bool created = false;
            string mutexName = anySelfTest
                ? @"Local\YOMI_CONTROLLER_WPF_SELFTEST_" + Guid.NewGuid().ToString("N")
                : @"Local\YOMI_CONTROLLER_WPF_DEV13_59";
            using (var mutex = new Mutex(true, mutexName, out created))
            {
                if (!created)
                    return anySelfTest ? 4 : 0;

                try
                {
                    string appDir = AppDomain.CurrentDomain.BaseDirectory.TrimEnd('\\');
                    string installRoot = Environment.GetEnvironmentVariable("YOMI_INSTALL_ROOT");
                    if (String.IsNullOrWhiteSpace(installRoot))
                        installRoot = Directory.GetParent(appDir).FullName;

                    string dataRoot = Path.Combine(
                        Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                        "YOMI"
                    );
                    if (anySelfTest)
                    {
                        string isolatedDataRoot = Environment.GetEnvironmentVariable("YOMI_SELFTEST_DATA_ROOT");
                        if (!String.IsNullOrWhiteSpace(isolatedDataRoot))
                            dataRoot = Path.GetFullPath(isolatedDataRoot);
                    }

                    string designPath = Path.Combine(appDir, "YomiDesign.xaml");
                    string windowPath = Path.Combine(appDir, "YomiControllerWpf.xaml");

                    if (!File.Exists(designPath) || !File.Exists(windowPath))
                        return 2;

                    var app = new Application();
                    app.ShutdownMode = ShutdownMode.OnExplicitShutdown;

                    using (var stream = File.OpenRead(designPath))
                    {
                        var design = (ResourceDictionary)XamlReader.Load(stream);
                        app.Resources.MergedDictionaries.Add(design);
                    }

                    Window window;
                    using (var stream = File.OpenRead(windowPath))
                        window = (Window)XamlReader.Load(stream);

                    // Install verification only proves that the shipped WPF resources and
                    // window can load. Strict semantic/fidelity assertions remain dev tests.
                    if (installProbe)
