        public ControllerHost(Application app, Window window, string installRoot, string dataRoot, string appDir)
        {
            _app = app;
            _window = window;
            _installRoot = Path.GetFullPath(installRoot);
            _dataRoot = Path.GetFullPath(dataRoot);
            _appDir = Path.GetFullPath(appDir);
            _stateRoot = Path.Combine(_dataRoot, "state");
            _cacheRoot = Path.Combine(_dataRoot, "cache");
            _objectRoot = Path.Combine(_cacheRoot, "objects");
            _runtimeRoot = Path.Combine(_installRoot, "runtime");
            _slotsRoot = Path.Combine(_dataRoot, "slots");
            _json = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
            _timer = new DispatcherTimer(DispatcherPriority.Background) { Interval = TimeSpan.FromMilliseconds(350) };
            _uiHeartbeatTimer = new DispatcherTimer(DispatcherPriority.Background) { Interval = TimeSpan.FromMilliseconds(250) };
            _queueSearchDebounce = new DispatcherTimer(DispatcherPriority.Background) { Interval = TimeSpan.FromMilliseconds(120) };
            _queueSearchDebounce.Tick += delegate { _queueSearchDebounce.Stop(); ApplyQueueFilterRefresh(); };
            _settingsLivePreviewTimer = new DispatcherTimer(DispatcherPriority.Background) { Interval = TimeSpan.FromMilliseconds(90) };
            _settingsLivePreviewTimer.Tick += delegate { _settingsLivePreviewTimer.Stop(); PublishSettingsLivePreview(); };
            ClearSettingsLivePreview();
            InitializeRuntimeJob();
        }

        public void Initialize()
        {
            BindControls();
            BuildHostedPanels();
            EnsureListeningSlotFoundation();
            LoadUiState();
            NormalizeObsPackageConfiguration();
            LoadLibraryState();
            LoadQueueCheckpoints();
            LoadIntentJournal();
            ConfigureApplicationIdentity();
            WireWindow();
            WireTransport();
            WireVolume();
            // R61.106.27: project remembered volume/mute before the first WPF frame.
            if (_volumePreferenceLoaded) ApplyVolumeUi();
            WireMenus();
            WireClassicMenus();
            WireIntegratedSettings();
            EnsureDetachedSettingsWindow();
            WireListeningSlots();
            WirePlaylistPool();
            WirePlaylistEditor();
            WireQueue();
            ApplyQueueDensity(false);
            WireCommandPalette();
            WireOperatorDeck();
            WireIntentFabric();
            WireInspector();
            if (String.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("YOMI_SELFTEST_DATA_ROOT")))
                ConfigureTray();
            ApplyAppearancePreset(false);
            ApplyInformationDensity(false);
            ApplyMediaMode(false);
            ApplyVisualizerPresentation(false);
            ApplyVisualizerMode(false);
            if (_workspaceProfile != WorkspaceProfile.Custom)
                ApplyWorkspaceProfile(_workspaceProfile, false);
            else
                ApplyWorkspaceMode(false);
            ApplyQuietSurface(false);
            // Maximizing is a window operation, not a Queue command. Preserve the operator's
            // saved Queue intent; never materialize thousands of rows just because Windows
            // changes WindowState during startup.
            bool reopenQueue = _queueOpen;
            _queueOpen = false;
            _window.Topmost = false;
            if (_restoreMaximized && !_miniMode)
                _window.WindowState = WindowState.Maximized;
            _lastWindowState = _window.WindowState;
            ApplyInstrumentActivity(_window.IsActive);
            UpdateControllerCadence();
            // R61.95 AUDIO-FIRST CONTROLLER STARTUP: paint the truthful Loading shell first,
            // launch prewarm immediately, and let Queue/session hydration trail on Background.
            // Cached audio must never wait behind 2,800-row metadata projection. Isolated self-tests
            // retain synchronous hydration because they validate state deterministically.
            bool isolatedStartupSelfTest = !String.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable("YOMI_SELFTEST_DATA_ROOT"));
            if (isolatedStartupSelfTest)
            {
                SafeRefresh(true);
                _window.Show();
                SetQueueOpen(reopenQueue, false);
                SafeRefresh(true);
                _windowPersistenceReady = true;
                CaptureNormalWindowGeometry();
                SaveUiState();
                PresentOrientationIfNeeded();
            }
            else
            {
                UpdateStatusBarProjection();
                if (_statusPlaybackText != null) _statusPlaybackText.Text = reopenQueue ? "Loading track info..." : "Loading playlist...";
                _window.Show();
                BeginStartupPrewarm();
                if (_statusPlaybackText != null) _statusPlaybackText.Text = reopenQueue ? "Loading track info..." : "Loading playlist...";
                _windowPersistenceReady = true;
                PresentOrientationIfNeeded();
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    if (_disposed) return;
                    SetQueueOpen(reopenQueue, false);
                    SafeRefresh(true);
                    CaptureNormalWindowGeometry();
                    SaveUiState();
                }));
            }
            _timer.Tick += delegate
            {
                long tickStart = _clock.ElapsedMilliseconds;
                SafeRefresh(false);
                long refreshMs = _clock.ElapsedMilliseconds - tickStart;
                if (refreshMs >= 650 && _clock.ElapsedMilliseconds - _lastUiStallLoggedMs >= 2500)
                {
                    _lastUiStallLoggedMs = _clock.ElapsedMilliseconds;
                    WriteControllerPerformanceLogAsync("REFRESH SLOW " + refreshMs.ToString(CultureInfo.InvariantCulture) + "ms");
                }
            };
            _timer.Start();
            // R61.86: measure dispatcher liveness independently from controller refresh cadence.
            // Hidden/minimized YOMI intentionally refreshes as slowly as 2.5-4.0 seconds; using that
            // timer as the heartbeat made healthy idle periods look exactly like multi-second hangs.
            _lastUiHeartbeatMs = _clock.ElapsedMilliseconds;
            _uiHeartbeatTimer.Tick += delegate
            {
                long beat = _clock.ElapsedMilliseconds;
                long previous = Interlocked.Exchange(ref _lastUiHeartbeatMs, beat);
                long gap = previous > 0 ? beat - previous : 0;
                if (gap >= 1400 && beat - _lastUiStallLoggedMs >= 5000)
                {
                    _lastUiStallLoggedMs = beat;
                    WriteControllerPerformanceLogAsync("UI HEARTBEAT GAP " + gap.ToString(CultureInfo.InvariantCulture) + "ms phase=" + (_uiOperationPhase ?? "unknown"));
                }
            };
            _uiHeartbeatTimer.Start();
            if (!isolatedStartupSelfTest)
                _window.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle, new Action(delegate { if (!_disposed) CheckForUpdates(true); }));
            // Independent watchdog: unlike DispatcherTimer diagnostics, this still runs while the
            // dispatcher is genuinely wedged. It does not touch WPF; it only records the duration
            // so a future support log identifies a UI-thread stall instead of looking mysteriously idle.
            _uiWatchdogTimer = new System.Threading.Timer(delegate(object ignored)
            {
                if (_disposed) return;
                long sample = _clock.ElapsedMilliseconds;
                long heartbeat = Interlocked.Read(ref _lastUiHeartbeatMs);
                long gap = heartbeat > 0 ? sample - heartbeat : 0;
                if (gap >= 1800 && sample - Interlocked.Read(ref _lastWatchdogReportMs) >= 5000)
                {
                    Interlocked.Exchange(ref _lastWatchdogReportMs, sample);
                    string phase = _uiOperationPhase ?? "unknown";
                    WriteControllerPerformanceLogAsync("UI WATCHDOG STALL " + gap.ToString(CultureInfo.InvariantCulture) + "ms phase=" + phase);
                }
            }, null, 1000, 1000);
        }

        private T Find<T>(string name) where T : class
        {
            var value = _window.FindName(name) as T;
            if (value == null)
                throw new InvalidOperationException("Required YOMI WPF element missing: " + name);
            return value;
        }

