            _inspectorSourceText = Find<TextBox>("InspectorSourceText");
            _inspectorMemoryText = Find<TextBox>("InspectorMemoryText");
            _inspectorReadinessText = Find<TextBox>("InspectorReadinessText");
            _inspectorMediaText = Find<TextBox>("InspectorMediaText");
            _inspectorRouteText = Find<TextBox>("InspectorRouteText");
            _inspectorRouteHistoryText = Find<TextBox>("InspectorRouteHistoryText");
            _inspectorSystemSummaryText = Find<TextBox>("InspectorSystemSummaryText");
            _inspectorRuntimeText = Find<TextBox>("InspectorRuntimeText");
            _inspectorSessionText = Find<TextBox>("InspectorSessionText");
            _inspectorActivityText = Find<TextBox>("InspectorActivityText");
            _inspectorCopyButton = Find<Button>("InspectorCopyButton");
            _inspectorOpenSourceButton = Find<Button>("InspectorOpenSourceButton");
            _inspectorCloseButton = Find<Button>("InspectorCloseButton");
            _toastHost = Find<Border>("ToastHost");
            _toastTitle = Find<TextBlock>("ToastTitle");
            _toastBody = Find<TextBlock>("ToastBody");
        }

        private void BuildHostedPanels()
        {
            // R61.94: native H.264 composition is primary for real video. The visualizer's
            // MediaElement remains only as an inert compatibility object; no live visualizer
            // route uses it because the binary-color contract requires raw quantized frames.
            ConfigurePreviewElement(_videoHost, false);
            ConfigurePreviewElement(_visualizerHost, true);
            if (_videoHost != null) _videoHost.Visibility = Visibility.Collapsed;
            if (_visualizerHost != null) _visualizerHost.Visibility = Visibility.Collapsed;
            if (_videoFrameHost != null) _videoFrameHost.Visibility = Visibility.Collapsed;
            if (_visualizerFrameHost != null) _visualizerFrameHost.Visibility = Visibility.Collapsed;
        }

        private void ConfigurePreviewElement(MediaElement media, bool visualizer)
        {
            if (media == null) return;
            media.LoadedBehavior = MediaState.Manual;
            media.UnloadedBehavior = MediaState.Manual;
            media.IsMuted = true;
            media.ScrubbingEnabled = true;
        }

        private void DetachNativePreviewHandlers(MediaElement media, bool visualizer)
        {
            if (media == null) return;
            if (visualizer)
            {
                if (_visualizerNativeOpenedHandler != null) media.MediaOpened -= _visualizerNativeOpenedHandler;
                if (_visualizerNativeEndedHandler != null) media.MediaEnded -= _visualizerNativeEndedHandler;
                if (_visualizerNativeFailedHandler != null) media.MediaFailed -= _visualizerNativeFailedHandler;
                _visualizerNativeOpenedHandler = null; _visualizerNativeEndedHandler = null; _visualizerNativeFailedHandler = null;
            }
            else
            {
                if (_videoNativeOpenedHandler != null) media.MediaOpened -= _videoNativeOpenedHandler;
                if (_videoNativeEndedHandler != null) media.MediaEnded -= _videoNativeEndedHandler;
                if (_videoNativeFailedHandler != null) media.MediaFailed -= _videoNativeFailedHandler;
                _videoNativeOpenedHandler = null; _videoNativeEndedHandler = null; _videoNativeFailedHandler = null;
            }
        }

        private void AttachNativePreviewHandlers(MediaElement media, bool visualizer, string expectedPath, int generation)
        {
            if (media == null) return;
            DetachNativePreviewHandlers(media, visualizer);
            string expected = expectedPath ?? "";
            RoutedEventHandler opened = delegate
            {
                int liveGeneration = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
                if (generation != liveGeneration || !NativeMediaSourceMatches(media, expected)) return;
                double start = visualizer ? _visualizerPreviewStartSeconds : _videoPreviewStartSeconds;
                SetPreviewPosition(media, start);
                bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                try { if (paused) media.Pause(); else media.Play(); } catch { }

                if (visualizer)
                {
                    _visualizerNativePreviewActive = true;
                    _visualizerPreviewBackend = "native-media";
                    _visualizerPreviewFailed = false; _visualizerPreviewFailure = ""; _visualizerPreviewReady = true;
                    _visualizerNativeOpenedMs = _clock.ElapsedMilliseconds;
                    if (_visualizerFramePreview != null) { try { _visualizerFramePreview.Dispose(); } catch { } _visualizerFramePreview = null; }
                    if (_visualizerFrameHost != null) { _visualizerFrameHost.Source = null; _visualizerFrameHost.Visibility = Visibility.Collapsed; }
                    if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                    media.Visibility = Visibility.Visible;
                    WritePreviewRendererLog("VISUALIZER NATIVE OPEN " + expected + " @ " + start.ToString("0.###", CultureInfo.InvariantCulture));
                    WritePreviewRendererLog("VISUALIZER NATIVE CLOCK FREE-RUN edge-synchronized");
                    SchedulePresentationStatusWrite(true);
                    return;
                }

                _videoNativePreviewActive = true;
                _nativeVideoClockBadSamples = 0;
                _videoPreviewBackend = "native-settling";
                _videoPreviewFailed = false; _videoPreviewFailure = ""; _videoPreviewReady = false;
                _videoNativeOpenedMs = _clock.ElapsedMilliseconds;
                if (_videoFramePreview != null) { try { _videoFramePreview.Dispose(); } catch { } _videoFramePreview = null; }
                if (_videoFrameHost != null) { _videoFrameHost.Source = null; _videoFrameHost.Visibility = Visibility.Collapsed; }
                media.Visibility = Visibility.Visible;
                media.Opacity = 0.0;
                ScheduleNativeVideoStableReveal(media, expected, generation, 90, 2);
            };
            RoutedEventHandler ended = delegate
            {
                int liveGeneration = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
                if (generation != liveGeneration || !NativeMediaSourceMatches(media, expected)) return;
                try
                {
                    media.Position = TimeSpan.Zero;
                    bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                    if (!paused) media.Play();
                }
                catch { }
            };
            EventHandler<ExceptionRoutedEventArgs> failed = delegate(object sender, ExceptionRoutedEventArgs e)
            {
                int liveGeneration = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
                if (generation != liveGeneration || !NativeMediaSourceMatches(media, expected)) return;
                string detail = e != null && e.ErrorException != null ? e.ErrorException.Message : "Windows media pipeline could not decode the cached preview.";
                FallbackNativePreview(visualizer, generation, "MediaFailed: " + detail);
            };
            if (visualizer)
            {
                _visualizerNativeOpenedHandler = opened; _visualizerNativeEndedHandler = ended; _visualizerNativeFailedHandler = failed;
            }
            else
            {
                _videoNativeOpenedHandler = opened; _videoNativeEndedHandler = ended; _videoNativeFailedHandler = failed;
            }
            media.MediaOpened += opened;
            media.MediaEnded += ended;
            media.MediaFailed += failed;
        }

        private void ScheduleNativeVideoStableReveal(MediaElement media, string expected, int generation, int delayMs, int remainingSeekSettles)
        {
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                Thread.Sleep(Math.Max(0, delayMs));
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Render, delegate
                    {
                        if (_disposed || generation != _videoNativePreviewGeneration || !NativeMediaSourceMatches(media, expected)) return;
                        double target = Math.Max(0, _timePosition);
                        double drift = 0;
                        try { drift = media.Position.TotalSeconds - target; } catch { }
                        if (remainingSeekSettles > 0 && Math.Abs(drift) > 0.30)
                        {
                            // Seek while still hidden, then give MediaElement a render edge to commit the
                            // post-seek frame. Never expose frame zero merely because MediaOpened fired.
                            SetPreviewPosition(media, target);
                            ScheduleNativeVideoStableReveal(media, expected, generation, 70, remainingSeekSettles - 1);
                            return;
                        }
                        bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
                        try { if (paused) media.Pause(); else media.Play(); } catch { }
                        if (!VideoRequestMatches(expected, _videoRequestedGeneration, _videoRequestedOccurrence)) return;
                        double naturalAspect = 0;
                        try
                        {
                            if (media.NaturalVideoWidth > 0 && media.NaturalVideoHeight > 0)
                                naturalAspect = (double)media.NaturalVideoWidth / (double)media.NaturalVideoHeight;
                        }
                        catch { }
                        _videoPreviewBackend = "native-media";
                        _videoPreviewReady = true;
                        if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                        CommitVideoPresentation(expected, _videoRequestedGeneration, _videoRequestedOccurrence, naturalAspect);
                        media.Visibility = Visibility.Visible;
                        media.Opacity = 1.0;
                        WritePreviewRendererLog("VIDEO NATIVE STABLE REVEAL " + expected + " @ " + target.ToString("0.###", CultureInfo.InvariantCulture) + " drift=" + drift.ToString("0.###", CultureInfo.InvariantCulture));
                        SyncHostedMediaAirspace();
                        SchedulePresentationStatusWrite(true);
                    });
                }
                catch { }
            });
        }

        private static bool NativeMediaSourceMatches(MediaElement media, string expectedFile)
        {
            if (media == null || media.Source == null || String.IsNullOrWhiteSpace(expectedFile)) return false;
            try
            {
                string actual = media.Source.IsFile ? media.Source.LocalPath : media.Source.ToString();
                return String.Equals(Path.GetFullPath(actual), Path.GetFullPath(expectedFile), StringComparison.OrdinalIgnoreCase);
            }
            catch { return false; }
        }

        private static double PreviewPositionWithinMedia(MediaElement media, double requested)
        {
            double value = Math.Max(0, requested);
            try
            {
                if (media != null && media.NaturalDuration.HasTimeSpan)
                {
                    double duration = media.NaturalDuration.TimeSpan.TotalSeconds;
                    if (duration > 0.25 && value >= duration) value %= duration;
                }
            }
            catch { }
            return value;
        }

        private static void SetPreviewPosition(MediaElement media, double requested)
        {
            if (media == null) return;
            try { media.Position = TimeSpan.FromSeconds(PreviewPositionWithinMedia(media, requested)); } catch { }
        }

        private bool HasModalWpfOverlay()
        {
            return (_settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible) ||
                   (_slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible) ||
                   (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible) ||
                   (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible) ||
                   (_commandPaletteOverlay != null && _commandPaletteOverlay.Visibility == Visibility.Visible) ||
                   (_operatorDeckOverlay != null && _operatorDeckOverlay.Visibility == Visibility.Visible) ||
                   (_intentFabricOverlay != null && _intentFabricOverlay.Visibility == Visibility.Visible);
        }

        private void SyncHostedMediaAirspace()
        {
            bool videoNative = _videoNativePreviewActive && _videoPreviewReady;
            bool videoNativeWarm = String.Equals(_videoPreviewBackend, "native-opening", StringComparison.Ordinal) ||
                                   String.Equals(_videoPreviewBackend, "native-settling", StringComparison.Ordinal);
            bool vizNative = _visualizerNativePreviewActive && _visualizerPreviewReady && _visualizerEnabled;
            bool vizBridge = _visualizerBridgeHold && _visualizerEnabled && _visualizerFrameHost != null && _visualizerFrameHost.Source != null;
            if (_videoHost != null)
            {
                _videoHost.Visibility = (videoNative || videoNativeWarm) ? Visibility.Visible : Visibility.Collapsed;
                _videoHost.Opacity = videoNativeWarm ? 0.0 : 1.0;
            }
            if (_visualizerHost != null) _visualizerHost.Visibility = vizNative ? Visibility.Visible : Visibility.Collapsed;
            if (_videoFrameHost != null) _videoFrameHost.Visibility = (!videoNative && !videoNativeWarm && _videoPreviewReady && _videoFramePreview != null) ? Visibility.Visible : Visibility.Collapsed;
            if (_visualizerFrameHost != null) _visualizerFrameHost.Visibility = (!vizNative && _visualizerEnabled && ((_visualizerPreviewReady && _visualizerFramePreview != null) || vizBridge)) ? Visibility.Visible : Visibility.Collapsed;
        }

        private bool TrySwitchListeningSlotShortcut(Key key)
        {
            int index = -1;
            int keyValue = (int)key;
            if (keyValue >= (int)Key.D1 && keyValue <= (int)Key.D9) index = keyValue - (int)Key.D1;
            else if (keyValue >= (int)Key.NumPad1 && keyValue <= (int)Key.NumPad9) index = keyValue - (int)Key.NumPad1;
            if (index < 0 || index >= _slotItems.Count || _slotSwitchActive) return false;
            SlotRecord target = _slotItems[index];
            if (target == null) return false;
            if (String.Equals(target.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase))
            {
                ShowToast("Listening session", target.Name + " is already active.");
                return true;
            }
            SwitchListeningSlot(target.Id, "shortcut " + (index + 1).ToString(CultureInfo.InvariantCulture));
            return true;
        }

        internal static void WriteRuntimeCrashDiagnostic(string scope, Exception ex)
        {
            try
            {
                string crashRoot = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "YOMI");
                Directory.CreateDirectory(crashRoot);
                string line = DateTime.Now.ToString("O", CultureInfo.InvariantCulture) + " | " + (scope ?? "runtime") + Environment.NewLine +
                    (ex == null ? "unknown exception" : ex.ToString()) + Environment.NewLine + Environment.NewLine;
                File.AppendAllText(Path.Combine(crashRoot, "controller-crash.log"), line, new UTF8Encoding(false));
            }
            catch { }
        }

        private void WireWindow()
        {
            _window.SourceInitialized += delegate
            {
                TryEnableModernWindowChrome();
                ConstrainWindowToVisibleWorkArea();
                try
                {
                    _windowSource = HwndSource.FromHwnd(new WindowInteropHelper(_window).Handle);
                    if (_windowSource != null) _windowSource.AddHook(WindowMessageHook);
                    SyncWindowCompositionBackground();
                }
                catch { _windowSource = null; }
            };

            Button menuRestore = _window.FindName("MenuRestoreButton") as Button;
            if (menuRestore != null) menuRestore.Click += delegate { SetMenuBarVisible(true, true); };

            _minimizeButton.Click += delegate { _window.WindowState = WindowState.Minimized; };
            _maximizeButton.Click += delegate { ToggleMaximize(); };
            _closeButton.Click += delegate { StopYomiAndExit(); };

            _window.StateChanged += delegate
            {
                WindowState previous = _lastWindowState;
                WindowState current = _window.WindowState;
                UpdateMaximizeGlyph();

                if (current == WindowState.Minimized)
                {
                    // Minimize is presentation suspension only. Preserve whether the user
                    // came from maximized state and stop only the child preview HWNDs.
                    StopPreviewProcesses();
                }
                else
                {
                    if (current == WindowState.Maximized)
                        _restoreMaximized = true;
                    else if (current == WindowState.Normal)
                        _restoreMaximized = false;

                    // R61: maximize/restore does not restart healthy previews. Only a real
                    // return from minimized state needs the hosted preview surfaces rebuilt.
                    if (previous == WindowState.Minimized)
                    {
                        if (current == WindowState.Normal)
                            RestoreLogicalNormalGeometry();
                        _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                        {
                            RestartFramePreviewsAt(_timePosition, true);
                            SafeRefresh(true);
                        }));
                    }
                    else if (previous == WindowState.Maximized && current == WindowState.Normal)
                    {
                        RestoreLogicalNormalGeometry();
                    }

                    // Maximize/restore preserves Queue intent. Do not synchronously open or
                    // rebuild Queue from StateChanged; large sessions made that transition feel
                    // like a full-screen hang and could block Windows' own resize sequence.
                }

                _lastWindowState = current;
                ApplyQueueCanvasLayout(true);
                UpdateControllerCadence();
                SaveUiState();
            };

            _window.Activated += delegate { ApplyInstrumentActivity(true); UpdateControllerCadence(); QueueControllerWakeRefresh(); };
            _window.Deactivated += delegate { ApplyInstrumentActivity(false); UpdateControllerCadence(); };

            // R61.106.8: Search Queue is an editing mode only while the actual text box owns focus.
            // Any pointer press elsewhere in the YOMI window immediately returns keyboard focus to
            // the shell/control that was clicked instead of leaving an invisible caret armed.
            if (_statusObsText != null)
            {
                _statusObsText.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
                {
                    bool packageOn = ObsIntegrationEnabled() && ObsMediaCacheEnabled();
                    SetObsPackageEnabled(!packageOn);
                    e.Handled = true;
                };
            }

            _window.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                DependencyObject source = e.OriginalSource as DependencyObject;

                // A Queue row highlight is an editing/selection state, not the NOW-playing marker.
                // Clicking elsewhere in the YOMI window clears manual selection while the separate
                // current-track presentation remains intact. Preserve selection only long enough for
                // row clicks and the selected-row action deck to act on their intended targets.
                if (_queueList != null && _queueList.SelectedItems.Count > 0 && source != null)
                {
                    ListBoxItem queueRow = FindVisualParent<ListBoxItem>(source);
                    bool insideQueueRow = queueRow != null && IsVisualDescendantOf(queueRow, _queueList);
                    bool selectionAction = _queueSelectionBar != null && IsVisualDescendantOf(source, _queueSelectionBar);
                    if (!insideQueueRow && !selectionAction) _queueList.SelectedItems.Clear();
                }

                if (_queueSearchBox == null || !_queueSearchBox.IsKeyboardFocusWithin) return;
                if (source != null && IsVisualDescendantOf(source, _queueSearchBox)) return;
                Keyboard.ClearFocus();
            };

            _window.IsVisibleChanged += delegate
            {
                if (!_window.IsVisible)
                    StopPreviewProcesses();
                else
                {
                    RestartFramePreviewsAt(_timePosition, true);
                    QueueControllerWakeRefresh();
                }
                UpdateControllerCadence();
            };

            _window.Closing += delegate(object sender, CancelEventArgs e)
            {
                SaveUiState();
                if (_controllerOnlyClose) return;
                if (_slotSwitchActive)
                {
                    e.Cancel = true; _shutdownRequested = true; _shutdownAfterSlotSwitch = true; Interlocked.Increment(ref _transportCommandEpoch); return;
                }
                if (!_shutdownRequested)
                {
                    _shutdownRequested = true; Interlocked.Increment(ref _slotStateEpoch); Interlocked.Increment(ref _transportCommandEpoch);
                    try { FinalizeListeningVisit(true,true); SlotRecord activeSlot; if(_slotsById.TryGetValue(_activeSlotId??"",out activeSlot)&&activeSlot!=null)CaptureLiveSlotBookmark(activeSlot); } catch { }
                    if(!StopOwnedYomiRuntime()){_shutdownRequested=false;e.Cancel=true;ReportShutdownOwnershipFailure();}
                    else { PersistRepeatModeForTransition(_repeatMode); try{PersistActiveSlotState(false);}catch{} }
                }
            };

            _window.Closed += delegate
            {
                _timer.Stop();
                _queueSearchDebounce.Stop();
                ClearSettingsLivePreview();
                try { if (_windowSource != null) _windowSource.RemoveHook(WindowMessageHook); } catch { }
                _windowSource = null;
                StopPreviewProcesses();
                if (_tray != null)
                    _tray.Visible = false;
                _app.Shutdown();
            };

            _window.SizeChanged += delegate
            {
                // Programmatic Queue/controller/media geometry changes must not feed their new shell
                // rectangle back into responsive topology during the same layout pass. The active
                // workspace is authoritative; only the outer window is changing here.
                if (_internalGeometryChange)
                {
                    UpdateProgressVisual();
                    return;
                }
                // Native drag/resize can deliver dozens of SizeChanged events per second. Do not
                // mutate the player topology while Windows owns the sizing loop: that used to make
                // controls jump between rows repeatedly and could drive recursive layout invalidation.
                if (_liveResize)
                {
                    UpdateProgressVisual();
                    return;
                }
                ApplyAutomaticScaleTier();
                ApplyCompactLayoutForSize();
                if (!_windowStateTransition) CaptureNormalWindowGeometry();
                ApplyAdaptiveLayout(false);
                ApplyQueueCanvasLayout(false);
                if (_queueCanvasActive) _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(ApplyQueuePlayerCompressionForCurrentHeight));
                ApplyQueueTableColumnFit();
                UpdateProgressVisual();
            };
            _window.LocationChanged += delegate { if (!_liveResize && !_windowStateTransition) CaptureNormalWindowGeometry(); };
            _window.PreviewMouseMove += WindowPreviewMouseMoveStatus;
            _window.MouseLeave += delegate { _lastHoverStatusSource = null; if (_hoverStatusText != null) _hoverStatusText.Text = ""; };
            _window.PreviewKeyDown += WindowPreviewKeyDown;
        }

        private static WorkspaceProfile ResolveAutomaticScaleProfile(double width, double height, WorkspaceProfile fullProfile)
        {
            // R61.95: a short window is the normal Queue-closed controller, not Micro.
            // Micro is reserved for genuinely narrow appliance geometry.
            if (width <= AutomaticMicroEnterWidth) return WorkspaceProfile.Micro;
            return IsContextWorkspace(fullProfile) ? fullProfile : WorkspaceProfile.Player;
        }

        private static WorkspaceProfile ResolveResponsiveWorkspaceProfile(double width, double height, WorkspaceProfile fullProfile, bool queueOpen)
        {
            WorkspaceProfile target = ResolveAutomaticScaleProfile(width, height, fullProfile);
            // Queue-open is durable full-workspace intent. Responsive shrinking may compact the
            // table and controls, but it may never turn that explicit work surface into Micro.
            if (queueOpen && target == WorkspaceProfile.Micro)
                return IsContextWorkspace(fullProfile) ? fullProfile : WorkspaceProfile.Player;
            return target;
        }

        private void ApplyAutomaticScaleTier()
        {
            // R61.106.37: resizing the normal player never changes workspace/profile.
            // Mini Player is explicit operator intent only (Ctrl+M / menu / button).
            return;
        }

        private void ApplyCompactLayoutForSize()
        {
            if (_mediaStageFullscreen)
            {
                // In-window media fullscreen owns the content rectangle. Title/menu remain under
                // their independent user toggles; the everyday status strip does not consume media.
                if (_statusBarSurface != null) _statusBarSurface.Visibility = Visibility.Collapsed;
                if (_statusBarRow != null) _statusBarRow.Height = new GridLength(0);
                return;
            }
            if (!_miniMode)
            {
                // Full-window YOMI always retains the conventional bottom status strip. It is
                // the durable hover-help surface and must not disappear merely because Queue closes.
                if (_statusBarSurface != null) _statusBarSurface.Visibility = Visibility.Visible;
                if (_statusBarRow != null) _statusBarRow.Height = new GridLength(23);
                if (_microTitleRow != null) _microTitleRow.Height = GridLength.Auto;
                if (_microTitleGapRow != null) _microTitleGapRow.Height = new GridLength(3);
                return;
            }

            // R61.77 compact appliances spend vertical space on playback before auxiliary chrome.
            // The classic menu remains governed solely by the user's menu preference.
            if (_statusBarSurface != null) _statusBarSurface.Visibility = Visibility.Collapsed;
            if (_statusBarRow != null) _statusBarRow.Height = new GridLength(0);

            if (_microTitleRow != null) _microTitleRow.Height = GridLength.Auto;
            if (_microTitleGapRow != null) _microTitleGapRow.Height = new GridLength(2);
        }

        private void WindowPreviewMouseMoveStatus(object sender, MouseEventArgs e)
        {
            if (_hoverStatusText == null) return;
            DependencyObject current = e.OriginalSource as DependencyObject;
            FrameworkElement candidate = null;
            while (current != null)
            {
                var fe = current as FrameworkElement;
                if (fe != null)
                {
                    object tip = ToolTipService.GetToolTip(fe);
                    string text = tip as string;
                    if (!String.IsNullOrWhiteSpace(text)) { candidate = fe; break; }
                    string automation = System.Windows.Automation.AutomationProperties.GetName(fe);
                    if (!String.IsNullOrWhiteSpace(automation) && (fe is Button || fe is ToggleButton || fe is Slider || fe is ComboBox || fe is TextBox)) { candidate = fe; break; }
                }
                try { current = VisualTreeHelper.GetParent(current); } catch { current = null; }
            }
            if (Object.ReferenceEquals(candidate, _lastHoverStatusSource)) return;
            _lastHoverStatusSource = candidate;
            if (candidate == null) { _hoverStatusText.Text = ""; return; }
            string status = ToolTipService.GetToolTip(candidate) as string;
            if (String.IsNullOrWhiteSpace(status)) status = System.Windows.Automation.AutomationProperties.GetName(candidate);
            _hoverStatusText.Text = String.IsNullOrWhiteSpace(status) ? "" : status.Replace("\r"," ").Replace("\n"," ");
        }

        private int ExpectedPlaylistEntryCount()
        {
            long now = _clock.ElapsedMilliseconds;
            if (_expectedPlaylistCount > 0 && now - _expectedPlaylistCountLastCheckMs < 400) return _expectedPlaylistCount;
            _expectedPlaylistCountLastCheckMs = now;
            try
            {
                string path = DirectPlaylistPath;
                if (!File.Exists(path)) return Math.Max(0, _expectedPlaylistCount);
                int count = CountPlaylistEntries(path);
                if (count > _expectedPlaylistCount) _expectedPlaylistCount = count;
            }
            catch { }
            return Math.Max(0, _expectedPlaylistCount);
        }

        private int ExpectedQueueEntryCount(Dictionary<string, object> session)
        {
            int expected = Math.Max(ExpectedPlaylistEntryCount(), Math.Max(0, GetInt(session, "count", 0)));
            expected = Math.Max(expected, _trackMeta.Count);
            expected = Math.Max(expected, _order.Count);
            SlotRecord activeSlot;
            if (!String.IsNullOrWhiteSpace(_activeSlotId) && _slotsById.TryGetValue(_activeSlotId, out activeSlot) && activeSlot != null)
                expected = Math.Max(expected, Math.Max(0, activeSlot.TrackCount));
            return Math.Max(0, expected);
        }

        private static void ClassifyQueueMetadataTitle(string title, int occurrence, ref int named, ref int unavailable)
        {
            if (occurrence <= 0 || IsPlaceholderTrackTitle(title, occurrence)) return;
            if (IsUnavailableTrackTitle(title)) unavailable++;
            else named++;
        }

        private void GetQueueMetadataProgress(out int named, out int unavailable, out int target)
        {
            named = 0;
            unavailable = 0;
            Dictionary<string, object> session = ReadJsonCached(Path.Combine(_stateRoot, "session.json"));
            target = ExpectedQueueEntryCount(session);
            if (target <= 0)
                target = Math.Max(_order.Count, Math.Max(_trackMeta.Count, _queueRows.Count));

            // Count the projected Queue rows whenever they exist. This is a set count, not a
            // position: 2240/2802 means 2240 rows are resolved somewhere in the Queue, not that
            // row 2241 is where loading stopped.
            if (_queueRows.Count > 0)
            {
                target = Math.Max(target, _queueRows.Count);
                foreach (QueueRow row in _queueRows)
                    if (row != null) ClassifyQueueMetadataTitle(row.Title, row.OccurrenceId, ref named, ref unavailable);
            }
            else if (_order.Count > 0)
            {
                foreach (int occurrence in _order)
                {
                    TrackMeta meta;
                    if (_trackMeta.TryGetValue(occurrence, out meta) && meta != null) ClassifyQueueMetadataTitle(meta.Title, occurrence, ref named, ref unavailable);
                }
            }
            else
            {
                foreach (var pair in _trackMeta)
                    if (pair.Value != null) ClassifyQueueMetadataTitle(pair.Value.Title, pair.Key, ref named, ref unavailable);
            }

            int resolved = named + unavailable;
            if (target < resolved) target = resolved;
        }

        private void GetQueueMetadataProgress(out int resolved, out int target)
        {
            int named, unavailable;
            GetQueueMetadataProgress(out named, out unavailable, out target);
            resolved = named + unavailable;
        }

        private bool QueueMetadataReady
        {
            get
            {
                int resolved, target;
                GetQueueMetadataProgress(out resolved, out target);
                return target > 0 && resolved >= target;
            }
        }

        private void RenderStatusLoadingBar(int resolved, int target, bool visible)
        {
            if (_statusLoadingCanvas == null || _hoverStatusText == null) return;
            _statusLoadingCanvas.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
            _hoverStatusText.Visibility = visible ? Visibility.Collapsed : Visibility.Visible;
            if (!visible)
            {
                if (_statusLoadingCanvas.Children.Count > 0) _statusLoadingCanvas.Children.Clear();
                return;
            }

            double width = Math.Max(0, _statusLoadingCanvas.ActualWidth);
            double height = Math.Max(0, _statusLoadingCanvas.ActualHeight);
            if (width < 20 || height < 4) return;

            const double gap = 2.0;
            int segments = Math.Max(8, Math.Min(64, (int)Math.Floor((width + gap) / 7.0)));
            double segmentWidth = Math.Max(3.0, Math.Floor((width - gap * (segments - 1)) / segments));
            double totalWidth = segmentWidth * segments + gap * (segments - 1);
            double startX = Math.Max(0, Math.Floor((width - totalWidth) / 2.0));
            double segmentHeight = Math.Max(5.0, Math.Min(10.0, Math.Floor(height - 4.0)));
            double startY = Math.Max(0, Math.Floor((height - segmentHeight) / 2.0));
            int filled = target > 0 ? (int)Math.Floor((Math.Max(0, Math.Min(resolved, target)) / (double)target) * segments) : 0;
            if (resolved > 0 && filled == 0) filled = 1;
            if (resolved >= target && target > 0) filled = segments;

            _statusLoadingCanvas.Children.Clear();
            for (int i = 0; i < segments; i++)
            {
                var segment = new Border
                {
                    Width = segmentWidth,
                    Height = segmentHeight,
                    Background = Brush(i < filled ? "Accent" : "SurfaceRaised"),
                    BorderBrush = Brush("BorderStrong"),
                    BorderThickness = new Thickness(1),
                    SnapsToDevicePixels = true,
                    IsHitTestVisible = false
                };
                Canvas.SetLeft(segment, startX + i * (segmentWidth + gap));
                Canvas.SetTop(segment, startY);
                _statusLoadingCanvas.Children.Add(segment);
            }
        }

        private void UpdateStatusBarProjection()
        {
            if (_statusPlaybackText != null)
            {
                int metadataNamed, metadataUnavailable, metadataTarget;
                GetQueueMetadataProgress(out metadataNamed, out metadataUnavailable, out metadataTarget);
                int metadataResolved = metadataNamed + metadataUnavailable;
                int metadataPending = Math.Max(0, metadataTarget - metadataResolved);
                bool metadataLoading = metadataTarget > 0 && metadataPending > 0;

                bool queueMaterializing = _queueOpen && _queueUiMaterializationActive;
                Dictionary<string, object> queueStatusSession = ReadJsonCached(Path.Combine(_stateRoot, "session.json"));
                int expectedQueueCount = ExpectedQueueEntryCount(queueStatusSession);
                bool queueModelIncomplete = expectedQueueCount > 0 && _order.Count < expectedQueueCount;
                bool queueRowsIncomplete = _queueOpen && expectedQueueCount > 0 && _queueRows.Count < expectedQueueCount;
                bool queueProjectionIncomplete = _queueOpen && (!QueueUiRowsReady || queueRowsIncomplete);
                bool queueStartupHydrating = _queueOpen && (_engineLaunchMonitorActive || queueModelIncomplete || queueProjectionIncomplete);
                bool queueLoading = _queueOpen && (queueMaterializing || queueStartupHydrating || queueRowsIncomplete);
                bool transportLoading = _startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm);

                if (metadataLoading) RenderStatusLoadingBar(metadataResolved, metadataTarget, true);
                else if (queueLoading)
                {
                    int progressTarget = Math.Max(expectedQueueCount, Math.Max(_order.Count, _queueRows.Count + Math.Max(0, _queueUiMaterializationRemaining)));
                    int progressLoaded = Math.Min(progressTarget, Math.Max(0, _queueRows.Count));
                    RenderStatusLoadingBar(progressLoaded, progressTarget, progressTarget > 0 && progressLoaded < progressTarget);
                }
                else RenderStatusLoadingBar(0, 0, false);

                if (metadataLoading)
                {
                    string prefix = _startupPrewarmReady ? "Player ready · " : "";
                    _statusPlaybackText.Text = metadataTarget > 1
                        ? prefix + "Loading track info · " + metadataNamed.ToString(CultureInfo.InvariantCulture) + " named · " +
                          metadataUnavailable.ToString(CultureInfo.InvariantCulture) + " unavailable · " +
                          metadataPending.ToString(CultureInfo.InvariantCulture) + " pending"
                        : prefix + "Loading track info...";
                }
                else if (queueLoading)
                {
                    int target = Math.Max(expectedQueueCount, Math.Max(_order.Count, _queueRows.Count + Math.Max(0, _queueUiMaterializationRemaining)));
                    int loaded = Math.Min(target, Math.Max(0, _queueRows.Count));
                    _statusPlaybackText.Text = target > 1
                        ? "Loading Queue " + loaded.ToString(CultureInfo.InvariantCulture) + "/" + target.ToString(CultureInfo.InvariantCulture)
                        : "Loading Queue...";
                }
                else if (transportLoading)
                {
                    _statusPlaybackText.Text = "Starting player...";
                }
                else
                {
                    string phase = _startupPrewarmReady ? "Ready" : (String.IsNullOrWhiteSpace(_lastPlaybackPhase) ? (_running ? "Ready" : "Stopped") : _lastPlaybackPhase);
                    _statusPlaybackText.Text = phase;
                }
            }
            if (_statusObsText != null)
            {
                bool integration = ObsIntegrationEnabled();
                bool prep = ObsMediaCacheEnabled();
                bool packageOn = integration && prep;
                bool connected = integration && _lastObsProbeResult != null && _lastObsProbeResult.BrowserClientCount > 0;
                if (packageOn) _statusObsText.Text = connected ? "OBS: On · Connected" : "OBS: On · Idle";
                else _statusObsText.Text = "OBS: Off";
                _statusObsText.ToolTip = packageOn
                    ? "OBS integration and background media preparation are on. Click to turn both off."
                    : "OBS integration and background media preparation are off. Click to turn both on.";
                _statusObsText.Foreground = Brush(connected ? "Info" : ((integration || prep) ? "TextSecondary" : "TextMuted"));
            }
        }

        private IntPtr WindowMessageHook(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            const int WM_NCHITTEST = 0x0084;
            const int WM_SIZING = 0x0214;
            const int WM_ENTERSIZEMOVE = 0x0231;
            const int WM_EXITSIZEMOVE = 0x0232;
            const int HTLEFT = 10;
            const int HTRIGHT = 11;
            const int HTTOP = 12;
            const int HTTOPLEFT = 13;
            const int HTTOPRIGHT = 14;
            const int HTBOTTOM = 15;
            const int HTBOTTOMLEFT = 16;
            const int HTBOTTOMRIGHT = 17;

            // Settings uses the same movable/resizable shell as the main controller. While the
            // Settings workspace is visible, make every physical edge an explicit resize target
            // instead of relying on the overlay to leave WindowChrome hit testing exposed.
            if (msg == WM_NCHITTEST && _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible &&
                _window != null && _window.WindowState == WindowState.Normal && _window.ResizeMode == ResizeMode.CanResize)
            {
                RECT settingsRect;
                if (GetWindowRect(hwnd, out settingsRect))
                {
                    long packed = lParam.ToInt64();
                    int screenX = unchecked((short)(packed & 0xFFFF));
                    int screenY = unchecked((short)((packed >> 16) & 0xFFFF));
                    double scale = 1.0;
                    try
                    {
                        PresentationSource ps = PresentationSource.FromVisual(_window);
                        if (ps != null && ps.CompositionTarget != null) scale = Math.Max(0.5, ps.CompositionTarget.TransformToDevice.M11);
                    }
                    catch { }
                    int edge = Math.Max(5, (int)Math.Ceiling(6.0 * scale));
                    bool left = screenX <= settingsRect.Left + edge, right = screenX >= settingsRect.Right - edge;
                    bool top = screenY <= settingsRect.Top + edge, bottom = screenY >= settingsRect.Bottom - edge;
                    if (top && left) { handled = true; return new IntPtr(HTTOPLEFT); }
                    if (top && right) { handled = true; return new IntPtr(HTTOPRIGHT); }
                    if (bottom && left) { handled = true; return new IntPtr(HTBOTTOMLEFT); }
                    if (bottom && right) { handled = true; return new IntPtr(HTBOTTOMRIGHT); }
                    if (left) { handled = true; return new IntPtr(HTLEFT); }
                    if (right) { handled = true; return new IntPtr(HTRIGHT); }
                    if (top) { handled = true; return new IntPtr(HTTOP); }
                    if (bottom) { handled = true; return new IntPtr(HTBOTTOM); }
                }
            }

            // R61.96: straight resize edges stay intentionally narrow so the Queue scrollbar
            // remains easy to grab. Bottom corners retain an 18-DIP target because corner
            // resizing is the high-value two-dimensional gesture. WindowChrome handles the
            // ordinary 4-DIP edges; this hook only enlarges the two bottom corners.
            if (msg == WM_NCHITTEST && _window != null && _window.WindowState == WindowState.Normal && _window.ResizeMode == ResizeMode.CanResize)
            {
                RECT rect;
                if (GetWindowRect(hwnd, out rect))
                {
                    long packed = lParam.ToInt64();
                    int screenX = unchecked((short)(packed & 0xFFFF));
                    int screenY = unchecked((short)((packed >> 16) & 0xFFFF));
                    double scale = 1.0;
                    try
                    {
                        PresentationSource ps = PresentationSource.FromVisual(_window);
                        if (ps != null && ps.CompositionTarget != null) scale = Math.Max(0.5, ps.CompositionTarget.TransformToDevice.M11);
                    }
                    catch { }
                    int corner = Math.Max(12, (int)Math.Ceiling(18.0 * scale));
                    if (screenY >= rect.Bottom - corner)
                    {
                        if (screenX <= rect.Left + corner) { handled = true; return new IntPtr(HTBOTTOMLEFT); }
                        if (screenX >= rect.Right - corner) { handled = true; return new IntPtr(HTBOTTOMRIGHT); }
                    }
                }
            }

            if (msg == WM_SIZING && _liveResize)
            {
                if (ApplyMediaStageAspectResize(wParam, lParam))
                {
                    handled = true;
                    return new IntPtr(1);
                }
            }

            if (msg == WM_ENTERSIZEMOVE && !_liveResize)
            {
                _liveResize = true;
                // R61.106.27: Fit-to-controller is a live controller-height constraint. Manual
                // resizing may change width, but while Fit is enabled the final height remains
                // exactly the controller instead of silently turning the preference off.
                // R61.36: previews are ordinary WPF Images now. Interactive resize no
                // longer hides them; this hook only marks resize state and lets the normal
                // frame surface continue without resurrecting the retired MediaElements.
                SyncHostedMediaAirspace();
            }
            else if (msg == WM_EXITSIZEMOVE && _liveResize)
            {
                _liveResize = false;
                SyncHostedMediaAirspace();
                // Commit the complete topology exactly once after Windows finishes the drag.
                // This is deliberately non-recursive and keeps the final rectangle authoritative.
                try
                {
                    ApplyAutomaticScaleTier();
                    ApplyCompactLayoutForSize();
                    ApplyAdaptiveLayout(true);
                    ApplyQueueCanvasLayout(false);
                    ApplyQueueTableColumnFit();
                    UpdateProgressVisual();
                    if (!_queueOpen && !MediaStageVisible() && !_miniMode)
                    {
                        _window.UpdateLayout();
                        SnapWindowToControllerHeight();
                    }
                    CaptureNormalWindowGeometry();
                    SaveUiState();
                }
                catch (Exception ex)
                {
                    WriteRuntimeCrashDiagnostic("resize-finalize", ex);
                }
                // Moving/resizing changes geometry only; refresh presentation without
                // counterfeiting a track transition or tearing down healthy previews.
                ScheduleFastPlaybackRefresh();
            }
            return IntPtr.Zero;
        }

        private void WindowPreviewKeyDown(object sender, KeyEventArgs e)
        {
            bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            bool shift = (e.KeyboardDevice.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
            bool alt = (e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt;

            // R61.36: the in-app playlist editor owns ordinary editing shortcuts while open.
            // The Window sees preview-key events before the TextBox does, so stop player/global
            // shortcuts here and let Ctrl+A/C/V/X/Z work as normal text editing below.
            if (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible)
            {
                if (ctrl && !shift && !alt && e.Key == Key.S) { SavePlaylistEditor(); e.Handled = true; }
                else if (!ctrl && !shift && !alt && e.Key == Key.Escape) { ClosePlaylistEditor(); e.Handled = true; }
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.OemComma)
            {
                OpenIntegratedSettings();
                e.Handled = true;
                return;
            }

            if (!ctrl && !shift && !alt && e.Key == Key.F10)
            {
                SetMenuBarVisible(true, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && alt && e.Key == Key.R)
            {
                CycleRepeatMode();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _settingsOverlay.Visibility == Visibility.Visible)
            {
                CloseIntegratedSettings();
                e.Handled = true;
                return;
            }
            // While Settings owns focus, normal media-player hotkeys must not
            // steal Space/arrows/letters from checkboxes and combo boxes.
            if (_settingsOverlay.Visibility == Visibility.Visible)
                return;

            // R61.67: once the command palette is visible it owns the keyboard surface.
            // Do this before other global command chords so list navigation cannot tunnel through
            // into player/workspace actions.
            if (_commandPaletteOverlay.Visibility == Visibility.Visible)
            {
                if (e.Key == Key.Escape)
                {
                    CloseCommandPalette();
                    e.Handled = true;
                }
                else if (ctrl && !shift && !alt && e.Key == Key.F)
                {
                    _commandPaletteSearch.Focus();
                    _commandPaletteSearch.SelectAll();
                    e.Handled = true;
                }
                return;
            }

            if (e.Key == Key.Escape && _slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible)
            {
                if (!_slotSwitchActive) CloseListeningSlots();
                e.Handled = true;
                return;
            }
            if (_slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible)
                return;

            Key chordKey = e.Key == Key.System ? e.SystemKey : e.Key;
            if (ctrl && !shift && alt && TrySwitchListeningSlotShortcut(chordKey))
            {
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible)
            {
                if (!_poolBuildActive) ClosePlaylistPool();
                e.Handled = true;
                return;
            }
            if (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible)
                return;

            if (ctrl && shift && !alt && e.Key == Key.L)
            {
                OpenIntentFabric();
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.X)
            {
                RequestCancelActiveIntent("keyboard abort");
                e.Handled = true;
                return;
            }

            if (!ctrl && !shift && !alt && e.Key == Key.F1)
            {
                OpenShortcutPalette();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _intentFabricOverlay.Visibility == Visibility.Visible)
            {
                CloseIntentFabric();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _operatorDeckOverlay.Visibility == Visibility.Visible)
            {
                CloseOperatorDeck();
                e.Handled = true;
                return;
            }

            if (_operatorDeckOverlay.Visibility == Visibility.Visible && !ctrl && !shift && (int)e.Key >= (int)Key.D1 && (int)e.Key <= (int)Key.D6)
            {
                ExecuteOperatorDeckNumber(((int)e.Key - (int)Key.D1) + 1);
                e.Handled = true;
                return;
            }

            if (!ctrl && !shift && !alt && e.Key == Key.Oem2 && _queueOpen)
            {
                _queueSearchBox.Focus();
                _queueSearchBox.SelectAll();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _queueOpen && _commandPaletteOverlay.Visibility != Visibility.Visible)
            {
                if (_queueSearchBox.IsKeyboardFocusWithin && !String.IsNullOrWhiteSpace(_queueSearchBox.Text))
                {
                    _queueSearchBox.Clear();
                    e.Handled = true;
                    return;
                }
                SetQueueOpen(false, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.F)
            {
                if (!_queueOpen)
                    SetQueueOpen(true, true);
                _queueSearchBox.Focus();
                _queueSearchBox.SelectAll();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.G)
            {
                BeginQueueSlotNavigation();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Q)
            {
                SetQueueOpen(!_queueOpen, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.I)
            {
                SetInspectorOpen(!_inspectorOpen, true);
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.R)
            {
                SetInspectorOpen(true, true);
                RefreshInspector();
                ShowToast("Media path", "Media-path details are available in Operations Center.");
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.M)
            {
                SetMicroMode(!_microMode, true);
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.V)
            {
                SetVisualizerEnabled(!_visualizerEnabled, true);
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.D1) { ToggleMediaModule(true); e.Handled = true; return; }
            if (ctrl && !shift && !alt && e.Key == Key.D2) { ToggleMediaModule(false); e.Handled = true; return; }

            if (ctrl && !shift && !alt && e.Key == Key.D)
            {
                ToggleFavoriteSelectedOrCurrent();
                e.Handled = true;
                return;
            }

            if (ctrl && shift && !alt && e.Key == Key.M)
            {
                ToggleMute();
                e.Handled = true;
                return;
            }

            if (ctrl && !shift && !alt && e.Key == Key.Up)
            {
                AdjustVolume(1.0);
                e.Handled = true;
                return;
            }
            if (ctrl && !shift && !alt && e.Key == Key.Down)
            {
                AdjustVolume(-1.0);
                e.Handled = true;
                return;
            }

            // R61.36: selectable/read-only text is still text. Once a user clicks title,
            // channel or Inspector detail to select/copy it, do not reinterpret typing,
            // Space or cursor keys as player transport until focus leaves that TextBox.
            bool nativeTextFocus = Keyboard.FocusedElement is TextBox;
            bool editing = _queueSearchBox.IsKeyboardFocusWithin || _commandPaletteSearch.IsKeyboardFocusWithin || nativeTextFocus;
            if (!editing && e.Key == Key.Space)
            {
                TogglePlayPause();
                e.Handled = true;
                return;
            }

            if (!editing && (e.Key == Key.Left || e.Key == Key.Right) && _running)
            {
                double step = shift ? 15.0 : 5.0;
                SeekRelative(e.Key == Key.Left ? -step : step);
                e.Handled = true;
                return;
            }

            if (!editing && e.Key == Key.MediaNextTrack)
            {
                if (_running) NavigateRelative(1);
                e.Handled = true;
                return;
            }
            if (!editing && e.Key == Key.MediaPreviousTrack)
            {
                if (_running) NavigateRelative(-1);
                e.Handled = true;
            }
        }

        private void NavigateRelative(int delta)
        {
            if (!_running || delta == 0)
                return;

            // R57 TRANSPORT FIDELITY: relative transport is resolved by the playback
            // authority, not by the controller's periodically refreshed occurrence.
            // Commands are serialized off the UI thread so repeated input stays crisp
            // even if the local IPC endpoint briefly takes time to acknowledge.
            string message = delta > 0 ? "yomi-next" : "yomi-prev";
            // R61.106.52.5.1: Queue scope/search is presentation state, not transport authority.
            // Next/Previous remains global unless the operator explicitly pressed Listen, which
            // creates _queuePlaybackSubsetActive. A hidden History view must never turn Mini
            // transport into a tiny history-only playlist.
            object[] transportCommand = _queuePlaybackSubsetActive && !String.IsNullOrWhiteSpace(_queuePlaybackSubsetCsv)
                ? new object[] { "script-message", "yomi-playback-subset-step", _queuePlaybackSubsetCsv, _queuePlaybackSubsetQuery ?? "", delta > 0 ? "1" : "-1" }
                : new object[] { "script-message", message };
            // R61.91: snapshot transport handoff evidence before asynchronous dispatch.
            // The engine can publish the destination before the callback runs; capturing here
            // guarantees the accepted command remembers the occurrence that was actually outgoing.
            int transportOutgoingMediaOccurrence = _lastMediaOccurrence > 0 ? _lastMediaOccurrence : _currentOccurrence;
            DispatchTransportCommand(transportCommand, delegate(bool accepted)
            {
                if (accepted)
                {
                    BeginPlaybackTransitionProjection();
                    _lastStateRefreshMs = 0;
                    _lastQueueRefreshMs = 0;
                    _pendingTransportOutgoingMediaOccurrence = transportOutgoingMediaOccurrence;
                    _lastVisualizerDemandSent = null;
                    _lastMediaDemandSent = "";
                    AddActivity("Playback", delta > 0 ? "next requested" : "previous requested");
                    ScheduleFastPlaybackRefresh();
                }
                else
                {
                    ShowToast("Playback", "Engine transport command failed.");
                }
            });
        }

        private void WireTransport()
        {
            _previousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            _nextButton.Click += delegate { if (_running) NavigateRelative(1); };
            _playPauseButton.Click += delegate { TogglePlayPause(); };
            _miniPreviousButton2.Click += delegate { if (_running) NavigateRelative(-1); };
            _miniPlayPauseButton2.Click += delegate { TogglePlayPause(); };
            _miniNextButton2.Click += delegate { if (_running) NavigateRelative(1); };
            _microPreviousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            _microNextButton.Click += delegate { if (_running) NavigateRelative(1); };
            _microPlayPauseButton.Click += delegate { TogglePlayPause(); };
            _repeatStatePill.Click += delegate { CycleRepeatMode(); };
            if (_miniRepeatButton2 != null) _miniRepeatButton2.Click += delegate { CycleRepeatMode(); };
            if (_microRepeatButton != null) _microRepeatButton.Click += delegate { CycleRepeatMode(); };
            if (_queueDockPreviousButton != null) _queueDockPreviousButton.Click += delegate { if (_running) NavigateRelative(-1); };
            if (_queueDockPlayPauseButton != null) _queueDockPlayPauseButton.Click += delegate { TogglePlayPause(); };
            if (_queueDockNextButton != null) _queueDockNextButton.Click += delegate { if (_running) NavigateRelative(1); };
            if (_queueDockRepeatButton != null) _queueDockRepeatButton.Click += delegate { CycleRepeatMode(); };
            if (_queueDockPositionButton != null) { _queueDockPositionButton.Visibility = Visibility.Collapsed; _queueDockPositionButton.IsHitTestVisible = false; }
            // R61.106.27: Queue is not a vertically draggable pane. The compatibility
            // GridSplitter remains collapsed in XAML so no resize gesture can mutate player height.
            if (_queueDockPlayerButton != null) _queueDockPlayerButton.Click += delegate
            {
                SetQueueOpen(false, true);
                if (_window.WindowState == WindowState.Maximized) _window.WindowState = WindowState.Normal;
                _window.Activate();
            };
            if (_queueDockHideButton != null) _queueDockHideButton.Click += delegate { SetQueueOpen(false, true); };
            if (_queueDockElapsedText != null) _queueDockElapsedText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            if (_queueDockRemainingText != null) _queueDockRemainingText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };

            _previousUpStrip.MouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e) { if (_running) NavigateRelative(-1); e.Handled = true; };
            _previousAgainButton.Click += delegate(object sender, RoutedEventArgs e) { QueuePreviousAgain(); e.Handled = true; };
            _previousLocateButton.Click += delegate(object sender, RoutedEventArgs e) { LocatePreviousInQueue(); e.Handled = true; };
            _nextLaterButton.Click += delegate(object sender, RoutedEventArgs e) { DeferNextOccurrence(5); e.Handled = true; };
            _nextLocateButton.Click += delegate(object sender, RoutedEventArgs e) { LocateNextInQueue(); e.Handled = true; };
            _favoriteButton.Click += delegate { ToggleFavoriteCurrent(); };
            _copyTrackButton.Click += delegate { CopyNowPlaying(); };
            if (_openSourceButton != null)
            {
                _openSourceButton.Visibility = Visibility.Collapsed;
                _openSourceButton.IsEnabled = false;
            }
            _queueTrackButton.Click += delegate { SetQueueOpen(true, true); JumpQueueToCurrent(); };
            _inspectTrackButton.Click += delegate { ToggleInspectorFromSurface(); };
            _mediaStateInspectButton.Click += delegate { ToggleInspectorFromSurface(); };
            _elapsedText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            _remainingText.MouseLeftButtonUp += delegate { ToggleTimeDisplayMode(); };
            // R50: right-click exposes the actions already present in the hover strip; no second action authority.
            var nowPlayingMenu = new ContextMenu();
            var nowPlayingQueueItem = new MenuItem { Header = "Show Queue", IsCheckable = true, IsChecked = _queueOpen, Tag = "show-queue" };
            nowPlayingQueueItem.Click += delegate { SetQueueOpen(nowPlayingQueueItem.IsChecked, true); nowPlayingQueueItem.IsChecked = _queueOpen; };
            nowPlayingMenu.Items.Add(nowPlayingQueueItem);
            nowPlayingMenu.Items.Add(new Separator());
            var nowFavoriteItem = AddMenuItem(nowPlayingMenu, "Favorite / unfavorite", delegate { ToggleFavoriteCurrent(); });
            AddMenuItem(nowPlayingMenu, "Copy now playing", delegate { CopyNowPlaying(); });
