            _volumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                e.Handled = true;
            };
            _miniVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                e.Handled = true;
            };
            _microVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                e.Handled = true;
            };
            if (_queueDockVolumeButton != null) _queueDockVolumeButton.MouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                e.Handled = true;
            };
            _mainVolumeSlider.ValueChanged += delegate(object sender, RoutedPropertyChangedEventArgs<double> e)
            {
                if (_syncingVolume || !_running)
                    return;
                SetVolume(e.NewValue, false);
            };
            _mainVolumeSlider.PreviewMouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                BeginVolumeUserDrag();
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                EndVolumeUserDrag();
                e.Handled = true;
            };
            _volumeSlider.ValueChanged += delegate(object sender, RoutedPropertyChangedEventArgs<double> e)
            {
                if (_syncingVolume || !_running)
                    return;
                SetVolume(e.NewValue, false);
            };
            _volumeSlider.PreviewMouseWheel += delegate(object sender, MouseWheelEventArgs e)
            {
                BeginVolumeUserDrag();
                AdjustVolume(e.Delta >= 0 ? 1.0 : -1.0);
                EndVolumeUserDrag();
                e.Handled = true;
            };
            WireImmediateSliderDrag(_mainVolumeSlider);
            WireImmediateSliderDrag(_volumeSlider);
            WireImmediateSliderDrag(_window.FindName("MiniVolumeSliderInline") as Slider);
            WireImmediateSliderDrag(_window.FindName("MicroVolumeSliderInline") as Slider);
            _volumeMuteToggle.Click += delegate { SetMute(_volumeMuteToggle.IsChecked == true); };
        }

        private bool VolumeUserOwnsAuthority(long now)
        {
            return _volumeUserDragActive || now < _volumeUserAuthorityUntilMs;
        }

        private void BeginVolumeUserDrag()
        {
            _volumeUserDragActive = true;
            _volumeUserAuthorityUntilMs = Int64.MaxValue;
            lock (_volumeSnapshotSync)
            {
                // Any mpv read already in flight describes an older pointer position. It must
                // never be allowed to pull the thumb backwards while the operator owns it.
                _volumeSnapshotGeneration++;
                _volumeSnapshotValid = false;
                _volumeSnapshotStampMs = -10000;
            }
        }

        private void EndVolumeUserDrag()
        {
            _volumeUserDragActive = false;
            _volumeUserAuthorityUntilMs = _clock.ElapsedMilliseconds + 900;
            lock (_volumeSnapshotSync)
            {
                _volumeSnapshotGeneration++;
                _volumeSnapshotValid = false;
                _volumeSnapshotStampMs = -10000;
            }
        }

        private void WireImmediateSliderDrag(Slider slider)
        {
            if (slider == null) return;
            bool dragging = false;
            slider.PreviewMouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                dragging = true;
                BeginVolumeUserDrag();
                slider.CaptureMouse();
                SetSliderValueFromPointer(slider, e.GetPosition(slider));
                e.Handled = true;
            };
            slider.PreviewMouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (!dragging || e.LeftButton != MouseButtonState.Pressed) return;
                SetSliderValueFromPointer(slider, e.GetPosition(slider));
                e.Handled = true;
            };
            slider.PreviewMouseLeftButtonUp += delegate(object sender, MouseButtonEventArgs e)
            {
                if (!dragging) return;
                SetSliderValueFromPointer(slider, e.GetPosition(slider));
                dragging = false;
                if (slider.IsMouseCaptured) slider.ReleaseMouseCapture();
                EndVolumeUserDrag();
                e.Handled = true;
            };
            slider.LostMouseCapture += delegate
            {
                if (!dragging) return;
                dragging = false;
                EndVolumeUserDrag();
            };
        }

        private static void SetSliderValueFromPointer(Slider slider, Point sliderPoint)
        {
            if (slider == null || slider.ActualWidth <= 1.0) return;
            double x = Math.Max(0.0, Math.Min(slider.ActualWidth, sliderPoint.X));
            double fraction = x / slider.ActualWidth;
            if (slider.FlowDirection == FlowDirection.RightToLeft) fraction = 1.0 - fraction;
            double value = slider.Minimum + fraction * (slider.Maximum - slider.Minimum);
            slider.Value = Math.Round(value, 0, MidpointRounding.AwayFromZero);
        }

        private void ToggleVolumePopup(Button target)
        {
            RefreshVolumeState(true);
            if (_volumePopup != null && target != null) _volumePopup.PlacementTarget = target;
            _volumePopup.IsOpen = !_volumePopup.IsOpen;
        }

        private void QueueMpvVolumeSnapshotRefresh()
        {
            long now = _clock.ElapsedMilliseconds;
            if (_disposed || !_running || _shutdownRequested || _slotSwitchActive || VolumeUserOwnsAuthority(now)) return;
            int generation;
            lock (_volumeSnapshotSync)
            {
                if (_volumeSnapshotWorkerActive) return;
                _volumeSnapshotWorkerActive = true;
                generation = _volumeSnapshotGeneration;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                double volume = _volume; bool muted = _muted; bool okVolume = false, okMute = false;
                try
                {
                    object raw;
                    if (GetMpvProperty("volume", out raw)) { volume = Math.Max(0, Math.Min(100, ToDouble(raw, volume))); okVolume = true; }
                    if (GetMpvProperty("mute", out raw)) { muted = raw is bool ? (bool)raw : String.Equals(Convert.ToString(raw, CultureInfo.InvariantCulture), "true", StringComparison.OrdinalIgnoreCase); okMute = true; }
                }
                catch { }
                lock (_volumeSnapshotSync)
                {
                    if ((okVolume || okMute) && generation == _volumeSnapshotGeneration && !_shutdownRequested && !_slotSwitchActive)
                    {
                        if (okVolume) _volumeSnapshotVolume = volume;
                        if (okMute) _volumeSnapshotMuted = muted;
                        _volumeSnapshotValid = true;
                        _volumeSnapshotStampMs = _clock.ElapsedMilliseconds;
                    }
                    _volumeSnapshotWorkerActive = false;
                }
            });
        }

        private void RefreshVolumeState(bool force)
        {
            if (_volumeButton == null) return;
            long now = _clock.ElapsedMilliseconds;
            if (!force && now - _lastVolumeRefreshMs < 1200) return;
            _lastVolumeRefreshMs = now;

            if (!_running)
            {
                _volumeAppliedToRuntime = false;
                _volumeButton.IsEnabled = false;
                if (_mainVolumeSlider != null) _mainVolumeSlider.IsEnabled = false;
                if (_queueDockVolumeButton != null) _queueDockVolumeButton.IsEnabled = false;
                lock (_volumeSnapshotSync) _volumeSnapshotValid = false;
                if (_volumePreferenceLoaded) ApplyVolumeUi();
                else { _volumeButton.Content = "Vol"; if (_queueDockVolumeButton != null) _queueDockVolumeButton.Content = "Vol"; _volumeValueText.Text = ""; }
                return;
            }

            _volumeButton.IsEnabled = true;
            if (_mainVolumeSlider != null) _mainVolumeSlider.IsEnabled = true;
            if (VolumeUserOwnsAuthority(now))
            {
                // During direct manipulation the local pointer value is authoritative. mpv is
                // receiving those writes asynchronously; reading it back here can only be stale.
                ApplyVolumeUi();
                return;
            }
            if (_queueDockVolumeButton != null) _queueDockVolumeButton.IsEnabled = true;
            if (_volumePreferenceLoaded && !_volumeAppliedToRuntime)
            {
                // Fire-and-forget property writes are bounded and do not wait for a response.
                bool volumeApplied = SendMpv("set_property", "volume", Math.Round(_volume, 1));
                bool muteApplied = SendMpv("set_property", "mute", _muted);
                if (volumeApplied && muteApplied) _volumeAppliedToRuntime = true;
                ApplyVolumeUi();
                QueueMpvVolumeSnapshotRefresh();
                return;
            }

            QueueMpvVolumeSnapshotRefresh();
            lock (_volumeSnapshotSync)
            {
                if (_volumeSnapshotValid && now - _volumeSnapshotStampMs <= 5000)
                {
                    _volume = _volumeSnapshotVolume;
                    _muted = _volumeSnapshotMuted;
                }
            }
            ApplyVolumeUi();
        }

        private void ApplyVolumeUi()
        {
            _syncingVolume = true;
            try
            {
                if (_mainVolumeSlider != null) _mainVolumeSlider.Value = Math.Max(0, Math.Min(100, _volume));
                if (_volumeSlider != null) _volumeSlider.Value = Math.Max(0, Math.Min(100, _volume));
                if (_volumeMuteToggle != null) _volumeMuteToggle.IsChecked = _muted;
                string value = Math.Round(_volume).ToString("0", CultureInfo.InvariantCulture);
                if (_mainVolumeValueText != null) _mainVolumeValueText.Text = _muted ? "Mute" : value + "%";
                if (_volumeValueText != null) _volumeValueText.Text = _muted ? "Muted " + value + "%" : value + "%";
                if (_volumeButton != null) _volumeButton.Content = _muted ? "Muted" : "Vol " + value;
                if (_statusVolumeText != null) _statusVolumeText.Text = _muted ? "Mute " + value + "%" : "Vol " + value + "%";
                if (_queueDockVolumeButton != null) { _queueDockVolumeButton.Content = _muted ? "Muted" : "Vol " + value; _queueDockVolumeButton.IsEnabled = _running; }
            }
            finally { _syncingVolume = false; }
        }

        private void AdjustVolume(double delta)
        {
            if (!_running) return;
            RefreshVolumeState(true);
            SetVolume(Math.Max(0, Math.Min(100, _volume + delta)), true);
        }

        private void SetVolume(double value, bool toast)
        {
            if (!_running) return;
            value = Math.Max(0, Math.Min(100, value));
            if (SendMpv("set_property", "volume", Math.Round(value, 1)))
            {
                _volume = value;
                if (!_volumeUserDragActive) _volumeUserAuthorityUntilMs = Math.Max(_volumeUserAuthorityUntilMs, _clock.ElapsedMilliseconds + 650);
                _volumePreferenceLoaded = true;
                _volumeAppliedToRuntime = true;
                if (_muted && value > 0) SetMute(false, false);
                ApplyVolumeUi();
                SaveUiState();
                if (toast) ShowToast("Volume", Math.Round(_volume).ToString("0", CultureInfo.InvariantCulture) + "%");
            }
        }

        private void ToggleMute()
        {
            if (!_running) return;
            RefreshVolumeState(true);
            SetMute(!_muted);
        }

        private void SetMute(bool muted)
        {
            SetMute(muted, true);
        }

        private void SetMute(bool muted, bool toast)
        {
            if (!_running) return;
            if (SendMpv("set_property", "mute", muted))
            {
                _muted = muted;
                _volumePreferenceLoaded = true;
                _volumeAppliedToRuntime = true;
                ApplyVolumeUi();
                SaveUiState();
                if (toast) ShowToast("Audio", muted ? "Muted" : "Unmuted");
            }
        }

