        private string ActiveSlotDescriptorPath { get { return Path.Combine(_dataRoot, "active-slot.json"); } }
        private string SlotSwitchJournalPath { get { return Path.Combine(_stateRoot, "listening-slot-switch.pending.json"); } }

        private string SlotRootPath(string id)
        {
            return Path.Combine(_slotsRoot, NormalizeSlotId(id));
        }

        private string SlotManifestPath(string id)
        {
            return Path.Combine(SlotRootPath(id), "slot.json");
        }

        private static string NormalizeSlotId(string value)
        {
            string raw = (value ?? "").Trim();
            if (raw.Length == 0) return "";
            var sb = new StringBuilder();
            foreach (char c in raw)
            {
                if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '-' || c == '_') sb.Append(c);
            }
            string clean = sb.ToString();
            return clean.Length > 80 ? clean.Substring(0, 80) : clean;
        }

        private static string NormalizeSlotName(string value)
        {
            string name = (value ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
            while (name.Contains("  ")) name = name.Replace("  ", " ");
            if (name.Length > 80) name = name.Substring(0, 80).Trim();
            return name;
        }

        private static string NormalizeSlotBroadcastPreset(string value)
        {
            string preset = (value ?? "").Trim();
            foreach (string allowed in new[] { "Keep current", "Classic strip", "Split sources", "Text + artwork", "Visual focus" })
                if (String.Equals(preset, allowed, StringComparison.OrdinalIgnoreCase)) return allowed;
            return "Keep current";
        }

        private string UniqueSlotName(string preferred)
        {
            string basis = NormalizeSlotName(preferred);
            if (basis.Length == 0) basis = "New session";
            string candidate = basis;
            int suffix = 2;
            while (_slotItems.Any(x => String.Equals(x.Name, candidate, StringComparison.OrdinalIgnoreCase)))
            {
                candidate = basis + " " + suffix.ToString(CultureInfo.InvariantCulture);
                suffix++;
            }
            return candidate;
        }

        private static string NewSlotId()
        {
            return "slot-" + Guid.NewGuid().ToString("N").Substring(0, 12);
        }

        private SlotRecord ReadSlotRecord(string id)
        {
            string clean = NormalizeSlotId(id);
            if (clean.Length == 0) return null;
            string path = SlotManifestPath(clean);
            if (!File.Exists(path)) return null;
            try
            {
                Dictionary<string, object> map = ReadJsonFresh(path);
                if (map.Count == 0) return null;
                string storedId = NormalizeSlotId(GetString(map, "id", clean));
                if (!String.Equals(storedId, clean, StringComparison.OrdinalIgnoreCase)) return null;
                return new SlotRecord
                {
                    Id = clean,
                    Name = NormalizeSlotName(GetString(map, "name", clean)),
                    SourceKind = GetString(map, "source_kind", "Playlist"),
                    PoolName = GetString(map, "pool_name", ""),
                    TrackCount = Math.Max(0, GetInt(map, "track_count", 0)),
                    BookmarkOccurrence = Math.Max(0, GetInt(map, "bookmark_occurrence", 0)),
                    BookmarkSeconds = Math.Max(0, GetDouble(map, "bookmark_seconds", 0)),
                    Paused = GetBool(map, "paused", false),
                    BroadcastPreset = NormalizeSlotBroadcastPreset(GetString(map, "broadcast_preset", "Keep current")),
                    CreatedUtc = GetString(map, "created_utc", ""),
                    UpdatedUtc = GetString(map, "updated_utc", ""),
                    LastUsedUtc = GetString(map, "last_used_utc", "")
                };
            }
            catch { return null; }
        }

        private void SaveSlotRecord(SlotRecord slot)
        {
            if (slot == null) return;
            slot.Id = NormalizeSlotId(slot.Id);
            slot.Name = NormalizeSlotName(slot.Name);
            if (slot.Id.Length == 0) throw new InvalidOperationException("Listening session has no valid ID.");
            if (slot.Name.Length == 0) slot.Name = "Session";
            if (String.IsNullOrWhiteSpace(slot.CreatedUtc)) slot.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            slot.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            string root = SlotRootPath(slot.Id);
            Directory.CreateDirectory(root);
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id }, { "name", slot.Name },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" }, { "track_count", slot.TrackCount },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "created_utc", slot.CreatedUtc ?? "" }, { "updated_utc", slot.UpdatedUtc ?? "" }, { "last_used_utc", slot.LastUsedUtc ?? "" }
            };
            WriteUtf8NoBom(SlotManifestPath(slot.Id), _json.Serialize(map));
        }

        private static bool ActiveSlotDescriptorMatches(string path, SlotRecord slot, JavaScriptSerializer serializer)
        {
            if (slot == null || serializer == null || String.IsNullOrWhiteSpace(path) || !File.Exists(path)) return false;
            try
            {
                Dictionary<string, object> map = AsMap(serializer.DeserializeObject(ReadTextShared(path)));
                return GetInt(map, "schema", 0) == 2 &&
                       String.Equals(GetString(map, "id", ""), slot.Id ?? "", StringComparison.Ordinal) &&
                       String.Equals(GetString(map, "name", ""), slot.Name ?? "", StringComparison.Ordinal) &&
                       String.Equals(GetString(map, "source_kind", "Playlist"), slot.SourceKind ?? "Playlist", StringComparison.Ordinal) &&
                       String.Equals(GetString(map, "pool_name", ""), slot.PoolName ?? "", StringComparison.Ordinal) &&
                       GetInt(map, "bookmark_occurrence", 0) == slot.BookmarkOccurrence &&
                       Math.Abs(GetDouble(map, "bookmark_seconds", 0) - Math.Max(0, slot.BookmarkSeconds)) < 0.0005 &&
                       GetBool(map, "paused", false) == slot.Paused &&
                       String.Equals(GetString(map, "broadcast_preset", "Keep current"), NormalizeSlotBroadcastPreset(slot.BroadcastPreset), StringComparison.Ordinal);
            }
            catch { return false; }
        }

        private void WriteActiveSlotDescriptor(SlotRecord slot)
        {
            if (slot == null) return;
            Directory.CreateDirectory(_dataRoot);
            if (ActiveSlotDescriptorMatches(ActiveSlotDescriptorPath, slot, _json)) return;
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id ?? "" }, { "name", slot.Name ?? "" },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "updated_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
            };
            WriteUtf8NoBom(ActiveSlotDescriptorPath, _json.Serialize(map));
        }

        private void ReloadSlotRecords()
        {
            string previousSelection = "";
            if (_slotsList != null && _slotsList.SelectedItem is SlotRecord) previousSelection = ((SlotRecord)_slotsList.SelectedItem).Id;
            _slotUiSyncing = true;
            try
            {
                _slotItems.Clear();
                _slotsById.Clear();
                if (Directory.Exists(_slotsRoot))
                {
                    var loaded = new List<SlotRecord>();
                    foreach (string directory in Directory.GetDirectories(_slotsRoot))
                    {
                        string id = NormalizeSlotId(Path.GetFileName(directory));
                        SlotRecord slot = ReadSlotRecord(id);
                        if (slot != null) loaded.Add(slot);
                    }
                    foreach (SlotRecord slot in loaded.OrderBy(x => String.IsNullOrWhiteSpace(x.CreatedUtc) ? "9999" : x.CreatedUtc, StringComparer.Ordinal).ThenBy(x => x.Name, StringComparer.OrdinalIgnoreCase))
                    {
                        slot.IsActive = String.Equals(slot.Id, _activeSlotId ?? "", StringComparison.OrdinalIgnoreCase);
                        _slotItems.Add(slot);
                        _slotsById[slot.Id] = slot;
                    }
                }
                _slotSelectorItems.Clear();
                foreach (SlotRecord slot in _slotItems) _slotSelectorItems.Add(slot);
                _slotSelectorItems.Add(new SlotRecord { Id = CreateNewSlotSentinelId, Name = "Create New…", SourceKind = "Action" });
                if (_slotSelector != null)
                {
                    SlotRecord active;
                    _slotsById.TryGetValue(_activeSlotId ?? "", out active);
                    _slotSelector.SelectedItem = active;
                    _slotSelector.ToolTip = active == null
                        ? "Switch listening session. Ctrl+Alt+1-9 switches the first nine sessions."
                        : active.Name + " | " + active.ListSubtitle + " | Ctrl+Alt+1-9 switches the first nine sessions.";
                }
                if (_slotsList != null)
                {
                    SlotRecord selected = null;
                    if (!String.IsNullOrWhiteSpace(previousSelection)) _slotsById.TryGetValue(previousSelection, out selected);
                    if (selected == null) _slotsById.TryGetValue(_activeSlotId ?? "", out selected);
                    _slotsList.SelectedItem = selected;
                }
            }
            finally { _slotUiSyncing = false; }
            UpdateSlotManagerSelection();
        }

        private int ReadResumeOccurrence()
        {
            try
            {
                string path = Path.Combine(_stateRoot, "resume-track.txt");
                if (!File.Exists(path)) return 0;
                int value;
                return Int32.TryParse((ReadTextShared(path) ?? "").Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out value) ? Math.Max(0, value) : 0;
            }
            catch { return 0; }
        }

        private int CountPlaylistEntries(string path)
        {
            try
            {
                if (!File.Exists(path)) return 0;
                int count = 0;
                foreach (string raw in File.ReadLines(path, Encoding.UTF8))
                {
                    string line = (raw ?? "").Trim();
                    if (line.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || line.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) count++;
                }
                return count;
            }
            catch { return 0; }
        }

        private bool ActivePlaylistMatchesCurrentPool()
        {
            try
            {
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                var tracks = GetList(pool, "tracks");
                if (tracks.Count == 0) return false;
                var playlist = File.Exists(DirectPlaylistPath)
                    ? File.ReadAllLines(DirectPlaylistPath, Encoding.UTF8).Select(x => (x ?? "").Trim()).Where(x => x.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || x.StartsWith("https://", StringComparison.OrdinalIgnoreCase)).ToList()
                    : new List<string>();
                if (playlist.Count != tracks.Count) return false;
                // Source ownership must be exact. Sampling only the first few entries can
                // misclassify a hand-edited playlist as its former Pool when a later URL changed.
                for (int i = 0; i < playlist.Count; i++)
                {
                    string url = GetString(AsMap(tracks[i]), "url", "").Trim();
                    if (!String.Equals(url, playlist[i], StringComparison.OrdinalIgnoreCase)) return false;
                }
                return true;
            }
            catch { return false; }
        }

        private string DetectActiveSlotSourceKind(out string poolName)
        {
            poolName = "";
            int count = CountPlaylistEntries(DirectPlaylistPath);
            if (count <= 0) return "Empty";
            if (ActivePlaylistMatchesCurrentPool())
            {
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                poolName = GetString(pool, "name", "Current Pool");
                return "Pool";
            }
            return "Playlist";
        }

        private void WriteSlotSwitchJournal(SlotRecord from, SlotRecord to)
        {
            if (from == null || to == null) throw new InvalidOperationException("Listening-session switch has no rollback authority.");
            Directory.CreateDirectory(_stateRoot);
            var map = new Dictionary<string, object>
            {
                { "schema", 1 }, { "from_id", from.Id ?? "" }, { "from_name", from.Name ?? "" },
                { "to_id", to.Id ?? "" }, { "to_name", to.Name ?? "" },
                { "created_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
            };
            WriteUtf8NoBom(SlotSwitchJournalPath, _json.Serialize(map));
        }

        private void SaveSlotRecordWorker(SlotRecord slot)
        {
            if (slot == null) return;
            slot.Id = NormalizeSlotId(slot.Id);
            slot.Name = NormalizeSlotName(slot.Name);
            if (slot.Id.Length == 0) throw new InvalidOperationException("Listening session has no valid ID.");
            if (slot.Name.Length == 0) slot.Name = "Session";
            if (String.IsNullOrWhiteSpace(slot.CreatedUtc)) slot.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            slot.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
            Directory.CreateDirectory(SlotRootPath(slot.Id));
            var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 64 };
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id }, { "name", slot.Name },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" }, { "track_count", slot.TrackCount },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "created_utc", slot.CreatedUtc ?? "" }, { "updated_utc", slot.UpdatedUtc ?? "" }, { "last_used_utc", slot.LastUsedUtc ?? "" }
            };
            WriteUtf8NoBom(SlotManifestPath(slot.Id), serializer.Serialize(map));
        }

        private void WriteActiveSlotDescriptorWorker(SlotRecord slot)
        {
            if (slot == null) return;
            Directory.CreateDirectory(_dataRoot);
            var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 64 };
            if (ActiveSlotDescriptorMatches(ActiveSlotDescriptorPath, slot, serializer)) return;
            var map = new Dictionary<string, object>
            {
                { "schema", 2 }, { "id", slot.Id ?? "" }, { "name", slot.Name ?? "" },
                { "source_kind", slot.SourceKind ?? "Playlist" }, { "pool_name", slot.PoolName ?? "" },
                { "bookmark_occurrence", slot.BookmarkOccurrence }, { "bookmark_seconds", Math.Max(0, slot.BookmarkSeconds) }, { "paused", slot.Paused },
                { "broadcast_preset", NormalizeSlotBroadcastPreset(slot.BroadcastPreset) },
                { "updated_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
            };
            WriteUtf8NoBom(ActiveSlotDescriptorPath, serializer.Serialize(map));
        }

        private void WriteSlotSwitchJournalWorker(SlotRecord from, SlotRecord to)
        {
            if (from == null || to == null) throw new InvalidOperationException("Listening-session switch has no rollback authority.");
            Directory.CreateDirectory(_stateRoot);
            var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 64 };
            var map = new Dictionary<string, object>
            {
                { "schema", 1 }, { "from_id", from.Id ?? "" }, { "from_name", from.Name ?? "" },
                { "to_id", to.Id ?? "" }, { "to_name", to.Name ?? "" },
