        private void SnapshotGlobalStateIntoSlotWorker(SlotRecord slot)
        {
            if (slot == null) return;
            string root = SlotRootPath(slot.Id);
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(Path.Combine(root, "state"));
            foreach (string relative in SlotSnapshotFiles) CopyGlobalFileToSlot(relative, root);
            if (slot.BookmarkOccurrence <= 0) slot.BookmarkOccurrence = ReadResumeOccurrence();
            SaveSlotRecordWorker(slot);
        }

        private void RestoreSlotIntoGlobalWorker(SlotRecord slot)
        {
            if (slot == null) throw new InvalidOperationException("Listening session is unavailable.");
            string root = SlotRootPath(slot.Id);
            if (!Directory.Exists(root)) throw new DirectoryNotFoundException("Listening session folder is missing: " + slot.Name);
            Directory.CreateDirectory(_stateRoot);
            foreach (string relative in SlotSnapshotFiles) RestoreSlotFileToGlobal(relative, root);
            if (!File.Exists(DirectPlaylistPath)) WriteUtf8NoBom(DirectPlaylistPath, "");
            if (slot.BookmarkOccurrence > 0) WriteUtf8NoBom(Path.Combine(_stateRoot, "resume-track.txt"), slot.BookmarkOccurrence.ToString(CultureInfo.InvariantCulture));
            foreach (string volatileName in new[] { "current.json", "engine-status.json", "queue-runtime.json", "runtime-lease.json", "startup-flight.json", "supervisor-status.txt", "planned-stop.pending", "controller-runtime-owner.json", "supervisor.pid", "engine.pid", "server.pid" })
            {
                try { File.Delete(Path.Combine(_stateRoot, volatileName)); } catch { }
            }
        }


        private void ClearSlotSwitchJournal()
        {
            try { File.Delete(SlotSwitchJournalPath); } catch { }
        }

        private void RecoverInterruptedSlotSwitch()
        {
            if (!File.Exists(SlotSwitchJournalPath)) return;
            Dictionary<string, object> journal = ReadJsonFresh(SlotSwitchJournalPath);
            string fromId = NormalizeSlotId(GetString(journal, "from_id", ""));
            SlotRecord from = null;
            if (fromId.Length > 0) _slotsById.TryGetValue(fromId, out from);
            if (from == null)
            {
                // Never guess which Slot owns partially restored global files. Preserve the
                // evidence for diagnostics and continue with the last committed descriptor.
                string quarantine = SlotSwitchJournalPath + ".unresolved." + DateTime.UtcNow.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture);
                try { File.Move(SlotSwitchJournalPath, quarantine); } catch { }
                return;
            }

            RestoreSlotIntoGlobal(from);
            _activeSlotId = from.Id;
            _activeSlotName = from.Name;
            WriteActiveSlotDescriptor(from);
            ClearSlotSwitchJournal();
            AddActivity("Listening session", "recovered interrupted switch | restored " + from.Name);
        }

        private void CopyGlobalFileToSlot(string relative, string slotRoot)
        {
            string source = Path.Combine(_dataRoot, relative);
            string target = Path.Combine(slotRoot, relative);
            if (File.Exists(source))
            {
                string parent = Path.GetDirectoryName(target);
                if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(source, target, true);
            }
            else
            {
                try { if (File.Exists(target)) File.Delete(target); } catch { }
            }
        }

        private void RestoreSlotFileToGlobal(string relative, string slotRoot)
        {
            string source = Path.Combine(slotRoot, relative);
            string target = Path.Combine(_dataRoot, relative);
            if (File.Exists(source))
            {
                string parent = Path.GetDirectoryName(target);
                if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(source, target, true);
            }
            else
            {
                try { if (File.Exists(target)) File.Delete(target); } catch { }
            }
        }

        private void CaptureLiveSlotBookmark(SlotRecord slot)
        {
            if (slot == null) return;
            int occurrence = _currentOccurrence > 0 ? _currentOccurrence : ReadResumeOccurrence();
            double seconds = Math.Max(0, _timePosition);
            if (_running)
            {
                double observed = GetMpvTimePosition();
                if (observed >= 0) seconds = observed;
            }
            slot.BookmarkOccurrence = occurrence;
            slot.BookmarkSeconds = seconds;
            slot.Paused = _running && _audioActive && _paused;
            if (occurrence > 0)
            {
                string resume = Path.Combine(SlotRootPath(slot.Id), "state", "resume-track.txt");
                Directory.CreateDirectory(Path.GetDirectoryName(resume));
                WriteUtf8NoBom(resume, occurrence.ToString(CultureInfo.InvariantCulture));
            }
            SaveSlotRecord(slot);
            if (String.Equals(slot.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) WriteActiveSlotDescriptor(slot);
        }

        private void SnapshotGlobalStateIntoSlot(SlotRecord slot, bool captureLiveBookmark)
        {
            if (slot == null) return;
            string root = SlotRootPath(slot.Id);
            Directory.CreateDirectory(root);
            Directory.CreateDirectory(Path.Combine(root, "state"));
            if (captureLiveBookmark)
            {
                SaveQueueCheckpointsState();
                CaptureLiveSlotBookmark(slot);
            }
            foreach (string relative in SlotSnapshotFiles) CopyGlobalFileToSlot(relative, root);

            if (!captureLiveBookmark && slot.BookmarkOccurrence <= 0)
                slot.BookmarkOccurrence = ReadResumeOccurrence();

            string poolName;
            slot.SourceKind = DetectActiveSlotSourceKind(out poolName);
            slot.PoolName = poolName;
            slot.TrackCount = CountPlaylistEntries(DirectPlaylistPath);
            SaveSlotRecord(slot);
            if (String.Equals(slot.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) WriteActiveSlotDescriptor(slot);
        }

        private void RestoreSlotIntoGlobal(SlotRecord slot)
        {
            if (slot == null) throw new InvalidOperationException("Listening session is unavailable.");
            string root = SlotRootPath(slot.Id);
            if (!Directory.Exists(root)) throw new DirectoryNotFoundException("Listening session folder is missing: " + slot.Name);
            Directory.CreateDirectory(_stateRoot);
            foreach (string relative in SlotSnapshotFiles) RestoreSlotFileToGlobal(relative, root);
            if (!File.Exists(DirectPlaylistPath)) WriteUtf8NoBom(DirectPlaylistPath, "");
            if (slot.BookmarkOccurrence > 0) WriteUtf8NoBom(Path.Combine(_stateRoot, "resume-track.txt"), slot.BookmarkOccurrence.ToString(CultureInfo.InvariantCulture));

            foreach (string volatileName in new[] { "current.json", "engine-status.json", "queue-runtime.json", "runtime-lease.json", "startup-flight.json", "supervisor-status.txt", "planned-stop.pending", "controller-runtime-owner.json", "supervisor.pid", "engine.pid", "server.pid" })
            {
                try { File.Delete(Path.Combine(_stateRoot, volatileName)); } catch { }
            }
            _jsonCache.Clear();
        }

        private void EnsureListeningSlotFoundation()
        {
            try
            {
                Directory.CreateDirectory(_slotsRoot);
                Directory.CreateDirectory(_stateRoot);
                ReloadSlotRecords();
                RecoverInterruptedSlotSwitch();
                ReloadSlotRecords();
                Dictionary<string, object> activeMap = ReadJsonFresh(ActiveSlotDescriptorPath);
                string requested = NormalizeSlotId(GetString(activeMap, "id", ""));
                SlotRecord active = null;
                if (requested.Length > 0) _slotsById.TryGetValue(requested, out active);

                if (_slotItems.Count == 0)
                {
                    active = new SlotRecord
                    {
                        Id = "default",
                        Name = "Main",
                        SourceKind = "Playlist",
                        CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture),
                        LastUsedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture)
                    };
                    _activeSlotId = active.Id;
                    _activeSlotName = active.Name;
                    SnapshotGlobalStateIntoSlot(active, false);
                    ReloadSlotRecords();
                    _slotsById.TryGetValue(active.Id, out active);
                }
                if (active == null && _slotItems.Count > 0) active = _slotItems[0];
                if (active == null) return;
                // If the engine had time to checkpoint a newer exact position but the
                // controller was terminated before its 15-second manifest checkpoint,
                // recover that active descriptor instead of throwing the position away.
                if (String.Equals(GetString(activeMap, "id", ""), active.Id, StringComparison.OrdinalIgnoreCase) &&
                    GetInt(activeMap, "engine_updated_unix", 0) > 0)
                {
                    active.BookmarkOccurrence = Math.Max(active.BookmarkOccurrence, GetInt(activeMap, "bookmark_occurrence", active.BookmarkOccurrence));
                    active.BookmarkSeconds = Math.Max(0, GetDouble(activeMap, "bookmark_seconds", active.BookmarkSeconds));
                    active.Paused = GetBool(activeMap, "paused", active.Paused);
                    SaveSlotRecord(active);
                }
                _activeSlotId = active.Id;
                _activeSlotName = active.Name;
                WriteActiveSlotDescriptor(active);
                ReloadSlotRecords();
            }
            catch
            {
                _activeSlotId = "";
                _activeSlotName = "Main";
            }
        }

        private void CheckpointActiveSlotBookmarkIfDue(long now)
        {
            if (!_running || String.IsNullOrWhiteSpace(_activeSlotId) || _slotSwitchActive || _shutdownRequested) return;
            if (now - _lastSlotBookmarkCheckpointMs < 15000) return;
            _lastSlotBookmarkCheckpointMs = now;
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId, out slot) || slot == null) return;
            slot.BookmarkOccurrence = _currentOccurrence > 0 ? _currentOccurrence : slot.BookmarkOccurrence;
            slot.BookmarkSeconds = Math.Max(0, _timePosition);
            slot.Paused = _audioActive && _paused;
            QueueSlotBookmarkWrite(slot.Clone(), Volatile.Read(ref _slotStateEpoch));
        }

        private void QueueSlotBookmarkWrite(SlotRecord snapshot, int epoch)
        {
            if (snapshot == null) return;
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try
                {
                    if (epoch != Volatile.Read(ref _slotStateEpoch) || _shutdownRequested || _slotSwitchActive) return;
                    snapshot.Id = NormalizeSlotId(snapshot.Id);
                    snapshot.Name = NormalizeSlotName(snapshot.Name);
                    if (snapshot.Id.Length == 0) return;
                    if (snapshot.Name.Length == 0) snapshot.Name = "Session";
                    if (String.IsNullOrWhiteSpace(snapshot.CreatedUtc)) snapshot.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                    snapshot.UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);
                    if (epoch != Volatile.Read(ref _slotStateEpoch) || _shutdownRequested || _slotSwitchActive) return;
                    SaveSlotRecordWorker(snapshot);
                    if (epoch != Volatile.Read(ref _slotStateEpoch) || _shutdownRequested || _slotSwitchActive) return;
                    WriteActiveSlotDescriptorWorker(snapshot);
                }
                catch (Exception ex) { WriteControllerPerformanceLogAsync("Session bookmark could not be saved: " + ex.GetType().Name + " " + ex.Message); }
            });
        }

        private void PersistActiveSlotState(bool captureLiveBookmark)
        {
            Interlocked.Increment(ref _slotStateEpoch);
            if (String.IsNullOrWhiteSpace(_activeSlotId)) return;
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId, out slot) || slot == null) slot = ReadSlotRecord(_activeSlotId);
            if (slot == null) return;
            SnapshotGlobalStateIntoSlot(slot, captureLiveBookmark);
            _activeSlotName = slot.Name;
        }

        private void MarkActiveSlotSourceChanged(string kind)
        {
            Interlocked.Increment(ref _slotStateEpoch);
            SlotRecord slot;
            if (!_slotsById.TryGetValue(_activeSlotId ?? "", out slot) || slot == null) return;
            string poolName;
            string detected = DetectActiveSlotSourceKind(out poolName);
            slot.SourceKind = String.IsNullOrWhiteSpace(kind) ? detected : kind;
            slot.PoolName = String.Equals(slot.SourceKind, "Pool", StringComparison.OrdinalIgnoreCase) ? poolName : "";
            slot.TrackCount = CountPlaylistEntries(DirectPlaylistPath);
            try { SnapshotGlobalStateIntoSlot(slot, false); } catch { }
            ReloadSlotRecords();
        }

        private bool ActiveSlotHasPlayableSource()
        {
            return CountPlaylistEntries(DirectPlaylistPath) > 0;
        }

        private void ResetControllerProjectionForSlotSwitch()
        {
            StopPreviewProcesses();
            Interlocked.Increment(ref _metadataGeneration);
            Interlocked.Increment(ref _metadataBulkGeneration);
            _metadataBulkActive = false; _metadataBulkSessionId = ""; _metadataBulkRetryAfterMs = 0; _metadataTailCursor = 0; _metadataCacheSweepActive = false; _metadataCacheSweepSessionId = "";
            Interlocked.Increment(ref _mediaResolveGeneration);
            lock (_mediaResolveSync) { _pendingMediaResolve = null; }
            _lastMediaCurrentSnapshot = null; _lastMediaResolveOccurrence = 0; _lastMediaResolveMs = -10000;
            _pendingRuntimeQueueProjectionEvidence = null; _lastQueueRuntimeSnapshot = null; _lastQueueSessionSnapshot = null; _lastQueueOrderSnapshot = null;
            lock (_runtimeLivenessSync) { _runtimeLivenessGeneration++; _runtimeLivenessValid = false; _enginePidLiveCached = false; _supervisorPidLiveCached = false; _runtimeLivenessStampMs = -10000; }
            lock (_playbackSnapshotSync) { _playbackSnapshotGeneration++; _playbackSnapshotValid = false; _playbackSnapshotStampMs = -10000; _playbackSnapshotPosition = -1; }
            lock (_presentationDemandSync) { _presentationDemandGeneration++; _presentationDemandPendingKey = ""; _presentationDemandLastAcceptedKey = ""; _presentationDemandRuntimeId = ""; _presentationDemandLastAcceptedMs = -10000; }
            lock (_volumeSnapshotSync) { _volumeSnapshotGeneration++; _volumeSnapshotValid = false; _volumeSnapshotStampMs = -10000; }
            _order.Clear(); _orderIndexByOccurrence.Clear(); _queueRows.Clear(); _queueByOccurrence.Clear(); _runtimeQueue.Clear(); _trackMeta.Clear();
            _queueUiMaterialized = false; _queueUiOrderDirty = true; _queueUiMaterializationActive = false; _queueUiMaterializationGeneration++;
            _queueUiMaterializationRemaining = 0; _queueUiDeferredDirtyOccurrences.Clear(); _queueUiRestoreSelectedOccurrences.Clear(); _queueUiPendingSelectOccurrence = 0; _queueUiPendingSelectRelaxFilters = false; _queueUiPendingSelectTopAnchor = false;
            _queueHorizonTemporalRows.Clear();
            _metadataPrefetchQueue.Clear(); _metadataUrgentQueue.Clear(); _metadataPrefetchPending.Clear(); _metadataPrefetchRetryAfterMs.Clear();
            _currentOccurrence = 0; _currentSlot = 0; _sessionId = ""; _orderRevision = -1; _orderCommandSerial = 0;
            _duration = 0; _timePosition = 0; _lastMediaOccurrence = 0; _pendingTransportOutgoingMediaOccurrence = 0; _lastQueueFollowOccurrence = 0;
            _running = false; _audioActive = false; _paused = false; _lastPlaybackPhase = "stopped";
            _startupPrewarmReady = false;
            _engineLaunchRequestedMs = -10000; _engineLaunchMonitorActive = false; _engineLaunchGeneration++;
            LoadQueueCheckpoints();
        }

        private void SwitchListeningSlot(string targetId, string origin)
        {
            string id = NormalizeSlotId(targetId);
            if (id.Length == 0 || _slotSwitchActive || _shutdownRequested) return;
            if ((_settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible) ||
                (_poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible) ||
                (_playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible))
            {
                ShowToast("Listening session", "Finish or close the open editor first so its draft stays attached to the right session.");
                ReloadSlotRecords();
                return;
            }
            if (String.Equals(id, _activeSlotId, StringComparison.OrdinalIgnoreCase))
            {
                ReloadSlotRecords();
                return;
            }
            SlotRecord targetLive;
            if (!_slotsById.TryGetValue(id, out targetLive) || targetLive == null)
            {
                ShowToast("Listening session", "That session is no longer available.");
                ReloadSlotRecords();
                return;
            }
            SlotRecord currentLive;
            _slotsById.TryGetValue(_activeSlotId ?? "", out currentLive);
            if (currentLive == null)
            {
                ShowToast("Listening session", "The current session state could not be verified, so YOMI did not switch.");
                ReloadSlotRecords();
                return;
            }
            bool wasRunning = _running || _engineLaunchMonitorActive || IsPidFileLive(Path.Combine(_stateRoot, "supervisor.pid")) || IsPidFileLive(Path.Combine(_stateRoot, "engine.pid"));
            Dictionary<string, object> broadcastBaseline = ReadJsonFresh(Path.Combine(_dataRoot, "config.json"));
            if (broadcastBaseline.Count == 0) broadcastBaseline = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));
            int broadcastGeneration = Interlocked.Increment(ref _slotBroadcastGeneration);
            Interlocked.Increment(ref _slotStateEpoch);
            Interlocked.Increment(ref _transportCommandEpoch);
            _slotSwitchActive = true;
            UpdateSlotSwitchUi();
            FinalizeListeningVisit(true, true);
            CaptureLiveSlotBookmark(currentLive);
            string poolName; currentLive.SourceKind = DetectActiveSlotSourceKind(out poolName); currentLive.PoolName = poolName; currentLive.TrackCount = CountPlaylistEntries(DirectPlaylistPath);
            SlotRecord current = currentLive.Clone(); SlotRecord target = targetLive.Clone(); string repeatAtBoundary = _repeatMode; string switchOrigin = origin ?? "ui";
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                bool switchJournalWritten=false, rollbackComplete=false; string failure=""; bool targetPlayable=false;
                try
                {
                    if (wasRunning && !StopOwnedYomiRuntime()) throw new InvalidOperationException("The current playback runtime could not be stopped safely, so YOMI kept the current session active.");
                    PersistRepeatModeForTransition(repeatAtBoundary);
                    SnapshotGlobalStateIntoSlotWorker(current);
                    WriteSlotSwitchJournalWorker(current,target); switchJournalWritten=true;
                    try { File.Delete(Path.Combine(_stateRoot, "planned-stop.pending")); } catch { }
                    RestoreSlotIntoGlobalWorker(target);
                    target.LastUsedUtc=DateTime.UtcNow.ToString("o",CultureInfo.InvariantCulture); SaveSlotRecordWorker(target); WriteActiveSlotDescriptorWorker(target); ClearSlotSwitchJournal(); switchJournalWritten=false;
                    targetPlayable=CountPlaylistEntries(DirectPlaylistPath)>0;
                }
                catch(Exception ex)
                {
                    failure=ex.Message;
                    try { RestoreSlotIntoGlobalWorker(current); WriteActiveSlotDescriptorWorker(current); rollbackComplete=true; if(switchJournalWritten) ClearSlotSwitchJournal(); } catch { rollbackComplete=false; }
                }
                if (!TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    bool succeeded=String.IsNullOrWhiteSpace(failure); SlotRecord authoritative=succeeded?target:current;
                    _jsonCache.Clear(); _activeSlotId=authoritative.Id; _activeSlotName=authoritative.Name; ResetControllerProjectionForSlotSwitch(); ReloadSlotRecords(); _slotSwitchProjectionCommit=true; try{SafeRefresh(true);}finally{_slotSwitchProjectionCommit=false;}
                    _slotSwitchActive=false;
                    if(succeeded)
                    {
                        bool broadcastQueued=QueueSlotBroadcastAffinity(authoritative, broadcastGeneration, broadcastBaseline); string obsNote=broadcastQueued?"OBS URL unchanged. The preferred broadcast layout is applying.":"OBS stays on the same YOMI output.";
                        if(wasRunning&&targetPlayable&&!_shutdownRequested)
                        {
                            var restart=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(650)}; restart.Tick+=delegate{restart.Stop();if(!_shutdownRequested&&!_slotSwitchActive)StartEngine();if(!_shutdownRequested)ShowToast("Listening session","Switched to "+authoritative.Name+". "+obsNote);};restart.Start();
                        }
                        else if(wasRunning&&!targetPlayable)ShowToast("Listening session",authoritative.Name+" is empty. "+obsNote+" Add a playlist or Pool, then press Play.");
                        else ShowToast("Listening session","Switched to "+authoritative.Name+". "+obsNote); AddActivity("Listening session","switched to "+authoritative.Name+" | "+switchOrigin);
                    }
                    else
                    {
                        SlotRecord keepCurrent = current.Clone(); keepCurrent.BroadcastPreset = "Keep current";
                        QueueSlotBroadcastAffinity(keepCurrent, broadcastGeneration, broadcastBaseline);
                        if(!rollbackComplete)AddActivity("Listening session","rollback incomplete | startup recovery journal retained"); ShowToast("Session switch stopped",failure);
                    }
                    ReloadSlotRecords(); UpdateSlotSwitchUi();
                    if(_shutdownAfterSlotSwitch){_shutdownAfterSlotSwitch=false;_shutdownRequested=false;StopYomiAndExit();}
                    else if(_controllerCloseAfterSlotSwitch){_controllerCloseAfterSlotSwitch=false;CloseControllerOnly();}
                })) _slotSwitchActive=false;
            });
        }

        private void WireListeningSlots()
        {
            if (_slotSelector == null || _slotsOverlay == null) return;
            _slotSelector.ItemsSource = _slotSelectorItems;
            _slotsList.ItemsSource = _slotItems;
            FillCombo(_slotBroadcastPresetCombo, "Keep current", "Classic strip", "Split sources", "Text + artwork", "Visual focus");
            _slotBroadcastFollowCheck.IsChecked = _slotBroadcastFollowEnabled;
            _slotBroadcastFollowCheck.Checked += delegate
            {
                if (_slotUiSyncing) return;
                _slotBroadcastFollowEnabled = true; SaveUiState();
                _slotsStatusText.Text = "Layout following enabled. A session's preferred layout applies when that session becomes active; the OBS URL does not change.";
                UpdateSlotSwitchUi();
            };
            _slotBroadcastFollowCheck.Unchecked += delegate
            {
                if (_slotUiSyncing) return;
                _slotBroadcastFollowEnabled = false; Interlocked.Increment(ref _slotBroadcastGeneration); SaveUiState();
                _slotsStatusText.Text = "Layout following disabled. Session switching changes music only.";
                UpdateSlotSwitchUi();
            };
            _slotBroadcastPresetCombo.SelectionChanged += delegate
            {
                if (_slotUiSyncing || _slotSwitchActive) return;
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null) return;
                selected.BroadcastPreset = NormalizeSlotBroadcastPreset(Convert.ToString(_slotBroadcastPresetCombo.SelectedItem, CultureInfo.InvariantCulture));
                try
                {
                    SaveSlotRecord(selected);
                    string keep = selected.Id; ReloadSlotRecords(); SlotRecord loaded; if (_slotsById.TryGetValue(keep, out loaded)) _slotsList.SelectedItem = loaded;
                    _slotsStatusText.Text = String.Equals(selected.BroadcastPreset, "Keep current", StringComparison.OrdinalIgnoreCase)
                        ? "This session will keep whatever broadcast layout is already active."
                        : "Preferred layout saved. It applies when this session becomes active if layout following is enabled.";
                }
                catch (Exception ex) { _slotsStatusText.Text = "Could not save layout preference: " + ex.Message; }
            };
            _slotSelector.SelectionChanged += delegate
            {
                if (_slotUiSyncing || _slotSwitchActive) return;
                SlotRecord selected = _slotSelector.SelectedItem as SlotRecord;
                if (selected == null) return;
                if (String.Equals(selected.Id, CreateNewSlotSentinelId, StringComparison.Ordinal))
                {
                    _slotUiSyncing = true;
                    try { SlotRecord active; _slotsById.TryGetValue(_activeSlotId ?? "", out active); _slotSelector.SelectedItem = active; }
                    finally { _slotUiSyncing = false; }
                    OpenListeningSlots();
                    if (_slotNameBox != null) { _slotNameBox.Text = ""; _slotNameBox.Focus(); }
                    return;
                }
                if (!String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) SwitchListeningSlot(selected.Id, "selector");
            };
            _slotsManageButton.Click += delegate { OpenListeningSlots(); };
            _slotsCloseButton.Click += delegate { if (!_slotSwitchActive) CloseListeningSlots(); };
            _slotSwitchButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected != null) SwitchListeningSlot(selected.Id, "manager");
            };
            _slotNewButton.Click += delegate { CreateBlankListeningSlot(); };
            _slotDuplicateButton.Click += delegate { DuplicateSelectedListeningSlot(); };
            _slotRenameButton.Click += delegate { RenameSelectedListeningSlot(); };
            _slotDeleteButton.Click += delegate { DeleteSelectedListeningSlot(); };
            _slotEditPlaylistButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null || !String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) return;
                CloseListeningSlots(); OpenPlaylistEditor();
            };
            _slotPoolButton.Click += delegate
            {
                SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
                if (selected == null || !String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) return;
                CloseListeningSlots(); OpenPlaylistPool();
            };
            _slotsList.SelectionChanged += delegate
            {
                if (_slotUiSyncing) return;
                UpdateSlotManagerSelection();
            };
            _slotNameBox.KeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key == Key.Enter) { RenameSelectedListeningSlot(); e.Handled = true; }
            };
            _slotsOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (_slotSwitchActive || IsVisualDescendantOf(e.OriginalSource as DependencyObject, _slotsCard)) return;
                CloseListeningSlots();
            };
            ReloadSlotRecords();
        }

        private bool PrepareAuthoringSurface(AuthoringSurfaceKind target, string label)
        {
            bool settingsOpen = _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible;
            bool slotsOpen = _slotsOverlay != null && _slotsOverlay.Visibility == Visibility.Visible;
            bool poolOpen = _poolOverlay != null && _poolOverlay.Visibility == Visibility.Visible;
            bool editorOpen = _playlistEditorOverlay != null && _playlistEditorOverlay.Visibility == Visibility.Visible;

            if (target != AuthoringSurfaceKind.Settings && settingsOpen)
            {
                ShowToast(label, "Close Settings first so its unsaved draft stays explicit.");
                return false;
            }
            if (target != AuthoringSurfaceKind.PlaylistPool && poolOpen)
            {
                ShowToast(label, "Close Playlist Pool first so one source editor owns the draft.");
                return false;
            }
            if (target != AuthoringSurfaceKind.PlaylistEditor && editorOpen)
            {
                ShowToast(label, "Close the playlist editor first so one source editor owns the draft.");
                return false;
            }
            if (target == AuthoringSurfaceKind.Settings && (poolOpen || editorOpen))
            {
                ShowToast(label, "Finish or close the active source draft first.");
                return false;
            }
            if (target != AuthoringSurfaceKind.ListeningSlots && slotsOpen) CloseListeningSlots();

            if (_commandPaletteOverlay != null && _commandPaletteOverlay.Visibility == Visibility.Visible) CloseCommandPalette();
            if (_operatorDeckOverlay != null && _operatorDeckOverlay.Visibility == Visibility.Visible) CloseOperatorDeck();
            if (_intentFabricOverlay != null && _intentFabricOverlay.Visibility == Visibility.Visible) CloseIntentFabric();
            if (_volumePopup != null) _volumePopup.IsOpen = false;
            return true;
        }

        private void OpenListeningSlots()
        {
            if (_slotsOverlay == null) return;
            if (_slotsOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_slotsList != null) _slotsList.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.ListeningSlots, "Session Manager")) return;
            _slotsReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            PersistActiveSlotState(false);
            ReloadSlotRecords();
            _slotsOverlay.Visibility = Visibility.Visible;
            _slotsOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            SlotRecord active;
            if (_slotsById.TryGetValue(_activeSlotId ?? "", out active)) _slotsList.SelectedItem = active;
            UpdateSlotManagerSelection();
            _slotsList.Focus();
        }

        private void CloseListeningSlots()
        {
            if (_slotsOverlay == null || _slotSwitchActive) return;
            _slotsOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _slotsReturnFocus;
            _slotsReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private void UpdateSlotManagerSelection()
        {
            if (_slotsList == null || _slotDetailText == null) return;
            SlotRecord selected = _slotsList.SelectedItem as SlotRecord;
            bool has = selected != null;
            bool active = has && String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase);
            _slotUiSyncing = true;
            try
            {
                if (_slotNameBox != null) _slotNameBox.Text = has ? selected.Name : "";
                if (_slotBroadcastFollowCheck != null) _slotBroadcastFollowCheck.IsChecked = _slotBroadcastFollowEnabled;
                if (_slotBroadcastPresetCombo != null) SetComboPreserve(_slotBroadcastPresetCombo, has ? NormalizeSlotBroadcastPreset(selected.BroadcastPreset) : "Keep current");
            }
            finally { _slotUiSyncing = false; }
            if (!has)
            {
                _slotDetailText.Text = "Select a session.";
            }
            else
            {
                string source = String.IsNullOrWhiteSpace(selected.SourceKind) ? "Playlist" : selected.SourceKind;
                if (String.Equals(source, "Pool", StringComparison.OrdinalIgnoreCase) && !String.IsNullOrWhiteSpace(selected.PoolName)) source += " | " + selected.PoolName;
                string bookmark = selected.BookmarkOccurrence > 0
                    ? "item " + selected.BookmarkOccurrence.ToString(CultureInfo.InvariantCulture) + (selected.BookmarkSeconds > 0.5 ? " at " + FormatTime(selected.BookmarkSeconds) : "")
                    : "no bookmark yet";
                string lastUsed = "";
                DateTime parsedLast;
                if (DateTime.TryParse(selected.LastUsedUtc, CultureInfo.InvariantCulture, DateTimeStyles.RoundtripKind, out parsedLast))
                    lastUsed = " | last used " + parsedLast.ToLocalTime().ToString("g", CultureInfo.CurrentCulture);
                _slotDetailText.Text = (active ? "Current · " : "") + source + " · " + selected.TrackCount.ToString("N0", CultureInfo.InvariantCulture) + " tracks · " + bookmark + (selected.Paused ? " · paused" : "") + lastUsed;
            }
            UpdateSlotSwitchUi();
        }

        private void UpdateSlotSwitchUi()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            bool has = selected != null;
            bool active = has && String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase);
            if (_slotSwitchButton != null) { _slotSwitchButton.IsEnabled = has && !active && !_slotSwitchActive; _slotSwitchButton.Content = _slotSwitchActive ? "Switching..." : "Switch"; }
            if (_slotNewButton != null) _slotNewButton.IsEnabled = !_slotSwitchActive;
            if (_slotDuplicateButton != null) _slotDuplicateButton.IsEnabled = has && !_slotSwitchActive;
            if (_slotRenameButton != null) _slotRenameButton.IsEnabled = has && !_slotSwitchActive;
            if (_slotDeleteButton != null) _slotDeleteButton.IsEnabled = has && !active && _slotItems.Count > 1 && !_slotSwitchActive;
            if (_slotEditPlaylistButton != null) _slotEditPlaylistButton.IsEnabled = active && !_slotSwitchActive;
            if (_slotPoolButton != null) _slotPoolButton.IsEnabled = active && !_slotSwitchActive;
            if (_slotSelector != null) _slotSelector.IsEnabled = !_slotSwitchActive;
            if (_slotsManageButton != null) _slotsManageButton.IsEnabled = !_slotSwitchActive;
            if (_slotBroadcastFollowCheck != null) _slotBroadcastFollowCheck.IsEnabled = !_slotSwitchActive;
            if (_slotBroadcastPresetCombo != null) _slotBroadcastPresetCombo.IsEnabled = has && !_slotSwitchActive;
            if (_slotsStatusText != null && _slotSwitchActive) _slotsStatusText.Text = "Saving your place and switching...";
            else if (_slotsStatusText != null) _slotsStatusText.Text = "Your place is saved before switching. Ctrl+Alt+1-9 jumps between sessions. OBS keeps using the same YOMI overlay URL.";
        }

        private void CreateBlankListeningSlot()
        {
            string requested = _slotNameBox != null ? _slotNameBox.Text : "";
            string name = UniqueSlotName(String.IsNullOrWhiteSpace(requested) ? "New session" : requested);
            SlotRecord slot = new SlotRecord
            {
                Id = NewSlotId(), Name = name, SourceKind = "Empty", TrackCount = 0,
                CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture), UpdatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture)
            };
            try
            {
                string root = SlotRootPath(slot.Id);
                Directory.CreateDirectory(Path.Combine(root, "state"));
                WriteUtf8NoBom(Path.Combine(root, "playlist.txt"), "");
                WriteUtf8NoBom(Path.Combine(root, "state", "repeat-mode.txt"), "all");
                WriteUtf8NoBom(Path.Combine(root, "state", "resume-track.txt"), "1");
                SaveSlotRecord(slot);
                ReloadSlotRecords();
                SlotRecord loaded; if (_slotsById.TryGetValue(slot.Id, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Blank session created. Switch to it, then add a playlist or Pool.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not create session: " + ex.Message; }
        }

        private void CopyDirectoryPayload(string sourceRoot, string targetRoot)
        {
            Directory.CreateDirectory(targetRoot);
            foreach (string directory in Directory.GetDirectories(sourceRoot, "*", SearchOption.AllDirectories))
            {
                string relative = directory.Substring(sourceRoot.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                Directory.CreateDirectory(Path.Combine(targetRoot, relative));
            }
            foreach (string file in Directory.GetFiles(sourceRoot, "*", SearchOption.AllDirectories))
            {
                if (String.Equals(Path.GetFileName(file), "slot.json", StringComparison.OrdinalIgnoreCase)) continue;
                string relative = file.Substring(sourceRoot.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
                string target = Path.Combine(targetRoot, relative);
                string parent = Path.GetDirectoryName(target); if (!String.IsNullOrWhiteSpace(parent)) Directory.CreateDirectory(parent);
                File.Copy(file, target, true);
            }
        }

        private void DuplicateSelectedListeningSlot()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null) return;
            if (String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) PersistActiveSlotState(true);
            selected = ReadSlotRecord(selected.Id) ?? selected;
            string requested = _slotNameBox != null ? _slotNameBox.Text : "";
            string name = UniqueSlotName(String.IsNullOrWhiteSpace(requested) || String.Equals(requested, selected.Name, StringComparison.OrdinalIgnoreCase) ? selected.Name + " copy" : requested);
            SlotRecord copy = selected.Clone();
            copy.Id = NewSlotId(); copy.Name = name; copy.CreatedUtc = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); copy.LastUsedUtc = "";
            try
            {
                CopyDirectoryPayload(SlotRootPath(selected.Id), SlotRootPath(copy.Id));
                SaveSlotRecord(copy);
                ReloadSlotRecords();
                SlotRecord loaded; if (_slotsById.TryGetValue(copy.Id, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Duplicated " + selected.Name + ". The copy has independent session state but uses the same shared YOMI cache.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not duplicate session: " + ex.Message; }
        }

        private void RenameSelectedListeningSlot()
        {
            if (_slotUiSyncing) return;
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null) return;
            string name = NormalizeSlotName(_slotNameBox != null ? _slotNameBox.Text : "");
            if (name.Length == 0) { _slotsStatusText.Text = "Give the session a name first."; return; }
            SlotRecord collision = _slotItems.FirstOrDefault(x => !String.Equals(x.Id, selected.Id, StringComparison.OrdinalIgnoreCase) && String.Equals(x.Name, name, StringComparison.OrdinalIgnoreCase));
            if (collision != null) { _slotsStatusText.Text = "Another session already uses that name."; return; }
            selected.Name = name;
            try
            {
                SaveSlotRecord(selected);
                if (String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase)) { _activeSlotName = selected.Name; WriteActiveSlotDescriptor(selected); }
                string keep = selected.Id; ReloadSlotRecords(); SlotRecord loaded; if (_slotsById.TryGetValue(keep, out loaded)) _slotsList.SelectedItem = loaded;
                _slotsStatusText.Text = "Session renamed.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not rename session: " + ex.Message; }
        }

        private void DeleteSelectedListeningSlot()
        {
            SlotRecord selected = _slotsList != null ? _slotsList.SelectedItem as SlotRecord : null;
            if (selected == null || String.Equals(selected.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase) || _slotItems.Count <= 1) return;
            MessageBoxResult answer = MessageBox.Show(_window,
                "Delete listening session '" + selected.Name + "'?\r\n\r\nIts playlist/Pool definition and saved session/bookmark are removed. Shared media cache, favorites and other sessions are untouched.",
                "Delete listening session", MessageBoxButton.YesNo, MessageBoxImage.Warning);
            if (answer != MessageBoxResult.Yes) return;
            try
            {
                Directory.Delete(SlotRootPath(selected.Id), true);
                ReloadSlotRecords();
                _slotsStatusText.Text = "Session deleted.";
            }
            catch (Exception ex) { _slotsStatusText.Text = "Could not delete session: " + ex.Message; }
        }

        private string DirectPlaylistPath { get { return Path.Combine(_dataRoot, "playlist.txt"); } }

        private void EditPlaylistFile()
        {
            OpenPlaylistEditor();
        }

        private void WirePlaylistEditor()
        {
            if (_playlistEditorOverlay == null) return;
            _playlistEditorCloseButton.Click += delegate { ClosePlaylistEditor(); };
            _playlistEditorSaveButton.Click += delegate { SavePlaylistEditor(); };
            _playlistEditorBox.TextChanged += delegate
            {
                if (_playlistEditorLoading) return;
                bool dirty = !String.Equals(_playlistEditorBox.Text ?? "", _playlistEditorBaseline ?? "", StringComparison.Ordinal);
                _playlistEditorSaveButton.IsEnabled = dirty;
                _playlistEditorStatusText.Text = dirty ? "Unsaved changes." : "No changes.";
            };
            _playlistEditorOverlay.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
                if (ctrl && e.Key == Key.S) { SavePlaylistEditor(); e.Handled = true; return; }
                if (e.Key == Key.Escape) { ClosePlaylistEditor(); e.Handled = true; }
            };
            _playlistEditorOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (IsVisualDescendantOf(e.OriginalSource as DependencyObject, _playlistEditorCard)) return;
                bool dirty = !String.Equals(_playlistEditorBox.Text ?? "", _playlistEditorBaseline ?? "", StringComparison.Ordinal);
                if (dirty)
                {
                    _playlistEditorStatusText.Text = "Unsaved changes - Save or Cancel.";
                    return;
                }
                ClosePlaylistEditor();
            };
        }

        private void OpenPlaylistEditor()
        {
            if (_playlistEditorOverlay == null) return;
            // Reopening a live editor must never reload playlist.txt over an unsaved draft.
            if (_playlistEditorOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_playlistEditorBox != null) _playlistEditorBox.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.PlaylistEditor, "Playlist")) return;

            _playlistEditorReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            string text = "";
            try
            {
                Directory.CreateDirectory(_dataRoot);
                if (!File.Exists(DirectPlaylistPath)) WriteUtf8NoBom(DirectPlaylistPath, "");
                text = ReadTextShared(DirectPlaylistPath);
            }
            catch { }

            _playlistEditorLoading = true;
            try
            {
                _playlistEditorBox.Text = (text ?? "").Replace("\r\n", "\n").Replace("\r", "\n").Replace("\n", Environment.NewLine);
                _playlistEditorBaseline = _playlistEditorBox.Text ?? "";
                _playlistEditorSaveButton.IsEnabled = false;
                _playlistEditorStatusText.Text = _running
                    ? "Changes apply the next time playback starts."
                    : "Changes apply when playback starts.";
            }
            finally { _playlistEditorLoading = false; }

            _playlistEditorOverlay.Visibility = Visibility.Visible;
            _playlistEditorOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            _playlistEditorBox.CaretIndex = 0;
            _playlistEditorBox.ScrollToHome();
            _playlistEditorBox.Focus();
            AddActivity("Playlist", "editor opened");
        }

        private void SavePlaylistEditor()
        {
            if (_playlistEditorOverlay == null || _playlistEditorOverlay.Visibility != Visibility.Visible) return;
            string text = _playlistEditorBox.Text ?? "";
            try
            {
                Directory.CreateDirectory(_dataRoot);
                WriteUtf8NoBom(DirectPlaylistPath, text);
                // Editing the active list directly makes this slot a direct-playlist source.
                // Saved Pool definitions remain reusable globally, but stale active Pool provenance
                // must not keep claiming ownership of a hand-edited list.
                try { File.Delete(CurrentPoolPath); } catch { }
                try { File.Delete(PoolSourcesPath); } catch { }
                try { File.Delete(PoolResetPath); } catch { }
                MarkActiveSlotSourceChanged("Playlist");
                _expectedPlaylistCount = 0;
                _playlistEditorBaseline = text;
                _playlistEditorSaveButton.IsEnabled = false;
                int entries = text.Replace("\r", "").Split('\n').Count(line => !String.IsNullOrWhiteSpace(line));
                _playlistEditorStatusText.Text = "Saved " + entries.ToString("N0", CultureInfo.InvariantCulture) + " entries. " + (_running ? "Restart playback to use the changes." : "They will be used when playback starts.");
                AddActivity("Playlist", "saved in YOMI");
                ShowToast("Playlist saved", entries.ToString("N0", CultureInfo.InvariantCulture) + " entries");
            }
            catch (Exception ex)
            {
                _playlistEditorStatusText.Text = "Could not save: " + ex.Message;
            }
        }

        private void ClosePlaylistEditor()
        {
            if (_playlistEditorOverlay == null || _playlistEditorOverlay.Visibility != Visibility.Visible) return;
            _playlistEditorOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _playlistEditorReturnFocus;
            _playlistEditorReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private string CurrentPoolPath { get { return Path.Combine(_dataRoot, "pool-current.json"); } }
        private string PoolSourcesPath { get { return Path.Combine(_dataRoot, "pool-sources.txt"); } }
        private string PoolResetPath { get { return Path.Combine(_stateRoot, "pool-reset.pending"); } }
        private string SavedPoolsDirectory { get { return Path.Combine(_dataRoot, "pools"); } }

        private void WirePlaylistPool()
        {
            if (_poolOverlay == null) return;
            if (_poolShuffleModeCombo != null)
            {
                _poolShuffleModeCombo.Items.Clear();
                _poolShuffleModeCombo.Items.Add("Global random");
                _poolShuffleModeCombo.Items.Add("Balanced sources");
                _poolShuffleModeCombo.SelectedIndex = 0;
            }
            _poolCloseButton.Click += delegate { if (!_poolBuildActive) ClosePlaylistPool(); };
            _poolBuildButton.Click += delegate { BuildPlaylistPool(); };
            if (_poolSaveButton != null) _poolSaveButton.Click += delegate { SavePlaylistPoolDefinition(); };
            if (_poolLoadButton != null) _poolLoadButton.Click += delegate { LoadSelectedPlaylistPoolDefinition(); };
            if (_poolDeleteButton != null) _poolDeleteButton.Click += delegate { DeleteSelectedPlaylistPoolDefinition(); };
            if (_poolDiscoverButton != null) _poolDiscoverButton.Click += delegate { BeginPlaylistDiscovery(); };
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.Click += delegate { AddSelectedDiscoveredPlaylists(); };
            if (_poolDiscoverList != null) _poolDiscoverList.SelectionChanged += delegate { if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = _poolDiscoverList.SelectedItems.Count > 0; };
            if (_poolDiscoverQueryBox != null) _poolDiscoverQueryBox.KeyDown += delegate(object sender, KeyEventArgs e) { if (e.Key == Key.Enter) { BeginPlaylistDiscovery(); e.Handled = true; } };
            _poolOverlay.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key == Key.Escape && !_poolBuildActive) { ClosePlaylistPool(); e.Handled = true; }
            };
            _poolOverlay.PreviewMouseDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (_poolBuildActive || IsVisualDescendantOf(e.OriginalSource as DependencyObject, _poolCard)) return;
                ClosePlaylistPool();
            };
        }

        private static string PlaylistDiscoveryUrl(string query)
        {
            return "https://www.youtube.com/results?search_query=" + Uri.EscapeDataString(query ?? "") + "&sp=EgIQAw%253D%253D";
        }

        private static string DiscoveredPlaylistUrl(Dictionary<string, object> entry)
        {
            if (entry == null) return "";
            string raw = GetString(entry, "webpage_url", GetString(entry, "url", "")).Trim();
            string id = GetString(entry, "id", "").Trim();
            if (raw.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || raw.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
            {
                if (raw.IndexOf("list=", StringComparison.OrdinalIgnoreCase) >= 0) return raw;
                if (id.Length > 0 && (GetString(entry, "ie_key", "").IndexOf("Tab", StringComparison.OrdinalIgnoreCase) >= 0 || GetString(entry, "_type", "").IndexOf("url", StringComparison.OrdinalIgnoreCase) >= 0))
                    return "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(id);
                return raw;
            }
            if (id.Length > 0) return "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(id);
            return "";
        }

        private void BeginPlaylistDiscovery()
        {
            if (_poolDiscoverQueryBox == null || _poolDiscoverList == null) return;
            string query = (_poolDiscoverQueryBox.Text ?? "").Trim();
            if (query.Length == 0)
            {
                if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "Type something to explore.";
                _poolDiscoverQueryBox.Focus();
                return;
            }
            string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
            if (!File.Exists(yt))
            {
                if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "yt-dlp is missing from the YOMI runtime.";
                return;
            }
            int generation = Interlocked.Increment(ref _poolDiscoveryGeneration);
            _poolDiscoverList.ItemsSource = null;
            _poolDiscoverList.Items.Clear();
            if (_poolDiscoverButton != null) { _poolDiscoverButton.IsEnabled = false; _poolDiscoverButton.Content = "Searching…"; }
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = false;
            if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = "Searching playlists…";
            string searchUrl = PlaylistDiscoveryUrl(query);
            ThreadPool.QueueUserWorkItem(delegate
            {
                var results = new List<PoolDiscoveryItem>();
                string failure = "";
                try
                {
                    string deno = Path.Combine(_runtimeRoot, "deno", "deno.exe");
                    string args = "--flat-playlist --playlist-end 18 --ignore-errors --quiet --no-warnings --dump-json --cache-dir " + Quote(YtDlpCacheDirectory());
                    if (File.Exists(deno)) args += " --js-runtimes " + Quote("deno:" + deno);
                    args += " " + Quote(searchUrl);
                    var lines = new List<string>();
                    var errors = new List<string>();
                    var psi = new ProcessStartInfo
                    {
                        FileName = yt,
                        Arguments = args,
                        WorkingDirectory = _dataRoot,
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        WindowStyle = ProcessWindowStyle.Hidden,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };
                    ConfigureYtDlpProcessStartInfo(psi);
                    using (var proc = new Process { StartInfo = psi })
                    {
                        proc.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (lines) lines.Add(e.Data); };
                        proc.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (errors) errors.Add(e.Data); };
                        if (!proc.Start()) throw new InvalidOperationException("Windows could not start yt-dlp.");
                        try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                        proc.BeginOutputReadLine(); proc.BeginErrorReadLine();
                        if (!proc.WaitForExit(60000)) { try { proc.Kill(); } catch { } throw new TimeoutException("Playlist discovery timed out."); }
                        try { proc.WaitForExit(); } catch { }
                        if (proc.ExitCode != 0 && lines.Count == 0)
                            throw new InvalidOperationException(errors.Count > 0 ? errors[errors.Count - 1] : "yt-dlp returned exit code " + proc.ExitCode.ToString(CultureInfo.InvariantCulture));
                    }
                    string[] snapshot; lock (lines) snapshot = lines.ToArray();
                    var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                    var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
                    foreach (string line in snapshot)
                    {
                        Dictionary<string, object> entry;
                        try { entry = AsMap(serializer.DeserializeObject(line)); } catch { continue; }
                        string url = DiscoveredPlaylistUrl(entry);
                        if (String.IsNullOrWhiteSpace(url) || !seen.Add(url)) continue;
                        string title = GetString(entry, "title", "Untitled playlist").Trim();
                        string channel = GetString(entry, "channel", GetString(entry, "uploader", GetString(entry, "channel_name", ""))).Trim();
                        int count = GetInt(entry, "playlist_count", GetInt(entry, "n_entries", GetInt(entry, "playlist_index", 0)));
                        string display = title;
                        if (!String.IsNullOrWhiteSpace(channel)) display += "  —  " + channel;
                        if (count > 0) display += "  ·  " + count.ToString("N0", CultureInfo.InvariantCulture) + " tracks";
                        results.Add(new PoolDiscoveryItem { Title = title, Channel = channel, Url = url, TrackCount = count, Display = display });
                        if (results.Count >= 18) break;
                    }
                }
                catch (Exception ex) { failure = ex.Message; }

                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (generation != _poolDiscoveryGeneration) return;
                        if (_poolDiscoverButton != null) { _poolDiscoverButton.IsEnabled = true; _poolDiscoverButton.Content = "Discover"; }
                        if (_poolDiscoverList != null) _poolDiscoverList.ItemsSource = results;
                        if (_poolDiscoverStatusText != null)
                        {
                            if (!String.IsNullOrWhiteSpace(failure)) _poolDiscoverStatusText.Text = "Discovery failed: " + failure;
                            else if (results.Count == 0) _poolDiscoverStatusText.Text = "No playlist results found.";
                            else _poolDiscoverStatusText.Text = results.Count.ToString(CultureInfo.InvariantCulture) + " playlists found";
                        }
                    });
                }
                catch { }
            });
        }

        private void AddSelectedDiscoveredPlaylists()
        {
            if (_poolDiscoverList == null || _poolSourcesBox == null) return;
            var urls = new List<string>();
            foreach (object raw in _poolDiscoverList.SelectedItems)
            {
                PoolDiscoveryItem item = raw as PoolDiscoveryItem;
                if (item != null && !String.IsNullOrWhiteSpace(item.Url)) urls.Add(item.Url.Trim());
            }
            if (urls.Count == 0) return;
            var existing = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            foreach (string line in (_poolSourcesBox.Text ?? "").Replace("\r", "").Split('\n'))
            {
                string trimmed = line.Trim();
                if (trimmed.Length == 0) continue;
                int space = trimmed.IndexOf(' ');
                string candidate = space > 0 && trimmed.Substring(0, space).EndsWith("x", StringComparison.OrdinalIgnoreCase) ? trimmed.Substring(space + 1).Trim() : trimmed;
                existing.Add(candidate);
            }
            int added = 0;
            var append = new List<string>();
            foreach (string url in urls) if (existing.Add(url)) { append.Add(url); added++; }
            if (append.Count > 0)
            {
                string prefix = String.IsNullOrWhiteSpace(_poolSourcesBox.Text) ? "" : (_poolSourcesBox.Text.TrimEnd() + Environment.NewLine);
                _poolSourcesBox.Text = prefix + String.Join(Environment.NewLine, append.ToArray());
                _poolSourcesBox.CaretIndex = _poolSourcesBox.Text.Length;
            }
            if (_poolDiscoverStatusText != null) _poolDiscoverStatusText.Text = added > 0 ? (added.ToString(CultureInfo.InvariantCulture) + " added to this Pool") : "Already in this Pool";
            if (_poolDiscoverAddButton != null) _poolDiscoverAddButton.IsEnabled = _poolDiscoverList.SelectedItems.Count > 0;
        }

        private void OpenPlaylistPool()
        {
            if (_poolOverlay == null) return;
            // Pool source text/weights are a live authoring draft. Re-invoking the command should
            // focus the existing surface, never reconstruct it underneath the user's hands.
            if (_poolOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                if (_poolSourcesBox != null) _poolSourcesBox.Focus();
                return;
            }
            if (!PrepareAuthoringSurface(AuthoringSurfaceKind.PlaylistPool, "Playlist Pool")) return;
            _poolReturnFocus = Keyboard.FocusedElement;
            if (_miniMode || (!_queueOpen && _window.WindowState == WindowState.Normal && _window.ActualHeight <= CompactControllerMaxHeight + 60.0)) ExpandCompactHostForOverlay();
            LoadPlaylistPoolDraft();
            RefreshSavedPoolList(null);
            _poolOverlay.Visibility = Visibility.Visible;
            _poolOverlay.IsHitTestVisible = true;
            SyncHostedMediaAirspace();
            _poolSourcesBox.Focus();
        }

        private void ClosePlaylistPool()
        {
            if (_poolOverlay == null || _poolBuildActive) return;
            _poolOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            RestoreCompactHostAfterOverlay();
            IInputElement restore = _poolReturnFocus;
            _poolReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private static string PoolShuffleModeFromUi(ComboBox combo)
        {
            string text = combo == null ? "" : Convert.ToString(combo.SelectedItem, CultureInfo.InvariantCulture);
            return String.Equals(text, "Balanced sources", StringComparison.OrdinalIgnoreCase) ? "balanced" : "global";
        }

        private static string PoolShuffleModeLabel(string mode)
        {
            return String.Equals(mode, "balanced", StringComparison.OrdinalIgnoreCase) ? "Balanced sources" : "Global random";
        }

        private static string FormatPoolSourceSpec(string url, int weight)
        {
            int w = Math.Max(1, Math.Min(9, weight));
            return (w == 1 ? "" : w.ToString(CultureInfo.InvariantCulture) + "x ") + (url ?? "");
        }

        private void LoadPlaylistPoolDraft()
        {
            try
            {
                string sourceText = "";
                Dictionary<string, object> pool = ReadJsonFresh(CurrentPoolPath);
                var sources = GetList(pool, "sources");
                if (sources.Count > 0)
                {
                    var lines = new List<string>();
                    foreach (object raw in sources)
                    {
                        var map = AsMap(raw);
                        string u = GetString(map, "url", "").Trim();
                        int weight = Math.Max(1, Math.Min(9, GetInt(map, "weight", 1)));
                        if (u.Length > 0) lines.Add(FormatPoolSourceSpec(u, weight));
                    }
                    sourceText = String.Join(Environment.NewLine, lines.ToArray());
                }
                if (sourceText.Length == 0 && File.Exists(PoolSourcesPath)) sourceText = ReadTextShared(PoolSourcesPath).Trim();
                _poolSourcesBox.Text = sourceText;
                if (_poolNameBox != null) _poolNameBox.Text = GetString(pool, "name", "Current Pool");
                _poolDeduplicateCheck.IsChecked = pool.Count == 0 || GetBool(pool, "deduplicate", true);
                if (_poolShuffleModeCombo != null) _poolShuffleModeCombo.SelectedItem = PoolShuffleModeLabel(GetString(pool, "shuffle_mode", "global"));
                int sourceCount = GetInt(pool, "source_count", sources.Count);
                int trackCount = GetInt(pool, "track_count", 0);
                _poolCurrentSummaryText.Text = trackCount > 0
                    ? sourceCount.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + trackCount.ToString("N0", CultureInfo.InvariantCulture) + " tracks  |  " + PoolShuffleModeLabel(GetString(pool, "shuffle_mode", "global"))
                    : "No Pool built yet";
                _poolStatusText.Text = "Ready.";
            }
            catch
            {
                _poolCurrentSummaryText.Text = "Pool state unavailable";
                _poolStatusText.Text = "You can still paste sources and rebuild.";
            }
        }

        private bool TryParsePoolSourceLines(out List<PoolSourceSpec> result, out string error)
        {
            result = new List<PoolSourceSpec>();
            error = "";
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string raw = _poolSourcesBox != null ? (_poolSourcesBox.Text ?? "") : "";
            int lineNumber = 0;
            foreach (string line0 in raw.Replace("\r", "").Split('\n'))
            {
                lineNumber++;
                string line = (line0 ?? "").Trim();
                if (line.Length == 0) continue;
                int weight = 1;
                string urlText = line;
                int space = line.IndexOf(' ');
                if (space > 0)
                {
                    string token = line.Substring(0, space).Trim();
                    if (token.EndsWith("x", StringComparison.OrdinalIgnoreCase))
                    {
                        int parsed;
                        if (!Int32.TryParse(token.Substring(0, token.Length - 1), NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed) || parsed < 1 || parsed > 9)
                        {
                            error = "Line " + lineNumber.ToString(CultureInfo.InvariantCulture) + ": source weight must be 1x through 9x.";
                            return false;
                        }
                        weight = parsed;
                        urlText = line.Substring(space + 1).Trim();
                    }
                }
                Uri uri;
                if (!Uri.TryCreate(urlText, UriKind.Absolute, out uri) || (uri.Scheme != Uri.UriSchemeHttp && uri.Scheme != Uri.UriSchemeHttps))
                {
                    error = "Line " + lineNumber.ToString(CultureInfo.InvariantCulture) + ": expected a YouTube http/https URL" + (weight != 1 ? " after the weight." : ".");
                    return false;
                }
                if (seen.Add(urlText)) result.Add(new PoolSourceSpec { Url = urlText, Weight = weight });
            }
            if (result.Count == 0)
            {
                error = "Paste at least one valid http/https playlist or video URL.";
                return false;
            }
            return true;
        }

        private string CurrentPoolName()
        {
            string name = _poolNameBox == null ? "" : (_poolNameBox.Text ?? "").Trim();
            return name.Length == 0 ? "Current Pool" : name;
        }

        private string PoolDefinitionPath(string name)
        {
            string key = Sha256Hex((name ?? "").Trim().ToLowerInvariant());
            return Path.Combine(SavedPoolsDirectory, key.Substring(0, 24) + ".json");
        }

        private Dictionary<string, object> MakePoolDefinition(string name, bool deduplicate, string shuffleMode, IEnumerable<PoolSourceSpec> specs)
        {
            var sourceMaps = new List<object>();
            foreach (PoolSourceSpec spec in specs)
                sourceMaps.Add(new Dictionary<string, object> { { "url", spec.Url }, { "weight", spec.Weight } });
            return new Dictionary<string, object>
            {
                { "schema", 1 }, { "name", name }, { "updated_utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) },
                { "deduplicate", deduplicate }, { "shuffle_mode", shuffleMode }, { "sources", sourceMaps }
            };
        }

        private void RefreshSavedPoolList(string selectName)
        {
            if (_poolSavedCombo == null) return;
            string prior = selectName;
            if (String.IsNullOrWhiteSpace(prior)) prior = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            var names = new List<string>();
            try
            {
                Directory.CreateDirectory(SavedPoolsDirectory);
                foreach (string path in Directory.GetFiles(SavedPoolsDirectory, "*.json"))
                {
                    Dictionary<string, object> map = ReadJsonFresh(path);
                    string name = GetString(map, "name", "").Trim();
                    if (name.Length > 0 && !names.Contains(name, StringComparer.OrdinalIgnoreCase)) names.Add(name);
                }
            }
            catch { }
            names.Sort(StringComparer.CurrentCultureIgnoreCase);
            _poolSavedCombo.Items.Clear();
            foreach (string name in names) _poolSavedCombo.Items.Add(name);
            if (!String.IsNullOrWhiteSpace(prior))
            {
                string match = names.FirstOrDefault(x => String.Equals(x, prior, StringComparison.OrdinalIgnoreCase));
                if (match != null) _poolSavedCombo.SelectedItem = match;
            }
            if (_poolSavedCombo.SelectedIndex < 0 && names.Count > 0) _poolSavedCombo.SelectedIndex = 0;
        }

        private void SavePlaylistPoolDefinition()
        {
            if (_poolBuildActive) return;
            List<PoolSourceSpec> specs; string error;
            if (!TryParsePoolSourceLines(out specs, out error)) { _poolStatusText.Text = error; return; }
            string name = CurrentPoolName();
            bool deduplicate = _poolDeduplicateCheck == null || _poolDeduplicateCheck.IsChecked == true;
            string shuffleMode = PoolShuffleModeFromUi(_poolShuffleModeCombo);
            try
            {
                Directory.CreateDirectory(SavedPoolsDirectory);
                WriteUtf8NoBom(PoolDefinitionPath(name), _json.Serialize(MakePoolDefinition(name, deduplicate, shuffleMode, specs)));
                RefreshSavedPoolList(name);
                _poolStatusText.Text = "Saved '" + name + "'. Building it later re-resolves the playlists, so newly added tracks can join the next shuffle.";
                ShowToast("Pool saved", name);
            }
            catch (Exception ex) { _poolStatusText.Text = "Could not save Pool: " + ex.Message; }
        }

        private void ApplyPoolDefinition(Dictionary<string, object> map)
        {
            if (map == null || map.Count == 0) throw new InvalidOperationException("Saved Pool is empty or unreadable.");
            string name = GetString(map, "name", "Current Pool");
            var lines = new List<string>();
            foreach (object raw in GetList(map, "sources"))
            {
                var source = AsMap(raw);
                string url = GetString(source, "url", "").Trim();
                if (url.Length == 0) continue;
                lines.Add(FormatPoolSourceSpec(url, Math.Max(1, Math.Min(9, GetInt(source, "weight", 1)))));
            }
            if (lines.Count == 0) throw new InvalidOperationException("Saved Pool has no usable sources.");
            _poolNameBox.Text = name;
            _poolSourcesBox.Text = String.Join(Environment.NewLine, lines.ToArray());
            _poolDeduplicateCheck.IsChecked = GetBool(map, "deduplicate", true);
            _poolShuffleModeCombo.SelectedItem = PoolShuffleModeLabel(GetString(map, "shuffle_mode", "global"));
            _poolStatusText.Text = "Loaded '" + name + "'. Build + shuffle when you want a fresh session from these sources.";
        }

        private void LoadSelectedPlaylistPoolDefinition()
        {
            if (_poolBuildActive || _poolSavedCombo == null) return;
            string name = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            if (String.IsNullOrWhiteSpace(name)) { _poolStatusText.Text = "No saved Pool selected."; return; }
            try { ApplyPoolDefinition(ReadJsonFresh(PoolDefinitionPath(name))); }
            catch (Exception ex) { _poolStatusText.Text = "Could not load Pool: " + ex.Message; }
        }

        private void DeleteSelectedPlaylistPoolDefinition()
        {
            if (_poolBuildActive || _poolSavedCombo == null) return;
            string name = Convert.ToString(_poolSavedCombo.SelectedItem, CultureInfo.InvariantCulture);
            if (String.IsNullOrWhiteSpace(name)) { _poolStatusText.Text = "No saved Pool selected."; return; }
            MessageBoxResult answer = MessageBox.Show(_window, "Delete the saved Pool definition '" + name + "'?\r\n\r\nThis does not delete cached media or the currently playing session.", "Delete Pool", MessageBoxButton.YesNo, MessageBoxImage.Question);
            if (answer != MessageBoxResult.Yes) return;
            try
            {
                string path = PoolDefinitionPath(name);
                if (File.Exists(path)) File.Delete(path);
                RefreshSavedPoolList(null);
                _poolStatusText.Text = "Deleted saved Pool '" + name + "'.";
            }
            catch (Exception ex) { _poolStatusText.Text = "Could not delete Pool: " + ex.Message; }
        }

        private void SetPoolBuildUi(bool active, string status)
        {
            _poolBuildActive = active;
            if (_poolBuildButton != null) { _poolBuildButton.IsEnabled = !active; _poolBuildButton.Content = active ? "Building..." : "Build + shuffle"; }
            if (_poolCloseButton != null) _poolCloseButton.IsEnabled = !active;
            if (_poolSourcesBox != null) _poolSourcesBox.IsReadOnly = active;
            if (_poolNameBox != null) _poolNameBox.IsReadOnly = active;
            if (_poolDeduplicateCheck != null) _poolDeduplicateCheck.IsEnabled = !active;
            if (_poolShuffleModeCombo != null) _poolShuffleModeCombo.IsEnabled = !active;
            if (_poolSavedCombo != null) _poolSavedCombo.IsEnabled = !active;
            if (_poolSaveButton != null) _poolSaveButton.IsEnabled = !active;
            if (_poolLoadButton != null) _poolLoadButton.IsEnabled = !active;
            if (_poolDeleteButton != null) _poolDeleteButton.IsEnabled = !active;
            if (_poolStatusText != null && !String.IsNullOrWhiteSpace(status)) _poolStatusText.Text = status;
        }

        private void PoolProgress(string text)
        {
            try
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    if (_poolStatusText != null) _poolStatusText.Text = text ?? "";
                }));
            }
            catch { }
        }

        private static string PoolCanonicalUrl(Dictionary<string, object> entry, string sourceUrl)
        {
            string id = GetString(entry, "id", "").Trim();
            string webpage = GetString(entry, "webpage_url", "").Trim();
            if (webpage.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || webpage.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) return webpage;
            string raw = GetString(entry, "url", "").Trim();
            if (raw.StartsWith("http://", StringComparison.OrdinalIgnoreCase) || raw.StartsWith("https://", StringComparison.OrdinalIgnoreCase)) return raw;
            if (id.Length > 0 && sourceUrl.IndexOf("youtu", StringComparison.OrdinalIgnoreCase) >= 0) return "https://www.youtube.com/watch?v=" + id;
            return raw;
        }

        private static string PoolTrackKey(string id, string url)
        {
            if (!String.IsNullOrWhiteSpace(id)) return "id:" + id.Trim().ToLowerInvariant();
            return "url:" + (url ?? "").Trim();
        }

        private static void ShufflePoolTracks(List<PoolTrackBuild> tracks, int seed)
        {
            var random = new Random(seed);
            for (int i = tracks.Count - 1; i > 0; i--)
            {
                int j = random.Next(i + 1);
                PoolTrackBuild temp = tracks[i]; tracks[i] = tracks[j]; tracks[j] = temp;
            }
        }

        private static void ShufflePoolTracksBalanced(List<PoolTrackBuild> tracks, List<PoolSourceBuild> sources, int seed)
        {
            var random = new Random(seed);
            var sourceByIndex = sources.ToDictionary(x => x.Index, x => x);
            var buckets = new Dictionary<int, List<PoolTrackBuild>>();
            foreach (PoolSourceBuild source in sources) buckets[source.Index] = new List<PoolTrackBuild>();

            var assignment = new List<PoolTrackBuild>(tracks);
            ShufflePoolTracks(assignment, seed ^ 0x51A7B11);
            foreach (PoolTrackBuild track in assignment)
            {
                int chosen = 0;
                double bestLoad = Double.MaxValue;
                foreach (int index in track.SourceIndexes)
                {
                    PoolSourceBuild src;
                    List<PoolTrackBuild> bucket;
                    if (!sourceByIndex.TryGetValue(index, out src) || !buckets.TryGetValue(index, out bucket)) continue;
                    double load = (double)bucket.Count / Math.Max(1, src.Weight);
                    if (load < bestLoad - 0.000001 || (Math.Abs(load - bestLoad) < 0.000001 && random.Next(2) == 0))
                    {
                        bestLoad = load;
                        chosen = index;
                    }
                }
                if (chosen == 0 && sources.Count > 0) chosen = sources[0].Index;
                buckets[chosen].Add(track);
            }
            foreach (List<PoolTrackBuild> bucket in buckets.Values) ShufflePoolTracks(bucket, random.Next());

            var credits = new Dictionary<int, int>();
            foreach (PoolSourceBuild source in sources) credits[source.Index] = random.Next(Math.Max(1, source.Weight));
            var mixed = new List<PoolTrackBuild>(tracks.Count);
            while (mixed.Count < tracks.Count)
            {
                int totalWeight = 0;
                foreach (PoolSourceBuild source in sources) if (buckets[source.Index].Count > 0) totalWeight += Math.Max(1, source.Weight);
                if (totalWeight <= 0) break;
                PoolSourceBuild chosen = null;
                int bestCredit = Int32.MinValue;
                foreach (PoolSourceBuild source in sources)
                {
                    if (buckets[source.Index].Count == 0) continue;
                    credits[source.Index] += Math.Max(1, source.Weight);
                    int credit = credits[source.Index];
                    if (chosen == null || credit > bestCredit || (credit == bestCredit && random.Next(2) == 0))
                    {
                        chosen = source;
                        bestCredit = credit;
                    }
                }
                if (chosen == null) break;
                credits[chosen.Index] -= totalWeight;
                List<PoolTrackBuild> selectedBucket = buckets[chosen.Index];
                int last = selectedBucket.Count - 1;
                mixed.Add(selectedBucket[last]);
                selectedBucket.RemoveAt(last);
            }
            if (mixed.Count == tracks.Count)
            {
                tracks.Clear();
                tracks.AddRange(mixed);
            }
        }

        private void BuildPlaylistPool()
        {
            if (_poolBuildActive) return;
            List<PoolSourceSpec> sourceSpecs; string parseError;
            if (!TryParsePoolSourceLines(out sourceSpecs, out parseError))
            {
                _poolStatusText.Text = parseError;
                return;
            }
            bool deduplicate = _poolDeduplicateCheck == null || _poolDeduplicateCheck.IsChecked == true;
            string shuffleMode = PoolShuffleModeFromUi(_poolShuffleModeCombo);
            string poolName = CurrentPoolName();
            string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
            if (!File.Exists(yt))
            {
                _poolStatusText.Text = "yt-dlp is missing from the YOMI runtime.";
                return;
            }
            SetPoolBuildUi(true, "Resolving " + sourceSpecs.Count.ToString(CultureInfo.InvariantCulture) + " source" + (sourceSpecs.Count == 1 ? "..." : "s..."));
            PoolSourceSpec[] sourceSnapshot = sourceSpecs.ToArray();
            ThreadPool.QueueUserWorkItem(delegate
            {
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                var sources = new List<PoolSourceBuild>();
                var tracks = new List<PoolTrackBuild>();
                var unique = new Dictionary<string, PoolTrackBuild>(StringComparer.OrdinalIgnoreCase);
                string failure = "";
                int rawTrackCount = 0;
                try
                {
                    for (int sourceIndex = 0; sourceIndex < sourceSnapshot.Length; sourceIndex++)
                    {
                        PoolSourceSpec spec = sourceSnapshot[sourceIndex];
                        string sourceUrl = spec.Url;
                        PoolProgress("Resolving source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " / " + sourceSnapshot.Length.ToString(CultureInfo.InvariantCulture) + "...");
                        var source = new PoolSourceBuild { Index = sourceIndex + 1, Url = sourceUrl, Weight = spec.Weight, Label = "Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) };
                        string deno = Path.Combine(_runtimeRoot, "deno", "deno.exe");
                        string args = "--flat-playlist --ignore-errors --quiet --no-warnings --dump-json --cache-dir " + Quote(YtDlpCacheDirectory());
                        if (File.Exists(deno)) args += " --js-runtimes " + Quote("deno:" + deno);
                        args += " " + Quote(sourceUrl);
                        var lines = new List<string>();
                        var errors = new List<string>();
                        var psi = new ProcessStartInfo
                        {
                            FileName = yt,
                            Arguments = args,
                            WorkingDirectory = _dataRoot,
                            UseShellExecute = false,
                            CreateNoWindow = true,
                            WindowStyle = ProcessWindowStyle.Hidden,
                            RedirectStandardOutput = true,
                            RedirectStandardError = true
                        };
                        ConfigureYtDlpProcessStartInfo(psi);
                        using (var proc = new Process { StartInfo = psi })
                        {
                            proc.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (lines) lines.Add(e.Data); };
                            proc.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e) { if (!String.IsNullOrWhiteSpace(e.Data)) lock (errors) errors.Add(e.Data); };
                            if (!proc.Start()) throw new InvalidOperationException("Windows could not start yt-dlp.");
                            try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                            proc.BeginOutputReadLine(); proc.BeginErrorReadLine();
                            if (!proc.WaitForExit(180000)) { try { proc.Kill(); } catch { } throw new TimeoutException("Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " timed out."); }
                            try { proc.WaitForExit(); } catch { }
                            if (proc.ExitCode != 0 && lines.Count == 0)
                            {
                                string detail = errors.Count > 0 ? errors[errors.Count - 1] : "yt-dlp returned exit code " + proc.ExitCode.ToString(CultureInfo.InvariantCulture);
                                throw new InvalidOperationException("Source " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " failed: " + detail);
                            }
                        }
                        string[] snapshot; lock (lines) snapshot = lines.ToArray();
                        foreach (string line in snapshot)
                        {
                            Dictionary<string, object> entry;
                            try { entry = AsMap(serializer.DeserializeObject(line)); } catch { continue; }
                            if (entry.Count == 0) continue;
                            string id = GetString(entry, "id", "").Trim();
                            string url = PoolCanonicalUrl(entry, sourceUrl);
                            if (String.IsNullOrWhiteSpace(url)) continue;
                            string playlistTitle = GetString(entry, "playlist_title", GetString(entry, "playlist", "")).Trim();
                            if (!String.IsNullOrWhiteSpace(playlistTitle) && source.Label.StartsWith("Source ", StringComparison.Ordinal)) source.Label = playlistTitle;
                            var candidate = new PoolTrackBuild
                            {
                                Url = url,
                                Id = id,
                                Title = GetString(entry, "title", "").Trim(),
                                Channel = GetString(entry, "channel", GetString(entry, "uploader", "")).Trim(),
                                Duration = GetDouble(entry, "duration", 0)
                            };
                            string key = PoolTrackKey(candidate.Id, candidate.Url);
                            rawTrackCount++;
                            PoolTrackBuild existing;
                            if (deduplicate && unique.TryGetValue(key, out existing))
                            {
                                if (!existing.SourceIndexes.Contains(source.Index))
                                {
                                    existing.SourceIndexes.Add(source.Index);
                                    existing.SourceLabels.Add(source.Label);
                                }
                            }
                            else
                            {
                                candidate.SourceIndexes.Add(source.Index);
                                candidate.SourceLabels.Add(source.Label);
                                tracks.Add(candidate);
                                if (deduplicate) unique[key] = candidate;
                            }
                            source.Extracted++;
                        }
                        sources.Add(source);
                        PoolProgress("Resolved " + (sourceIndex + 1).ToString(CultureInfo.InvariantCulture) + " / " + sourceSnapshot.Length.ToString(CultureInfo.InvariantCulture) + "  |  " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " playable tracks");
                    }
                    if (tracks.Count == 0) throw new InvalidOperationException("The Pool resolved zero playable tracks.");
                    foreach (PoolTrackBuild track in tracks)
                    {
                        for (int i = 0; i < track.SourceIndexes.Count; i++)
                        {
                            int index = track.SourceIndexes[i];
                            PoolSourceBuild src = sources.FirstOrDefault(x => x.Index == index);
                            if (src != null && i < track.SourceLabels.Count) track.SourceLabels[i] = src.Label;
                        }
                    }
                    int seed = BitConverter.ToInt32(Guid.NewGuid().ToByteArray(), 0) & Int32.MaxValue;
                    if (String.Equals(shuffleMode, "balanced", StringComparison.OrdinalIgnoreCase)) ShufflePoolTracksBalanced(tracks, sources, seed);
                    else ShufflePoolTracks(tracks, seed);
                    var sourceMaps = new List<object>();
                    foreach (PoolSourceBuild source in sources)
                    {
                        sourceMaps.Add(new Dictionary<string, object> { { "index", source.Index }, { "url", source.Url }, { "label", source.Label }, { "weight", source.Weight }, { "extracted_count", source.Extracted } });
                    }
                    var trackMaps = new List<object>();
                    for (int i = 0; i < tracks.Count; i++)
                    {
                        PoolTrackBuild track = tracks[i];
                        trackMaps.Add(new Dictionary<string, object>
                        {
                            { "position", i + 1 }, { "url", track.Url }, { "id", track.Id }, { "title", track.Title }, { "channel", track.Channel }, { "duration", track.Duration },
                            { "source_indexes", track.SourceIndexes.Cast<object>().ToList() }, { "source_labels", track.SourceLabels.Cast<object>().ToList() }
                        });
                    }
                    var poolMap = new Dictionary<string, object>
                    {
                        { "schema", 2 }, { "name", poolName }, { "built_utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) },
                        { "deduplicate", deduplicate }, { "shuffle_mode", shuffleMode }, { "shuffle_seed", seed }, { "source_count", sources.Count }, { "raw_track_count", rawTrackCount }, { "track_count", tracks.Count },
                        { "sources", sourceMaps }, { "tracks", trackMaps }
                    };
                    Directory.CreateDirectory(_dataRoot); Directory.CreateDirectory(_stateRoot);
                    string playlistPath = Path.Combine(_dataRoot, "playlist.txt");
                    bool oldSourcesExists = File.Exists(PoolSourcesPath), oldPoolExists = File.Exists(CurrentPoolPath), oldPlaylistExists = File.Exists(playlistPath), oldResetExists = File.Exists(PoolResetPath);
                    string oldSources = oldSourcesExists ? ReadTextShared(PoolSourcesPath) : "";
                    string oldPool = oldPoolExists ? ReadTextShared(CurrentPoolPath) : "";
                    string oldPlaylist = oldPlaylistExists ? ReadTextShared(playlistPath) : "";
                    string oldReset = oldResetExists ? ReadTextShared(PoolResetPath) : "";
                    try
                    {
                        WriteUtf8NoBom(PoolSourcesPath, String.Join(Environment.NewLine, sourceSnapshot.Select(x => FormatPoolSourceSpec(x.Url, x.Weight)).ToArray()) + Environment.NewLine);
                        WriteUtf8NoBom(CurrentPoolPath, serializer.Serialize(poolMap));
                        WriteUtf8NoBom(playlistPath, String.Join(Environment.NewLine, tracks.Select(t => t.Url).ToArray()) + Environment.NewLine);
                        _expectedPlaylistCount = 0;
                        WriteUtf8NoBom(PoolResetPath, DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture));
                    }
                    catch
                    {
                        RestoreFileSnapshot(PoolSourcesPath, oldSourcesExists, oldSources);
                        RestoreFileSnapshot(CurrentPoolPath, oldPoolExists, oldPool);
                        RestoreFileSnapshot(playlistPath, oldPlaylistExists, oldPlaylist);
                        RestoreFileSnapshot(PoolResetPath, oldResetExists, oldReset);
                        throw;
                    }
                    int duplicateCount = Math.Max(0, rawTrackCount - tracks.Count);
                    TryBeginInvokeUi(DispatcherPriority.Normal, delegate
                    {
                        string modeLabel = PoolShuffleModeLabel(shuffleMode);
                        SetPoolBuildUi(false, "Built " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks from " + sources.Count.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + modeLabel + (duplicateCount > 0 ? "  |  " + duplicateCount.ToString("N0", CultureInfo.InvariantCulture) + " duplicates collapsed" : "") + ".");
                        _poolCurrentSummaryText.Text = poolName + "  |  " + sources.Count.ToString("N0", CultureInfo.InvariantCulture) + " sources  |  " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks  |  " + modeLabel;
                        MarkActiveSlotSourceChanged("Pool");
                        AddActivity("Playlist Pool", "built " + tracks.Count.ToString(CultureInfo.InvariantCulture) + " tracks from " + sources.Count.ToString(CultureInfo.InvariantCulture) + " sources");
                        ShowToast("Playlist Pool ready", modeLabel + ": " + tracks.Count.ToString("N0", CultureInfo.InvariantCulture) + " tracks.");
                        if (_running)
                        {
                            MessageBoxResult restart = MessageBox.Show(_window,
                                "The Pool is built. Restart YOMI playback now so the new mix becomes authoritative?\r\n\r\nCurrent playback keeps running until you choose to switch.",
                                "Activate Playlist Pool", MessageBoxButton.YesNo, MessageBoxImage.Question);
                            if (restart == MessageBoxResult.Yes) RestartPlaybackForPool();
                            else _poolStatusText.Text += " Current playback is unchanged; restart when you want to activate it.";
                        }
                        else
                        {
                            _poolStatusText.Text += " Press Play to start it.";
                        }
                    });
                }
                catch (Exception ex)
                {
                    failure = ex.Message;
                    TryBeginInvokeUi(DispatcherPriority.Normal, delegate
                    {
                        SetPoolBuildUi(false, "Could not build Pool: " + failure);
                        ShowToast("Playlist Pool", "Build failed. Your current playlist was left unchanged.");
                    });
                }
            });
        }

        private static void RestoreFileSnapshot(string path, bool existed, string content)
        {
            try
            {
                if (existed) WriteUtf8NoBom(path, content ?? "");
                else if (File.Exists(path)) File.Delete(path);
            }
            catch { }
        }

        private void RestartPlaybackForPool()
        {
            if (!_running) { StartEngine(); return; }
            _poolStatusText.Text = "Activating Pool...";
            if (!StopOwnedYomiRuntime())
            {
                _poolStatusText.Text = "Pool built, but the current runtime could not be stopped safely. Restart YOMI later to activate it.";
                return;
            }
            _running = false; _audioActive = false; _paused = false;
            _startupPrewarmReady = false;
            try { File.Delete(Path.Combine(_stateRoot, "planned-stop.pending")); } catch { }
            SafeRefresh(true);
            var restart = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(750) };
            restart.Tick += delegate
            {
                restart.Stop();
                StartEngine();
                _poolStatusText.Text = "Pool active.";
            };
            restart.Start();
        }

        private string UpdateLaneSummary()
        {
            string updateHostPath = Path.Combine(_appDir, "YomiUpdateHost.ps1");
            if (!File.Exists(updateHostPath)) return "Update packages: setup EXE only (persistent host is not installed).";
            bool associationReady = false;
            try
            {
                using (Microsoft.Win32.RegistryKey extension = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Classes\.yomiupdate"))
                using (Microsoft.Win32.RegistryKey command = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Classes\YOMI.UpdatePackage\shell\open\command"))
                {
                    string type = extension == null ? "" : Convert.ToString(extension.GetValue(""), CultureInfo.InvariantCulture);
                    string launch = command == null ? "" : Convert.ToString(command.GetValue(""), CultureInfo.InvariantCulture);
                    associationReady = String.Equals(type, "YOMI.UpdatePackage", StringComparison.OrdinalIgnoreCase) &&
                        !String.IsNullOrWhiteSpace(launch) && launch.IndexOf("YomiUpdateHost.ps1", StringComparison.OrdinalIgnoreCase) >= 0;
                }
            }
            catch { }
            return associationReady
                ? "Update packages: ready in YOMI and by .yomiupdate double-click."
                : "Update packages: double-click association is not registered; use the updater host or setup package.";
        }

        private string InstalledFocusedBuildSummary()
        {
            // R61.86: About reads the same promoted build marker the installer writes.
            // A stale hard-coded revision can therefore never disagree with the installed bytes again.
            try
            {
                string marker = Path.Combine(_appDir, "FOCUSED-BUILD.txt");
                if (File.Exists(marker))
                {
                    string[] markerLines = File.ReadAllLines(marker);
                    for (int i = markerLines.Length - 1; i >= 0; i--)
                    {
                        string line = (markerLines[i] ?? "").Trim();
                        if (line.Length > 0) return line;
                    }
                }
            }
            catch { }
            return "Optical Ergonomics + Interaction Hierarchy R61.96";
        }

        private void ShowAboutYomi()
        {
            string text =
                "YOMI 4.2.0.9.9.1 - YouTube OBS Music Interface\r\n" +
                "Focused build: " + InstalledFocusedBuildSummary() + "\r\n" +
                UpdateLaneSummary() + "\r\n\r\n" +
                "A music player built for lightweight YouTube playback and OBS presentation.";
            MessageBox.Show(_window, text, "About YOMI 4.2.0.9.9.1", MessageBoxButton.OK, MessageBoxImage.Information);
        }

