        private void StartPublicUpdaterHidden()
        {
            try
            {
                string publicUpdater = Path.Combine(_appDir, "update.ps1");
                if (!File.Exists(publicUpdater)) { BuildYomiStatusDialog("Updates", "The public updater is not present in this installation.", null, null).ShowDialog(); return; }
                string powershell = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows), "System32", "WindowsPowerShell", "v1.0", "powershell.exe");
                var psi = new ProcessStartInfo(powershell, "-NoProfile -WindowStyle Hidden -ExecutionPolicy Bypass -File " + Quote(publicUpdater) + " -Manual -Approved")
                { UseShellExecute = false, CreateNoWindow = true, WindowStyle = ProcessWindowStyle.Hidden };
                Process.Start(psi);
            }
            catch (Exception ex) { BuildYomiStatusDialog("Updates", "Could not start the updater.\r\n\r\n" + ex.Message, null, null).ShowDialog(); }
        }

        private static string NormalizeDottedVersionText(string text)
        {
            if (String.IsNullOrWhiteSpace(text)) return "0.0";
            var match = System.Text.RegularExpressions.Regex.Match(text, @"\d+(?:\.\d+)+");
            return match.Success ? match.Value : "0.0";
        }

        private static int CompareDottedVersions(string left, string right)
        {
            string[] a = NormalizeDottedVersionText(left).Split('.');
            string[] b = NormalizeDottedVersionText(right).Split('.');
            int n = Math.Max(a.Length, b.Length);
            for (int i = 0; i < n; i++)
            {
                long av = 0, bv = 0;
                if (i < a.Length) Int64.TryParse(a[i], NumberStyles.Integer, CultureInfo.InvariantCulture, out av);
                if (i < b.Length) Int64.TryParse(b[i], NumberStyles.Integer, CultureInfo.InvariantCulture, out bv);
                if (av < bv) return -1;
                if (av > bv) return 1;
            }
            return 0;
        }

        private void CheckForUpdates() { CheckForUpdates(false); }

        private void CheckForUpdates(bool automatic)
        {
            if (!automatic) ShowToast("Updates", "Checking for YOMI updates...");
            Task.Run(delegate
            {
                try
                {
                    ServicePointManager.SecurityProtocol = SecurityProtocolType.Tls12;
                    string json;
                    using (var client = new WebClient())
                    {
                        client.Headers[HttpRequestHeader.UserAgent] = "YOMI-4.2.0.9.9.1-Controller";
                        json = client.DownloadString("https://raw.githubusercontent.com/TheSensibleStreamer/YOMI-YouTube-Playlist-Randomizer/main/update.json");
                    }
                    var manifest = new JavaScriptSerializer().Deserialize<Dictionary<string, object>>(json);
                    string latestText = NormalizeDottedVersionText(GetString(manifest, "version", "0.0"));
                    string currentText = "4.2.0.9.9.1";
                    try { string versionPath = Path.Combine(_installRoot, "VERSION.txt"); if (File.Exists(versionPath)) currentText = NormalizeDottedVersionText(File.ReadAllText(versionPath).Trim()); } catch { }
                    int comparison = CompareDottedVersions(latestText, currentText);
                    _window.Dispatcher.BeginInvoke(new Action(delegate
                    {
                        if (comparison <= 0)
                        {
                            if (!automatic) BuildYomiStatusDialog("Updates", "YOMI " + currentText + " is current.\r\n\r\nNo newer public build is available.", null, null).ShowDialog();
                        }
                        else
                            BuildYomiStatusDialog("Update available", "YOMI " + latestText + " is available. You have " + currentText + ".", "Run updater", StartPublicUpdaterHidden).ShowDialog();
                    }));
                }
                catch (Exception ex)
                {
                    if (!automatic) _window.Dispatcher.BeginInvoke(new Action(delegate { BuildYomiStatusDialog("Updates", "YOMI could not check for updates.\r\n\r\n" + ex.Message, null, null).ShowDialog(); }));
                }
            });
        }

