        private static void FillCombo(ComboBox box, params string[] values)
        {
            box.Items.Clear(); foreach (string value in values) box.Items.Add(value);
        }
        private static int NormalizeVisualizerAnalysisWidth(int value)
        {
            if (value >= 300) return 340;
            if (value >= 220) return 260;
            if (value >= 130) return 180;
            return 96;
        }

        private static int NormalizeVisualizerAnalysisHeight(int value)
        {
            if (value >= 56) return 64;
            if (value >= 42) return 48;
            if (value >= 30) return 36;
            return 24;
        }

        private static string VisualizerPixelSizeChoice(int width, int height)
        {
            width = NormalizeVisualizerAnalysisWidth(width); height = NormalizeVisualizerAnalysisHeight(height);
            if (width <= 96 || height <= 24) return "Extra Chunky";
            if (width <= 180 || height <= 36) return "Chunky";
            if (width <= 260 || height <= 48) return "Fine";
            return "Extra Fine";
        }

        private static void VisualizerPixelSizeDimensions(string choice, out int width, out int height)
        {
            string value = (choice ?? "").Trim();
            if (value.Equals("Extra Chunky", StringComparison.OrdinalIgnoreCase)) { width = 96; height = 24; return; }
            if (value.Equals("Fine", StringComparison.OrdinalIgnoreCase)) { width = 260; height = 48; return; }
            if (value.Equals("Extra Fine", StringComparison.OrdinalIgnoreCase)) { width = 340; height = 64; return; }
            width = 180; height = 36;
        }

        private static string ComboItemText(object item)
        {
            ComboBoxItem styled = item as ComboBoxItem;
            if (styled != null) return Convert.ToString(styled.Content, CultureInfo.InvariantCulture) ?? "";
            return Convert.ToString(item, CultureInfo.InvariantCulture) ?? "";
        }
        private static void SetCombo(ComboBox box, string value)
        {
            if (box == null) return;
            string wanted = value ?? "";
            foreach (object item in box.Items)
            {
                if (String.Equals(ComboItemText(item), wanted, StringComparison.OrdinalIgnoreCase)) { box.SelectedItem = item; return; }
            }
            box.SelectedItem = value;
            if (box.SelectedIndex < 0 && box.Items.Count > 0) box.SelectedIndex = 0;
        }
        private static void SetComboPreserve(ComboBox box, string value)
        {
            if (box == null) return;
            string wanted = value ?? "";
            foreach (object item in box.Items)
            {
                if (String.Equals(ComboItemText(item), wanted, StringComparison.OrdinalIgnoreCase)) { box.SelectedItem = item; return; }
            }
            if (wanted.Length > 0) box.Items.Add(wanted);
            box.SelectedItem = wanted;
            if (box.SelectedIndex < 0 && box.Items.Count > 0) box.SelectedIndex = 0;
        }
        private static string ComboText(ComboBox box, string fallback)
        {
            if (box == null) return fallback;
            // Editable ComboBox.Text can lag SelectionChanged by one dispatcher turn. While the
            // popup is selecting an item, trust SelectedItem so dirty tracking and live preview
            // react immediately instead of waiting for focus to leave the control.
            if (box.IsEditable && box.IsDropDownOpen && box.SelectedItem != null) return ComboItemText(box.SelectedItem);
            string typed = box.IsEditable ? (box.Text ?? "").Trim() : "";
            if (!String.IsNullOrWhiteSpace(typed)) return typed;
            return box.SelectedItem == null ? fallback : ComboItemText(box.SelectedItem);
        }
        private static bool Checked(CheckBox box) { return box.IsChecked == true; }
        private static int NormalizeOverlayTextSize(int value)
        {
            int clamped = Math.Max(24, Math.Min(64, value));
            return Math.Max(24, Math.Min(64, (int)Math.Round(clamped / 4.0, MidpointRounding.AwayFromZero) * 4));
        }
        private static string NormalizeOverlayFontChoice(string value)
        {
            return String.Equals((value ?? "").Trim(), "Bahnschrift SemiCondensed", StringComparison.OrdinalIgnoreCase)
                ? "Bahnschrift Condensed"
                : (value ?? "").Trim();
        }
        private static int ComboInt(ComboBox box, int fallback) { int n; return Int32.TryParse(ComboText(box, fallback.ToString(CultureInfo.InvariantCulture)), NumberStyles.Integer, CultureInfo.InvariantCulture, out n) ? n : fallback; }
        private static double ComboDouble(ComboBox box, double fallback) { double n; return Double.TryParse(ComboText(box, fallback.ToString(CultureInfo.InvariantCulture)), NumberStyles.Float, CultureInfo.InvariantCulture, out n) ? n : fallback; }

        private static void PrepareSettingsComboItem(ComboBox box, ComboBoxItem item)
        {
            if (box == null || item == null) return;
            try
            {
                Style style = box.TryFindResource("SettingsComboItem") as Style;
                if (style != null) item.Style = style;
            }
            catch { }
            item.Background = Brushes.Transparent;
            item.BorderThickness = new Thickness(0);
        }

