        private static System.Windows.Media.Effects.DropShadowEffect LegibilityEffect(Color color)
        {
            double luminance = (0.2126 * color.R + 0.7152 * color.G + 0.0722 * color.B) / 255.0;
            return new System.Windows.Media.Effects.DropShadowEffect
            {
                Color = luminance > 0.55 ? Colors.Black : Colors.White,
                BlurRadius = 1.0, ShadowDepth = 0.0, Opacity = 0.92, Direction = 0
            };
        }

        private static Brush GradientChoiceBrush(string first, string second)
        {
            return GradientChoiceBrush(new[] { first, second });
        }

        private static Brush GradientChoiceBrush(string[] colors)
        {
            var brush = new LinearGradientBrush { StartPoint = new Point(0,0.5), EndPoint = new Point(1,0.5) };
            if (colors == null || colors.Length == 0) colors = new[] { "#8A8A84" };
            for (int i=0; i<colors.Length; i++)
                brush.GradientStops.Add(new GradientStop(ParseColor(colors[i]), colors.Length == 1 ? 0.0 : (double)i / (double)(colors.Length - 1)));
            brush.Freeze(); return brush;
        }

        private static void StyleChoice(FrameworkElement element, Brush foreground, Color contrastSample)
        {
            if (element == null) return;
            Control control = element as Control;
            if (control != null) control.Foreground = foreground;
            element.Effect = LegibilityEffect(contrastSample);
        }

