            {
                Color color = ParseColor(pair.Value);
                var item = new ComboBoxItem { Content = pair.Key, Tag = pair.Value, FontWeight = FontWeights.SemiBold, Foreground = new SolidColorBrush(color), Effect = LegibilityEffect(color) };
                item.Effect = LegibilityEffect(color);
                PrepareSettingsComboItem(box, item);
                box.Items.Add(item);
            }
        }

