        private static void SelectNamedColor(ComboBox box, string raw, string fallback)
        {
            if (box == null) return;
            string wanted = String.IsNullOrWhiteSpace(raw) ? fallback : raw.Trim().ToUpperInvariant();
            foreach (object obj in box.Items)
            {
                ComboBoxItem item = obj as ComboBoxItem;
                if (item != null && String.Equals(Convert.ToString(item.Tag, CultureInfo.InvariantCulture), wanted, StringComparison.OrdinalIgnoreCase))
                { box.SelectedItem = item; box.Foreground = item.Foreground; box.Effect = item.Effect; return; }
            }
            Color color;
            try { color = ParseColor(wanted); } catch { wanted = fallback; color = ParseColor(fallback); }
            var custom = new ComboBoxItem { Content = "Custom color", Tag = wanted, FontWeight = FontWeights.SemiBold, Foreground = new SolidColorBrush(color), Effect = LegibilityEffect(color) };
            PrepareSettingsComboItem(box, custom); box.Items.Add(custom); box.SelectedItem = custom; box.Foreground = custom.Foreground; box.Effect = custom.Effect;
        }

        private static void GradientPresetColors(string preset, out string first, out string second)
        {
            if (String.Equals(preset, "Ocean", StringComparison.OrdinalIgnoreCase)) { first="#00B4D8"; second="#023E8A"; return; }
            if (String.Equals(preset, "Pastel", StringComparison.OrdinalIgnoreCase)) { first="#FFAFCC"; second="#BDE0FE"; return; }
            if (String.Equals(preset, "Fire", StringComparison.OrdinalIgnoreCase)) { first="#FF3B30"; second="#FFD60A"; return; }
            if (String.Equals(preset, "Forest", StringComparison.OrdinalIgnoreCase)) { first="#2D6A4F"; second="#B7E4C7"; return; }
            if (String.Equals(preset, "Mono", StringComparison.OrdinalIgnoreCase)) { first="#6E6E68"; second="#F2F0E8"; return; }
            first="#FF6B6B"; second="#7B2CBF";
        }

