        private static string PreviewFontFamilySource(string choice)
        {
            if (String.Equals(choice, "Bahnschrift Condensed", StringComparison.OrdinalIgnoreCase) ||
                String.Equals(choice, "Bahnschrift SemiCondensed", StringComparison.OrdinalIgnoreCase)) return "Bahnschrift";
            return choice;
        }

        private static FontStretch PreviewFontStretch(string choice)
        {
            if (String.Equals(choice, "Bahnschrift Condensed", StringComparison.OrdinalIgnoreCase)) return FontStretches.Condensed;
            if (String.Equals(choice, "Bahnschrift SemiCondensed", StringComparison.OrdinalIgnoreCase)) return FontStretches.SemiCondensed;
            return FontStretches.Normal;
        }

        private void RefreshTextFontComboPreview()
        {
            if (_settingsTextFont == null) return;
            string choice = ComboText(_settingsTextFont, DefaultOverlayTextFont);
            try
            {
                _settingsTextFont.FontFamily = new FontFamily(PreviewFontFamilySource(choice));
                _settingsTextFont.FontStretch = PreviewFontStretch(choice);
            }
            catch
            {
                _settingsTextFont.FontFamily = new FontFamily("Bahnschrift");
                _settingsTextFont.FontStretch = FontStretches.Condensed;
            }
        }

        private void FillCuratedTextFontCombo(ComboBox box)
        {
            if (box == null) return;
            box.Items.Clear(); box.IsEditable = true;
            var installed = Fonts.SystemFontFamilies.Select(f => f.Source).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(x => x, StringComparer.OrdinalIgnoreCase).ToList();
            var installedSet = new HashSet<string>(installed, StringComparer.OrdinalIgnoreCase);
            var added = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

            // Bahnschrift Condensed is a face inside the Bahnschrift family. The old exact-family
            // filter deleted YOMI's own default from the picker on normal Windows installs.
            Func<string, bool> available = choice =>
                installedSet.Contains(choice) ||
                ((String.Equals(choice, "Bahnschrift Condensed", StringComparison.OrdinalIgnoreCase) ||
                  String.Equals(choice, "Bahnschrift SemiCondensed", StringComparison.OrdinalIgnoreCase)) && installedSet.Contains("Bahnschrift"));

            Action<string> add = choice =>
            {
                if (String.IsNullOrWhiteSpace(choice) || !available(choice) || !added.Add(choice)) return;
                var item = new ComboBoxItem
                {
                    Content = choice,
                    Tag = choice,
                    FontFamily = new FontFamily(PreviewFontFamilySource(choice)),
                    FontStretch = PreviewFontStretch(choice),
                    FontWeight = FontWeights.Normal
                };
                PrepareSettingsComboItem(box, item);
                box.Items.Add(item);
            };

            // Compact / understated. These are useful for long track titles, not generic office filler.
            foreach (string choice in new[]
            {
                "Bahnschrift Condensed", "Aptos Narrow", "Franklin Gothic Medium Cond", "News Gothic MT",
                "Tw Cen MT Condensed", "Gill Sans MT Condensed", "Roboto Condensed", "IBM Plex Sans Condensed",
                "Barlow Condensed", "Oswald", "Franklin Gothic Medium", "Rockwell Condensed"
            })
            {
                if (box.Items.Count >= 12) break;
                add(choice);
            }

            // Soft / cute / expressive. Reserve slots so compact fonts cannot crowd this category out.
            int playfulBefore = box.Items.Count;
            foreach (string choice in new[]
            {
                "Ink Free", "Gabriola", "MV Boli", "Forte", "Gigi", "Bradley Hand ITC",
                "Juice ITC", "Curlz MT", "Kristen ITC", "Segoe Script"
            })
            {
                if (box.Items.Count - playfulBefore >= 7) break;
                add(choice);
            }

            // Pick up only a couple of useful compact fonts the user installed independently.
            foreach (string family in installed)
            {
                if (box.Items.Count >= 18) break;
                if (family.IndexOf("Condensed", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    family.IndexOf("Narrow", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    family.IndexOf("Compressed", StringComparison.OrdinalIgnoreCase) >= 0) add(family);
            }

            if (box.Items.Count == 0)
            {
                var fallback = new ComboBoxItem
                {
                    Content = DefaultOverlayTextFont, Tag = DefaultOverlayTextFont,
                    FontFamily = new FontFamily("Bahnschrift"), FontStretch = FontStretches.Condensed
                };
                PrepareSettingsComboItem(box, fallback);
                box.Items.Add(fallback);
            }
        }

