            _settingsTabs.SelectionChanged += delegate(object sender, SelectionChangedEventArgs e) { if (Object.ReferenceEquals(e.OriginalSource, _settingsTabs)) { UpdateSettingsContextBand(); ScheduleSettingsSectionCartography(); } };
            _settingsEverydayScroll.ScrollChanged += delegate { UpdateSettingsSectionCartography(); };
            _settingsBroadcastScroll.ScrollChanged += delegate { UpdateSettingsSectionCartography(); };
            _settingsPerformanceScroll.ScrollChanged += delegate { UpdateSettingsSectionCartography(); };
