            _settingsBroadcastCustomizeExpander.Collapsed += delegate { ScheduleSettingsSectionCartography(); };
            _settingsPerformanceAdvancedExpander.Expanded += delegate { ScheduleSettingsSectionCartography(); };
            _settingsPerformanceAdvancedExpander.Collapsed += delegate { ScheduleSettingsSectionCartography(); };
