            _settingsUndoButton.Click += delegate { UndoSettingsDraft(); };
            _settingsRedoButton.Click += delegate { RedoSettingsDraft(); };
            _settingsResetButton.Click += delegate { RestoreDefaultSettingsDraft(); };
            _settingsOverlay.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if ((Keyboard.Modifiers & ModifierKeys.Control) != 0 && e.Key == Key.Z)
                {
                    if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0) RedoSettingsDraft(); else UndoSettingsDraft();
                    e.Handled = true;
                }
                else if ((Keyboard.Modifiers & ModifierKeys.Control) != 0 && e.Key == Key.Y)
                {
                    RedoSettingsDraft(); e.Handled = true;
                }
            };
            // R61.50: Settings is an explicit workspace. ComboBox items live in a WPF Popup
            // outside the card visual tree, so backdrop-dismiss can mistake a real setting
            // selection for an outside click and close the whole surface. Close/Esc are authoritative.
            WireSettingsDirtyTracking();
        }

        private void WireSettingsDirtyTracking()
        {
            ComboBox[] combos = new[] { _settingsAppMode, _settingsHistoryMax, _settingsAudioQuality, _settingsPlayerVideoQuality, _settingsTransitionPolicy, _settingsOverlayVideoQuality, _settingsVideoFps, _settingsCanvasWidth, _settingsCanvasHeight, _settingsMediaWidth, _settingsMediaHeight, _settingsSafeMargin, _settingsBroadcastPreset, _settingsOutput1Modules, _settingsOutput1Layout, _settingsOutput2Modules, _settingsOutput2Layout, _settingsOutput3Modules, _settingsOutput3Layout, _settingsOutput4Modules, _settingsOutput4Layout, _settingsTextSize, _settingsMinTextSize, _settingsTextGap, _settingsTextFont, _settingsTextColor, _settingsTextOutline, _settingsOutlineColor, _settingsTextOpacity, _settingsTextAlignment, _settingsTextSpacing, _settingsMediaBorderPx, _settingsMediaBorderColor, _settingsMediaCornerStyle, _settingsVisualizerFill, _settingsVisualizerActivity, _settingsVisualizerOpacity, _settingsVisualizerColorMode, _settingsVisualizerSolidColor, _settingsVisualizerGradientPreset, _settingsVisualizerGradientOrientation, _settingsVisualizerPixelSize, _settingsVisualizerFrequencyScale, _settingsVisualizerTrim, _settingsVisualizerLift, _settingsVisualizerShape, _settingsVisualizerSpacing, _settingsVisualizerFps, _settingsVisualizerLength, _settingsVisualizerDirection, _settingsVisualizerAnchor, _settingsVisualizerLayer, _settingsPrefetch, _settingsVideoPrefetch, _settingsCacheWorkers, _settingsBrowserFps, _settingsVisualizerInternalWidth, _settingsVisualizerInternalHeight, _settingsWorkspace, _settingsTheme, _settingsThemeIntensity, _settingsThemeAccent, _settingsThemeBlend, _settingsDetail };
            foreach (ComboBox combo in combos)
            {
                ComboBox watched = combo;
                watched.SelectionChanged += delegate
                {
                    if (watched.IsEditable)
                        watched.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate { MarkSettingsDirty("Unsaved changes."); }));
                    else MarkSettingsDirty("Unsaved changes.");
                };
                if (watched.IsEditable) watched.LostKeyboardFocus += delegate { MarkSettingsDirty("Unsaved changes."); };
                watched.PreviewMouseWheel += SettingsComboPreviewMouseWheel;
            }
            CheckBox[] checks = new[] { _settingsHistoryEnabled, _settingsLoudness, _settingsArtwork, _settingsVideo, _settingsTitle, _settingsChannel, _settingsSmartArtworkCrop, _settingsAutoFitText, _settingsTextGlow, _settingsMediaBorderEnabled, _settingsVisualizerEnabled, _settingsVisualizerMatchText, _settingsObsMediaCache, _settingsDirectorMode, _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled, _settingsClassicMenu, _settingsReduceMotion };
            foreach (CheckBox check in checks)
            {
                check.Checked += delegate { MarkSettingsDirty("Unsaved changes."); };
                check.Unchecked += delegate { MarkSettingsDirty("Unsaved changes."); };
            }
            foreach (Slider slider in SettingsDraftSliders())
                if (slider != null) slider.ValueChanged += delegate { if (!_settingsPopulating) { UpdateSettingsSliderLabels(); MarkSettingsDirty("Unsaved changes."); } };
        }

        private void SettingsComboPreviewMouseWheel(object sender, MouseWheelEventArgs e)
        {
            ComboBox combo = sender as ComboBox;
            if (combo == null || _settingsPopulating || combo.IsDropDownOpen || combo.Items.Count <= 0 || e.Delta == 0) return;
            int current = combo.SelectedIndex;
            if (current < 0) current = 0;
            int next = Math.Max(0, Math.Min(combo.Items.Count - 1, current + (e.Delta > 0 ? -1 : 1)));
            if (next == current) return;
            combo.SelectedIndex = next;
            e.Handled = true;
        }

        private string SettingsLivePreviewPath() { return Path.Combine(_stateRoot, "settings-live-preview.json"); }

        private void ClearSettingsLivePreview()
        {
            try { if (_settingsLivePreviewTimer != null) _settingsLivePreviewTimer.Stop(); } catch { }
            try { string path = SettingsLivePreviewPath(); if (File.Exists(path)) File.Delete(path); } catch { }
        }

        private void ScheduleSettingsLivePreview()
        {
            if (_settingsPopulating || _settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible || _settingsLivePreviewTimer == null) return;
            _settingsLivePreviewTimer.Stop();
            _settingsLivePreviewTimer.Start();
        }

        private void PublishSettingsLivePreview()
        {
            if (_settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible) { ClearSettingsLivePreview(); return; }
            try
            {
                Dictionary<string, object> preview = GetObsQuickSetupConfig();
                Directory.CreateDirectory(_stateRoot);
                string path = SettingsLivePreviewPath();
                string temp = path + ".tmp";
                WriteUtf8NoBom(temp, _json.Serialize(preview));
                try
                {
                    if (File.Exists(path)) File.Replace(temp, path, null, true);
                    else File.Move(temp, path);
                }
                catch
                {
                    File.Copy(temp, path, true);
                    try { File.Delete(temp); } catch { }
                }
            }
            catch { }
        }

        private void MarkSettingsDirty(string message)
        {
            if (_settingsPopulating || _settingsHistoryApplying) return;
            RecordSettingsDraftChange();
            string current = CaptureSettingsDraft();
            _settingsDirty = !String.Equals(current, _settingsBaselineSnapshot, StringComparison.Ordinal);
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = _settingsDirty;
            if (_settingsStatusText != null) _settingsStatusText.Text = _settingsDirty ? message : "Back to the saved settings.";
            UpdateSettingsHistoryButtons();
            ScheduleSettingsLivePreview();
            // Draft edits are geometry-neutral in the Settings shell. OBS consumes a debounced
            // transient config file, so visual choices preview without committing config.json.
            // The setup card itself is not rebuilt on every tick, avoiding a one-frame resize/flash.
        }

        private ComboBox[] SettingsDraftCombos()
        {
            return new[] { _settingsAppMode, _settingsHistoryMax, _settingsAudioQuality, _settingsPlayerVideoQuality, _settingsTransitionPolicy, _settingsOverlayVideoQuality, _settingsVideoFps, _settingsCanvasWidth, _settingsCanvasHeight, _settingsMediaWidth, _settingsMediaHeight, _settingsSafeMargin, _settingsBroadcastPreset, _settingsOutput1Modules, _settingsOutput1Layout, _settingsOutput2Modules, _settingsOutput2Layout, _settingsOutput3Modules, _settingsOutput3Layout, _settingsOutput4Modules, _settingsOutput4Layout, _settingsTextSize, _settingsMinTextSize, _settingsTextGap, _settingsTextFont, _settingsTextColor, _settingsTextOutline, _settingsOutlineColor, _settingsTextOpacity, _settingsTextAlignment, _settingsTextSpacing, _settingsMediaBorderPx, _settingsMediaBorderColor, _settingsMediaCornerStyle, _settingsVisualizerFill, _settingsVisualizerActivity, _settingsVisualizerOpacity, _settingsVisualizerColorMode, _settingsVisualizerSolidColor, _settingsVisualizerGradientPreset, _settingsVisualizerGradientOrientation, _settingsVisualizerPixelSize, _settingsVisualizerFrequencyScale, _settingsVisualizerTrim, _settingsVisualizerLift, _settingsVisualizerShape, _settingsVisualizerSpacing, _settingsVisualizerFps, _settingsVisualizerLength, _settingsVisualizerDirection, _settingsVisualizerAnchor, _settingsVisualizerLayer, _settingsPrefetch, _settingsVideoPrefetch, _settingsCacheWorkers, _settingsBrowserFps, _settingsVisualizerInternalWidth, _settingsVisualizerInternalHeight, _settingsWorkspace, _settingsTheme, _settingsThemeIntensity, _settingsThemeAccent, _settingsThemeBlend, _settingsDetail };
        }

        private CheckBox[] SettingsDraftChecks()
        {
            return new[] { _settingsHistoryEnabled, _settingsLoudness, _settingsArtwork, _settingsVideo, _settingsTitle, _settingsChannel, _settingsSmartArtworkCrop, _settingsAutoFitText, _settingsTextGlow, _settingsMediaBorderEnabled, _settingsVisualizerEnabled, _settingsVisualizerMatchText, _settingsObsMediaCache, _settingsDirectorMode, _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled, _settingsClassicMenu, _settingsReduceMotion };
        }

        private Slider[] SettingsDraftSliders()
        {
            return new[] { _settingsThemeIntensitySlider, _settingsThemeBlendSlider, _settingsWindowTransparencySlider, _settingsPrefetchSlider, _settingsCacheBudgetSlider, _settingsCacheWorkersSlider };
        }

        private string CaptureSettingsDraft()
        {
            try
            {
                var map = new SortedDictionary<string, object>(StringComparer.Ordinal);
                foreach (ComboBox combo in SettingsDraftCombos()) if (combo != null) map["combo:" + combo.Name] = ComboText(combo, "");
                foreach (CheckBox check in SettingsDraftChecks()) if (check != null) map["check:" + check.Name] = check.IsChecked == true;
                foreach (Slider slider in SettingsDraftSliders()) if (slider != null) map["slider:" + slider.Name] = Math.Round(slider.Value, 2);
                return _json.Serialize(map);
            }
            catch { return ""; }
        }

        private void PushSettingsHistory(Stack<string> stack, string snapshot)
        {
            if (stack == null || String.IsNullOrEmpty(snapshot)) return;
            if (stack.Count >= SettingsHistoryLimit)
            {
                string[] newestFirst = stack.ToArray();
                stack.Clear();
                foreach (string item in newestFirst.Take(SettingsHistoryLimit - 1).Reverse()) stack.Push(item);
            }
            stack.Push(snapshot);
        }

        private void RecordSettingsDraftChange()
        {
            if (_settingsPopulating || _settingsHistoryApplying) return;
            string current = CaptureSettingsDraft();
            if (String.IsNullOrEmpty(current)) return;
            if (String.IsNullOrEmpty(_settingsLastSnapshot)) { _settingsLastSnapshot = current; return; }
            if (String.Equals(current, _settingsLastSnapshot, StringComparison.Ordinal)) return;
            PushSettingsHistory(_settingsUndo, _settingsLastSnapshot);
            _settingsRedo.Clear();
            _settingsLastSnapshot = current;
        }

        private void UpdateSettingsHistoryButtons()
        {
            if (_settingsUndoButton != null) _settingsUndoButton.IsEnabled = _settingsUndo.Count > 0;
            if (_settingsRedoButton != null) _settingsRedoButton.IsEnabled = _settingsRedo.Count > 0;
        }

        private void ApplySettingsDraftSnapshot(string snapshot, string status)
        {
            if (String.IsNullOrWhiteSpace(snapshot)) return;
            Dictionary<string, object> map;
            try { map = AsMap(_json.DeserializeObject(snapshot)); } catch { return; }
            _settingsHistoryApplying = true;
            _settingsPopulating = true;
            try
            {
                foreach (ComboBox combo in SettingsDraftCombos())
                {
                    if (combo == null) continue; object raw;
                    if (map.TryGetValue("combo:" + combo.Name, out raw)) SetComboPreserve(combo, Convert.ToString(raw, CultureInfo.InvariantCulture));
                }
                foreach (CheckBox check in SettingsDraftChecks())
                {
                    if (check == null) continue; object raw;
                    if (map.TryGetValue("check:" + check.Name, out raw)) check.IsChecked = raw is bool ? (bool)raw : String.Equals(Convert.ToString(raw, CultureInfo.InvariantCulture), "true", StringComparison.OrdinalIgnoreCase);
                }
                foreach (Slider slider in SettingsDraftSliders())
                {
                    if (slider == null) continue; object raw;
                    if (map.TryGetValue("slider:" + slider.Name, out raw)) slider.Value = Math.Max(slider.Minimum, Math.Min(slider.Maximum, ToDouble(raw, slider.Value)));
                }
                UpdateSettingsSliderLabels();
                RefreshVisualizerColorComboForeground(_settingsVisualizerSolidColor);
                RefreshStyledComboForeground(_settingsThemeAccent);
            }
            finally { _settingsPopulating = false; _settingsHistoryApplying = false; }
            _settingsLastSnapshot = CaptureSettingsDraft();
            _settingsDirty = !String.Equals(_settingsLastSnapshot, _settingsBaselineSnapshot, StringComparison.Ordinal);
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = _settingsDirty;
            if (_settingsStatusText != null) _settingsStatusText.Text = status + (_settingsDirty ? " Previewing now; Save keeps it." : " You are back at the saved settings.");
            UpdateSettingsHistoryButtons();
            ApplySettingsThemePreview();
            RefreshObsQuickSetup();
            ScheduleSettingsLivePreview();
        }

        private void UndoSettingsDraft()
        {
            if (_settingsUndo.Count == 0) return;
            _settingsFactoryResetPending = false;
            string current = CaptureSettingsDraft();
            PushSettingsHistory(_settingsRedo, current);
            string previous = _settingsUndo.Pop();
            ApplySettingsDraftSnapshot(previous, "Undid the last settings change.");
        }

        private void RedoSettingsDraft()
        {
            if (_settingsRedo.Count == 0) return;
            _settingsFactoryResetPending = false;
            string current = CaptureSettingsDraft();
            PushSettingsHistory(_settingsUndo, current);
            string next = _settingsRedo.Pop();
            ApplySettingsDraftSnapshot(next, "Redid the settings change.");
        }

        private void RestoreDefaultSettingsDraft()
        {
            MessageBoxResult answer = MessageBox.Show(_window,
                "Restore YOMI to factory settings?\r\n\r\nThis resets preferences, interface/layout state, media presentation, theme, Queue view, window geometry, volume, and performance/broadcast settings.\r\n\r\nIt does NOT delete listening sessions, playlists/pools, favorites, cache, library data, or your current/resume bookmark.",
                "Restore YOMI to factory settings", MessageBoxButton.YesNo, MessageBoxImage.Warning, MessageBoxResult.No);
            if (answer != MessageBoxResult.Yes) return;
            string before = CaptureSettingsDraft();
            PopulateIntegratedSettings(true);
            string after = CaptureSettingsDraft();
            if (!String.Equals(before, after, StringComparison.Ordinal)) PushSettingsHistory(_settingsUndo, before);
            _settingsRedo.Clear();
            _settingsFactoryResetPending = true;
            _settingsLastSnapshot = after;
            // UI-only state is not represented in CaptureSettingsDraft, so a factory reset is
            // save-worthy even when config.json already happens to equal default-config.json.
            _settingsDirty = true;
            if (_settingsSaveButton != null) _settingsSaveButton.IsEnabled = true;
            if (_settingsStatusText != null) _settingsStatusText.Text = "Factory reset staged. Save resets settings and interface state; your sessions, media cache, favorites and playback bookmark stay intact.";
            UpdateSettingsHistoryButtons();
            ApplySettingsThemePreview();
            RefreshObsQuickSetup();
            ScheduleSettingsLivePreview();
        }

        private static string OutputBundleToModules(string bundle)
        {
            switch ((bundle ?? "").Trim())
            {
                case "Thumbnail + text":
                case "Artwork + text": return "artwork,title,channel";
                case "Video + text": return "video,title,channel";
                case "Text only": return "title,channel";
                case "Thumbnail only":
                case "Artwork only": return "artwork";
                case "Video only": return "video";
                case "Visualizer only": return "visualizer";
                case "Thumbnail + visualizer":
                case "Artwork + visualizer": return "artwork,visualizer";
                case "Video + visualizer": return "video,visualizer";
                case "Full strip": return "artwork,video,title,channel,visualizer";
                default: return String.IsNullOrWhiteSpace(bundle) ? "artwork,video,title,channel,visualizer" : bundle.Trim();
            }
        }

        private static string ModulesToOutputBundle(string modules)
        {
            string normalized = String.Join(",", (modules ?? "").Split(',').Select(v => v.Trim().ToLowerInvariant()).Where(v => v.Length > 0));
            if (normalized == "artwork,title,channel" || normalized == "artwork,channel,title") return "Thumbnail + text";
            if (normalized == "video,title,channel" || normalized == "video,channel,title") return "Video + text";
            if (normalized == "title,channel" || normalized == "channel,title") return "Text only";
            if (normalized == "artwork") return "Thumbnail only";
            if (normalized == "video") return "Video only";
            if (normalized == "visualizer") return "Visualizer only";
            if (normalized == "artwork,visualizer" || normalized == "visualizer,artwork") return "Thumbnail + visualizer";
            if (normalized == "video,visualizer" || normalized == "visualizer,video") return "Video + visualizer";
            if (normalized == "history") return "Full strip";
            if (normalized == "artwork,video,title,channel,visualizer") return "Full strip";
            return String.IsNullOrWhiteSpace(modules) ? "Full strip" : modules;
        }

        private Dictionary<string, object> DirectorOutput(Dictionary<string, object> config, int id)
        {
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw);
                if (GetInt(map, "id", 0) == id) return map;
            }
            return EmptyMap();
        }

        private void LoadDirectorOutputDraft(Dictionary<string, object> config, int id, CheckBox enabled, ComboBox modules, ComboBox layout)
        {
            Dictionary<string, object> map = DirectorOutput(config, id);
            enabled.IsChecked = GetBool(map, "enabled", id == 1);
            SetComboPreserve(modules, ModulesToOutputBundle(GetString(map, "modules", id == 1 ? "artwork,video,title,channel,visualizer" : "")));
            SetComboPreserve(layout, GetString(map, "layout", "Horizontal"));
        }

        private List<object> BuildDirectorOutputs(Dictionary<string, object> config)
        {
            var output = new List<object>();
            var seen = new HashSet<int>();
            CheckBox[] enabled = new[] { _settingsOutput1Enabled, _settingsOutput2Enabled, _settingsOutput3Enabled, _settingsOutput4Enabled };
            ComboBox[] modules = new[] { _settingsOutput1Modules, _settingsOutput2Modules, _settingsOutput3Modules, _settingsOutput4Modules };
            ComboBox[] layout = new[] { _settingsOutput1Layout, _settingsOutput2Layout, _settingsOutput3Layout, _settingsOutput4Layout };
            for (int id = 1; id <= 4; id++)
            {
                Dictionary<string, object> map = DirectorOutput(config, id);
                if (map.Count == 0) map = EmptyMap(); else map = new Dictionary<string, object>(map, StringComparer.OrdinalIgnoreCase);
                map["id"] = id;
                map["enabled"] = enabled[id - 1].IsChecked == true;
                map["modules"] = OutputBundleToModules(ComboText(modules[id - 1], "Full strip"));
                map["layout"] = ComboText(layout[id - 1], "Horizontal");
                output.Add(map); seen.Add(id);
            }
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw); int id = GetInt(map, "id", 0);
                if (id > 0 && !seen.Contains(id)) output.Add(map);
            }
            return output;
        }

        private void ApplyBroadcastPresetDraft(string preset)
        {
            if (_settingsPopulating || String.IsNullOrWhiteSpace(preset) || String.Equals(preset, "Custom", StringComparison.OrdinalIgnoreCase)) return;
            _settingsPopulating = true;
            try
            {
                if (String.Equals(preset, "Classic strip", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = false; _settingsArtwork.IsChecked = true; _settingsVideo.IsChecked = true; _settingsTitle.IsChecked = true; _settingsChannel.IsChecked = true; _settingsVisualizerEnabled.IsChecked = true;
                }
                else if (String.Equals(preset, "Split sources", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail only"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = true; SetComboPreserve(_settingsOutput2Modules, "Video only"); SetComboPreserve(_settingsOutput2Layout, "Horizontal");
                    _settingsOutput3Enabled.IsChecked = true; SetComboPreserve(_settingsOutput3Modules, "Text only"); SetComboPreserve(_settingsOutput3Layout, "Horizontal");
                    _settingsOutput4Enabled.IsChecked = true; SetComboPreserve(_settingsOutput4Modules, "Visualizer only"); SetComboPreserve(_settingsOutput4Layout, "Horizontal");
                }
                else if (String.Equals(preset, "Text + artwork", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail + text"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = false; _settingsOutput3Enabled.IsChecked = false; _settingsOutput4Enabled.IsChecked = false;
                }
                else if (String.Equals(preset, "Visual focus", StringComparison.OrdinalIgnoreCase))
                {
                    _settingsDirectorMode.IsChecked = true;
                    _settingsOutput1Enabled.IsChecked = true; SetComboPreserve(_settingsOutput1Modules, "Thumbnail + visualizer"); SetComboPreserve(_settingsOutput1Layout, "Horizontal");
                    _settingsOutput2Enabled.IsChecked = true; SetComboPreserve(_settingsOutput2Modules, "Text only"); SetComboPreserve(_settingsOutput2Layout, "Horizontal");
                    _settingsOutput3Enabled.IsChecked = false; _settingsOutput4Enabled.IsChecked = false;
                }
            }
            finally { _settingsPopulating = false; }
            MarkSettingsDirty("Broadcast preset previewed. Save keeps it.");
        }

        private void SetDirectorOutputConfig(Dictionary<string, object> config, int id, bool enabled, string modules, string layout)
        {
            var outputs = new List<object>();
            bool found = false;
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> map = AsMap(raw);
                if (GetInt(map, "id", 0) == id)
                {
                    map = new Dictionary<string, object>(map, StringComparer.OrdinalIgnoreCase);
                    map["id"] = id; map["enabled"] = enabled;
                    if (modules != null) map["modules"] = modules;
                    if (layout != null) map["layout"] = layout;
                    found = true;
                }
                outputs.Add(map);
            }
            if (!found)
            {
                var map = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "id", id }, { "enabled", enabled }, { "modules", modules ?? "" }, { "layout", layout ?? "Horizontal" }
                };
                outputs.Add(map);
            }
            config["director_outputs"] = outputs;
        }

        private void ApplyBroadcastPresetToConfig(Dictionary<string, object> config, string requestedPreset)
        {
            if (config == null) throw new ArgumentNullException("config");
            string preset = NormalizeSlotBroadcastPreset(requestedPreset);
            if (String.Equals(preset, "Keep current", StringComparison.OrdinalIgnoreCase)) return;
            config["overlay_preset"] = preset;
            if (String.Equals(preset, "Classic strip", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = false; config["artwork_enabled"] = true; config["video_enabled"] = true; config["title_enabled"] = true; config["channel_enabled"] = true; config["visualizer_enabled"] = true;
            }
            else if (String.Equals(preset, "Split sources", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork", "Horizontal");
                SetDirectorOutputConfig(config, 2, true, "video", "Horizontal");
                SetDirectorOutputConfig(config, 3, true, "title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 4, true, "visualizer", "Horizontal");
            }
            else if (String.Equals(preset, "Text + artwork", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork,title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 2, false, null, null); SetDirectorOutputConfig(config, 3, false, null, null); SetDirectorOutputConfig(config, 4, false, null, null);
            }
            else if (String.Equals(preset, "Visual focus", StringComparison.OrdinalIgnoreCase))
            {
                config["director_mode"] = true;
                SetDirectorOutputConfig(config, 1, true, "artwork,visualizer", "Horizontal");
                SetDirectorOutputConfig(config, 2, true, "title,channel", "Horizontal");
                SetDirectorOutputConfig(config, 3, false, null, null); SetDirectorOutputConfig(config, 4, false, null, null);
            }
        }

        private string ApplyIntegratedConfigTransaction(Dictionary<string, object> config)
        {
            return ApplyIntegratedConfigTransaction(config, null);
        }

        private string ApplyIntegratedConfigTransaction(Dictionary<string, object> config, Func<bool> stillAuthoritative)
        {
            if (config == null || config.Count == 0) throw new InvalidOperationException("The settings candidate is empty.");
            Func<bool> authorized = stillAuthoritative ?? delegate { return true; };
            if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority before it started.");
            Directory.CreateDirectory(_stateRoot);
            string token = Guid.NewGuid().ToString("N");
            string candidate = Path.Combine(_stateRoot, "settings-candidate-" + token + ".json");
            string result = Path.Combine(_stateRoot, "settings-result-" + token + ".json");
            var serializer = new JavaScriptSerializer();
            WriteUtf8NoBom(candidate, serializer.Serialize(config));
            try
            {
                if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority before commit.");
                string script = Path.Combine(_appDir, "apply-integrated-settings.ps1");
                if (!File.Exists(script))
                {
                    string configPath = Path.Combine(_dataRoot, "config.json");
                    string previousPath = Path.Combine(_stateRoot, "config-before-integrated-save.json");
                    try
                    {
                        if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority before fallback commit.");
                        if (File.Exists(configPath)) File.Copy(configPath, previousPath, true);
                        if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority before fallback write.");
                        WriteUtf8NoBom(configPath, serializer.Serialize(config));
                        try { File.Delete(Path.Combine(_stateRoot, "config-pending.json")); } catch { }
                        try { File.Delete(Path.Combine(_stateRoot, "config-pending-conflict.json")); } catch { }
                        _jsonCache.Clear();
                    }
                    catch (OperationCanceledException) { throw; }
                    catch (Exception ex)
                    {
                        throw new InvalidOperationException("YOMI could not commit settings atomically: " + ex.Message, ex);
                    }
                    if (authorized() && _running) SendMpv("script-message", "yomi-reload-config");
                    return "APPLIED";
                }
                string ps = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
                var psi = new ProcessStartInfo { FileName=ps, Arguments="-NoProfile -ExecutionPolicy Bypass -File " + Quote(script) + " -CandidatePath " + Quote(candidate) + " -ResultPath " + Quote(result), WorkingDirectory=_appDir, UseShellExecute=false, CreateNoWindow=true, WindowStyle=ProcessWindowStyle.Hidden };
                using (Process proc = Process.Start(psi))
                {
                    if (proc == null) throw new InvalidOperationException("YOMI could not start the settings helper.");
                    Stopwatch wait = Stopwatch.StartNew();
                    while (!proc.HasExited && wait.ElapsedMilliseconds < 12000 && authorized()) Thread.Sleep(100);
                    if (!authorized())
                    {
                        if (!proc.HasExited) { try { proc.Kill(); } catch { } }
                        throw new OperationCanceledException("The settings transaction was superseded by a newer session transition.");
                    }
                    if (!proc.HasExited)
                    {
                        try { proc.Kill(); } catch { }
                        throw new TimeoutException("The settings helper timed out and was stopped.");
                    }
                    if (proc.ExitCode != 0) throw new InvalidOperationException("The settings helper exited with code " + proc.ExitCode + ".");
                }
                if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority after the helper returned.");
                if (!File.Exists(result)) throw new InvalidOperationException("The settings helper returned no result.");
                Dictionary<string, object> r = AsMap(serializer.DeserializeObject(ReadTextShared(result)));
                if (!String.Equals(GetString(r, "status", ""), "PASS", StringComparison.OrdinalIgnoreCase)) throw new InvalidOperationException(GetString(r, "message", "The settings transaction did not report PASS."));
                string action = GetString(r, "action", "");
                if (String.IsNullOrWhiteSpace(action)) throw new InvalidOperationException("The settings transaction returned no action.");
                if (!authorized()) throw new OperationCanceledException("The settings transaction lost authority before final projection.");

                string liveConfigPath = Path.Combine(_dataRoot, "config.json");
                WriteUtf8NoBom(liveConfigPath, serializer.Serialize(config));
                try { File.Delete(Path.Combine(_stateRoot, "config-pending.json")); } catch { }
                try { File.Delete(Path.Combine(_stateRoot, "config-pending-conflict.json")); } catch { }
                _jsonCache.Clear();
                if (authorized() && _running) SendMpv("script-message", "yomi-reload-config");
                return "APPLIED";
            }
            finally { try { File.Delete(candidate); File.Delete(result); } catch { } }
        }

        private Dictionary<string, object> CloneIntegratedConfig(Dictionary<string, object> source)
        {
            if (source == null || source.Count == 0) return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
            return AsMap(serializer.DeserializeObject(serializer.Serialize(source)));
        }

        private bool QueueSlotBroadcastAffinity(SlotRecord slot)
        {
            Dictionary<string, object> baseline = ReadJsonFresh(Path.Combine(_dataRoot, "config.json"));
            if (baseline.Count == 0) baseline = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));
            int generation = Interlocked.Increment(ref _slotBroadcastGeneration);
            return QueueSlotBroadcastAffinity(slot, generation, baseline);
        }

        private bool QueueSlotBroadcastAffinity(SlotRecord slot, int generation, Dictionary<string, object> baseline)
        {
            if (!_slotBroadcastFollowEnabled || slot == null) return false;
            string preset = NormalizeSlotBroadcastPreset(slot.BroadcastPreset);
            Dictionary<string, object> candidate = CloneIntegratedConfig(baseline);
            bool changesLayout = !String.Equals(preset, "Keep current", StringComparison.OrdinalIgnoreCase);
            if (changesLayout) ApplyBroadcastPresetToConfig(candidate, preset);

            bool startWorker = false;
            lock (_slotBroadcastSync)
            {
                _slotBroadcastPendingConfig = candidate;
                _slotBroadcastPendingPreset = preset;
                _slotBroadcastPendingGeneration = generation;
                if (!_slotBroadcastWorkerActive)
                {
                    _slotBroadcastWorkerActive = true;
                    startWorker = true;
                }
            }
            if (startWorker) ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainSlotBroadcastAffinity(); });
            return changesLayout;
        }

        private void DrainSlotBroadcastAffinity()
        {
            while (true)
            {
                Dictionary<string, object> candidate;
                string preset;
                int generation;
                lock (_slotBroadcastSync)
                {
                    candidate = _slotBroadcastPendingConfig;
                    preset = _slotBroadcastPendingPreset;
                    generation = _slotBroadcastPendingGeneration;
                    _slotBroadcastPendingConfig = null;
                    _slotBroadcastPendingPreset = "";
                }
                if (candidate == null)
                {
                    lock (_slotBroadcastSync)
                    {
                        if (_slotBroadcastPendingConfig == null)
                        {
                            _slotBroadcastWorkerActive = false;
                            return;
                        }
                    }
                    continue;
                }

                string action = "";
                string failure = "";
                bool cancelled = false;
                Func<bool> authority = delegate
                {
                    return generation == Volatile.Read(ref _slotBroadcastGeneration) && !_shutdownRequested && !_slotSwitchActive;
                };
                try { action = ApplyIntegratedConfigTransaction(candidate, authority); }
                catch (OperationCanceledException) { cancelled = true; }
                catch (Exception ex) { failure = ex.Message; }

                if (!cancelled && generation == Volatile.Read(ref _slotBroadcastGeneration) && !_shutdownRequested && !_slotSwitchActive)
                {
                    string actionCopy = action;
                    string failureCopy = failure;
                    string presetCopy = preset;
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (generation != Volatile.Read(ref _slotBroadcastGeneration) || _shutdownRequested || _slotSwitchActive) return;
                        if (String.IsNullOrWhiteSpace(failureCopy))
                            AddActivity("Listening session", "broadcast layout " + presetCopy + " | " + (String.IsNullOrWhiteSpace(actionCopy) ? "applied" : actionCopy.ToLowerInvariant()));
                        else
                        {
                            AddActivity("Listening session", "broadcast layout preference failed");
                            ShowToast("Listening session", "The session switched, but its preferred broadcast layout could not be applied. The current OBS layout was kept.");
                        }
                    });
                }

                lock (_slotBroadcastSync)
                {
                    if (_slotBroadcastPendingConfig == null)
                    {
                        _slotBroadcastWorkerActive = false;
                        return;
                    }
                }
            }
        }

        public bool SelfTestSettingsHierarchy()
        {
            _selfTestFailureDetail = "";
            try
            {
                if (_settingsTabs == null || _settingsTabs.Items.Count != 3) return SelfTestFail("SelfTestSettingsHierarchy assertion 1: expected 3 tabs; actual " + (_settingsTabs == null ? "<null>" : _settingsTabs.Items.Count.ToString(CultureInfo.InvariantCulture)));
                string[] expected = new[] { "General", "Broadcast", "Performance" };
                for (int i = 0; i < expected.Length; i++)
                {
                    TabItem tab = _settingsTabs.Items[i] as TabItem;
                    string actual = tab == null ? "" : Convert.ToString(tab.Header, CultureInfo.InvariantCulture);
                    if (tab == null || !String.Equals(actual, expected[i], StringComparison.Ordinal)) return SelfTestFail("SelfTestSettingsHierarchy assertion 2: tab " + i.ToString(CultureInfo.InvariantCulture) + " expected='" + expected[i] + "' actual='" + actual + "'");
                }
                if (_settingsPerformanceAdvancedExpander == null || !_settingsPerformanceAdvancedExpander.IsExpanded) return SelfTestFail("SelfTestSettingsHierarchy assertion 3: Performance controls must be visible by default");
                if (_settingsSectionText == null || _settingsEverydayScroll == null || _settingsSectionEverydayUse == null || _settingsSectionBroadcastSetup == null || _settingsSectionPerformancePreparation == null) return SelfTestFail("SelfTestSettingsHierarchy assertion 4: settings section visual tree incomplete");
                if (_settingsCloseButton == null) return SelfTestFail("SelfTestSettingsHierarchy assertion 5: Settings close action missing");
                if (_settingsTheme == null || _settingsTheme.Items.Count < 18 || _settingsThemeIntensity == null || _settingsThemeIntensity.Items.Count != 3 || _settingsThemeIntensitySlider == null || _settingsThemeAccent == null || _settingsThemeAccent.Items.Count < 17 || _settingsThemeBlend == null || _settingsThemeBlend.Items.Count != 3 || _settingsThemeBlendSlider == null || _settingsWindowTransparencySlider == null || _settingsThemeHint == null || _settingsThemeSwatchApp == null || _settingsThemeSwatchSurface == null || _settingsThemeSwatchAccent == null || _settingsThemeSwatchText == null || _settingsThemePreviousButton == null || _settingsThemeNextButton == null)
                    return SelfTestFail("SelfTestSettingsHierarchy assertion 6: appearance composition controls incomplete");
                if (_settingsPlayerVideoQuality == null || _settingsPlayerVideoQuality.Items.Count != 7 || _settingsOverlayVideoQuality == null || _settingsOverlayVideoQuality.Visibility != Visibility.Collapsed)
                    return SelfTestFail("SelfTestSettingsHierarchy assertion 6a: Player/OBS video quality is not one visible authority");
                if (_settingsVisualizerPixelSize == null || _settingsVisualizerPixelSize.Items.Count != 4)
                    return SelfTestFail("SelfTestSettingsHierarchy assertion 6b: human visualizer pixel-size choices are missing");
                foreach (AppearancePreset theme in new[] { AppearancePreset.Rosewood, AppearancePreset.Plum, AppearancePreset.Orchid, AppearancePreset.Lavender, AppearancePreset.Blush, AppearancePreset.Champagne })
                {
                    Dictionary<string,string> palette = AppearanceColors(theme);
                    if (!palette.ContainsKey("AppBg") || !palette.ContainsKey("SurfaceRaised") || !palette.ContainsKey("Accent") || !palette.ContainsKey("TextPrimary"))
                        return SelfTestFail("SelfTestSettingsHierarchy assertion 7: incomplete palette for " + theme.ToString());
                }
                return true;
            }
            catch (Exception ex) { return SelfTestFail("SelfTestSettingsHierarchy assertion 8 exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public bool SelfTestMediaPresentation()
        {
            _selfTestFailureDetail = "";
            MediaMode oldMode = _mediaMode;
            MediaPairLayout oldPairLayout = _mediaPairLayout;
            MediaRackSize oldRackSize = _mediaRackSize;
            MediaScaleFilter oldArtFilter = _artworkScaleFilter;
            MediaScaleFilter oldVideoFilter = _videoScaleFilter;
            VideoBackdropMode oldBackdropMode = _videoBackdropMode;
            MediaStageKind oldStageKind = _mediaStageKind;
            bool oldStageFullscreen = _mediaStageFullscreen;
            bool oldLarge = _largeVideoArea;
            bool oldAbsent = _videoAuthoritativelyAbsent;
            double oldAspect = _videoPresentedAspect;
            string oldBackend = _videoPreviewBackend;
            bool oldNative = _videoNativePreviewActive;
            bool oldReady = _videoPreviewReady;
            bool oldQueueCanvasForTest = _queueCanvasActive;
            AdaptiveLayoutTier oldAdaptiveTierForTest = _adaptiveLayoutTier;
            bool oldVisualizerBridgeHold = _visualizerBridgeHold;
            bool oldVisualizerReady = _visualizerPreviewReady;
            bool oldVisualizerNative = _visualizerNativePreviewActive;
            bool oldVisualizerEnabled = _visualizerEnabled;
            ImageSource oldVisualizerSource = _visualizerFrameHost == null ? null : _visualizerFrameHost.Source;
            Visibility oldVisualizerVisibility = _visualizerFrameHost == null ? Visibility.Collapsed : _visualizerFrameHost.Visibility;
            try
            {
                if (_mediaViewport == null || _mediaGapColumn == null || _videoBridgeHost == null || _videoPresentationFrame == null || _videoPresentationBorderOverlay == null || _artworkVideoDivider == null || _largeVideoAreaHost == null || _largeVideoAreaRow == null || _largeVideoAreaGapRow == null)
                    return SelfTestFail("SelfTestMediaPresentation assertion 1: R61.106.8 presentation surfaces incomplete");
                Thickness inset = _mediaViewport.Margin;
                if (Math.Abs(inset.Left) > 0.01 || Math.Abs(inset.Top) > 0.01 || Math.Abs(inset.Right) > 0.01 || Math.Abs(inset.Bottom) > 0.01)
                    return SelfTestFail("SelfTestMediaPresentation assertion 2: hidden media viewport inset returned");

                double rw, rh;
                MediaRackResolution(MediaRackSize.P144, out rw, out rh); if (Math.Abs(rw - 256) > 0.01 || Math.Abs(rh - 144) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2a: 144p media preset lost exact resolution identity");
                MediaRackResolution(MediaRackSize.P240, out rw, out rh); if (Math.Abs(rw - 426) > 0.01 || Math.Abs(rh - 240) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2b: 240p media preset lost exact resolution identity");
                MediaRackResolution(MediaRackSize.P360, out rw, out rh); if (Math.Abs(rw - 640) > 0.01 || Math.Abs(rh - 360) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2c: 360p media preset lost exact resolution identity");
                MediaRackResolution(MediaRackSize.P480, out rw, out rh); if (Math.Abs(rw - 854) > 0.01 || Math.Abs(rh - 480) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2d: 480p media preset lost exact resolution identity");
                MediaRackResolution(MediaRackSize.P720, out rw, out rh); if (Math.Abs(rw - 1280) > 0.01 || Math.Abs(rh - 720) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2e: 720p media preset lost exact resolution identity");
                MediaRackResolution(MediaRackSize.Native, out rw, out rh); if (rw < 256 || rh < 144 || Math.Abs((rw / rh) - (16.0 / 9.0)) > 0.02) return SelfTestFail("SelfTestMediaPresentation assertion 2f: Native media size did not resolve to selected canonical video quality");
                MediaRackResolution(MediaRackSize.Fit, out rw, out rh); if (Math.Abs(rw - 1280) > 0.01 || Math.Abs(rh - 720) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 2g: Fit nominal identity changed before controller fit-down");
                if (_visualizerBackdropImage == null) return SelfTestFail("SelfTestMediaPresentation assertion 2f: controller visualizer backdrop image is missing");
                ApplyVisualizerPresentation(false);
                if (RenderOptions.GetBitmapScalingMode(_visualizerBackdropImage) != BitmapScalingMode.NearestNeighbor)
                    return SelfTestFail("SelfTestMediaPresentation assertion 2g: controller visualizer final scaler is not forced to nearest-neighbor");

                _mediaMode = MediaMode.Both;
                _mediaPairLayout = MediaPairLayout.LeftRight;
                _mediaRackSize = MediaRackSize.P144;
                _videoAuthoritativelyAbsent = false;
                _largeVideoArea = false;
                _adaptiveLayoutTier = AdaptiveLayoutTier.Standard;
                ReparentVideoPresenter();
                double borderV = _mediaFrame == null ? 0.0 : _mediaFrame.BorderThickness.Top + _mediaFrame.BorderThickness.Bottom;

                // Paired media contract: Art and Video own equal 16:9 OUTER reservations.
                // Artwork and video content still use independent crop/source-aspect rules inside
                // those equal viewboxes, and only the real video source rectangle is framed.
                _videoPresentedAspect = 4.0 / 3.0;
                ApplyMediaMode(false);
                double drawable = Math.Max(1.0, (_mediaFrame == null ? AdaptiveMediaHeight() : _mediaFrame.Height) - borderV);
                if (Math.Abs(_mediaGapColumn.Width.Value) > 0.01) return SelfTestFail("SelfTestMediaPresentation assertion 3: empty Thumbnail/Video spacer column returned");
                double pairedArtWidth = _artworkColumn.Width.Value;
                double stableVideoWidth = _videoColumn.Width.Value;
                if (Math.Abs(stableVideoWidth - pairedArtWidth) > 1.5) return SelfTestFail("SelfTestMediaPresentation assertion 4: paired Thumbnail/Video outer viewboxes are not equal width");
                if (Math.Abs(stableVideoWidth - drawable * (16.0 / 9.0)) > 1.5) return SelfTestFail("SelfTestMediaPresentation assertion 4a: video reservation is not stable 16:9 geometry");
                if (Math.Abs(pairedArtWidth - drawable * (16.0 / 9.0)) > 1.5) return SelfTestFail("SelfTestMediaPresentation assertion 4b: paired artwork reservation is not equal 16:9 geometry");
                Grid videoInner = _window.FindName("VideoPresentationContent") as Grid;
                Grid artworkInner = _window.FindName("ArtworkPresentationContent") as Grid;
                Border videoBevelShadow = _window.FindName("VideoBevelShadow") as Border;
                Border videoBevelHighlight = _window.FindName("VideoBevelHighlight") as Border;
                Border artworkBevelShadow = _window.FindName("ArtworkBevelShadow") as Border;
                Border artworkBevelHighlight = _window.FindName("ArtworkBevelHighlight") as Border;
                if (_videoPresentationFrame.HorizontalAlignment != HorizontalAlignment.Center ||
                    _videoPresentationFrame.VerticalAlignment != VerticalAlignment.Center ||
                    Math.Abs(_videoPresentationFrame.Width - drawable * (4.0 / 3.0)) > 1.5 ||
                    Math.Abs(_videoPresentationFrame.Height - drawable) > 1.5 ||
                    _artworkVideoDivider.Visibility != Visibility.Collapsed ||
                    _videoPresentationBorderOverlay.Visibility != Visibility.Collapsed ||
                    Math.Abs(_videoPresentationFrame.BorderThickness.Left - 1.0) > 0.01 || Math.Abs(_videoPresentationFrame.BorderThickness.Right - 1.0) > 0.01 ||
                    videoInner == null || Math.Abs(videoInner.Margin.Left) > 0.01 || Math.Abs(videoInner.Margin.Top) > 0.01 || Math.Abs(videoInner.Margin.Right) > 0.01 || Math.Abs(videoInner.Margin.Bottom) > 0.01 ||
                    videoBevelShadow == null || videoBevelShadow.BorderThickness.Left > 0.01 || videoBevelShadow.BorderThickness.Top > 0.01 || videoBevelShadow.BorderThickness.Right > 0.01 || videoBevelShadow.BorderThickness.Bottom > 0.01 ||
                    videoBevelHighlight == null || videoBevelHighlight.BorderThickness.Left > 0.01 || videoBevelHighlight.BorderThickness.Top > 0.01 || videoBevelHighlight.BorderThickness.Right > 0.01 || videoBevelHighlight.BorderThickness.Bottom > 0.01)
                    return SelfTestFail("SelfTestMediaPresentation assertion 4c: video must stay whole, center-anchored and use a flat 1px theme frame");
                if (_mediaFrame != null && (_mediaFrame.BorderThickness.Left > 0.01 || _mediaFrame.BorderThickness.Top > 0.01 || _mediaFrame.BorderThickness.Right > 0.01 || _mediaFrame.BorderThickness.Bottom > 0.01))
                    return SelfTestFail("SelfTestMediaPresentation assertion 4d: outer rack border returned around source-aspect space");
                if (_artworkPane != null && (Math.Abs(_artworkPane.BorderThickness.Left - 1.0) > 0.01 || Math.Abs(_artworkPane.BorderThickness.Top - 1.0) > 0.01 || Math.Abs(_artworkPane.BorderThickness.Right - 1.0) > 0.01 || Math.Abs(_artworkPane.BorderThickness.Bottom - 1.0) > 0.01 ||
                    artworkInner == null || Math.Abs(artworkInner.Margin.Left) > 0.01 || Math.Abs(artworkInner.Margin.Top) > 0.01 || Math.Abs(artworkInner.Margin.Right) > 0.01 || Math.Abs(artworkInner.Margin.Bottom) > 0.01 ||
                    artworkBevelShadow == null || artworkBevelShadow.BorderThickness.Left > 0.01 || artworkBevelShadow.BorderThickness.Top > 0.01 ||
                    artworkBevelHighlight == null || artworkBevelHighlight.BorderThickness.Right > 0.01 || artworkBevelHighlight.BorderThickness.Bottom > 0.01))
                    return SelfTestFail("SelfTestMediaPresentation assertion 4e: artwork must use the same flat 1px theme frame as video");

                _videoPresentedAspect = 16.0 / 9.0;
                ApplyMediaMode(false);
                if (Math.Abs(_videoColumn.Width.Value - stableVideoWidth) > 0.01 ||
                    Math.Abs(_videoPresentationFrame.Width - stableVideoWidth) > 1.5 ||
                    Math.Abs(_videoPresentationFrame.Height - drawable) > 1.5 ||
                    _artworkPane == null || Math.Abs(_artworkPane.BorderThickness.Right) > 0.01 ||
                    Math.Abs(_videoPresentationFrame.BorderThickness.Left - 1.0) > 0.01)
                    return SelfTestFail("SelfTestMediaPresentation assertion 4f: 16:9 video does not fill the stable video reservation");

                _mediaPairLayout = MediaPairLayout.TopBottom;
                ApplyMediaMode(false);
                RowDefinition mediaTopRow = _window.FindName("MediaTopRow") as RowDefinition;
                RowDefinition mediaBottomRow = _window.FindName("MediaBottomRow") as RowDefinition;
                if (mediaTopRow == null || mediaBottomRow == null || Grid.GetRow(_artworkPane) != 0 || Grid.GetRow(_videoPane) != 1 || Grid.GetColumn(_videoPane) != 0 || mediaBottomRow.Height.Value <= 0)
                    return SelfTestFail("SelfTestMediaPresentation assertion 4f2: Top/Bottom media layout did not remain a deterministic two-cell rack");
                _mediaPairLayout = MediaPairLayout.LeftRight;
                ApplyMediaMode(false);

                double probeFps, probeAspect;
                ParseSourceVideoProbeText("width=480\nheight=360\navg_frame_rate=30000/1001\n", out probeFps, out probeAspect);
                if (Math.Abs(probeAspect - (4.0 / 3.0)) > 0.0001 || Math.Abs(probeFps - (30000.0 / 1001.0)) > 0.001)
                    return SelfTestFail("SelfTestMediaPresentation assertion 4g: named ffprobe parser lost 4:3 source geometry");

                _videoPresentedAspect = 9.0 / 16.0;
                ApplyMediaMode(false);
                if (Math.Abs(_videoColumn.Width.Value - stableVideoWidth) > 0.01 ||
                    _videoPresentationFrame.HorizontalAlignment != HorizontalAlignment.Center ||
                    _videoPresentationFrame.VerticalAlignment != VerticalAlignment.Center ||
                    Math.Abs(_videoPresentationFrame.Width - drawable * (9.0 / 16.0)) > 1.5 ||
                    Math.Abs(_videoPresentationFrame.Height - drawable) > 1.5)
                    return SelfTestFail("SelfTestMediaPresentation assertion 4h: portrait video must stay whole and center-anchored without changing rack width");

                _videoPresentedAspect = 2.39;
                ApplyMediaMode(false);
                double cinemaExpectedHeight = stableVideoWidth / 2.39;
                if (Math.Abs(_videoColumn.Width.Value - stableVideoWidth) > 0.01 ||
                    Math.Abs(_videoPresentationFrame.Width - stableVideoWidth) > 1.5 ||
                    Math.Abs(_videoPresentationFrame.Height - cinemaExpectedHeight) > 1.5 ||
                    _videoPresentationFrame.VerticalAlignment != VerticalAlignment.Center)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5: ultrawide video must shorten the real frame instead of letterboxing inside it");
                if (_videoHost == null || _videoHost.Stretch != Stretch.Uniform || _videoFrameHost == null || _videoFrameHost.Stretch != Stretch.Uniform)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5a: video presenter no longer preserves source aspect");

                double configuredVideoWidth = _videoColumn.Width.Value;
                double configuredFrameHeight = _mediaFrame == null ? 0.0 : _mediaFrame.Height;
                _videoAuthoritativelyAbsent = true;
                ApplyMediaMode(false);
                if (Math.Abs(_videoColumn.Width.Value - configuredVideoWidth) > 0.01 || (_mediaFrame != null && Math.Abs(_mediaFrame.Height - configuredFrameHeight) > 0.01))
                    return SelfTestFail("SelfTestMediaPresentation assertion 5b: missing video changed configured rack geometry");
                _videoAuthoritativelyAbsent = false;
                ApplyMediaMode(false);

                _mediaMode = MediaMode.Artwork;
                ApplyMediaMode(false);
                double artOnlyWidth = _artworkColumn.Width.Value;
                if (Math.Abs(artOnlyWidth - pairedArtWidth) > 1.5 || _videoColumn.Width.Value > 0.01)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5c: artwork-only mode did not preserve the selected resolution-linked cell geometry");

                _mediaMode = MediaMode.Video;
                _videoPresentedAspect = 4.0 / 3.0;
                ApplyMediaMode(false);
                if (_videoPresentationFrame.HorizontalAlignment != HorizontalAlignment.Center)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5d: video-only presentation is not centered in its stable reservation");

                _mediaMode = MediaMode.Both;
                _videoPresentedAspect = 4.0 / 3.0;
                ApplyMediaMode(false);

                // Synthetic thumbnail with four unequal baked edge bands: left 10, right 20,
                // top 8, bottom 12. Smart Crop must remove padding on both axes independently.
                int testW = 100, testH = 80, testStride = testW * 4;
                byte[] testPixels = new byte[testStride * testH];
                for (int yy = 0; yy < testH; yy++)
                {
                    for (int xx = 0; xx < testW; xx++)
                    {
                        int ii = yy * testStride + xx * 4;
                        byte v;
                        if (xx < 10) v = 8;
                        else if (xx >= 80) v = 24;
                        else if (yy < 8) v = 40;
                        else if (yy >= 68) v = 56;
                        else v = (byte)((yy * 11 + xx * 3) & 0xFF);
                        testPixels[ii] = v; testPixels[ii + 1] = v; testPixels[ii + 2] = v; testPixels[ii + 3] = 255;
                    }
                }
                var testBitmap = BitmapSource.Create(testW, testH, 96, 96, PixelFormats.Bgra32, null, testPixels, testStride);
                Int32Rect testCropRect;
                BitmapSource asymmetricCrop = BuildFlatEdgeArtworkCrop(testBitmap, out testCropRect);
                if (asymmetricCrop == null || asymmetricCrop.PixelWidth != 70 || asymmetricCrop.PixelHeight != 60 ||
                    testCropRect.X != 10 || testCropRect.Y != 8 || testCropRect.Width != 70 || testCropRect.Height != 60)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5d: four-edge artwork padding crop did not preserve the intended content rectangle");
                ImageBrush centeredBrush = CreateCenteredArtworkBrush(asymmetricCrop, true);
                if (centeredBrush == null || centeredBrush.Stretch != Stretch.UniformToFill || centeredBrush.AlignmentX != AlignmentX.Center || centeredBrush.AlignmentY != AlignmentY.Center)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5e: Smart Crop artwork is not explicitly centered and crop-zoomed to fill");

                // R61.106.5 recorder regressions. Deep portrait padding must not be vetoed merely
                // because the retained picture is narrower than the old 42% safety floor.
                int deepW = 128, deepH = 72, deepStride = deepW * 4;
                byte[] deepPixels = new byte[deepStride * deepH];
                for (int yy = 0; yy < deepH; yy++)
                {
                    for (int xx = 0; xx < deepW; xx++)
                    {
                        int ii = yy * deepStride + xx * 4;
                        byte v = (xx < 39 || xx >= 89) ? (byte)0 : (byte)((xx * 7 + yy * 13) & 0xFF);
                        deepPixels[ii] = v; deepPixels[ii + 1] = v; deepPixels[ii + 2] = v; deepPixels[ii + 3] = 255;
                    }
                }
                var deepBitmap = BitmapSource.Create(deepW, deepH, 96, 96, PixelFormats.Bgra32, null, deepPixels, deepStride);
                Int32Rect deepCropRect;
                BitmapSource deepCrop = BuildFlatEdgeArtworkCrop(deepBitmap, out deepCropRect);
                if (deepCrop == null || deepCropRect.X != 39 || deepCropRect.Width != 50 || deepCropRect.Y != 0 || deepCropRect.Height != deepH)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5f: deep portrait padding was not removed");

                // R61.106.27 recorder regression: equal deep black pillarbox bands can surround
                // artwork whose real left edge itself contains a mostly-black design rail. The
                // left transition is weak, but the opposing bands are same-color, extremely pure
                // and symmetric while the right transition is decisive. That is padding, not a
                // reason to preserve 55% of the bitmap as dead space.
                int symW = 160, symH = 90, symStride = symW * 4;
                byte[] symPixels = new byte[symStride * symH];
                for (int yy = 0; yy < symH; yy++)
                {
                    for (int xx = 0; xx < symW; xx++)
                    {
                        int ii = yy * symStride + xx * 4;
                        byte v;
                        if (xx < 44 || xx >= 116) v = 0;
                        else if (xx < 68) v = (yy % 7 == 0) ? (byte)180 : (byte)0;
                        else v = (byte)(40 + ((xx * 9 + yy * 5) % 180));
                        symPixels[ii] = v; symPixels[ii + 1] = v; symPixels[ii + 2] = v; symPixels[ii + 3] = 255;
                    }
                }
                var symBitmap = BitmapSource.Create(symW, symH, 96, 96, PixelFormats.Bgra32, null, symPixels, symStride);
                Int32Rect symCropRect;
                BitmapSource symCrop = BuildFlatEdgeArtworkCrop(symBitmap, out symCropRect);
                if (symCrop == null || symCropRect.X != 44 || symCropRect.Width != 72 || symCropRect.Y != 0 || symCropRect.Height != symH)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5g: symmetric deep pillarbox padding with a dark content rail was not removed");

                // A designed side rail can still look 90%-flat column-by-column. Contaminate one
                // candidate band with a small embedded mark: the whole-band purity gate must veto
                // BOTH sides rather than cropping the artwork furniture away.
                int railW = 128, railH = 72, railStride = railW * 4;
                byte[] railPixels = new byte[railStride * railH];
                for (int yy = 0; yy < railH; yy++)
                {
                    for (int xx = 0; xx < railW; xx++)
                    {
                        int ii = yy * railStride + xx * 4;
                        byte v = (xx < 12 || xx >= 116) ? (byte)0 : (byte)((xx * 5 + yy * 9) & 0xFF);
                        if (xx >= 3 && xx <= 8 && yy >= 20 && yy <= 25) v = 240;
                        railPixels[ii] = v; railPixels[ii + 1] = v; railPixels[ii + 2] = v; railPixels[ii + 3] = 255;
                    }
                }
                var railBitmap = BitmapSource.Create(railW, railH, 96, 96, PixelFormats.Bgra32, null, railPixels, railStride);
                Int32Rect railCropRect;
                BitmapSource railCrop = BuildFlatEdgeArtworkCrop(railBitmap, out railCropRect);
                if (railCrop != null || railCropRect.Width > 0 || railCropRect.Height > 0)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5h: designed edge rail was mistaken for disposable padding");

                // R61.106.2: reproduce the target-machine failure boundary. Decode a PNG frame on
                // a foreign STA, detach it there, then build/freeze the UI brush on this Dispatcher.
                // A BitmapFrame/BitmapDecoder object must never survive the worker-to-UI handoff.
                BitmapSource detachedFromForeignDecoder = null;
                Exception foreignDecodeFailure = null;
                Thread foreignArtworkThread = new Thread(delegate()
                {
                    try
                    {
                        int fw = 16, fh = 12, fs = fw * 4;
                        byte[] fp = new byte[fs * fh];
                        for (int fi = 0; fi < fp.Length; fi += 4)
                        {
                            fp[fi] = 20; fp[fi + 1] = 80; fp[fi + 2] = 160; fp[fi + 3] = 255;
                        }
                        BitmapSource seed = BitmapSource.Create(fw, fh, 96, 96, PixelFormats.Bgra32, null, fp, fs);
                        using (var encoded = new MemoryStream())
                        {
                            var png = new PngBitmapEncoder();
                            png.Frames.Add(BitmapFrame.Create(seed));
                            png.Save(encoded);
                            encoded.Position = 0;
                            BitmapDecoder decoder = BitmapDecoder.Create(encoded, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad);
                            detachedFromForeignDecoder = CreateDetachedArtworkBitmap(decoder.Frames[0]);
                        }
                    }
                    catch (Exception ex) { foreignDecodeFailure = ex; }
                });
                foreignArtworkThread.IsBackground = true;
                foreignArtworkThread.SetApartmentState(ApartmentState.STA);
                foreignArtworkThread.Start();
                if (!foreignArtworkThread.Join(3000))
                    return SelfTestFail("SelfTestMediaPresentation assertion 5h: foreign artwork decode/detach worker did not finish");
                if (foreignDecodeFailure != null || detachedFromForeignDecoder == null || !detachedFromForeignDecoder.IsFrozen)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5h: decoder-backed artwork was not detached/frozen before UI handoff" +
                        (foreignDecodeFailure == null ? "" : " | " + foreignDecodeFailure.GetType().Name + ": " + foreignDecodeFailure.Message));
                ImageBrush foreignBrush = CreateCenteredArtworkBrush(detachedFromForeignDecoder, false);
                if (foreignBrush == null || !foreignBrush.IsFrozen)
                    return SelfTestFail("SelfTestMediaPresentation assertion 5i: detached foreign artwork could not be frozen into a UI brush");

                // Queue compression must resolve through ApplyMediaMode only. A second height-only
                // mutation would desynchronize pane widths from the frame until a later refresh.
                _queueCanvasActive = true;
                ApplyMediaMode(false);
                double queueFrameHeight = _mediaFrame == null ? 0.0 : _mediaFrame.Height;
                double queueArtWidth = _artworkColumn == null ? 0.0 : _artworkColumn.Width.Value;
                double queueVideoWidth = _videoColumn == null ? 0.0 : _videoColumn.Width.Value;
                ApplyQueuePlayerCompressionForCurrentHeight();
                if ((_mediaFrame != null && Math.Abs(_mediaFrame.Height - queueFrameHeight) > 0.01) ||
                    (_artworkColumn != null && Math.Abs(_artworkColumn.Width.Value - queueArtWidth) > 0.01) ||
                    (_videoColumn != null && Math.Abs(_videoColumn.Width.Value - queueVideoWidth) > 0.01))
                    return SelfTestFail("SelfTestMediaPresentation assertion 5j: Queue compression introduced a second media-geometry authority");
                _queueCanvasActive = oldQueueCanvasForTest;
                ApplyMediaMode(false);

                _mediaMode = MediaMode.Both;
                _videoAuthoritativelyAbsent = false;
                _videoNativePreviewActive = false;
                if (VideoPreparationEnabled())
                {
                    _mediaStageKind = MediaStageKind.Video;
                    _mediaStageFullscreen = false;
                    _videoBackdropMode = VideoBackdropMode.PlayerArea;
                    ApplyMediaMode(false);
                    if ((_videoPane != null && _videoPane.Visibility != Visibility.Collapsed) ||
                        (_videoColumn != null && _videoColumn.Width.Value > 0.01) ||
                        (_playerVideoBackdropSurface != null && _playerVideoBackdropSurface.Visibility != Visibility.Collapsed))
                        return SelfTestFail("SelfTestMediaPresentation assertion 5k: detached video stage did not suppress duplicate/legacy controller video surfaces");
                }
                else
                {
                    _mediaStageKind = MediaStageKind.None;
                    _videoBackdropMode = VideoBackdropMode.Off;
                    ApplyMediaMode(false);
                    if ((_playerVideoBackdropSurface != null && _playerVideoBackdropSurface.Visibility != Visibility.Collapsed) ||
                        (_mediaStageSurface != null && _mediaStageSurface.Visibility == Visibility.Visible))
                        return SelfTestFail("SelfTestMediaPresentation assertion 5k: Settings Video Off leaked into detached video presentation");
                }
                _mediaStageKind = MediaStageKind.None;
                _mediaStageFullscreen = false;
                _videoBackdropMode = VideoBackdropMode.Off;
                ApplyMediaMode(false);

                _videoPreviewBackend = "native-opening";
                _videoNativePreviewActive = false;
                _videoPreviewReady = false;
                SyncHostedMediaAirspace();
                if (_videoHost == null || _videoHost.Visibility != Visibility.Visible || Math.Abs(_videoHost.Opacity) > 0.001)
                    return SelfTestFail("SelfTestMediaPresentation assertion 6: incoming native video is not warm-rendered at opacity zero");

                // R61.106.3: the outgoing raw visualizer frame remains visible while the new
                // decoder warms, then the incoming preview replaces this Image.Source on frame 1.
                if (_visualizerFrameHost == null) return SelfTestFail("SelfTestMediaPresentation assertion 6b: visualizer frame surface missing");
                _visualizerEnabled = true;
                _visualizerNativePreviewActive = false;
                _visualizerPreviewReady = false;
                _visualizerBridgeHold = true;
                _visualizerFrameHost.Source = testBitmap;
                SyncHostedMediaAirspace();
                if (_visualizerFrameHost.Visibility != Visibility.Visible)
                    return SelfTestFail("SelfTestMediaPresentation assertion 6b: outgoing visualizer frame is not retained through decoder warmup");

                MediaElement samePresenter = _videoHost;
                _largeVideoArea = true;
                ReparentVideoPresenter();
                Grid largeSurface = LargeVideoAreaSurface();
                if (largeSurface == null || !Object.ReferenceEquals(_videoPane.Parent, largeSurface) || !Object.ReferenceEquals(samePresenter, _videoHost))
                    return SelfTestFail("SelfTestMediaPresentation assertion 7: Large Video Area created/replaced the presenter instead of reparenting it");
                _largeVideoArea = false;
                ReparentVideoPresenter();
                if (!Object.ReferenceEquals(_videoPane.Parent, _mediaContentGrid) || !Object.ReferenceEquals(samePresenter, _videoHost))
                    return SelfTestFail("SelfTestMediaPresentation assertion 8: presenter did not survive return to Now Playing rack");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("SelfTestMediaPresentation assertion 9 exception: " + ex.GetType().Name + ": " + ex.Message); }
            finally
            {
                _mediaMode = oldMode;
                _mediaPairLayout = oldPairLayout;
                _mediaRackSize = oldRackSize;
                _artworkScaleFilter = oldArtFilter;
                _videoScaleFilter = oldVideoFilter;
                _videoBackdropMode = oldBackdropMode;
                _mediaStageKind = oldStageKind;
                _mediaStageFullscreen = oldStageFullscreen;
                _largeVideoArea = oldLarge;
                _videoAuthoritativelyAbsent = oldAbsent;
                _videoPresentedAspect = oldAspect;
                _videoPreviewBackend = oldBackend;
                _videoNativePreviewActive = oldNative;
                _videoPreviewReady = oldReady;
                _queueCanvasActive = oldQueueCanvasForTest;
                _adaptiveLayoutTier = oldAdaptiveTierForTest;
                _visualizerBridgeHold = oldVisualizerBridgeHold;
                _visualizerPreviewReady = oldVisualizerReady;
                _visualizerNativePreviewActive = oldVisualizerNative;
                _visualizerEnabled = oldVisualizerEnabled;
                if (_visualizerFrameHost != null) { _visualizerFrameHost.Source = oldVisualizerSource; _visualizerFrameHost.Visibility = oldVisualizerVisibility; }
                ReparentVideoPresenter();
                ApplyMediaMode(false);
                SyncHostedMediaAirspace();
            }
        }

        public bool SelfTestQueueConfidence()
        {
            _selfTestFailureDetail = "";
            try
            {
                var full = new RuntimeQueueItem { Audio="READY", Artwork="READY", Video="READY", Visualizer="READY", TransitionReady=true, PresentationComplete=true };
                string fullNote = QueueConfidenceNote("READY", "FULL READY", full, 2);
                if (!String.IsNullOrWhiteSpace(fullNote)) return SelfTestFail("SelfTestQueueConfidence assertion 1: expected empty note; actual='" + fullNote + "'");
                var audioReady = new RuntimeQueueItem { Audio="READY", Artwork="ACTIVE", Video="NOT_REQUIRED", Visualizer="NOT_REQUIRED", TransitionReady=true, PresentationComplete=false };
                string audioReadyNote = QueueConfidenceNote("AUDIO READY", "AUDIO READY", audioReady, 2);
                if (audioReadyNote.IndexOf("artwork is still catching up", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 2: expected specific artwork waiting note; actual='" + audioReadyNote + "'");
                var late = new RuntimeQueueItem { Audio="READY", Artwork="ACTIVE", HasSlack=true, SlackSeconds=-8, TransitionReady=false };
                string lateNote = QueueConfidenceNote("BUILDING", "SLACK -8s", late, 2);
                if (lateNote.IndexOf("audio remains priority", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 3: actual='" + lateNote + "'");
                var isolated = new RuntimeQueueItem { Audio="READY", Artwork="DEFERRED_CIRCUIT", TransitionReady=true, PresentationComplete=true };
                string isolatedNote = QueueConfidenceNote("ISOLATED READY", "ISOLATED READY", isolated, 2);
                if (isolatedNote.IndexOf("fault contained", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 4: actual='" + isolatedNote + "'");
                var fallback = new RuntimeQueueItem { Audio="READY", Artwork="READY", Video="READY", Visualizer="READY", TransitionReady=true, PresentationComplete=true, VideoFallback=true, VideoActualHeight=360 };
                string fallbackNote = QueueConfidenceNote("READY", "FULL READY", fallback, 2);
                if (fallbackNote.IndexOf("360p", StringComparison.OrdinalIgnoreCase) < 0) return SelfTestFail("SelfTestQueueConfidence assertion 5: actual='" + fallbackNote + "'");
                string playedNote = QueueConfidenceNote("PLAYED", "", late, -1);
                if (!String.IsNullOrWhiteSpace(playedNote)) return SelfTestFail("SelfTestQueueConfidence assertion 6: expected empty note; actual='" + playedNote + "'");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("SelfTestQueueConfidence assertion 7 exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public void OpenSettingsInitial() { OpenIntegratedSettings(); }

        private void OpenSettingsTab(int tabIndex, FrameworkElement focus, string status)
        {
            OpenIntegratedSettings();
            if (_settingsTabs != null && tabIndex >= 0 && tabIndex < _settingsTabs.Items.Count) _settingsTabs.SelectedIndex = tabIndex;
            if (!String.IsNullOrWhiteSpace(status) && _settingsStatusText != null) _settingsStatusText.Text = status;
            if (focus != null)
            {
                ExpandSettingsAncestors(focus);
                _window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    try { ExpandSettingsAncestors(focus); focus.BringIntoView(); focus.Focus(); } catch { }
                }), DispatcherPriority.Background);
            }
        }

        private static void ExpandSettingsAncestors(FrameworkElement focus)
        {
            DependencyObject current = focus;
            for (int guard = 0; current != null && guard < 32; guard++)
            {
                Expander expander = current as Expander;
                if (expander != null) expander.IsExpanded = true;
                DependencyObject next = null;
                try { next = LogicalTreeHelper.GetParent(current); } catch { }
                if (next == null)
                {
                    try { next = VisualTreeHelper.GetParent(current); } catch { }
                }
                current = next;
            }
        }

        private void OpenObsQuickSetup()
        {
            if (_settingsObsAdvancedExpander != null) _settingsObsAdvancedExpander.IsExpanded = false;
            if (_settingsBroadcastCustomizeExpander != null) _settingsBroadcastCustomizeExpander.IsExpanded = true;
            OpenSettingsTab(1, _settingsObsCopyPrimaryButton, "");
            RefreshObsQuickSetup();
        }
        private void OpenBroadcastSettings() { if (_settingsBroadcastCustomizeExpander != null) _settingsBroadcastCustomizeExpander.IsExpanded = true; if (_settingsObsAdvancedExpander != null) _settingsObsAdvancedExpander.IsExpanded = false; OpenSettingsTab(1, _settingsBroadcastPreset, ""); }
        private void OpenBroadcastComposition() { if (_settingsBroadcastCustomizeExpander != null) _settingsBroadcastCustomizeExpander.IsExpanded = true; OpenSettingsTab(1, _settingsOutput1Modules, ""); }
        private void OpenBroadcastVisualizer() { if (_settingsBroadcastCustomizeExpander != null) _settingsBroadcastCustomizeExpander.IsExpanded = true; OpenSettingsTab(1, _settingsVisualizerEnabled, ""); }

        private static double EffectiveFullWidthFloor(Rect work)
        {
            // R61.67 fluid desktop contract: the full player is allowed to become genuinely compact.
            // Individual controls own their own irreducible minimums; the shell should not reserve dead width.
            return Math.Min(FullPlayerMinWidth, Math.Max(360.0, work.Width));
        }

        private static double EffectiveFullHeightFloor(Rect work)
        {
            return Math.Min(FullPlayerMinHeight, Math.Max(FullPlayerMinHeight, work.Height));
        }

        private void ExpandCompactHostForOverlay()
        {
            if (_overlayExpandedCompactHost || _window.WindowState != WindowState.Normal) return;
            Rect work = CurrentWorkAreaDips();
            // R61.48: tool surfaces are workstation surfaces. They grow the host deliberately,
            // independently of Mini/compact player geometry, then restore it exactly on close.
            double targetWidth = Math.Min(ToolHostPreferredWidth, Math.Max(760.0, work.Width - 24));
            double targetHeight = Math.Min(ToolHostPreferredHeight, Math.Max(500.0, work.Height - 24));
            if (!_miniMode && _window.ActualWidth >= targetWidth - 1 && _window.ActualHeight >= targetHeight - 1) return;
            _overlayExpandedCompactHost = true;
            _overlayHostWidth = _window.Width; _overlayHostHeight = _window.Height;
            _overlayHostLeft = _window.Left; _overlayHostTop = _window.Top;
            _overlayHostMinWidth = _window.MinWidth; _overlayHostMinHeight = _window.MinHeight;
            double width = targetWidth;
            double height = targetHeight;
            _internalGeometryChange = true;
            try
            {
                _window.MinWidth = Math.Min(EffectiveFullWidthFloor(work), width);
                _window.MinHeight = Math.Min(EffectiveFullHeightFloor(work), height);
                _window.Width = width; _window.Height = height;
                _window.Left = Math.Max(work.Left, Math.Min(_overlayHostLeft, work.Right - width));
                _window.Top = Math.Max(work.Top, Math.Min(_overlayHostTop, work.Bottom - height));
            }
            finally { _internalGeometryChange = false; }
            ApplyCompactLayoutForSize();
        }

        private void RestoreCompactHostAfterOverlay()
        {
            if (!_overlayExpandedCompactHost) return;
            _overlayExpandedCompactHost = false;
            if (_window.WindowState != WindowState.Normal) return;
            Rect work = CurrentWorkAreaDips();
            double width = Math.Max(1, _overlayHostWidth);
            double height = Math.Max(1, _overlayHostHeight);
            _internalGeometryChange = true;
            try
            {
                _window.MinWidth = _overlayHostMinWidth > 0 ? _overlayHostMinWidth : (_miniMode ? MicroPlayerMinWidth : EffectiveFullWidthFloor(CurrentWorkAreaDips()));
                _window.MinHeight = _overlayHostMinHeight > 0 ? _overlayHostMinHeight : (_miniMode ? MicroPlayerMinHeight : EffectiveFullHeightFloor(CurrentWorkAreaDips()));
                _window.Width = width; _window.Height = height;
                _window.Left = Math.Max(work.Left, Math.Min(_overlayHostLeft, work.Right - width));
                _window.Top = Math.Max(work.Top, Math.Min(_overlayHostTop, work.Bottom - height));
            }
            finally { _internalGeometryChange = false; }
            ApplyCompactLayoutForSize();
        }

        private void CaptureSettingsNavigationMemory()
        {
            if (_settingsTabs != null) _settingsRememberedTab = Math.Max(0, Math.Min(2, _settingsTabs.SelectedIndex));
            if (_settingsEverydayScroll != null) _settingsRememberedEverydayOffset = Math.Max(0.0, _settingsEverydayScroll.VerticalOffset);
            if (_settingsBroadcastScroll != null) _settingsRememberedBroadcastOffset = Math.Max(0.0, _settingsBroadcastScroll.VerticalOffset);
            if (_settingsPerformanceScroll != null) _settingsRememberedPerformanceOffset = Math.Max(0.0, _settingsPerformanceScroll.VerticalOffset);
        }

        private void RestoreSettingsNavigationMemory()
        {
            if (_settingsTabs == null) return;
            _settingsTabs.SelectedIndex = Math.Max(0, Math.Min(2, _settingsRememberedTab));
            _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(delegate
            {
                if (_settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible) return;
                if (_settingsEverydayScroll != null) _settingsEverydayScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedEverydayOffset));
                if (_settingsBroadcastScroll != null) _settingsBroadcastScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedBroadcastOffset));
                if (_settingsPerformanceScroll != null) _settingsPerformanceScroll.ScrollToVerticalOffset(Math.Max(0.0, _settingsRememberedPerformanceOffset));
                UpdateSettingsContextBand();
                ScheduleSettingsSectionCartography();
            }));
        }

        private Button CreateSettingsWindowButton(bool closeButton)
        {
            var button = new Button { Focusable = false };
            object style = _app.TryFindResource(closeButton ? "CloseWindowChromeButton" : "WindowChromeButton");
            if (style is Style) button.Style = (Style)style;
            System.Windows.Shell.WindowChrome.SetIsHitTestVisibleInChrome(button, true);
            return button;
        }

        private static Grid SettingsWindowGlyph(string kind)
        {
            var grid = new Grid { Width = 14, Height = 14, Margin = new Thickness(0, -1, 0, 1), SnapsToDevicePixels = true };
            if (String.Equals(kind, "min", StringComparison.OrdinalIgnoreCase))
            {
                grid.Children.Add(new System.Windows.Shapes.Path { Data = Geometry.Parse("M 2,7 L 12,7"), StrokeThickness = 1.2, Stretch = Stretch.None, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center });
            }
            else if (String.Equals(kind, "max", StringComparison.OrdinalIgnoreCase))
            {
                grid.Children.Add(new System.Windows.Shapes.Path { Data = Geometry.Parse("M 3,3 L 13,3 13,13 3,13 Z"), StrokeThickness = 1.0, Fill = Brushes.Transparent, Stretch = Stretch.None, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center });
            }
            else if (String.Equals(kind, "restore", StringComparison.OrdinalIgnoreCase))
            {
                grid.Children.Add(new System.Windows.Shapes.Path { Data = Geometry.Parse("M 5,3 L 13,3 13,11 M 3,5 L 11,5 11,13 3,13 Z"), StrokeThickness = 1.0, Fill = Brushes.Transparent, Stretch = Stretch.None, HorizontalAlignment = HorizontalAlignment.Center, VerticalAlignment = VerticalAlignment.Center });
            }
            else
            {
                grid.Children.Add(new System.Windows.Shapes.Path { Data = Geometry.Parse("M 3,3 L 11,11"), StrokeThickness = 1.2 });
                grid.Children.Add(new System.Windows.Shapes.Path { Data = Geometry.Parse("M 11,3 L 3,11"), StrokeThickness = 1.2 });
            }
            foreach (System.Windows.Shapes.Path path in grid.Children.OfType<System.Windows.Shapes.Path>())
                path.SetBinding(System.Windows.Shapes.Shape.StrokeProperty, new Binding("Foreground") { RelativeSource = new RelativeSource(RelativeSourceMode.FindAncestor, typeof(Button), 1) });
            return grid;
        }

        private void CaptureDetachedSettingsWindowGeometry()
        {
            if (_settingsWindow == null || !_settingsWindow.IsVisible || _settingsWindow.WindowState != WindowState.Normal) return;
            _settingsWindowLeft = _settingsWindow.Left;
            _settingsWindowTop = _settingsWindow.Top;
            _settingsWindowWidth = Math.Max(760.0, _settingsWindow.Width);
            _settingsWindowHeight = Math.Max(500.0, _settingsWindow.Height);
        }

        private void ActivateDetachedSettingsWindow()
        {
            if (_settingsWindow == null) return;
            // R61.106.52.1: WPF forbids assigning Owner before the owner Window has ever been shown.
            // Settings is constructed during controller initialization, before _window.Show(), so bind
            // ownership only when Settings is actually activated and the main shell is already visible.
            if (_settingsWindow.Owner == null && _window != null && _window.IsVisible)
            {
                try { _settingsWindow.Owner = _window; } catch (InvalidOperationException) { }
            }
            if (_settingsWindow.WindowState == WindowState.Minimized) _settingsWindow.WindowState = WindowState.Normal;
            if (!_settingsWindow.IsVisible) _settingsWindow.Show();
            _settingsWindow.Activate();
        }

