            if (!Double.IsNaN(_settingsWindowLeft) && !Double.IsInfinity(_settingsWindowLeft)) _settingsWindow.Left = _settingsWindowLeft;
            else _settingsWindow.Left = _window.Left + 40.0;
            if (!Double.IsNaN(_settingsWindowTop) && !Double.IsInfinity(_settingsWindowTop)) _settingsWindow.Top = _settingsWindowTop;
            else _settingsWindow.Top = _window.Top + 40.0;
            try { _settingsWindow.Icon = _window.Icon; } catch { }
            System.Windows.Shell.WindowChrome.SetWindowChrome(_settingsWindow, new System.Windows.Shell.WindowChrome
            {
                CaptionHeight = 25.0, ResizeBorderThickness = new Thickness(4), GlassFrameThickness = new Thickness(0), CornerRadius = new CornerRadius(0), UseAeroCaptionButtons = false
            });
            _settingsWindow.SourceInitialized += delegate
