        private Dictionary<string, object> ReadJsonFresh(string path)
        {
            try { if (File.Exists(path)) return AsMap(_json.DeserializeObject(ReadTextShared(path))); } catch { }
            return EmptyMap();
        }

        private AppearancePreset ParseAppearance(string s)
        {
            s = (s ?? "").Trim();
            if (s.StartsWith("Midnight", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Midnight;
            if (s.StartsWith("Graphite", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Graphite;
            if (s.StartsWith("Carbon", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.CarbonViolet;
            if (s.StartsWith("Ember", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Ember;
            if (s.StartsWith("Dusk", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Dusk;
            if (s.StartsWith("Slate", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Slate;
            if (s.StartsWith("Moss", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Moss;
            if (s.StartsWith("Rosewood", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Rosewood;
            if (s.StartsWith("Plum", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Plum;
            if (s.StartsWith("Orchid", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Orchid;
            if (s.StartsWith("Harbor", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Harbor;
            if (s.StartsWith("Sage", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Sage;
            if (s.StartsWith("Lavender", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Lavender;
            if (s.StartsWith("Blush", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Blush;
            if (s.StartsWith("Champagne", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Champagne;
            if (s.StartsWith("Paper", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.Paper;
            if (s.StartsWith("High", StringComparison.OrdinalIgnoreCase)) return AppearancePreset.HighContrast;
            return AppearancePreset.Midnight;
        }

        private static bool SettingsThemeFollowsWindows(string value)
        {
            string text = (value ?? "").Trim();
            return text.StartsWith("System Theme", StringComparison.OrdinalIgnoreCase) || text.StartsWith("Follow Windows", StringComparison.OrdinalIgnoreCase);
        }

        private void CycleSettingsTheme(int delta)
        {
            if (_settingsTheme == null || _settingsTheme.Items.Count == 0) return;
            int count = _settingsTheme.Items.Count;
            int index = _settingsTheme.SelectedIndex;
            if (index < 0) index = 0;
            index = (index + delta) % count;
            if (index < 0) index += count;
            _settingsTheme.SelectedIndex = index;
            _settingsTheme.Focus();
        }

        private static ThemeIntensity ParseThemeIntensity(string raw)
        {
            ThemeIntensity value; return Enum.TryParse<ThemeIntensity>((raw ?? "").Trim(), true, out value) ? value : ThemeIntensity.Soft;
        }

        private static ThemeBlendStrength ParseThemeBlendStrength(string raw)
        {
            ThemeBlendStrength value; return Enum.TryParse<ThemeBlendStrength>((raw ?? "").Trim(), true, out value) ? value : ThemeBlendStrength.Balanced;
        }

        private void UpdateSettingsSliderLabels()
        {
            if (_settingsThemeIntensityValueText != null && _settingsThemeIntensitySlider != null) _settingsThemeIntensityValueText.Text = Math.Round(_settingsThemeIntensitySlider.Value).ToString(CultureInfo.InvariantCulture) + "%";
            if (_settingsThemeBlendValueText != null && _settingsThemeBlendSlider != null) _settingsThemeBlendValueText.Text = Math.Round(_settingsThemeBlendSlider.Value).ToString(CultureInfo.InvariantCulture) + "%";
            if (_settingsWindowTransparencyValueText != null && _settingsWindowTransparencySlider != null) _settingsWindowTransparencyValueText.Text = Math.Round(_settingsWindowTransparencySlider.Value).ToString(CultureInfo.InvariantCulture) + "%";
            if (_settingsPrefetchValueText != null && _settingsPrefetchSlider != null) _settingsPrefetchValueText.Text = Math.Round(_settingsPrefetchSlider.Value).ToString(CultureInfo.InvariantCulture);
            if (_settingsCacheBudgetValueText != null && _settingsCacheBudgetSlider != null) _settingsCacheBudgetValueText.Text = Math.Round(_settingsCacheBudgetSlider.Value).ToString(CultureInfo.InvariantCulture) + " MB";
            if (_settingsCacheWorkersValueText != null && _settingsCacheWorkersSlider != null) _settingsCacheWorkersValueText.Text = Math.Round(_settingsCacheWorkersSlider.Value).ToString(CultureInfo.InvariantCulture);
        }

        private static ThemeIntensity ThemeIntensityFromAmount(double amount)
        {
            return amount >= 0.75 ? ThemeIntensity.Vivid : (amount >= 0.30 ? ThemeIntensity.Rich : ThemeIntensity.Soft);
        }

        private static ThemeBlendStrength ThemeBlendFromAmount(double amount)
        {
            return amount >= 0.75 ? ThemeBlendStrength.Strong : (amount >= 0.45 ? ThemeBlendStrength.Balanced : ThemeBlendStrength.Subtle);
        }

        private void HandleSettingsThemeCompositionChanged()
        {
            if (_settingsThemeIntensity == null || _settingsThemeAccent == null || _settingsThemeBlend == null) return;
            RefreshStyledComboForeground(_settingsThemeAccent);
            ApplySettingsThemePreview();
        }

        private void HandleSettingsThemeSelectionChanged()
        {
            if (_settingsTheme == null) return;
            bool reopen = _settingsTheme.IsDropDownOpen || _settingsTheme.IsKeyboardFocusWithin;
            RefreshStyledComboForeground(_settingsTheme);
            ApplySettingsThemePreview();
            if (reopen && _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible)
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Input, new Action(delegate
                {
                    if (_settingsTheme != null && _settingsTheme.IsEnabled) _settingsTheme.IsDropDownOpen = true;
                }));
            }
        }

        private void ApplySettingsThemePreview()
        {
            if (_settingsTheme == null) return;
            string draft = ComboText(_settingsTheme, _appearanceManuallySelected ? AppearanceLabel(_appearancePreset) : "System Theme");
            bool followWindows = SettingsThemeFollowsWindows(draft);
            AppearancePreset preview = followWindows ? ResolveSystemAppearancePreset() : ParseAppearance(draft);
            _appearanceManuallySelected = !followWindows;
            _appearancePreset = preview;
            _themeIntensityAmount = _settingsThemeIntensitySlider == null ? (_themeIntensity == ThemeIntensity.Vivid ? 1.0 : (_themeIntensity == ThemeIntensity.Rich ? 0.50 : 0.0)) : Math.Max(0.0, Math.Min(1.0, _settingsThemeIntensitySlider.Value / 100.0));
            _themeIntensity = ThemeIntensityFromAmount(_themeIntensityAmount);
            string accentText = ComboText(_settingsThemeAccent, "None");
            _appearanceAccentEnabled = !String.Equals(accentText, "None", StringComparison.OrdinalIgnoreCase);
            if (_appearanceAccentEnabled) _appearanceAccentPreset = ParseAppearance(accentText);
            _themeBlendAmount = _settingsThemeBlendSlider == null ? (_themeBlendStrength == ThemeBlendStrength.Strong ? 0.85 : (_themeBlendStrength == ThemeBlendStrength.Subtle ? 0.35 : 0.60)) : Math.Max(0.0, Math.Min(1.0, _settingsThemeBlendSlider.Value / 100.0));
            _themeBlendStrength = ThemeBlendFromAmount(_themeBlendAmount);
            ApplyAppearancePreset(false);
            UpdateSettingsThemePreviewChrome(preview, followWindows);
        }

        private void UpdateSettingsThemePreviewChrome(AppearancePreset preset, bool followWindows)
        {
            if (_settingsThemeHint != null)
            {
                string prefix = followWindows ? "System theme · currently " + AppearanceLabel(preset) + ". " : "";
                string composition = " " + Math.Round(_themeIntensityAmount * 100.0).ToString(CultureInfo.InvariantCulture) + "% intensity" + (_appearanceAccentEnabled ? " · " + AppearanceLabel(_appearanceAccentPreset) + " accent · " + Math.Round(_themeBlendAmount * 100.0).ToString(CultureInfo.InvariantCulture) + "% blend." : ".");
                _settingsThemeHint.Text = prefix + AppearanceDescription(preset) + composition + " Save keeps it; Close or Esc restores the saved appearance.";
            }
        }
        private WorkspaceProfile ParseWorkspace(string s) { if (String.Equals((s ?? "").Trim(), "Mini Player", StringComparison.OrdinalIgnoreCase)) return WorkspaceProfile.Micro; WorkspaceProfile v; return Enum.TryParse<WorkspaceProfile>(s, true, out v) ? v : WorkspaceProfile.Player; }
        private InformationDensity ParseDensity(string s)
        {
            if (String.Equals((s ?? "").Trim(), "Simple", StringComparison.OrdinalIgnoreCase)) return InformationDensity.Clean;
            InformationDensity v;
            return Enum.TryParse<InformationDensity>(s, true, out v) ? (v == InformationDensity.Balanced ? InformationDensity.Clean : v) : InformationDensity.Clean;
        }

        private void SetSettingsSaveBusy(bool busy)
        {
            _settingsSaveInFlight = busy;
            if (_settingsTabs != null) _settingsTabs.IsEnabled = true; // Saving is geometry/appearance neutral; do not flash the entire Settings tree disabled.
            if (_settingsCloseButton != null) _settingsCloseButton.IsEnabled = !busy;
            if (_settingsResetButton != null) _settingsResetButton.IsEnabled = !busy;
            if (_settingsUndoButton != null) _settingsUndoButton.IsEnabled = !busy && _settingsUndo.Count > 0;
            if (_settingsRedoButton != null) _settingsRedoButton.IsEnabled = !busy && _settingsRedo.Count > 0;
        }

        private void ApplyFactoryControllerDefaults(Dictionary<string, object> config)
        {
            BeginUiStateTransaction();
            try
            {
                if (_queueOpen) SetQueueOpen(false, false);
                _largeVideoArea = false;
                _videoBackdropMode = VideoBackdropMode.Off;
                _mediaStageKind = MediaStageKind.None;
                _mediaStageFullscreen = false;
                _compactControllerMode = false;
                _mediaPairLayout = MediaPairLayout.TopBottom;
                _mediaRackSize = MediaRackSize.Fit;
                _artworkScaleFilter = MediaScaleFilter.Bicubic;
                _videoScaleFilter = MediaScaleFilter.Bilinear;
                _artworkPresentation = ArtworkPresentation.Cropped;
                _visualizerPresentation = VisualizerPresentation.Standard;
                // Fresh/factory controller defaults are intentionally presentation-light. OBS remains
                // independently configurable; these flags govern only what the controller itself shows.
                _visualizerEnabled = false;
                _mediaMode = MediaMode.Off;

                _queueScope = QueueScope.All;
                _queueDensity = QueueDensity.Dense;
                _queuePlayerDock = QueuePlayerDock.Top;
                _queuePlayerHeight = 176.0;
                _queueFollowCurrent = true;
                _queueTableFavoriteWidth = 20.0; _queueTableNumberWidth = 28.0; _queueTableTitleWidth = 360.0; _queueTableChannelWidth = 240.0;
                _queueTableTimeWidth = 72.0; _queueTableStateWidth = 100.0; _queueTableMediaWidth = 94.0; _queueTablePlaysWidth = 58.0;
                _queueTableFavoriteVisible = true; _queueTableNumberVisible = true; _queueTableChannelVisible = true; _queueTableTimeVisible = true;
                _queueTableStateVisible = true; _queueTableMediaVisible = true; _queueTablePlaysVisible = true;
                _workspaceContexts.Clear();
                ClearPendingQueueInteractionContext();
                _inspectorOpen = true;
                _lastFullWorkspaceProfile = WorkspaceProfile.Player;
                _previousFullWorkspaceProfile = WorkspaceProfile.Player;
                _compactQueueReturnProfile = WorkspaceProfile.Custom;
                _slotBroadcastFollowEnabled = false;
                _settingsRememberedTab = 0; _settingsRememberedEverydayOffset = 0; _settingsRememberedBroadcastOffset = 0; _settingsRememberedPerformanceOffset = 0;
                _showTotalTime = false;
                _recentCommandTitles.Clear();

                _normalWidth = FullPlayerDefaultWidth; _normalHeight = FullPlayerDefaultHeight;
                _queueWorkbenchWidth = FullPlayerDefaultWidth; _queueWorkbenchHeight = QueueWorkbenchMinHeight;
                _compactControllerWidth = CompactControllerDefaultWidth; _compactControllerHeight = CompactControllerDefaultHeight;
                // Settings can temporarily enlarge a compact host. Replace its return rectangle too,
                // otherwise closing Settings would resurrect the pre-reset window geometry.
                if (_overlayExpandedCompactHost)
                {
                    _overlayHostWidth = FullPlayerDefaultWidth; _overlayHostHeight = FullPlayerDefaultHeight;
                    _overlayHostLeft = _window.Left; _overlayHostTop = _window.Top;
                    _overlayHostMinWidth = FullPlayerMinWidth; _overlayHostMinHeight = FullPlayerMinHeight;
                }

                _volume = 100.0; _muted = false; _volumePreferenceLoaded = true; ApplyVolumeUi();
                if (_running)
                {
                    SendMpv("set_property", "volume", "100");
                    SendMpv("set_property", "mute", "false");
                }

                _themeIntensity = ThemeIntensity.Vivid; _themeIntensityAmount = 1.0; _appearanceAccentEnabled = false; _appearanceAccentPreset = AppearancePreset.Dusk; _themeBlendStrength = ThemeBlendStrength.Balanced; _themeBlendAmount = 0.60; _windowTransparencyPercent = 10.0; if (_window != null) _window.Opacity = 1.0;
                SetSystemAppearanceMode(false);
                SetInformationDensity(InformationDensity.Clean, false);
                SetQuietSurface(true, false);
                SetMenuBarVisible(true, false);
                SetTitleBarVisible(true, false);
                SetReduceMotion(false, false);

                _microMode = false; _miniMode = false; _performanceWorkspace = false;
                ApplyWorkspaceProfile(WorkspaceProfile.Player, false);
                SetQueueOpen(true, false);
                _inspectorOpen = true;
                ApplyInspectorVisibility();
                if (_window != null && _window.WindowState == WindowState.Normal)
                {
                    _internalGeometryChange = true;
                    try { _window.Width = FullPlayerDefaultWidth; _window.Height = FullPlayerDefaultHeight; }
                    finally { _internalGeometryChange = false; }
                    ConstrainWindowToVisibleWorkArea();
                }
                ApplyArtworkCropPreference();
                ApplyMediaScaleFiltering();
                ApplyMediaMode(false);
                ApplyVisualizerPresentation(false);
                ApplyAdaptiveLayout(true);
                ApplyQueueCanvasLayout(false);
                ApplyQueueTableColumnFit();
                UpdateProgressVisual();
            }
            finally { EndUiStateTransaction(true); }
        }

