                requestedThemeIntensityAmount = _settingsThemeIntensitySlider == null ? _themeIntensityAmount : Math.Max(0.0, Math.Min(1.0, _settingsThemeIntensitySlider.Value / 100.0));
                requestedThemeIntensity = ThemeIntensityFromAmount(requestedThemeIntensityAmount);
