                requestedThemeBlendAmount = _settingsThemeBlendSlider == null ? _themeBlendAmount : Math.Max(0.0, Math.Min(1.0, _settingsThemeBlendSlider.Value / 100.0));
                requestedThemeBlend = ThemeBlendFromAmount(requestedThemeBlendAmount);
                requestedDensity = ParseDensity(ComboText(_settingsDetail, _informationDensity.ToString()));
                quiet = true; classicMenu = Checked(_settingsClassicMenu); reduceMotion = false;
