                return;
            }

            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                string action = ""; string failure = "";
                try { action = ApplyIntegratedConfigTransaction(c); }
                catch (Exception ex) { failure = ex.Message; }
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        SetSettingsSaveBusy(false);
                        if (!String.IsNullOrWhiteSpace(failure))
                        {
                            _settingsStatusText.Text = "Could not save: " + failure;
                            SetSettingsSaveBusy(false);
                            _settingsSaveButton.IsEnabled = true;
                            ShowToast("Settings", "Could not save settings.");
                            return;
                        }
                        _jsonCache.Clear();
                        if (factoryResetPending) ApplyFactoryControllerDefaults(c);
                        _settingsFactoryResetPending = false;
                        _settingsStatusText.Text = factoryResetPending ? "Factory settings restored. User data was preserved." : (String.Equals(action, "NOOP", StringComparison.OrdinalIgnoreCase) ? "No changes to save." : "Saved and applied.");
                        if (requestedWorkspace == WorkspaceProfile.Custom) _workspaceProfile = WorkspaceProfile.Custom;
                        else if (requestedWorkspace != _workspaceProfile) ApplyWorkspaceProfile(requestedWorkspace, false);
                        if (_appearanceManuallySelected != requestedAppearanceManual || _appearancePreset != requestedAppearance ||
                            _themeIntensity != requestedThemeIntensity || Math.Abs(_themeIntensityAmount - requestedThemeIntensityAmount) > 0.001 || _appearanceAccentEnabled != requestedAppearanceAccentEnabled ||
                            _appearanceAccentPreset != requestedAppearanceAccent || _themeBlendStrength != requestedThemeBlend || Math.Abs(_themeBlendAmount - requestedThemeBlendAmount) > 0.001 || Math.Abs(_windowTransparencyPercent - requestedWindowTransparency) > 0.01)
                        {
                            _appearanceManuallySelected = requestedAppearanceManual;
                            _appearancePreset = requestedAppearance;
                            _themeIntensity = requestedThemeIntensity;
                            _themeIntensityAmount = requestedThemeIntensityAmount;
                            _appearanceAccentEnabled = requestedAppearanceAccentEnabled;
                            _appearanceAccentPreset = requestedAppearanceAccent;
                            _themeBlendStrength = requestedThemeBlend;
                            _themeBlendAmount = requestedThemeBlendAmount;
                            _windowTransparencyPercent = requestedWindowTransparency;
                            ApplyAppearancePreset(false);
                        }
                        if (_informationDensity != requestedDensity) SetInformationDensity(requestedDensity, false);
                        if (_quietSurface != quiet) SetQuietSurface(quiet, false);
                        if (_menuBarVisible != classicMenu) SetMenuBarVisible(classicMenu, false);
                        if (_reduceMotion != reduceMotion) SetReduceMotion(reduceMotion, false);
                        _visualizerShape = GetString(c, "visualizer_shape", "Spectrum");
                        if (mediaConfigChanged) { ApplyArtworkCropPreference(); ApplyMediaMode(false); }
                        else ApplyVisualizerPresentation(false);
                        ClearSettingsLivePreview(); RefreshObsQuickSetup(); SaveUiState();
                        _settingsBaselineSnapshot = saveSnapshot; _settingsLastSnapshot = CaptureSettingsDraft(); _settingsDirty = !String.Equals(_settingsLastSnapshot, _settingsBaselineSnapshot, StringComparison.Ordinal); if (factoryResetPending) _settingsDirty = false; SetSettingsSaveBusy(false); _settingsSaveButton.IsEnabled = _settingsDirty; _settingsAppearanceAtOpen = _appearancePreset; _settingsAppearanceManualAtOpen = _appearanceManuallySelected; _settingsThemeIntensityAtOpen = _themeIntensity; _settingsThemeIntensityAmountAtOpen = _themeIntensityAmount; _settingsWindowTransparencyAtOpen = _windowTransparencyPercent; _settingsAppearanceAccentEnabledAtOpen = _appearanceAccentEnabled; _settingsAppearanceAccentAtOpen = _appearanceAccentPreset; _settingsThemeBlendAtOpen = _themeBlendStrength; _settingsThemeBlendAmountAtOpen = _themeBlendAmount; UpdateSettingsHistoryButtons(); UpdateSettingsThemePreviewChrome(_appearancePreset, !_appearanceManuallySelected);
                        if (visualizerConfigChanged && !_performanceWorkspace && _visualizerEnabled && !String.IsNullOrWhiteSpace(_lastVizPath))
                        {
                            // Keep the committed bitmap on screen while the replacement decoder warms.
                            // A Settings save may change pixels, never controller geometry or blank the backdrop.
                            _lastVizGeneration = "";
                            StartFramePreview(_lastVizPath, _timePosition, true, true);
                        }
                    });
                }
                catch { }
            });
        }

