            AddRepeatMenuItem(repeatMode, "Off", "off");
            AddRepeatMenuItem(repeatMode, "All", "all");
            AddRepeatMenuItem(repeatMode, "One", "one");
            repeatMode.SubmenuOpened += delegate { RefreshRepeatMenuChecks(repeatMode); };
            more.Items.Add(repeatMode);
            AddMenuItem(more, "Mini Player    Ctrl+M", delegate { SetMicroMode(!_microMode, true); });
            AddMenuItem(more, "Show menu bar    F10", delegate { SetMenuBarVisible(true, true); });
            AddMenuItem(more, "Appearance settings...", delegate { OpenAppearanceSettings(); });
            more.Items.Add(new Separator());
            AddMenuItem(more, "Session Manager...", delegate { OpenListeningSlots(); });
            AddMenuItem(more, "Playlist Pool...", delegate { OpenPlaylistPool(); });
            AddMenuItem(more, "Settings...", delegate { OpenIntegratedSettings(); });
            var help = new MenuItem { Header = "Help / shortcuts" };
            AddMenuItem(help, "Check for updates...", delegate { CheckForUpdates(); });
            AddMenuItem(help, "Keyboard shortcuts    F1", delegate { OpenShortcutPalette(); });
            more.Items.Add(help);
            AddMenuItem(more, "OBS / Broadcast settings", delegate { OpenBroadcastSettings(); });
            more.Items.Add(new Separator());
            AddMenuItem(more, "Open YOMI data folder", delegate { SafeStart("explorer.exe", Quote(_dataRoot)); });
            more.Items.Add(new Separator());
            AddMenuItem(more, "Hide to tray", delegate { HideToTray(); });
            AddMenuItem(more, "Stop YOMI and exit", delegate { StopYomiAndExit(); });
            more.Opened += delegate { RefreshWindowControllerMenuChecks(more.Items); };
            _moreButton.ContextMenu = more;
            _moreButton.Click += delegate
            {
                more.PlacementTarget = _moreButton;
                more.Placement = PlacementMode.Bottom;
                more.IsOpen = true;
            };
            WireShellContextMenu();
        }

        private void NormalizeObsPackageConfiguration()
        {
            // R61.106.52.5.1: OBS Integration + Media Prep is one package. Treat either legacy
            // half-on bit as ON instead of letting one stale field silently disable the other.
            // The .52 migration window could also rewrite a previously working Streamer/OBS
            // config to Player; recover that specific state once from config.json.previous.
            try
            {
                string path = Path.Combine(_dataRoot, "config.json");
                if (!File.Exists(path)) return;
                Dictionary<string, object> config = ReadJsonFresh(path);
                if (config.Count == 0) return;

                bool appEnabled = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
                bool prepEnabled = GetBool(config, "obs_media_cache_enabled", appEnabled);
                bool enabled = appEnabled || prepEnabled;
                int packageSchema = GetInt(config, "obs_package_state_schema", 0);

                if (!enabled && packageSchema < 2)
                {
                    bool affectedUiState = false;
                    try
                    {
                        Dictionary<string, object> ui = ReadJsonFresh(Path.Combine(_stateRoot, "controller-ui.json"));
                        int uiSchema = GetInt(ui, "schema", 0);
                        affectedUiState = uiSchema > 0 && uiSchema <= 48;
                    }
                    catch { }
                    if (affectedUiState)
                    {
                        Dictionary<string, object> previous = ReadJsonFresh(path + ".previous");
                        bool previousApp = String.Equals(GetString(previous, "app_mode", ""), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
                        bool previousPrep = GetBool(previous, "obs_media_cache_enabled", previousApp);
                        bool samePlaylist = String.Equals(GetString(previous, "playlist", ""), GetString(config, "playlist", ""), StringComparison.OrdinalIgnoreCase);
                        if (previous.Count > 0 && samePlaylist && (previousApp || previousPrep)) enabled = true;
                    }
                }

                bool changed = packageSchema < 2 || appEnabled != enabled || prepEnabled != enabled;
                if (!changed) return;
                config["app_mode"] = enabled ? "Streamer / OBS" : "Player";
                config["obs_media_cache_enabled"] = enabled;
                config["obs_package_state_schema"] = 2;
                WriteUtf8NoBom(path, _json.Serialize(config));
                _jsonCache.Clear();
            }
            catch { }
        }

        private bool ObsIntegrationEnabled()
        {
            Dictionary<string, object> config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            if (config.Count == 0) config = ReadJsonCached(Path.Combine(_appDir, "default-config.json"));
            return String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
        }

        private void SetObsIntegrationEnabled(bool enabled)
        {
            SetObsPackageEnabled(enabled);
        }

        private void SetObsPackageEnabled(bool enabled)
        {
            try
            {
                string path = Path.Combine(_dataRoot, "config.json");
                Dictionary<string, object> config = ReadJsonFresh(path);
                if (config.Count == 0) config = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));
                if (config.Count == 0) config = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                config["app_mode"] = enabled ? "Streamer / OBS" : "Player";
                config["obs_media_cache_enabled"] = enabled;
                WriteUtf8NoBom(path, _json.Serialize(config));
                _jsonCache.Clear();
                if (_settingsAppMode != null && _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible)
                    SetCombo(_settingsAppMode, enabled ? "Streamer / OBS" : "Player");
                if (_settingsObsMediaCache != null && _settingsOverlay != null && _settingsOverlay.Visibility == Visibility.Visible)
                    _settingsObsMediaCache.IsChecked = enabled;
                if (_obsMediaCacheToggle != null) _obsMediaCacheToggle.IsChecked = enabled;
                if (_running) SendMpv("script-message", "yomi-reload-config");
                UpdateStatusBarProjection();
                ShowToast("OBS", enabled ? "OBS integration and background media preparation are on." : "OBS integration and background media preparation are off.");
            }
            catch (Exception ex)
            {
                ShowToast("OBS", "Could not change the OBS package: " + ex.Message);
            }
        }

        private bool ObsMediaCacheEnabled()
        {
            Dictionary<string, object> config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            if (config.Count == 0) config = ReadJsonCached(Path.Combine(_appDir, "default-config.json"));
            return GetBool(config, "obs_media_cache_enabled", true);
        }

        private void SetObsMediaCacheEnabled(bool enabled)
        {
            SetObsPackageEnabled(enabled);
        }

        private void ApplyVisualizerQuickConfig(Action<Dictionary<string, object>> mutate)
        {
            try
            {
                string path = Path.Combine(_dataRoot, "config.json");
                Dictionary<string, object> config = ReadJsonFresh(path);
                if (config.Count == 0) config = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));
                if (config.Count == 0) config = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
                if (mutate != null) mutate(config);
                WriteUtf8NoBom(path, _json.Serialize(config));
                _jsonCache.Clear();
                _visualizerShape = GetString(config, "visualizer_shape", "Spectrum");
                _visualizerFramePreviewFps = GetString(config, "visualizer_fps", "30 FPS").StartsWith("60", StringComparison.OrdinalIgnoreCase) ? 60 : 30;
                _visualizerRawFrameWidth = NormalizeVisualizerAnalysisWidth(GetInt(config, "visualizer_internal_width", 180));
                _visualizerRawFrameHeight = NormalizeVisualizerAnalysisHeight(GetInt(config, "visualizer_internal_height", 36));
                // Palette/shape changes are geometry-neutral. The backdrop already owns a fixed
                // zero-authority layer; changing a visualizer setting must not touch shell layout.
                if (_visualizerBackdropImage != null) RenderOptions.SetBitmapScalingMode(_visualizerBackdropImage, BitmapScalingMode.NearestNeighbor);
                if (_running)
                {
                    SendMpv("script-message", "yomi-reload-config");
                    if (_currentOccurrence > 0) SendMpv("script-message", "yomi-prepare", _currentOccurrence.ToString(CultureInfo.InvariantCulture));
                }
                _lastVizGeneration = "";
                ScheduleFastPlaybackRefresh();
            }
            catch (Exception ex)
            {
                ShowToast("Visualizer", "Could not apply preview setting: " + ex.Message);
            }
        }

        private static void RefreshQuickChoiceChecks(MenuItem parent, object selectedTag)
        {
            if (parent == null) return;
            foreach (object raw in parent.Items)
            {
                MenuItem item = raw as MenuItem;
                if (item != null && item.IsCheckable) item.IsChecked = Object.Equals(item.Tag, selectedTag);
            }
        }

        private MenuItem VisualizerQuickChoice(MenuItem parent, string header, string tag, Action apply)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, Tag = tag, StaysOpenOnClick = true };
            item.Click += delegate { if (apply != null) apply(); RefreshQuickChoiceChecks(parent, tag); };
            parent.Items.Add(item);
            return item;
        }

        private void SetVisualizerPixelSizeChoice(string value)
        {
            int w, h; VisualizerPixelSizeDimensions(value, out w, out h);
            ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_internal_width"] = w; cfg["visualizer_internal_height"] = h; });
        }

        private MenuItem BuildVisualizerQuickMenu()
        {
            var root = new MenuItem { Header = "Visualizer" };
            root.SubmenuOpened += delegate
            {
                root.Items.Clear();
                Dictionary<string, object> c = ReadJsonFresh(Path.Combine(_dataRoot, "config.json"));
                if (c.Count == 0) c = ReadJsonFresh(Path.Combine(_appDir, "default-config.json"));

                var mode = new MenuItem { Header = "Color mode" };
                string currentMode = GetString(c, "visualizer_color_mode", "Solid");
                foreach (string value in new[] { "Solid", "Gradient", "Rainbow" })
                {
                    MenuItem item = VisualizerQuickChoice(mode, value, value, delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_color_mode"] = value; }); });
                    item.IsChecked = String.Equals(currentMode, value, StringComparison.OrdinalIgnoreCase);
                }
                root.Items.Add(mode);

                var colors = new MenuItem { Header = "Solid color" };
                string currentColor = GetString(c, "visualizer_solid_color", "#8A8A84");
                foreach (KeyValuePair<string,string> pair in VisualizerNamedColors)
                {
                    string name = pair.Key, hex = pair.Value;
                    MenuItem item = VisualizerQuickChoice(colors, name, hex, delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_solid_color"] = hex; cfg["visualizer_color_mode"] = "Solid"; }); });
                    try { Color color=ParseColor(hex); item.Foreground = new SolidColorBrush(color); item.Effect = LegibilityEffect(color); } catch { }
                    item.IsChecked = String.Equals(currentColor, hex, StringComparison.OrdinalIgnoreCase) && String.Equals(currentMode, "Solid", StringComparison.OrdinalIgnoreCase);
                }
                root.Items.Add(colors);

                var gradient = new MenuItem { Header = "Gradient" };
                string currentGradient = GetString(c, "visualizer_gradient_preset", "Sunset");
                foreach (string value in new[] { "Sunset", "Ocean", "Pastel", "Fire", "Forest", "Mono" })
                {
                    MenuItem item = VisualizerQuickChoice(gradient, value, value, delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_gradient_preset"] = value; cfg["visualizer_color_mode"] = "Gradient"; }); });
                    string ga,gb; GradientPresetColors(value,out ga,out gb); item.Foreground=GradientChoiceBrush(ga,gb); item.Effect=LegibilityEffect(ParseColor(ga));
                    item.IsChecked = String.Equals(currentGradient, value, StringComparison.OrdinalIgnoreCase) && String.Equals(currentMode, "Gradient", StringComparison.OrdinalIgnoreCase);
                }
                var orientation = new MenuItem { Header = "Direction" };
                string currentOrientation = GetString(c, "visualizer_gradient_orientation", "Horizontal");
                foreach (string value in new[] { "Horizontal", "Vertical" })
                {
                    MenuItem item = VisualizerQuickChoice(orientation, value, value, delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_gradient_orientation"] = value; }); });
                    item.IsChecked = String.Equals(currentOrientation, value, StringComparison.OrdinalIgnoreCase);
                }
                gradient.Items.Add(new Separator()); gradient.Items.Add(orientation);
                root.Items.Add(gradient);

                var pixels = new MenuItem { Header = "Pixel size" };
                string currentPixels = VisualizerPixelSizeChoice(GetInt(c, "visualizer_internal_width", 180), GetInt(c, "visualizer_internal_height", 36));
                foreach (string value in new[] { "Extra Chunky", "Chunky", "Fine", "Extra Fine" })
                {
                    MenuItem item = VisualizerQuickChoice(pixels, value, value, delegate { SetVisualizerPixelSizeChoice(value); });
                    item.IsChecked = String.Equals(currentPixels, value, StringComparison.OrdinalIgnoreCase);
                }
                root.Items.Add(pixels);

                Action<string,string,string[]> addTextChoices = delegate(string label, string key, string[] values)
                {
                    var menu = new MenuItem { Header = label };
                    string current = GetString(c, key, values.Length > 0 ? values[0] : "");
                    foreach (string rawValue in values)
                    {
                        string value = rawValue;
                        MenuItem item = VisualizerQuickChoice(menu, value, value, delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg[key] = value; }); });
                        item.IsChecked = String.Equals(current, value, StringComparison.OrdinalIgnoreCase);
                    }
                    root.Items.Add(menu);
                };
                addTextChoices("Activity", "visualizer_activity", new[] { "Subtle", "Normal", "Active" });
                addTextChoices("Fill quiet ranges", "visualizer_adaptive_fill", new[] { "Off", "Adaptive", "Aggressive" });
                addTextChoices("Frequency scale", "visualizer_frequency_scale", new[] { "Logarithmic", "Linear" });
                addTextChoices("Shape", "visualizer_shape", new[] { "Spectrum", "Center Mirror", "Oscilloscope", "Dots", "Skyline", "Particle Field", "Twin Rails" });
                addTextChoices("Bar spacing", "visualizer_bar_spacing", new[] { "None", "Light", "Wide" });
                addTextChoices("FPS", "visualizer_fps", new[] { "30 FPS", "60 FPS" });
                addTextChoices("Direction", "visualizer_direction", new[] { "Normal", "Mirrored" });
                addTextChoices("Vertical anchor", "visualizer_vertical_anchor", new[] { "Source", "Top", "Center", "Bottom" });

                var opacity = new MenuItem { Header = "Opacity" };
                double currentOpacity = GetDouble(c, "visualizer_opacity", 0.30);
                foreach (double value in new[] { 0.15, 0.20, 0.25, 0.30, 0.40, 0.50, 0.65, 0.80, 1.00 })
                {
                    double captured = value;
                    string label = Math.Round(value * 100).ToString(CultureInfo.InvariantCulture) + "%";
                    MenuItem item = VisualizerQuickChoice(opacity, label, value.ToString("0.00", CultureInfo.InvariantCulture), delegate { ApplyVisualizerQuickConfig(delegate(Dictionary<string, object> cfg) { cfg["visualizer_opacity"] = captured; }); });
                    item.IsChecked = Math.Abs(currentOpacity - value) < 0.005;
                }
                root.Items.Add(opacity);
                root.Items.Add(new Separator());
                var scaling = new MenuItem { Header = "Scaling · Nearest neighbor", IsEnabled = false };
                root.Items.Add(scaling);
                root.Items.Add(MenuAction("Open full visualizer settings...", "", OpenBroadcastVisualizer));
            };
            return root;
        }

        private void WireShellContextMenu()
        {
            if (_window == null) return;
            var shell = new ContextMenu();
            var menuBar = new MenuItem { Header = "Menu bar", IsCheckable = true };
            menuBar.Click += delegate { SetMenuBarVisible(menuBar.IsChecked, true); };
            var titleBar = new MenuItem { Header = "Title bar", IsCheckable = true };
            titleBar.Click += delegate { SetTitleBarVisible(titleBar.IsChecked, true); };
            var art = new MenuItem { Header = "Thumbnail", IsCheckable = true, StaysOpenOnClick = true };
            art.Click += delegate { ToggleMediaModule(true); art.IsChecked = MediaModeHasArtwork(_mediaMode); };
            var video = new MenuItem { Header = "Video", IsCheckable = true, StaysOpenOnClick = true };
            video.Click += delegate { ToggleMediaModule(false); video.IsChecked = MediaModeHasVideo(_mediaMode); };
            var visualizer = new MenuItem { Header = "Visualizer", IsCheckable = true, StaysOpenOnClick = true };
            visualizer.Click += delegate { SetVisualizerEnabled(visualizer.IsChecked, true); };
            var queue = new MenuItem { Header = "Queue", IsCheckable = true, Tag = "show-queue" };
            queue.Click += delegate { SetQueueOpen(queue.IsChecked, true); queue.IsChecked = _queueOpen; };
            var operations = new MenuItem { Header = "Operations Center", IsCheckable = true, Tag = "operations-center" };
            operations.Click += delegate { SetInspectorOpen(operations.IsChecked, true); operations.IsChecked = _inspectorOpen; };
            shell.Items.Add(queue);
            shell.Items.Add(operations);
            shell.Items.Add(new Separator());
            shell.Items.Add(art); shell.Items.Add(video); shell.Items.Add(visualizer);
            var obsIntegration = new MenuItem { Header = "OBS Integration + Media Prep", IsCheckable = true, ToolTip = "Enable or disable OBS integration and media preparation together." };
            obsIntegration.Click += delegate { SetObsPackageEnabled(obsIntegration.IsChecked); };
            shell.Items.Add(obsIntegration);
            shell.Items.Add(new Separator());
            shell.Items.Add(MiniPlayerWindowMenuItem());
            shell.Items.Add(ControllerPositionMenu());
            shell.Items.Add(MediaSizeMenu());
            shell.Items.Add(new Separator());
            shell.Items.Add(menuBar); shell.Items.Add(titleBar);
            shell.Items.Add(new Separator());
            var repeat = new MenuItem { Header = "Repeat" };
            AddRepeatMenuItem(repeat, "Off", "off"); AddRepeatMenuItem(repeat, "All", "all"); AddRepeatMenuItem(repeat, "One", "one");
            repeat.SubmenuOpened += delegate { RefreshRepeatMenuChecks(repeat); };
            shell.Items.Add(repeat);
            shell.Items.Add(MenuAction("Appearance settings...", "", OpenAppearanceSettings));
            shell.Items.Add(new Separator());
            shell.Items.Add(MenuAction("Settings...", "Ctrl+,", OpenIntegratedSettings));
            shell.Items.Add(MenuAction("Session Manager...", "", OpenListeningSlots));
            shell.Items.Add(new Separator());
            shell.Items.Add(MenuAction("Quit YOMI", "", StopYomiAndExit));
            shell.Opened += delegate
            {
                RefreshWindowControllerMenuChecks(shell.Items);
                menuBar.IsChecked = _menuBarVisible; titleBar.IsChecked = _titleBarVisible; queue.IsChecked = _queueOpen; operations.IsChecked = _inspectorOpen;
                art.IsChecked = MediaModeHasArtwork(_mediaMode); video.IsChecked = MediaModeHasVideo(_mediaMode); visualizer.IsChecked = _visualizerEnabled;
                obsIntegration.IsChecked = ObsIntegrationEnabled() && ObsMediaCacheEnabled();
                RefreshRepeatMenuChecks(repeat);
            };
            _window.ContextMenu = shell;
            _window.PreviewMouseRightButtonUp += delegate(object sender, MouseButtonEventArgs e)
            {
                DependencyObject node = e.OriginalSource as DependencyObject;
                while (node != null)
                {
                    if (node is TextBoxBase || node is ComboBox || node is Slider) return;
                    FrameworkElement fe = node as FrameworkElement;
                    if (fe != null && !Object.ReferenceEquals(fe, _window) && fe.ContextMenu != null && !Object.ReferenceEquals(fe.ContextMenu, shell)) return;
                    DependencyObject next = null;
                    try { next = VisualTreeHelper.GetParent(node); } catch { }
                    if (next == null && fe != null) next = fe.Parent;
                    if (Object.ReferenceEquals(node, _window)) break;
                    node = next;
                }
                if (shell.IsOpen) return;
                shell.PlacementTarget = _window;
                shell.Placement = PlacementMode.MousePoint;
                shell.IsOpen = true;
                e.Handled = true;
            };
        }

        private void WireQueue()
        {
            _queueList.ItemsSource = _queueRows;
            _queueList.Loaded += delegate { AttachQueueHorizonScroll(); ScheduleQueueHorizonMarker(); };
            _queueView = CollectionViewSource.GetDefaultView(_queueRows);
            _queueView.Filter = QueueFilter;

            _queueFilterAll.Click += delegate { SetQueueScope(QueueScope.All); };
            _queueFilterUpcoming.Click += delegate { SetQueueScope(QueueScope.Upcoming); };
            _queueFilterReady.Click += delegate { SetQueueScope(QueueScope.Ready); };
            _queueFilterIssues.Click += delegate { SetQueueScope(QueueScope.Issues); };
            _queueFilterHistory.Click += delegate { SetQueueScope(QueueScope.History); };
            _queueFilterNextTen.Click += delegate { SetQueueScope(QueueScope.NextTen); };
            _queueFilterUnready.Click += delegate { SetQueueScope(QueueScope.Unready); };
            _queueFilterFavorites.Click += delegate { SetQueueScope(QueueScope.Favorites); };
            _queueFilterUnheard.Click += delegate { SetQueueScope(QueueScope.Unheard); };
            _queueFilterFrequent.Click += delegate { SetQueueScope(QueueScope.Frequent); };
            _queueAdvancedFiltersToggle.Click += delegate
            {
                _queueAdvancedFiltersOpen = false;
                _queueAdvancedFiltersToggle.IsChecked = false;
                OpenQueueFilterMenu();
            };
            _queueSearchClearButton.Click += delegate
            {
                ClearQueuePlaybackSubset();
                _queueSearchBox.Clear();
                Keyboard.ClearFocus();
            };
            if (_queueSearchPlayButton != null) _queueSearchPlayButton.Click += delegate { ActivateQueueSearchPlaybackSubset(); };
            _queueJumpCurrentButton.Click += delegate { JumpQueueToCurrent(); };
            Grid queueScrollTrack = _queueOverviewTrackSurface ?? _queueOverviewSurface;
            queueScrollTrack.PreviewMouseLeftButtonDown += QueueOverviewMouseDown;
            queueScrollTrack.PreviewMouseMove += QueueOverviewMouseMove;
            queueScrollTrack.PreviewMouseLeftButtonUp += QueueOverviewMouseUp;
            queueScrollTrack.LostMouseCapture += delegate { _queueOverviewDragging = false; };
            queueScrollTrack.SizeChanged += delegate { UpdateQueueOverviewMap(); };
            if (_queueScrollUpButton != null) _queueScrollUpButton.Click += delegate { AttachQueueHorizonScroll(); if (_queueHorizonScrollViewer != null) _queueHorizonScrollViewer.LineUp(); };
            if (_queueScrollDownButton != null) _queueScrollDownButton.Click += delegate { AttachQueueHorizonScroll(); if (_queueHorizonScrollViewer != null) _queueHorizonScrollViewer.LineDown(); };
            _queueCollapseButton.Click += delegate { SetQueueOpen(false, true); };
            // R61.106.8: every Queue column boundary is a real spreadsheet-style resize grip.
            // A completed drag snapshots ALL lane widths so SharedSizeGroup/header/rows remain in lockstep.
            foreach (GridSplitter splitter in new[] { _queueTableFavoriteSplitter, _queueTableNumberSplitter, _queueTableChannelSplitter, _queueTableTimeSplitter, _queueTableStateSplitter, _queueTableMediaSplitter, _queueTablePlaysSplitter })
            {
                if (splitter == null) continue;
                splitter.DragCompleted += delegate { CaptureQueueTableColumnWidthsFromLayout(); SaveUiState(); };
                splitter.MouseDoubleClick += delegate { ResetQueueTableColumnWidths(); ApplyQueueTableColumnFit(); SaveUiState(); };
            }
            WireQueueTableHeaderContextMenu();
            _queueFollowToggle.Click += delegate
            {
                _queueFollowCurrent = _queueFollowToggle.IsChecked == true;
                SaveUiState();
                if (_queueFollowCurrent) FollowCurrentQueueRow(true);
            };
            ApplyQueueScopeUi();
            _queueList.AddHandler(Button.ClickEvent, new RoutedEventHandler(QueueTemplateActionClick));

            _queueSelectionPlayNextButton.Click += delegate { BatchPlayNextSelected(); };
            _queueSelectionPrepareButton.Click += delegate { BatchPrepareSelected(); };
            _queueSelectionLaterButton.Click += delegate { BatchMoveLaterSelected(5); };
            _queueSelectionFavoriteButton.Click += delegate { FavoriteSelectedQueueRows(); };
            _queueSelectionRemoveButton.Click += delegate { QueueRemoveSelected(); };
            UpdateQueueSelectionBar();

            _queueSearchBox.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key != Key.Enter) return;
                // R61.67: Enter is deterministic even if the 120 ms typing debounce has not fired yet.
                _queueSearchDebounce.Stop();
                ApplyQueueFilterRefresh();
                if (_queueList == null || _queueList.Items.Count == 0) return;
                QueueRow row = _queueList.Items[0] as QueueRow;
                if (row == null) return;
                _queueList.SelectedItems.Clear();
                _queueList.SelectedItem = row;
                _queueList.ScrollIntoView(row);
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
                {
                    ListBoxItem container = _queueList.ItemContainerGenerator.ContainerFromItem(row) as ListBoxItem;
                    if (container != null) container.Focus();
                    else _queueList.Focus();
                }));
                e.Handled = true;
            };

            _queueSearchBox.GotKeyboardFocus += delegate
            {
                if (_queueSearchPlaceholder != null && String.IsNullOrWhiteSpace(_queueSearchBox.Text))
                    _queueSearchPlaceholder.Visibility = Visibility.Collapsed;
            };
            _queueSearchBox.LostKeyboardFocus += delegate
            {
                if (_queueSearchPlaceholder != null)
                    _queueSearchPlaceholder.Visibility = String.IsNullOrWhiteSpace(_queueSearchBox.Text) ? Visibility.Visible : Visibility.Collapsed;
            };

            _queueSearchBox.TextChanged += delegate
            {
                bool searchEmpty = String.IsNullOrWhiteSpace(_queueSearchBox.Text);
                if (_queuePlaybackSubsetActive && !String.Equals((_queueSearchBox.Text ?? "").Trim(), _queuePlaybackSubsetQuery, StringComparison.OrdinalIgnoreCase)) ClearQueuePlaybackSubset();
                _queueSearchPlaceholder.Visibility = searchEmpty && !_queueSearchBox.IsKeyboardFocused ? Visibility.Visible : Visibility.Collapsed;
                _queueSearchClearButton.Visibility = searchEmpty ? Visibility.Collapsed : Visibility.Visible;
                if (_queueSearchPlayButton != null)
                {
                    _queueSearchPlayButton.Visibility = searchEmpty ? Visibility.Hidden : Visibility.Visible;
                    _queueSearchPlayButton.IsEnabled = !searchEmpty && !_queuePlaybackSubsetActive;
                }
                if (IsContextWorkspace(_workspaceProfile) && !_applyingWorkspaceProfile)
                    WorkspaceContextFor(_workspaceProfile).QueueSearch = _queueSearchBox.Text ?? "";
                CompileQueueFilterQuery();
                // R61.67: filtering 2,000-10,000 rows synchronously for every physical key event
                // is needless UI-thread churn. Coalesce ordinary typing into one refresh while
                // keeping Enter/clear/scope changes deterministic through immediate flushes.
                _queueSearchDebounce.Stop();
                _queueSearchDebounce.Start();
            };

            _queueList.PreviewMouseWheel += delegate
            {
                if (_queueFollowCurrent)
                {
                    _queueFollowCurrent = false;
                    ApplyQueueScopeUi();
                    SaveUiState();
                }
            };
            _queueList.AddHandler(ScrollBar.ScrollEvent, new ScrollEventHandler(delegate(object sender, ScrollEventArgs e)
            {
                if (_queueProgrammaticScroll || !_queueFollowCurrent) return;
                _queueFollowCurrent = false;
                ApplyQueueScopeUi();
                SaveUiState();
            }));

            _queueList.SelectionChanged += delegate
            {
                RefreshInspector();
                UpdateQueueFilterSummary();
                UpdateQueueSelectionBar();
                _queueOverviewIndexDirty = true;
                UpdateQueueOverviewMap();
            };

            _queueList.MouseDoubleClick += delegate(object sender, MouseButtonEventArgs e)
            {
                var inlineButton = FindVisualParent<Button>(e.OriginalSource as DependencyObject);
                if (inlineButton != null && ((inlineButton.Tag as string) ?? "").StartsWith("queue-row-", StringComparison.Ordinal))
                    return;
                var row = _queueList.SelectedItem as QueueRow;
                if (row != null && _running)
                {
                    BeginPlaybackTransitionProjection();
                    SendMpv("script-message", "yomi-jump", row.OccurrenceId.ToString(CultureInfo.InvariantCulture));
                }
            };

            _queueList.PreviewMouseRightButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                if (item != null && !item.IsSelected)
                {
                    _queueList.SelectedItems.Clear();
                    item.IsSelected = true;
                }
            };

            _queueList.PreviewMouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                var inlineButton = FindVisualParent<Button>(e.OriginalSource as DependencyObject);
                if (inlineButton != null && ((inlineButton.Tag as string) ?? "").StartsWith("queue-row-", StringComparison.Ordinal))
                {
                    _queueDragArmed = false;
                    return;
                }
                _queueDragStart = e.GetPosition(_queueList);
                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                _queueDragArmed = item != null;
                if (item != null && item.IsSelected && _queueList.SelectedItems.Count > 1 &&
                    Keyboard.Modifiers == ModifierKeys.None)
                {
                    // Explorer-style multi-drag: pressing an already-selected row must not
                    // collapse the selection before the drag threshold is crossed.
                    item.Focus();
                    e.Handled = true;
                }
            };
            _queueList.PreviewMouseLeftButtonUp += delegate
            {
                _queueDragArmed = false;
                ClearQueueDropIndicator();
            };
            _queueList.PreviewMouseMove += delegate(object sender, MouseEventArgs e)
            {
                if (!_queueDragArmed || e.LeftButton != MouseButtonState.Pressed)
                    return;
                Point now = e.GetPosition(_queueList);
                if (Math.Abs(now.X - _queueDragStart.X) < SystemParameters.MinimumHorizontalDragDistance &&
                    Math.Abs(now.Y - _queueDragStart.Y) < SystemParameters.MinimumVerticalDragDistance)
                    return;
                var rows = SelectedQueueRows().Where(r => r.OccurrenceId != _currentOccurrence).ToList();
                if (rows.Count == 0)
                {
                    _queueDragArmed = false;
                    ShowToast("Queue reorder", "The playing occurrence stays anchored.");
                    return;
                }
                if (!QueueDragEditingAllowed())
                {
                    _queueDragArmed = false;
                    ShowToast("Queue reorder", "Use All with an empty search to drag exact positions.");
                    return;
                }
                _queueDragArmed = false;
                var payload = String.Join(",", rows.Select(r => r.OccurrenceId.ToString(CultureInfo.InvariantCulture)).ToArray());
                var data = new DataObject("YOMI_QUEUE_OCCURRENCES", payload);
                DragDrop.DoDragDrop(_queueList, data, DragDropEffects.Move);
                ClearQueueDropIndicator();
            };
            _queueList.AllowDrop = true;
            _queueList.DragOver += delegate(object sender, DragEventArgs e)
            {
                if (!_running || !QueueDragEditingAllowed() || !e.Data.GetDataPresent("YOMI_QUEUE_OCCURRENCES"))
                {
                    e.Effects = DragDropEffects.None;
                    ClearQueueDropIndicator();
                    e.Handled = true;
                    return;
                }
                Point listPoint = e.GetPosition(_queueList);
                var scroller = FindVisualChild<ScrollViewer>(_queueList);
                if (scroller != null)
                {
                    if (listPoint.Y < 26) scroller.LineUp();
                    else if (listPoint.Y > Math.Max(26, _queueList.ActualHeight - 26)) scroller.LineDown();
                }

                var item = FindVisualParent<ListBoxItem>(e.OriginalSource as DependencyObject);
                var row = item != null ? item.DataContext as QueueRow : null;
                if (row == null)
                {
                    ClearQueueDropIndicator();
                    _queueDropToEnd = true;
                    if (_queueDropEndIndicator != null) _queueDropEndIndicator.Visibility = Visibility.Visible;
                    e.Effects = DragDropEffects.Move;
                    e.Handled = true;
                    return;
                }
                _queueDropToEnd = false;
                if (_queueDropEndIndicator != null) _queueDropEndIndicator.Visibility = Visibility.Collapsed;
                Point p = e.GetPosition(item);
                bool after = p.Y > Math.Max(1.0, item.ActualHeight / 2.0);
                SetQueueDropIndicator(row, after);
                e.Effects = DragDropEffects.Move;
                e.Handled = true;
            };
            _queueList.DragLeave += delegate { ClearQueueDropIndicator(); };
            _queueList.Drop += delegate(object sender, DragEventArgs e)
            {
                try
                {
                    if (!_running || !QueueDragEditingAllowed() ||
                        (!_queueDropToEnd && _queueDropRow == null) ||
                        !e.Data.GetDataPresent("YOMI_QUEUE_OCCURRENCES"))
                        return;
                    string raw = Convert.ToString(e.Data.GetData("YOMI_QUEUE_OCCURRENCES"), CultureInfo.InvariantCulture) ?? "";
                    int targetBoundary = _queueDropToEnd
                        ? _order.Count + 1
                        : _queueDropRow.Slot + (_queueDropAfter ? 1 : 0);
                    MoveOccurrenceBlock(raw, targetBoundary, _queueDropToEnd ? "drag-end" : "drag");
                }
                finally
                {
                    ClearQueueDropIndicator();
                    e.Handled = true;
                }
            };

            var queueMenu = new ContextMenu();
            var queueMenuShow = new MenuItem { Header = "Show Queue", IsCheckable = true, IsChecked = true, Tag = "show-queue" };
            queueMenuShow.Click += delegate { SetQueueOpen(queueMenuShow.IsChecked, true); };
            queueMenu.Items.Add(queueMenuShow);
            AddMenuItem(queueMenu, "Now Playing", delegate { JumpQueueToCurrent(); });
            var queueMenuFollow = new MenuItem { Header = "Follow Now Playing", IsCheckable = true, IsChecked = _queueFollowCurrent };
            queueMenuFollow.Click += delegate { _queueFollowCurrent = queueMenuFollow.IsChecked; ApplyQueueScopeUi(); SaveUiState(); if (_queueFollowCurrent) FollowCurrentQueueRow(true); };
            queueMenu.Items.Add(queueMenuFollow);
            var queueMenuFilter = new MenuItem { Header = "Filter" };
            Action<string, QueueScope> addQueueScope = delegate(string label, QueueScope scope)
            {
                var scopeItem = new MenuItem { Header = label, IsCheckable = true, IsChecked = _queueScope == scope, Tag = scope };
                scopeItem.Click += delegate { SetQueueScope(scope); };
                queueMenuFilter.Items.Add(scopeItem);
            };
            addQueueScope("All", QueueScope.All); addQueueScope("Upcoming", QueueScope.Upcoming); addQueueScope("Ready", QueueScope.Ready); addQueueScope("Issues", QueueScope.Issues);
            queueMenuFilter.Items.Add(new Separator());
addQueueScope("Next 10", QueueScope.NextTen); addQueueScope("Unready", QueueScope.Unready); addQueueScope("Favorites", QueueScope.Favorites); addQueueScope("Unheard", QueueScope.Unheard); addQueueScope("Frequent", QueueScope.Frequent);
            queueMenuFilter.SubmenuOpened += delegate
            {
                foreach (object raw in queueMenuFilter.Items)
                {
                    MenuItem mi = raw as MenuItem;
                    if (mi == null || !(mi.Tag is QueueScope)) continue;
                    mi.IsChecked = (QueueScope)mi.Tag == _queueScope;
                }
            };
            queueMenu.Items.Add(queueMenuFilter);
            queueMenu.Items.Add(new Separator());
            AddMenuItem(queueMenu, "Play now", delegate { QueueCommand("yomi-jump"); });
            AddMenuItem(queueMenu, "Play next", delegate { QueueCommand("yomi-order-play-next"); });
            AddMenuItem(queueMenu, "Prepare", delegate { BatchPrepareSelected(); });
            AddMenuItem(queueMenu, "Toggle favorite", delegate { ToggleFavoriteSelectedOrCurrent(); });
            // Source opening is intentionally not exposed in the Queue menu. Accidental browser
            // launches were repeatedly reported as disruptive; diagnostics retain the URL internally.
            var queueMoveMenu = new MenuItem { Header = "Move" };
            AddMenuItem(queueMoveMenu, "+5 positions", delegate { QueueCommand("yomi-order-move-later", "5"); });
            AddMenuItem(queueMoveMenu, "To top of upcoming", delegate { MoveSelectedBlockToBoundary(Math.Max(1, _currentSlot + 1), "top-upcoming"); });
            AddMenuItem(queueMoveMenu, "To end", delegate { MoveSelectedBlockToBoundary(_order.Count + 1, "end"); });
            queueMenu.Items.Add(queueMoveMenu);
            var queueSelectedMenu = new MenuItem { Header = "Selected rows" };
            var batchPlayNextItem = AddMenuItem(queueSelectedMenu, "Play selected next", delegate { BatchPlayNextSelected(); });
            var batchCopyItem = AddMenuItem(queueSelectedMenu, "Copy selected", delegate { CopySelectedQueueRows(false); });
            var batchCopyTableItem = AddMenuItem(queueSelectedMenu, "Copy selected as table", delegate { CopySelectedQueueRowsAsTable(); });
            var batchCopyUrlsItem = AddMenuItem(queueSelectedMenu, "Copy selected URLs", delegate { CopySelectedQueueRows(true); });
            queueSelectedMenu.Items.Add(new Separator());
            var batchRemoveItem = AddMenuItem(queueSelectedMenu, "Remove selected", delegate { QueueRemoveSelected(); });
            queueMenu.Items.Add(queueSelectedMenu);
            queueMenu.Opened += delegate
            {
                RefreshWindowControllerMenuChecks(queueMenu.Items);
                queueMenuShow.IsChecked = _queueOpen;
                queueMenuFollow.IsChecked = _queueFollowCurrent;
                int count = SelectedQueueRows().Count;
                string suffix = count > 1 ? " (" + count.ToString(CultureInfo.InvariantCulture) + ")" : "";
                batchPlayNextItem.Header = "Play selected next" + suffix;
                batchCopyItem.Header = "Copy selected" + suffix;
                batchCopyTableItem.Header = "Copy selected as table" + suffix;
                batchCopyUrlsItem.Header = "Copy selected URLs" + suffix;
                batchRemoveItem.Header = "Remove selected" + suffix;
            };
            queueMenu.Items.Add(new Separator());
            var queueCheckpointMenu = new MenuItem { Header = "Checkpoints" };
            AddMenuItem(queueCheckpointMenu, "Save queue checkpoint", delegate { SaveQueueCheckpoint(); });
            AddMenuItem(queueCheckpointMenu, "Restore latest checkpoint", delegate { RestoreLatestQueueCheckpoint(); });
            queueMenu.Items.Add(queueCheckpointMenu);
            var queueWindowMenu = new MenuItem { Header = "Window / controller" };
            AddWindowControllerMenuItems(queueWindowMenu.Items, false);
            queueMenu.Items.Add(queueWindowMenu);
            queueMenu.Items.Add(new Separator());
            AddMenuItem(queueMenu, "Quit YOMI", delegate { StopYomiAndExit(); });
            _queueList.ContextMenu = queueMenu;
            _queueList.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                bool shift = (e.KeyboardDevice.Modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
                bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
                if (e.Key == Key.Enter)
                {
                    if (shift) BatchPlayNextSelected();
                    else QueueCommand("yomi-jump");
                    e.Handled = true;
                }
                else if (e.Key == Key.P && !ctrl)
                {
                    BatchPrepareSelected();
                    e.Handled = true;
                }
                else if (e.Key == Key.Delete)
                {
                    QueueRemoveSelected();
                    e.Handled = true;
                }
                else if ((e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt && e.Key == Key.Up)
                {
                    MoveSelectedBlockByOne(-1);
                    e.Handled = true;
                }
                else if ((e.KeyboardDevice.Modifiers & ModifierKeys.Alt) == ModifierKeys.Alt && e.Key == Key.Down)
                {
                    MoveSelectedBlockByOne(1);
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.Home)
                {
                    MoveSelectedBlockToBoundary(Math.Max(1, _currentSlot + 1), "top-upcoming");
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.End)
                {
                    MoveSelectedBlockToBoundary(_order.Count + 1, "end");
                    e.Handled = true;
                }
                else if (ctrl && shift && e.Key == Key.C)
                {
                    CopySelectedQueueRowsAsTable();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.C)
                {
                    CopySelectedQueueRows(false);
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.A)
                {
                    _queueList.SelectAll();
                    UpdateQueueSelectionBar();
                    _queueOverviewIndexDirty = true;
                    UpdateQueueOverviewMap();
                    _queueList.Focus();
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.D)
                {
                    ToggleFavoriteSelectedOrCurrent();
                    e.Handled = true;
                }
            };

            var nowMenu = new ContextMenu();
            var nowShowQueue = new MenuItem { Header = "Show Queue", IsCheckable = true, IsChecked = _queueOpen, Tag = "show-queue" };
            nowShowQueue.Click += delegate { SetQueueOpen(nowShowQueue.IsChecked, true); nowShowQueue.IsChecked = _queueOpen; };
            nowMenu.Items.Add(nowShowQueue);
            nowMenu.Items.Add(new Separator());
            AddMenuItem(nowMenu, "Toggle favorite    Ctrl+D", delegate { ToggleFavoriteCurrent(); });
            AddMenuItem(nowMenu, "Copy now playing", delegate { CopyNowPlaying(); });
            AddMenuItem(nowMenu, "Copy source URL", delegate { CopyCurrentSourceUrl(); });
            nowMenu.Items.Add(new Separator());
            var nowArt = new MenuItem { Header = "Thumbnail", IsCheckable = true, StaysOpenOnClick = true };
            nowArt.Click += delegate { ToggleMediaModule(true); nowArt.IsChecked = MediaModeHasArtwork(_mediaMode); };
            var nowVideo = new MenuItem { Header = "Video", IsCheckable = true, StaysOpenOnClick = true };
            nowVideo.Click += delegate { ToggleMediaModule(false); nowVideo.IsChecked = MediaModeHasVideo(_mediaMode); };
            var nowVisualizer = new MenuItem { Header = "Visualizer", IsCheckable = true, StaysOpenOnClick = true };
            nowVisualizer.Click += delegate { SetVisualizerEnabled(nowVisualizer.IsChecked, true); nowVisualizer.IsChecked = _visualizerEnabled; };
            nowMenu.Items.Add(nowArt); nowMenu.Items.Add(nowVideo); nowMenu.Items.Add(nowVisualizer);
            nowMenu.Items.Add(new Separator());
            AddWindowControllerMenuItems(nowMenu.Items, false);
            var nowRepeat = new MenuItem { Header = "Repeat" };
            AddRepeatMenuItem(nowRepeat, "Off", "off"); AddRepeatMenuItem(nowRepeat, "All", "all"); AddRepeatMenuItem(nowRepeat, "One", "one");
            nowRepeat.SubmenuOpened += delegate { RefreshRepeatMenuChecks(nowRepeat); };
            nowMenu.Items.Add(nowRepeat);
            nowMenu.Items.Add(new Separator());
            AddMenuItem(nowMenu, "Operations Center", delegate { SetInspectorOpen(true, true); });
            AddMenuItem(nowMenu, "Quit YOMI", delegate { StopYomiAndExit(); });
            nowMenu.Opened += delegate
            {
                RefreshWindowControllerMenuChecks(nowMenu.Items);
                nowShowQueue.IsChecked = _queueOpen;
                nowArt.IsChecked = MediaModeHasArtwork(_mediaMode); nowVideo.IsChecked = MediaModeHasVideo(_mediaMode); nowVisualizer.IsChecked = _visualizerEnabled;
                RefreshRepeatMenuChecks(nowRepeat);
            };
            _nowPlayingSurface.ContextMenu = nowMenu;
        }

        private void StartBroadcastRehearsal(int count)
        {
            if (!_running)
            {
                ShowToast("Broadcast rehearsal", "Start YOMI playback first.");
                return;
            }
            count = Math.Max(1, Math.Min(20, count));
            if (SendMpv("script-message", "yomi-rehearse", count.ToString(CultureInfo.InvariantCulture)))
            {
                _lastQueueRefreshMs = 0;
                AddActivity("Broadcast", "rehearse next " + count.ToString(CultureInfo.InvariantCulture));
                ShowToast("Broadcast rehearsal", "Preparing next " + count.ToString(CultureInfo.InvariantCulture) + " transitions");
            }
        }

        private void ToggleBroadcastFreeze()
        {
            if (!_running)
            {
                ShowToast("Broadcast Freeze", "Start YOMI playback first.");
                return;
            }
            if (SendMpv("script-message", "yomi-freeze-toggle"))
            {
                _lastQueueRefreshMs = 0;
                AddActivity("Broadcast", "freeze toggle requested");
                ShowToast("Broadcast Freeze", "Toggle requested");
            }
        }

        private void BeginQueueSlotNavigation()
        {
            if (!_queueOpen)
                SetQueueOpen(true, true);
            if (_queueScope != QueueScope.All)
            {
                _queueScope = QueueScope.All;
                ApplyQueueScopeUi();
                if (_queueView != null) _queueView.Refresh();
            }
            _queueSearchBox.Text = "#";
            _queueSearchBox.CaretIndex = _queueSearchBox.Text.Length;
            _queueSearchBox.Focus();
        }

        private void ActivateQueueSearchPlaybackSubset()
        {
            if (_queueView == null || _queueSearchBox == null) return;
            _queueSearchDebounce.Stop();
            ApplyQueueFilterRefresh();
            // R61.106.46: Listen is a filter/playback operation, not a global metadata
            // readiness operation. If the matching rows have occurrence IDs, activate them.
            string query = (_queueSearchBox.Text ?? "").Trim();
            if (query.Length == 0) return;
            var ids = new List<int>();
            foreach (object raw in _queueView)
            {
                QueueRow row = raw as QueueRow;
                if (row != null && row.OccurrenceId > 0) ids.Add(row.OccurrenceId);
            }
            if (ids.Count == 0) return;
            if (!_running)
            {
                ShowToast("Search playlist", "Start playback first, then Listen will restrict playback to these matches.");
                return;
            }
            string csv = String.Join(",", ids.Select(x => x.ToString(CultureInfo.InvariantCulture)).ToArray());
            if (!SendMpv("script-message", "yomi-playback-subset", csv, query)) return;
            _queuePlaybackSubsetActive = true;
            _queuePlaybackSubsetQuery = query;
            _queuePlaybackSubsetCsv = csv;
            if (_queueSearchPlayButton != null) { _queueSearchPlayButton.Content = "Listening"; _queueSearchPlayButton.IsEnabled = false; }
            AddActivity("Search playlist", query + " | " + ids.Count.ToString(CultureInfo.InvariantCulture) + " matches");
            ShowToast("Filtered playback", ids.Count.ToString(CultureInfo.InvariantCulture) + " matching tracks. Next and Previous now stay inside this filter.");
        }

        private void ClearQueuePlaybackSubset()
        {
            if (!_queuePlaybackSubsetActive) return;
            if (_running) SendMpv("script-message", "yomi-playback-subset-clear");
            _queuePlaybackSubsetActive = false;
            _queuePlaybackSubsetQuery = "";
            _queuePlaybackSubsetCsv = "";
            if (_queueSearchPlayButton != null) { _queueSearchPlayButton.Content = "Listen"; _queueSearchPlayButton.IsEnabled = !String.IsNullOrWhiteSpace(_queueSearchBox == null ? "" : _queueSearchBox.Text); }
        }

        private void CompileQueueFilterQuery()
        {
            string q = (_queueSearchBox == null ? "" : (_queueSearchBox.Text ?? "")).Trim();
            _queueQueryText = q;
            _queueQueryIncludes.Clear();
            _queueQueryExcludes.Clear();
            _queueQueryA = 0; _queueQueryB = 0;
            _queueQueryKind = q.Length == 0 ? QueueQueryKind.None : QueueQueryKind.Text;
            if (q.Length == 0) return;

            int a, b;
            if (q[0] == '#')
            {
                string slotText = q.Substring(1).Trim();
                int dash = slotText.IndexOf('-');
                if (dash > 0 &&
                    Int32.TryParse(slotText.Substring(0, dash).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a) &&
                    Int32.TryParse(slotText.Substring(dash + 1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out b))
                {
                    _queueQueryKind = QueueQueryKind.SlotRange; _queueQueryA = Math.Min(a,b); _queueQueryB = Math.Max(a,b); return;
                }
                if (slotText.StartsWith(">", StringComparison.Ordinal) && Int32.TryParse(slotText.Substring(1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotGreater; _queueQueryA = a; return; }
                if (slotText.StartsWith("<", StringComparison.Ordinal) && Int32.TryParse(slotText.Substring(1).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotLess; _queueQueryA = a; return; }
                if (Int32.TryParse(slotText, NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
                { _queueQueryKind = QueueQueryKind.SlotExact; _queueQueryA = a; return; }
            }
            else if (q[0] == '@')
            {
                _queueQueryKind = QueueQueryKind.Channel; _queueQueryText = q.Substring(1).Trim(); return;
            }
            else if (q.StartsWith("id:", StringComparison.OrdinalIgnoreCase) &&
                     Int32.TryParse(q.Substring(3).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out a))
            {
                _queueQueryKind = QueueQueryKind.Occurrence; _queueQueryA = a; return;
            }

            CompileQueueTextTerms(q);
        }

        private static string NormalizeQueueSearchTerm(string value)
        {
            string term = (value ?? "").Trim();
            if (term.Length >= 2 && term[0] == '"' && term[term.Length - 1] == '"')
                term = term.Substring(1, term.Length - 2).Trim();
            return term;
        }

        private void AddQueueSearchTerm(List<string> target, string value)
        {
            string term = NormalizeQueueSearchTerm(value);
            if (term.Length == 0) return;
            if (!target.Any(x => String.Equals(x, term, StringComparison.OrdinalIgnoreCase)))
                target.Add(term);
        }

        private static List<string> SplitQueueSearchClauses(string query)
        {
            var clauses = new List<string>();
            if (String.IsNullOrWhiteSpace(query)) return clauses;
            var part = new StringBuilder();
            bool quoted = false;
            for (int i = 0; i < query.Length; i++)
            {
                char ch = query[i];
                if (ch == '"')
                {
                    quoted = !quoted;
                    part.Append(ch);
                    continue;
                }
                if (ch == ',' && !quoted)
                {
                    clauses.Add(part.ToString());
                    part.Clear();
                    continue;
                }
                part.Append(ch);
            }
            clauses.Add(part.ToString());
            return clauses;
        }

        private void CompileQueueTextTerms(string query)
        {
            // R61.101: preserve legacy phrase-search when no structured syntax is used.
            // Commas opt into AND clauses; a leading '-' clause excludes that phrase.
            // Inline Google-style negatives are also accepted: "jazz live -remix".
            bool structured = query.IndexOf(',') >= 0;
            if (!structured)
            {
                for (int i = 0; i < query.Length; i++)
                {
                    if (query[i] == '-' && (i == 0 || Char.IsWhiteSpace(query[i - 1])))
                    {
                        structured = true;
                        break;
                    }
                }
            }
            if (!structured)
            {
                AddQueueSearchTerm(_queueQueryIncludes, query);
                return;
            }

            foreach (string rawClause in SplitQueueSearchClauses(query))
            {
                string clause = (rawClause ?? "").Trim();
                if (clause.Length == 0) continue;
                if (clause[0] == '-')
                {
                    AddQueueSearchTerm(_queueQueryExcludes, clause.Substring(1));
                    continue;
                }

                int positiveStart = 0;
                bool quoted = false;
                for (int i = 0; i < clause.Length; i++)
                {
                    char ch = clause[i];
                    if (ch == '"') { quoted = !quoted; continue; }
                    if (quoted || ch != '-' || (i > 0 && !Char.IsWhiteSpace(clause[i - 1]))) continue;

                    AddQueueSearchTerm(_queueQueryIncludes, clause.Substring(positiveStart, i - positiveStart));
                    int termStart = i + 1;
                    while (termStart < clause.Length && Char.IsWhiteSpace(clause[termStart])) termStart++;
                    if (termStart >= clause.Length) { positiveStart = clause.Length; break; }

                    int termEnd = termStart;
                    if (clause[termStart] == '"')
                    {
                        termEnd++;
                        while (termEnd < clause.Length && clause[termEnd] != '"') termEnd++;
                        if (termEnd < clause.Length) termEnd++;
                    }
                    else
                    {
                        while (termEnd < clause.Length && !Char.IsWhiteSpace(clause[termEnd])) termEnd++;
                    }
                    AddQueueSearchTerm(_queueQueryExcludes, clause.Substring(termStart, termEnd - termStart));
                    positiveStart = termEnd;
                    i = Math.Max(i, termEnd - 1);
                }
                if (positiveStart < clause.Length)
                    AddQueueSearchTerm(_queueQueryIncludes, clause.Substring(positiveStart));
            }
        }

        private bool QueueTextFilterMatches(QueueRow row)
        {
            string haystack = row == null ? "" : (row.SearchText ?? "");
            foreach (string term in _queueQueryIncludes)
                if (haystack.IndexOf(term, StringComparison.OrdinalIgnoreCase) < 0) return false;
            foreach (string term in _queueQueryExcludes)
                if (haystack.IndexOf(term, StringComparison.OrdinalIgnoreCase) >= 0) return false;
            return _queueQueryIncludes.Count > 0 || _queueQueryExcludes.Count > 0;
        }

        private bool QueueFilter(object item)
        {
            var row = item as QueueRow;
            if (row == null || IsHardUnavailableTrackTitle(row.Title) || !QueueScopeAccepts(row)) return false;
            switch (_queueQueryKind)
            {
                case QueueQueryKind.None: return true;
                case QueueQueryKind.Channel: return _queueQueryText.Length == 0 || (row.Channel ?? "").IndexOf(_queueQueryText, StringComparison.OrdinalIgnoreCase) >= 0;
                case QueueQueryKind.SlotExact: return row.Slot == _queueQueryA;
                case QueueQueryKind.SlotRange: return row.Slot >= _queueQueryA && row.Slot <= _queueQueryB;
                case QueueQueryKind.SlotGreater: return row.Slot > _queueQueryA;
                case QueueQueryKind.SlotLess: return row.Slot < _queueQueryA;
                case QueueQueryKind.Occurrence: return row.OccurrenceId == _queueQueryA;
                default: return QueueTextFilterMatches(row);
            }
        }

        private bool QueueScopeAccepts(QueueRow row)
        {
            if (row == null) return false;
            switch (_queueScope)
            {
                case QueueScope.Upcoming:
                    return row.Status != "PLAYED";
                case QueueScope.Ready:
                    return row.Status == "READY" || row.Status == "AUDIO READY" || row.Status == "POLICY READY" || row.Status == "ISOLATED READY" || row.Status == "PLAYING" || row.Status == "PAUSED";
                case QueueScope.Issues:
                    return row.Status == "BUILDING" || row.Status == "WAITING" || row.Status == "FAILED" || row.Status == "AUDIO READY" || row.Status == "POLICY READY" || row.Status == "ISOLATED READY";
                case QueueScope.History:
                    return row.Status == "PLAYED";
                case QueueScope.NextTen:
                    return row.Slot > _currentSlot && row.Slot <= _currentSlot + 10;
                case QueueScope.Unready:
                    return row.Status == "BUILDING" || row.Status == "WAITING" || row.Status == "QUEUED" || row.Status == "FAILED";
                case QueueScope.Favorites:
                    return row.IsFavorite;
                case QueueScope.Unheard:
                    return row.PlayCount <= 0;
                case QueueScope.Frequent:
                    return row.PlayCount >= 3;
                default:
                    return true;
            }
        }

        private void ApplyQueueFilterRefresh()
        {
            if (_queueView == null) return;
            CompileQueueFilterQuery();
            long started = _clock.ElapsedMilliseconds;
            bool searchEmpty = _queueSearchBox == null || String.IsNullOrWhiteSpace(_queueSearchBox.Text);
            _queueView.Refresh();
            if (_queueSearchPlayButton != null)
            {
                _queueSearchPlayButton.Visibility = searchEmpty ? Visibility.Hidden : Visibility.Visible;
                _queueSearchPlayButton.IsEnabled = !searchEmpty && !_queuePlaybackSubsetActive;
            }
            PruneHiddenQueueSelection();
            UpdateQueueFilterSummary();
            _queueOverviewIndexDirty = true;
            UpdateQueueOverviewMap();
            if (_queueFollowCurrent) FollowCurrentQueueRow();
            ScheduleQueueHorizonMarker();
            long elapsed = _clock.ElapsedMilliseconds - started;
            if (elapsed >= 100)
                WriteControllerPerformanceLogAsync("QUEUE FILTER REFRESH " + elapsed.ToString(CultureInfo.InvariantCulture) + "ms rows=" + _queueRows.Count.ToString(CultureInfo.InvariantCulture));
        }

        private void SetQueueScope(QueueScope scope)
        {
            SetQueueScope(scope, true);
        }

        private void SetQueueScope(QueueScope scope, bool announce)
        {
            if (scope == QueueScope.History) scope = QueueScope.All;
            bool changed = _queueScope != scope;
            if (changed && _queuePlaybackSubsetActive) ClearQueuePlaybackSubset();
            _queueScope = scope;
            ApplyQueueScopeUi();
            _queueSearchDebounce.Stop();
            ApplyQueueFilterRefresh();
            if (changed)
                SaveUiState();
            if (announce && changed)
            {
                AddActivity("Queue scope", QueueScopeLabel(scope));
            }
        }

        private void CycleQueueDensity()
        {
            _queueDensity = QueueDensity.Dense;
            ApplyQueueDensity(true);
        }

        private void ApplyQueueDensity(bool save)
        {
            _queueDensity = QueueDensity.Dense;
            double preservedOffset = -1.0;
            if (_queueList != null)
            {
                AttachQueueHorizonScroll();
                if (_queueHorizonScrollViewer != null)
                    preservedOffset = _queueHorizonScrollViewer.VerticalOffset;

                _queueList.Tag = _queueDensity.ToString();

                // R61.94: TABLE is the Queue renderer, not one density among several.
                // Bind it directly and keep old density tokens as migration-only input.
                if (_queueTableItemTemplate != null && !Object.ReferenceEquals(_queueList.ItemTemplate, _queueTableItemTemplate))
                    _queueList.ItemTemplate = _queueTableItemTemplate;
            }
            ApplyQueueTableColumnFit();

            if (_queueDensityButton != null)
            {
                _queueDensityButton.Content = "Table";
                _queueDensityButton.ToolTip = "Queue presentation: Table";
            }
            if (_queueList != null) _queueList.Margin = _queueDensity == QueueDensity.Dense ? new Thickness(4,0,2,0) : new Thickness(6,6,2,3);
            if (_queueSelectionBar != null)
            {
                bool table = _queueDensity == QueueDensity.Dense;
                _queueSelectionBar.Padding = table ? new Thickness(8,4,8,4) : new Thickness(10,8,10,8);
                _queueSelectionBar.Margin = table ? new Thickness(4,0,4,4) : new Thickness(10,0,10,8);
                _queueSelectionBar.CornerRadius = table ? new CornerRadius(2) : new CornerRadius(8);
            }
            ApplyQueueCanvasChrome();

            if (preservedOffset >= 0.0)
            {
                double restore = preservedOffset;
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
                {
                    AttachQueueHorizonScroll();
                    if (_queueHorizonScrollViewer != null)
                        _queueHorizonScrollViewer.ScrollToVerticalOffset(restore);
                    UpdateQueueHorizonMarker();
                    UpdateQueueOverviewMap();
                }));
            }
            if (save) SaveUiState();
        }

        private void ApplyQueueScopeUi()
        {
            _queueFilterAll.IsChecked = _queueScope == QueueScope.All;
            _queueFilterUpcoming.IsChecked = _queueScope == QueueScope.Upcoming;
            _queueFilterReady.IsChecked = _queueScope == QueueScope.Ready;
            _queueFilterIssues.IsChecked = _queueScope == QueueScope.Issues;
            _queueFilterHistory.IsChecked = _queueScope == QueueScope.History;
            _queueFilterNextTen.IsChecked = _queueScope == QueueScope.NextTen;
            _queueFilterUnready.IsChecked = _queueScope == QueueScope.Unready;
            _queueFilterFavorites.IsChecked = _queueScope == QueueScope.Favorites;
            _queueFilterUnheard.IsChecked = _queueScope == QueueScope.Unheard;
            _queueFilterFrequent.IsChecked = _queueScope == QueueScope.Frequent;
            _queueFollowToggle.IsChecked = _queueFollowCurrent;
            ApplyQueueAdvancedFilterVisibility();
        }

        private bool IsAdvancedQueueScope()
        {
            return _queueScope == QueueScope.History || _queueScope == QueueScope.NextTen ||
                   _queueScope == QueueScope.Unready || _queueScope == QueueScope.Favorites ||
                   _queueScope == QueueScope.Unheard || _queueScope == QueueScope.Frequent;
        }

        private void OpenQueueFilterMenu()
        {
            if (_queueAdvancedFiltersToggle == null) return;
            var menu = new ContextMenu();
            Action<string, QueueScope> addScope = delegate(string label, QueueScope scope)
            {
                var item = new MenuItem { Header = label, IsCheckable = true, IsChecked = _queueScope == scope };
                item.Click += delegate { SetQueueScope(scope); };
                menu.Items.Add(item);
            };
            addScope("All", QueueScope.All);
            addScope("Upcoming", QueueScope.Upcoming);
            addScope("Ready", QueueScope.Ready);
            addScope("Issues", QueueScope.Issues);
            menu.Items.Add(new Separator());
            addScope("Next 10", QueueScope.NextTen);
            addScope("Unready", QueueScope.Unready);
            addScope("Favorites", QueueScope.Favorites);
            addScope("Unheard", QueueScope.Unheard);
            addScope("Frequent", QueueScope.Frequent);
            menu.Items.Add(new Separator());
            var follow = new MenuItem { Header = "Follow Now Playing", IsCheckable = true, IsChecked = _queueFollowCurrent };
            follow.Click += delegate { _queueFollowCurrent = follow.IsChecked; ApplyQueueScopeUi(); SaveUiState(); if (_queueFollowCurrent) FollowCurrentQueueRow(true); };
            menu.Items.Add(follow);
            menu.PlacementTarget = _queueAdvancedFiltersToggle;
            menu.Placement = System.Windows.Controls.Primitives.PlacementMode.Bottom;
            menu.IsOpen = true;
        }

        private void ApplyQueueAdvancedFilterVisibility()
        {
            if (_queueAdvancedFilterPanel == null || _queueAdvancedFiltersToggle == null) return;
            _queueAdvancedFiltersOpen = false;
            _queueAdvancedFilterPanel.Visibility = Visibility.Collapsed;
            _queueAdvancedFiltersToggle.IsChecked = false;
            _queueAdvancedFiltersToggle.Content = "Filter";
        }

        private void PruneHiddenQueueSelection()
        {
            if (_queueList == null || _queueList.SelectedItems.Count == 0) return;
            var hidden = new List<QueueRow>();
            foreach (var item in _queueList.SelectedItems)
            {
                var row = item as QueueRow;
                if (row != null && !QueueFilter(row)) hidden.Add(row);
            }
            foreach (var row in hidden)
                _queueList.SelectedItems.Remove(row);
            if (hidden.Count > 0) UpdateQueueSelectionBar();
        }

        private int ReindexVisibleQueueRows()
        {
            int visibleSlot = 0;
            foreach (QueueRow row in _queueRows)
            {
                if (row == null || IsHardUnavailableTrackTitle(row.Title))
                {
                    if (row != null) row.DisplaySlot = 0;
                    continue;
                }
                row.DisplaySlot = ++visibleSlot;
            }
            return visibleSlot;
        }

        private void UpdateQueueFilterSummary()
        {
            if (_queueFilterSummaryText == null) return;
            int activeTotal = ReindexVisibleQueueRows();
            int visible = activeTotal;
            bool simpleAllView = _queueScope == QueueScope.All && _queueQueryKind == QueueQueryKind.None && String.IsNullOrWhiteSpace(_queueQueryText);
            if (!simpleAllView)
            {
                visible = 0;
                foreach (var row in _queueRows)
                {
                    if (QueueFilter(row)) visible++;
                }
            }
            if (simpleAllView)
            {
                _queueFilterSummaryText.Text = activeTotal.ToString(CultureInfo.InvariantCulture) + (activeTotal == 1 ? " track" : " tracks");
                _queueFilterSummaryText.ToolTip = "Playable tracks in the Queue";
            }
            else
            {
                _queueFilterSummaryText.Text = visible.ToString(CultureInfo.InvariantCulture) + " of " + activeTotal.ToString(CultureInfo.InvariantCulture) + " tracks";
                _queueFilterSummaryText.ToolTip = "Tracks shown by the current Queue filter out of all playable tracks";
            }
            if (_queueEmptyState != null)
            {
                bool empty = visible == 0;
                _queueEmptyState.Visibility = empty ? Visibility.Visible : Visibility.Collapsed;
                if (empty && _queueEmptyTitleText != null && _queueEmptyBodyText != null)
                {
                    bool hasSearch = !String.IsNullOrWhiteSpace(_queueSearchBox.Text);
                    _queueEmptyTitleText.Text = hasSearch ? "Nothing matches" : "No tracks in this view";
                    _queueEmptyBodyText.Text = hasSearch
                        ? "Reset the search or choose a broader queue view."
                        : "Choose All or Upcoming to return to the active session.";
                }
            }
        }

        private void AttachQueueHorizonScroll()
        {
            if (_queueList == null || _queueHorizonScrollViewer != null) return;
            var scroller = FindVisualChild<ScrollViewer>(_queueList);
            if (scroller == null) return;
            _queueHorizonScrollViewer = scroller;
            // R61.99: ScrollViewer can emit bursts while dragging/using the wheel. Collapse those
            // into one background marker update instead of doing presentation geometry inline on
            // every ScrollChanged callback.
            scroller.ScrollChanged += delegate { ScheduleQueueHorizonMarker(); UpdateQueueScrollbarPresentation(); };
            scroller.SizeChanged += delegate { UpdateQueueScrollbarPresentation(); };
            _queueList.SizeChanged += delegate { UpdateQueueScrollbarPresentation(); };
            UpdateQueueScrollbarPresentation();
        }

        private void UpdateQueueScrollbarPresentation()
        {
            if (_queueScrollColumn == null || _queueList == null) return;
            bool needed = _queueOpen && _queueHorizonScrollViewer != null &&
                _queueHorizonScrollViewer.ScrollableHeight > 0.5;
            _queueScrollColumn.Width = new GridLength(needed ? 18.0 : 0.0);
            if (_queueScrollLaneCap != null) _queueScrollLaneCap.Visibility = needed ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableHeaderCap != null)
            {
                bool dense = String.Equals(Convert.ToString(_queueList.Tag, CultureInfo.InvariantCulture), "Dense", StringComparison.OrdinalIgnoreCase);
                _queueTableHeaderCap.Visibility = needed && dense ? Visibility.Visible : Visibility.Collapsed;
            }
            if (_queueOverviewSurface != null)
            {
                _queueOverviewSurface.Visibility = needed ? Visibility.Visible : Visibility.Collapsed;
                _queueOverviewSurface.IsHitTestVisible = needed;
            }
            if (needed) UpdateQueueOverviewMap();
        }

        private void ScheduleQueueHorizonMarker()
        {
            if (_queueViewportSurface == null || _queueHorizonMarkerPending) return;
            _queueHorizonMarkerPending = true;
            try
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    _queueHorizonMarkerPending = false;
                    AttachQueueHorizonScroll();
                    UpdateQueueHorizonMarker();
                }));
            }
            catch { _queueHorizonMarkerPending = false; }
        }

        private void UpdateQueueHorizonMarker()
        {
            if (_queueCurrentMarker == null || _queueViewportSurface == null || _queueList == null)
                return;

            UpdateQueueOverviewMap();
            _queueCurrentMarker.Opacity = 0;
            if (!_queueOpen || _currentOccurrence <= 0) return;

            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(_currentOccurrence, out row) || row == null || !QueueFilter(row)) return;
            var item = _queueList.ItemContainerGenerator.ContainerFromItem(row) as ListBoxItem;

            if (item != null && item.ActualHeight > 0)
            {
                try
                {
                    Point p = item.TranslatePoint(new Point(0, item.ActualHeight * 0.5), _queueViewportSurface);
                    double y = Math.Round(p.Y);
                    if (y >= 5 && y <= _queueViewportSurface.ActualHeight - 5)
                    {
                        Canvas.SetTop(_queueCurrentMarker, Math.Max(0.0, y - 9.0));
                        _queueCurrentMarker.Opacity = 0.88;
                        return;
                    }
                    // R61.69: never cover table rows with floating current-location chrome.
                    // The persistent Queue > Current control owns navigation.
                    return;
                }
                catch { }
            }

            // Recycling virtualization may mean NOW has no container at all. Because the
            // ListBox explicitly uses logical item scrolling, VerticalOffset/ViewportHeight
            // are trustworthy item-space coordinates for a direction-only continuation cue.
            int viewIndex = _queueList.Items.IndexOf(row);
            if (viewIndex < 0 || _queueHorizonScrollViewer == null) return;
            double first = _queueHorizonScrollViewer.VerticalOffset;
            double lastExclusive = first + Math.Max(1.0, _queueHorizonScrollViewer.ViewportHeight);
            // R61.69: offscreen state remains implicit; Current/Follow are stable toolbar controls.
        }

        private void RecomputeQueueOverviewSemanticIndexes()
        {
            _queueOverviewIndexDirty = false;
            _queueOverviewIndexedOccurrence = _currentOccurrence;
            _queueOverviewCurrentIndex = -1;
            _queueOverviewSelectionAverage = -1;
            if (_queueList == null || _queueList.Items.Count <= 0) return;

            // R61.99: Library/All is the normal 2,000+ row view. Its visual order is the
            // authoritative session order, so overview semantics can be resolved from the O(1)
            // occurrence index instead of walking every virtualized row whenever the horizon
            // marker is scheduled. Filtered/search views retain the exact view-index scan below.
            if (_queueScope == QueueScope.All && _queueQueryKind == QueueQueryKind.None &&
                _queueList.Items.Count == _order.Count)
            {
                int currentOrderIndex;
                if (_currentOccurrence > 0 && _orderIndexByOccurrence.TryGetValue(_currentOccurrence, out currentOrderIndex))
                    _queueOverviewCurrentIndex = currentOrderIndex;

                long selectedOrderSum = 0;
                int selectedOrderHits = 0;
                foreach (object raw in _queueList.SelectedItems)
                {
                    QueueRow row = raw as QueueRow;
                    int selectedOrderIndex;
                    if (row != null && _orderIndexByOccurrence.TryGetValue(row.OccurrenceId, out selectedOrderIndex))
                    {
                        selectedOrderSum += selectedOrderIndex;
                        selectedOrderHits++;
                    }
                }
                if (selectedOrderHits > 0) _queueOverviewSelectionAverage = (double)selectedOrderSum / selectedOrderHits;
                return;
            }

            var selected = new HashSet<object>();
            foreach (object raw in _queueList.SelectedItems) if (raw != null) selected.Add(raw);
            long selectedIndexSum = 0;
            int selectedHits = 0;
            for (int i = 0; i < _queueList.Items.Count; i++)
            {
                object raw = _queueList.Items[i];
                QueueRow row = raw as QueueRow;
                if (row == null) continue;
                if (row.OccurrenceId == _currentOccurrence) _queueOverviewCurrentIndex = i;
                if (selected.Contains(raw)) { selectedIndexSum += i; selectedHits++; }
            }
            if (selectedHits > 0) _queueOverviewSelectionAverage = (double)selectedIndexSum / selectedHits;
        }

        private void RenderQueueOverviewTopology(double height)
        {
            // R61.67: decorative readiness/favorite topology was intentionally retired.
            // Keep the compatibility canvas empty; the overview now communicates only
            // viewport, current-track and selection position.
            if (_queueOverviewTopologyCanvas != null && _queueOverviewTopologyCanvas.Children.Count > 0)
                _queueOverviewTopologyCanvas.Children.Clear();
        }

        private void UpdateQueueOverviewMap()
        {
            if (_queueOverviewSurface == null || _queueOverviewCanvas == null || _queueOverviewViewport == null || _queueList == null) return;
            _queueOverviewViewport.Opacity = 0;
            if (_queueOverviewCurrentNode != null) _queueOverviewCurrentNode.Opacity = 0;
            if (_queueOverviewSelectionMarker != null) _queueOverviewSelectionMarker.Opacity = 0;
            if (!_queueOpen || _queueList.Items.Count <= 0) return;
            AttachQueueHorizonScroll();
            if (_queueHorizonScrollViewer == null || _queueHorizonScrollViewer.ScrollableHeight <= 0.5) return;

            double height = _queueOverviewCanvas.ActualHeight;
            double extent = Math.Max(1.0, _queueHorizonScrollViewer.ExtentHeight);
            double visible = Math.Max(1.0, _queueHorizonScrollViewer.ViewportHeight);
            if (height < 20.0 || extent <= visible) return;

            double thumbHeight = Math.Max(20.0, Math.Min(height, height * Math.Min(1.0, visible / extent)));
            double travel = Math.Max(0.0, height - thumbHeight);
            double scrollable = Math.Max(0.0, _queueHorizonScrollViewer.ScrollableHeight);
            double ratio = scrollable <= 0.0 ? 0.0 : Math.Max(0.0, Math.Min(1.0, _queueHorizonScrollViewer.VerticalOffset / scrollable));
            _queueOverviewViewport.Height = thumbHeight;
            Canvas.SetTop(_queueOverviewViewport, travel * ratio);
            _queueOverviewViewport.Opacity = 0.92;
        }

        private void QueueOverviewScrollFromThumbTop(double thumbTop)
        {
            if (_queueOverviewSurface == null || _queueOverviewViewport == null) return;
            AttachQueueHorizonScroll();
            if (_queueHorizonScrollViewer == null) return;
            double height = Math.Max(1.0, (_queueOverviewTrackSurface ?? _queueOverviewSurface).ActualHeight);
            double thumbHeight = Math.Max(20.0, Math.Min(height, _queueOverviewViewport.Height));
            double travel = Math.Max(0.0, height - thumbHeight);
            double clampedTop = Math.Max(0.0, Math.Min(travel, thumbTop));
            double ratio = travel <= 0.0 ? 0.0 : clampedTop / travel;
            _queueHorizonScrollViewer.ScrollToVerticalOffset(ratio * Math.Max(0.0, _queueHorizonScrollViewer.ScrollableHeight));
            UpdateQueueHorizonMarker();
        }

        private void QueueOverviewMouseDown(object sender, MouseButtonEventArgs e)
        {
            if (_queueOverviewSurface == null || _queueOverviewViewport == null) return;
            Grid track = _queueOverviewTrackSurface ?? _queueOverviewSurface;
            Point point = e.GetPosition(track);
            double top = Canvas.GetTop(_queueOverviewViewport);
            if (Double.IsNaN(top)) top = 0.0;
            double thumbHeight = Math.Max(20.0, _queueOverviewViewport.Height);
            _queueOverviewDragOffset = point.Y >= top && point.Y <= top + thumbHeight ? point.Y - top : thumbHeight * 0.5;
            _queueOverviewDragging = true;
            track.CaptureMouse();
            QueueOverviewScrollFromThumbTop(point.Y - _queueOverviewDragOffset);
            e.Handled = true;
        }

        private void QueueOverviewMouseMove(object sender, MouseEventArgs e)
        {
            if (!_queueOverviewDragging || e.LeftButton != MouseButtonState.Pressed || _queueOverviewSurface == null) return;
            Grid track = _queueOverviewTrackSurface ?? _queueOverviewSurface;
            QueueOverviewScrollFromThumbTop(e.GetPosition(track).Y - _queueOverviewDragOffset);
            e.Handled = true;
        }

        private void QueueOverviewMouseUp(object sender, MouseButtonEventArgs e)
        {
            if (!_queueOverviewDragging) return;
            _queueOverviewDragging = false;
            Grid track = _queueOverviewTrackSurface ?? _queueOverviewSurface;
            if (track != null && track.IsMouseCaptured) track.ReleaseMouseCapture();
            e.Handled = true;
        }

        private void UpdateQueueNowAnchor()
        {
            if (_queueNowText == null) return;
            if (_currentOccurrence <= 0 || String.IsNullOrWhiteSpace(_titleText.Text) || _titleText.Text.StartsWith("Waiting", StringComparison.OrdinalIgnoreCase))
            {
                _queueNowText.Text = "Now - waiting for playback";
                if (_queueJumpCurrentButton != null) _queueJumpCurrentButton.IsEnabled = false;
                return;
            }
            QueueRow currentQueueRow;
            int visibleTotal = 0;
            foreach (QueueRow queueRow in _queueRows) if (queueRow != null && !IsHardUnavailableTrackTitle(queueRow.Title)) visibleTotal++;
            int visibleCurrent = _queueByOccurrence.TryGetValue(_currentOccurrence, out currentQueueRow) && currentQueueRow != null ? currentQueueRow.DisplaySlot : 0;
            string slot = visibleCurrent > 0 && visibleTotal > 0 ? visibleCurrent.ToString(CultureInfo.InvariantCulture) + "/" + visibleTotal.ToString(CultureInfo.InvariantCulture) : "";
            string channel = String.IsNullOrWhiteSpace(_channelText.Text) ? "" : "  -  " + _channelText.Text;
            _queueNowText.Text = "Now " + slot + "  -  " + _titleText.Text + channel;
            if (_queueJumpCurrentButton != null) _queueJumpCurrentButton.IsEnabled = true;
        }

        private void SelectQueueOccurrenceWhenReady(int occurrence, bool relaxFilters)
        {
            SelectQueueOccurrenceWhenReady(occurrence, relaxFilters, false);
        }

        private void SelectQueueOccurrenceWhenReady(int occurrence, bool relaxFilters, bool topAnchor)
        {
            if (occurrence <= 0) return;
            if (!QueueUiRowsReady)
            {
                _queueUiPendingSelectOccurrence = occurrence;
                _queueUiPendingSelectRelaxFilters = relaxFilters;
                _queueUiPendingSelectTopAnchor = topAnchor;
                EnsureQueueUiMaterialized("locate");
                return;
            }

            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(occurrence, out row)) return;
            if (relaxFilters)
            {
                if (!QueueFilter(row) && !String.IsNullOrWhiteSpace(_queueSearchBox.Text))
                    _queueSearchBox.Clear();
                if (!QueueFilter(row) && _queueScope != QueueScope.All)
                    SetQueueScope(QueueScope.All, false);
            }
            if (!QueueFilter(row)) return;
            _queueList.SelectedItems.Clear();
            _queueList.SelectedItem = row;
            if (topAnchor) ScrollQueueRowToTop(row);
            else _queueList.ScrollIntoView(row);
            _queueList.Focus();
            ScheduleQueueHorizonMarker();
        }

        private void ScrollQueueRowToTop(QueueRow row)
        {
            if (row == null || _queueList == null) return;
            AttachQueueHorizonScroll();
            int index = _queueList.Items.IndexOf(row);
            if (index < 0)
            {
                _queueList.ScrollIntoView(row);
                return;
            }
            if (_queueHorizonScrollViewer == null)
            {
                _queueList.ScrollIntoView(row);
                return;
            }

            // R61.106.5: ScrollIntoView only guarantees visibility and therefore places a row
            // that was below the viewport at the BOTTOM. "Current" is a positional command:
            // anchor the playing row to the first visible queue line from either direction.
            _queueProgrammaticScroll = true;
            _queueHorizonScrollViewer.ScrollToVerticalOffset(index);
            try { _queueList.UpdateLayout(); } catch { }
            int anchorOccurrence = row.OccurrenceId;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
            {
                if (_disposed || _queueList == null || _queueHorizonScrollViewer == null) { _queueProgrammaticScroll = false; return; }
                QueueRow currentRow;
                if (!_queueByOccurrence.TryGetValue(anchorOccurrence, out currentRow) || !Object.ReferenceEquals(currentRow, row)) { _queueProgrammaticScroll = false; return; }
                int currentIndex = _queueList.Items.IndexOf(currentRow);
                if (currentIndex >= 0) _queueHorizonScrollViewer.ScrollToVerticalOffset(currentIndex);
                ScheduleQueueHorizonMarker();
                _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(delegate { _queueProgrammaticScroll = false; }));
            }));
        }

        private void JumpQueueToCurrent()
        {
            SelectQueueOccurrenceWhenReady(_currentOccurrence, true, true);
        }

        private static string QueueScopeLabel(QueueScope scope)
        {
            switch (scope)
            {
                case QueueScope.Upcoming: return "UPCOMING";
                case QueueScope.Ready: return "READY";
                case QueueScope.Issues: return "ISSUES";
                case QueueScope.History: return "HISTORY";
                case QueueScope.NextTen: return "NEXT 10";
                case QueueScope.Unready: return "UNREADY";
                case QueueScope.Favorites: return "FAVORITES";
                case QueueScope.Unheard: return "UNHEARD";
                case QueueScope.Frequent: return "FREQUENT";
                default: return "ALL";
            }
        }

        private void FollowCurrentQueueRow(bool selectCurrent = false)
        {
            if (!_queueOpen || !_queueFollowCurrent || _currentOccurrence <= 0)
                return;
            QueueRow current;
            if (_queueByOccurrence.TryGetValue(_currentOccurrence, out current) && QueueFilter(current))
            {
                // R61.106.49: Follow owns the current-track highlight only at the moments that
                // actually define following: a track transition or explicitly turning Follow on.
                // Manual row selection remains free between transitions.
                if (selectCurrent && _queueList != null && !Object.ReferenceEquals(_queueList.SelectedItem, current))
                {
                    _queueList.SelectedItems.Clear();
                    _queueList.SelectedItem = current;
                }
                ScrollQueueRowToTop(current);
                ScheduleQueueHorizonMarker();
            }
        }

        private static bool IsVisualDescendantOf(DependencyObject source, DependencyObject ancestor)
        {
            DependencyObject current = source;
            while (current != null)
            {
                if (Object.ReferenceEquals(current, ancestor)) return true;
                current = VisualTreeHelper.GetParent(current);
            }
            return false;
        }

        private static T FindVisualParent<T>(DependencyObject source) where T : DependencyObject
        {
            DependencyObject current = source;
            while (current != null)
            {
                var typed = current as T;
                if (typed != null)
                    return typed;
                current = VisualTreeHelper.GetParent(current);
            }
            return null;
        }

        private static ScrollBar FindVerticalScrollBar(DependencyObject source)
        {
            if (source == null) return null;
            int count = VisualTreeHelper.GetChildrenCount(source);
            for (int i = 0; i < count; i++)
            {
                DependencyObject child = VisualTreeHelper.GetChild(source, i);
                ScrollBar bar = child as ScrollBar;
                if (bar != null && bar.Orientation == Orientation.Vertical) return bar;
                ScrollBar nested = FindVerticalScrollBar(child);
                if (nested != null) return nested;
            }
            return null;
        }

        private static T FindVisualChild<T>(DependencyObject source) where T : DependencyObject
        {
            if (source == null) return null;
            int count = VisualTreeHelper.GetChildrenCount(source);
            for (int i = 0; i < count; i++)
            {
                var child = VisualTreeHelper.GetChild(source, i);
                var typed = child as T;
                if (typed != null) return typed;
                var nested = FindVisualChild<T>(child);
                if (nested != null) return nested;
            }
            return null;
        }

        private void SetMediaMode(MediaMode mode, bool restartPreview)
        {
            bool changed = _mediaMode != mode;
            _mediaMode = mode;
            if (changed) SaveUiState();
            ApplyMediaMode(restartPreview);
            if (!_adaptiveLayoutApplying && !_miniMode) ApplyAdaptiveLayout(true);
            QueuePresentationDemandSync(true);
            if (_running && _currentOccurrence > 0)
                SendMpv("script-message", "yomi-prepare", _currentOccurrence.ToString(CultureInfo.InvariantCulture));
            if (_performanceWorkspace) ApplyPerformanceWorkspace(true);
            if (changed) SafeRefresh(true);
        }

        private static bool MediaModeHasArtwork(MediaMode mode)
        {
            return mode == MediaMode.Artwork || mode == MediaMode.Both;
        }

        private static bool MediaModeHasVideo(MediaMode mode)
        {
            return mode == MediaMode.Video || mode == MediaMode.Both;
        }

        private void ToggleMediaModule(bool artwork)
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode);
            if (artwork) art = !art; else video = !video;
            MediaMode next = art ? (video ? MediaMode.Both : MediaMode.Artwork) : (video ? MediaMode.Video : MediaMode.Off);
            // R61.88: a local Thumbnail/Video toggle is not a global presentation restart.
            // ApplyResolvedMedia already stops/starts the affected video/artwork surface selectively;
            // forcing _lastMediaOccurrence=0 here made the next refresh tear down the unrelated
            // visualizer graph as if the track itself had changed.
            SetMediaMode(next, false);
        }

        private bool VideoPreparationEnabled()
        {
            // R61.106.27: Settings Video Off is a hard authority boundary. Local presentation
            // intent may expose an empty themed frame, but it may never request/download/decode
            // video when the global module or unified quality is Off.
            var config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            if (!GetBool(config, "video_enabled", true)) return false;
            string unifiedQuality = UnifiedVideoQualityFromConfig(config);
            if (unifiedQuality.StartsWith("Off", StringComparison.OrdinalIgnoreCase)) return false;
            return MediaModeHasVideo(_mediaMode) || _videoBackdropMode != VideoBackdropMode.Off || _largeVideoArea;
        }

        private void EnforceVideoAuthority()
        {
            if (VideoPreparationEnabled()) return;
            StopVideoPreview(true);
            _lastVideoPath = ""; _lastVideoGeneration = "";
            _videoRequestedPath = ""; _videoRequestedGeneration = ""; _videoRequestedOccurrence = 0;
            _videoPresentedPath = ""; _videoPresentedGeneration = ""; _videoPresentedOccurrence = 0;
            _videoAuthoritativelyAbsent = true;
            if (_videoHost != null) _videoHost.Visibility = Visibility.Collapsed;
            if (_videoFrameHost != null) { _videoFrameHost.Source = null; _videoFrameHost.Visibility = Visibility.Collapsed; }
            if (_playerVideoBackdropSurface != null) _playerVideoBackdropSurface.Visibility = Visibility.Collapsed;
            if (_queueVideoBackdropSurface != null) _queueVideoBackdropSurface.Visibility = Visibility.Collapsed;
        }

        private void SyncMediaDemand()
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode);
            if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.IsChecked = art;
            if (_mediaVideoToggle != null) _mediaVideoToggle.IsChecked = video;
            QueuePresentationDemandSync(false);
        }

        private void CycleVisualizerPresentation()
        {
            VisualizerPresentation next = _visualizerPresentation == VisualizerPresentation.Compact
                ? VisualizerPresentation.Standard
                : _visualizerPresentation == VisualizerPresentation.Standard
                    ? VisualizerPresentation.Cinema
                    : VisualizerPresentation.Compact;
            SetVisualizerPresentation(next, true);
        }

        private void SetVisualizerEnabled(bool enabled, bool restartPreview)
        {
            if (_visualizerEnabled == enabled) { SyncVisualizerDemand(); return; }
            _visualizerEnabled = enabled;
            _lastVisualizerDemandSent = null;
            SaveUiState();
            QueuePresentationDemandSync(true);
            if (enabled && _running && _currentOccurrence > 0)
                SendMpv("script-message", "yomi-prepare", _currentOccurrence.ToString(CultureInfo.InvariantCulture));
            ApplyVisualizerMode(restartPreview);
            // Backdrop-only visualizer: never alter controller topology or dimensions.
            if (_performanceWorkspace) ApplyPerformanceWorkspace(true);
            ApplyVisualizerPresentation(false);
        }

        private void SyncVisualizerDemand()
        {
            QueuePresentationDemandSync(false);
        }

        private void ObservePresentationDemandRuntime(Dictionary<string, object> current, Dictionary<string, object> engine)
        {
            string runtimeId = GetString(engine, "runtime_id", "");
            if (String.IsNullOrWhiteSpace(runtimeId))
            {
                var projected = GetMap(current, "controller_demand");
                runtimeId = GetString(projected, "runtime_id", "");
            }
            if (String.IsNullOrWhiteSpace(runtimeId))
            {
                var protocol = GetMap(current, "state_protocol");
                runtimeId = GetString(protocol, "runtime_id", "");
            }

            _diagnosticRuntimeId = runtimeId ?? "";
            lock (_presentationDemandSync)
            {
                if (!String.Equals(_presentationDemandRuntimeId, runtimeId, StringComparison.Ordinal))
                {
                    _presentationDemandRuntimeId = runtimeId ?? "";
                    _presentationDemandLastAcceptedKey = "";
                    _presentationDemandLastAcceptedMs = -10000;
                    _lastMediaDemandSent = "";
                    _lastVisualizerDemandSent = null;
                }
            }
        }

        private void QueuePresentationDemandSync(bool force)
        {
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode) && VideoPreparationEnabled();
            bool viz = _visualizerEnabled;
            if (!_running || _shutdownRequested || _slotSwitchActive)
            {
                lock (_presentationDemandSync)
                {
                    _presentationDemandLastAcceptedKey = ""; _presentationDemandLastAcceptedMs = -10000; _presentationDemandPendingKey = "";
                }
                return;
            }
            bool startWorker = false;
            lock (_presentationDemandSync)
            {
                string runtime = _presentationDemandRuntimeId ?? "";
                string key = runtime + "|" + (art ? "1" : "0") + (video ? "1" : "0") + (viz ? "1" : "0");
                long now = _clock.ElapsedMilliseconds;
                if (!force && String.Equals(_presentationDemandLastAcceptedKey, key, StringComparison.Ordinal) && now - _presentationDemandLastAcceptedMs < PresentationDemandLeaseMs) return;
                _presentationDemandPendingKey = key; _presentationDemandPendingArt = art; _presentationDemandPendingVideo = video; _presentationDemandPendingViz = viz;
                if (!_presentationDemandWorkerActive) { _presentationDemandWorkerActive = true; startWorker = true; }
            }
            if (startWorker) ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainPresentationDemandSync(); });
        }

        private void DrainPresentationDemandSync()
        {
            while (!_disposed)
            {
                string key; string runtime; bool art; bool video; bool viz; int generation;
                lock (_presentationDemandSync)
                {
                    key = _presentationDemandPendingKey; runtime = _presentationDemandRuntimeId ?? ""; art = _presentationDemandPendingArt; video = _presentationDemandPendingVideo; viz = _presentationDemandPendingViz; generation = _presentationDemandGeneration;
                }
                if (String.IsNullOrWhiteSpace(key)) { lock (_presentationDemandSync) _presentationDemandWorkerActive = false; return; }
                bool accepted = !_shutdownRequested && !_slotSwitchActive && generation == Volatile.Read(ref _presentationDemandGeneration) && SendMpvAcknowledged("script-message", "yomi-controller-demand", art ? "1" : "0", video ? "1" : "0", viz ? "1" : "0", runtime);
                lock (_presentationDemandSync)
                {
                    if (generation != _presentationDemandGeneration) continue;
                    if (accepted) { _presentationDemandLastAcceptedKey = key; _presentationDemandLastAcceptedMs = _clock.ElapsedMilliseconds; _lastMediaDemandSent = (art ? "1" : "0") + ":" + (video ? "1" : "0"); _lastVisualizerDemandSent = viz; }
                    if (String.Equals(_presentationDemandPendingKey, key, StringComparison.Ordinal)) { _presentationDemandWorkerActive = false; return; }
                }
            }
            lock (_presentationDemandSync) _presentationDemandWorkerActive = false;
        }

        private void AddVisualizerPresentationMenuItem(MenuItem parent, string header, VisualizerPresentation presentation)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, Tag = presentation, StaysOpenOnClick = true };
            item.Click += delegate { SetVisualizerPresentation(presentation, true); RefreshVisualizerPresentationMenuChecks(parent); };
            parent.Items.Add(item);
        }

        private void RefreshVisualizerPresentationMenuChecks(MenuItem parent)
        {
            foreach (var raw in parent.Items)
            {
                var item = raw as MenuItem;
                if (item != null && item.Tag is VisualizerPresentation) item.IsChecked = (VisualizerPresentation)item.Tag == _visualizerPresentation;
            }
        }

        private void SetVisualizerPresentation(VisualizerPresentation presentation, bool save)
        {
            if (_visualizerPresentation == presentation) return;
            _visualizerPresentation = presentation;
            if (_visualizerSizeButton != null) _visualizerSizeButton.Content = presentation.ToString().ToUpperInvariant();
            ApplyVisualizerPresentation(save);
            if (save) AddActivity("Visualizer", VisualizerPresentationLabel(presentation));
        }

        private void ApplyVisualizerPresentation(bool save)
        {
            if (_visualizerSizeButton != null) _visualizerSizeButton.Content = _visualizerPresentation.ToString().ToUpperInvariant();
            bool show = _visualizerEnabled && !_miniMode && !_performanceWorkspace;
            Dictionary<string, object> visualizerConfig = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            double controllerVisualizerOpacity = Math.Max(0.05, Math.Min(1.0, GetDouble(visualizerConfig, "visualizer_opacity", 0.30)));
            if (_visualizerRow != null) { _visualizerRow.MinHeight = 0; _visualizerRow.MaxHeight = 0; _visualizerRow.Height = new GridLength(0); }
            if (_visualizerBottomGapRow != null) _visualizerBottomGapRow.Height = new GridLength(0);
            if (_nowPlayingVisualizerColumn != null) _nowPlayingVisualizerColumn.Width = new GridLength(0);
            if (_nowPlayingVisualizerGapColumn != null) _nowPlayingVisualizerGapColumn.Width = new GridLength(0);

            // R61.106.27: the visualizer is atmosphere, not another viewport competing for width.
            // It fills the complete controller atmosphere while the host remains geometry-neutral.
            // Toggling it changes only this background layer; no shell reflow.
            if (_visualizerBackdropImage != null)
            {
                RenderOptions.SetBitmapScalingMode(_visualizerBackdropImage, BitmapScalingMode.NearestNeighbor);
                _visualizerBackdropImage.Stretch = Stretch.Fill;
                _visualizerBackdropImage.SnapsToDevicePixels = true;
                // Width/Height are bound in XAML to the already-arranged visualizer surface.
                // Do not overwrite those bindings here: the source bitmap's native raster must
                // never participate in WPF measure and enlarge the controller.
            }
            if (_visualizerFrameHost != null) RenderOptions.SetBitmapScalingMode(_visualizerFrameHost, BitmapScalingMode.NearestNeighbor);
            if (_visualizerSurface != null)
            {
                _visualizerSurface.Width = Double.NaN;
                _visualizerSurface.MinWidth = 0.0;
                _visualizerSurface.MaxWidth = Double.PositiveInfinity;
                _visualizerSurface.Height = Double.NaN;
                _visualizerSurface.MinHeight = 0.0;
                _visualizerSurface.MaxHeight = Double.PositiveInfinity;
                _visualizerSurface.Margin = new Thickness(0);
                _visualizerSurface.HorizontalAlignment = HorizontalAlignment.Stretch;
                _visualizerSurface.VerticalAlignment = VerticalAlignment.Stretch;
                _visualizerSurface.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
                _visualizerSurface.Opacity = show ? controllerVisualizerOpacity : 0.0;
                _visualizerSurface.IsHitTestVisible = false;
            }
            if (_visualizerReadabilityScrim != null)
            {
                _visualizerReadabilityScrim.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
                _visualizerReadabilityScrim.Opacity = show ? 0.18 : 0.0;
                _visualizerReadabilityScrim.IsHitTestVisible = false;
            }
            if (_visualizerChrome != null) _visualizerChrome.Visibility = Visibility.Collapsed;
            if (save) SaveUiState();
        }

        private static string VisualizerPresentationLabel(VisualizerPresentation presentation)
        {
            switch (presentation)
            {
                case VisualizerPresentation.Compact: return "Compact";
                case VisualizerPresentation.Cinema: return "Cinema";
                default: return "Standard";
            }
        }

