        private void WireCommandPalette()
        {
            BuildCommandCatalog();
            _commandPaletteList.ItemsSource = _commandItems;
            _commandView = CollectionViewSource.GetDefaultView(_commandItems);
            _commandView.Filter = CommandFilter;
            ApplyRecentCommandRanks();

            _commandPaletteSearch.TextChanged += delegate
            {
                _commandPalettePlaceholder.Visibility = String.IsNullOrWhiteSpace(_commandPaletteSearch.Text)
                    ? Visibility.Visible : Visibility.Collapsed;
                UpdateCommandMatchRanks(_commandPaletteSearch.Text);
                if (_commandView != null) _commandView.Refresh();
                if (_commandPaletteList.Items.Count > 0) _commandPaletteList.SelectedIndex = 0;
                UpdateCommandPaletteSummary();
            };

            _commandPaletteSearch.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                if (e.Key == Key.Escape)
                {
                    CloseCommandPalette();
                    e.Handled = true;
                }
                else if (e.Key == Key.Enter)
                {
                    ExecuteSelectedCommand();
                    e.Handled = true;
                }
                else if (e.Key == Key.Down && _commandPaletteList.Items.Count > 0)
                {
                    _commandPaletteList.SelectedIndex = Math.Max(0, _commandPaletteList.SelectedIndex);
                    _commandPaletteList.Focus();
                    e.Handled = true;
                }
                else if (e.Key == Key.Up && _commandPaletteList.Items.Count > 0)
                {
                    _commandPaletteList.SelectedIndex = _commandPaletteList.Items.Count - 1;
                    _commandPaletteList.Focus();
                    e.Handled = true;
                }
            };

            _commandPaletteList.MouseDoubleClick += delegate { ExecuteSelectedCommand(); };
            _commandPaletteList.PreviewKeyDown += delegate(object sender, KeyEventArgs e)
            {
                bool ctrl = (e.KeyboardDevice.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
                if (e.Key == Key.Enter) { ExecuteSelectedCommand(); e.Handled = true; }
                else if (e.Key == Key.Escape) { CloseCommandPalette(); e.Handled = true; }
                else if (e.Key == Key.Up && _commandPaletteList.SelectedIndex <= 0)
                {
                    _commandPaletteSearch.Focus();
                    _commandPaletteSearch.CaretIndex = _commandPaletteSearch.Text == null ? 0 : _commandPaletteSearch.Text.Length;
                    e.Handled = true;
                }
                else if (ctrl && e.Key == Key.F)
                {
                    _commandPaletteSearch.Focus();
                    _commandPaletteSearch.SelectAll();
                    e.Handled = true;
                }
            };

            _commandPaletteOverlay.MouseLeftButtonDown += delegate(object sender, MouseButtonEventArgs e)
            {
                if (IsVisualDescendantOf(e.OriginalSource as DependencyObject, _commandPaletteCard))
                    return;
                CloseCommandPalette();
            };
        }

