        private void AddCommand(string category, string title, string shortcut, string keywords, Action action)
        {
            _commandItems.Add(new CommandItem(category, title, shortcut, keywords, action));
        }

        private bool CommandFilter(object item)
        {
            var command = item as CommandItem;
            if (command == null) return false;
            if (_commandShortcutsOnly && !command.HasShortcut) return false;
            return command.MatchRank < 100000;
        }

        private static int FuzzySubsequenceRank(string haystack, string needle)
        {
            if (String.IsNullOrWhiteSpace(needle)) return 0;
            if (String.IsNullOrWhiteSpace(haystack)) return 100000;
            string h = haystack.ToLowerInvariant(), n = needle.ToLowerInvariant();
            int hi = 0, first = -1, last = -1, gaps = 0;
            for (int ni = 0; ni < n.Length; ni++)
            {
                char c = n[ni]; bool found = false;
                while (hi < h.Length)
                {
                    if (h[hi] == c)
                    {
                        if (first < 0) first = hi;
                        if (last >= 0) gaps += Math.Max(0, hi - last - 1);
                        last = hi; hi++; found = true; break;
                    }
                    hi++;
                }
                if (!found) return 100000;
            }
            return 48 + Math.Min(120, gaps) + Math.Min(40, Math.Max(0, first));
        }

        private static int CommandTokenRank(CommandItem command, string token)
        {
            if (command == null || String.IsNullOrWhiteSpace(token)) return 0;
            if (command.Title.StartsWith(token, StringComparison.OrdinalIgnoreCase)) return 2;
            int p = command.Title.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (p >= 0) return 8 + Math.Min(20, p);
            if (command.Category.StartsWith(token, StringComparison.OrdinalIgnoreCase)) return 14;
            p = command.Category.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (p >= 0) return 18 + Math.Min(12, p);
            if (!String.IsNullOrWhiteSpace(command.Shortcut) && command.Shortcut.IndexOf(token, StringComparison.OrdinalIgnoreCase) >= 0) return 20;
            p = command.SearchText.IndexOf(token, StringComparison.OrdinalIgnoreCase);
            if (p >= 0) return 26 + Math.Min(30, p / 3);
            return FuzzySubsequenceRank(command.SearchText, token);
        }

        private void UpdateCommandMatchRanks(string query)
        {
            string q = (query ?? "").Trim();
            foreach (CommandItem command in _commandItems)
            {
                if (q.Length == 0) { command.MatchRank = 0; continue; }
                if (String.Equals(command.Title, q, StringComparison.OrdinalIgnoreCase)) { command.MatchRank = 0; continue; }
                int total = 0; bool rejected = false;
                foreach (string token in q.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    int rank = CommandTokenRank(command, token);
                    if (rank >= 100000) { rejected = true; break; }
                    total += rank;
                }
                if (!rejected && command.Title.StartsWith(q, StringComparison.OrdinalIgnoreCase)) total = Math.Min(total, 3);
                command.MatchRank = rejected ? 100000 : total;
            }
        }

        private void OpenCommandPalette() { OpenCommandPalette(false); }
        private void OpenShortcutPalette() { OpenCommandPalette(true); }

        private void OpenCommandPalette(bool shortcutsOnly)
        {
            // R50: one existing palette is both action discovery and shortcut reference.
            // Reopening a live surface still preserves the user's in-progress query/context.
            if (_commandPaletteOverlay.Visibility == Visibility.Visible)
            {
                _window.Activate();
                return;
            }
            if (_intentFabricOverlay.Visibility == Visibility.Visible) CloseIntentFabric();
            if (_operatorDeckOverlay.Visibility == Visibility.Visible) CloseOperatorDeck();
            if (_volumePopup != null) _volumePopup.IsOpen = false;
            _commandPaletteReturnFocus = Keyboard.FocusedElement;
            _commandShortcutsOnly = shortcutsOnly;
            UpdateCommandDiscoveryRanks();
            UpdateCommandPaletteContext();
            _commandPaletteOverlay.Visibility = Visibility.Visible;
            SyncHostedMediaAirspace();
            _commandPaletteSearch.Text = "";
            UpdateCommandMatchRanks("");
            _commandPalettePlaceholder.Text = shortcutsOnly ? "Type to filter keyboard shortcuts..." : "Type what you want to do...";
            if (_commandView != null) _commandView.Refresh();
            _commandPaletteList.SelectedIndex = _commandPaletteList.Items.Count > 0 ? 0 : -1;
            UpdateCommandPaletteSummary();
            _window.Dispatcher.BeginInvoke(new Action(delegate
            {
                _commandPaletteSearch.Focus();
                Keyboard.Focus(_commandPaletteSearch);
            }), DispatcherPriority.Input);
        }

        private void CloseCommandPalette()
        {
            if (_commandPaletteOverlay.Visibility != Visibility.Visible) return;
            _commandPaletteOverlay.Visibility = Visibility.Collapsed;
            SyncHostedMediaAirspace();
            IInputElement restore = _commandPaletteReturnFocus;
            _commandPaletteReturnFocus = null;
            RestoreKeyboardFocus(restore);
        }

        private void ExecuteSelectedCommand()
        {
            var command = _commandPaletteList.SelectedItem as CommandItem;
            if (command == null && _commandPaletteList.Items.Count > 0)
                command = _commandPaletteList.Items[0] as CommandItem;
            if (command == null) return;
            CloseCommandPalette();
            RememberCommand(command.Title);
            try { command.Execute(); } catch { }
        }

        private void UpdateCommandPaletteSummary()
        {
            if (_commandPaletteSummary == null) return;
            UpdateCommandPaletteContext();
            int count = _commandPaletteList.Items.Count;
            string query = (_commandPaletteSearch.Text ?? "").Trim();
            if (_commandShortcutsOnly)
                _commandPaletteSummary.Text = count.ToString(CultureInfo.InvariantCulture) + (query.Length == 0 ? " shortcuts" : " shortcut matches");
            else if (query.Length == 0)
                _commandPaletteSummary.Text = count.ToString(CultureInfo.InvariantCulture) + " commands  |  useful now first";
            else
                _commandPaletteSummary.Text = count.ToString(CultureInfo.InvariantCulture) + " matches";
        }

        private void UpdateCommandPaletteContext()
        {
            if (_commandPaletteContextText == null) return;
            var parts = new List<string>();
            parts.Add((_workspaceProfile == WorkspaceProfile.Custom ? "CUSTOM" : _workspaceProfile.ToString()).ToUpperInvariant());
            if (_currentSlot > 0 && _order.Count > 0) parts.Add("NOW " + _currentSlot.ToString(CultureInfo.InvariantCulture) + "/" + _order.Count.ToString(CultureInfo.InvariantCulture));
            if (_queueOpen) parts.Add("QUEUE " + QueueScopeLabel(_queueScope) + " | " + _queueDensity.ToString().ToUpperInvariant());
            int selected = _queueList == null ? 0 : _queueList.SelectedItems.Count;
            if (selected > 0) parts.Add(selected.ToString(CultureInfo.InvariantCulture) + " SELECTED");
            if (_inspectorOpen) parts.Add("OPERATIONS CENTER");
            if (_performanceWorkspace) parts.Add("LOCAL PREVIEWS OFF");
            _commandPaletteContextText.Text = "Context: " + String.Join(" / ", parts.ToArray());
        }

        private void SetCommandDiscoveryRank(string title, int rank)
        {
            var command = _commandItems.FirstOrDefault(x => String.Equals(x.Title, title, StringComparison.OrdinalIgnoreCase));
            if (command != null) command.DiscoveryRank = Math.Min(command.DiscoveryRank, rank);
        }

        private void UpdateCommandDiscoveryRanks()
        {
            foreach (var command in _commandItems) command.DiscoveryRank = 999;

            // Stable baseline: the five actions that explain the normal YOMI mental model.
            SetCommandDiscoveryRank("Play / Pause", 20);
            SetCommandDiscoveryRank("Toggle queue", 30);
            SetCommandDiscoveryRank("Operations Center / system health", 40);
            SetCommandDiscoveryRank("Toggle favorite", 50);
            SetCommandDiscoveryRank("Settings", 60);

            // Context outranks generic recency without hiding anything.
            if (_queueOpen)
            {
                SetCommandDiscoveryRank("Find in queue", 2);
                SetCommandDiscoveryRank("Show issues / building", 6);
                SetCommandDiscoveryRank("Follow current queue item", 10);
            }
            var selectedRows = SelectedQueueRows();
            if (selectedRows.Count > 0)
            {
                SetCommandDiscoveryRank("Play selected next", 1);
                SetCommandDiscoveryRank("Prepare selected", 2);
                SetCommandDiscoveryRank("Copy selected", 3);
            }
            if (_mediaStateOverlay != null && _mediaStateOverlay.Visibility == Visibility.Visible)
                SetCommandDiscoveryRank("Media route / continuity", 1);
            if (_inspectorOpen)
                SetCommandDiscoveryRank("Operations Center / system health", 12);
            if (_microMode)
                SetCommandDiscoveryRank("Mini Player", 7);
            else if (_miniMode)
                SetCommandDiscoveryRank("Mini Player", 8);
            if (_running)
            {
                SetCommandDiscoveryRank("Next track", 24);
                SetCommandDiscoveryRank("Previous track", 25);
            }
            ApplyRecentCommandRanks();
        }

        private static bool IsContextWorkspace(WorkspaceProfile profile)
        {
            return profile == WorkspaceProfile.Player || profile == WorkspaceProfile.Broadcast || profile == WorkspaceProfile.Library || profile == WorkspaceProfile.Performance;
        }

        private static WorkspaceContextRecord DefaultWorkspaceContext(WorkspaceProfile profile)
        {
            var context = new WorkspaceContextRecord();
            if (profile == WorkspaceProfile.Library)
            {
                context.QueueOpen = true; context.QueueScope = QueueScope.All; context.QueueDensity = QueueDensity.Dense; context.QueueFollowCurrent = false; context.QueueAdvancedFiltersOpen = false; context.InspectorOpen = false; context.InformationDensity = InformationDensity.Balanced; context.VisualizerPresentation = VisualizerPresentation.Compact;
            }
            else if (profile == WorkspaceProfile.Performance)
            {
                context.QueueOpen = false; context.QueueScope = QueueScope.All; context.QueueDensity = QueueDensity.Dense; context.QueueFollowCurrent = true; context.QueueAdvancedFiltersOpen = false; context.InspectorOpen = false; context.InformationDensity = InformationDensity.Clean; context.VisualizerPresentation = VisualizerPresentation.Compact;
            }
            else if (profile == WorkspaceProfile.Player)
            {
                // First-run Player workspace is the practical control surface: Queue and Operations
                // Center are visible; optional controller media remains a separate user choice.
                context.QueueOpen = true; context.QueueScope = QueueScope.All; context.QueueDensity = QueueDensity.Dense; context.QueueFollowCurrent = true; context.QueueAdvancedFiltersOpen = false; context.InspectorOpen = true; context.InformationDensity = InformationDensity.Clean; context.VisualizerPresentation = VisualizerPresentation.Standard;
            }
            else
            {
                context.QueueOpen = false; context.QueueScope = QueueScope.All; context.QueueDensity = QueueDensity.Dense; context.QueueFollowCurrent = true; context.QueueAdvancedFiltersOpen = false; context.InspectorOpen = false; context.InformationDensity = InformationDensity.Clean; context.VisualizerPresentation = VisualizerPresentation.Standard;
            }
            return context;
        }

        private void CaptureWorkspaceContext(WorkspaceProfile profile)
        {
            if (!IsContextWorkspace(profile)) return;
            WorkspaceContextRecord prior = null;
            _workspaceContexts.TryGetValue(profile, out prior);
            string currentSession = _sessionId ?? "";
            bool sameSession = prior != null && String.Equals(prior.QueueSessionId ?? "", currentSession, StringComparison.Ordinal);
            var context = new WorkspaceContextRecord
            {
                QueueOpen = _queueOpen, QueueScope = _queueScope, QueueDensity = QueueDensity.Dense, QueueFollowCurrent = _queueFollowCurrent,
                QueueAdvancedFiltersOpen = false, InspectorOpen = _inspectorOpen, InformationDensity = _informationDensity, VisualizerPresentation = _visualizerPresentation,
                QueueSearch = _queueSearchBox == null ? "" : (_queueSearchBox.Text ?? ""), QueueSessionId = currentSession,
                QueueAnchorOccurrence = sameSession ? prior.QueueAnchorOccurrence : 0,
                QueueAnchorFraction = sameSession ? prior.QueueAnchorFraction : 0.0,
                FocusName = prior == null ? "" : (prior.FocusName ?? "")
            };
            AttachQueueHorizonScroll();
            if (_queueOpen && _queueHorizonScrollViewer != null && _queueList != null && _queueList.Items.Count > 0)
            {
                double offset = Math.Max(0.0, _queueHorizonScrollViewer.VerticalOffset);
                int index = Math.Max(0, Math.Min(_queueList.Items.Count - 1, (int)Math.Floor(offset)));
                QueueRow anchor = _queueList.Items[index] as QueueRow;
                if (anchor != null)
                {
                    context.QueueAnchorOccurrence = anchor.OccurrenceId;
                    context.QueueAnchorFraction = Math.Max(0.0, Math.Min(0.999, offset - Math.Floor(offset)));
                }
            }
            if (!String.IsNullOrWhiteSpace(currentSession) && _queueList != null)
            {
                foreach (QueueRow selected in SelectedQueueRows().Take(64))
                    context.QueueSelectedOccurrences.Add(selected.OccurrenceId);
                context.QueueHadKeyboardFocus = _queueList.IsKeyboardFocusWithin;
                if (context.QueueHadKeyboardFocus)
                {
                    var focusedContainer = FindVisualParent<ListBoxItem>(Keyboard.FocusedElement as DependencyObject);
                    QueueRow focusedRow = focusedContainer == null ? null : focusedContainer.DataContext as QueueRow;
                    if (focusedRow != null) context.QueueFocusedOccurrence = focusedRow.OccurrenceId;
                    else
                    {
                        QueueRow selected = _queueList.SelectedItem as QueueRow;
                        if (selected != null) context.QueueFocusedOccurrence = selected.OccurrenceId;
                    }
                }
            }
            if (context.QueueHadKeyboardFocus)
            {
                // Queue keyboard locus supersedes any older named-control locus. Otherwise a delayed
                // workspace focus restore could steal focus back after Queue interaction restoration.
                context.FocusName = "";
            }
            else
            {
                FrameworkElement focused = Keyboard.FocusedElement as FrameworkElement;
                if (focused != null && !String.IsNullOrWhiteSpace(focused.Name) &&
                    (_settingsOverlay == null || _settingsOverlay.Visibility != Visibility.Visible) &&
                    (_commandPaletteOverlay == null || _commandPaletteOverlay.Visibility != Visibility.Visible) &&
                    (_queueList == null || !_queueList.IsKeyboardFocusWithin))
                    context.FocusName = focused.Name;
            }
            _workspaceContexts[profile] = context;
        }

        private WorkspaceContextRecord WorkspaceContextFor(WorkspaceProfile profile)
        {
            WorkspaceContextRecord context;
            if (_workspaceContexts.TryGetValue(profile, out context) && context != null) return context;
            context = DefaultWorkspaceContext(profile);
            _workspaceContexts[profile] = context;
            return context;
        }

        private List<object> SerializeWorkspaceContexts()
        {
            var list = new List<object>();
            foreach (WorkspaceProfile profile in new[] { WorkspaceProfile.Player, WorkspaceProfile.Broadcast, WorkspaceProfile.Library, WorkspaceProfile.Performance })
            {
                WorkspaceContextRecord context;
                if (!_workspaceContexts.TryGetValue(profile, out context) || context == null) continue;
                list.Add(new Dictionary<string, object>
                {
                    { "profile", profile.ToString() }, { "queue_open", context.QueueOpen }, { "queue_scope", context.QueueScope.ToString() }, { "queue_density", context.QueueDensity.ToString() },
                    { "queue_follow_current", context.QueueFollowCurrent }, { "queue_advanced_filters", context.QueueAdvancedFiltersOpen }, { "inspector_open", context.InspectorOpen },
                    { "information_density", context.InformationDensity.ToString() }, { "visualizer_presentation", context.VisualizerPresentation.ToString() },
                    { "queue_search", context.QueueSearch ?? "" }, { "queue_session_id", context.QueueSessionId ?? "" }, { "queue_anchor_occurrence", context.QueueAnchorOccurrence },
                    { "queue_anchor_fraction", Math.Round(context.QueueAnchorFraction, 4) }, { "queue_selected_occurrences", context.QueueSelectedOccurrences.Take(64).ToArray() },
                    { "queue_focused_occurrence", context.QueueFocusedOccurrence }, { "queue_had_keyboard_focus", context.QueueHadKeyboardFocus }, { "focus_name", context.FocusName ?? "" }
                });
            }
            return list;
        }

        private void LoadWorkspaceContexts(Dictionary<string, object> map)
        {
            _workspaceContexts.Clear();
            foreach (object raw in GetList(map, "workspace_contexts"))
            {
                var item = AsMap(raw);
                WorkspaceProfile profile;
                if (!Enum.TryParse(GetString(item, "profile", ""), true, out profile) || !IsContextWorkspace(profile)) continue;
                QueueScope scope; if (!Enum.TryParse(GetString(item, "queue_scope", "All"), true, out scope)) scope = QueueScope.All;
                if (scope == QueueScope.History) scope = QueueScope.All;
                InformationDensity information; if (!Enum.TryParse(GetString(item, "information_density", "Clean"), true, out information)) information = InformationDensity.Clean;
                VisualizerPresentation visualizer; if (!Enum.TryParse(GetString(item, "visualizer_presentation", "Standard"), true, out visualizer)) visualizer = VisualizerPresentation.Standard;
                var context = new WorkspaceContextRecord
                {
                    QueueOpen = GetBool(item, "queue_open", false), QueueScope = scope, QueueDensity = QueueDensity.Dense, QueueFollowCurrent = GetBool(item, "queue_follow_current", true),
                    QueueAdvancedFiltersOpen = GetBool(item, "queue_advanced_filters", false), InspectorOpen = GetBool(item, "inspector_open", false), InformationDensity = information, VisualizerPresentation = visualizer,
                    QueueSearch = GetString(item, "queue_search", ""), QueueSessionId = GetString(item, "queue_session_id", ""), QueueAnchorOccurrence = GetInt(item, "queue_anchor_occurrence", 0),
                    QueueAnchorFraction = Math.Max(0.0, Math.Min(0.999, GetDouble(item, "queue_anchor_fraction", 0.0))),
                    QueueFocusedOccurrence = GetInt(item, "queue_focused_occurrence", 0), QueueHadKeyboardFocus = GetBool(item, "queue_had_keyboard_focus", false), FocusName = GetString(item, "focus_name", "")
                };
                foreach (object selectedRaw in GetList(item, "queue_selected_occurrences"))
                {
                    int occurrence;
                    if (Int32.TryParse(Convert.ToString(selectedRaw, CultureInfo.InvariantCulture), NumberStyles.Integer, CultureInfo.InvariantCulture, out occurrence) &&
                        occurrence > 0 && !context.QueueSelectedOccurrences.Contains(occurrence) && context.QueueSelectedOccurrences.Count < 64)
                        context.QueueSelectedOccurrences.Add(occurrence);
                }
                _workspaceContexts[profile] = context;
            }
        }

        private void ClearPendingQueueInteractionContext()
        {
            _pendingQueueContextSelectedOccurrences.Clear();
            _pendingQueueContextSelectionSpecified = false;
            _pendingQueueContextFocusedOccurrence = 0;
            _pendingQueueContextHadKeyboardFocus = false;
            _pendingQueueContextSessionId = "";
        }

        private void RestorePendingQueueContextAnchor()
        {
            if (_pendingQueueContextAnchorOccurrence <= 0 || !_queueOpen || _queueList == null) return;
            // Follow is a stronger viewport contract than remembered workspace geometry. If Follow
            // is enabled, a stale saved top-row anchor must never pull Now Playing away from row 1.
            if (_queueFollowCurrent)
            {
                _pendingQueueContextAnchorOccurrence = 0;
                _pendingQueueContextAnchorFraction = 0;
                return;
            }
            if (!String.IsNullOrWhiteSpace(_pendingQueueContextSessionId))
            {
                if (String.IsNullOrWhiteSpace(_sessionId)) return;
                if (!String.Equals(_pendingQueueContextSessionId, _sessionId, StringComparison.Ordinal))
                {
                    _pendingQueueContextAnchorOccurrence = 0;
                    _pendingQueueContextAnchorFraction = 0;
                    ClearPendingQueueInteractionContext();
                    if (_queueFollowCurrent) FollowCurrentQueueRow();
                    return;
                }
            }
            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(_pendingQueueContextAnchorOccurrence, out row) || row == null || !QueueFilter(row))
            {
                // The session still matches, so discard only the stale visual anchor. Selection/focus
                // can remain meaningful even when a changed filter makes the old top row unavailable.
                _pendingQueueContextAnchorOccurrence = 0;
                _pendingQueueContextAnchorFraction = 0;
                if (_queueFollowCurrent) FollowCurrentQueueRow();
                return;
            }
            AttachQueueHorizonScroll();
            if (_queueHorizonScrollViewer == null) return;
            int index = _queueList.Items.IndexOf(row);
            if (index < 0) return;
            _queueHorizonScrollViewer.ScrollToVerticalOffset(Math.Max(0.0, index + _pendingQueueContextAnchorFraction));
            _pendingQueueContextAnchorOccurrence = 0;
            _pendingQueueContextAnchorFraction = 0;
            UpdateQueueHorizonMarker();
        }

        private void RestorePendingQueueInteractionContext()
        {
            if (!_queueOpen || _queueList == null) return;
            if (!String.IsNullOrWhiteSpace(_pendingQueueContextSessionId))
            {
                if (String.IsNullOrWhiteSpace(_sessionId)) return;
                if (!String.Equals(_pendingQueueContextSessionId, _sessionId, StringComparison.Ordinal))
                {
                    ClearPendingQueueInteractionContext();
                    return;
                }
            }

            if (_pendingQueueContextSelectionSpecified)
            {
                // Empty selection is meaningful state too. Always clear before replaying the remembered set.
                _queueList.SelectedItems.Clear();
                foreach (int occurrence in _pendingQueueContextSelectedOccurrences.Take(64))
                {
                    QueueRow row;
                    if (_queueByOccurrence.TryGetValue(occurrence, out row) && row != null && QueueFilter(row) && _queueList.Items.Contains(row))
                        _queueList.SelectedItems.Add(row);
                }
                UpdateQueueSelectionBar();
                _queueOverviewIndexDirty = true;
            }

            if (_pendingQueueContextHadKeyboardFocus)
            {
                if (_queueFollowCurrent)
                {
                    // Restoring focus must not scroll an older selected row over the Follow anchor.
                    _queueList.Focus();
                }
                else
                {
                    QueueRow focusRow = null;
                    if (_pendingQueueContextFocusedOccurrence > 0) _queueByOccurrence.TryGetValue(_pendingQueueContextFocusedOccurrence, out focusRow);
                    if (focusRow == null || !QueueFilter(focusRow) || !_queueList.Items.Contains(focusRow))
                        focusRow = _queueList.SelectedItem as QueueRow;
                    if (focusRow != null)
                    {
                        _queueList.ScrollIntoView(focusRow);
                        _window.Dispatcher.BeginInvoke(DispatcherPriority.Input, new Action(delegate
                        {
                            if (!_queueOpen || _queueList == null) return;
                            var container = _queueList.ItemContainerGenerator.ContainerFromItem(focusRow) as ListBoxItem;
                            if (container != null) { container.Focus(); Keyboard.Focus(container); }
                            else _queueList.Focus();
                        }));
                    }
                    else _queueList.Focus();
                }
            }

            ClearPendingQueueInteractionContext();
            UpdateQueueOverviewMap();
        }

        private void ScheduleWorkspaceFocusRestore()
        {
            string name = _pendingWorkspaceFocusName;
            _pendingWorkspaceFocusName = "";
            if (String.IsNullOrWhiteSpace(name)) return;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(delegate
            {
                FrameworkElement target = _window.FindName(name) as FrameworkElement;
                if (target == null || !target.IsVisible || !target.IsEnabled || !target.Focusable) return;
                try { target.Focus(); Keyboard.Focus(target); } catch { }
            }));
        }

        private void ReturnToPreviousWorkspace()
        {
            if (!IsContextWorkspace(_previousFullWorkspaceProfile) || _previousFullWorkspaceProfile == _workspaceProfile)
            {
                if (_miniMode) ApplyWorkspaceProfile(_lastFullWorkspaceProfile, true);
                return;
            }
            ApplyWorkspaceProfile(_previousFullWorkspaceProfile, true);
        }

        private void ApplyWorkspaceProfile(WorkspaceProfile profile, bool save)
        {
            if (profile == WorkspaceProfile.Custom) return;
            if (profile == WorkspaceProfile.Mini) profile = WorkspaceProfile.Micro;
            if (!_compactQueueDetourEntering && _compactQueueReturnProfile != WorkspaceProfile.Custom)
            {
                // An explicit workspace choice supersedes a pending Mini/Micro -> Queue -> compact
                // round-trip. Never let an animation completion overwrite newer operator intent.
                _compactQueueReturnProfile = WorkspaceProfile.Custom;
                _compactQueueReturnFocus = null;
            }
            bool workspaceApplied = false;
            BeginUiStateTransaction();
            try
            {
                WorkspaceProfile previous = _workspaceProfile;
                if (profile != previous && IsContextWorkspace(previous))
                {
                    CaptureWorkspaceContext(previous);
                    _lastFullWorkspaceProfile = previous;
                    if (IsContextWorkspace(profile)) _previousFullWorkspaceProfile = previous;
                }
                if (IsContextWorkspace(profile)) _lastFullWorkspaceProfile = profile;
                _workspaceProfile = profile;
                _applyingWorkspaceProfile = true;
                try
                {
                    if (profile == WorkspaceProfile.Micro)
                    {
                        _microMode = profile == WorkspaceProfile.Micro;
                        _miniMode = true;
                        _performanceWorkspace = false;
                        _inspectorOpen = false;
                        ApplyInspectorVisibility();
                        ApplyWorkspaceMode(false);
                        SetQueueOpen(false, false);
                    }
                    else
                    {
                        _microMode = false;
                        _miniMode = false;
                        _performanceWorkspace = profile == WorkspaceProfile.Performance;
                        WorkspaceContextRecord context = WorkspaceContextFor(profile);
                        _queueScope = context.QueueScope;
                        _queueDensity = QueueDensity.Dense;
                        _queueFollowCurrent = context.QueueFollowCurrent;
                        _queueAdvancedFiltersOpen = false;
                        if (_queueSearchBox != null && !String.Equals(_queueSearchBox.Text ?? "", context.QueueSearch ?? "", StringComparison.Ordinal)) _queueSearchBox.Text = context.QueueSearch ?? "";
                        _pendingQueueContextAnchorOccurrence = context.QueueAnchorOccurrence;
                        _pendingQueueContextAnchorFraction = context.QueueAnchorFraction;
                        _pendingQueueContextSessionId = context.QueueSessionId ?? "";
                        _pendingQueueContextSelectedOccurrences.Clear();
                        foreach (int occurrence in context.QueueSelectedOccurrences.Take(64)) _pendingQueueContextSelectedOccurrences.Add(occurrence);
                        _pendingQueueContextSelectionSpecified = true;
                        _pendingQueueContextFocusedOccurrence = context.QueueFocusedOccurrence;
                        _pendingQueueContextHadKeyboardFocus = context.QueueHadKeyboardFocus;
                        _pendingWorkspaceFocusName = context.QueueHadKeyboardFocus ? "" : (context.FocusName ?? "");
                        _informationDensity = profile == WorkspaceProfile.Performance ? InformationDensity.Clean : context.InformationDensity;
                        _visualizerPresentation = profile == WorkspaceProfile.Performance ? VisualizerPresentation.Compact : context.VisualizerPresentation;
                        _inspectorOpen = profile == WorkspaceProfile.Performance ? false : context.InspectorOpen;
                        ApplyWorkspaceMode(false);
                        ApplyQueueDensity(false);
                        ApplyQueueScopeUi();
                        if (_queueView != null) _queueView.Refresh();
                        UpdateQueueFilterSummary();
                        ApplyQueueAdvancedFilterVisibility();
                        ApplyVisualizerPresentation(false);
                        ApplyInformationDensity(false);
                        ApplyInspectorVisibility();
                        // R61.105: automatic Micro is a temporary presentation detour, not a Queue-close
                        // command. The full workspace context was captured before entering Micro, so
                        // returning above the Micro threshold restores the operator's Queue-open intent.
                        SetQueueOpen(context.QueueOpen, false);
                        RestorePendingQueueContextAnchor();
                        RestorePendingQueueInteractionContext();
                        ScheduleWorkspaceFocusRestore();
                        if (_queueSearchPlaceholder != null)
                            _queueSearchPlaceholder.Text = "Search queue";
                        if (profile == WorkspaceProfile.Performance) ApplyPerformanceWorkspace(true);
                    }
                }
                finally
                {
                    _applyingWorkspaceProfile = false;
                }
                ApplyWorkspaceOptics();
                UpdateCommandPaletteContext();
                if (save)
                {
                    CaptureWorkspaceContext(profile);
                    SaveUiState();
                    AddActivity("Workspace", profile.ToString());
                }
                workspaceApplied = true;
            }
            finally
            {
                // A failed profile transition must not persist a half-applied workspace snapshot.
                EndUiStateTransaction(save && workspaceApplied);
            }
        }

        private void ApplyWorkspaceMode(bool save)
        {
            if (_miniMode)
            {
                bool micro = true;
                if (_mainSurface != null) _mainSurface.Visibility = Visibility.Collapsed;
                if (_miniSurface != null) _miniSurface.Visibility = micro ? Visibility.Collapsed : Visibility.Visible;
                if (_microSurface != null) _microSurface.Visibility = micro ? Visibility.Visible : Visibility.Collapsed;
                if (_workspaceMainColumn != null) _workspaceMainColumn.MinWidth = 0.0;
                if (_workspaceHost != null) _workspaceHost.Margin = new Thickness(0);
                if (_titleTaglineText != null) _titleTaglineText.Visibility = Visibility.Collapsed;
                if (_window.WindowState == WindowState.Normal && (_normalWidth < FullPlayerMinWidth || _normalHeight < FullPlayerMinHeight))
                {
                    _normalWidth = Math.Max(_window.Width, FullPlayerDefaultWidth);
                    _normalHeight = Math.Max(_window.Height, FullPlayerDefaultHeight);
                }
                if (_queueOpen) SetQueueOpen(false, false);
                _visualizerSurface.Visibility = Visibility.Collapsed;
                if (_visualizerReadabilityScrim != null) _visualizerReadabilityScrim.Visibility = Visibility.Collapsed;
                if (_visualizerRow != null) { _visualizerRow.MinHeight = 0; _visualizerRow.MaxHeight = Double.PositiveInfinity; _visualizerRow.Height = new GridLength(0); }
                if (_visualizerBottomGapRow != null) _visualizerBottomGapRow.Height = new GridLength(0);
                if (_visualizerChrome != null) _visualizerChrome.Visibility = Visibility.Collapsed;
                _runtimeSurface.Visibility = Visibility.Collapsed;
                if (_miniContextSurface != null) _miniContextSurface.Visibility = micro ? Visibility.Collapsed : Visibility.Visible;
                if (_visualizerToggle != null) _visualizerToggle.Visibility = Visibility.Collapsed;
                if (_visualizerSettingsButton != null) _visualizerSettingsButton.Visibility = Visibility.Collapsed;
                if (_repeatStatePill != null) _repeatStatePill.Visibility = Visibility.Collapsed;
                if (_queueToggle != null) _queueToggle.Visibility = Visibility.Collapsed;
                if (_moreButton != null) _moreButton.Visibility = Visibility.Collapsed;
                if (_slotsManageButton != null) _slotsManageButton.Visibility = Visibility.Collapsed;
                if (_trackQuickStrip != null) _trackQuickStrip.Visibility = Visibility.Collapsed;
                _footerHint.Visibility = Visibility.Collapsed;
                if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Collapsed;
                if (_playbackSummaryText != null) _playbackSummaryText.Visibility = Visibility.Collapsed;
                if (_technicalText != null) _technicalText.Visibility = Visibility.Collapsed;
                if (_occurrencePill != null) _occurrencePill.Visibility = Visibility.Collapsed;
                if (_memoryPill != null) _memoryPill.Visibility = Visibility.Collapsed;
                if (_bufferPill != null) _bufferPill.Visibility = Visibility.Collapsed;
                if (_workerPill != null) _workerPill.Visibility = Visibility.Collapsed;
                if (_qualityPill != null) _qualityPill.Visibility = Visibility.Collapsed;
                if (_mediaFrame != null) { _mediaFrame.Height = 0; _mediaFrame.Visibility = Visibility.Collapsed; }
                if (_nowPlayingMediaColumn != null) _nowPlayingMediaColumn.Width = new GridLength(0);
                if (_nowPlayingGapColumn != null) _nowPlayingGapColumn.Width = new GridLength(0);
                if (_nowPlayingSurface != null) _nowPlayingSurface.Padding = new Thickness(8, 6, 8, 7);
                if (_slotSelector != null) _slotSelector.Visibility = Visibility.Collapsed;
                if (_favoriteButton != null) _favoriteButton.Visibility = Visibility.Collapsed;
                if (_trackQuickStrip != null) _trackQuickStrip.Visibility = Visibility.Collapsed;
                if (_miniContextSurface != null) _miniContextSurface.Padding = new Thickness(8, 5, 8, 5);
                ApplyInspectorVisibility();
                _window.MinWidth = MicroPlayerMinWidth;
                _window.MinHeight = MicroPlayerMinHeight;
                if (_window.WindowState == WindowState.Normal && !_overlayExpandedCompactHost && !_automaticScaleApplying && _windowPersistenceReady)
                {
                    _window.Width = MicroPlayerDefaultWidth;
                    _window.Height = MicroPlayerDefaultHeight;
                    ConstrainWindowToVisibleWorkArea();
                }
            }
            else
            {
                if (_mainSurface != null) _mainSurface.Visibility = Visibility.Visible;
                if (_miniSurface != null) _miniSurface.Visibility = Visibility.Collapsed;
                if (_microSurface != null) _microSurface.Visibility = Visibility.Collapsed;
                if (_workspaceMainColumn != null) _workspaceMainColumn.MinWidth = 0.0;
                if (_workspaceHost != null) _workspaceHost.Margin = new Thickness(0);
                if (_titleTaglineText != null) _titleTaglineText.Visibility = Visibility.Visible;
                ApplyVisualizerPresentation(false);
                if (_miniContextSurface != null) _miniContextSurface.Visibility = Visibility.Collapsed;
                if (_visualizerToggle != null) _visualizerToggle.Visibility = Visibility.Collapsed;
                if (_visualizerSettingsButton != null) _visualizerSettingsButton.Visibility = Visibility.Collapsed;
                if (_repeatStatePill != null) _repeatStatePill.Visibility = Visibility.Collapsed;
                if (_queueToggle != null) _queueToggle.Visibility = Visibility.Collapsed;
                if (_moreButton != null) _moreButton.Visibility = Visibility.Collapsed;
                if (_slotsManageButton != null) _slotsManageButton.Visibility = Visibility.Collapsed;
                UpdateRuntimeSurfaceVisibility(_lastObservedPhase);
                _footerHint.Visibility = Visibility.Collapsed;
                if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Visible;
                ApplyInformationDensity(false);
                ApplyMediaMode(false);
                if (_nowPlayingSurface != null) _nowPlayingSurface.Padding = new Thickness(8, 5, 8, 7);
                if (_slotSelector != null) _slotSelector.Visibility = Visibility.Collapsed;
                if (_favoriteButton != null) _favoriteButton.Visibility = Visibility.Visible;
                if (_trackQuickStrip != null) _trackQuickStrip.Visibility = Visibility.Collapsed;
                    if (_visualizerQuickStrip != null) _visualizerQuickStrip.Visibility = Visibility.Collapsed;
                ApplyInspectorVisibility();
                Rect fullWork = CurrentWorkAreaDips();
                // R61.76: the minimum window size is the Mini Player floor. Presentation
                // tier changes with geometry instead of clipping Full controls at an artificial floor.
                _window.MinWidth = MicroPlayerMinWidth;
                _window.MinHeight = FullPlayerMinHeight;
                // Startup must honor the exact persisted rectangle loaded before this method.
                // Workspace-profile application may choose a preferred shape only after the first
                // shown/persistable frame; otherwise every launch collapses back to the same strip.
                if (_window.WindowState == WindowState.Normal && !_automaticScaleApplying && _windowPersistenceReady)
                {
                    _window.Width = _queueOpen ? Math.Max(FullPlayerMinWidth, _normalWidth) : Math.Max(FullPlayerMinWidth, _compactControllerWidth);
                    _window.Height = _queueOpen ? Math.Max(QueueWorkbenchMinHeight, _normalHeight) : Math.Max(FullPlayerMinHeight, _compactControllerHeight);
                    ConstrainWindowToVisibleWorkArea();
                }
                ApplyPerformanceWorkspace(_performanceWorkspace);
                ApplyAdaptiveLayout(true);
            }
            ApplyCompactLayoutForSize();
            // Surface visibility is owned by the shared workspace compositor. This reapplies an
            // explicit Mini-controller density after profile/theme transitions that touch Main.
            ApplyQueueCanvasLayout(true);
            ApplyQuietSurface(false);
            ApplyWorkspaceOptics();
            UpdateProgressVisual();
            if (save) SaveUiState();
        }

        private void QueueControllerWakeRefresh()
        {
            if (_controllerWakeRefreshQueued || !_window.IsVisible || _window.WindowState == WindowState.Minimized) return;
            _controllerWakeRefreshQueued = true;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
            {
                _controllerWakeRefreshQueued = false;
                SafeRefresh(false);
            }));
        }

        private void UpdateControllerCadence()
        {
            if (_timer == null) return;
            int target;
            bool hidden = !_window.IsVisible || _window.WindowState == WindowState.Minimized;
            if (hidden) target = _performanceWorkspace ? 4000 : 2500;
            else if (_performanceWorkspace) target = _window.IsActive ? 900 : 1600;
            else target = _window.IsActive ? 350 : 800;
            if (target == _controllerCadenceMs) return;
            _controllerCadenceMs = target;
            _timer.Interval = TimeSpan.FromMilliseconds(target);
        }

        private static AdaptiveLayoutTier ResolveAdaptiveLayoutTierForBudgets(double fullVisualizerLane, double compactVisualizerLane)
        {
            // Stable shell: reserve enough room for one-line title/session chrome and a compact
            // transport row. Standard is intentionally broad; only genuinely roomy lanes use
            // the single-row desktop deck.
            if (fullVisualizerLane >= 720.0) return AdaptiveLayoutTier.Spacious;
            if (compactVisualizerLane >= 400.0) return AdaptiveLayoutTier.Standard;
            return AdaptiveLayoutTier.Constrained;
        }

        private static double CompactVisualizerWidthForShell(double shellWidth, double requestedWidth)
        {
            if (requestedWidth <= 0) return 0;
            return Math.Min(requestedWidth, Math.Max(180.0, Math.Min(240.0, shellWidth * 0.18)));
        }

        private double RequestedVisualizerWidthForLayout()
        {
            if (!_visualizerEnabled || _miniMode || _performanceWorkspace) return 0.0;
            return _visualizerPresentation == VisualizerPresentation.Compact ? 260.0 :
                (_visualizerPresentation == VisualizerPresentation.Cinema ? 500.0 : 360.0);
        }

        private double PredictedMediaRackWidthForLayout(double shellWidth)
        {
            if (_miniMode || _performanceWorkspace) return 0.0;
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode) && !_largeVideoArea;
            if (!art && !video) return 0.0;
            bool pair = art && video;
            bool verticalPair = pair && _mediaPairLayout == MediaPairLayout.TopBottom;
            double cellWidth, cellHeight;
            EffectiveMediaCellGeometry(pair, verticalPair, out cellWidth, out cellHeight);
            return verticalPair ? cellWidth : cellWidth * (pair ? 2.0 : 1.0);
        }

        private AdaptiveLayoutTier ResolveAdaptiveLayoutTier()
        {
            double shellWidth = _nowPlayingSurface != null && _nowPlayingSurface.ActualWidth > 1.0
                ? _nowPlayingSurface.ActualWidth
                : (_window.ActualWidth > 0 ? _window.ActualWidth : _window.Width);
            double horizontalPadding = _nowPlayingSurface == null ? 0.0 : _nowPlayingSurface.Padding.Left + _nowPlayingSurface.Padding.Right;
            double mediaWidth = PredictedMediaRackWidthForLayout(shellWidth);
            double mediaGap = mediaWidth > 0.0 ? 8.0 : 0.0;
            // The Full-player visualizer is now a background layer and consumes zero layout width.
            double laneWithoutVisualizer = Math.Max(0.0, shellWidth - horizontalPadding - mediaWidth - mediaGap);
            double fullLane = laneWithoutVisualizer;
            double compactLane = laneWithoutVisualizer;
            return ResolveAdaptiveLayoutTierForBudgets(fullLane, compactLane);
        }

        private static double ComputeAdaptiveMediaWidth(double width)
        {
            if (Double.IsNaN(width) || Double.IsInfinity(width) || width <= 0) width = FullPlayerDefaultWidth;
            return Math.Max(164.0, Math.Min(188.0, width * 0.17));
        }

        private static double ComputeAdaptiveMediaHeight(double width)
        {
            if (Double.IsNaN(width) || Double.IsInfinity(width) || width <= 0) width = FullPlayerDefaultWidth;
            return Math.Max(82.0, Math.Min(96.0, width * 0.09));
        }

        private double AdaptiveMediaWidth()
        {
            double width = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            // R61.67: continuous media geometry. Compactness comes from reflow, never microscopic labels.
            return ComputeAdaptiveMediaWidth(width);
        }

        private double AdaptiveMediaHeight()
        {
            double width = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            return ComputeAdaptiveMediaHeight(width);
        }

        private static double ClampQueueColumn(double value, double min, double max, double fallback)
        {
            if (Double.IsNaN(value) || Double.IsInfinity(value) || value <= 0) value = fallback;
            return Math.Max(min, Math.Min(max, value));
        }

        private MenuItem QueueColumnVisibilityMenuItem(string header, Func<bool> get, Action<bool> set)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, IsChecked = get() };
            item.Click += delegate
            {
                set(item.IsChecked);
                ApplyQueueTableColumnFit();
                SaveUiState();
            };
            return item;
        }

        private void WireQueueTableHeaderContextMenu()
        {
            if (_queueTableHeader == null) return;
            var menu = new ContextMenu();
            menu.Opened += delegate
            {
                menu.Items.Clear();
                menu.Items.Add(new MenuItem { Header = "Title", IsCheckable = true, IsChecked = true, IsEnabled = false });
                menu.Items.Add(QueueColumnVisibilityMenuItem("Favorite", delegate { return _queueTableFavoriteVisible; }, delegate(bool v) { _queueTableFavoriteVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("Queue position", delegate { return _queueTableNumberVisible; }, delegate(bool v) { _queueTableNumberVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("Channel", delegate { return _queueTableChannelVisible; }, delegate(bool v) { _queueTableChannelVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("Time", delegate { return _queueTableTimeVisible; }, delegate(bool v) { _queueTableTimeVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("State", delegate { return _queueTableStateVisible; }, delegate(bool v) { _queueTableStateVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("Media", delegate { return _queueTableMediaVisible; }, delegate(bool v) { _queueTableMediaVisible = v; }));
                menu.Items.Add(QueueColumnVisibilityMenuItem("Plays", delegate { return _queueTablePlaysVisible; }, delegate(bool v) { _queueTablePlaysVisible = v; }));
                menu.Items.Add(new Separator());
                menu.Items.Add(MenuAction("Reset column widths", "", delegate { ResetQueueTableColumnWidths(); ApplyQueueTableColumnFit(); SaveUiState(); }));
            };
            _queueTableHeader.ContextMenu = menu;
        }

        private void CaptureQueueTableColumnWidthsFromLayout()
        {
            if (_queueTableFavoriteColumn != null && _queueTableFavoriteColumn.ActualWidth > 0) _queueTableFavoriteWidth = ClampQueueColumn(_queueTableFavoriteColumn.ActualWidth, 18, 64, 20);
            if (_queueTableNumberColumn != null && _queueTableNumberColumn.ActualWidth > 0) _queueTableNumberWidth = ClampQueueColumn(_queueTableNumberColumn.ActualWidth, 24, 96, 28);
            if (_queueTableTitleColumn != null && _queueTableTitleColumn.ActualWidth > 0) _queueTableTitleWidth = ClampQueueColumn(_queueTableTitleColumn.ActualWidth, 120, 1200, 360);
            if (_queueTableChannelColumn != null && _queueTableChannelColumn.ActualWidth > 0) _queueTableChannelWidth = ClampQueueColumn(_queueTableChannelColumn.ActualWidth, 80, 720, 240);
            if (_queueTableTimeColumn != null && _queueTableTimeColumn.ActualWidth > 0) _queueTableTimeWidth = ClampQueueColumn(_queueTableTimeColumn.ActualWidth, 48, 160, 72);
            if (_queueTableStateColumn != null && _queueTableStateColumn.ActualWidth > 0) _queueTableStateWidth = ClampQueueColumn(_queueTableStateColumn.ActualWidth, 72, 240, 100);
            if (_queueTableMediaColumn != null && _queueTableMediaColumn.ActualWidth > 0) _queueTableMediaWidth = ClampQueueColumn(_queueTableMediaColumn.ActualWidth, 72, 260, 94);
            if (_queueTablePlaysColumn != null && _queueTablePlaysColumn.ActualWidth > 0) _queueTablePlaysWidth = ClampQueueColumn(_queueTablePlaysColumn.ActualWidth, 44, 140, 58);
        }

        private void ResetQueueTableColumnWidths()
        {
            _queueTableFavoriteWidth = 20; _queueTableNumberWidth = 28; _queueTableTitleWidth = 360; _queueTableChannelWidth = 240;
            _queueTableTimeWidth = 72; _queueTableStateWidth = 100; _queueTableMediaWidth = 94; _queueTablePlaysWidth = 58;
        }

        private static void SetQueueColumnBounds(ColumnDefinition column, bool visible, double min, double max)
        {
            if (column == null) return;
            if (visible)
            {
                // Restore MaxWidth before MinWidth so a previously hidden 0/0 column never
                // passes through an invalid MinWidth > MaxWidth transition.
                column.MaxWidth = max;
                column.MinWidth = min;
            }
            else
            {
                column.MinWidth = 0;
                column.MaxWidth = 0;
            }
        }

        private void ApplyQueueRowColumnVisibility(QueueRow row, int mask)
        {
            if (row == null) return;
            row.SetColumnVisibility(
                (mask & 0x01) != 0, (mask & 0x02) != 0, (mask & 0x04) != 0,
                (mask & 0x08) != 0, (mask & 0x10) != 0, (mask & 0x20) != 0, (mask & 0x40) != 0);
        }

        private void ApplyQueueTableColumnFit()
        {
            if (_queueTableTitleColumn == null || _queueTableChannelColumn == null) return;
            double width = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            if (Double.IsNaN(width) || Double.IsInfinity(width) || width <= 0) width = FullPlayerDefaultWidth;

            QueueTableResponsiveTier tier = width < 620.0 ? QueueTableResponsiveTier.Compact :
                (width < 860.0 ? QueueTableResponsiveTier.Narrow :
                (width < 1080.0 ? QueueTableResponsiveTier.Standard : QueueTableResponsiveTier.Wide));
            _queueTableResponsiveTier = tier;

            bool showFavorite = _queueTableFavoriteVisible;
            bool showNumber = _queueTableNumberVisible;
            bool showChannel = _queueTableChannelVisible && tier != QueueTableResponsiveTier.Compact;
            bool showTime = _queueTableTimeVisible && tier != QueueTableResponsiveTier.Compact;
            bool showState = _queueTableStateVisible && tier != QueueTableResponsiveTier.Compact;
            bool showMedia = _queueTableMediaVisible && (tier == QueueTableResponsiveTier.Standard || tier == QueueTableResponsiveTier.Wide);
            bool showPlays = _queueTablePlaysVisible && tier == QueueTableResponsiveTier.Wide;

            double fav = showFavorite ? ClampQueueColumn(_queueTableFavoriteWidth, 18, 64, 20) : 0;
            double num = showNumber ? ClampQueueColumn(_queueTableNumberWidth, 24, 96, 28) : 0;
            double title = ClampQueueColumn(_queueTableTitleWidth, 120, 1200, 360);
            double channel = showChannel ? ClampQueueColumn(_queueTableChannelWidth, 80, 720, 240) : 0;
            double time = showTime ? ClampQueueColumn(_queueTableTimeWidth, 48, 160, 72) : 0;
            double state = showState ? ClampQueueColumn(_queueTableStateWidth, 72, 240, 100) : 0;
            double media = showMedia ? ClampQueueColumn(_queueTableMediaWidth, 72, 260, 94) : 0;
            double plays = showPlays ? ClampQueueColumn(_queueTablePlaysWidth, 44, 140, 58) : 0;

            // Reserve scrollbar/margins and shrink only flexible text lanes when the window is tight.
            double available = Math.Max(220.0, width - 46.0);
            double fixedWidth = fav + num + time + state + media + plays;
            double flexibleBudget = Math.Max(120.0, available - fixedWidth);
            if (showChannel)
            {
                double titleFloor = tier == QueueTableResponsiveTier.Narrow ? 150.0 : 180.0;
                double channelFloor = 80.0;
                double wanted = title + channel;
                if (wanted > flexibleBudget)
                {
                    double excess = wanted - flexibleBudget;
                    double shrinkTitle = Math.Min(excess, Math.Max(0, title - titleFloor));
                    title -= shrinkTitle; excess -= shrinkTitle;
                    if (excess > 0) channel = Math.Max(channelFloor, channel - excess);
                }
            }
            else
            {
                title = Math.Max(120.0, flexibleBudget);
            }

            int visibilityMask = (showFavorite ? 0x01 : 0) | (showNumber ? 0x02 : 0) | (showChannel ? 0x04 : 0) |
                                 (showTime ? 0x08 : 0) | (showState ? 0x10 : 0) | (showMedia ? 0x20 : 0) | (showPlays ? 0x40 : 0);
            if (visibilityMask != _queueTableAppliedVisibilityMask)
            {
                _queueTableAppliedVisibilityMask = visibilityMask;
                foreach (QueueRow row in _queueRows) ApplyQueueRowColumnVisibility(row, visibilityMask);
            }

            // A hidden SharedSizeGroup must be truly zero-sized. Merely assigning Width=0 while
            // retaining MinWidth lets WPF reopen it, and visible row text can otherwise become the
            // group's largest desired member. Row cells are collapsed above; header bounds are zeroed here.
            SetQueueColumnBounds(_queueTableFavoriteColumn, showFavorite, 18, 64);
            SetQueueColumnBounds(_queueTableNumberColumn, showNumber, 24, 96);
            SetQueueColumnBounds(_queueTableChannelColumn, showChannel, 80, 720);
            SetQueueColumnBounds(_queueTableTimeColumn, showTime, 48, 160);
            SetQueueColumnBounds(_queueTableStateColumn, showState, 72, 240);
            SetQueueColumnBounds(_queueTableMediaColumn, showMedia, 72, 260);
            SetQueueColumnBounds(_queueTablePlaysColumn, showPlays, 44, 140);

            _queueTableFavoriteColumn.Width = new GridLength(fav);
            _queueTableNumberColumn.Width = new GridLength(num);
            _queueTableTitleColumn.Width = new GridLength(title);
            _queueTableChannelColumn.Width = new GridLength(channel);
            if (_queueTableTimeColumn != null) _queueTableTimeColumn.Width = new GridLength(time);
            if (_queueTableStateColumn != null) _queueTableStateColumn.Width = new GridLength(state);
            if (_queueTableMediaColumn != null) _queueTableMediaColumn.Width = new GridLength(media);
            if (_queueTablePlaysColumn != null) _queueTablePlaysColumn.Width = new GridLength(plays);

            // Splitter visibility mirrors the right-hand lane at each boundary; no dead resize grips.
            TextBlock favoriteHeader = _window.FindName("QueueTableFavoriteHeader") as TextBlock;
            if (favoriteHeader != null) favoriteHeader.Visibility = Visibility.Collapsed;
            TextBlock numberHeader = _window.FindName("QueueTableNumberHeader") as TextBlock;
            if (numberHeader != null) numberHeader.Visibility = showNumber ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableFavoriteSplitter != null) _queueTableFavoriteSplitter.Visibility = showFavorite && showNumber ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableNumberSplitter != null)
            {
                _queueTableNumberSplitter.Visibility = showNumber ? Visibility.Visible : Visibility.Collapsed;
                _queueTableNumberSplitter.IsHitTestVisible = showNumber;
                _queueTableNumberSplitter.Width = showNumber ? 7 : 0;
                _queueTableNumberSplitter.Opacity = showNumber ? 1 : 0;
                _queueTableNumberSplitter.ToolTip = showNumber ? "Drag to resize # / Title  double-click to reset" : null;
            }
            if (_queueTableChannelSplitter != null) _queueTableChannelSplitter.Visibility = showChannel ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableTimeSplitter != null) _queueTableTimeSplitter.Visibility = showTime ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableStateSplitter != null) _queueTableStateSplitter.Visibility = showState ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTableMediaSplitter != null) _queueTableMediaSplitter.Visibility = showMedia ? Visibility.Visible : Visibility.Collapsed;
            if (_queueTablePlaysSplitter != null) _queueTablePlaysSplitter.Visibility = showPlays ? Visibility.Visible : Visibility.Collapsed;
        }

        private void ApplyQueueCanvasChrome()
        {
            bool canvas = ShouldUseQueueCanvasLayout();
            double width = _window.ActualWidth > 0 ? _window.ActualWidth : _window.Width;
            bool compact = canvas && width < 620.0;
            bool veryCompact = canvas && width < 520.0;
            if (_queueHeaderSurface != null) { _queueHeaderSurface.Margin = new Thickness(7, 1, 7, 1); _queueHeaderSurface.VerticalAlignment = VerticalAlignment.Top; }
            if (_queueSearchSurface != null) _queueSearchSurface.Margin = new Thickness(0);
            if (_queueFilterSurface != null) { _queueFilterSurface.Margin = new Thickness(0); _queueFilterSurface.Visibility = Visibility.Collapsed; }
            if (_queueSubtitleText != null) _queueSubtitleText.Visibility = Visibility.Collapsed;
            if (_queueNowText != null) { _queueNowText.Visibility = canvas ? Visibility.Collapsed : Visibility.Visible; _queueNowText.Margin = new Thickness(0,3,0,0); }
            if (_queueDensityButton != null) _queueDensityButton.Visibility = Visibility.Collapsed;
            if (_queueFilterSummaryText != null) _queueFilterSummaryText.Visibility = Visibility.Visible;
            if (_queueAdvancedFiltersToggle != null) _queueAdvancedFiltersToggle.Visibility = Visibility.Collapsed;
            if (_queueSearchPlayButton != null)
            {
                _queueSearchPlayButton.MinWidth = compact ? 44 : 52;
                _queueSearchPlayButton.Padding = compact ? new Thickness(5,0,5,0) : new Thickness(7,0,7,0);
                _queueSearchPlayButton.Margin = new Thickness(compact ? 4 : 6,0,0,0);
            }
            if (_queueJumpCurrentButton != null)
            {
                _queueJumpCurrentButton.Content = veryCompact ? "Now" : "Now Playing";
                _queueJumpCurrentButton.Padding = veryCompact ? new Thickness(5,0,5,0) : new Thickness(8,0,8,0);
                _queueJumpCurrentButton.Margin = new Thickness(compact ? 4 : 6,0,0,0);
            }
            if (_queueCollapseButton != null)
            {
                _queueCollapseButton.Width = 44;
                _queueCollapseButton.Margin = new Thickness(5,0,5,0);
            }
            // LIST/TIGHT prioritize the work list. Detailed horizon telemetry remains one click away in COMFY/DETAIL.
            if (_queueHorizonSurface != null) _queueHorizonSurface.Visibility = Visibility.Collapsed;
            ApplyQueueTableColumnFit();
        }

        private bool ShouldUseQueueCanvasLayout()
        {
            return _queueOpen && !_miniMode;
        }

        private void SetQueuePlayerDock(QueuePlayerDock dock, bool save)
        {
            // R61.106.27: one controller-position authority governs both Queue and detached media.
            _queuePlayerDock = dock;
            ApplyQueueCanvasLayout(true);
            if (save) SaveUiState();
        }

        private void ApplyQueueCanvasRowLengths()
        {
            if (_workspaceTopRow == null || _workspaceBottomRow == null || _workspaceSplitRow == null) return;
            _workspaceTopRow.MinHeight = 0; _workspaceBottomRow.MinHeight = 0;
            _workspaceSplitRow.Height = new GridLength(0);
            if (_workspaceQueueSplitter != null) _workspaceQueueSplitter.Visibility = Visibility.Collapsed;
            if (_workspaceSplitHairline != null) _workspaceSplitHairline.Visibility = Visibility.Collapsed;
            if (_mediaStageFullscreen)
            {
                _workspaceTopRow.Height = new GridLength(1, GridUnitType.Star);
                _workspaceBottomRow.Height = new GridLength(0);
                return;
            }
            bool hasWorkplane = _queueCanvasActive || MediaStageVisible();
            if (!hasWorkplane)
            {
                if (_queuePlayerDock == QueuePlayerDock.Top)
                { _workspaceTopRow.Height = new GridLength(1, GridUnitType.Star); _workspaceBottomRow.Height = new GridLength(0); }
                else
                { _workspaceTopRow.Height = new GridLength(0); _workspaceBottomRow.Height = new GridLength(1, GridUnitType.Star); }
                return;
            }
            if (_queuePlayerDock == QueuePlayerDock.Top)
            { _workspaceTopRow.Height = GridLength.Auto; _workspaceBottomRow.Height = new GridLength(1, GridUnitType.Star); }
            else
            { _workspaceTopRow.Height = new GridLength(1, GridUnitType.Star); _workspaceBottomRow.Height = GridLength.Auto; }
        }

        private void ApplyQueuePlayerCompressionForCurrentHeight()
        {
            if (!_queueCanvasActive || _mainSurface == null) return;

            if (_footerHint != null) _footerHint.Visibility = Visibility.Collapsed;
            if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Collapsed;
            if (_technicalText != null) _technicalText.Visibility = Visibility.Collapsed;
            if (_nowPlayingSurface != null) _nowPlayingSurface.Padding = new Thickness(6, 2, 6, 2);

            // R61.106.2: ApplyMediaMode is the only rack-geometry authority. It already knows that
            // Queue canvas caps the rack at 116 px. Do not mutate only MediaFrame.Height after
            // pane widths were resolved, or the rack becomes internally inconsistent until a later
            // refresh recomputes it.
            ApplyMediaMode(false);

            // R61.94: Queue never receives a separate visualizer row. The visualizer stays in
            // the upper-right Now Playing lane and TABLE receives every reclaimed vertical pixel.
            ApplyVisualizerPresentation(false);
        }

        private void RestoreFullPlayerPresentationAfterQueueCanvas()
        {
            ApplyAdaptiveLayout(true);
            ApplyVisualizerPresentation(false);
            ApplyQuietSurface(false);
            RefreshEverydayStatusVisibility();
        }

        private void ApplyQueueCanvasLayout(bool force)
        {
            if (_workspaceTopRow == null || _workspaceSplitRow == null || _workspaceBottomRow == null || _queueDrawer == null || _mainSurface == null || _miniSurface == null || _microSurface == null) return;
            bool canvas = ShouldUseQueueCanvasLayout();
            bool wasCanvas = _queueCanvasActive;
            _queueCanvasActive = canvas;
            int controllerRow = _queuePlayerDock == QueuePlayerDock.Top ? 0 : 2;
            int workRow = _queuePlayerDock == QueuePlayerDock.Top ? 2 : 0;

            _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, null);
            _queueDrawer.BeginAnimation(UIElement.OpacityProperty, null);
            ApplyQueueCanvasRowLengths();

            Grid.SetRow(_mainSurface, controllerRow); Grid.SetColumn(_mainSurface, 0); Grid.SetColumnSpan(_mainSurface, 2);
            Grid.SetRow(_miniSurface, controllerRow); Grid.SetColumn(_miniSurface, 0); Grid.SetColumnSpan(_miniSurface, 2);
            Grid.SetRow(_microSurface, controllerRow); Grid.SetColumn(_microSurface, 0); Grid.SetColumnSpan(_microSurface, 2);
            if (_mediaStageSurface != null && !_mediaStageFullscreen) { Grid.SetRow(_mediaStageSurface, workRow); Grid.SetRowSpan(_mediaStageSurface, 1); Grid.SetColumn(_mediaStageSurface, 0); Grid.SetColumnSpan(_mediaStageSurface, 2); }
            Grid.SetRow(_queueDrawer, workRow); Grid.SetColumn(_queueDrawer, 0); Grid.SetColumnSpan(_queueDrawer, 2);

            bool compactSurface = _microMode || _compactControllerMode;
            bool showController = !_mediaStageFullscreen;
            _mainSurface.Visibility = showController && !_miniMode && !compactSurface ? Visibility.Visible : Visibility.Collapsed;
            _miniSurface.Visibility = showController && _miniMode && !_microMode ? Visibility.Visible : Visibility.Collapsed;
            _microSurface.Visibility = showController && compactSurface ? Visibility.Visible : Visibility.Collapsed;
            _microSurface.VerticalAlignment = _queuePlayerDock == QueuePlayerDock.Top ? VerticalAlignment.Top : VerticalAlignment.Bottom;
            _miniSurface.Margin = new Thickness(0);
            if (_queuePlayerDockSurface != null) { _queuePlayerDockSurface.Visibility = Visibility.Collapsed; _queuePlayerDockSurface.Margin = new Thickness(0); }
            if (_queueDockPositionButton != null) _queueDockPositionButton.Visibility = Visibility.Collapsed;

            if (canvas)
            {
                if (_mediaStageSurface != null) _mediaStageSurface.Visibility = Visibility.Collapsed;
                _queueDrawer.Visibility = Visibility.Visible;
                _queueDrawer.HorizontalAlignment = HorizontalAlignment.Stretch;
                _queueDrawer.Width = Double.NaN;
                _queueDrawer.Margin = new Thickness(0);
                _queueDrawer.BorderThickness = new Thickness(0);
                _queueDrawer.Opacity = 1;
                ApplyQueueCanvasChrome();
                if (!compactSurface) ApplyQueuePlayerCompressionForCurrentHeight();
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate { if (!(_microMode || _compactControllerMode)) ApplyQueuePlayerCompressionForCurrentHeight(); }));
                return;
            }

            _queueDrawer.HorizontalAlignment = HorizontalAlignment.Stretch;
            _queueDrawer.Margin = new Thickness(0);
            _queueDrawer.BorderThickness = new Thickness(0);
            if (_queueOpen)
            {
                _queueExpansionWidth = 0; _queueExpansionShiftX = 0;
                _queueDrawer.Width = Double.NaN; _queueDrawer.Opacity = 1; _queueDrawer.Visibility = Visibility.Visible;
            }
            else
            {
                _queueDrawer.Width = 0; _queueDrawer.Opacity = 0; _queueDrawer.Visibility = Visibility.Collapsed;
            }
            RefreshMediaStagePresentation();
            if (wasCanvas) RestoreFullPlayerPresentationAfterQueueCanvas();
        }

        private void ApplyAdaptiveLayout(bool force)
        {
            if (_adaptiveLayoutApplying || _miniMode || _liveResize) return;
            AdaptiveLayoutTier tier = ResolveAdaptiveLayoutTier();
            double height = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
            bool heightConstrained = height < 520.0;
            if (!force && tier == _adaptiveLayoutTier && heightConstrained == _adaptiveHeightConstrained) return;
            _adaptiveLayoutApplying = true;
            try
            {
                _adaptiveLayoutTier = tier;
                _adaptiveHeightConstrained = heightConstrained;
                bool constrained = tier == AdaptiveLayoutTier.Constrained;
                bool standard = tier == AdaptiveLayoutTier.Standard;
                bool spacious = tier == AdaptiveLayoutTier.Spacious;

                if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.Content = "Thumbnail";
                if (_mediaVideoToggle != null) _mediaVideoToggle.Content = constrained ? "Vid" : "Video";
                if (_visualizerToggle != null) _visualizerToggle.Content = spacious ? "Visualizer" : "Viz";
                if (_visualizerSettingsButton != null) _visualizerSettingsButton.Width = 30;
                if (_mediaQuickControls != null) _mediaQuickControls.Visibility = Visibility.Collapsed; // R61.106.27: Art/Video/Visualizer/options live in context menus, not permanent controller chrome.

                Grid nowPlayingHeaderGrid = _window.FindName("NowPlayingHeaderGrid") as Grid;
                Grid nowPlayingTitleHost = _window.FindName("NowPlayingTitleHost") as Grid;
                StackPanel nowPlayingSessionControls = _window.FindName("NowPlayingSessionControls") as StackPanel;
                if (nowPlayingHeaderGrid != null && nowPlayingTitleHost != null && nowPlayingSessionControls != null)
                {
                    // Horizontal pressure never creates another header row. Rare session controls are
                    // removed from the controller; the remaining favorite control owns only its
                    // natural right-edge width while title space trims naturally.
                    Grid.SetRow(nowPlayingTitleHost, 0); Grid.SetColumn(nowPlayingTitleHost, 0); Grid.SetColumnSpan(nowPlayingTitleHost, 1);
                    Grid.SetRow(nowPlayingSessionControls, 0); Grid.SetColumn(nowPlayingSessionControls, 2); Grid.SetColumnSpan(nowPlayingSessionControls, 1);
                    nowPlayingTitleHost.Margin = new Thickness(0,0,4,0);
                    nowPlayingSessionControls.Margin = new Thickness(0);
                    nowPlayingSessionControls.HorizontalAlignment = HorizontalAlignment.Right;
                    nowPlayingSessionControls.VerticalAlignment = VerticalAlignment.Center;
                }

                if (_mainControlDeck != null && _leftControlDeck != null && _transportDatumDeck != null && _mainVolumeSurface != null && _rightControlDeck != null)
                {
                    // R61.106.27: utility hierarchy. Transport + the long 0-100 Volume lane
                    // own the primary row. Media/Repeat/Queue controls are retired from permanent chrome;
                    // the second row stays available for genuinely contextual content only.
                    Grid.SetRow(_transportDatumDeck, 0); Grid.SetColumn(_transportDatumDeck, 0); Grid.SetColumnSpan(_transportDatumDeck, 1);
                    _transportDatumDeck.HorizontalAlignment = HorizontalAlignment.Left;
                    Grid.SetRow(_mainVolumeSurface, 0); Grid.SetColumn(_mainVolumeSurface, 1); Grid.SetColumnSpan(_mainVolumeSurface, 2);
                    _mainVolumeSurface.HorizontalAlignment = HorizontalAlignment.Right;
                    Grid.SetRow(_leftControlDeck, 1); Grid.SetColumn(_leftControlDeck, 0); Grid.SetColumnSpan(_leftControlDeck, 2);
                    Grid.SetRow(_rightControlDeck, 1); Grid.SetColumn(_rightControlDeck, 2); Grid.SetColumnSpan(_rightControlDeck, 1);
                    _leftControlDeck.Margin = new Thickness(0,4,0,0);
                    _rightControlDeck.Margin = new Thickness(0,4,0,0);
                    _rightControlDeck.HorizontalAlignment = HorizontalAlignment.Right;
                }

                ApplyVisualizerPresentation(false);
                // Volume is a primary transport control. It never degrades to a popup text button
                // in the full player; constrained layouts sacrifice the percent label first.
                if (_mainVolumeSurface != null) _mainVolumeSurface.Visibility = Visibility.Visible;
                if (_mainVolumeValueText != null) _mainVolumeValueText.Visibility = Visibility.Visible;
                ColumnDefinition mainVolumeValueColumn = _window.FindName("MainVolumeValueColumn") as ColumnDefinition;
                if (mainVolumeValueColumn != null) mainVolumeValueColumn.Width = new GridLength(38);
                if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.Padding = constrained ? new Thickness(7,0,7,0) : new Thickness(10,0,10,0);
                if (_mediaVideoToggle != null) _mediaVideoToggle.Padding = constrained ? new Thickness(7,0,7,0) : new Thickness(10,0,10,0);
                if (_visualizerToggle != null) _visualizerToggle.Padding = constrained ? new Thickness(7,0,7,0) : new Thickness(10,0,10,0);
                if (_queueToggle != null) _queueToggle.Padding = constrained ? new Thickness(7,0,7,0) : new Thickness(10,0,10,0);
                if (_volumeButton != null) _volumeButton.Visibility = Visibility.Collapsed;
                if (_repeatStatePill != null)
                {
                    _repeatStatePill.Visibility = Visibility.Collapsed;
                    _repeatStatePill.Width = 0; _repeatStatePill.MinWidth = 0;
                    _repeatStatePill.Padding = new Thickness(0); _repeatStatePill.Margin = new Thickness(0);
                }
                if (_queueToggle != null) { _queueToggle.Visibility = Visibility.Collapsed; _queueToggle.Width = 0; _queueToggle.MinWidth = 0; _queueToggle.Padding = new Thickness(0); _queueToggle.Margin = new Thickness(0); }
                if (_rightControlDeck != null) { _rightControlDeck.Visibility = Visibility.Collapsed; _rightControlDeck.Width = 0; _rightControlDeck.Margin = new Thickness(0); }
                if (_mainVolumeSurface != null) { _mainVolumeSurface.Margin = new Thickness(constrained ? 5 : 10,0,constrained ? 5 : 10,0); _mainVolumeSurface.Width = constrained ? 180 : 204; _mainVolumeSurface.MinWidth = constrained ? 180 : 204; _mainVolumeSurface.MaxWidth = constrained ? 180 : 204; _mainVolumeSurface.HorizontalAlignment = HorizontalAlignment.Right; }
                if (_volumeButton != null) _volumeButton.Margin = new Thickness(0);
                if (_visualizerSettingsButton != null) _visualizerSettingsButton.Visibility = Visibility.Collapsed;
                if (_slotSelector != null) { _slotSelector.Visibility = Visibility.Collapsed; _slotSelector.Width = 0; }
                if (_slotsManageButton != null) { _slotsManageButton.Visibility = Visibility.Collapsed; _slotsManageButton.Width = 0; }
                if (_nowPlayingSurface != null) _nowPlayingSurface.Padding = constrained ? new Thickness(6,3,6,4) : new Thickness(7,3,7,4);
                if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Collapsed;
                UpdateRepeatPill();
                ApplyMediaMode(false);
            }
            finally { _adaptiveLayoutApplying = false; }
        }

        private void ApplyPerformanceWorkspace(bool enabled)
        {
            _performanceWorkspace = enabled;
            UpdateControllerCadence();
            if (!enabled)
            {
                ApplyWorkspaceOptics();
                RestartFramePreviewsAt(_timePosition, true);
                return;
            }
            StopPreviewProcesses();
            if (_mediaFrame != null) { _mediaFrame.Visibility = Visibility.Collapsed; _mediaFrame.Height = 0; }
            if (_nowPlayingMediaColumn != null) _nowPlayingMediaColumn.Width = new GridLength(0);
            if (_nowPlayingGapColumn != null) _nowPlayingGapColumn.Width = new GridLength(0);
            if (_visualizerSurface != null) _visualizerSurface.Visibility = Visibility.Collapsed;
            if (_nowPlayingVisualizerColumn != null) _nowPlayingVisualizerColumn.Width = new GridLength(0);
            if (_nowPlayingVisualizerGapColumn != null) _nowPlayingVisualizerGapColumn.Width = new GridLength(0);
            if (_visualizerRow != null) _visualizerRow.Height = new GridLength(0);
            if (_visualizerBottomGapRow != null) _visualizerBottomGapRow.Height = new GridLength(0);
            if (_visualizerChrome != null) _visualizerChrome.Visibility = Visibility.Collapsed;
            if (_runtimeSurface != null) _runtimeSurface.Visibility = Visibility.Collapsed;
            if (_visualizerToggle != null) _visualizerToggle.Visibility = Visibility.Collapsed;
            if (_visualizerSettingsButton != null) _visualizerSettingsButton.Visibility = Visibility.Collapsed;
            if (_slotsManageButton != null) _slotsManageButton.Visibility = Visibility.Collapsed;
            if (_trackContextRail != null) _trackContextRail.Visibility = Visibility.Collapsed;
            if (_trackQuickStrip != null) _trackQuickStrip.Visibility = Visibility.Collapsed;
            if (_visualizerQuickStrip != null) _visualizerQuickStrip.Visibility = Visibility.Collapsed;
            if (_queueToggle != null) _queueToggle.Visibility = Visibility.Collapsed;
            if (_moreButton != null) _moreButton.Visibility = Visibility.Collapsed;
            if (_modeText != null) _modeText.Text = "Performance mode - local previews off; Queue available";
            ApplyWorkspaceOptics();
        }

        private void SetMiniMode(bool enabled, bool save)
        {
            // R61.94 compatibility shim: legacy Mini intent migrates to Micro.
            SetMicroMode(enabled, save);
        }

        private void ExpandFromMiniPlayer()
        {
            bool hadCompactController = _compactControllerMode;
            _compactControllerMode = false;
            SetMicroMode(false, false);
            ApplyQueueCanvasLayout(true);
            ApplyAdaptiveLayout(true);
            ApplyCompactLayoutForSize();
            SaveUiState();
            if (hadCompactController) AddActivity("Workspace", "Full controller");
        }

        private void SetMicroMode(bool enabled, bool save)
        {
            if (enabled)
            {
                if (_microMode) return;
                if (IsContextWorkspace(_workspaceProfile)) { CaptureWorkspaceContext(_workspaceProfile); _lastFullWorkspaceProfile = _workspaceProfile; }
                _performanceWorkspace = false;
                _microMode = true;
                _miniMode = true;
                _workspaceProfile = WorkspaceProfile.Micro;
                ApplyWorkspaceMode(save);
                return;
            }
            if (!_microMode) return;
            _microMode = false;
            _miniMode = false;
            WorkspaceProfile restore = IsContextWorkspace(_lastFullWorkspaceProfile) ? _lastFullWorkspaceProfile : WorkspaceProfile.Player;
            ApplyWorkspaceProfile(restore, save);
        }

        private void RefreshNowPlayingSelectableText()
        {
            if (_nowPlayingCombinedText == null || _nowPlayingCombinedText.Document == null) return;
            System.Windows.Documents.Paragraph title = null, channel = null;
            foreach (System.Windows.Documents.Block block in _nowPlayingCombinedText.Document.Blocks)
            {
                System.Windows.Documents.Paragraph paragraph = block as System.Windows.Documents.Paragraph;
                if (paragraph == null) continue;
                if (title == null) title = paragraph;
                else { channel = paragraph; break; }
            }
            Action<System.Windows.Documents.Paragraph, string> setText = delegate(System.Windows.Documents.Paragraph paragraph, string text)
            {
                if (paragraph == null) return;
                foreach (System.Windows.Documents.Inline inline in paragraph.Inlines)
                {
                    System.Windows.Documents.Run run = inline as System.Windows.Documents.Run;
                    if (run == null) continue;
                    run.Text = text ?? "";
                    return;
                }
            };
            setText(title, _titleText == null ? "" : _titleText.Text);
            setText(channel, _channelText == null ? "" : _channelText.Text);
        }

        private void ConfigureApplicationIdentity()
        {
            try
            {
                string canonical = Path.Combine(_appDir, "yomi.ico");
                string legacy = Path.Combine(_installRoot, "assets", "yomi-v408.ico");
                if (File.Exists(canonical))
                    _applicationIcon = new Drawing.Icon(canonical);
                else if (File.Exists(legacy))
                    _applicationIcon = new Drawing.Icon(legacy);
                else
                    _applicationIcon = Drawing.Icon.ExtractAssociatedIcon(Process.GetCurrentProcess().MainModule.FileName);

                if (_applicationIcon != null)
                {
                    var source = Imaging.CreateBitmapSourceFromHIcon(
                        _applicationIcon.Handle,
                        Int32Rect.Empty,
                        BitmapSizeOptions.FromEmptyOptions()
                    );
                    if (source != null)
                    {
                        source.Freeze();
                        _window.Icon = source;
                        var titleIcon = _window.FindName("TitleBarIcon") as Image;
                        if (titleIcon != null) titleIcon.Source = source;
                    }
                }
            }
            catch { }
        }

        private void ConfigureTray()
        {
            _tray = new Forms.NotifyIcon();
            try
            {
                _tray.Icon = _applicationIcon != null
                    ? (Drawing.Icon)_applicationIcon.Clone()
                    : Drawing.Icon.ExtractAssociatedIcon(Process.GetCurrentProcess().MainModule.FileName);
            }
            catch { }
            if (_tray.Icon == null)
                _tray.Icon = Drawing.SystemIcons.Application;
            _tray.Text = "YOMI";
            _tray.Visible = true;
            _tray.DoubleClick += delegate { RestoreFromTray(); };

            var menu = new Forms.ContextMenuStrip();
            var previousItem = menu.Items.Add("Previous", null, delegate { _window.Dispatcher.BeginInvoke(new Action(delegate { if (_running) NavigateRelative(-1); })); });
            var pauseItem = menu.Items.Add("Play / Pause", null, delegate { _window.Dispatcher.BeginInvoke(new Action(TogglePlayPause)); });
            var nextItem = menu.Items.Add("Next", null, delegate { _window.Dispatcher.BeginInvoke(new Action(delegate { if (_running) NavigateRelative(1); })); });
            menu.Items.Add(new Forms.ToolStripSeparator());
            var slotsItem = new Forms.ToolStripMenuItem("Session Manager");
            menu.Items.Add(slotsItem);
            menu.Items.Add(new Forms.ToolStripSeparator());
            var showItem = menu.Items.Add("Show YOMI", null, delegate { RestoreFromTray(); });
            var hideItem = menu.Items.Add("Hide to tray", null, delegate { _window.Dispatcher.BeginInvoke(new Action(HideToTray)); });
            var settingsItem = menu.Items.Add("Settings", null, delegate { _window.Dispatcher.BeginInvoke(new Action(delegate { RestoreFromTray(); OpenIntegratedSettings(); })); });
            menu.Items.Add(new Forms.ToolStripSeparator());
            menu.Items.Add("Stop YOMI and exit", null, delegate { _window.Dispatcher.BeginInvoke(new Action(StopYomiAndExit)); });
            menu.Opening += delegate
            {
                bool visible = _window.IsVisible;
                previousItem.Enabled = _running;
                pauseItem.Enabled = _running;
                nextItem.Enabled = _running;
                slotsItem.DropDownItems.Clear();
                SlotRecord[] traySlots = _slotItems.ToArray();
                for (int slotIndex = 0; slotIndex < traySlots.Length; slotIndex++)
                {
                    SlotRecord slot = traySlots[slotIndex];
                    string slotId = slot.Id; string slotName = slot.Name;
                    string prefix = slotIndex < 9 ? (slotIndex + 1).ToString(CultureInfo.InvariantCulture) + "   " : "    ";
                    var item = new Forms.ToolStripMenuItem(prefix + slotName);
                    item.Checked = String.Equals(slotId, _activeSlotId, StringComparison.OrdinalIgnoreCase);
                    item.Enabled = !_slotSwitchActive && !item.Checked;
                    item.ToolTipText = slot.ListSubtitle + (String.Equals(NormalizeSlotBroadcastPreset(slot.BroadcastPreset), "Keep current", StringComparison.OrdinalIgnoreCase) ? "" : " | " + slot.BroadcastSubtitle);
                    item.Click += delegate { _window.Dispatcher.BeginInvoke(new Action(delegate { SwitchListeningSlot(slotId, "tray"); })); };
                    slotsItem.DropDownItems.Add(item);
                }
                if (slotsItem.DropDownItems.Count == 0) slotsItem.DropDownItems.Add(new Forms.ToolStripMenuItem("No sessions") { Enabled = false });
                slotsItem.DropDownItems.Add(new Forms.ToolStripSeparator());
                var manageSlotsItem = new Forms.ToolStripMenuItem("Session Manager...");
                manageSlotsItem.Enabled = !_slotSwitchActive;
                manageSlotsItem.Click += delegate { _window.Dispatcher.BeginInvoke(new Action(delegate { RestoreFromTray(); OpenListeningSlots(); })); };
                slotsItem.DropDownItems.Add(manageSlotsItem);
                slotsItem.Enabled = !_slotSwitchActive;
                showItem.Enabled = !visible;
                hideItem.Enabled = visible;
                settingsItem.Enabled = true;
            };
            _tray.ContextMenuStrip = menu;
        }

        private void HideToTray()
        {
            if (!_window.IsVisible) return;
            _trayReturnFocus = Keyboard.FocusedElement;
            StopPreviewProcesses();
            _window.Hide();
        }

        private void RestoreFromTray()
        {
            _window.Dispatcher.BeginInvoke(new Action(delegate
            {
                bool wasHidden = !_window.IsVisible;
                _window.Show();
                if (_window.WindowState == WindowState.Minimized)
                    _window.WindowState = (_restoreMaximized && !_miniMode) ? WindowState.Maximized : WindowState.Normal;
                if (_window.WindowState == WindowState.Normal)
                    RestoreLogicalNormalGeometry();
                ConstrainWindowToVisibleWorkArea();
                _window.Activate();
                _window.Topmost = true;
                _window.Topmost = false;
                if (wasHidden)
                {
                    IInputElement restore = _trayReturnFocus;
                    _trayReturnFocus = null;
                    RestoreKeyboardFocus(restore);
                }
                RestartFramePreviewsAt(_timePosition, true);
                SafeRefresh(true);
            }));
        }

        private void CloseControllerOnly()
        {
            if (_disposed)
                return;
            _controllerOnlyClose = true;
            _window.Close();
        }

        private void StopYomiAndExit()
        {
            if (_disposed) return;
            if (_slotSwitchActive)
            {
                _shutdownRequested = true; _shutdownAfterSlotSwitch = true; Interlocked.Increment(ref _transportCommandEpoch); return;
            }
            if (_shutdownRequested) return;
            _shutdownRequested = true; Interlocked.Increment(ref _slotStateEpoch); Interlocked.Increment(ref _transportCommandEpoch);
            try { FinalizeListeningVisit(true,true); SlotRecord activeSlot; if(_slotsById.TryGetValue(_activeSlotId??"",out activeSlot)&&activeSlot!=null)CaptureLiveSlotBookmark(activeSlot); } catch { }
            if(!StopOwnedYomiRuntime()){_shutdownRequested=false;ReportShutdownOwnershipFailure();return;}
            PersistRepeatModeForTransition(_repeatMode); try{PersistActiveSlotState(false);}catch{} CloseControllerOnly();
        }

        private void ReportShutdownOwnershipFailure()
        {
            AddActivity("Shutdown", "ownership verification incomplete | controller retained");
            ShowToast("YOMI is still running", "Could not safely verify every owned runtime process. The controller was kept open.");
        }

        private void InitializeRuntimeJob()
        {
            if (_runtimeJobHandle != IntPtr.Zero) return;
            try
            {
                IntPtr job = CreateJobObject(IntPtr.Zero, null);
                if (job == IntPtr.Zero) return;
                JOBOBJECT_EXTENDED_LIMIT_INFORMATION info = new JOBOBJECT_EXTENDED_LIMIT_INFORMATION();
                info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
                int size = Marshal.SizeOf(typeof(JOBOBJECT_EXTENDED_LIMIT_INFORMATION));
                IntPtr buffer = Marshal.AllocHGlobal(size);
                try
                {
                    Marshal.StructureToPtr(info, buffer, false);
                    if (!SetInformationJobObject(job, JobObjectExtendedLimitInformation, buffer, (uint)size))
                    {
                        CloseHandle(job);
                        return;
                    }
                }
                finally { Marshal.FreeHGlobal(buffer); }
                _runtimeJobHandle = job;
                _runtimeJobConfigured = true;
            }
            catch { _runtimeJobHandle = IntPtr.Zero; _runtimeJobConfigured = false; }
        }

        private void RecordSupervisorRuntimeOwnership(int supervisorPid)
        {
            _runtimeJobOwnsSupervisor = true;
            _runtimeJobSupervisorPid = supervisorPid;
            try
            {
                Directory.CreateDirectory(_stateRoot);
                File.WriteAllText(Path.Combine(_stateRoot, "controller-runtime-owner.json"),
                    "{\"schema\":1,\"controller_pid\":" + Process.GetCurrentProcess().Id.ToString(CultureInfo.InvariantCulture) +
                    ",\"supervisor_pid\":" + supervisorPid.ToString(CultureInfo.InvariantCulture) +
                    ",\"kill_on_controller_exit\":true,\"spawn\":\"suspended-then-owned\"}", new UTF8Encoding(false));
            }
            catch { }
        }

        private bool OwnSupervisorWithRuntimeJob(Process supervisor)
        {
            if (supervisor == null) return false;
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero) InitializeRuntimeJob();
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero) return false;
            try
            {
                if (!AssignProcessToJobObject(_runtimeJobHandle, supervisor.Handle)) return false;
                RecordSupervisorRuntimeOwnership(supervisor.Id);
                return true;
            }
            catch { return false; }
        }

        private Process StartOwnedSupervisorSuspended(string executable, string arguments)
        {
            if (String.IsNullOrWhiteSpace(executable)) throw new ArgumentException("Supervisor executable is missing.", "executable");
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero) InitializeRuntimeJob();
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero)
                throw new InvalidOperationException("Windows could not create YOMI's crash-safe runtime job.");

            STARTUPINFO si = new STARTUPINFO();
            si.cb = (uint)Marshal.SizeOf(typeof(STARTUPINFO));
            PROCESS_INFORMATION pi;
            StringBuilder commandLine = new StringBuilder(Quote(executable) + " " + (arguments ?? ""));
            uint flags = CREATE_SUSPENDED | CREATE_NO_WINDOW;
            if (!CreateProcess(executable, commandLine, IntPtr.Zero, IntPtr.Zero, false, flags, IntPtr.Zero, _appDir, ref si, out pi))
                throw new Win32Exception(Marshal.GetLastWin32Error(), "Windows could not create the YOMI supervisor process.");

            bool resumed = false;
            try
            {
                // Critical ownership barrier: the supervisor is born suspended, joins the
                // kill-on-close Job, and only then is allowed to execute supervisor.ps1.
                // Therefore server/mpv descendants cannot escape through a start/assign race.
                if (!AssignProcessToJobObject(_runtimeJobHandle, pi.hProcess))
                    throw new Win32Exception(Marshal.GetLastWin32Error(), "Windows would not attach the YOMI supervisor to its runtime job.");
                RecordSupervisorRuntimeOwnership((int)pi.dwProcessId);
                uint resume = ResumeThread(pi.hThread);
                if (resume == 0xFFFFFFFFu)
                    throw new Win32Exception(Marshal.GetLastWin32Error(), "Windows could not resume the owned YOMI supervisor.");
                resumed = true;
                return Process.GetProcessById((int)pi.dwProcessId);
            }
            catch
            {
                try { TerminateProcess(pi.hProcess, 1); } catch { }
                _runtimeJobOwnsSupervisor = false;
                _runtimeJobSupervisorPid = 0;
                try { File.Delete(Path.Combine(_stateRoot, "controller-runtime-owner.json")); } catch { }
                throw;
            }
            finally
            {
                try { CloseHandle(pi.hThread); } catch { }
                try { CloseHandle(pi.hProcess); } catch { }
                if (!resumed)
                {
                    try { File.Delete(Path.Combine(_stateRoot, "supervisor.pid")); } catch { }
                }
            }
        }

        private bool OwnAuxiliaryProcessWithRuntimeJob(Process process)
        {
            if (process == null) return false;
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero) InitializeRuntimeJob();
            if (!_runtimeJobConfigured || _runtimeJobHandle == IntPtr.Zero) return false;
            try { return AssignProcessToJobObject(_runtimeJobHandle, process.Handle); }
            catch { return false; }
        }

        private bool TerminateOwnedRuntimeJob()
        {
            if (!_runtimeJobOwnsSupervisor || _runtimeJobHandle == IntPtr.Zero) return false;
            bool terminated = false;
            try { terminated = TerminateJobObject(_runtimeJobHandle, 0); } catch { }
            // TerminateJobObject is the authoritative process-tree stop. Do not sleep on the
            // caller (often the WPF thread) merely to make PID cleanup feel serialized; the
            // next engine launch is already deferred and validates runtime ownership afresh.
            foreach (string name in new[] { "supervisor.pid", "engine.pid", "server.pid" })
                try { File.Delete(Path.Combine(_stateRoot, name)); } catch { }
            try { File.Delete(Path.Combine(_stateRoot, "controller-runtime-owner.json")); } catch { }
            _runtimeJobOwnsSupervisor = false;
            _runtimeJobSupervisorPid = 0;
            return terminated;
        }

        private void CloseRuntimeJobHandle()
        {
            if (_runtimeJobHandle == IntPtr.Zero) return;
            try { CloseHandle(_runtimeJobHandle); } catch { }
            _runtimeJobHandle = IntPtr.Zero;
            _runtimeJobConfigured = false;
            _runtimeJobOwnsSupervisor = false;
            _runtimeJobSupervisorPid = 0;
        }

        private bool StopOwnedYomiRuntime()
        {
            try
            {
                Directory.CreateDirectory(_stateRoot);
                File.WriteAllText(Path.Combine(_stateRoot, "planned-stop.pending"), "1", Encoding.ASCII);
            }
            catch { }

            try { SendMpv("quit"); } catch { }
            try
            {
                // R61.59: runtime repair may execute from the OBS diagnostic worker. WPF preview teardown
                // must still happen on the UI dispatcher; process termination stays off the UI thread.
                if (_window != null && !_window.Dispatcher.CheckAccess())
                    _window.Dispatcher.Invoke(new Action(StopPreviewProcesses), DispatcherPriority.Send);
                else
                    StopPreviewProcesses();
            }
            catch { }

            // Authoritative R61.25 path: the supervisor and every descendant belong to
            // the controller's kill-on-close Job Object. Terminate the job as one unit.
            if (_runtimeJobOwnsSupervisor && _runtimeJobHandle != IntPtr.Zero)
            {
                bool stopped = TerminateOwnedRuntimeJob();
                if (stopped) return true;
            }

            // The OBS repair path can run here from a worker thread. Avoid the UI refresh cache and
            // its shared JavaScriptSerializer; take a one-shot runtime snapshot with thread-local parsing.
            Dictionary<string, object> runtime = ReadJsonUncached(Path.Combine(_stateRoot, "runtime-instance.json"));
            bool supervisorStopped = StopRuntimeRole("supervisor", "supervisor.pid", runtime);
            bool engineStopped = StopRuntimeRole("engine", "engine.pid", runtime);
            bool serverStopped = StopRuntimeRole("server", "server.pid", runtime);
            return supervisorStopped && engineStopped && serverStopped;
        }

        private bool StopRuntimeRole(string role, string pidFileName, Dictionary<string, object> runtime)
        {
            string pidFile = Path.Combine(_stateRoot, pidFileName);
            int pid = 0;
            try
            {
                if (!File.Exists(pidFile))
                    return true;
                if (!Int32.TryParse(File.ReadAllText(pidFile).Trim(), out pid) || pid <= 0)
                {
                    try { File.Delete(pidFile); } catch { }
                    return true;
                }
            }
            catch { return false; }

            Process process = null;
            try
            {
                try { process = Process.GetProcessById(pid); }
                catch
                {
                    try { File.Delete(pidFile); } catch { }
                    return true;
                }

                if (process.HasExited)
                {
                    try { File.Delete(pidFile); } catch { }
                    return true;
                }

                // R48: a live PID is ownership evidence. Never erase it merely because
                // provenance is incomplete; either verify + stop the process or retain the evidence.
                if (!RuntimeProcessIdentityMatches(process, role, runtime))
                    return false;

                process.Kill();
                // Legacy/non-Job fallback only. Keep the bounded confirmation short so a
                // broken runtime cannot freeze an otherwise responsive controller for ~5 s
                // while three roles are checked serially. Failure is safer than blocking.
                try { process.WaitForExit(450); } catch { }
                if (!process.HasExited)
                    return false;

                try { File.Delete(pidFile); } catch { }
                return true;
            }
            catch { return false; }
            finally
            {
                if (process != null) try { process.Dispose(); } catch { }
            }
        }

        private bool RuntimeProcessIdentityMatches(Process process, string role, Dictionary<string, object> runtime)
        {
            if (process == null)
                return false;

            var processes = GetMap(runtime, "processes");
            var identity = GetMap(processes, role);
            int recordedPid = GetInt(identity, "pid", 0);
            long recordedTicks = GetInt64(identity, "start_ticks_utc", 0L);
            string expectedPath = GetString(identity, "executable_path", "");

            if (recordedPid == process.Id && recordedTicks > 0)
            {
                try
                {
                    long actualTicks = process.StartTime.ToUniversalTime().Ticks;
                    if (Math.Abs(actualTicks - recordedTicks) > TimeSpan.TicksPerSecond * 2)
                        return false;
                }
                catch { return false; }

                if (!String.IsNullOrWhiteSpace(expectedPath))
                {
                    try
                    {
                        string actual = Path.GetFullPath(process.MainModule.FileName);
                        if (!String.Equals(actual, Path.GetFullPath(expectedPath), StringComparison.OrdinalIgnoreCase))
                            return false;
                    }
                    catch { return false; }
                }
                return true;
            }

            // Older retained runtime records may lack process provenance. Engine fallback is
            // still safe because the authoritative engine PID must name the bundled mpv process.
            if (String.Equals(role, "engine", StringComparison.OrdinalIgnoreCase))
            {
                try
                {
                    string name = process.ProcessName ?? "";
                    string path = Path.GetFullPath(process.MainModule.FileName);
                    return String.Equals(name, "mpv", StringComparison.OrdinalIgnoreCase) &&
                           path.StartsWith(_runtimeRoot + Path.DirectorySeparatorChar, StringComparison.OrdinalIgnoreCase);
                }
                catch { return false; }
            }
            return false;
        }

        private void ToggleMaximize()
        {
            // Preserve the last deliberate normal bounds before Windows begins resizing
            // the borderless window. SizeChanged can otherwise sample near-maximized
            // transition geometry and accidentally make that the next restore size.
            if (_window.WindowState == WindowState.Normal)
                CaptureNormalWindowGeometry();

            _windowStateTransition = true;
            try
            {
                _window.WindowState = _window.WindowState == WindowState.Maximized
                    ? WindowState.Normal
                    : WindowState.Maximized;
            }
            finally
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    if (_window.WindowState == WindowState.Normal) RestoreLogicalNormalGeometry();
                    _windowStateTransition = false;
                }));
            }
        }

        private void UpdateMaximizeGlyph()
        {
            if (_maximizeGlyph == null)
                return;
            if (_window.WindowState == WindowState.Maximized)
            {
                _maximizeGlyph.Data = Geometry.Parse("M 5,3 L 13,3 13,11 M 3,5 L 11,5 11,13 3,13 Z");
                _maximizeButton.ToolTip = "Restore";
            }
            else
            {
                _maximizeGlyph.Data = Geometry.Parse("M 3,3 L 13,3 13,13 3,13 Z");
                _maximizeButton.ToolTip = "Maximize";
            }
        }

        private void TogglePlayPause()
        {
            if (_startupPrewarmReady)
            {
                _startupPrewarmReady = false;
                _startupPrewarmPlayLatched = true;
                PrepareExplicitPlayStartupIntent();
                ApplyPrimaryTransportGlyph();
                WriteControllerPerformanceLogAsync("PREWARM READY explicit Play requested");
                ResumeLatchedStartupPrewarm();
                return;
            }

            if (_startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm))
            {
                _startupPrewarmPlayLatched = true;
                PrepareExplicitPlayStartupIntent();
                ApplyPrimaryTransportGlyph();
                WriteControllerPerformanceLogAsync("PREWARM PLAY LATCH captured by transport button");
                return;
            }

            if (!_running)
            {
                StartEngine(true);
                return;
            }

            // Toggle only confirmed active audio. A live MPV process is not the same
            // thing as a playing track: PREPARING / STARTING / COMPLETE / ERROR must
            // never turn the button into a misleading pause control.
            if (_audioActive)
            {
                bool basis = _pauseIntentPending ? _pauseIntentState : _paused;
                bool targetPause = !basis;
                long serial = ++_pauseIntentSerial;
                _pauseIntentPending = true;
                _pauseIntentState = targetPause;
                // Project the user's pause/resume intent onto local previews immediately.
                // Audio authority still belongs to MPV; a rejected command rolls this back.
                ApplyPreviewPauseProjection(targetPause);
                DispatchTransportCommand(new object[] { "set_property", "pause", targetPause }, delegate(bool accepted)
                {
                    if (serial != _pauseIntentSerial) return;
                    _pauseIntentPending = false;
                    if (accepted)
                    {
                        _paused = targetPause;
                        ProjectPlaybackSnapshotPause(targetPause);
                        ApplyPreviewPauseProjection(targetPause);
                        ApplyPrimaryTransportGlyph();
                        ScheduleFastPlaybackRefresh();
                    }
                    else
                    {
                        ApplyPreviewPauseProjection(_paused);
                        ShowToast("Playback", targetPause ? "Pause command was not accepted." : "Resume command was not accepted.");
                        ScheduleFastPlaybackRefresh();
                    }
                });
                return;
            }

            string phase = (_lastPlaybackPhase ?? "").ToLowerInvariant();
            if (phase == "preparing" || phase == "starting" || phase == "advancing")
            {
                ScheduleFastPlaybackRefresh();
                return;
            }

            int occurrence = _currentOccurrence > 0 ? _currentOccurrence : (_currentSlot > 0 && _currentSlot <= _order.Count ? _order[_currentSlot - 1] : 0);
            if (occurrence > 0)
            {
                DispatchTransportCommand(new object[] { "script-message", "yomi-jump", occurrence.ToString(CultureInfo.InvariantCulture) }, delegate(bool accepted)
                {
                    if (accepted)
                    {
                        BeginPlaybackTransitionProjection();
                        _lastStateRefreshMs = 0;
                        _lastQueueRefreshMs = 0;
                        ScheduleFastPlaybackRefresh();
                    }
                    else
                    {
                        ShowToast("Playback", "The engine is running, but the play request was not accepted.");
                    }
                });
                return;
            }

            ShowToast("Playback", "The engine is running, but no playable occurrence is ready yet.");
        }

        private void StartEngine()
        {
            StartEngine(false, false);
        }

        private void PrepareExplicitPlayStartupIntent()
        {
            // R61.82: explicit Play is a one-launch command intent, not a durable-state rewrite.
            // The supervisor carries -ExplicitPlay to mpv/Lua, so the WPF input path performs no
            // synchronous slot/config I/O and crash recovery still restores a saved paused state.
            _paused = false;
            _pauseIntentPending = false;
            _pauseIntentState = false;
            _previewPauseState = false;
            WriteControllerPerformanceLogAsync("PLAY STARTUP INTENT explicit resume requested for supervisor launch");
        }

        private void StartEngine(bool explicitPlayIntent)
        {
            StartEngine(explicitPlayIntent, false);
        }

        private void BeginStartupPrewarm()
        {
            if (_disposed || _running || _engineLaunchMonitorActive || _startupPrewarmInFlight) return;
            _startupPrewarmInFlight = true;
            _startupPrewarmPlayLatched = false;
            _startupPrewarmReady = false;
            _startupPrewarmResumeAttempts = 0;
            WriteControllerPerformanceLogAsync("PREWARM START audio-first after shell paint");
            StartEngine(false, true);
        }

        private void ResumeLatchedStartupPrewarm()
        {
            if (_disposed || !_startupPrewarmPlayLatched) return;
            int attempt = ++_startupPrewarmResumeAttempts;
            DispatchTransportCommand(new object[] { "set_property", "pause", false }, delegate(bool accepted)
            {
                if (_disposed || !_startupPrewarmPlayLatched) return;
                if (accepted)
                {
                    _startupPrewarmPlayLatched = false;
                    _startupPrewarmReady = false;
                    _startupPrewarmResumeAttempts = 0;
                    _paused = false;
                    _pauseIntentPending = false;
                    _pauseIntentState = false;
                    ProjectPlaybackSnapshotPause(false);
                    ApplyPreviewPauseProjection(false);
                    ApplyPrimaryTransportGlyph();
                    WriteControllerPerformanceLogAsync("PREWARM PLAY LATCH resumed on warmed engine");
                    ScheduleFastPlaybackRefresh();
                    return;
                }
                if (attempt >= 12)
                {
                    // Preserve the user's Play intent across a stubborn warm-control handoff.
                    // Re-enter the explicit startup path without clearing the latch; if a supervisor
                    // already owns mpv, that path now drives the same acknowledged resume instead
                    // of silently treating the existing process as success.
                    _startupPrewarmResumeAttempts = 0;
                    WriteControllerPerformanceLogAsync("PREWARM PLAY LATCH resume ACK delayed; reasserting explicit intent");
                    StartEngine(true, false);
                    return;
                }
                var retry = new DispatcherTimer(DispatcherPriority.Background, _window.Dispatcher);
                retry.Interval = TimeSpan.FromMilliseconds(120);
                retry.Tick += delegate
                {
                    retry.Stop();
                    ResumeLatchedStartupPrewarm();
                };
                retry.Start();
            });
        }

        private void StartEngine(bool explicitPlayIntent, bool prewarm)
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive) return;
            lock (_runtimeLivenessSync) { _runtimeLivenessGeneration++; _runtimeLivenessValid = false; _enginePidLiveCached = false; _supervisorPidLiveCached = false; _runtimeLivenessStampMs = -10000; }
            lock (_playbackSnapshotSync) { _playbackSnapshotGeneration++; _playbackSnapshotValid = false; _playbackSnapshotStampMs = -10000; _playbackSnapshotPosition = -1; }
            lock (_presentationDemandSync) { _presentationDemandGeneration++; _presentationDemandPendingKey = ""; _presentationDemandLastAcceptedKey = ""; _presentationDemandRuntimeId = ""; _presentationDemandLastAcceptedMs = -10000; }
            lock (_volumeSnapshotSync) { _volumeSnapshotGeneration++; _volumeSnapshotValid = false; _volumeSnapshotStampMs = -10000; }
            // R61.86: the button press itself remains a pure UI transaction. Disk, PID/process
            // inspection, stale-file cleanup and CreateProcess all run on a worker. This closes
            // the last cold-Play path where Defender or a slow filesystem could wedge WPF.
            if (_engineLaunchMonitorActive)
            {
                if (explicitPlayIntent && _engineLaunchPrewarm)
                {
                    _startupPrewarmPlayLatched = true;
                    PrepareExplicitPlayStartupIntent();
                    WriteControllerPerformanceLogAsync("PREWARM PLAY LATCH captured while warm startup is in flight");
                }
                ScheduleFastPlaybackRefresh();
                return;
            }
            if (_clock.ElapsedMilliseconds - _engineLaunchRequestedMs < 4000)
            {
                ScheduleFastPlaybackRefresh();
                return;
            }

            if (explicitPlayIntent) PrepareExplicitPlayStartupIntent();
            _engineLaunchPrewarm = prewarm;
            if (prewarm)
            {
                _startupPrewarmInFlight = true;
                _startupPrewarmReady = false;
            }
            _engineLaunchRequestedMs = _clock.ElapsedMilliseconds;
            _engineLaunchMonitorActive = true;
            int launchGeneration = ++_engineLaunchGeneration;
            ApplyPrimaryTransportGlyph();
            UpdateTransportAvailability(_lastPlaybackPhase, true);
            ScheduleFastPlaybackRefresh();

            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                long workerStarted = _clock.ElapsedMilliseconds;
                string supervisor = Path.Combine(_appDir, "supervisor.ps1");
                string supervisorPid = Path.Combine(_stateRoot, "supervisor.pid");
                Process child = null;
                string immediateFailure = "";
                bool existingSupervisor = false;
                long staleProbeMs = 0;
                long spawnMs = 0;

                try
                {
                    if (_disposed || launchGeneration != _engineLaunchGeneration) return;
                    if (!File.Exists(supervisor))
                    {
                        immediateFailure = "supervisor.ps1 is missing from the installation.";
                    }
                    else
                    {
                        long staleStarted = _clock.ElapsedMilliseconds;
                        // Stale pid files should never turn Play into a no-op or false success,
                        // but proving staleness can touch both disk and the Windows process table.
                        // That proof belongs entirely off the dispatcher.
                        foreach (string stalePid in new[] { "supervisor.pid", "engine.pid", "server.pid" })
                        {
                            string stalePath = Path.Combine(_stateRoot, stalePid);
                            if (!File.Exists(stalePath)) continue;
                            if (!ProbePidFileLive(stalePath))
                            {
                                try { File.Delete(stalePath); } catch { }
                            }
                        }
                        existingSupervisor = ProbePidFileLive(supervisorPid);
                        bool existingEngine = ProbePidFileLive(Path.Combine(_stateRoot, "engine.pid"));
                        PublishRuntimeLivenessSnapshot(existingEngine, existingSupervisor);
                        staleProbeMs = _clock.ElapsedMilliseconds - staleStarted;

                        if (!existingSupervisor && !_disposed && launchGeneration == _engineLaunchGeneration)
                        {
                            try
                            {
                                Directory.CreateDirectory(_stateRoot);
                                try { File.Delete(Path.Combine(_stateRoot, "startup-flight.json")); } catch { }
                                File.WriteAllText(Path.Combine(_stateRoot, "supervisor-status.txt"), prewarm ? "Controller is prewarming the last session..." : "Controller requested playback...", Encoding.UTF8);
                            }
                            catch { }

                            string powershell = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
                            string supervisorArgs = "-NoProfile -NonInteractive -ExecutionPolicy Bypass -STA -File " + Quote(supervisor) +
                                (explicitPlayIntent ? " -ExplicitPlay" : "") + (prewarm ? " -Prewarm" : "");
                            long spawnStarted = _clock.ElapsedMilliseconds;
                            child = StartOwnedSupervisorSuspended(powershell, supervisorArgs);
                            spawnMs = _clock.ElapsedMilliseconds - spawnStarted;
                            if (child == null) immediateFailure = "Windows did not create the YOMI supervisor process.";
                        }
                    }
                }
                catch (Exception ex)
                {
                    immediateFailure = "Could not launch supervisor.ps1: " + ex.Message;
                }

                long setupMs = _clock.ElapsedMilliseconds - workerStarted;
                WriteControllerPerformanceLogAsync("PLAY LAUNCH SETUP total=" + setupMs.ToString(CultureInfo.InvariantCulture) +
                    "ms stale_pid=" + staleProbeMs.ToString(CultureInfo.InvariantCulture) +
                    "ms spawn=" + spawnMs.ToString(CultureInfo.InvariantCulture) +
                    "ms existing_supervisor=" + (existingSupervisor ? "1" : "0") +
                    " prewarm=" + (prewarm ? "1" : "0") +
                    " ui_thread=0");

                if (_disposed || launchGeneration != _engineLaunchGeneration)
                {
                    if (child != null) try { child.Dispose(); } catch { }
                    return;
                }

                if (!String.IsNullOrWhiteSpace(immediateFailure))
                {
                    string failure = immediateFailure;
                    TryBeginInvokeUi(DispatcherPriority.Normal, delegate
                    {
                        if (_disposed || launchGeneration != _engineLaunchGeneration) return;
                        bool failedPrewarm = _engineLaunchPrewarm && !explicitPlayIntent && !_startupPrewarmPlayLatched;
                        _engineLaunchMonitorActive = false;
                        _engineLaunchPrewarm = false;
                        _startupPrewarmInFlight = false;
                        _startupPrewarmReady = false;
                        _engineLaunchRequestedMs = -10000;
                        ApplyPrimaryTransportGlyph();
                        if (failedPrewarm)
                        {
                            WriteControllerPerformanceLogAsync("PREWARM SILENT FAILURE " + failure);
                        }
                        else
                        {
                            ShowToast("Playback could not start", failure);
                        }
                        RefreshRuntimeLiveness(true);
                        SafeRefresh(true);
                    });
                    if (child != null) try { child.Dispose(); } catch { }
                    return;
                }

                if (existingSupervisor)
                {
                    TryBeginInvokeUi(DispatcherPriority.Normal, delegate
                    {
                        if (_disposed || launchGeneration != _engineLaunchGeneration) return;
                        _engineLaunchMonitorActive = false;
                        _engineLaunchPrewarm = false;
                        _startupPrewarmInFlight = false;
                        _engineLaunchRequestedMs = -10000;
                        SafeRefresh(true);
                        _startupPrewarmReady = prewarm && CachedEngineLive() && !explicitPlayIntent;
                        ApplyPrimaryTransportGlyph();
                        UpdateStatusBarProjection();
                        if (explicitPlayIntent)
                        {
                            _startupPrewarmPlayLatched = true;
                            WriteControllerPerformanceLogAsync("PLAY STARTUP INTENT existing supervisor; acknowledged resume requested");
                            ResumeLatchedStartupPrewarm();
                        }
                    });
                    return;
                }

                int checks = 0;
                string outcome = "";
                string outcomeDetail = "";
                int outcomeExitCode = -1;
                while (checks < 250)
                {
                    if (_disposed || launchGeneration != _engineLaunchGeneration)
                    {
                        outcome = "cancelled";
                        break;
                    }
                    checks++;
                    bool engineLive = ProbePidFileLive(Path.Combine(_stateRoot, "engine.pid"));
                    
                    // Startup authority is acquired off the WPF dispatcher. Slow AV/disk access
                    // can delay this monitor without ever preventing the window from repainting.
                    Dictionary<string, object> startupFlight = ReadJsonFresh(Path.Combine(_stateRoot, "startup-flight.json"));
                    string startupStage = GetString(startupFlight, "stage", "").ToLowerInvariant();
                    bool startupComplete = GetBool(startupFlight, "complete", false) &&
                        (startupStage == "first_sound" || startupStage == "media_ready_paused");
                    Dictionary<string, object> startupEngine = ReadJsonFresh(Path.Combine(_stateRoot, "engine-status.json"));
                    string startupPhase = GetString(startupEngine, "phase", "").ToLowerInvariant();
                    bool engineMediaReady = startupPhase == "playing" || startupPhase == "paused";
                    bool startupAuthorityReady = startupComplete || engineMediaReady;
                    if (engineLive && startupAuthorityReady)
                    {
                        PublishRuntimeLivenessSnapshot(true, ProbePidFileLive(supervisorPid));
                        outcome = "ready";
                        break;
                    }

                    bool exited = false;
                    try
                    {
                        exited = child == null || child.HasExited;
                        if (child != null && exited) outcomeExitCode = child.ExitCode;
                    }
                    catch { exited = true; }
                    if (exited)
                    {
                        outcome = "exited";
                        outcomeDetail = ReadPlaybackStartupDetail();
                        PublishRuntimeLivenessSnapshot(ProbePidFileLive(Path.Combine(_stateRoot, "engine.pid")), ProbePidFileLive(supervisorPid));
                        break;
                    }
                    Thread.Sleep(80);
                }
                if (String.IsNullOrWhiteSpace(outcome))
                {
                    outcome = "timeout";
                    outcomeDetail = ReadPlaybackStartupDetail();
                }

                string finalOutcome = outcome;
                string finalDetail = outcomeDetail;
                int finalExitCode = outcomeExitCode;
                TryBeginInvokeUi(DispatcherPriority.Normal, delegate
                {
                    if (_disposed || launchGeneration != _engineLaunchGeneration)
                    {
                        if (child != null) try { child.Dispose(); } catch { }
                        return;
                    }
                    bool completedPrewarm = _engineLaunchPrewarm;
                    _engineLaunchMonitorActive = false;
                    _engineLaunchPrewarm = false;
                    _startupPrewarmInFlight = false;
                    if (finalOutcome == "ready")
                    {
                        _engineLaunchRequestedMs = -10000;
                        bool resumeWarmPlay = completedPrewarm && _startupPrewarmPlayLatched;
                        _startupPrewarmReady = completedPrewarm && !resumeWarmPlay;
                        SafeRefresh(true);
                        ApplyPrimaryTransportGlyph();
                        UpdateStatusBarProjection();
                        if (resumeWarmPlay) ResumeLatchedStartupPrewarm();
                    }
                    else if (finalOutcome == "exited")
                    {
                        _startupPrewarmReady = false;
                        _engineLaunchRequestedMs = -10000;
                        string detail = finalDetail;
                        if (String.IsNullOrWhiteSpace(detail))
                            detail = "The supervisor exited before MPV started (exit " + finalExitCode.ToString(CultureInfo.InvariantCulture) + ").";
                        if (completedPrewarm && !_startupPrewarmPlayLatched)
                            WriteControllerPerformanceLogAsync("PREWARM SILENT EXIT " + detail);
                        else
                            ShowToast("Playback did not start", detail);
                        RefreshRuntimeLiveness(true);
                    }
                    else if (finalOutcome == "timeout")
                    {
                        _startupPrewarmReady = false;
                        string detail = finalDetail;
                        if (String.IsNullOrWhiteSpace(detail)) detail = "Startup authority timed out after 21 seconds.";
                        if (completedPrewarm && !_startupPrewarmPlayLatched)
                            WriteControllerPerformanceLogAsync("PREWARM SILENT TIMEOUT " + detail);
                        else
                            ShowToast("Playback could not start", detail);
                        RefreshRuntimeLiveness(true);
                        SafeRefresh(true);
                    }
                    ApplyPrimaryTransportGlyph();
                    if (child != null) try { child.Dispose(); } catch { }
                });
            });
        }

        private string FriendlyStartupFlightDetail(Dictionary<string, object> flight)
        {
            if (flight == null || flight.Count == 0) return "";
            string stage = GetString(flight, "stage", "").Trim().ToLowerInvariant();
            string waiting = GetString(flight, "waiting_stage", "").Trim().ToLowerInvariant();
            int elapsedMs = GetInt(flight, "elapsed_ms", 0);
            string seconds = elapsedMs > 0 ? " (" + (elapsedMs / 1000.0).ToString("0.0", CultureInfo.InvariantCulture) + "s)" : "";
            if (stage == "deadline_exceeded" && waiting.Length > 0) stage = waiting;
            switch (stage)
            {
                case "script_loaded": return "Playback engine loaded; preparing the session" + seconds + ".";
                case "playlist_ready": return "Playlist loaded; restoring the listening session" + seconds + ".";
                case "session_ready": return "Listening session restored; arming playback" + seconds + ".";
                case "runtime_ready": return "Playback runtime is ready; starting the selected track" + seconds + ".";
                case "cache_check": return "Checking the selected track's cache identity" + seconds + ".";
                case "stream_resolving": return "Waiting for YouTube to resolve the selected audio stream" + seconds + ".";
                case "stream_route": return "Trying a bounded YouTube resolver route" + seconds + ".";
                case "stream_retry": return "The first YouTube resolver route was slow; trying the lightweight fallback" + seconds + ".";
                case "stream_resolve_failed": return "The selected track could not produce a stream inside the fast-start window; YOMI is moving on" + seconds + ".";
                case "cache_fallback": return "Direct streaming did not resolve; preparing local audio" + seconds + ".";
                case "loadfile_stream": return "MPV received the audio stream; waiting for audio output" + seconds + ".";
                case "loadfile_cache": return "MPV received cached audio; waiting for audio output" + seconds + ".";
                case "file_loaded": return "The track is loaded; waiting for audio output" + seconds + ".";
                case "playlist_empty": return "The active listening session has no playable playlist entries.";
                case "shutdown_before_first_sound": return "Playback stopped before first sound was confirmed" + seconds + ".";
                default:
                    string detail = GetString(flight, "detail", "").Trim();
                    return detail.Length > 0 ? detail + seconds : "";
            }
        }

        private string ReadPlaybackStartupDetail()
        {
            string status = "";
            string lastLog = "";
            string flightDetail = FriendlyStartupFlightDetail(ReadJsonFresh(Path.Combine(_stateRoot, "startup-flight.json")));
            try
            {
                string path = Path.Combine(_stateRoot, "supervisor-status.txt");
                if (File.Exists(path)) status = File.ReadAllText(path, Encoding.UTF8).Trim();
            }
            catch { }
            try
            {
                string logPath = Path.Combine(_dataRoot, "logs", "supervisor.log");
                if (File.Exists(logPath))
                {
                    string[] lines = File.ReadAllLines(logPath, Encoding.UTF8);
                    for (int i = lines.Length - 1; i >= 0; i--)
                    {
                        string candidate = (lines[i] ?? "").Trim();
                        if (!String.IsNullOrWhiteSpace(candidate))
                        {
                            lastLog = candidate;
                            break;
                        }
                    }
                }
            }
            catch { }

            bool genericStatus = String.IsNullOrWhiteSpace(status) ||
                                 status.IndexOf("Controller requested playback", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                 status.IndexOf("Starting YOMI", StringComparison.OrdinalIgnoreCase) >= 0 ||
                                 status.IndexOf("Player started; preparing", StringComparison.OrdinalIgnoreCase) >= 0;
            if (!String.IsNullOrWhiteSpace(flightDetail)) return flightDetail;
            if (genericStatus && !String.IsNullOrWhiteSpace(lastLog)) return lastLog;
            if (!String.IsNullOrWhiteSpace(status) && !String.IsNullOrWhiteSpace(lastLog) &&
                lastLog.IndexOf(status, StringComparison.OrdinalIgnoreCase) < 0)
                return status + "  |  " + lastLog;
            if (!String.IsNullOrWhiteSpace(status)) return status;
            return lastLog;
        }

        private void SafeRefresh(bool force)
        {
            if (_slotSwitchActive && !_slotSwitchProjectionCommit) return;
            try
            {
                RefreshAll(force);
            }
            catch (Exception ex)
            {
                try
                {
                    _systemStatusText.Text = "Controller presentation error isolated; playback continues.";
                    _headerStateText.Text = "Needs attention";
                    _headerStateText.Foreground = Brush("Warning");
                    string errorText = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) + " " + ex + Environment.NewLine;
                    ThreadPool.QueueUserWorkItem(delegate
                    {
                        try
                        {
                            Directory.CreateDirectory(Path.Combine(_dataRoot, "logs"));
                            File.AppendAllText(Path.Combine(_dataRoot, "logs", "controller-wpf-errors.log"), errorText, new UTF8Encoding(false));
                        }
                        catch { }
                    });
                }
                catch { }
            }
            finally { _uiOperationPhase = "idle"; }
        }

        private void RefreshAll(bool force)
        {
            if (_disposed)
                return;

            long now = _clock.ElapsedMilliseconds;
            long phaseStart = now;
            long queueMs = 0, playbackMs = 0, auxiliaryMs = 0;
            bool budgetPressure = now < _uiBudgetPressureUntilMs;
            _uiOperationPhase = "runtime-liveness";
            RefreshRuntimeLiveness(force);
            // Under demonstrated dispatcher pressure, retain playback responsiveness while allowing
            // queue/background projection to breathe. Force refreshes always bypass the governor.
            bool stateDue = force || now - _lastStateRefreshMs >= (budgetPressure ? 450 : 300);
            bool queueDue = force || now - _lastQueueRefreshMs >= (budgetPressure ? 1800 : 900);

            // On authoritative/first refresh, establish session/order metadata first so
            // the playback projection can name the requested occurrence without a stale
            // one-frame fallback. Background cadence remains playback-first and restrained.
            if (force && queueDue)
            {
                long started = _clock.ElapsedMilliseconds;
                _lastQueueRefreshMs = now;
                _uiOperationPhase = "queue-authoritative";
                RefreshQueueState(true);
                queueMs += _clock.ElapsedMilliseconds - started;
                queueDue = false;
            }
            if (stateDue)
            {
                long started = _clock.ElapsedMilliseconds;
                _lastStateRefreshMs = now;
                _uiOperationPhase = "playback-projection";
                RefreshPlaybackState();
                playbackMs += _clock.ElapsedMilliseconds - started;
            }
            if (queueDue)
            {
                long started = _clock.ElapsedMilliseconds;
                _lastQueueRefreshMs = now;
                _uiOperationPhase = "queue-incremental";
                RefreshQueueState(false);
                queueMs += _clock.ElapsedMilliseconds - started;
            }

            long auxiliaryStarted = _clock.ElapsedMilliseconds;
            _uiOperationPhase = "auxiliary-projection";
            RefreshVolumeState(force);
            MaybeSelfHealPlaybackEngine(now);
            MaybeSelfHealObsOutput(now, ReadJsonCached(Path.Combine(_dataRoot, "config.json")));
            FlushLibraryStateIfDue(false);
            CheckpointActiveSlotBookmarkIfDue(now);
            auxiliaryMs = _clock.ElapsedMilliseconds - auxiliaryStarted;
            _uiOperationPhase = "idle";

            long totalMs = _clock.ElapsedMilliseconds - phaseStart;
            _lastRefreshDurationMs = (int)Math.Min(Int32.MaxValue, Math.Max(0, totalMs));
            _uiRefreshEmaMs = _uiRefreshEmaMs <= 0.01 ? totalMs : (_uiRefreshEmaMs * 0.88) + (totalMs * 0.12);
            string budgetCulprit = queueMs >= playbackMs && queueMs >= auxiliaryMs ? "queue" :
                (playbackMs >= auxiliaryMs ? "playback" : "auxiliary");
            if (!force && totalMs > UiRefreshBudgetMs)
            {
                _uiBudgetOverrunCount++;
                _uiBudgetPressureUntilMs = Math.Max(_uiBudgetPressureUntilMs, _clock.ElapsedMilliseconds + 2400);
                if (_clock.ElapsedMilliseconds - _lastUiBudgetLogMs >= 2500)
                {
                    _lastUiBudgetLogMs = _clock.ElapsedMilliseconds;
                    WriteControllerPerformanceLogAsync("UI BUDGET PRESSURE refresh=" + totalMs.ToString(CultureInfo.InvariantCulture) +
                        "ms ema=" + _uiRefreshEmaMs.ToString("0.0", CultureInfo.InvariantCulture) +
                        "ms overruns=" + _uiBudgetOverrunCount.ToString(CultureInfo.InvariantCulture) +
                        " culprit=" + budgetCulprit +
                        " queue=" + queueMs.ToString(CultureInfo.InvariantCulture) +
                        "ms playback=" + playbackMs.ToString(CultureInfo.InvariantCulture) +
                        "ms auxiliary=" + auxiliaryMs.ToString(CultureInfo.InvariantCulture) + "ms");
                }
            }
            if (totalMs >= 90 && _clock.ElapsedMilliseconds - _lastRefreshBreakdownLogMs >= 1500)
            {
                _lastRefreshBreakdownLogMs = _clock.ElapsedMilliseconds;
                WriteControllerPerformanceLogAsync("REFRESH BREAKDOWN total=" + totalMs.ToString(CultureInfo.InvariantCulture) +
                    "ms playback=" + playbackMs.ToString(CultureInfo.InvariantCulture) +
                    "ms queue=" + queueMs.ToString(CultureInfo.InvariantCulture) +
                    "ms auxiliary=" + auxiliaryMs.ToString(CultureInfo.InvariantCulture) + "ms");
            }

            UpdateStatusBarProjection();
            SchedulePresentationStatusWrite(false);

            if (_pendingOrderMutationRevision >= 0 &&
                now - _pendingOrderMutationStartedMs > 5000)
            {
                AddActivity("Queue reorder", "no authoritative revision observed");
                ShowToast("Reorder not confirmed", "The engine did not publish a new order revision.");
                ClearPendingOrderMutation();
                if (_queueRevisionText != null)
                    _queueRevisionText.Text = Math.Max(0, _orderRevision).ToString(CultureInfo.InvariantCulture);
            }
        }

        private void PublishRuntimeLivenessSnapshot(bool engine, bool supervisor)
        {
            lock (_runtimeLivenessSync)
            {
                _enginePidLiveCached = engine;
                _supervisorPidLiveCached = supervisor;
                _runtimeLivenessValid = true;
                _runtimeLivenessStampMs = _clock.ElapsedMilliseconds;
            }
        }

        private void RefreshRuntimeLiveness(bool force)
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive) return;
            int generation;
            lock (_runtimeLivenessSync)
            {
                long age = _clock.ElapsedMilliseconds - _runtimeLivenessStampMs;
                if (_runtimeLivenessWorkerActive) return;
                if (!force && _runtimeLivenessValid && age < 250) return;
                _runtimeLivenessWorkerActive = true; generation = _runtimeLivenessGeneration;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                long started = _clock.ElapsedMilliseconds;
                bool engine = ProbePidFileLive(Path.Combine(_stateRoot, "engine.pid"));
                bool supervisor = ProbePidFileLive(Path.Combine(_stateRoot, "supervisor.pid"));
                long elapsed = _clock.ElapsedMilliseconds - started;
                lock (_runtimeLivenessSync)
                {
                    if (generation == _runtimeLivenessGeneration && !_shutdownRequested && !_slotSwitchActive)
                    { _enginePidLiveCached = engine; _supervisorPidLiveCached = supervisor; _runtimeLivenessValid = true; _runtimeLivenessStampMs = _clock.ElapsedMilliseconds; }
                    _runtimeLivenessWorkerActive = false;
                }
                if (elapsed >= 40) WriteControllerPerformanceLogAsync("RUNTIME LIVENESS PROBE " + elapsed.ToString(CultureInfo.InvariantCulture) + "ms ui_thread=0");
            });
        }

        private bool CachedEngineLive()
        {
            lock (_runtimeLivenessSync) return _runtimeLivenessValid && _enginePidLiveCached;
        }

        private bool CachedSupervisorLive()
        {
            lock (_runtimeLivenessSync) return _runtimeLivenessValid && _supervisorPidLiveCached;
        }

        private static bool ProbePidFileLive(string path)
        {
            try
            {
                if (!File.Exists(path)) return false;
                int pid;
                if (!Int32.TryParse(File.ReadAllText(path).Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out pid) || pid <= 0) return false;
                using (var process = Process.GetProcessById(pid)) return !process.HasExited;
            }
            catch { return false; }
        }

        private void RefreshPlaybackState()
        {
            var current = ReadJsonCached(Path.Combine(_stateRoot, "current.json"));
            var engine = ReadJsonCached(Path.Combine(_stateRoot, "engine-status.json"));
            var queue = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
            var config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));

            _running = CachedEngineLive();
            ObservePresentationDemandRuntime(current, engine);
            if (!_running)
            {
                lock (_playbackSnapshotSync)
                {
                    _playbackSnapshotValid = false;
                    _playbackSnapshotPosition = -1;
                }
            }
            string phase = GetString(engine, "phase", _running ? "starting" : "stopped").ToLowerInvariant();
            bool enginePaused = GetBool(engine, "paused", false);
            bool idleActive = true;
            bool mpvPaused = enginePaused;
            double mpvPosition = -1;
            bool haveMpvSnapshot = _running && TryGetMpvPlaybackSnapshot(out idleActive, out mpvPaused, out mpvPosition);
            if (haveMpvSnapshot)
            {
                // A decoded/loaded file is not audible playback. During preparing/starting/advancing,
                // mpv may already expose a time position while buffering or handoff is still pending.
                // Only the engine's playback-restart-confirmed PLAYING/PAUSED phases may light the
                // desktop controller as active playback.
                bool phaseClaimsAudiblePlayback = phase == "playing" || phase == "paused";
                _audioActive = !idleActive && phaseClaimsAudiblePlayback;
                _paused = _audioActive && mpvPaused;
                if (_audioActive && _paused) phase = "paused";
                else if (_audioActive && phase == "paused") phase = "playing";
            }
            else
            {
                _audioActive = _running && (phase == "playing" || phase == "paused");
                _paused = _audioActive && (phase == "paused" || enginePaused);
            }
            _lastPlaybackPhase = phase;

            int currentOccurrence = GetInt(current, "occurrence_id", GetInt(current, "index", 0));
            int engineOccurrence = GetInt(engine, "index", 0);
            int queueOccurrence = GetInt(queue, "current_index", 0);
            int occurrence = ResolveSurfaceOccurrence(currentOccurrence, engineOccurrence, queueOccurrence, phase);
            int position = GetInt(current, "position", 0);
            if (IsTransitionPhase(phase))
                position = GetInt(queue, "current_order_slot", position);
            int playlistCount = GetInt(current, "playlist_count", GetInt(queue, "count", 0));
            double duration = currentOccurrence == occurrence ? GetDouble(current, "duration", 0) : 0;
            string repeat = GetString(current, "repeat_mode", _repeatMode).ToLowerInvariant();
            if (repeat == "off" || repeat == "all" || repeat == "one")
            {
                if (!String.IsNullOrWhiteSpace(_pendingRepeatIntent))
                {
                    if (String.Equals(repeat, _pendingRepeatIntent, StringComparison.OrdinalIgnoreCase))
                    {
                        _repeatMode = repeat;
                        _pendingRepeatIntent = "";
                        _pendingRepeatIntentUntilMs = 0;
                    }
                    else if (_clock.ElapsedMilliseconds > _pendingRepeatIntentUntilMs)
                    {
                        _repeatMode = repeat;
                        _pendingRepeatIntent = "";
                        _pendingRepeatIntentUntilMs = 0;
                    }
                }
                else _repeatMode = repeat;
            }

            bool surfaceOccurrenceChanged = false;
            if (occurrence > 0)
            {
                int outgoingOccurrence = _currentOccurrence;
                surfaceOccurrenceChanged = outgoingOccurrence > 0 && outgoingOccurrence != occurrence;
                if (surfaceOccurrenceChanged)
                {
                    RetireOutgoingTimedVisualsAtAudioOccurrenceSwitch(outgoingOccurrence, occurrence);
                    BeginPlaybackTransitionProjection();
                }
                _currentOccurrence = occurrence;
                if (position > 0)
                    _currentSlot = position;
                if (duration <= 0 && _trackMeta.ContainsKey(occurrence)) duration = _trackMeta[occurrence].Duration;
                _duration = Math.Max(0, duration);
            }

            string title = currentOccurrence == occurrence ? GetString(current, "title", "") : "";
            string channel = currentOccurrence == occurrence ? GetString(current, "channel", "") : "";
            if (_currentOccurrence > 0 && _trackMeta.ContainsKey(_currentOccurrence) &&
                (title.Length == 0 || currentOccurrence != _currentOccurrence))
            {
                title = _trackMeta[_currentOccurrence].Title;
                channel = _trackMeta[_currentOccurrence].Channel;
            }

            bool supervisorStarting = !_running && (_engineLaunchMonitorActive || CachedSupervisorLive());
            if (_running && _currentOccurrence > 0)
            {
                if (IsPlaceholderTrackTitle(title, _currentOccurrence)) QueueMetadataPrefetch(_currentOccurrence, true);
                _titleText.Text = title.Length > 0 ? title : "Track " + _currentOccurrence;
                _channelText.Text = channel;
                RefreshNowPlayingSelectableText();
                // R61.37: queue position belongs in the queue. NOW PLAYING does not need a second
                // identity counter beside the title, especially in the compact/player-first surfaces.
                _trackNumberText.Text = "";
                _occurrenceText.Text = "Item " + _currentOccurrence.ToString(CultureInfo.InvariantCulture);
            }
            else if (supervisorStarting)
            {
                // Routine startup stays visually calm. Media/title surfaces simply populate as
                // authoritative state arrives; only actionable failures earn prose.
                _titleText.Text = "";
                _channelText.Text = "";
                _trackNumberText.Text = "";
                _occurrenceText.Text = "";
                _duration = 0;
                _timePosition = 0;
            }
            else
            {
                // Idle is visually silent. The transport itself is the invitation to play;
                // routine readiness prose only creates startup chatter and can flash during refresh.
                _titleText.Text = "";
                _channelText.Text = "";
                _trackNumberText.Text = "";
                _occurrenceText.Text = "";
                _duration = 0;
                _timePosition = 0;
            }

            if (_running && !_seeking)
            {
                // Never project the outgoing file's sampled clock onto an incoming occurrence.
                // During preparing/starting/advancing (or the first refresh after identity changes),
                // the only truthful position is zero until mpv publishes a fresh snapshot.
                if (IsTransitionPhase(phase) || surfaceOccurrenceChanged)
                {
                    _timePosition = 0;
                }
                else
                {
                    double pos = haveMpvSnapshot ? mpvPosition : -1;
                    if (pos >= 0) _timePosition = pos;
                }
            }
            if (!_seeking)
                UpdateTimeUi(_timePosition);
            UpdateFramePreviewClocks();

            ObserveListeningMemory(current);
            UpdateCurrentFavoritePill();
            UpdateCurrentMemoryPill();
            UpdateRuntimeStateUi(phase, engine, queue, config, current);
            UpdatePreviewPauseState();
            SyncVisualizerDemand();
            SyncMediaDemand();
            RefreshMediaIfNeeded(current);
        }

        private static bool IsTransitionPhase(string phase)
        {
            string value = (phase ?? "").ToLowerInvariant();
            return value == "preparing" || value == "starting" || value == "advancing";
        }

        private static int ResolveSurfaceOccurrence(int currentOccurrence, int engineOccurrence, int queueOccurrence, string phase)
        {
            if (IsTransitionPhase(phase))
            {
                if (engineOccurrence > 0) return engineOccurrence;
                if (queueOccurrence > 0) return queueOccurrence;
            }
            if (currentOccurrence > 0) return currentOccurrence;
            if (queueOccurrence > 0) return queueOccurrence;
            return engineOccurrence > 0 ? engineOccurrence : 0;
        }

        private static string FriendlyRuntimeStatus(string phase)
        {
            // R61.94 calm surface: technical preparation belongs in diagnostics, not the player.
            // Durable user states are already projected by the state pill, so ordinary prose stays blank.
            switch ((phase ?? "").ToLowerInvariant())
            {
                case "error": return "Open Operations Center for details.";
                case "complete": return "End of queue.";
                default: return "";
            }
        }

        private static int VideoQualityRank(string quality)
        {
            if (String.IsNullOrWhiteSpace(quality)) return 0;
            if (quality.IndexOf("Best", StringComparison.OrdinalIgnoreCase) >= 0) return 10000;
            System.Text.RegularExpressions.Match match = System.Text.RegularExpressions.Regex.Match(quality, @"(\d+)\s*p", System.Text.RegularExpressions.RegexOptions.IgnoreCase);
            int height;
            return match.Success && Int32.TryParse(match.Groups[1].Value, NumberStyles.Integer, CultureInfo.InvariantCulture, out height) ? height : 0;
        }

        private static string NormalizeUnifiedVideoQuality(string raw)
        {
            string value = (raw ?? "").Trim();
            if (value.Length == 0) return "240p";
            if (value.StartsWith("144p", StringComparison.OrdinalIgnoreCase)) return "144p";
            if (value.StartsWith("Best", StringComparison.OrdinalIgnoreCase)) return "Best";
            if (value.StartsWith("Off", StringComparison.OrdinalIgnoreCase)) return "Off (audio only)";
            foreach (string known in new[] { "240p", "360p", "480p", "720p" })
                if (value.StartsWith(known, StringComparison.OrdinalIgnoreCase)) return known;
            return value;
        }

        private static string UnifiedVideoQualityFromConfig(Dictionary<string, object> config)
        {
            string unified = GetString(config, "video_quality", "");
            if (!String.IsNullOrWhiteSpace(unified)) return NormalizeUnifiedVideoQuality(unified);
            string player = GetString(config, "player_video_quality", "Off (audio only)");
            string overlay = GetString(config, "overlay_video_quality", "240p");
            // Legacy configs used two knobs. On migration, preserve the higher prepared quality
            // so unifying the setting can never silently downgrade an existing OBS/controller path.
            if (player.StartsWith("Off", StringComparison.OrdinalIgnoreCase)) return NormalizeUnifiedVideoQuality(overlay);
            return NormalizeUnifiedVideoQuality(VideoQualityRank(player) >= VideoQualityRank(overlay) ? player : overlay);
        }

        private static string EffectiveControllerVideoQuality(Dictionary<string, object> config)
        {
            if (!GetBool(config, "video_enabled", true)) return "";
            string unified = UnifiedVideoQualityFromConfig(config);
            return unified.StartsWith("Off", StringComparison.OrdinalIgnoreCase) ? "" : unified;
        }

        private string BuildStateProtocolSignal(Dictionary<string, object> current, Dictionary<string, object> queue, bool detailed)
        {
            var cp = GetMap(current, "state_protocol");
            var qp = GetMap(queue, "state_protocol");
            var head = ReadJsonCached(Path.Combine(_stateRoot, "state-coherence.json"));
            var runtime = ReadJsonCached(Path.Combine(_stateRoot, "runtime-instance.json"));
            string cr = GetString(cp, "runtime_id", "");
            string qr = GetString(qp, "runtime_id", "");
            string hr = GetString(head, "runtime_id", "");
            string rr = GetString(runtime, "runtime_id", "");
            string csid = GetString(cp, "session_id", "");
            string qsid = GetString(qp, "session_id", "");
            long cseq = GetInt(cp, "sequence", -1);
            long qseq = GetInt(qp, "sequence", -1);
            long hseq = GetInt(head, "sequence", -1);
            int cep = GetInt(cp, "presentation_epoch", -1);
            int qep = GetInt(qp, "presentation_epoch", -1);
            bool missing = cseq < 0 || qseq < 0 || String.IsNullOrWhiteSpace(cr) || String.IsNullOrWhiteSpace(qr);
            bool identityConflict =
                (!String.IsNullOrWhiteSpace(cr) && !String.IsNullOrWhiteSpace(qr) && !String.Equals(cr, qr, StringComparison.Ordinal)) ||
                (!String.IsNullOrWhiteSpace(rr) && !String.IsNullOrWhiteSpace(cr) && !String.Equals(rr, cr, StringComparison.Ordinal)) ||
                (!String.IsNullOrWhiteSpace(hr) && !String.IsNullOrWhiteSpace(cr) && !String.Equals(hr, cr, StringComparison.Ordinal)) ||
                (!String.IsNullOrWhiteSpace(csid) && !String.IsNullOrWhiteSpace(qsid) && !String.Equals(csid, qsid, StringComparison.Ordinal));
            bool causalConflict = false;
            if (!missing)
            {
                if (qseq > cseq && qep >= 0 && cep >= 0 && qep < cep) causalConflict = true;
                if (cseq > qseq && qep >= 0 && cep >= 0 && cep < qep) causalConflict = true;
            }
            if (identityConflict || causalConflict)
                return detailed ? "STATE CONFLICT | identity/causality violation" : "STATE CONFLICT";
            if (missing)
                return detailed ? "State is still synchronizing." : "State synchronizing";
            long max = Math.Max(cseq, qseq);
            long min = Math.Min(cseq, qseq);
            long lag = max - min;
            bool headSync = hseq >= 0 && hseq != max;
            if (headSync)
            {
                string detail = "STATE SYNC H" + hseq.ToString(CultureInfo.InvariantCulture) + "->S" + max.ToString(CultureInfo.InvariantCulture);
                return detailed ? detail + " | commit-head/read race" : detail;
            }
            string ok = "STATE COHERENT S" + max.ToString(CultureInfo.InvariantCulture);
            if (detailed) ok += " | E" + Math.Max(cep, qep).ToString(CultureInfo.InvariantCulture) + " | Delta" + lag.ToString(CultureInfo.InvariantCulture);
            return ok;
        }

        private string BuildRecoveryReplaySignal(bool detailed)
        {
            var plan = ReadJsonCached(Path.Combine(_stateRoot, "recovery-plan.json"));
            if (plan == null) return detailed ? "RECOVERY - no startup plan yet" : "REC -";
            string state = GetString(plan, "state", "UNKNOWN").ToUpperInvariant();
            string action = GetString(plan, "action", "").ToUpperInvariant();
            int occurrence = GetInt(plan, "resume_occurrence", 0);
            int orderRevision = GetInt(plan, "order_revision", -1);
            string reason = GetString(plan, "reason", "");
            string badge;
            if (state == "CLEAN") badge = "Recovery: clean";
            else if (state == "RESUMED") badge = "Recovery: resumed";
            else if (state == "FALLBACK") badge = "Recovery: fallback used";
            else if (state == "OBSERVE") badge = "Recovery: checking";
            else if (state == "BLOCKED" || state == "CONFLICT") badge = "Recovery: needs attention";
            else badge = "Recovery: " + state.ToLowerInvariant();
            if (occurrence > 0) badge += " O" + occurrence.ToString(CultureInfo.InvariantCulture);
            if (orderRevision >= 0) badge += " R" + orderRevision.ToString(CultureInfo.InvariantCulture);
            if (detailed)
            {
                if (!String.IsNullOrWhiteSpace(action)) badge += " | " + action;
                if (!String.IsNullOrWhiteSpace(reason)) badge += " | " + reason;
            }
            return badge;
        }

        private string BuildUpdateDeploymentSignal(bool detailed)
        {
            var tx = ReadJsonCached(Path.Combine(_stateRoot, "update-transaction.json"));
            if (tx == null) return detailed ? "UPDATE - no deployment transaction recorded" : "UPD -";
            string state = GetString(tx, "state", "UNKNOWN").ToUpperInvariant();
            string from = GetString(tx, "from_version", "");
            string to = GetString(tx, "to_version", "");
            int verified = GetInt(tx, "verified_files", 0);
            string reason = GetString(tx, "reason", "");
            string badge = "UPD " + state;
            if (!String.IsNullOrWhiteSpace(to)) badge += " " + to;
            if (verified > 0) badge += " F" + verified.ToString(CultureInfo.InvariantCulture);
            if (detailed)
            {
                if (!String.IsNullOrWhiteSpace(from) || !String.IsNullOrWhiteSpace(to)) badge += " | " + from + "->" + to;
                if (!String.IsNullOrWhiteSpace(reason)) badge += " | " + reason;
            }
            return badge;
        }

