        private void UpdateRuntimeStateUi(
            string phase,
            Dictionary<string, object> engine,
            Dictionary<string, object> queue,
            Dictionary<string, object> config,
            Dictionary<string, object> current)
        {
            Brush accent = Brush("Accent");
            Brush warning = Brush("Warning");
            Brush danger = Brush("Danger");
            Brush info = Brush("Info");
            Brush muted = Brush("TextMuted");

            bool supervisorStarting = !_running && (_engineLaunchMonitorActive || CachedSupervisorLive());
            bool silentWarmSurface = _startupPrewarmReady || _startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm);

            if (_startupPrewarmInFlight || (_engineLaunchMonitorActive && _engineLaunchPrewarm) || supervisorStarting)
            {
                // Do not narrate routine startup. The state pill is intentionally blank until
                // playback becomes authoritative; genuine errors still project below.
                _headerStateText.Text = "";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = Brushes.Transparent;
                _headerStatePill.Background = Brushes.Transparent;
                _headerStatePill.BorderBrush = Brushes.Transparent;
                _headerStatePill.ToolTip = null;
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
                _playGlyph.Visibility = Visibility.Visible;
                _pauseGlyph.Visibility = Visibility.Collapsed;
            }
            else if (!_running)
            {
                _headerStateText.Text = "Stopped";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "Playback is stopped. Press Play or Space to start YOMI.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brush("SurfaceRaised");
                _runtimePill.BorderBrush = Brush("Border");
                _systemStatusText.Text = "";
                _playGlyph.Visibility = Visibility.Visible;
                _pauseGlyph.Visibility = Visibility.Collapsed;
            }
            else if (phase == "paused" && _audioActive)
            {
                _headerStateText.Text = "Paused";
                _headerStateText.Foreground = warning;
                _headerStateDot.Fill = warning;
                _headerStatePill.Background = Brush("WarningSoft");
                _headerStatePill.BorderBrush = warning;
                _headerStatePill.ToolTip = "Playback is paused. Prepared queue and cached media remain available.";
                _runtimeText.Text = "Player ready";
                _runtimeText.Foreground = accent;
                _runtimePill.Background = Brush("AccentSoft");
                _runtimePill.BorderBrush = Brush("AccentBorder");
                _systemStatusText.Text = FriendlyRuntimeStatus("paused");
            }
            else if (phase == "preparing")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "YOMI is ready.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
            }
            else if (phase == "starting")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "YOMI is ready.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
            }
            else if (phase == "advancing")
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "YOMI is ready.";
                _runtimeText.Text = "";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brushes.Transparent;
                _runtimePill.BorderBrush = Brushes.Transparent;
                _systemStatusText.Text = "";
            }
            else if (phase == "complete")
            {
                _headerStateText.Text = "Complete";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "The active queue reached its end. Press Play to replay the current occurrence.";
                _runtimeText.Text = "Player ready";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brush("SurfaceRaised");
                _runtimePill.BorderBrush = Brush("Border");
                _systemStatusText.Text = FriendlyRuntimeStatus("complete");
            }
            else if (phase == "error")
            {
                _headerStateText.Text = "Attention";
                _headerStateText.Foreground = danger;
                _headerStateDot.Fill = danger;
                _headerStatePill.Background = Brush("DangerSoft");
                _headerStatePill.BorderBrush = danger;
                _headerStatePill.ToolTip = "YOMI needs attention. Open Operations Center for details.";
                _runtimeText.Text = "Player error";
                _runtimeText.Foreground = danger;
                _runtimePill.Background = Brush("DangerSoft");
                _runtimePill.BorderBrush = danger;
                _systemStatusText.Text = FriendlyRuntimeStatus("error");
            }
            else if (_audioActive)
            {
                _headerStateText.Text = "Playing";
                _headerStateText.Foreground = accent;
                _headerStateDot.Fill = accent;
                _headerStatePill.Background = Brush("AccentSoft");
                _headerStatePill.BorderBrush = Brush("AccentBorder");
                _headerStatePill.ToolTip = "Playback is active.";
                _runtimeText.Text = "Player live";
                _runtimeText.Foreground = accent;
                _runtimePill.Background = Brush("AccentSoft");
                _runtimePill.BorderBrush = Brush("AccentBorder");
                _systemStatusText.Text = FriendlyRuntimeStatus("playing");
            }
            else
            {
                _headerStateText.Text = "Ready";
                _headerStateText.Foreground = muted;
                _headerStateDot.Fill = muted;
                _headerStatePill.Background = Brush("SurfaceRaised");
                _headerStatePill.BorderBrush = Brush("Border");
                _headerStatePill.ToolTip = "Playback is ready.";
                _runtimeText.Text = "Player ready";
                _runtimeText.Foreground = muted;
                _runtimePill.Background = Brush("SurfaceRaised");
                _runtimePill.BorderBrush = Brush("Border");
                _systemStatusText.Text = FriendlyRuntimeStatus("ready");
            }

            ApplyHeaderSignalVisibility(phase, supervisorStarting);
            ApplyPrimaryTransportGlyph();
            UpdateTransportAvailability(phase, supervisorStarting);
            if (_tray != null)
            {
                try { _tray.Text = "YOMI - " + _headerStateText.Text; } catch { }
            }

            string health = GetString(queue, "buffer_health", "-").ToUpperInvariant();
            int ready = GetInt(queue, "ready_ahead", 0);
            int target = GetInt(queue, "target_ahead", 0);
            _lastReadyAhead = ready;
            _lastTargetAhead = target;
            _lastObservedBufferHealth = health;
            _bufferText.Text = String.Format(CultureInfo.InvariantCulture, "BUFFER {0}  {1}/{2}", health, ready, target);
            _queueBufferText.Text = target > 0
                ? String.Format(CultureInfo.InvariantCulture, "{0}/{1} READY", ready, target)
                : "-";

            if (health == "HEALTHY")
            {
                _bufferPill.Background = Brush("AccentSoft");
                _bufferPill.BorderBrush = Brush("AccentBorder");
                _bufferText.Foreground = accent;
            }
            else if (health == "THIN")
            {
                _bufferPill.Background = Brush("WarningSoft");
                _bufferPill.BorderBrush = warning;
                _bufferText.Foreground = warning;
            }
            else
            {
                _bufferPill.Background = Brush("DangerSoft");
                _bufferPill.BorderBrush = danger;
                _bufferText.Foreground = danger;
            }
            RefreshEverydayStatusVisibility();

            int workers = GetInt(queue, "workers", GetInt(engine, "workers", 0));
            int activeJobs = GetInt(queue, "active_jobs", 0);
            int queuedJobs = GetInt(queue, "queued_jobs", 0);
            _workerText.Text = workers > 0
                ? String.Format(CultureInfo.InvariantCulture, "Preparation: {0} workers · {1} active · {2} waiting", workers, activeJobs, queuedJobs)
                : "Preparation: idle";

            string appMode = GetString(config, "app_mode", "");
            string videoQuality = EffectiveControllerVideoQuality(config);
            string vizFps = GetString(config, "visualizer_fps", "");
            string videoFpsSetting = GetString(config, "video_fps", "Source FPS");
            _visualizerFramePreviewFps = vizFps.StartsWith("60", StringComparison.OrdinalIgnoreCase) ? 60 : 30;
            _visualizerShape = GetString(config, "visualizer_shape", "Spectrum");
            double localVizOpacity = Math.Max(0.05, Math.Min(1.0, GetDouble(config, "visualizer_opacity", 0.3)));
            if (_visualizerFrameHost != null) _visualizerFrameHost.Opacity = localVizOpacity;
            if (_visualizerHost != null) _visualizerHost.Opacity = localVizOpacity;
            string vizFill = GetString(config, "visualizer_adaptive_fill", "Adaptive");
            int vizTrim = GetInt(config, "visualizer_high_frequency_trim", 0);
            int vizLift = GetInt(config, "visualizer_high_frequency_lift_db", 4);
            int vizWidth = NormalizeVisualizerAnalysisWidth(GetInt(config, "visualizer_internal_width", 180));
            int vizHeight = NormalizeVisualizerAnalysisHeight(GetInt(config, "visualizer_internal_height", 36));
            // Analysis resolution is the actual cached pixel raster. Manual length controls
            // presentation width separately; it must not silently multiply decode bandwidth.
            int vizRenderWidth = Math.Max(64, Math.Min(512, vizWidth));
            int vizRenderHeight = Math.Max(16, Math.Min(128, vizHeight));
            if ((vizRenderWidth & 1) != 0) vizRenderWidth++;
            if ((vizRenderHeight & 1) != 0) vizRenderHeight++;
            _visualizerRawFrameWidth = vizRenderWidth;
            _visualizerRawFrameHeight = vizRenderHeight;
            string profileLabel = _performanceWorkspace ? "PERFORMANCE | LOCAL PREVIEWS OFF" : _workspaceProfile.ToString().ToUpperInvariant();
            _modeText.Text = appMode.Length > 0 ? profileLabel + "  |  " + appMode.ToUpperInvariant() : profileLabel;
            string vizView = _visualizerPreviewActualFps > 1.0 ? " | VIEW " + _visualizerPreviewActualFps.ToString("0.0", CultureInfo.InvariantCulture) + " FPS" : "";
            _visualizerMetaText.Text = String.Format(CultureInfo.InvariantCulture, "{0}x{1} | {2} | {3} | TRIM {4}% | HF +{5}dB{6}",
                vizWidth, vizHeight, String.IsNullOrWhiteSpace(vizFps) ? "30 FPS" : vizFps.ToUpperInvariant(),
                vizFill.ToUpperInvariant(), vizTrim, vizLift, vizView);

            var videoResult = GetMap(current, "video_result");
            int videoHeight = GetInt(videoResult, "actual_height", 0);
            int videoFps = GetInt(videoResult, "fps", 0);
            if (videoFpsSetting.StartsWith("60", StringComparison.OrdinalIgnoreCase)) _videoFramePreviewFps = 60;
            else if (videoFpsSetting.StartsWith("30", StringComparison.OrdinalIgnoreCase)) _videoFramePreviewFps = 30;
            else _videoFramePreviewFps = videoFps > 0 ? Math.Max(1, Math.Min(120, videoFps)) : 30;
            if (videoHeight > 0)
            {
                bool videoFallback = GetBool(videoResult, "fallback", false);
                int videoRoute = GetInt(videoResult, "route", 0);
                _qualityText.Text = String.Format(
                    CultureInfo.InvariantCulture,
                    "VIDEO {0}P{1}{2}{3}",
                    videoHeight,
                    videoFps > 0 ? " | " + videoFps + " FPS" : "",
                    videoFallback ? " | FALLBACK" : "",
                    ""
                );
            }
            else if (videoQuality.Length > 0)
                _qualityText.Text = videoQuality.ToUpperInvariant();
            else
                _qualityText.Text = "Cache";

            var technical = new List<string>();
            if (_sessionId.Length > 0)
                technical.Add("SESSION " + _sessionId.Substring(0, Math.Min(8, _sessionId.Length)).ToUpperInvariant());
            if (_orderRevision >= 0)
                technical.Add("ORDER R" + _orderRevision.ToString(CultureInfo.InvariantCulture));
            var rehearsalSummary = GetMap(queue, "rehearsal");
            if (GetBool(rehearsalSummary, "active", false))
                technical.Add("REHEARSE " + GetInt(rehearsalSummary, "sync_ready", 0).ToString(CultureInfo.InvariantCulture) + "/" + GetInt(rehearsalSummary, "target", 0).ToString(CultureInfo.InvariantCulture));
            var freezeSummary = GetMap(queue, "freeze");
            if (GetBool(freezeSummary, "active", false))
                technical.Add("FREEZE " + GetInt(freezeSummary, "count", 0).ToString(CultureInfo.InvariantCulture));
            string failureDomain = GetString(queue, "failure_domain", "");
            if (!String.IsNullOrWhiteSpace(failureDomain) && !String.Equals(failureDomain, "OK", StringComparison.OrdinalIgnoreCase))
                technical.Add("DOMAIN " + failureDomain.ToUpperInvariant());
            var serviceLevel = GetMap(queue, "service_level");
            string continuityPolicy = GetString(serviceLevel, "continuity_policy", "");
            if (!String.IsNullOrWhiteSpace(continuityPolicy))
                technical.Add("CONTINUITY " + continuityPolicy.ToUpperInvariant());
            var routeIntelligence = GetMap(queue, "route_intelligence");
            int routeEntries = GetInt(routeIntelligence, "entries", -1);
            if (routeEntries >= 0)
                technical.Add("ROUTES " + routeEntries.ToString(CultureInfo.InvariantCulture));
            var predictive = GetMap(queue, "predictive");
            string predictiveState = GetString(predictive, "state", "").ToUpperInvariant();
            int predictiveConfidence = GetInt(predictive, "confidence", -1);
            int predictiveSamples = GetInt(predictive, "samples", -1);
            if (!String.IsNullOrWhiteSpace(predictiveState))
            {
                string badge = "PRED " + predictiveState;
                if (predictiveConfidence >= 0) badge += " " + predictiveConfidence.ToString(CultureInfo.InvariantCulture) + "%";
                if (predictiveSamples >= 0) badge += " N" + predictiveSamples.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            var admission = GetMap(queue, "admission");
            string admissionPolicy = GetString(admission, "policy", "").ToUpperInvariant();
            int admissionDeferred = GetInt(admission, "deferred", -1);
            int admissionBudget = GetInt(admission, "budget_percent", -1);
            if (!String.IsNullOrWhiteSpace(admissionPolicy))
            {
                string badge = "ADMIT " + admissionPolicy;
                if (admissionBudget >= 0) badge += " " + admissionBudget.ToString(CultureInfo.InvariantCulture) + "%";
                if (admissionDeferred > 0) badge += " D" + admissionDeferred.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            var coherence = GetMap(queue, "coherence");
            string coherencePolicy = GetString(coherence, "policy", "").ToUpperInvariant();
            int coherenceQuarantine = GetInt(coherence, "quarantined", 0);
            int coherenceMismatch = GetInt(coherence, "mismatches", 0);
            int coherenceAdopted = GetInt(coherence, "adopted", 0);
            if (!String.IsNullOrWhiteSpace(coherencePolicy))
            {
                string badge = "CACHE " + (coherenceQuarantine == 0 && coherenceMismatch == 0 ? "COHERENT" : coherencePolicy);
                if (coherenceQuarantine > 0) badge += " Q" + coherenceQuarantine.ToString(CultureInfo.InvariantCulture);
                if (coherenceMismatch > 0) badge += " M" + coherenceMismatch.ToString(CultureInfo.InvariantCulture);
                if (coherenceAdopted > 0) badge += " A" + coherenceAdopted.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            var performance = GetMap(queue, "performance");
            string performanceMode = GetString(performance, "mode", "").ToUpperInvariant();
            string performanceCritical = GetString(performance, "critical_stage", "").ToUpperInvariant();
            double performanceP95 = GetDouble(performance, "critical_p95_seconds", -1);
            int performanceAnomalies = GetInt(performance, "anomalies", 0);
            int performanceSamples = GetInt(performance, "samples", 0);
            if (!String.IsNullOrWhiteSpace(performanceMode))
            {
                string badge = "PERF " + (String.IsNullOrWhiteSpace(performanceCritical) ? performanceMode : performanceCritical);
                if (performanceP95 >= 0) badge += " P95 " + CompactSeconds(performanceP95);
                if (performanceAnomalies > 0) badge += " A" + performanceAnomalies.ToString(CultureInfo.InvariantCulture);
                if (performanceSamples > 0) badge += " N" + performanceSamples.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            var slo = GetMap(queue, "slo");
            string sloState = GetString(slo, "state", "").ToUpperInvariant();
            int sloBaselineSessions = GetInt(slo, "baseline_sessions", 0);
            int sloBreaches = GetInt(slo, "breaches", 0);
            int sloRegressions = GetInt(slo, "regressions", 0);
            if (!String.IsNullOrWhiteSpace(sloState))
            {
                string badge = "SLO " + sloState;
                if (sloBaselineSessions > 0) badge += " B" + sloBaselineSessions.ToString(CultureInfo.InvariantCulture);
                if (sloRegressions > 0) badge += " R" + sloRegressions.ToString(CultureInfo.InvariantCulture);
                if (sloBreaches > 0) badge += " !" + sloBreaches.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            technical.Add(BuildStateProtocolSignal(current, queue, false));
            technical.Add(BuildRecoveryReplaySignal(false));
            technical.Add(BuildUpdateDeploymentSignal(false));
            var configConflict = ReadJsonCached(Path.Combine(_stateRoot, "config-pending-conflict.json"));
            var configPending = ReadJsonCached(Path.Combine(_stateRoot, "config-pending.json"));
            if (configConflict != null)
            {
                technical.Add("CFG CONFLICT");
            }
            else if (configPending != null)
            {
                var configPlan = GetMap(configPending, "plan");
                string risk = GetString(configPlan, "risk", "").ToUpperInvariant();
                int changed = GetInt(configPlan, "changed_count", 0);
                bool restart = GetBool(configPlan, "requires_restart", false);
                string badge = "CFG STAGED";
                if (changed > 0) badge += " Delta" + changed.ToString(CultureInfo.InvariantCulture);
                if (!String.IsNullOrWhiteSpace(risk)) badge += " " + risk;
                if (restart) badge += " RESTART";
                technical.Add(badge);
            }
            var faultSummary = GetMap(queue, "faults");
            string faultPolicy = GetString(faultSummary, "policy", "").ToUpperInvariant();
            int faultOpen = GetInt(faultSummary, "open", 0);
            int faultProbation = GetInt(faultSummary, "probation", 0);
            int faultSuppressed = GetInt(faultSummary, "suppressed", 0);
            if (!String.IsNullOrWhiteSpace(faultPolicy))
            {
                string badge = "FAULT " + (faultOpen == 0 && faultProbation == 0 ? "OK" : faultPolicy);
                if (faultOpen > 0) badge += " O" + faultOpen.ToString(CultureInfo.InvariantCulture);
                if (faultProbation > 0) badge += " P" + faultProbation.ToString(CultureInfo.InvariantCulture);
                if (faultSuppressed > 0) badge += " S" + faultSuppressed.ToString(CultureInfo.InvariantCulture);
                technical.Add(badge);
            }
            if (GetBool(config, "visualizer_enabled", true))
            {
                string fillBadge = GetString(config, "visualizer_adaptive_fill", "Adaptive").ToUpperInvariant();
                int liftBadge = GetInt(config, "visualizer_high_frequency_lift_db", 4);
                technical.Add("VIZ " + fillBadge + " +" + liftBadge.ToString(CultureInfo.InvariantCulture) + "DB");
            }
            if (String.Equals(appMode, "Streamer / OBS", StringComparison.OrdinalIgnoreCase))
            {
                bool autoFit = GetBool(config, "overlay_auto_fit_text", true);
                int composeGap = GetInt(config, "overlay_text_gap_px", 14);
                int safeMargin = GetInt(config, "overlay_safe_margin_px", 8);
                technical.Add("COMPOSE " + (autoFit ? "FIT" : "FIXED") + " G" + composeGap.ToString(CultureInfo.InvariantCulture) + " S" + safeMargin.ToString(CultureInfo.InvariantCulture));

                int handoffEpoch = GetInt(current, "presentation_epoch", 0);
                int handoffLoadMs = GetInt(current, "handoff_audio_load_ms", 0);
                int visualJoinMs = GetInt(config, "overlay_visual_join_ms", 90);
                if (handoffEpoch > 0)
                    technical.Add("HANDOFF E" + handoffEpoch.ToString(CultureInfo.InvariantCulture) + " " + handoffLoadMs.ToString(CultureInfo.InvariantCulture) + "MS J" + visualJoinMs.ToString(CultureInfo.InvariantCulture) + "MS");
            }
            _technicalText.Text = String.Join("   |   ", technical.ToArray());
            UpdateNextUpUi();
            UpdatePlaybackSummary();

            int observedOccurrence = _currentOccurrence;
            string observedTitle = GetString(current, "title", "");
            if (String.IsNullOrWhiteSpace(observedTitle) && observedOccurrence > 0 && _trackMeta.ContainsKey(observedOccurrence))
                observedTitle = _trackMeta[observedOccurrence].Title;
            if (_lastObservedOccurrence != observedOccurrence && observedOccurrence > 0)
            {
                _lastObservedOccurrence = observedOccurrence;
                AddActivity("Track", String.IsNullOrWhiteSpace(observedTitle) ? "Occurrence " + observedOccurrence.ToString(CultureInfo.InvariantCulture) : observedTitle);
            }
            if (!String.Equals(_lastObservedPhase, phase, StringComparison.OrdinalIgnoreCase))
            {
                _lastObservedPhase = phase;
                AddActivity("Playback", phase.ToUpperInvariant());
            }
            if (!String.Equals(_lastObservedBufferHealth, health, StringComparison.OrdinalIgnoreCase))
            {
                _lastObservedBufferHealth = health;
                AddActivity("Buffer", health);
            }
            UpdateRuntimeSurfaceVisibility(phase);
            UpdateOperatorIntelligence(queue, engine);
            RefreshInspector(current, engine, queue, config);
        }

        private string ContextOccurrenceLabel(int occurrence)
        {
            if (occurrence <= 0) return "-";
            TrackMeta meta;
            if (_trackMeta.TryGetValue(occurrence, out meta) && !String.IsNullOrWhiteSpace(meta.Title))
                return meta.Title;
            return "Occurrence " + occurrence.ToString(CultureInfo.InvariantCulture);
        }

        private void UpdateTrackContextTooltips()
        {
            // Snapshot mutable queue authority once. Incremental queue projection can replace
            // _order/_currentSlot between Count and index operations; tooltips must never race it.
            int[] order = _order == null ? new int[0] : _order.ToArray();
            int currentSlot = _currentSlot;
            if (_previousUpStrip != null)
            {
                var lines = new List<string> { "Click card: play previous now", "PLAY NEXT: make this the very next track | FIND: locate it" };
                int count = 0;
                int previousStart = Math.Min(order.Length - 1, currentSlot - 2);
                for (int slot = previousStart; slot >= 0 && slot < order.Length && count < 3; slot--, count++)
                    lines.Add((count + 1).ToString(CultureInfo.InvariantCulture) + ". " + ContextOccurrenceLabel(order[slot]));
                if (count == 0) lines.Add("Start of active queue");
                _previousUpStrip.ToolTip = String.Join(Environment.NewLine, lines.ToArray());
            }
            if (_nextUpStrip != null)
            {
                var lines = new List<string> { "Click card: play next now", "MOVE LATER: move it five positions deeper in the queue | FIND: locate it", "Up next" };
                int count = 0;
                int nextStart = Math.Min(order.Length, Math.Max(0, currentSlot));
                for (int slot = nextStart; slot >= 0 && slot < order.Length && count < 3; slot++, count++)
                    lines.Add((count + 1).ToString(CultureInfo.InvariantCulture) + ". " + ContextOccurrenceLabel(order[slot]));
                if (count == 0) lines.Add("End of active queue");
                _nextUpStrip.ToolTip = String.Join(Environment.NewLine, lines.ToArray());
            }
        }

        private void SetContextState(TextBlock target, string text, Brush brush, bool visible)
        {
            if (target == null) return;
            target.Text = text ?? "";
            target.Foreground = brush ?? Brush("TextMuted");
            target.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
        }

        private void ApplyHeaderSignalVisibility(string phase, bool supervisorStarting)
        {
            if (_headerStatePill == null) return;
            string state = (phase ?? "").Trim().ToLowerInvariant();
            // Routine startup/transition state stays silent. The title bar is reserved for
            // actionable failure; media/title surfaces populate as authoritative state arrives.
            bool signal = state == "error";
            _headerStatePill.Visibility = signal ? Visibility.Visible : Visibility.Collapsed;
        }

        private void UpdateNextUpUi()
        {
            UpdateRepeatPill();
            UpdateTrackContextTooltips();
            if (_nextUpStrip == null || _nextUpTitleText == null || _nextUpStateText == null) return;
            if (_previousUpTitleText != null && _previousUpStateText != null)
            {
                int previousOccurrence = (_currentSlot > 1 && _currentSlot - 2 < _order.Count) ? _order[_currentSlot - 2] : 0;
                TrackMeta previousMeta;
                _previousUpTitleText.Text = previousOccurrence > 0 && _trackMeta.TryGetValue(previousOccurrence, out previousMeta) && !String.IsNullOrWhiteSpace(previousMeta.Title)
                    ? previousMeta.Title : previousOccurrence > 0 ? "Occurrence " + previousOccurrence.ToString(CultureInfo.InvariantCulture) : "No previous track";
                bool previousRequesting = _contextOrderCommandPending && String.Equals(_contextOrderCommandKind, "play-next", StringComparison.OrdinalIgnoreCase);
                bool previousCommitting = _pendingOrderMutationRevision >= 0 && String.Equals(_pendingOrderMutationKind, "context-play-next", StringComparison.OrdinalIgnoreCase);
                SetContextState(_previousUpStateText, previousRequesting ? "REQUESTING" : "COMMITTING", Brush("Warning"), previousRequesting || previousCommitting);
            }
            if (!_running)
            {
                _nextUpTitleText.Text = "Playback stopped";
                if (_miniNextText != null) _miniNextText.Text = "Playback stopped";
                SetContextState(_nextUpStateText, "", Brush("TextMuted"), false);
                return;
            }
            int nextOccurrence = (_currentSlot > 0 && _currentSlot < _order.Count) ? _order[_currentSlot] : 0;
            if (_repeatMode == "one") nextOccurrence = _currentOccurrence;
            else if (nextOccurrence <= 0 && _repeatMode == "all" && _order.Count > 0) nextOccurrence = _order[0];
            if (nextOccurrence <= 0)
            {
                _nextUpTitleText.Text = "End of active queue";
                if (_miniNextText != null) _miniNextText.Text = "End of active queue";
                SetContextState(_nextUpStateText, "", Brush("TextMuted"), false);
                return;
            }
            TrackMeta meta;
            _nextUpTitleText.Text = _trackMeta.TryGetValue(nextOccurrence, out meta) && !String.IsNullOrWhiteSpace(meta.Title)
                ? meta.Title : "Occurrence " + nextOccurrence.ToString(CultureInfo.InvariantCulture);
            if (_miniNextText != null) _miniNextText.Text = _nextUpTitleText.Text;
            bool nextRequesting = _contextOrderCommandPending && String.Equals(_contextOrderCommandKind, "move-later", StringComparison.OrdinalIgnoreCase);
            bool nextCommitting = _pendingOrderMutationRevision >= 0 && String.Equals(_pendingOrderMutationKind, "context-move-later", StringComparison.OrdinalIgnoreCase);
            if (nextRequesting || nextCommitting)
            {
                SetContextState(_nextUpStateText, nextRequesting ? "REQUESTING" : "COMMITTING", Brush("Warning"), true);
                return;
            }
            RuntimeQueueItem runtime;
            if (!_runtimeQueue.TryGetValue(nextOccurrence, out runtime))
            {
                SetContextState(_nextUpStateText, "", Brush("TextMuted"), false);
                return;
            }
            // R61.39: readiness percentages and healthy queue phases are diagnostics, not player chrome.
            // Surface the NEXT state only when it may affect continuity.
            bool urgent = String.Equals(runtime.Risk, "URGENT", StringComparison.OrdinalIgnoreCase) ||
                          String.Equals(runtime.Risk, "AT_RISK", StringComparison.OrdinalIgnoreCase);
            if (urgent)
            {
                string state = String.Equals(runtime.Risk, "AT_RISK", StringComparison.OrdinalIgnoreCase) ? "AT RISK" : "URGENT";
                if (runtime.EtaSeconds >= 0 && runtime.EtaSeconds < 86400) state += " | " + FormatTime(runtime.EtaSeconds);
                SetContextState(_nextUpStateText, state, Brush("Danger"), true);
            }
            else if (!runtime.TransitionReady && !runtime.SyncReady && runtime.HasActiveWork)
            {
                string state = "GETTING READY";
                if (runtime.EtaSeconds >= 0 && runtime.EtaSeconds < 86400) state += " | " + FormatTime(runtime.EtaSeconds);
                SetContextState(_nextUpStateText, state, Brush("Warning"), true);
            }
            else
            {
                SetContextState(_nextUpStateText, "", Brush("TextMuted"), false);
            }
        }

        private void SelectNextOccurrenceInQueue()
        {
            if (_currentSlot <= 0 || _currentSlot >= _order.Count) return;
            SelectQueueOccurrenceWhenReady(_order[_currentSlot], false);
        }

        private void SelectPreviousOccurrenceInQueue()
        {
            if (_currentSlot <= 1 || _currentSlot - 2 >= _order.Count) return;
            SelectQueueOccurrenceWhenReady(_order[_currentSlot - 2], false);
        }

        private int ContextOccurrence(int relative)
        {
            if (_currentSlot <= 0 || _order.Count == 0) return 0;
            int index = relative < 0 ? _currentSlot - 2 : _currentSlot;
            if (index < 0 || index >= _order.Count) return 0;
            return _order[index];
        }

        private void LocatePreviousInQueue()
        {
            SetQueueOpen(true, true);
            SetQueueScope(QueueScope.All);
            SelectPreviousOccurrenceInQueue();
        }

        private void LocateNextInQueue()
        {
            SetQueueOpen(true, true);
            SetQueueScope(QueueScope.Upcoming);
            SelectNextOccurrenceInQueue();
        }

        private void SetContextOrderCommandPending(bool pending, string kind)
        {
            _contextOrderCommandPending = pending;
            _contextOrderCommandKind = pending ? (kind ?? "") : "";
            UpdateOrderMutationControls();
            UpdateNextUpUi();
        }

        private void QueuePreviousAgain()
        {
            if (!_running || OrderMutationBusy)
            {
                if (OrderMutationBusy) ShowToast("Queue updating", "Wait for the current order change to finish committing.");
                return;
            }
            int occurrence = ContextOccurrence(-1);
            if (occurrence <= 0 || occurrence == _currentOccurrence) return;
            string label = ContextOccurrenceLabel(occurrence);
            SetContextOrderCommandPending(true, "play-next");
            if (!TryBeginOrderMutationRequest("context-play-next"))
            {
                SetContextOrderCommandPending(false, "");
                return;
            }
            DispatchTransportCommand(new object[] { "script-message", "yomi-order-play-next", occurrence.ToString(CultureInfo.InvariantCulture) }, delegate(bool accepted)
            {
                if (!accepted)
                {
                    EndOrderMutationRequest();
                    SetContextOrderCommandPending(false, "");
                    ShowToast("Play next", "The engine did not accept the queue change.");
                    return;
                }
                BeginPendingOrderMutation("play next | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture), "context-play-next");
                EndOrderMutationRequest();
                SetContextOrderCommandPending(false, "");
                AddActivity("Queue context", "play next requested | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture));
                ShowToast("Play next requested", label + " is being placed directly after the current track.");
                _previousContextQuickStrip.Visibility = Visibility.Collapsed;
                ScheduleFastQueueRefresh();
            });
        }

        private void DeferNextOccurrence(int slots)
        {
            if (!_running || OrderMutationBusy)
            {
                if (OrderMutationBusy) ShowToast("Queue updating", "Wait for the current order change to finish committing.");
                return;
            }
            int occurrence = ContextOccurrence(1);
            if (occurrence <= 0 || occurrence == _currentOccurrence) return;
            slots = Math.Max(1, Math.Min(25, slots));
            string label = ContextOccurrenceLabel(occurrence);
            int requestedSlots = slots;
            SetContextOrderCommandPending(true, "move-later");
            if (!TryBeginOrderMutationRequest("context-move-later"))
            {
                SetContextOrderCommandPending(false, "");
                return;
            }
            DispatchTransportCommand(new object[] { "script-message", "yomi-order-move-later", occurrence.ToString(CultureInfo.InvariantCulture), requestedSlots.ToString(CultureInfo.InvariantCulture) }, delegate(bool accepted)
            {
                if (!accepted)
                {
                    EndOrderMutationRequest();
                    SetContextOrderCommandPending(false, "");
                    ShowToast("Move later", "The engine did not accept the queue change.");
                    return;
                }
                BeginPendingOrderMutation("move later +" + requestedSlots.ToString(CultureInfo.InvariantCulture) + " | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture), "context-move-later");
                EndOrderMutationRequest();
                SetContextOrderCommandPending(false, "");
                AddActivity("Queue context", "move later requested +" + requestedSlots.ToString(CultureInfo.InvariantCulture) + " | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture));
                ShowToast("Move later requested", label + " is being moved " + requestedSlots.ToString(CultureInfo.InvariantCulture) + " positions later.");
                _nextContextQuickStrip.Visibility = Visibility.Collapsed;
                ScheduleFastQueueRefresh();
            });
        }

        private void UpdateRepeatPill()
        {
            string fullLabel = _repeatMode == "one" ? "Repeat One" : _repeatMode == "all" ? "Repeat All" : "Repeat Off";
            string compactLabel = fullLabel;
            string tip = "Repeat mode: " + _repeatMode + ". Click to cycle Off, All, and One.";
            // Repeat is an interactive mode selector, not passive status. Each surface projects
            // independently so a missing/hidden full-player affordance can never suppress Mini
            // or maximized-Queue repeat authority.
            if (_repeatStateText != null) _repeatStateText.Text = _adaptiveLayoutTier == AdaptiveLayoutTier.Spacious ? fullLabel : compactLabel;
            if (_repeatStatePill != null)
            {
                _repeatStatePill.Visibility = Visibility.Collapsed;
                _repeatStatePill.Width = 0; _repeatStatePill.MinWidth = 0; _repeatStatePill.Margin = new Thickness(0);
                _repeatStatePill.ToolTip = tip;
            }
            if (_miniRepeatButton2 != null)
            {
                _miniRepeatButton2.Content = compactLabel;
                _miniRepeatButton2.ToolTip = tip;
            }
            if (_microRepeatButton != null)
            {
                _microRepeatButton.Content = _repeatMode == "one" ? "One" : _repeatMode == "all" ? "All" : "Off";
                _microRepeatButton.ToolTip = tip;
            }
            if (_queueDockRepeatButton != null)
            {
                _queueDockRepeatButton.Content = compactLabel;
                _queueDockRepeatButton.ToolTip = tip;
            }
        }

        private static string NormalizeRepeatMode(string mode)
        {
            string normalized = (mode ?? "all").Trim().ToLowerInvariant();
            return normalized == "off" || normalized == "one" || normalized == "all" ? normalized : "all";
        }

        private void AddRepeatMenuItem(MenuItem parent, string header, string mode)
        {
            string normalized = NormalizeRepeatMode(mode);
            var item = new MenuItem { Header = header, IsCheckable = true, IsChecked = String.Equals(_repeatMode, normalized, StringComparison.OrdinalIgnoreCase), Tag = "repeat:" + normalized, StaysOpenOnClick = true };
            item.Click += delegate { SetRepeatMode(normalized); RefreshRepeatMenuChecks(parent); };
            parent.Items.Add(item);
        }

        private void RefreshRepeatMenuChecks(MenuItem parent)
        {
            if (parent == null) return;
            foreach (object raw in parent.Items)
            {
                MenuItem item = raw as MenuItem;
                if (item == null || !(item.Tag is string)) continue;
                string tag = (string)item.Tag;
                if (!tag.StartsWith("repeat:", StringComparison.OrdinalIgnoreCase)) continue;
                item.IsChecked = String.Equals(tag.Substring(7), _repeatMode, StringComparison.OrdinalIgnoreCase);
            }
        }

        private static void StyleSystemThemeItem(MenuItem item)
        {
            if (item == null) return;
            try
            {
                item.Foreground = GradientChoiceBrush(new[] { "#0B1620", "#34404A", "#7C8A92", "#F3EEE4" });
                item.Effect = null;
                item.FontWeight = FontWeights.SemiBold;
            }
            catch { }
        }

        private void AddAppearanceMenuItem(MenuItem parent, string header, AppearancePreset preset)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, IsChecked = _appearanceManuallySelected && preset == _appearancePreset, Tag = preset, StaysOpenOnClick = true };
            try
            {
                Dictionary<string,string> colors=AppearanceColors(preset);
                string app=colors.ContainsKey("AppBg")?colors["AppBg"]:"#151515";
                string surface=colors.ContainsKey("SurfaceRaised")?colors["SurfaceRaised"]:"#252525";
                string accent=colors.ContainsKey("Accent")?colors["Accent"]:"#8A8A84";
                string text=colors.ContainsKey("TextPrimary")?colors["TextPrimary"]:"#F2F0E8";
                item.Foreground=GradientChoiceBrush(new[] { app, surface, accent, text }); item.Effect=null;
            } catch { }
            item.Click += delegate { SetAppearancePreset(preset, true); RefreshAppearanceMenuChecks(parent); }; parent.Items.Add(item);
        }
        private void AddDensityMenuItem(MenuItem parent, string header, InformationDensity density)
        {
            var item = new MenuItem { Header = header, IsCheckable = true, IsChecked = density == _informationDensity, Tag = density, StaysOpenOnClick = true };
            item.Click += delegate { SetInformationDensity(density, true); RefreshAppearanceMenuChecks(parent); }; parent.Items.Add(item);
        }
        private void RefreshAppearanceMenuChecks(MenuItem parent)
        {
            foreach (var raw in parent.Items)
            {
                var item = raw as MenuItem; if (item == null) continue;
                if (item.Tag is AppearancePreset) item.IsChecked = _appearanceManuallySelected && (AppearancePreset)item.Tag == _appearancePreset;
                if (item.Tag is InformationDensity) item.IsChecked = (InformationDensity)item.Tag == _informationDensity;
                if (item.Tag is string && String.Equals((string)item.Tag, "follow-windows", StringComparison.Ordinal)) item.IsChecked = !_appearanceManuallySelected;
            }
        }
        private void SetAppearancePreset(AppearancePreset preset, bool save)
        {
            // R61.94: any explicit YOMI theme choice permanently takes authority from the
            // Windows light/dark default until the user deliberately chooses another YOMI theme.
            if (save) _appearanceManuallySelected = true;
            if (_appearancePreset == preset)
            {
                if (save) SaveUiState();
                return;
            }
            _appearancePreset = preset;
            ApplyAppearancePreset(save);
            if (save) AddActivity("Appearance", AppearanceLabel(preset));
        }

        private void SetSystemAppearanceMode(bool save)
        {
            _appearanceManuallySelected = false;
            AppearancePreset resolved = ResolveSystemAppearancePreset();
            bool changed = _appearancePreset != resolved;
            _appearancePreset = resolved;
            ApplyAppearancePreset(save);
            if (save) AddActivity("Appearance", "System Theme" + (changed ? " · " + AppearanceLabel(resolved) : ""));
        }

        private static AppearancePreset ResolveSystemAppearancePreset()
        {
            try
            {
                using (Microsoft.Win32.RegistryKey key = Microsoft.Win32.Registry.CurrentUser.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"))
                {
                    object raw = key != null ? key.GetValue("AppsUseLightTheme") : null;
                    if (raw != null && Convert.ToInt32(raw, CultureInfo.InvariantCulture) != 0) return AppearancePreset.Paper;
                }
            }
            catch { }
            return AppearancePreset.Midnight;
        }
        private void ApplyAppearancePreset(bool save)
        {
            var palette = EffectiveAppearanceColors(_appearancePreset);
            foreach (var pair in palette) SetResourceBrush(pair.Key, pair.Value);
            ApplyReadableSurfaceResources(palette);
            ApplyAppearanceAtmosphere(palette);
            if (_appearanceBadge != null) _appearanceBadge.Text = AppearanceLabel(_appearancePreset).ToUpperInvariant();
            SyncWindowCompositionBackground();
            if (_queueByOccurrence.Count > 0) ApplyQueueRowsBudgeted(new HashSet<int>(_queueByOccurrence.Keys), "appearance");
            if (save) SaveUiState();
        }
