        private void ApplyAppearanceAtmosphere(Dictionary<string,string> palette)
        {
            try
            {
                string app = palette.ContainsKey("AppBg") ? palette["AppBg"] : "#090D11";
                string surface = palette.ContainsKey("Surface") ? palette["Surface"] : app;
                string accentSoft = palette.ContainsKey("AccentSoft") ? palette["AccentSoft"] : surface;
                string chrome = palette.ContainsKey("ChromeBg") ? palette["ChromeBg"] : app;
                string raised = palette.ContainsKey("SurfaceRaised") ? palette["SurfaceRaised"] : surface;
                // R61.96: make depth legible at ordinary controller/workbench sizes. The old
                // gradients differed by only a few RGB values and effectively vanished unless
                // the window exposed a huge empty area. These remain theme-derived, but each
                // functional surface gets a visibly distinct tonal range.
                var work = new LinearGradientBrush { StartPoint = new Point(0,0), EndPoint = new Point(1,1) };
                work.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(app),ParseColor(surface),0.62)),0));
                work.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(app),ParseColor(surface),0.16)),0.52));
                work.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(app),ParseColor(accentSoft),0.66)),1));
                work.Freeze(); SetResourceValue(_app.Resources,"WorkbenchAtmosphere",work);

                var player = new LinearGradientBrush { StartPoint = new Point(0,0), EndPoint = new Point(1,1) };
                player.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(surface),ParseColor(raised),0.78)),0));
                player.GradientStops.Add(new GradientStop(WindowSurfaceColor(ParseColor(surface)),0.50));
                player.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(surface),ParseColor(accentSoft),0.72)),1));
                player.Freeze(); SetResourceValue(_app.Resources,"PlayerAtmosphere",player);

                var queue = new LinearGradientBrush { StartPoint = new Point(0,0), EndPoint = new Point(1,1) };
                queue.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(surface),ParseColor(raised),0.48)),0));
                queue.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(app),ParseColor(surface),0.54)),0.58));
                queue.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(app),ParseColor(accentSoft),0.52)),1));
                queue.Freeze(); SetResourceValue(_app.Resources,"QueueAtmosphere",queue);

                var chromeBrush = new LinearGradientBrush { StartPoint = new Point(0,0), EndPoint = new Point(0,1) };
                chromeBrush.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(chrome),ParseColor(raised),0.72)),0));
                chromeBrush.GradientStops.Add(new GradientStop(WindowSurfaceColor(ParseColor(chrome)),0.56));
                chromeBrush.GradientStops.Add(new GradientStop(WindowSurfaceColor(BlendColor(ParseColor(chrome),ParseColor(app),0.72)),1));
                chromeBrush.Freeze(); SetResourceValue(_app.Resources,"ChromeAtmosphere",chromeBrush);

                Color playerFill = BlendColor(ParseColor(surface), ParseColor(raised), 0.64);
                Color playerHover = palette.ContainsKey("SurfaceHover") ? ParseColor(palette["SurfaceHover"]) : ParseColor(raised);
                Color playerPressed = palette.ContainsKey("SurfacePressed") ? ParseColor(palette["SurfacePressed"]) : ParseColor(raised);
                SetResourceValue(_app.Resources, "PlayerControlFill", AlphaBrush(playerFill, 104));
                SetResourceValue(_app.Resources, "PlayerControlHover", AlphaBrush(playerHover, 154));
                SetResourceValue(_app.Resources, "PlayerControlPressed", AlphaBrush(playerPressed, 184));
            }
            catch { }
        }
        private static Color ParseColor(string hex) { return (Color)ColorConverter.ConvertFromString(hex); }
        private static Color BlendColor(Color a, Color b, double t)
        {
            t=Math.Max(0,Math.Min(1,t));
            return Color.FromArgb(255,(byte)Math.Round(a.R+(b.R-a.R)*t),(byte)Math.Round(a.G+(b.G-a.G)*t),(byte)Math.Round(a.B+(b.B-a.B)*t));
        }
        private static SolidColorBrush AlphaBrush(Color color, byte alpha)
        {
            color.A = alpha; var brush = new SolidColorBrush(color); brush.Freeze(); return brush;
        }

        private void SetInformationDensity(InformationDensity density,bool save)
        {
            if (_informationDensity == density) return;
            _informationDensity=density;
            // Named full workspaces are working environments, not immutable presets. Their density is remembered in-context.
            ApplyInformationDensity(save);
            if (save) AddActivity("Detail", density.ToString());
        }
        private static bool StatusNeedsAttention(string value)
        {
            string state = (value ?? "").Trim().ToUpperInvariant();
            if (state.Length == 0 || state == "-" || state == "UNKNOWN" || state == "IDLE" || state == "WARMING") return false;
            return state != "OK" && state != "HEALTHY" && state != "READY" && state != "NORMAL" && state != "NOMINAL" && state != "LIVE";
        }

        private bool BufferNeedsAttention()
        {
            return StatusNeedsAttention(_lastObservedBufferHealth);
        }

        private static bool BroadcastSurfaceNeedsAttention(Dictionary<string, object> queue, Dictionary<string, object> engine)
        {
            if (queue == null) queue = EmptyMap();
            if (engine == null) engine = EmptyMap();
            if (StatusNeedsAttention(GetString(queue, "buffer_health", ""))) return true;
            string governor = GetString(GetMap(queue, "resource"), "governor_mode", "");
            if (StatusNeedsAttention(governor)) return true;
            string phase = GetString(engine, "phase", "").ToUpperInvariant();
            if (phase == "ERROR" || phase == "FAILED" || phase == "FAULT" || phase == "FAULTED") return true;
            if (GetBool(GetMap(queue, "rehearsal"), "active", false)) return true;
            if (GetBool(GetMap(queue, "freeze"), "active", false)) return true;
            return false;
        }

        private void RefreshEverydayStatusVisibility()
        {
            bool technical = _informationDensity == InformationDensity.Technical;
            if (_occurrencePill != null) _occurrencePill.Visibility = Visibility.Collapsed;
            if (_playbackSummaryText != null) _playbackSummaryText.Visibility = Visibility.Collapsed;
            if (_memoryPill != null)
                _memoryPill.Visibility = (!_miniMode && (technical || (_workspaceProfile == WorkspaceProfile.Library && _informationDensity != InformationDensity.Clean))) ? Visibility.Visible : Visibility.Collapsed;
            if (_bufferPill != null)
                _bufferPill.Visibility = (!_miniMode && (technical || BufferNeedsAttention())) ? Visibility.Visible : Visibility.Collapsed;
            if (_workerPill != null)
                _workerPill.Visibility = (!_miniMode && technical) ? Visibility.Visible : Visibility.Collapsed;
        }

        private void ApplyInformationDensity(bool save)
        {
            bool technical=_informationDensity==InformationDensity.Technical;
            // R61.37: information density is opt-in. Healthy preparation data does not earn permanent
            // space merely because YOMI knows it; failures/warnings may still surface themselves.
            RefreshEverydayStatusVisibility();
            _technicalText.Visibility=Visibility.Collapsed;
            if (_operatorHealthRail != null) _operatorHealthRail.Visibility = (!_miniMode && technical) ? Visibility.Visible : Visibility.Collapsed;
            ApplyQuietSurface(false);
            if(save)SaveUiState();
        }

        private void SetQuietSurface(bool quiet, bool save)
        {
            if (_quietSurface == quiet) return;
            _quietSurface = quiet;
            ApplyQuietSurface(save);
            if (save) AddActivity("Interface", quiet ? "quiet surface" : "expanded chrome");
        }

        private void SetTitleBarVisible(bool visible, bool save)
        {
            if (_titleBarVisible == visible) return;
            _titleBarVisible = visible;
            ApplyQuietSurface(save);
            if (MediaStageVisible()) ScheduleMediaStageAspectSnap();
        }

        private void SetMenuBarVisible(bool visible, bool save)
        {
            if (_menuBarVisible == visible) return;
            _menuBarVisible = visible;
            ApplyQuietSurface(save);
            if (MediaStageVisible()) ScheduleMediaStageAspectSnap();
            if (save && visible && _classicMenu != null) _classicMenu.Focus();
        }

        private void ApplyQuietSurface(bool save)
        {
            bool quiet = _quietSurface && !_miniMode;
            // R61.69: menu visibility is one reversible preference. Mini stays a transport appliance,
            // while every full-window workspace can restore the menu from the title bar or F10.
            bool title = _titleBarVisible;
            if (_titleBar != null) _titleBar.Visibility = title ? Visibility.Visible : Visibility.Collapsed;
            if (_titleBarRow != null) _titleBarRow.Height = new GridLength(title ? 25 : 0);
            try
            {
                System.Windows.Shell.WindowChrome chrome = System.Windows.Shell.WindowChrome.GetWindowChrome(_window);
                if (chrome != null) chrome.CaptionHeight = title ? 25 : 0;
            }
            catch { }
            bool menu = !_miniMode && _menuBarVisible;
            if (_classicMenuBar != null) _classicMenuBar.Visibility = menu ? Visibility.Visible : Visibility.Collapsed;
            if (_classicMenuRow != null) _classicMenuRow.Height = new GridLength(menu ? 21 : 0);
            Button menuRestore = _window.FindName("MenuRestoreButton") as Button;
            if (menuRestore != null) menuRestore.Visibility = (!_miniMode && !menu) ? Visibility.Visible : Visibility.Collapsed;
            if (_appearanceBadge != null) { _appearanceBadge.Text = ""; _appearanceBadge.Visibility = Visibility.Collapsed; }
            if (_qualityPill != null) _qualityPill.Visibility = (!_miniMode && _informationDensity == InformationDensity.Technical) ? Visibility.Visible : Visibility.Collapsed;
            if (_queueRevisionText != null) _queueRevisionText.Visibility = (!_miniMode && _informationDensity == InformationDensity.Technical) ? Visibility.Visible : Visibility.Collapsed;
            if (_mediaModeBadge != null) _mediaModeBadge.Visibility = Visibility.Collapsed;
            if (_visualizerChrome != null) _visualizerChrome.Visibility = (!quiet || _informationDensity == InformationDensity.Technical) ? Visibility.Visible : Visibility.Collapsed;
            // Shortcut wallpaper is useful as onboarding, not as a permanent status bar.
            // F1 / Ctrl+K remain the durable discovery paths when the quiet surface is active.
            if (_footerHint != null) _footerHint.Visibility = (!quiet && !_miniMode) ? Visibility.Visible : Visibility.Collapsed;
            UpdateRepeatPill();
            UpdateRuntimeSurfaceVisibility(_lastObservedPhase);
            if (save) SaveUiState();
        }

        private void UpdateRuntimeSurfaceVisibility(string phase)
        {
            if (_runtimeSurface == null) return;
            if (_miniMode) { _runtimeSurface.Visibility = Visibility.Collapsed; return; }
            bool attention = String.Equals(phase, "error", StringComparison.OrdinalIgnoreCase);
            bool explicitDetail = !_quietSurface || _informationDensity == InformationDensity.Technical;
            _runtimeSurface.Visibility = (attention || explicitDetail) ? Visibility.Visible : Visibility.Collapsed;
        }

        private void SetRepeatMode(string mode)
        {
            string normalized = NormalizeRepeatMode(mode);
            bool accepted = !_running || SendMpv("script-message", "yomi-repeat-mode", normalized);
            // R61.106.8: when the engine accepts the command, music.lua is the sole persistence
            // authority for repeat-mode.txt. The old controller+Lua double-write raced two atomic
            // replacements against the same path and produced intermittent "file already exists"
            // IOExceptions. Controller persistence is only the offline/rejected fallback now.
            if (!_running || !accepted) QueueRepeatModePersistence(normalized);
            _repeatMode = normalized;
            if (_running && accepted)
            {
                _pendingRepeatIntent = normalized;
                _pendingRepeatIntentUntilMs = _clock.ElapsedMilliseconds + 5000;
            }
            else
            {
                _pendingRepeatIntent = "";
                _pendingRepeatIntentUntilMs = 0;
            }
            UpdateRepeatPill();
            UpdateNextUpUi();
            AddActivity("Repeat", (normalized == "one" ? "Repeat One" : normalized == "all" ? "Repeat All" : "Repeat Off") + (accepted ? "" : " - saved for next playback start"));
            ScheduleFastPlaybackRefresh();
        }

        private void QueueRepeatModePersistence(string normalized)
        {
            lock (_repeatPersistenceSync)
            {
                _pendingRepeatModePersistence = normalized ?? "all";
                _pendingRepeatModeEpoch = Volatile.Read(ref _slotStateEpoch);
                if (_repeatPersistenceWorkerActive) return;
                _repeatPersistenceWorkerActive = true;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainRepeatModePersistence(); });
        }

        private void DrainRepeatModePersistence()
        {
            try
            {
                while (true)
                {
                    string pending;
                    int epoch;
                    lock (_repeatPersistenceSync)
                    {
                        pending = _pendingRepeatModePersistence;
                        epoch = _pendingRepeatModeEpoch;
                        _pendingRepeatModePersistence = "";
                    }
                    if (String.IsNullOrWhiteSpace(pending)) break;
                    if (epoch != Volatile.Read(ref _slotStateEpoch) || _shutdownRequested || _slotSwitchActive) continue;
                    try
                    {
                        Directory.CreateDirectory(_stateRoot);
                        WriteUtf8NoBom(Path.Combine(_stateRoot, "repeat-mode.txt"), pending);
                    }
                    catch (Exception ex) { WriteControllerPerformanceLogAsync("REPEAT PERSIST FAILED " + ex.GetType().Name + " " + ex.Message); }
                }
            }
            finally
            {
                lock (_repeatPersistenceSync)
                {
                    _repeatPersistenceWorkerActive = false;
                    if (!String.IsNullOrWhiteSpace(_pendingRepeatModePersistence))
                    {
                        _repeatPersistenceWorkerActive = true;
                        ThreadPool.QueueUserWorkItem(delegate(object nested) { DrainRepeatModePersistence(); });
                    }
                }
            }
        }

        private void PersistRepeatModeForTransition(string normalized)
        {
            try
            {
                Directory.CreateDirectory(_stateRoot);
                WriteUtf8NoBom(Path.Combine(_stateRoot, "repeat-mode.txt"), NormalizeRepeatMode(normalized));
            }
            catch (Exception ex) { WriteControllerPerformanceLogAsync("REPEAT TRANSITION PERSIST FAILED " + ex.GetType().Name + " " + ex.Message); }
        }

        private void CycleRepeatMode()
        {
            SetRepeatMode(_repeatMode == "all" ? "one" : _repeatMode == "one" ? "off" : "all");
        }
        private void SetReduceMotion(bool reduce,bool save){if(_reduceMotion==reduce)return;_reduceMotion=reduce;if(save)SaveUiState();}

        private void UpdateTimeUi(double position)
        {
            if (Double.IsNaN(position) || Double.IsInfinity(position) || position < 0)
                position = 0;
            if (_duration > 0)
                position = Math.Min(position, _duration);

            _elapsedText.Text = FormatTime(position);
            _remainingText.Text = _duration > 0
                ? (_showTotalTime ? FormatTime(_duration) : "-" + FormatTime(Math.Max(0, _duration - position)))
                : (_showTotalTime ? "0:00" : "-0:00");
            if (_elapsedText != null) _elapsedText.ToolTip = _showTotalTime ? "Elapsed / total | click for remaining" : "Elapsed / remaining | click for total";
            if (_remainingText != null) _remainingText.ToolTip = _elapsedText.ToolTip;
            UpdateProgressVisual();
            UpdatePlaybackSummary();
            UpdateCurrentQueueTemporalState();
            UpdateUpcomingQueueTemporalState();
        }

        // R38 PRIORITY FIDELITY: temporal context may replace only ordinary healthy-ready
        // labels. Degraded-but-playable states (policy-deferred, fault-isolated, SLA-yielded)
        // remain visible instead of being cosmetically flattened into timing. R37 COMFY
        // horizon legibility remains intact without adding any surface or authority.
        private bool QueueTemporalLabelMayReplaceSafety(QueueRow row, RuntimeQueueItem runtime)
        {
            if (row == null || runtime == null) return false;
            if (String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase)) return false;
            if (!runtime.TransitionReady && !runtime.PresentationComplete) return false;
            if (runtime.HasSlack) return false;
            if (runtime.EstimatedPrepareSeconds >= 0 && !runtime.TransitionReady) return false;

            string label = row.SafetyLabel ?? "";
            return String.IsNullOrWhiteSpace(label)
                || label.StartsWith("ENDS ", StringComparison.Ordinal)
                || label.StartsWith("STARTS ~", StringComparison.Ordinal)
                || String.Equals(label, "FULL READY", StringComparison.Ordinal)
                || String.Equals(label, "AUDIO READY", StringComparison.Ordinal);
        }

        private void RestoreQueueTemporalSafety(QueueRow row, RuntimeQueueItem runtime, int delta)
        {
            if (row == null) return;
            string label = row.SafetyLabel ?? "";
            if (label.StartsWith("ENDS ", StringComparison.Ordinal) || label.StartsWith("STARTS ~", StringComparison.Ordinal))
            {
                ApplyQueueObservatoryState(row, runtime, delta);
                ApplyQueueConfidence(row, runtime, delta);
                row.Explanation = ExplainQueueRow(row);
            }
        }

        private void UpdateCurrentQueueTemporalState()
        {
            if (_currentOccurrence <= 0) return;
            QueueRow row;
            if (!_queueByOccurrence.TryGetValue(_currentOccurrence, out row) || row == null) return;

            RuntimeQueueItem runtime;
            _runtimeQueue.TryGetValue(_currentOccurrence, out runtime);
            if (!_running || _duration <= 0 || !QueueTemporalLabelMayReplaceSafety(row, runtime))
            {
                RestoreQueueTemporalSafety(row, runtime, 0);
                return;
            }

            double remaining = Math.Max(0, _duration - Math.Max(0, _timePosition));
            row.SafetyLabel = "ENDS " + FormatTime(remaining);
            row.SafetyBrush = remaining <= 15 ? Brush("Warning") : Brush("TextMuted");
            row.Explanation = ExplainQueueRow(row);
        }

        private void UpdateUpcomingQueueTemporalState()
        {
            // R61.99: this runs with the playback clock. Never linearly scan a multi-thousand
            // item session merely to refresh the current/next-three temporal labels.
            int currentIndex = -1;
            int mappedTemporalIndex;
            if (_currentOccurrence > 0 && _orderIndexByOccurrence.TryGetValue(_currentOccurrence, out mappedTemporalIndex))
                currentIndex = mappedTemporalIndex;
            foreach (int occ in _queueHorizonTemporalRows.ToArray())
            {
                QueueRow oldRow;
                if (_queueByOccurrence.TryGetValue(occ, out oldRow) && oldRow != null)
                {
                    oldRow.Detail = oldRow.BaseDetail;
                    RuntimeQueueItem oldRuntime;
                    _runtimeQueue.TryGetValue(occ, out oldRuntime);
                    int oldIndex = -1;
                    int mappedOldTemporalIndex;
                    if (_orderIndexByOccurrence.TryGetValue(occ, out mappedOldTemporalIndex)) oldIndex = mappedOldTemporalIndex;
                    int oldDelta = currentIndex >= 0 && oldIndex >= 0 ? oldIndex - currentIndex : 0;
                    RestoreQueueTemporalSafety(oldRow, oldRuntime, oldDelta);
                }
            }
            _queueHorizonTemporalRows.Clear();

            if (!_running || _currentOccurrence <= 0 || _duration <= 0 || currentIndex < 0) return;

            double untilStart = Math.Max(0, _duration - Math.Max(0, _timePosition));
            for (int delta = 1; delta <= 3; delta++)
            {
                int index = currentIndex + delta;
                if (index < 0 || index >= _order.Count) break;
                int occ = _order[index];
                QueueRow row;
                if (!_queueByOccurrence.TryGetValue(occ, out row) || row == null) break;

                row.Detail = row.BaseDetail + "  |  STARTS ~" + FormatTime(untilStart);
                _queueHorizonTemporalRows.Add(occ);

                RuntimeQueueItem runtime;
                _runtimeQueue.TryGetValue(occ, out runtime);
                if (QueueTemporalLabelMayReplaceSafety(row, runtime))
                {
                    row.SafetyLabel = "STARTS ~" + FormatTime(untilStart);
                    row.SafetyBrush = Brush("TextMuted");
                    row.Explanation = ExplainQueueRow(row);
                }

                TrackMeta meta;
                if (!_trackMeta.TryGetValue(occ, out meta) || meta == null || meta.Duration <= 0)
                    break;
                untilStart += meta.Duration;
            }
        }

        private void ToggleTimeDisplayMode()
        {
            _showTotalTime = !_showTotalTime;
            SaveUiState();
            UpdateTimeUi(_timePosition);
        }

        private void UpdatePlaybackSummary()
        {
            if (_playbackSummaryText == null) return;
            string position = _currentSlot > 0 && _order.Count > 0
                ? _currentSlot.ToString(CultureInfo.InvariantCulture) + " / " + _order.Count.ToString(CultureInfo.InvariantCulture)
                : "Queue —";
            string duration = _duration > 0 ? FormatTime(_timePosition) + " / " + FormatTime(_duration) : "TIME -";
            string buffer = String.IsNullOrWhiteSpace(_lastObservedBufferHealth) || _lastObservedBufferHealth == "-"
                ? "BUFFER -"
                : "BUFFER " + _lastObservedBufferHealth;
            if (_lastTargetAhead > 0)
                buffer += " " + _lastReadyAhead.ToString(CultureInfo.InvariantCulture) + "/" + _lastTargetAhead.ToString(CultureInfo.InvariantCulture);
            _playbackSummaryText.Text = position + "  |  " + duration + "  |  " + buffer;
            UpdateQueueNowAnchor();
        }

        private void UpdateProgressVisual()
        {
            double value = _seeking ? _seekPreview : _timePosition;
            double fraction = _duration > 0 ? Math.Max(0, Math.Min(1, value / _duration)) : 0;
            UpdateProgressGeometry(_progressTrack, _progressFill, _progressThumb, fraction, 5.0);
            UpdateProgressGeometry(_miniProgressTrack, _miniProgressFill, _miniProgressThumb, fraction, 4.0);
            UpdateProgressGeometry(_microProgressTrack, _microProgressFill, _microProgressThumb, fraction, 4.0);
            UpdateProgressGeometry(_queueDockProgressTrack, _queueDockProgressFill, _queueDockProgressThumb, fraction, 4.0);
        }

        private static void UpdateProgressGeometry(Border track, Border fill, FrameworkElement thumb, double fraction, double thumbOffset)
        {
            if (track == null || fill == null || thumb == null || track.ActualWidth <= 0) return;
            double pixels = track.ActualWidth * Math.Max(0, Math.Min(1, fraction));
            fill.Width = pixels;
            thumb.Margin = new Thickness(pixels - thumbOffset, 0, 0, 0);
        }

        private void UpdateQueueDockSeekPreview(double x)
        {
            double width = Math.Max(1, _queueDockProgressTrack != null ? _queueDockProgressTrack.ActualWidth : 1);
            double fraction = Math.Max(0, Math.Min(1, x / width));
            _seekPreview = _duration * fraction;
            UpdateTimeUi(_seekPreview);
        }

        private void UpdateMiniSeekPreview(double x)
        {
            double width = Math.Max(1, _miniProgressTrack.ActualWidth);
            double fraction = Math.Max(0, Math.Min(1, x / width));
            _seekPreview = _duration * fraction;
            UpdateTimeUi(_seekPreview);
        }

        private void UpdateMicroSeekPreview(double x)
        {
            double width = Math.Max(1, _microProgressTrack.ActualWidth);
            double fraction = Math.Max(0, Math.Min(1, x / width));
            _seekPreview = _duration * fraction;
            UpdateTimeUi(_seekPreview);
        }

        private void UpdateSeekPreview(double x)
        {
            double width = Math.Max(1, _progressTrack.ActualWidth);
            double fraction = Math.Max(0, Math.Min(1, x / width));
            _seekPreview = _duration * fraction;
            UpdateSeekHover(x);
            UpdateTimeUi(_seekPreview);
        }

        private void UpdateSeekHover(double x)
        {
            if (_duration <= 0 || _progressTrack.ActualWidth <= 0)
            {
                HideSeekHover();
                return;
            }
            double width = Math.Max(1, _progressTrack.ActualWidth);
            double clamped = Math.Max(0, Math.Min(width, x));
            double preview = _duration * (clamped / width);
            _seekPreviewText.Text = FormatTime(preview);
            _seekPreviewBubble.Visibility = Visibility.Visible;
            _seekPreviewMarker.Visibility = Visibility.Visible;
            Canvas.SetLeft(_seekPreviewMarker, Math.Max(0, Math.Min(width - 1, clamped)));
            Canvas.SetLeft(_seekPreviewBubble, Math.Max(0, Math.Min(Math.Max(0, width - 54), clamped - 27)));
        }

        private void HideSeekHover()
        {
            if (_seekPreviewBubble != null) _seekPreviewBubble.Visibility = Visibility.Collapsed;
            if (_seekPreviewMarker != null) _seekPreviewMarker.Visibility = Visibility.Collapsed;
        }

        private void SeekRelative(double seconds)
        {
            if (!_running) return;
            double target = Math.Max(0, _timePosition + seconds);
            if (_duration > 0) target = Math.Min(_duration, target);
            SeekAbsolute(target);
        }

        private void SeekAbsolute(double target)
        {
            if (!_running) return;
            target = Math.Max(0, target);
            if (_duration > 0) target = Math.Min(_duration, target);
            string value = target.ToString("0.###", CultureInfo.InvariantCulture);
            _timePosition = target;
            lock (_playbackSnapshotSync)
            {
                _playbackSnapshotGeneration++;
                _playbackSnapshotValid = false;
                _playbackSnapshotStampMs = -10000;
                _playbackSnapshotPosition = target;
            }
            UpdateTimeUi(_timePosition);
            SendMpv("seek", value, "absolute+exact");
            RestartFramePreviewsAt(target, true);
        }

        private static string FormatTime(double seconds)
        {
            if (Double.IsNaN(seconds) || Double.IsInfinity(seconds) || seconds < 0)
                seconds = 0;
            int total = (int)Math.Floor(seconds + 0.0001);
            int hours = total / 3600;
            int minutes = (total % 3600) / 60;
            int secs = total % 60;
            return hours > 0
                ? String.Format(CultureInfo.InvariantCulture, "{0}:{1:00}:{2:00}", hours, minutes, secs)
                : String.Format(CultureInfo.InvariantCulture, "{0}:{1:00}", minutes, secs);
        }

        private static bool IsPlaceholderTrackTitle(string title, int occurrence)
        {
            if (String.IsNullOrWhiteSpace(title)) return true;
            string trimmed = title.Trim();
            return String.Equals(trimmed, "Track " + occurrence.ToString(CultureInfo.InvariantCulture), StringComparison.OrdinalIgnoreCase) ||
                   String.Equals(trimmed, "Occurrence " + occurrence.ToString(CultureInfo.InvariantCulture), StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsUnavailableTrackTitle(string title)
        {
            if (String.IsNullOrWhiteSpace(title)) return false;
            string normalized = title.Trim().ToLowerInvariant();
            return normalized == "unavailable video" || normalized == "metadata unavailable" || normalized == "private video" || normalized == "deleted video" ||
                   normalized == "[private video]" || normalized == "[deleted video]";
        }

        private static bool IsHardUnavailableTrackTitle(string title)
        {
            if (String.IsNullOrWhiteSpace(title)) return false;
            string normalized = title.Trim().ToLowerInvariant();
            return normalized == "unavailable video" || normalized == "private video" || normalized == "deleted video" ||
                   normalized == "[private video]" || normalized == "[deleted video]";
        }

        private static bool StderrConfirmsHardUnavailable(MetadataBulkCandidate candidate, string[] stderrLines)
        {
            if (candidate == null || stderrLines == null || stderrLines.Length == 0) return false;
            string id = (candidate.YoutubeId ?? "").Trim();
            string url = (candidate.Url ?? "").Trim();
            foreach (string raw in stderrLines)
            {
                string line = (raw ?? "").Trim();
                if (line.Length == 0) continue;
                bool identifiesCandidate = (id.Length > 0 && line.IndexOf(id, StringComparison.OrdinalIgnoreCase) >= 0) ||
                                           (url.Length > 0 && line.IndexOf(url, StringComparison.OrdinalIgnoreCase) >= 0);
                if (!identifiesCandidate) continue;
                string lower = line.ToLowerInvariant();
                if (lower.Contains("video unavailable") || lower.Contains("private video") || lower.Contains("this video is private") ||
                    lower.Contains("deleted video") || lower.Contains("has been removed") || lower.Contains("has been deleted") ||
                    lower.Contains("no longer available") || lower.Contains("account associated with this video has been terminated"))
                    return true;
            }
            return false;
        }

        private static bool MetadataTerminalCacheFresh(Dictionary<string, object> map, string title, string path)
        {
            if (!IsUnavailableTrackTitle(title)) return true;
            DateTime checkedUtc;
            string stamp = GetString(map, "checked_utc", "");
            if (!DateTime.TryParse(stamp, CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out checkedUtc))
            {
                try { checkedUtc = File.GetLastWriteTimeUtc(path); }
                catch { return false; }
            }
            TimeSpan ttl = String.Equals(title.Trim(), "Metadata unavailable", StringComparison.OrdinalIgnoreCase) ? TimeSpan.FromDays(7) : TimeSpan.FromDays(30);
            return checkedUtc > DateTime.UtcNow.Subtract(ttl);
        }

        private string MetadataCachePath(int occurrence)
        {
            return Path.Combine(_cacheRoot, "meta", "track-" + occurrence.ToString(CultureInfo.InvariantCulture) + ".info.json");
        }

        private string MetadataObjectCachePath(string youtubeId, string url)
        {
            string sourceKey = ComputeSourceKey(youtubeId, url);
            if (String.IsNullOrWhiteSpace(sourceKey)) return "";
            return Path.Combine(_cacheRoot, "objects", "meta", sourceKey + "-meta.info.json");
        }

        private static string YoutubeIdFromUrl(string url)
        {
            if (String.IsNullOrWhiteSpace(url)) return "";
            try
            {
                Uri uri;
                if (!Uri.TryCreate(url, UriKind.Absolute, out uri)) return "";
                string host = (uri.Host ?? "").ToLowerInvariant();
                if (host.EndsWith("youtu.be")) return uri.AbsolutePath.Trim('/').Split('/')[0];
                string query = uri.Query ?? "";
                foreach (string part in query.TrimStart('?').Split('&'))
                {
                    int eq = part.IndexOf('=');
                    if (eq > 0 && String.Equals(part.Substring(0, eq), "v", StringComparison.OrdinalIgnoreCase))
                        return Uri.UnescapeDataString(part.Substring(eq + 1));
                }
                string[] pieces = uri.AbsolutePath.Trim('/').Split('/');
                for (int i = 0; i + 1 < pieces.Length; i++)
                    if (String.Equals(pieces[i], "shorts", StringComparison.OrdinalIgnoreCase) || String.Equals(pieces[i], "embed", StringComparison.OrdinalIgnoreCase))
                        return pieces[i + 1];
            }
            catch { }
            return "";
        }

        private bool TryHydrateMetadataFromCache(int occurrence)
        {
            TrackMeta meta;
            if (occurrence <= 0 || !_trackMeta.TryGetValue(occurrence, out meta) || meta == null) return false;
            string path = MetadataCachePath(occurrence);
            if (!File.Exists(path)) return false;
            Dictionary<string, object> map = ReadJsonFresh(path);
            if (map.Count == 0) return false;
            string expected = YoutubeIdFromUrl(meta.Url);
            string observed = GetString(map, "id", "");
            if (expected.Length > 0 && observed.Length > 0 && !String.Equals(expected, observed, StringComparison.OrdinalIgnoreCase)) return false;
            string title = GetString(map, "title", "");
            if (String.IsNullOrWhiteSpace(title) || !MetadataTerminalCacheFresh(map, title, path)) return false;
            meta.Title = title;
            meta.Channel = GetString(map, "channel", GetString(map, "uploader", meta.Channel));
            meta.Duration = GetDouble(map, "duration", meta.Duration);
            if (String.IsNullOrWhiteSpace(meta.YoutubeId)) meta.YoutubeId = observed;
            return true;
        }

        private void QueueMetadataPrefetch(int occurrence, bool urgent = false)
        {
            TrackMeta meta;
            if (occurrence <= 0 || !_trackMeta.TryGetValue(occurrence, out meta) || meta == null || String.IsNullOrWhiteSpace(meta.Url)) return;
            if (!IsPlaceholderTrackTitle(meta.Title, occurrence)) return;
            // R61.70: cache lookup belongs to the metadata worker. Do not perform dozens of
            // File.Exists/open/JSON parses on WPF merely because the queue horizon moved.
            long retryAfter;
            if (_metadataPrefetchRetryAfterMs.TryGetValue(occurrence, out retryAfter) && _clock.ElapsedMilliseconds < retryAfter) return;
            lock (_metadataPrefetchQueue)
            {
                // The bulk playlist lane owns background metadata hydration. While it is active,
                // only the currently visible track may bypass it for one urgent lookup. This
                // prevents a bulk playlist extraction and dozens of per-track yt-dlp processes
                // from racing to discover the same information.
                if (_metadataBulkActive && (!urgent || occurrence != _currentOccurrence)) return;
                if (_metadataPrefetchPending.Contains(occurrence)) return;
                _metadataPrefetchPending.Add(occurrence);
                if (urgent) _metadataUrgentQueue.Enqueue(occurrence);
                else _metadataPrefetchQueue.Enqueue(occurrence);
            }
            PumpMetadataPrefetch();
        }
        private void ScheduleMetadataAhead()
        {
            if (_trackMeta.Count == 0) return;
            if (_clock.ElapsedMilliseconds < _uiBudgetPressureUntilMs) return;

            // Queue-title readiness is independent of transport readiness. First hydrate every
            // title already present in YOMI's local metadata cache; then resolve the remaining
            // placeholders through one bulk source. Neither phase waits for Play to become active.
            StartMetadataCacheSweepIfUseful();
            if (_metadataCacheSweepActive) return;
            StartBulkMetadataPrefetchIfUseful();
            if (_metadataBulkActive) return;

            // Individual lookups remain the low-priority fallback for the current/ahead horizon.
            // Keep those behind first-sound readiness so they cannot compete with playback startup.
            if (!_running || !_audioActive || _timePosition < 2.5) return;
            if (_currentOccurrence > 0) QueueMetadataPrefetch(_currentOccurrence, true);
            int start = _currentSlot > 0 ? Math.Max(0, _currentSlot - 1) : 0;
            int finish = Math.Min(_order.Count, start + MetadataPrefetchAhead);
            for (int i = start; i < finish; i++) QueueMetadataPrefetch(_order[i]);
        }

        private void StartMetadataCacheSweepIfUseful()
        {
            if (_metadataCacheSweepActive || String.IsNullOrWhiteSpace(_sessionId) ||
                String.Equals(_metadataCacheSweepSessionId, _sessionId, StringComparison.Ordinal)) return;

            Dictionary<string, object> metadataSession = ReadJsonCached(Path.Combine(_stateRoot, "session.json"));
            int expectedMetadataCount = ExpectedQueueEntryCount(metadataSession);
            if (expectedMetadataCount > 0 && _trackMeta.Count < expectedMetadataCount) return;

            MetadataBulkCandidate[] candidates = _trackMeta
                .Where(pair => pair.Value != null && IsPlaceholderTrackTitle(pair.Value.Title, pair.Key) && !String.IsNullOrWhiteSpace(pair.Value.Url))
                .Select(pair => new MetadataBulkCandidate
                {
                    Occurrence = pair.Key,
                    YoutubeId = !String.IsNullOrWhiteSpace(pair.Value.YoutubeId) ? pair.Value.YoutubeId : YoutubeIdFromUrl(pair.Value.Url),
                    Url = pair.Value.Url ?? "",
                    SourceIndex = pair.Value.SourceIndex
                }).ToArray();

            _metadataCacheSweepSessionId = _sessionId;
            if (candidates.Length == 0) return;

            string sessionId = _sessionId;
            int generation = Volatile.Read(ref _metadataGeneration);
            _metadataCacheSweepActive = true;
            ThreadPool.QueueUserWorkItem(delegate
            {
                var hydrations = new List<MetadataHydration>();
                foreach (MetadataBulkCandidate candidate in candidates)
                {
                    if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive) return;
                    MetadataHydration hydration = ReadMetadataHydration(MetadataCachePath(candidate.Occurrence), candidate.Occurrence, candidate.Url);
                    if (hydration == null)
                    {
                        string objectPath = MetadataObjectCachePath(candidate.YoutubeId, candidate.Url);
                        if (!String.IsNullOrWhiteSpace(objectPath))
                            hydration = ReadMetadataHydration(objectPath, candidate.Occurrence, candidate.Url);
                    }
                    if (hydration == null)
                    {
                        string permanentMarker = Path.Combine(_cacheRoot, "status", "track-" + candidate.Occurrence.ToString(CultureInfo.InvariantCulture) + ".audio.permanent");
                        if (File.Exists(permanentMarker))
                        {
                            hydration = new MetadataHydration
                            {
                                Occurrence = candidate.Occurrence,
                                YoutubeId = candidate.YoutubeId,
                                Title = "Unavailable video",
                                Channel = "",
                                Duration = 0,
                                Url = candidate.Url
                            };
                        }
                    }
                    if (hydration != null) hydrations.Add(hydration);
                }
                MetadataHydration[] hydrationArray = hydrations.ToArray();
                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive ||
                        !String.Equals(_sessionId, sessionId, StringComparison.Ordinal))
                    {
                        _metadataCacheSweepActive = false;
                        return;
                    }
                    if (hydrationArray.Length == 0)
                    {
                        _metadataCacheSweepActive = false;
                        StartBulkMetadataPrefetchIfUseful();
                        return;
                    }
                    ApplyMetadataCacheHydrationSlice(sessionId, generation, hydrationArray, 0);
                });
            });
        }

        private void ApplyMetadataCacheHydrationSlice(string sessionId, int generation, MetadataHydration[] hydrations, int offset)
        {
            if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive ||
                !String.Equals(_sessionId, sessionId, StringComparison.Ordinal) || hydrations == null)
            {
                _metadataCacheSweepActive = false;
                return;
            }
            int start = Math.Max(0, offset);
            int end = Math.Min(hydrations.Length, start + MetadataBulkApplySlice);
            if (start == 0 && hydrations.Length > 0) QueueMetadataCacheWrites(hydrations);
            var dirty = new HashSet<int>();
            for (int i = start; i < end; i++)
            {
                MetadataHydration hydration = hydrations[i];
                if (hydration != null && ApplyMetadataHydration(hydration)) dirty.Add(hydration.Occurrence);
            }
            bool finalSlice = end >= hydrations.Length;
            if (dirty.Count > 0) UpdateQueueRows(dirty, !finalSlice);
            if (!finalSlice)
            {
                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    ApplyMetadataCacheHydrationSlice(sessionId, generation, hydrations, end);
                });
                return;
            }
            _metadataCacheSweepActive = false;
            UpdateStatusBarProjection();
            UpdateNextUpUi();
            TrackMeta current;
            if (_currentOccurrence > 0 && _trackMeta.TryGetValue(_currentOccurrence, out current) && current != null)
            {
                _titleText.Text = current.Title;
                _channelText.Text = current.Channel ?? "";
                RefreshNowPlayingSelectableText();
            }
            StartBulkMetadataPrefetchIfUseful();
        }

        private static string YoutubePlaylistIdFromUrl(string raw)
        {
            if (String.IsNullOrWhiteSpace(raw)) return "";
            try
            {
                Uri uri;
                if (!Uri.TryCreate(raw.Trim(), UriKind.Absolute, out uri)) return "";
                string query = (uri.Query ?? "").TrimStart('?');
                foreach (string part in query.Split('&'))
                {
                    if (String.IsNullOrWhiteSpace(part)) continue;
                    int eq = part.IndexOf('=');
                    string key = eq >= 0 ? part.Substring(0, eq) : part;
                    if (!String.Equals(Uri.UnescapeDataString(key), "list", StringComparison.OrdinalIgnoreCase)) continue;
                    string value = eq >= 0 ? Uri.UnescapeDataString(part.Substring(eq + 1)) : "";
                    return (value ?? "").Trim();
                }
            }
            catch { }
            return "";
        }

        private bool TryResolveBulkMetadataSource(Dictionary<string, object> config, out string source, out bool sourceIsBatchFile)
        {
            source = GetString(config, "playlist", "").Trim();
            sourceIsBatchFile = false;
            if (!String.IsNullOrWhiteSpace(source))
            {
                string localCandidate = source;
                try
                {
                    if (!Path.IsPathRooted(localCandidate)) localCandidate = Path.Combine(_dataRoot, localCandidate);
                }
                catch { localCandidate = source; }
                if (File.Exists(localCandidate))
                {
                    source = localCandidate;
                    sourceIsBatchFile = true;
                    return true;
                }
                if (!source.StartsWith("http://", StringComparison.OrdinalIgnoreCase) && !source.StartsWith("https://", StringComparison.OrdinalIgnoreCase))
                    source = "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(source);
                return true;
            }

            // Direct playlist.txt often contains watch URLs that still carry the originating
            // YouTube list= id. Recover the dominant list and restore the old one-request bulk
            // path even when config.json no longer retains its historical playlist field.
            var listCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            foreach (TrackMeta meta in _trackMeta.Values)
            {
                if (meta == null || String.IsNullOrWhiteSpace(meta.Url)) continue;
                string listId = YoutubePlaylistIdFromUrl(meta.Url);
                if (String.IsNullOrWhiteSpace(listId)) continue;
                int count;
                listCounts.TryGetValue(listId, out count);
                listCounts[listId] = count + 1;
            }
            if (listCounts.Count > 0)
            {
                KeyValuePair<string, int> best = listCounts.OrderByDescending(pair => pair.Value).First();
                int denominator = Math.Max(1, _trackMeta.Count);
                if (best.Value >= 8 && best.Value * 2 >= denominator)
                {
                    source = "https://www.youtube.com/playlist?list=" + Uri.EscapeDataString(best.Key);
                    return true;
                }
            }

            // Mixed/direct URL lists have no single playlist id. yt-dlp's batch-file mode is the
            // correct fallback; unlike treating the file path as a playlist id, it actually reads
            // each URL from playlist.txt.
            if (File.Exists(DirectPlaylistPath))
            {
                source = DirectPlaylistPath;
                sourceIsBatchFile = true;
                return true;
            }
            return false;
        }

        private void StartBulkMetadataPrefetchIfUseful()
        {
            if (_metadataCacheSweepActive || _metadataBulkActive || String.IsNullOrWhiteSpace(_sessionId) || String.Equals(_metadataBulkSessionId, _sessionId, StringComparison.Ordinal)) return;
            if (_clock.ElapsedMilliseconds < _metadataBulkRetryAfterMs) return;

            // Do not poison a session as "metadata complete" from the first one-track startup
            // snapshot. Wait until the session/playlist model has actually reached the expected
            // occurrence count, then hydrate the complete placeholder set in one bulk pass.
            Dictionary<string, object> metadataSession = ReadJsonCached(Path.Combine(_stateRoot, "session.json"));
            int expectedMetadataCount = ExpectedQueueEntryCount(metadataSession);
            if (expectedMetadataCount > 0 && _trackMeta.Count < expectedMetadataCount) return;

            bool needsMetadata = _trackMeta.Any(pair => pair.Value != null && IsPlaceholderTrackTitle(pair.Value.Title, pair.Key));
            if (!needsMetadata)
            {
                _metadataBulkSessionId = _sessionId;
                _metadataBulkRetryAfterMs = 0;
                return;
            }

            MetadataBulkCandidate[] candidates = _trackMeta
                .Where(pair => pair.Value != null && IsPlaceholderTrackTitle(pair.Value.Title, pair.Key))
                .OrderBy(pair => pair.Key)
                .Select(pair => new MetadataBulkCandidate
                {
                    Occurrence = pair.Key,
                    YoutubeId = !String.IsNullOrWhiteSpace(pair.Value.YoutubeId) ? pair.Value.YoutubeId : YoutubeIdFromUrl(pair.Value.Url),
                    Url = pair.Value.Url ?? "",
                    SourceIndex = pair.Value.SourceIndex
                }).ToArray();
            if (candidates.Length == 0) { _metadataBulkRetryAfterMs = _clock.ElapsedMilliseconds + 5000; return; }
            int totalPendingCandidates = candidates.Length;

            Dictionary<string, object> config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            string source = "";
            bool sourceIsBatchFile = false;
            string transientBatchPath = "";
            bool authoritativeTailBatch = false;
            try
            {
                // R61.106.49: once any portion of the queue has resolved, the remaining rows
                // must be checked against the LOCAL queue URLs, not only the current remote
                // playlist. A remote playlist may have dropped perfectly valid old entries,
                // which was the source of the permanent ~420-item plateau.
                if (candidates.Length < _trackMeta.Count && candidates.All(candidate => !String.IsNullOrWhiteSpace(candidate.Url)))
                {
                    // Never make the unresolved tail one giant all-or-nothing subprocess. Rotate
                    // through small direct-URL chunks so a pathological/dead URL cannot hold the
                    // other pending rows hostage behind one global timeout.
                    int chunkCount = Math.Min(MetadataTailBatchSize, candidates.Length);
                    int start = candidates.Length > 0 ? Math.Abs(_metadataTailCursor % candidates.Length) : 0;
                    var chunk = new List<MetadataBulkCandidate>(chunkCount);
                    for (int j = 0; j < chunkCount; j++) chunk.Add(candidates[(start + j) % candidates.Length]);
                    candidates = chunk.ToArray();
                    _metadataTailCursor = totalPendingCandidates > 0 ? (start + chunkCount) % totalPendingCandidates : 0;

                    string tempRoot = Path.Combine(_dataRoot, "updates", "metadata-tail");
                    Directory.CreateDirectory(tempRoot);
                    transientBatchPath = Path.Combine(tempRoot, "unresolved-" + Guid.NewGuid().ToString("N") + ".txt");
                    File.WriteAllLines(transientBatchPath, candidates.Select(candidate => candidate.Url).ToArray(), new UTF8Encoding(false));
                    source = transientBatchPath;
                    sourceIsBatchFile = true;
                    authoritativeTailBatch = true;
                    WriteControllerPerformanceLogAsync("METADATA TAIL START pending=" + totalPendingCandidates.ToString(CultureInfo.InvariantCulture) +
                        " chunk=" + candidates.Length.ToString(CultureInfo.InvariantCulture) +
                        " start=" + start.ToString(CultureInfo.InvariantCulture));
                }
            }
            catch
            {
                transientBatchPath = "";
                authoritativeTailBatch = false;
            }
            if (String.IsNullOrWhiteSpace(source) && !TryResolveBulkMetadataSource(config, out source, out sourceIsBatchFile))
            {
                _metadataBulkRetryAfterMs = _clock.ElapsedMilliseconds + 5000;
                try { if (!String.IsNullOrWhiteSpace(transientBatchPath) && File.Exists(transientBatchPath)) File.Delete(transientBatchPath); } catch { }
                return;
            }

            string sessionId = _sessionId;
            int bulkGeneration = Volatile.Read(ref _metadataBulkGeneration);
            _metadataBulkActive = true;
            _metadataBulkRetryAfterMs = 0;
            ThreadPool.QueueUserWorkItem(delegate
            {
                var lines = new List<string>();
                var stderrLines = new List<string>();
                bool completed = false;
                bool processExited = false;
                int exitCode = Int32.MinValue;
                bool timedOut = false;
                try
                {
                    string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
                    if (File.Exists(yt) && bulkGeneration == Volatile.Read(ref _metadataBulkGeneration) && !_shutdownRequested && !_slotSwitchActive)
                    {
                        string args = authoritativeTailBatch
                            ? ("--no-playlist --ignore-errors --quiet --no-warnings --dump-json --socket-timeout 6 --retries 0 --fragment-retries 0 --extractor-retries 0 --cache-dir " + Quote(YtDlpCacheDirectory()))
                            : ("--flat-playlist --ignore-errors --quiet --no-warnings --dump-json --cache-dir " + Quote(YtDlpCacheDirectory()));
                        string deno = Path.Combine(_runtimeRoot, "deno", "deno.exe");
                        if (File.Exists(deno)) args += " --js-runtimes " + Quote("deno:" + deno);
                        args += sourceIsBatchFile ? (" --batch-file " + Quote(source)) : (" " + Quote(source));
                        var psi = new ProcessStartInfo
                        {
                            FileName = yt,
                            Arguments = args,
                            WorkingDirectory = _dataRoot,
                            UseShellExecute = false,
                            CreateNoWindow = true,
                            WindowStyle = ProcessWindowStyle.Hidden,
                            RedirectStandardOutput = true,
                            RedirectStandardError = true
                        };
                        ConfigureYtDlpProcessStartInfo(psi);
                        using (Process proc = new Process { StartInfo = psi })
                        {
                            proc.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e)
                            {
                                if (!String.IsNullOrWhiteSpace(e.Data)) lock (lines) lines.Add(e.Data);
                            };
                            proc.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e)
                            {
                                if (!String.IsNullOrWhiteSpace(e.Data)) lock (stderrLines) stderrLines.Add(e.Data);
                            };
                            if (proc.Start())
                            {
                                try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                                proc.BeginOutputReadLine();
                                proc.BeginErrorReadLine();
                                int ceilingMs = authoritativeTailBatch ? 45000 : 120000;
                                Stopwatch wait = Stopwatch.StartNew();
                                while (!proc.HasExited && wait.ElapsedMilliseconds < ceilingMs &&
                                       bulkGeneration == Volatile.Read(ref _metadataBulkGeneration) &&
                                       !_shutdownRequested && !_slotSwitchActive)
                                    Thread.Sleep(250);
                                if (!proc.HasExited)
                                {
                                    timedOut = true;
                                    try { proc.Kill(); } catch { }
                                    try { proc.WaitForExit(); } catch { }
                                    try { processExited = proc.HasExited; if (processExited) exitCode = proc.ExitCode; } catch { }
                                }
                                else
                                {
                                    processExited = true;
                                    try { exitCode = proc.ExitCode; } catch { exitCode = Int32.MinValue; }
                                    completed = authoritativeTailBatch ? true : exitCode == 0;
                                    try { proc.WaitForExit(); } catch { }
                                }
                            }
                        }
                    }
                }
                catch { completed = false; }
                if (bulkGeneration != Volatile.Read(ref _metadataBulkGeneration) || _shutdownRequested || _slotSwitchActive)
                    return;

                string[] stderrSnapshot; lock (stderrLines) stderrSnapshot = stderrLines.ToArray();
                bool invocationFailure = stderrSnapshot.Any(line =>
                    line.IndexOf("no such option", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    line.IndexOf("Usage:", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    line.IndexOf("Traceback (most recent call last)", StringComparison.OrdinalIgnoreCase) >= 0 ||
                    line.IndexOf("is not recognized as an internal or external command", StringComparison.OrdinalIgnoreCase) >= 0);
                bool authoritativeCompleted = authoritativeTailBatch && processExited && !timedOut && !invocationFailure;

                var entries = new List<Dictionary<string, object>>();
                if (completed || lines.Count > 0)
                {
                    var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                    string[] snapshot; lock (lines) snapshot = lines.ToArray();
                    foreach (string line in snapshot)
                    {
                        try
                        {
                            Dictionary<string, object> entry = AsMap(serializer.DeserializeObject(line));
                            if (entry.Count > 0) entries.Add(entry);
                        }
                        catch { }
                    }
                }

                var hydrations = new List<MetadataHydration>();
                var byId = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
                var byUrl = new Dictionary<string, Dictionary<string, object>>(StringComparer.OrdinalIgnoreCase);
                var bySourceIndex = new Dictionary<int, Dictionary<string, object>>();
                int sourceIndex = 0;
                foreach (Dictionary<string, object> entry in entries)
                {
                    string id = GetString(entry, "id", "").Trim();
                    string url = GetString(entry, "webpage_url", GetString(entry, "url", "")).Trim();
                    if (!url.StartsWith("http://", StringComparison.OrdinalIgnoreCase) && !url.StartsWith("https://", StringComparison.OrdinalIgnoreCase) && id.Length > 0)
                        url = "https://www.youtube.com/watch?v=" + id;
                    if (id.Length == 0 && url.Length == 0) continue;
                    sourceIndex++;
                    bySourceIndex[sourceIndex] = entry;
                    if (id.Length > 0 && !byId.ContainsKey(id)) byId[id] = entry;
                    if (url.Length > 0 && !byUrl.ContainsKey(url)) byUrl[url] = entry;
                }

                // Always walk the submitted candidates, even when yt-dlp emitted zero JSON rows.
                // A completed authoritative direct-URL scan with zero output is precisely how a
                // chunk made entirely of deleted/private/unavailable videos can look; treating
                // entries.Count==0 as "nothing happened" was the source of the permanent 420-pending plateau.
                foreach (MetadataBulkCandidate candidate in candidates)
                {
                    Dictionary<string, object> entry = null;
                    if (candidate.YoutubeId.Length > 0) byId.TryGetValue(candidate.YoutubeId, out entry);
                    if (entry == null && candidate.Url.Length > 0) byUrl.TryGetValue(candidate.Url, out entry);
                    if (entry == null && candidate.SourceIndex > 0) bySourceIndex.TryGetValue(candidate.SourceIndex, out entry);
                    if (entry == null)
                    {
                        if (authoritativeCompleted)
                        {
                            // A completed direct metadata probe is terminal for STARTUP METADATA,
                            // but a non-zero yt-dlp exit is not proof that audio itself is dead.
                            // Keep that distinction explicit so the loading bar can finish without
                            // teaching transport to skip a track that may still play on demand.
                            hydrations.Add(new MetadataHydration
                            {
                                Occurrence = candidate.Occurrence,
                                YoutubeId = candidate.YoutubeId,
                                Title = (exitCode == 0 || StderrConfirmsHardUnavailable(candidate, stderrSnapshot)) ? "Unavailable video" : "Metadata unavailable",
                                Channel = "",
                                Duration = 0,
                                Url = candidate.Url
                            });
                        }
                        continue;
                    }
                    string title = GetString(entry, "title", "").Trim();
                    if (title.Length == 0) continue;
                    string id = GetString(entry, "id", "").Trim();
                    hydrations.Add(new MetadataHydration
                    {
                        Occurrence = candidate.Occurrence,
                        YoutubeId = candidate.YoutubeId.Length > 0 ? candidate.YoutubeId : id,
                        Title = title,
                        Channel = GetString(entry, "channel", GetString(entry, "uploader", "")),
                        Duration = GetDouble(entry, "duration", 0),
                        Url = candidate.Url
                    });
                }

                MetadataHydration[] hydrationArray = hydrations.ToArray();
                if (authoritativeTailBatch)
                {
                    int stderrCount = stderrSnapshot.Length;
                    WriteControllerPerformanceLogAsync("METADATA TAIL RESULT pending=" + totalPendingCandidates.ToString(CultureInfo.InvariantCulture) +
                        " chunk=" + candidates.Length.ToString(CultureInfo.InvariantCulture) +
                        " output=" + entries.Count.ToString(CultureInfo.InvariantCulture) +
                        " hydrated=" + hydrationArray.Length.ToString(CultureInfo.InvariantCulture) +
                        " completed=" + (authoritativeCompleted ? "1" : "0") +
                        " exit=" + exitCode.ToString(CultureInfo.InvariantCulture) +
                        " timeout=" + (timedOut ? "1" : "0") +
                        " invoke_fail=" + (invocationFailure ? "1" : "0") +
                        " stderr_lines=" + stderrCount.ToString(CultureInfo.InvariantCulture));
                    if (stderrSnapshot.Length > 0)
                    {
                        string sample = String.Join(" | ", stderrSnapshot.Take(2).Select(line => (line ?? "").Replace("\r", " ").Replace("\n", " ").Trim()).ToArray());
                        if (sample.Length > 480) sample = sample.Substring(0, 480);
                        WriteControllerPerformanceLogAsync("METADATA TAIL STDERR " + sample);
                    }
                }
                try { if (!String.IsNullOrWhiteSpace(transientBatchPath) && File.Exists(transientBatchPath)) File.Delete(transientBatchPath); } catch { }
                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    if (bulkGeneration != Volatile.Read(ref _metadataBulkGeneration) || _shutdownRequested || _slotSwitchActive ||
                        !String.Equals(_sessionId, sessionId, StringComparison.Ordinal))
                    {
                        if (bulkGeneration == Volatile.Read(ref _metadataBulkGeneration)) _metadataBulkActive = false;
                        return;
                    }
                    if (hydrationArray.Length == 0)
                    {
                        _metadataBulkActive = false;
                        _metadataBulkRetryAfterMs = _clock.ElapsedMilliseconds + 5000;
                        UpdateStatusBarProjection();
                        return;
                    }
                    ApplyBulkMetadataHydrationSlice(sessionId, bulkGeneration, hydrationArray, 0);
                });
            });
        }

        private void ApplyBulkMetadataHydrationSlice(string sessionId, int bulkGeneration, MetadataHydration[] hydrations, int offset)
        {
            if (bulkGeneration != Volatile.Read(ref _metadataBulkGeneration) || _shutdownRequested || _slotSwitchActive ||
                !String.Equals(_sessionId, sessionId, StringComparison.Ordinal) || hydrations == null)
            {
                if (bulkGeneration == Volatile.Read(ref _metadataBulkGeneration)) _metadataBulkActive = false;
                return;
            }
            int start = Math.Max(0, offset);
            int end = Math.Min(hydrations.Length, start + MetadataBulkApplySlice);
            if (start == 0 && hydrations.Length > 0) QueueMetadataCacheWrites(hydrations);
            var dirty = new HashSet<int>();
            for (int i = start; i < end; i++)
            {
                MetadataHydration hydration = hydrations[i];
                TrackMeta live;
                if (hydration != null && _trackMeta.TryGetValue(hydration.Occurrence, out live) && live != null &&
                    String.Equals((live.Url ?? "").Trim(), (hydration.Url ?? "").Trim(), StringComparison.OrdinalIgnoreCase) &&
                    ApplyMetadataHydration(hydration)) dirty.Add(hydration.Occurrence);
            }
            bool finalSlice = end >= hydrations.Length;
            if (dirty.Count > 0) UpdateQueueRows(dirty, !finalSlice);
            if (dirty.Count > 0) UpdateStatusBarProjection();

            if (!finalSlice)
            {
                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    ApplyBulkMetadataHydrationSlice(sessionId, bulkGeneration, hydrations, end);
                });
                return;
            }

            _metadataBulkActive = false;
            bool metadataComplete = !_trackMeta.Any(pair => pair.Value != null && IsPlaceholderTrackTitle(pair.Value.Title, pair.Key));
            _metadataBulkSessionId = metadataComplete ? sessionId : "";
            _metadataBulkRetryAfterMs = metadataComplete ? 0 : (_clock.ElapsedMilliseconds + 1500);
            UpdateStatusBarProjection();
            UpdateNextUpUi();
            TrackMeta current;
            if (_currentOccurrence > 0 && _trackMeta.TryGetValue(_currentOccurrence, out current) && current != null)
            {
                _titleText.Text = current.Title ?? "";
                _channelText.Text = current.Channel ?? "";
                RefreshNowPlayingSelectableText();
            }
            WriteControllerPerformanceLogAsync("METADATA BULK HYDRATION rows=" + hydrations.Length.ToString(CultureInfo.InvariantCulture) +
                " slice=" + MetadataBulkApplySlice.ToString(CultureInfo.InvariantCulture) +
                " complete=" + (metadataComplete ? "1" : "0"));
            if (!metadataComplete) ScheduleMetadataAhead();
        }

        private void PumpMetadataPrefetch()
        {
            while (true)
            {
                int occurrence = 0;
                string url = "";
                lock (_metadataPrefetchQueue)
                {
                    if (_metadataPrefetchActive >= MetadataPrefetchWorkers || (_metadataUrgentQueue.Count == 0 && _metadataPrefetchQueue.Count == 0)) return;
                    occurrence = _metadataUrgentQueue.Count > 0 ? _metadataUrgentQueue.Dequeue() : _metadataPrefetchQueue.Dequeue();
                    TrackMeta meta;
                    if (!_trackMeta.TryGetValue(occurrence, out meta) || meta == null || String.IsNullOrWhiteSpace(meta.Url) ||
                        !IsPlaceholderTrackTitle(meta.Title, occurrence) || (_metadataBulkActive && occurrence != _currentOccurrence))
                    {
                        // Re-check immediately before process creation. A queued row may already
                        // have been hydrated by the bulk result while it was waiting.
                        _metadataPrefetchPending.Remove(occurrence);
                        continue;
                    }
                    url = meta.Url;
                    _metadataPrefetchActive++;
                }
                StartMetadataPrefetchWorker(occurrence, url);
            }
        }

        private void StartMetadataPrefetchWorker(int occurrence, string url)
        {
            int generation = Volatile.Read(ref _metadataGeneration);
            string expectedUrl = (url ?? "").Trim();
            ThreadPool.QueueUserWorkItem(delegate
            {
                bool success = false;
                bool permanentSourceKnown = false;
                string tempInfo = "";
                MetadataHydration hydration = null;
                try
                {
                    if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive) return;
                    hydration = ReadMetadataHydration(MetadataCachePath(occurrence), occurrence, expectedUrl);
                    success = hydration != null;
                    if (!success)
                    {
                        string permanentMarker = Path.Combine(_cacheRoot, "status", "track-" + occurrence.ToString(CultureInfo.InvariantCulture) + ".audio.permanent");
                        permanentSourceKnown = File.Exists(permanentMarker);
                        if (permanentSourceKnown)
                        {
                            hydration = new MetadataHydration
                            {
                                Occurrence = occurrence,
                                YoutubeId = YoutubeIdFromUrl(expectedUrl),
                                Title = "Unavailable video",
                                Channel = "",
                                Duration = 0,
                                Url = expectedUrl
                            };
                            success = true;
                            WriteControllerPerformanceLogAsync("METADATA RESOLVE PERMANENT track=" + occurrence.ToString(CultureInfo.InvariantCulture) + " label=Unavailable video");
                        }
                        else
                        {
                            string yt = Path.Combine(_runtimeRoot, "yt-dlp", "yt-dlp.exe");
                            if (!File.Exists(yt)) return;
                            string metaDir = Path.Combine(_cacheRoot, "meta");
                            Directory.CreateDirectory(metaDir);
                            string prefix = "track-" + occurrence.ToString(CultureInfo.InvariantCulture) + ".controller";
                            string template = Path.Combine(metaDir, prefix + ".%(ext)s");
                            tempInfo = Path.Combine(metaDir, prefix + ".info.json");
                            try { if (File.Exists(tempInfo)) File.Delete(tempInfo); } catch { }
                            string args = "--no-playlist --quiet --no-warnings --socket-timeout 15 --retries 1 --skip-download --write-info-json --no-part --cache-dir " + Quote(YtDlpCacheDirectory()) + " --output " + Quote(template) + " " + Quote(expectedUrl);
                            var psi = new ProcessStartInfo
                            {
                                FileName = yt, Arguments = args, WorkingDirectory = metaDir,
                                UseShellExecute = false, CreateNoWindow = true, WindowStyle = ProcessWindowStyle.Hidden
                            };
                            ConfigureYtDlpProcessStartInfo(psi);
                            using (Process proc = Process.Start(psi))
                            {
                                if (proc != null)
                                {
                                    try { proc.PriorityClass = ProcessPriorityClass.BelowNormal; } catch { }
                                    Stopwatch wait = Stopwatch.StartNew();
                                    while (!proc.HasExited && wait.ElapsedMilliseconds < 30000 &&
                                           generation == Volatile.Read(ref _metadataGeneration) &&
                                           !_shutdownRequested && !_slotSwitchActive)
                                        Thread.Sleep(250);
                                    if (!proc.HasExited) { try { proc.Kill(); } catch { } }
                                    else success = proc.ExitCode == 0 && File.Exists(tempInfo);
                                }
                            }
                            if (success && generation == Volatile.Read(ref _metadataGeneration) && !_shutdownRequested && !_slotSwitchActive)
                            {
                                string canonical = MetadataCachePath(occurrence);
                                try { File.Copy(tempInfo, canonical, true); }
                                catch { success = false; }
                                if (success) hydration = ReadMetadataHydration(canonical, occurrence, expectedUrl);
                                success = hydration != null;
                            }
                        }
                    }
                }
                catch { success = false; hydration = null; }
                finally
                {
                    try { if (tempInfo.Length > 0 && File.Exists(tempInfo)) File.Delete(tempInfo); } catch { }
                    MetadataHydration result = hydration;
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        bool currentGeneration = generation == Volatile.Read(ref _metadataGeneration);
                        lock (_metadataPrefetchQueue)
                        {
                            _metadataPrefetchActive = Math.Max(0, _metadataPrefetchActive - 1);
                            if (currentGeneration) _metadataPrefetchPending.Remove(occurrence);
                        }
                        if (!currentGeneration || _shutdownRequested || _slotSwitchActive)
                        {
                            PumpMetadataPrefetch();
                            return;
                        }
                        TrackMeta live;
                        if (!_trackMeta.TryGetValue(occurrence, out live) || live == null ||
                            !String.Equals((live.Url ?? "").Trim(), expectedUrl, StringComparison.OrdinalIgnoreCase))
                        {
                            PumpMetadataPrefetch();
                            return;
                        }
                        if (success && result != null &&
                            String.Equals((result.Url ?? "").Trim(), expectedUrl, StringComparison.OrdinalIgnoreCase) &&
                            ApplyMetadataHydration(result))
                        {
                            _metadataPrefetchRetryAfterMs.Remove(occurrence);
                            UpdateQueueRows(new HashSet<int>(new[] { occurrence }));
                            UpdateStatusBarProjection();
                            UpdateNextUpUi();
                            if (occurrence == _currentOccurrence)
                            {
                                TrackMeta meta;
                                if (_trackMeta.TryGetValue(occurrence, out meta) && meta != null)
                                {
                                    _titleText.Text = meta.Title;
                                    _channelText.Text = meta.Channel ?? "";
                                    RefreshNowPlayingSelectableText();
                                }
                            }
                        }
                        else _metadataPrefetchRetryAfterMs[occurrence] = _clock.ElapsedMilliseconds + (permanentSourceKnown ? 21600000 : 60000);
                        PumpMetadataPrefetch();
                    });
                }
            });
        }

        private MetadataHydration ReadMetadataHydration(string path, int occurrence, string expectedUrl)
        {
            try
            {
                if (!File.Exists(path)) return null;
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                Dictionary<string, object> map = AsMap(serializer.DeserializeObject(ReadTextShared(path)));
                if (map.Count == 0) return null;
                string expected = YoutubeIdFromUrl(expectedUrl);
                string observed = GetString(map, "id", "");
                if (expected.Length > 0 && observed.Length > 0 && !String.Equals(expected, observed, StringComparison.OrdinalIgnoreCase)) return null;
                string title = GetString(map, "title", "").Trim();
                if (title.Length == 0 || !MetadataTerminalCacheFresh(map, title, path)) return null;
                return new MetadataHydration
                {
                    Occurrence = occurrence, YoutubeId = observed, Title = title,
                    Channel = GetString(map, "channel", GetString(map, "uploader", "")),
                    Duration = GetDouble(map, "duration", 0), Url = expectedUrl ?? ""
                };
            }
            catch { return null; }
        }

        private bool ApplyMetadataHydration(MetadataHydration hydration)
        {
            if (hydration == null || hydration.Occurrence <= 0) return false;
            TrackMeta meta;
            if (!_trackMeta.TryGetValue(hydration.Occurrence, out meta) || meta == null) return false;
            if (String.IsNullOrWhiteSpace(hydration.Title)) return false;
            meta.Title = hydration.Title;
            if (!String.IsNullOrWhiteSpace(hydration.Channel)) meta.Channel = hydration.Channel;
            if (hydration.Duration > 0) meta.Duration = hydration.Duration;
            if (String.IsNullOrWhiteSpace(meta.YoutubeId) && !String.IsNullOrWhiteSpace(hydration.YoutubeId)) meta.YoutubeId = hydration.YoutubeId;
            return true;
        }

        private void QueueMetadataCacheWrites(MetadataHydration[] writes)
        {
            if (writes == null || writes.Length == 0) return;
            int generation = Volatile.Read(ref _metadataGeneration);
            MetadataHydration[] snapshot = writes.Where(write => write != null && write.Occurrence > 0).ToArray();
            if (snapshot.Length == 0) return;
            var authorizedSources = new Dictionary<int, string>();
            foreach (MetadataHydration write in snapshot)
            {
                TrackMeta live;
                if (_trackMeta.TryGetValue(write.Occurrence, out live) && live != null)
                    authorizedSources[write.Occurrence] = (live.Url ?? "").Trim();
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try
                {
                    if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive) return;
                    Directory.CreateDirectory(Path.Combine(_cacheRoot, "meta"));
                    Directory.CreateDirectory(Path.Combine(_cacheRoot, "objects", "meta"));
                    var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                    foreach (MetadataHydration write in snapshot)
                    {
                        if (generation != Volatile.Read(ref _metadataGeneration) || _shutdownRequested || _slotSwitchActive) return;
                        string authorized;
                        if (!authorizedSources.TryGetValue(write.Occurrence, out authorized) ||
                            !String.Equals((write.Url ?? "").Trim(), authorized, StringComparison.OrdinalIgnoreCase)) continue;
                        try
                        {
                            var cache = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                            {
                                { "id", write.YoutubeId ?? "" }, { "title", write.Title ?? "" }, { "channel", write.Channel ?? "" },
                                { "uploader", write.Channel ?? "" }, { "duration", write.Duration }, { "webpage_url", write.Url ?? "" },
                                { "checked_utc", DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture) }
                            };
                            string serialized = serializer.Serialize(cache);
                            WriteUtf8NoBom(MetadataCachePath(write.Occurrence), serialized);
                            string objectPath = MetadataObjectCachePath(write.YoutubeId, write.Url);
                            if (!String.IsNullOrWhiteSpace(objectPath)) WriteUtf8NoBom(objectPath, serialized);
                        }
                        catch { }
                    }
                }
                catch { }
            });
        }

        private Dictionary<int, RuntimeQueueItem> BuildRuntimeQueueProjection(Dictionary<string, object> queueState)
        {
            var projection = new Dictionary<int, RuntimeQueueItem>();
            foreach (var raw in GetList(queueState, "items"))
            {
                var map = AsMap(raw);
                int occ = GetInt(map, "index", 0);
                if (occ <= 0) continue;
                projection[occ] = RuntimeQueueItem.From(map);
            }
            return projection;
        }

        private void ApplyRuntimeQueueProjection(Dictionary<int, RuntimeQueueItem> projection, HashSet<int> dirty)
        {
            if (projection == null) projection = new Dictionary<int, RuntimeQueueItem>();
            if (dirty == null) dirty = new HashSet<int>();
            int currentOrderIndex = -1;
            if (_currentOccurrence > 0)
            {
                int mappedCurrentIndex;
                if (_orderIndexByOccurrence.TryGetValue(_currentOccurrence, out mappedCurrentIndex)) currentOrderIndex = mappedCurrentIndex;
            }
            foreach (var pair in projection)
            {
                RuntimeQueueItem previous;
                int pairOrderIndex;
                bool timingSensitive = currentOrderIndex < 0 || !_orderIndexByOccurrence.TryGetValue(pair.Key, out pairOrderIndex) || Math.Abs(pairOrderIndex - currentOrderIndex) <= 24;
                if (!_runtimeQueue.TryGetValue(pair.Key, out previous) || !pair.Value.ProjectionEquals(previous, timingSensitive)) dirty.Add(pair.Key);
            }
            foreach (int previousOccurrence in _runtimeQueue.Keys)
                if (!projection.ContainsKey(previousOccurrence)) dirty.Add(previousOccurrence);
            _runtimeQueue.Clear();
            foreach (var pair in projection) _runtimeQueue[pair.Key] = pair.Value;
        }

        private void QueueRuntimeQueueProjection(Dictionary<string, object> evidence)
        {
            if (evidence == null) return;
            lock (_runtimeQueueProjectionSync)
            {
                _pendingRuntimeQueueProjectionEvidence = evidence;
                if (_runtimeQueueProjectionWorkerActive) return;
                _runtimeQueueProjectionWorkerActive = true;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainRuntimeQueueProjection(); });
        }

        private void DrainRuntimeQueueProjection()
        {
            try
            {
                while (true)
                {
                    Dictionary<string, object> evidence;
                    lock (_runtimeQueueProjectionSync)
                    {
                        evidence = _pendingRuntimeQueueProjectionEvidence;
                        _pendingRuntimeQueueProjectionEvidence = null;
                    }
                    if (evidence == null) break;
                    Dictionary<int, RuntimeQueueItem> projection = BuildRuntimeQueueProjection(evidence);
                    try
                    {
                        TryBeginInvokeUi(DispatcherPriority.Background, delegate
                        {
                            if (_disposed || !Object.ReferenceEquals(evidence, _lastQueueRuntimeSnapshot)) return;
                            var dirty = new HashSet<int>();
                            ApplyRuntimeQueueProjection(projection, dirty);
                            // ApplyRuntimeQueueProjection already reports the occurrences whose
                            // runtime fields actually changed. Do not force the current row dirty on
                            // every queue-runtime write; that duplicate projection was the dominant
                            // recurring WPF queue cost in the R61.85 flight record.
                            if (dirty.Count > 0)
                                ApplyQueueRowsBudgeted(dirty, "runtime");
                        });
                    }
                    catch { }
                }
            }
            finally
            {
                lock (_runtimeQueueProjectionSync)
                {
                    _runtimeQueueProjectionWorkerActive = false;
                    if (_pendingRuntimeQueueProjectionEvidence != null)
                    {
                        _runtimeQueueProjectionWorkerActive = true;
                        ThreadPool.QueueUserWorkItem(delegate(object nested) { DrainRuntimeQueueProjection(); });
                    }
                }
            }
        }

        private void RefreshQueueState(bool force)
        {
            var session = ReadJsonCached(Path.Combine(_stateRoot, "session.json"));
            var orderState = ReadJsonCached(Path.Combine(_stateRoot, "session-order.json"));
            var queueState = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));

            bool queueEvidenceChanged = !Object.ReferenceEquals(session, _lastQueueSessionSnapshot) ||
                                        !Object.ReferenceEquals(orderState, _lastQueueOrderSnapshot) ||
                                        !Object.ReferenceEquals(queueState, _lastQueueRuntimeSnapshot);
            bool queueProjectionChanged = _lastQueueProjectedOccurrence != _currentOccurrence ||
                                          _lastQueueProjectedPaused != _paused ||
                                          _lastQueueProjectedAudioActive != _audioActive ||
                                          !String.Equals(_lastQueueProjectedPhase, _lastPlaybackPhase, StringComparison.Ordinal);

            // Metadata hydration has its own readiness layer. It must keep getting scheduling
            // opportunities even when the Queue/session/order files are otherwise stable.
            // R61.106.39 accidentally left this behind the evidence-change early return, which
            // could strand every row at Track #... forever after the one startup attempt.
            if (_trackMeta.Count > 0) ScheduleMetadataAhead();

            if (!force && !queueEvidenceChanged && !queueProjectionChanged)
                return;

            string sid = GetString(session, "session_id", "");
            if (sid.Length == 0)
                sid = GetString(orderState, "session_id", "");

            bool sessionChanged = !String.Equals(sid, _sessionId, StringComparison.Ordinal);
            bool sessionEvidenceChanged = !Object.ReferenceEquals(session, _lastQueueSessionSnapshot);
            int revision = GetInt(orderState, "revision", 0);
            int commandSerial = GetInt(orderState, "command_serial", 0);
            string commandStatus = GetString(orderState, "last_command_status", "");
            string commandReason = GetString(orderState, "last_command_reason", "");
            // R61.80: force means "re-read authoritative state", not "pretend structural state changed".
            // The old coupling caused every SafeRefresh(true) to reproject all ~2,800 rows on the
            // WPF UI thread even when the order revision was identical.
            bool orderChanged = sessionChanged || revision != _orderRevision;
            bool orderEvidenceChanged = !Object.ReferenceEquals(orderState, _lastQueueOrderSnapshot);
            List<int> desiredOrder = null;
            bool orderContentsChanged = false;
            if (orderChanged || orderEvidenceChanged)
            {
                desiredOrder = ParseOrder(orderState, session);
                orderContentsChanged = desiredOrder.Count != _order.Count || !desiredOrder.SequenceEqual(_order);
            }
            bool commandReceiptChanged = sessionChanged || commandSerial != _orderCommandSerial;

            if (sessionChanged || _trackMeta.Count == 0)
            {
                if (sessionChanged && _queuePlaybackSubsetActive)
                {
                    _queuePlaybackSubsetActive = false;
                    _queuePlaybackSubsetQuery = "";
                    _queuePlaybackSubsetCsv = "";
                    if (_queueSearchPlayButton != null)
                    {
                        _queueSearchPlayButton.Content = "Listen";
                        _queueSearchPlayButton.IsEnabled = _queueSearchBox != null && !String.IsNullOrWhiteSpace(_queueSearchBox.Text);
                    }
                }
                _sessionId = sid;
                LoadTrackMetadata(session, orderState);
            }
            else
            {
                if (sessionEvidenceChanged) MergeSessionMetadataEvidence(session);
                MergeInsertedMetadata(orderState);
            }

            var dirtyRuntimeRows = new HashSet<int>();
            bool runtimeEvidenceChanged = !Object.ReferenceEquals(queueState, _lastQueueRuntimeSnapshot);
            bool runtimeProjectionWasEmpty = _runtimeQueue.Count == 0;
            if (runtimeProjectionWasEmpty)
            {
                ApplyRuntimeQueueProjection(BuildRuntimeQueueProjection(queueState), dirtyRuntimeRows);
            }
            else if (runtimeEvidenceChanged)
            {
                // R61.86: runtime evidence is parsed/diffed on the worker. Do not also reproject
                // the current row synchronously before that worker has produced any new data.
                QueueRuntimeQueueProjection(queueState);
            }
            if (queueProjectionChanged || runtimeProjectionWasEmpty)
            {
                if (_lastQueueProjectedOccurrence > 0) dirtyRuntimeRows.Add(_lastQueueProjectedOccurrence);
                if (_currentOccurrence > 0) dirtyRuntimeRows.Add(_currentOccurrence);
            }

            int queueCurrent = GetInt(queueState, "current_index", 0);
            int queueSlot = GetInt(queueState, "current_order_slot", 0);
            if (_currentOccurrence <= 0 && queueCurrent > 0)
                _currentOccurrence = queueCurrent;
            if (_currentSlot <= 0 && queueSlot > 0)
                _currentSlot = queueSlot;

            if (orderChanged || orderContentsChanged)
            {
                // R61.106.52.9: revision is command semantics, not a safe content-version token.
                // Startup/order projection may grow while retaining the same revision. Compare the
                // actual order payload so an early partial snapshot (for example one viewport) can
                // never become the permanent Queue model.
                if (desiredOrder == null) desiredOrder = ParseOrder(orderState, session);
                SynchronizeQueueOrder(desiredOrder);
                _orderRevision = revision;
            }

            if (commandReceiptChanged)
            {
                _orderCommandSerial = commandSerial;
            }

            if (_pendingOrderMutationSerial >= 0 && commandSerial > _pendingOrderMutationSerial)
            {
                string detail = String.IsNullOrWhiteSpace(_pendingOrderMutationDescription)
                    ? "authoritative queue command"
                    : _pendingOrderMutationDescription;
                if (String.Equals(commandStatus, "committed", StringComparison.OrdinalIgnoreCase))
                {
                    AddActivity("Queue committed", "R" + revision.ToString(CultureInfo.InvariantCulture) + " | " + detail);
                    ShowToast("Queue updated", "The queue order was updated.");
                }
                else if (String.Equals(commandStatus, "no-op", StringComparison.OrdinalIgnoreCase))
                {
                    AddActivity("Queue unchanged", detail + " | " + commandReason);
                    ShowToast("Queue unchanged", "The engine confirmed that no order change was needed.");
                }
                else
                {
                    AddActivity("Queue rejected", detail + " | " + commandReason);
                    ShowToast("Queue change refused", "The engine rejected the requested order change.");
                }
                ClearPendingOrderMutation();
            }

            if (_queueOpen && _queueUiMaterializationActive && _queueRows.Count < _order.Count &&
                _queueUiMaterializationLastProgressMs > 0 &&
                _clock.ElapsedMilliseconds - _queueUiMaterializationLastProgressMs >= QueueMaterializationWatchdogMs)
            {
                WriteControllerPerformanceLogAsync("QUEUE UI MATERIALIZE WATCHDOG rows=" + _queueRows.Count.ToString(CultureInfo.InvariantCulture) +
                    " target=" + _order.Count.ToString(CultureInfo.InvariantCulture) +
                    " remaining=" + _queueUiMaterializationRemaining.ToString(CultureInfo.InvariantCulture));
                _queueUiMaterializationGeneration++;
                _queueUiMaterializationActive = false;
                _queueUiOrderDirty = true;
                BeginQueueUiMaterialization("watchdog");
            }

            bool queueUiReady = _queueOpen && QueueUiRowsReady;
            bool fullQueueProjection = queueUiReady && (sessionChanged || orderChanged || orderContentsChanged);
            bool queueBudgetOwnsNextUp = false;
            if (_queueOpen && !queueUiReady)
            {
                EnsureQueueUiMaterialized(sessionChanged ? "session" : (orderChanged ? "order" : "refresh"));
                DeferQueueUiProjection(dirtyRuntimeRows);
            }
            else if (fullQueueProjection)
            {
                _libraryCoverageSummaryDirty = true;
                ApplyQueueRowsBudgeted(new HashSet<int>(_order), sessionChanged ? "session" : "order");
                queueBudgetOwnsNextUp = true;
            }
            else if (queueUiReady && dirtyRuntimeRows.Count > 0)
            {
                ApplyQueueRowsBudgeted(dirtyRuntimeRows, "queue-refresh");
                queueBudgetOwnsNextUp = true;
            }
            else if (queueUiReady && (queueProjectionChanged || runtimeProjectionWasEmpty))
                UpdateQueueRows(dirtyRuntimeRows);
            else if (!_queueOpen && dirtyRuntimeRows.Count > 0)
                DeferQueueUiProjection(dirtyRuntimeRows);
            // When only queue-runtime.json changed, the worker owns parsing, diffing and any
            // resulting row projection. Do not run an empty synchronous Queue reconciliation here.
            if (force && !fullQueueProjection && dirtyRuntimeRows.Count == 0)
                WriteControllerPerformanceLogAsync("QUEUE FORCE REUSE revision=" + revision.ToString(CultureInfo.InvariantCulture) + " rows=" + _order.Count.ToString(CultureInfo.InvariantCulture) + " ui=" + (_queueOpen ? "open" : "closed"));

            // The coverage string is Queue chrome. A closed Queue must not scan the full session
            // merely to update invisible subtitle text. Dirty state is consumed when Queue opens.
            if (_queueOpen)
            {
                if (_order.Count > 0)
                {
                    if (_libraryCoverageSummaryDirty || String.IsNullOrWhiteSpace(_libraryCoverageSummaryCached))
                    {
                        long coverageStarted = _clock.ElapsedMilliseconds;
                        _libraryCoverageSummaryCached = BuildLibraryCoverageSummary();
                        _libraryCoverageSummaryStampMs = _clock.ElapsedMilliseconds;
                        _libraryCoverageSummaryDirty = false;
                        long coverageElapsed = Math.Max(0, _clock.ElapsedMilliseconds - coverageStarted);
                        if (coverageElapsed >= 8)
                            WriteControllerPerformanceLogAsync("QUEUE COVERAGE REBUILD " + coverageElapsed.ToString(CultureInfo.InvariantCulture) +
                                "ms rows=" + _order.Count.ToString(CultureInfo.InvariantCulture));
                    }
                    _queueSubtitleText.Text = _libraryCoverageSummaryCached;
                }
                else
                {
                    _libraryCoverageSummaryCached = "";
                    _libraryCoverageSummaryDirty = true;
                    _queueSubtitleText.Text = "No active session order";
                }
            }
            _queueRevisionText.Text = Math.Max(0, _orderRevision).ToString(CultureInfo.InvariantCulture) + (OrderMutationBusy ? " | UPDATING" : "");
            ScheduleMetadataAhead();
            if (!queueBudgetOwnsNextUp && (queueProjectionChanged || commandReceiptChanged)) UpdateNextUpUi();
            _lastQueueSessionSnapshot = session;
            _lastQueueOrderSnapshot = orderState;
            _lastQueueRuntimeSnapshot = queueState;
            _lastQueueProjectedOccurrence = _currentOccurrence;
            _lastQueueProjectedPaused = _paused;
            _lastQueueProjectedAudioActive = _audioActive;
            _lastQueueProjectedPhase = _lastPlaybackPhase ?? "";
        }

        private void LoadTrackMetadata(Dictionary<string, object> session, Dictionary<string, object> orderState)
        {
            _trackMeta.Clear();
            int ordinal = 0;
            foreach (var raw in GetList(session, "occurrences"))
            {
                ordinal++;
                var map = AsMap(raw);
                int occ = GetInt(map, "position", ordinal);
                if (occ <= 0)
                    occ = ordinal;
                var meta = new TrackMeta
                {
                    OccurrenceId = occ,
                    Title = GetString(map, "title", "Track " + occ),
                    Channel = GetString(map, "channel", ""),
                    Url = GetString(map, "url", ""),
                    YoutubeId = GetString(map, "id", ""),
                    SourceKey = GetString(map, "source_key", ""),
                    SourceIndex = GetInt(map, "source_index", occ),
                    Duration = GetDouble(map, "duration", 0),
                    DuplicateOrdinal = GetInt(map, "duplicate_ordinal", 1),
                    DuplicateCount = GetInt(map, "duplicate_count", 1),
                    PoolName = GetString(map, "pool_name", ""),
                    PoolSourceSummary = GetStringListSummary(map, "pool_source_labels")
                };
                if (String.IsNullOrWhiteSpace(meta.SourceKey))
                    meta.SourceKey = ComputeSourceKey(meta.YoutubeId, meta.Url);
                _trackMeta[occ] = meta;
            }
            MergeInsertedMetadata(orderState);
        }

        private void MergeSessionMetadataEvidence(Dictionary<string, object> session)
        {
            if (session == null || session.Count == 0) return;
            var dirty = new HashSet<int>();
            int ordinal = 0;
            foreach (var raw in GetList(session, "occurrences"))
            {
                ordinal++;
                var map = AsMap(raw);
                int occ = GetInt(map, "position", ordinal);
                if (occ <= 0) occ = ordinal;
                string incomingTitle = GetString(map, "title", "Track " + occ).Trim();
                string incomingChannel = GetString(map, "channel", "").Trim();
                string incomingUrl = GetString(map, "url", "").Trim();
                string incomingId = GetString(map, "id", "").Trim();

                TrackMeta meta;
                if (!_trackMeta.TryGetValue(occ, out meta) || meta == null)
                {
                    meta = new TrackMeta
                    {
                        OccurrenceId = occ,
                        Title = incomingTitle.Length > 0 ? incomingTitle : "Track " + occ,
                        Channel = incomingChannel,
                        Url = incomingUrl,
                        YoutubeId = incomingId,
                        SourceKey = GetString(map, "source_key", ""),
                        SourceIndex = GetInt(map, "source_index", occ),
                        Duration = GetDouble(map, "duration", 0),
                        DuplicateOrdinal = GetInt(map, "duplicate_ordinal", 1),
                        DuplicateCount = GetInt(map, "duplicate_count", 1),
                        PoolName = GetString(map, "pool_name", ""),
                        PoolSourceSummary = GetStringListSummary(map, "pool_source_labels")
                    };
                    if (String.IsNullOrWhiteSpace(meta.SourceKey)) meta.SourceKey = ComputeSourceKey(meta.YoutubeId, meta.Url);
                    _trackMeta[occ] = meta;
                    dirty.Add(occ);
                    continue;
                }

                bool changed = false;
                if (!IsPlaceholderTrackTitle(incomingTitle, occ) && !String.Equals(meta.Title ?? "", incomingTitle, StringComparison.Ordinal))
                { meta.Title = incomingTitle; changed = true; }
                if (incomingChannel.Length > 0 && !String.Equals(meta.Channel ?? "", incomingChannel, StringComparison.Ordinal))
                { meta.Channel = incomingChannel; changed = true; }
                if (incomingUrl.Length > 0 && !String.Equals(meta.Url ?? "", incomingUrl, StringComparison.OrdinalIgnoreCase))
                { meta.Url = incomingUrl; changed = true; }
                if (incomingId.Length > 0 && !String.Equals(meta.YoutubeId ?? "", incomingId, StringComparison.OrdinalIgnoreCase))
                { meta.YoutubeId = incomingId; changed = true; }
                double incomingDuration = GetDouble(map, "duration", 0);
                if (incomingDuration > 0 && Math.Abs(meta.Duration - incomingDuration) > 0.001)
                { meta.Duration = incomingDuration; changed = true; }
                if (changed) dirty.Add(occ);
            }
            if (dirty.Count > 0 && _queueOpen && QueueUiRowsReady) UpdateQueueRows(dirty);
        }

        private void MergeInsertedMetadata(Dictionary<string, object> orderState)
        {
            foreach (var raw in GetList(orderState, "inserted"))
            {
                var map = AsMap(raw);
                int occ = GetInt(map, "occurrence_id", 0);
                if (occ <= 0)
                    continue;
                var meta = new TrackMeta
                {
                    OccurrenceId = occ,
                    Title = GetString(map, "title", "Track " + occ),
                    Channel = GetString(map, "channel", ""),
                    Url = GetString(map, "url", ""),
                    YoutubeId = GetString(map, "youtube_id", ""),
                    SourceKey = GetString(map, "source_key", ""),
                    SourceIndex = GetInt(map, "source_index", occ),
                    Duration = GetDouble(map, "duration", 0),
                    DuplicateOrdinal = 1,
                    DuplicateCount = 1,
                    PoolName = GetString(map, "pool_name", ""),
                    PoolSourceSummary = GetStringListSummary(map, "pool_source_labels")
                };
                if (String.IsNullOrWhiteSpace(meta.SourceKey))
                    meta.SourceKey = ComputeSourceKey(meta.YoutubeId, meta.Url);
                _trackMeta[occ] = meta;
            }
        }

        private List<int> ParseOrder(Dictionary<string, object> orderState, Dictionary<string, object> session)
        {
            var desired = new List<int>();
            var seen = new HashSet<int>();
            foreach (var raw in GetList(orderState, "order"))
            {
                int occ = ToInt(raw, 0);
                if (occ > 0 && seen.Add(occ))
                    desired.Add(occ);
            }

            if (desired.Count == 0)
            {
                int count = GetInt(session, "count", _trackMeta.Count);
                for (int i = 1; i <= count; i++)
                    desired.Add(i);
            }
            return desired;
        }

        private bool QueueUiRowsReady
        {
            get
            {
                return _queueUiMaterialized && !_queueUiOrderDirty && !_queueUiMaterializationActive &&
                       _queueRows.Count == _order.Count;
            }
        }

        private void UpdateLogicalQueueOrder(List<int> desired)
        {
            if (desired == null) desired = new List<int>();
            _order = new List<int>(desired);
            _orderIndexByOccurrence.Clear();
            for (int orderIndex = 0; orderIndex < _order.Count; orderIndex++)
                _orderIndexByOccurrence[_order[orderIndex]] = orderIndex;
            // R61.99: semantic overview indexes remain cached across scroll-only marker updates,
            // so a genuine order mutation must explicitly invalidate that cache.
            _queueOverviewIndexDirty = true;
            if (_currentOccurrence > 0)
            {
                int mappedCurrentIndex;
                if (_orderIndexByOccurrence.TryGetValue(_currentOccurrence, out mappedCurrentIndex))
                    _currentSlot = mappedCurrentIndex + 1;
            }
        }

        private void DeferQueueUiProjection(IEnumerable<int> occurrences)
        {
            if (occurrences == null) return;
            foreach (int occurrence in occurrences)
                if (occurrence > 0) _queueUiDeferredDirtyOccurrences.Add(occurrence);
        }

        private void EnsureQueueUiMaterialized(string reason)
        {
            if (_disposed || !_queueOpen) return;
            if (QueueUiRowsReady)
            {
                if (_queueUiDeferredDirtyOccurrences.Count > 0)
                {
                    var deferred = new HashSet<int>(_queueUiDeferredDirtyOccurrences);
                    _queueUiDeferredDirtyOccurrences.Clear();
                    ApplyQueueRowsBudgeted(deferred, "reopen");
                }
                return;
            }
            if (_queueUiMaterializationActive) return;
            BeginQueueUiMaterialization(reason);
        }

        private void BeginQueueUiMaterialization(string reason)
        {
            if (_disposed || !_queueOpen) return;

            int generation = ++_queueUiMaterializationGeneration;
            _queueUiMaterializationActive = true;
            _queueUiMaterialized = false;
            _queueUiOrderDirty = true;
            _queueUiRestoreSelectedOccurrences.Clear();
            foreach (var selectedItem in _queueList.SelectedItems)
            {
                var selectedRow = selectedItem as QueueRow;
                if (selectedRow != null && !_queueUiRestoreSelectedOccurrences.Contains(selectedRow.OccurrenceId))
                    _queueUiRestoreSelectedOccurrences.Add(selectedRow.OccurrenceId);
            }

            // A stale row-projection batch must not race a fresh materialization generation.
            _queueProjectionApplyGeneration++;
            _queueProjectionApplyActive = false;
            _queueProjectionCurrentRemainingRows = 0;
            _queueProjectionApplyPendingRows = 0;
            _queueProjectionApplyReason = "";
            _queueProjectionDeferredOccurrences.Clear();
            // Fresh materialization reads the current metadata/runtime model, so previously
            // deferred hidden-row dirties are already subsumed. Dirties arriving after this
            // point are accumulated normally and applied at completion.
            _queueUiDeferredDirtyOccurrences.Clear();

            _queueRows.Clear();
            _queueByOccurrence.Clear();
            _queueUiMaterializationSliceRows = QueueMaterializationSliceInitial;
            _queueUiMaterializationLastProgressMs = _clock.ElapsedMilliseconds;
            int[] snapshot = _order.ToArray();
            _queueUiMaterializationRemaining = snapshot.Length;
            UpdateQueueFilterSummary();
            UpdateStatusBarProjection();
            long startedMs = _clock.ElapsedMilliseconds;
            WriteControllerPerformanceLogAsync("QUEUE UI MATERIALIZE START reason=" + (reason ?? "open") +
                " rows=" + snapshot.Length.ToString(CultureInfo.InvariantCulture));

            if (snapshot.Length == 0)
            {
                FinishQueueUiMaterialization(generation, startedMs, reason);
                return;
            }
            try
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                {
                    ApplyQueueUiMaterializationSlice(generation, snapshot, 0, startedMs, reason);
                }));
            }
            catch
            {
                _queueUiMaterializationActive = false;
                _queueUiOrderDirty = true;
            }
        }

        private void ApplyQueueUiMaterializationSlice(int generation, int[] snapshot, int offset, long startedMs, string reason)
        {
            if (_disposed || generation != _queueUiMaterializationGeneration || snapshot == null) return;
            _queueUiMaterializationLastProgressMs = _clock.ElapsedMilliseconds;
            // R61.106.52.5.1: once a Queue snapshot starts materializing, finish it even if the
            // operator temporarily hides Queue or enters Mini. Aborting here used to leave a
            // partial/empty projection which then appeared to rebuild one current track at a time.

            int sliceRows = Math.Max(QueueMaterializationSliceMin, Math.Min(QueueMaterializationSliceMax, _queueUiMaterializationSliceRows));
            int end = Math.Min(snapshot.Length, offset + sliceRows);
            var slice = new HashSet<int>();
            var pendingRows = new List<QueueRow>(Math.Max(0, end - offset));
            long sliceStartedMs = _clock.ElapsedMilliseconds;
            _uiOperationPhase = "queue-materialize";
            for (int i = offset; i < end; i++)
            {
                int occurrence = snapshot[i];
                var row = new QueueRow(occurrence);
                ApplyQueueRowColumnVisibility(row, _queueTableAppliedVisibilityMask);
                _queueByOccurrence[occurrence] = row;
                pendingRows.Add(row);
                slice.Add(occurrence);
            }

            // R61.90: project row state before exposing the row to ICollectionView/WPF.
            // R61.89 inserted default QueueRow objects first, which made filters evaluate
            // incomplete state and forced a whole 2,802-row Refresh at materialization end.
            UpdateQueueRows(slice, true);
            foreach (QueueRow row in pendingRows)
                _queueRows.Add(row);
            _queueUiMaterializationLastProgressMs = _clock.ElapsedMilliseconds;
            long sliceElapsedMs = Math.Max(0, _clock.ElapsedMilliseconds - sliceStartedMs);
            if (sliceElapsedMs > QueueMaterializationTargetMs && _queueUiMaterializationSliceRows > QueueMaterializationSliceMin)
                _queueUiMaterializationSliceRows = Math.Max(QueueMaterializationSliceMin, _queueUiMaterializationSliceRows / 2);
            else if (sliceElapsedMs <= Math.Max(2, QueueMaterializationTargetMs / 2) && _queueUiMaterializationSliceRows < QueueMaterializationSliceMax)
                _queueUiMaterializationSliceRows = Math.Min(QueueMaterializationSliceMax, _queueUiMaterializationSliceRows + 2);
            if (sliceElapsedMs >= 12)
                WriteControllerPerformanceLogAsync("QUEUE UI MATERIALIZE SLICE " + sliceElapsedMs.ToString(CultureInfo.InvariantCulture) +
                    "ms rows=" + (end - offset).ToString(CultureInfo.InvariantCulture) +
                    " next=" + _queueUiMaterializationSliceRows.ToString(CultureInfo.InvariantCulture));
            _queueUiMaterializationRemaining = Math.Max(0, snapshot.Length - end);
            if (offset == 0 || end == snapshot.Length || (end % 128) < sliceRows)
            {
                UpdateQueueFilterSummary();
                UpdateStatusBarProjection();
            }

            if (end < snapshot.Length)
            {
                try
                {
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                    {
                        ApplyQueueUiMaterializationSlice(generation, snapshot, end, startedMs, reason);
                    }));
                }
                catch
                {
                    _queueUiMaterializationActive = false;
                    _queueUiOrderDirty = true;
                }
                return;
            }
            FinishQueueUiMaterialization(generation, startedMs, reason);
        }

        private void FinishQueueUiMaterialization(int generation, long startedMs, string reason)
        {
            if (_disposed || generation != _queueUiMaterializationGeneration) return;
            _queueUiMaterializationActive = false;
            _queueUiMaterializationLastProgressMs = 0;
            _queueUiMaterialized = true;
            _queueUiOrderDirty = false;
            _queueUiMaterializationRemaining = 0;
            UpdateQueueRows(new HashSet<int>(), false);
            UpdateQueueFilterSummary();
            UpdateStatusBarProjection();
            try
            {
                _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(delegate
                {
                    AttachQueueHorizonScroll();
                    UpdateQueueScrollbarPresentation();
                }));
            }
            catch { }
            // R61.90: rows enter the collection only after their initial projection is complete,
            // so the default Queue scope no longer needs a whole-view correction Refresh here.
            // Non-default dynamic scopes are still refreshed by UpdateQueueRows when required.

            if (_queueUiRestoreSelectedOccurrences.Count > 0)
            {
                _queueList.SelectedItems.Clear();
                foreach (int occurrence in _queueUiRestoreSelectedOccurrences)
                {
                    QueueRow selectedRow;
                    if (_queueByOccurrence.TryGetValue(occurrence, out selectedRow))
                        _queueList.SelectedItems.Add(selectedRow);
                }
                _queueUiRestoreSelectedOccurrences.Clear();
                UpdateQueueSelectionBar();
            }

            long elapsed = Math.Max(0, _clock.ElapsedMilliseconds - startedMs);
            WriteControllerPerformanceLogAsync("QUEUE UI MATERIALIZE COMPLETE reason=" + (reason ?? "open") +
                " rows=" + _queueRows.Count.ToString(CultureInfo.InvariantCulture) +
                " elapsed=" + elapsed.ToString(CultureInfo.InvariantCulture) + "ms");
            _uiOperationPhase = "idle";

            if (_queueUiDeferredDirtyOccurrences.Count > 0)
            {
                var deferred = new HashSet<int>(_queueUiDeferredDirtyOccurrences);
                _queueUiDeferredDirtyOccurrences.Clear();
                ApplyQueueRowsBudgeted(deferred, "materialize-followup");
            }
            if (_queueUiPendingSelectOccurrence > 0)
            {
                int pendingOccurrence = _queueUiPendingSelectOccurrence;
                bool relaxFilters = _queueUiPendingSelectRelaxFilters;
                bool topAnchor = _queueUiPendingSelectTopAnchor;
                _queueUiPendingSelectOccurrence = 0;
                _queueUiPendingSelectRelaxFilters = false;
                _queueUiPendingSelectTopAnchor = false;
                SelectQueueOccurrenceWhenReady(pendingOccurrence, relaxFilters, topAnchor);
            }
            _libraryCoverageSummaryDirty = true;
            RefreshQueueState(true);
            RestorePendingQueueContextAnchor();
            RestorePendingQueueInteractionContext();
            if (_queueFollowCurrent) FollowCurrentQueueRow(true);
            if (_queueSearchPlayButton != null && _queueSearchBox != null && !String.IsNullOrWhiteSpace(_queueSearchBox.Text))
            {
                _queueSearchPlayButton.Visibility = Visibility.Visible;
                _queueSearchPlayButton.IsEnabled = !_queuePlaybackSubsetActive;
            }
        }

        private void SynchronizeQueueOrder(List<int> desired)
        {
            long syncStartedMs = _clock.ElapsedMilliseconds;
            if (desired == null) desired = new List<int>();

            // Logical playback/order authority is always updated, even with a closed Queue.
            UpdateLogicalQueueOrder(desired);
            _libraryCoverageSummaryDirty = true;

            if (!_queueOpen)
            {
                _queueUiOrderDirty = true;
                long modelElapsed = Math.Max(0, _clock.ElapsedMilliseconds - syncStartedMs);
                WriteControllerPerformanceLogAsync("QUEUE ORDER MODEL ONLY elapsed=" + modelElapsed.ToString(CultureInfo.InvariantCulture) +
                    "ms desired=" + desired.Count.ToString(CultureInfo.InvariantCulture) + " ui=closed");
                return;
            }

            if (!QueueUiRowsReady)
            {
                _queueUiOrderDirty = true;
                if (_queueUiMaterializationActive)
                {
                    _queueUiMaterializationGeneration++;
                    _queueUiMaterializationActive = false;
                }
                BeginQueueUiMaterialization("order");
                return;
            }

            int removedRows = 0, insertedRows = 0, movedRows = 0;
            var selectedOccurrences = new List<int>();
            foreach (var selectedItem in _queueList.SelectedItems)
            {
                var selectedRow = selectedItem as QueueRow;
                if (selectedRow != null && !selectedOccurrences.Contains(selectedRow.OccurrenceId))
                    selectedOccurrences.Add(selectedRow.OccurrenceId);
            }

            var desiredSet = new HashSet<int>(desired);
            for (int i = _queueRows.Count - 1; i >= 0; i--)
            {
                if (!desiredSet.Contains(_queueRows[i].OccurrenceId))
                {
                    _queueByOccurrence.Remove(_queueRows[i].OccurrenceId);
                    _queueRows.RemoveAt(i);
                    removedRows++;
                }
            }

            for (int target = 0; target < desired.Count; target++)
            {
                int occ = desired[target];
                QueueRow row;
                if (!_queueByOccurrence.TryGetValue(occ, out row))
                {
                    row = new QueueRow(occ);
                    ApplyQueueRowColumnVisibility(row, _queueTableAppliedVisibilityMask);
                    _queueByOccurrence[occ] = row;
                    _queueRows.Insert(Math.Min(target, _queueRows.Count), row);
                    insertedRows++;
                }
                else
                {
                    int actual = _queueRows.IndexOf(row);
                    if (actual >= 0 && actual != target)
                    {
                        _queueRows.Move(actual, target);
                        movedRows++;
                    }
                }
            }

            _queueUiMaterialized = true;
            _queueUiOrderDirty = false;
            if (selectedOccurrences.Count > 0)
            {
                _queueList.SelectedItems.Clear();
                foreach (int occurrence in selectedOccurrences)
                {
                    QueueRow selectedRow;
                    if (_queueByOccurrence.TryGetValue(occurrence, out selectedRow))
                        _queueList.SelectedItems.Add(selectedRow);
                }
            }
            UpdateQueueSelectionBar();
            long syncElapsedMs = Math.Max(0, _clock.ElapsedMilliseconds - syncStartedMs);
            if (syncElapsedMs >= UiRefreshBudgetMs || removedRows + insertedRows + movedRows > 0)
                WriteControllerPerformanceLogAsync("QUEUE ORDER SYNC elapsed=" + syncElapsedMs.ToString(CultureInfo.InvariantCulture) +
                    "ms desired=" + desired.Count.ToString(CultureInfo.InvariantCulture) +
                    " removed=" + removedRows.ToString(CultureInfo.InvariantCulture) +
                    " inserted=" + insertedRows.ToString(CultureInfo.InvariantCulture) +
                    " moved=" + movedRows.ToString(CultureInfo.InvariantCulture));
        }

        private void ApplyQueueRowsBudgeted(HashSet<int> dirtyOccurrences, string reason)
        {
            if (_disposed) return;
            // R61.88: hidden Queue state is model-only. Runtime/readiness changes are remembered
            // without touching WPF rows; reopening either applies the dirty set or performs a fresh
            // cooperative materialization when structural order changed.
            if (!_queueOpen)
            {
                if (dirtyOccurrences == null) _queueUiOrderDirty = true;
                else DeferQueueUiProjection(dirtyOccurrences);
                return;
            }
            if (!QueueUiRowsReady)
            {
                if (dirtyOccurrences != null) DeferQueueUiProjection(dirtyOccurrences);
                EnsureQueueUiMaterialized(reason ?? "projection");
                return;
            }
            if (dirtyOccurrences == null)
            {
                UpdateQueueRows(null);
                return;
            }
            if (_queueProjectionApplyActive)
            {
                foreach (int occurrence in dirtyOccurrences) _queueProjectionDeferredOccurrences.Add(occurrence);
                _queueProjectionApplyPendingRows = _queueProjectionCurrentRemainingRows + _queueProjectionDeferredOccurrences.Count;
                if (!String.IsNullOrWhiteSpace(reason)) _queueProjectionApplyReason = reason;
                return;
            }
            if (dirtyOccurrences.Count <= QueueProjectionImmediateLimit)
            {
                UpdateQueueRows(dirtyOccurrences);
                UpdateNextUpUi();
                return;
            }

            var ordered = dirtyOccurrences
                .Where(occ => _orderIndexByOccurrence.ContainsKey(occ))
                .OrderBy(occ => _orderIndexByOccurrence[occ])
                .ToArray();
            if (ordered.Length == 0)
            {
                UpdateQueueRows(new HashSet<int>());
                return;
            }

            int generation = ++_queueProjectionApplyGeneration;
            _queueProjectionApplyActive = true;
            _queueProjectionCurrentRemainingRows = ordered.Length;
            _queueProjectionApplyPendingRows = ordered.Length;
            _queueProjectionApplyReason = reason ?? "queue";
            long started = _clock.ElapsedMilliseconds;
            WriteControllerPerformanceLogAsync("QUEUE BUDGET START reason=" + _queueProjectionApplyReason +
                " rows=" + ordered.Length.ToString(CultureInfo.InvariantCulture) +
                " slice-max=" + QueueProjectionApplySlice.ToString(CultureInfo.InvariantCulture) +
                " slice-now=" + _queueProjectionAdaptiveSlice.ToString(CultureInfo.InvariantCulture));
            ApplyQueueRowsBudgetSlice(generation, ordered, 0, started, _queueProjectionApplyReason);
        }

        private void ApplyQueueRowsBudgetSlice(int generation, int[] orderedOccurrences, int offset, long startedMs, string reason)
        {
            if (_disposed || generation != _queueProjectionApplyGeneration || orderedOccurrences == null) return;
            int sliceRows = Math.Max(QueueProjectionAdaptiveMin, Math.Min(QueueProjectionApplySlice, _queueProjectionAdaptiveSlice));
            int end = Math.Min(orderedOccurrences.Length, offset + sliceRows);
            var slice = new HashSet<int>();
            for (int i = offset; i < end; i++) slice.Add(orderedOccurrences[i]);
            _uiOperationPhase = "queue-budget-slice";
            long sliceStartedMs = _clock.ElapsedMilliseconds;
            UpdateQueueRows(slice, true);
            long sliceElapsedMs = Math.Max(0, _clock.ElapsedMilliseconds - sliceStartedMs);
            if (sliceElapsedMs > 10 && _queueProjectionAdaptiveSlice > QueueProjectionAdaptiveMin)
                _queueProjectionAdaptiveSlice = Math.Max(QueueProjectionAdaptiveMin, _queueProjectionAdaptiveSlice / 2);
            else if (sliceElapsedMs <= 5 && _queueProjectionAdaptiveSlice < QueueProjectionApplySlice)
                _queueProjectionAdaptiveSlice = Math.Min(QueueProjectionApplySlice, _queueProjectionAdaptiveSlice + 6);
            _queueProjectionCurrentRemainingRows = Math.Max(0, orderedOccurrences.Length - end);
            _queueProjectionApplyPendingRows = _queueProjectionCurrentRemainingRows + _queueProjectionDeferredOccurrences.Count;

            if (end < orderedOccurrences.Length)
            {
                try
                {
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                    {
                        ApplyQueueRowsBudgetSlice(generation, orderedOccurrences, end, startedMs, reason);
                    }));
                }
                catch { }
                return;
            }

            HashSet<int> followUp = null;
            if (_queueProjectionDeferredOccurrences.Count > 0)
            {
                followUp = new HashSet<int>(_queueProjectionDeferredOccurrences);
                _queueProjectionDeferredOccurrences.Clear();
            }
            _queueProjectionApplyActive = false;
            _queueProjectionCurrentRemainingRows = 0;
            _queueProjectionApplyPendingRows = followUp != null ? followUp.Count : 0;
            _queueProjectionApplyReason = "";
            // Empty incremental projection intentionally runs only the expensive reconciliation once.
            UpdateQueueRows(new HashSet<int>(), false);
            UpdateNextUpUi();
            long elapsed = Math.Max(0, _clock.ElapsedMilliseconds - startedMs);
            WriteControllerPerformanceLogAsync("QUEUE BUDGET COMPLETE reason=" + (reason ?? "queue") +
                " rows=" + orderedOccurrences.Length.ToString(CultureInfo.InvariantCulture) +
                " elapsed=" + elapsed.ToString(CultureInfo.InvariantCulture) + "ms" +
                " slice-now=" + _queueProjectionAdaptiveSlice.ToString(CultureInfo.InvariantCulture) +
                (followUp != null ? " deferred=" + followUp.Count.ToString(CultureInfo.InvariantCulture) : ""));
            _uiOperationPhase = "idle";
            if (followUp != null && followUp.Count > 0)
            {
                try
                {
                    _window.Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(delegate
                    {
                        ApplyQueueRowsBudgeted(followUp, "coalesced");
                    }));
                }
                catch { }
            }
        }

        private void UpdateQueueRows()
        {
            UpdateQueueRows(null);
        }

        private void UpdateQueueRows(HashSet<int> dirtyOccurrences)
        {
            UpdateQueueRows(dirtyOccurrences, false);
        }

        private void UpdateQueueRows(HashSet<int> dirtyOccurrences, bool deferExpensiveReconcile)
        {
            long projectionStarted = _clock.ElapsedMilliseconds;
            bool incremental = dirtyOccurrences != null;
            int currentIndex = -1;
            if (_currentOccurrence > 0)
            {
                int mappedCurrentIndex;
                if (_orderIndexByOccurrence.TryGetValue(_currentOccurrence, out mappedCurrentIndex)) currentIndex = mappedCurrentIndex;
            }
            if (currentIndex >= 0)
                _currentSlot = currentIndex + 1;
            if (!deferExpensiveReconcile) UpdatePlaybackSummary();

            // R61.80: incremental projection walks only dirty slots. Previously this loop walked
            // the entire order and performed a HashSet lookup for every row even when 1-20 rows
            // changed. A stable index map makes the normal path O(dirty), not O(queue length).
            List<int> projectionIndices = null;
            if (incremental)
            {
                projectionIndices = new List<int>(dirtyOccurrences.Count);
                foreach (int dirtyOccurrence in dirtyOccurrences)
                {
                    int dirtyIndex;
                    if (_orderIndexByOccurrence.TryGetValue(dirtyOccurrence, out dirtyIndex))
                        projectionIndices.Add(dirtyIndex);
                }
            }
            int projectionCount = incremental ? projectionIndices.Count : _order.Count;
            int projectedRows = 0;
            bool queueVisibilityChanged = false;
            for (int projectionOffset = 0; projectionOffset < projectionCount; projectionOffset++)
            {
                int i = incremental ? projectionIndices[projectionOffset] : projectionOffset;
                int occ = _order[i];
                projectedRows++;
                QueueRow row;
                if (!_queueByOccurrence.TryGetValue(occ, out row))
                    continue;

                TrackMeta meta;
                _trackMeta.TryGetValue(occ, out meta);
                RuntimeQueueItem runtime;
                _runtimeQueue.TryGetValue(occ, out runtime);

                int slot = i + 1;
                int delta = currentIndex >= 0 ? i - currentIndex : 0;
                string position = currentIndex < 0
                    ? slot.ToString(CultureInfo.InvariantCulture)
                    : delta == 0 ? "NOW"
                    : delta > 0 ? "+" + delta.ToString(CultureInfo.InvariantCulture)
                    : "-" + Math.Abs(delta).ToString(CultureInfo.InvariantCulture);

                row.Slot = slot;
                row.DisplaySlot = slot;
                row.PositionLabel = position;
                bool wasHardUnavailable = IsHardUnavailableTrackTitle(row.Title);
                row.Title = meta != null && !String.IsNullOrWhiteSpace(meta.Title) ? meta.Title : "Track " + occ;
                if (wasHardUnavailable != IsHardUnavailableTrackTitle(row.Title)) queueVisibilityChanged = true;
                row.Channel = meta != null ? meta.Channel : "";
                row.DurationSeconds = meta != null && meta.Duration > 0 ? meta.Duration : 0.0;
                row.DurationLabel = row.DurationSeconds > 0 ? FormatTime(row.DurationSeconds) : "";
                row.IsFavorite = meta != null && IsFavorite(meta);
                ListeningRecord memory = meta != null ? ListeningRecordFor(meta, false) : null;
                row.PlayCount = memory != null ? memory.Plays : 0;
                row.PlayCountLabel = row.PlayCount > 0 ? row.PlayCount.ToString(CultureInfo.InvariantCulture) : "";
                row.MemorySummary = BuildListeningSummary(meta, memory, false);
                row.Badge = "ITEM " + occ.ToString(CultureInfo.InvariantCulture) + (row.IsFavorite ? "  FAV" : "");
                if (delta == 0 && currentIndex >= 0)
                {
                    row.QuickPrimaryLabel = _paused ? "RESUME" : (_audioActive ? "PAUSE" : "PLAY");
                    row.QuickSecondaryLabel = "SKIP";
                    row.QuickPrimaryTip = _paused ? "Resume current playback" : (_audioActive ? "Pause current playback" : "Play current occurrence");
                    row.QuickSecondaryTip = "Skip to the next occurrence";
                    row.Status = _paused ? "PAUSED" : (_audioActive ? "PLAYING" : ProductPlaybackPhase(_lastPlaybackPhase));
                    row.SetStatus(Brush("AccentSoft"), Brush("AccentBorder"), _audioActive || _paused ? Brush("Accent") : Brush("TextSecondary"));
                    row.PositionBrush = Brush("Accent");
                    row.TitleBrush = Brush("TextPrimary");
                    row.RowBackground = Brushes.Transparent;
                    row.BaseDetail = BuildQueueDetail(runtime, meta, "Current track " + slot);
                    row.Detail = row.BaseDetail;
                }
                else if (delta < 0 && currentIndex >= 0)
                {
                    row.QuickPrimaryLabel = "PLAY";
                    row.QuickSecondaryLabel = "AGAIN";
                    row.QuickPrimaryTip = "Play this occurrence now";
                    row.QuickSecondaryTip = "Queue this played occurrence directly after the current track";
                    row.Status = "PLAYED";
                    row.SetStatus(Brush("SurfaceRaised"), Brush("Border"), Brush("TextMuted"));
                    row.PositionBrush = Brush("TextMuted");
                    row.TitleBrush = Brush("TextPrimary");
                    row.RowBackground = Brushes.Transparent;
                    row.BaseDetail = BuildQueueDetail(runtime, meta, "Track " + slot);
                    row.Detail = row.BaseDetail;
                }
                else if (runtime != null)
                {
                    row.QuickPrimaryLabel = "PLAY";
                    row.QuickSecondaryLabel = "NEXT";
                    row.QuickPrimaryTip = "Play this occurrence now";
                    row.QuickSecondaryTip = "Move this occurrence directly after the current track";
                    ApplyRuntimeQueueStatus(row, runtime);
                    row.PositionBrush = Brush("TextSecondary");
                    row.TitleBrush = Brush("TextPrimary");
                    row.RowBackground = Brushes.Transparent;
                    row.BaseDetail = BuildQueueDetail(runtime, meta, "Track " + slot);
                    row.Detail = row.BaseDetail;
                }
                else
                {
                    row.QuickPrimaryLabel = "PLAY";
                    row.QuickSecondaryLabel = "NEXT";
                    row.QuickPrimaryTip = "Play this occurrence now";
                    row.QuickSecondaryTip = "Move this occurrence directly after the current track";
                    row.Status = "QUEUED";
                    row.SetStatus(Brush("SurfaceRaised"), Brush("Border"), Brush("TextSecondary"));
                    row.PositionBrush = Brush("TextMuted");
                    row.TitleBrush = Brush("TextPrimary");
                    row.RowBackground = Brushes.Transparent;
                    row.BaseDetail = BuildQueueDetail(null, meta, "Track " + slot);
                    row.Detail = row.BaseDetail;
                }

                if (delta == 1 && currentIndex >= 0)
                {
                    row.QuickSecondaryLabel = "LATER";
                    row.QuickSecondaryTip = "Move this already-next occurrence five positions later";
                }

                ApplyQueueObservatoryState(row, runtime, delta);
                row.Explanation = ExplainQueueRow(row);

                row.SearchText = String.Join(" ", new[]
                {
                    row.Title ?? "", row.Channel ?? "", row.DurationLabel ?? "", row.Badge ?? "", row.Status ?? "",
                    row.ReadinessSummary ?? "", row.MediaSummary ?? "", row.SafetyLabel ?? "", row.ConfidenceNote ?? "", row.MemorySummary ?? "",
                    meta != null ? (meta.Url ?? "") : "", meta != null ? (meta.YoutubeId ?? "") : "", meta != null ? (meta.SourceKey ?? "") : "",
                    memory != null ? BuildListeningSummary(meta, memory, true) : "",
                    row.IsFavorite ? "favorite starred" : "", row.PlayCount <= 0 ? "unheard new never played" : "heard played",
                    row.PlayCount >= 3 ? "frequent rotation" : "", slot.ToString(CultureInfo.InvariantCulture)
                });
            }

            if (!deferExpensiveReconcile && _queueOpen)
            {
                bool dynamicView = !incremental || queueVisibilityChanged || _queueScope != QueueScope.All || _queueQueryKind == QueueQueryKind.Text;
                if (_queueView != null && dynamicView) _queueView.Refresh();
                // R46: playback/readiness/order changes can move a selected row out of the
                // active view without any user filter gesture. Reconcile selection after
                // the authoritative row state has changed, not only after search/scope input.
                if (dynamicView) PruneHiddenQueueSelection();
                UpdateQueueFilterSummary();
                try { _window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, new Action(UpdateQueueScrollbarPresentation)); } catch { }
                UpdateQueueHorizonSummary(currentIndex);
                UpdateCurrentQueueTemporalState();
                RestorePendingQueueContextAnchor();
                RestorePendingQueueInteractionContext();
                if (_queueFollowCurrent && _currentOccurrence > 0)
                {
                    bool followedTrackChanged = _currentOccurrence != _lastQueueFollowOccurrence;
                    if (followedTrackChanged || dynamicView)
                    {
                        if (followedTrackChanged) _lastQueueFollowOccurrence = _currentOccurrence;
                        FollowCurrentQueueRow(followedTrackChanged);
                    }
                }
                ScheduleQueueHorizonMarker();
            }
            if (!deferExpensiveReconcile && _inspectorOpen) RefreshInspector();
            long projectionMs = _clock.ElapsedMilliseconds - projectionStarted;
            if (projectionMs >= 45)
                WriteControllerPerformanceLogAsync("QUEUE PROJECTION " + projectionMs.ToString(CultureInfo.InvariantCulture) + "ms rows=" + projectedRows.ToString(CultureInfo.InvariantCulture) + "/" + _order.Count.ToString(CultureInfo.InvariantCulture) + (incremental ? " incremental" : " full"));
        }

        private void ApplyQueueObservatoryState(QueueRow row, RuntimeQueueItem runtime, int delta)
        {
            if (row == null) return;

            row.AudioStageBrush = QueueStageBrush(runtime != null ? runtime.Audio : "", true);
            row.ArtworkStageBrush = QueueStageBrush(runtime != null ? runtime.Artwork : "", false);
            row.VideoStageBrush = QueueStageBrush(runtime != null ? runtime.Video : "", false);
            row.VisualizerStageBrush = QueueStageBrush(runtime != null ? runtime.Visualizer : "", false);

            if (delta < 0)
            {
                Brush historyBrush = new SolidColorBrush(Color.FromRgb(35, 43, 48));
                row.AudioStageBrush = historyBrush;
                row.ArtworkStageBrush = historyBrush;
                row.VideoStageBrush = historyBrush;
                row.VisualizerStageBrush = historyBrush;
                row.ReadinessSummary = "PLAYBACK HISTORY";
                row.MediaSummary = "";
                row.SafetyLabel = "";
                row.SafetyBrush = Brush("TextMuted");
                return;
            }

            if (runtime == null)
            {
                row.ReadinessSummary = "Audio: waiting · Thumbnail: waiting · Video: waiting · Visuals: waiting";
                row.MediaSummary = delta >= 0 && delta <= 3 ? "Checking" : "";
                row.SafetyLabel = "NOT PROFILED";
                row.SafetyBrush = Brush("TextMuted");
                return;
            }

            var stages = new List<string>();
            stages.Add("Audio: " + StageDisplay(runtime.Audio).ToLowerInvariant());
            stages.Add("Thumbnail: " + StageDisplay(runtime.Artwork).ToLowerInvariant());
            if (!String.IsNullOrWhiteSpace(runtime.Video) && !String.Equals(runtime.Video, "NOT_REQUIRED", StringComparison.OrdinalIgnoreCase))
            {
                string video = runtime.VideoActualHeight > 0
                    ? runtime.VideoActualHeight.ToString(CultureInfo.InvariantCulture) + "p" + (runtime.VideoFallback ? " fallback" : "")
                    : StageDisplay(runtime.Video).ToLowerInvariant();
                stages.Add("Video: " + video);
            }
            if (!String.IsNullOrWhiteSpace(runtime.Visualizer) && !String.Equals(runtime.Visualizer, "NOT_REQUIRED", StringComparison.OrdinalIgnoreCase))
                stages.Add("Visuals: " + StageDisplay(runtime.Visualizer).ToLowerInvariant());
            row.ReadinessSummary = String.Join(" · ", stages.ToArray());
            if (String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase)) row.MediaSummary = "Audio failed";
            else if (delta == 0 && runtime.PresentationComplete) row.MediaSummary = "Ready";
            else if (delta >= 0 && delta <= 3 && runtime.TransitionReady) row.MediaSummary = "Audio ready";
            else if (delta >= 0 && delta <= 3 && !runtime.PresentationComplete) row.MediaSummary = "Preparing";
            else row.MediaSummary = "";

            if (String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase))
            {
                row.SafetyLabel = "AUDIO BLOCKED";
                row.SafetyBrush = Brush("Danger");
            }
            else if (runtime.HasSlack)
            {
                if (runtime.SlackSeconds >= 0)
                {
                    row.SafetyLabel = "SLACK +" + CompactSeconds(runtime.SlackSeconds);
                    row.SafetyBrush = runtime.SlackSeconds < 10 ? Brush("Warning") : Brush("Accent");
                }
                else
                {
                    row.SafetyLabel = "SLACK -" + CompactSeconds(Math.Abs(runtime.SlackSeconds));
                    row.SafetyBrush = Brush("Danger");
                }
            }
            else if (runtime.EstimatedPrepareSeconds >= 0 && !runtime.TransitionReady)
            {
                row.SafetyLabel = "ETA " + CompactSeconds(runtime.EstimatedPrepareSeconds);
                row.SafetyBrush = Brush("Warning");
            }
            else if (runtime.PresentationComplete)
            {
                bool faultIsolated = IsFaultIsolated(runtime.Artwork) || IsFaultIsolated(runtime.Video) || IsFaultIsolated(runtime.Visualizer);
                bool admissionDeferred = IsAdmissionDeferred(runtime.AdmissionArtwork) || IsAdmissionDeferred(runtime.AdmissionVideo) || IsAdmissionDeferred(runtime.AdmissionVisualizer);
                row.SafetyLabel = faultIsolated ? "ISOLATED READY" : (admissionDeferred ? "POLICY READY" : "FULL READY");
                row.SafetyBrush = (faultIsolated || admissionDeferred) ? Brush("Info") : Brush("Accent");
            }
            else if (runtime.TransitionReady)
            {
                row.SafetyLabel = runtime.PresentationSlaYielded ? "AUDIO WON SLA" : "AUDIO READY";
                row.SafetyBrush = Brush("Info");
            }
            else
            {
                row.SafetyLabel = runtime.HasActiveWork ? "PREPARING" : "NOT READY";
                row.SafetyBrush = runtime.HasActiveWork ? Brush("Warning") : Brush("TextMuted");
            }
        }

        private void ApplyQueueConfidence(QueueRow row, RuntimeQueueItem runtime, int delta)
        {
            if (row == null) return;
            string note = QueueConfidenceNote(row.Status, row.SafetyLabel, runtime, delta);
            row.ConfidenceNote = note;
            if (String.IsNullOrWhiteSpace(note))
            {
                row.ConfidenceBrush = Brush("TextMuted");
                return;
            }

            string safety = (row.SafetyLabel ?? "").ToUpperInvariant();
            bool low = safety == "AUDIO BLOCKED" || safety.StartsWith("SLACK -", StringComparison.Ordinal) || safety.StartsWith("SLACK -", StringComparison.Ordinal);
            bool tightPositive = safety.StartsWith("SLACK +", StringComparison.Ordinal) && runtime != null && runtime.HasSlack && runtime.SlackSeconds >= 0 && runtime.SlackSeconds < 10;
            bool caution = tightPositive || safety.StartsWith("ETA ", StringComparison.Ordinal) || safety == "PREPARING" || safety == "NOT READY" || safety == "NOT PROFILED";
            row.ConfidenceBrush = low ? Brush("Danger") : caution ? Brush("Warning") : Brush("Info");
        }

        private static string QueueConfidenceNote(string status, string safety, RuntimeQueueItem runtime, int delta)
        {
            if (delta < 0) return "";
            string state = (status ?? "").Trim().ToUpperInvariant();
            string note = (safety ?? "").Trim().ToUpperInvariant();

            if (note == "AUDIO BLOCKED" || (runtime != null && String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase)))
                return "Audio path failed | INFO explains the route";
            if (note.StartsWith("SLACK -", StringComparison.Ordinal) || note.StartsWith("SLACK -", StringComparison.Ordinal))
                return "Visual preparation may miss start | audio remains priority";
            if (note.StartsWith("SLACK +", StringComparison.Ordinal) && runtime != null && runtime.HasSlack && runtime.SlackSeconds >= 0 && runtime.SlackSeconds < 10)
                return "Tight preparation margin | projected ready just before start";
            if (note.StartsWith("ETA ", StringComparison.Ordinal) || note == "PREPARING" || state == "BUILDING")
                return "Still preparing | audio start remains protected";
            if (note == "ISOLATED READY" || state == "ISOLATED READY")
            {
                string affected = FriendlyAffectedPresentation(runtime, true);
                return (String.IsNullOrWhiteSpace(affected) ? "Optional visual fault" : affected + " fault") + " contained | audio remains ready";
            }
            if (note == "POLICY READY" || state == "POLICY READY")
            {
                string affected = FriendlyAffectedPresentation(runtime, false);
                return (String.IsNullOrWhiteSpace(affected) ? "Optional visual work" : affected) + " deferred to protect resources";
            }
            if (note == "AUDIO WON SLA" || (runtime != null && runtime.PresentationSlaYielded))
                return "Visual wait ended so audio could start on time";
            if (note == "AUDIO READY" || state == "AUDIO READY" || (runtime != null && runtime.TransitionReady && !runtime.PresentationComplete))
            {
                string waiting = FriendlyWaitingPresentation(runtime);
                return "Audio ready | " + (String.IsNullOrWhiteSpace(waiting) ? "optional visuals are" : waiting + " is") + " still catching up";
            }
            if (runtime != null && runtime.VideoFallback)
            {
                if (runtime.VideoActualHeight > 0)
                    return "Video fallback | using " + runtime.VideoActualHeight.ToString(CultureInfo.InvariantCulture) + "p available route";
                return "Video fallback | using the next available route";
            }
            if (note == "NOT PROFILED")
                return delta > 0 && delta <= 3 ? "Readiness has not been profiled yet" : "";
            if (note == "NOT READY")
                return delta > 0 && delta <= 3 ? "No preparation result yet | INFO explains current evidence" : "";
            if (runtime != null && !String.IsNullOrWhiteSpace(runtime.Risk))
                return "Preparation risk detected | INFO explains the evidence";
            return "";
        }

        private static string FriendlyAffectedPresentation(RuntimeQueueItem runtime, bool isolated)
        {
            if (runtime == null) return "";
            var parts = new List<string>();
            if (isolated ? IsFaultIsolated(runtime.Artwork) : IsAdmissionDeferred(runtime.AdmissionArtwork)) parts.Add("thumbnail");
            if (isolated ? IsFaultIsolated(runtime.Video) : IsAdmissionDeferred(runtime.AdmissionVideo)) parts.Add("video");
            if (isolated ? IsFaultIsolated(runtime.Visualizer) : IsAdmissionDeferred(runtime.AdmissionVisualizer)) parts.Add("visualizer");
            return FriendlyJoin(parts);
        }

        private static string FriendlyWaitingPresentation(RuntimeQueueItem runtime)
        {
            if (runtime == null) return "";
            var parts = new List<string>();
            if (!PresentationStageSettled(runtime.Artwork)) parts.Add("thumbnail");
            if (!PresentationStageSettled(runtime.Video)) parts.Add("video");
            if (!PresentationStageSettled(runtime.Visualizer)) parts.Add("visualizer");
            return FriendlyJoin(parts);
        }

        private static bool PresentationStageSettled(string stage)
        {
            string value = (stage ?? "").ToUpperInvariant();
            return value == "READY" || value == "NOT_REQUIRED" || value == "FAILED_OPTIONAL" || value.StartsWith("DEFERRED_", StringComparison.Ordinal);
        }

        private static string FriendlyJoin(List<string> parts)
        {
            if (parts == null || parts.Count == 0) return "";
            if (parts.Count == 1) return parts[0];
            if (parts.Count == 2) return parts[0] + " and " + parts[1];
            return parts[0] + ", " + parts[1] + " and " + parts[2];
        }

        private Brush QueueStageBrush(string stage, bool essential)
        {
            switch ((stage ?? "").ToUpperInvariant())
            {
                case "READY": return Brush("Accent");
                case "ACTIVE": return Brush("Warning");
                case "QUEUED": return Brush("Info");
                case "WAITING": return Brush("BorderStrong");
                case "FAILED_OPTIONAL": return Brush("TextMuted");
                case "DEFERRED_ADMISSION": return Brush("Info");
                case "DEFERRED_CIRCUIT": return Brush("Warning");
                case "DEFERRED_RESOURCE": return Brush("TextMuted");
                case "DEFERRED_NETWORK": return Brush("TextMuted");
                case "FAILED_PERMANENT": return Brush("Danger");
                case "NOT_REQUIRED": return new SolidColorBrush(Color.FromRgb(35, 43, 48));
                default: return essential ? Brush("BorderStrong") : new SolidColorBrush(Color.FromRgb(35, 43, 48));
            }
        }

        private static string StageDisplay(string stage)
        {
            switch ((stage ?? "").ToUpperInvariant())
            {
                case "READY": return "READY";
                case "ACTIVE": return "PREPARING";
                case "QUEUED": return "QUEUED";
                case "WAITING": return "WAITING";
                case "FAILED_OPTIONAL": return "OPTIONAL OFF";
                case "DEFERRED_ADMISSION": return "DEFERRED";
                case "DEFERRED_CIRCUIT": return "CONTAINED";
                case "DEFERRED_RESOURCE": return "PAUSED";
                case "DEFERRED_NETWORK": return "NETWORK WAIT";
                case "FAILED_PERMANENT": return "FAILED";
                case "NOT_REQUIRED": return "-";
                default: return String.IsNullOrWhiteSpace(stage) ? "-" : stage.ToUpperInvariant();
            }
        }

        private void UpdateQueueHorizonSummary(int currentIndex)
        {
            if (_queueHorizonText == null) return;
            int start = currentIndex >= 0 ? currentIndex + 1 : 0;
            if (start >= _order.Count)
            {
                _queueHorizonText.Text = "Next 10: end of queue";
                _queueHorizonText.Foreground = Brush("TextMuted");
                _queueHorizonText.ToolTip = "There are no upcoming occurrences in the active queue.";
                return;
            }

            int end = Math.Min(_order.Count, start + 10);
            int fullReady = 0, policyReady = 0, isolatedReady = 0, audioReady = 0, building = 0, waiting = 0, failed = 0, fallback = 0, unknownDuration = 0;
            double durationSeconds = 0;
            double lowestSlack = Double.MaxValue;
            bool hasSlack = false;

            for (int i = start; i < end; i++)
            {
                int occ = _order[i];
                RuntimeQueueItem runtime;
                _runtimeQueue.TryGetValue(occ, out runtime);
                TrackMeta meta;
                if (_trackMeta.TryGetValue(occ, out meta) && meta != null && meta.Duration > 0) durationSeconds += meta.Duration;
                else unknownDuration++;

                if (runtime == null) waiting++;
                else if (String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase)) failed++;
                else if (runtime.PresentationComplete)
                {
                    bool isolated = IsFaultIsolated(runtime.Artwork) || IsFaultIsolated(runtime.Video) || IsFaultIsolated(runtime.Visualizer);
                    bool deferred = IsAdmissionDeferred(runtime.AdmissionArtwork) || IsAdmissionDeferred(runtime.AdmissionVideo) || IsAdmissionDeferred(runtime.AdmissionVisualizer);
                    if (isolated) isolatedReady++; else if (deferred) policyReady++; else fullReady++;
                }
                else if (runtime.TransitionReady) audioReady++;
                else if (runtime.HasActiveWork) building++;
                else waiting++;

                if (runtime != null && runtime.VideoFallback) fallback++;
                if (runtime != null && runtime.HasSlack) { hasSlack = true; lowestSlack = Math.Min(lowestSlack, runtime.SlackSeconds); }
            }

            bool lowConfidence = failed > 0 || (hasSlack && lowestSlack < 0);
            bool mixedConfidence = !lowConfidence && (building > 0 || waiting > 0 || audioReady > 0 || isolatedReady > 0 || policyReady > 0 || fallback > 0 || unknownDuration > 0 || (hasSlack && lowestSlack < 10));
            string confidence = lowConfidence ? "LOW" : mixedConfidence ? "MIXED" : "HIGH";

            var parts = new List<string>();
            parts.Add("CONFIDENCE " + confidence);
            parts.Add("NEXT " + (end - start).ToString(CultureInfo.InvariantCulture));
            if (fullReady > 0) parts.Add(fullReady.ToString(CultureInfo.InvariantCulture) + " FULL");
            if (policyReady > 0) parts.Add(policyReady.ToString(CultureInfo.InvariantCulture) + " POLICY-READY");
            if (isolatedReady > 0) parts.Add(isolatedReady.ToString(CultureInfo.InvariantCulture) + " ISOLATED");
            if (audioReady > 0) parts.Add(audioReady.ToString(CultureInfo.InvariantCulture) + " AUDIO-READY");
            if (building > 0) parts.Add(building.ToString(CultureInfo.InvariantCulture) + " BUILDING");
            if (waiting > 0) parts.Add(waiting.ToString(CultureInfo.InvariantCulture) + " UNPROFILED/WAITING");
            if (failed > 0) parts.Add(failed.ToString(CultureInfo.InvariantCulture) + " AUDIO-BLOCKED");
            if (durationSeconds > 0) parts.Add(CompactSeconds(durationSeconds) + " KNOWN WINDOW");
            if (unknownDuration > 0) parts.Add("TIMING PARTIAL");
            if (hasSlack) parts.Add(lowestSlack >= 0 ? "LOW MARGIN +" + CompactSeconds(lowestSlack) : "LOW MARGIN -" + CompactSeconds(Math.Abs(lowestSlack)));
            if (fallback > 0) parts.Add(fallback.ToString(CultureInfo.InvariantCulture) + " VIDEO FALLBACK");

            _queueHorizonText.Text = "Next 10: " + String.Join(" / ", parts.ToArray());
            _queueHorizonText.Foreground = lowConfidence ? Brush("Danger") : mixedConfidence ? Brush("Warning") : Brush("Accent");

            var why = new List<string>();
            if (failed > 0) why.Add(failed.ToString(CultureInfo.InvariantCulture) + " upcoming audio path" + (failed == 1 ? " is" : "s are") + " blocked");
            if (hasSlack && lowestSlack < 0) why.Add("the lowest preparation margin is already negative");
            if (building > 0) why.Add(building.ToString(CultureInfo.InvariantCulture) + " occurrence" + (building == 1 ? " is" : "s are") + " still preparing");
            if (waiting > 0) why.Add(waiting.ToString(CultureInfo.InvariantCulture) + " occurrence" + (waiting == 1 ? " has" : "s have") + " incomplete readiness evidence");
            if (audioReady > 0) why.Add(audioReady.ToString(CultureInfo.InvariantCulture) + " occurrence" + (audioReady == 1 ? " has" : "s have") + " audio ready while optional presentation catches up");
            if (policyReady > 0) why.Add("optional presentation work was deferred by resource policy");
            if (isolatedReady > 0) why.Add("an optional presentation fault is isolated");
            if (fallback > 0) why.Add("video fallback is active");
            if (unknownDuration > 0) why.Add("unknown duration limits downstream STARTS estimates");
            if (why.Count == 0) why.Add("all profiled upcoming audio and requested presentation paths are ready with no known timing risk");
            _queueHorizonText.ToolTip = "Confidence " + confidence.ToLowerInvariant() + ": " + String.Join("; ", why.ToArray()) + ".";
        }

        private void ApplyRuntimeQueueStatus(QueueRow row, RuntimeQueueItem runtime)
        {
            if (String.Equals(runtime.Audio, "FAILED_PERMANENT", StringComparison.OrdinalIgnoreCase))
            {
                row.Status = "FAILED";
                row.SetStatus(Brush("DangerSoft"), Brush("Danger"), Brush("Danger"));
            }
            else if (runtime.PresentationComplete)
            {
                bool faultIsolated = IsFaultIsolated(runtime.Artwork) || IsFaultIsolated(runtime.Video) || IsFaultIsolated(runtime.Visualizer);
                bool admissionDeferred = IsAdmissionDeferred(runtime.AdmissionArtwork) || IsAdmissionDeferred(runtime.AdmissionVideo) || IsAdmissionDeferred(runtime.AdmissionVisualizer);
                row.Status = faultIsolated ? "ISOLATED READY" : (admissionDeferred ? "POLICY READY" : "READY");
                bool degraded = faultIsolated || admissionDeferred;
                row.SetStatus(degraded ? Brush("InfoSoft") : Brush("AccentSoft"), degraded ? Brush("Info") : Brush("AccentBorder"), degraded ? Brush("Info") : Brush("Accent"));
            }
            else if (runtime.TransitionReady)
            {
                row.Status = "AUDIO READY";
                row.SetStatus(Brush("InfoSoft"), Brush("Info"), Brush("Info"));
            }
            else if (runtime.HasActiveWork)
            {
                row.Status = "BUILDING";
                row.SetStatus(Brush("WarningSoft"), Brush("Warning"), Brush("Warning"));
            }
            else
            {
                row.Status = "WAITING";
                row.SetStatus(Brush("SurfaceRaised"), Brush("Border"), Brush("TextSecondary"));
            }
        }

        private string BuildQueueDetail(RuntimeQueueItem runtime, TrackMeta meta, string prefix)
        {
            var parts = new List<string> { prefix };
            if (runtime != null)
            {
                if (!String.IsNullOrWhiteSpace(runtime.Audio)) parts.Add("Audio: " + FriendlyStateWord(StageDisplay(runtime.Audio)));
                if (!String.IsNullOrWhiteSpace(runtime.Video) && runtime.Video != "NOT_REQUIRED") parts.Add("Video: " + FriendlyStateWord(StageDisplay(runtime.Video)));
                if (!String.IsNullOrWhiteSpace(runtime.Visualizer) && runtime.Visualizer != "NOT_REQUIRED") parts.Add("Visuals: " + FriendlyStateWord(StageDisplay(runtime.Visualizer)));
                if (!String.IsNullOrWhiteSpace(runtime.Risk) && runtime.Risk != "OK") parts.Add("Attention: " + FriendlyStateWord(runtime.Risk));
                if (runtime.EtaSeconds >= 0) parts.Add("Preparation estimate: " + CompactSeconds(runtime.EtaSeconds));
                if (runtime.PredictiveConfidence >= 0) parts.Add("Preparation confidence: " + runtime.PredictiveConfidence.ToString(CultureInfo.InvariantCulture) + "%");
                var deferred = new List<string>();
                if (IsAdmissionDeferred(runtime.AdmissionArtwork)) deferred.Add("thumbnail");
                if (IsAdmissionDeferred(runtime.AdmissionVideo)) deferred.Add("video");
                if (IsAdmissionDeferred(runtime.AdmissionVisualizer)) deferred.Add("visuals");
                if (deferred.Count > 0) parts.Add("Delayed: " + String.Join(", ", deferred.ToArray()));
                var isolated = new List<string>();
                if (IsFaultIsolated(runtime.Artwork)) isolated.Add("thumbnail");
                if (IsFaultIsolated(runtime.Video)) isolated.Add("video");
                if (IsFaultIsolated(runtime.Visualizer)) isolated.Add("visuals");
                if (isolated.Count > 0) parts.Add("Contained: " + String.Join(", ", isolated.ToArray()));
                var incoherent = new List<string>();
                if (IsCacheAnomaly(runtime.CacheAudio)) incoherent.Add("audio " + FriendlyStateWord(runtime.CacheAudio));
                if (IsCacheAnomaly(runtime.CacheArtwork)) incoherent.Add("thumbnail " + FriendlyStateWord(runtime.CacheArtwork));
                if (IsCacheAnomaly(runtime.CacheVideo)) incoherent.Add("video " + FriendlyStateWord(runtime.CacheVideo));
                if (IsCacheAnomaly(runtime.CacheVisualizer)) incoherent.Add("visuals " + FriendlyStateWord(runtime.CacheVisualizer));
                if (incoherent.Count > 0) parts.Add("Cache issue: " + String.Join(", ", incoherent.ToArray()));
                if (!String.IsNullOrWhiteSpace(runtime.PerfBottleneck) && runtime.PerfTotalMs >= 0)
                {
                    string perf = "Last preparation: " + FriendlyStateWord(runtime.PerfBottleneck) + " " + CompactMilliseconds(runtime.PerfTotalMs);
                    if (runtime.PerfQueueMs > 0) perf += ", waited " + CompactMilliseconds(runtime.PerfQueueMs);
                    if (runtime.PerfAnomaly) perf += ", timing anomaly";
                    parts.Add(perf);
                }
                if (!String.IsNullOrWhiteSpace(runtime.DecisionReason)) parts.Add("Reason: " + runtime.DecisionReason);
                if (runtime.VideoActualHeight > 0)
                {
                    string videoRoute = "Video: " + runtime.VideoActualHeight.ToString(CultureInfo.InvariantCulture) + "p";
                    if (runtime.VideoFallback) videoRoute += " fallback";
                    if (!String.IsNullOrWhiteSpace(runtime.VideoRouteLabel)) videoRoute += ", " + CompactRouteLabel(runtime.VideoRouteLabel, 34);
                    parts.Add(videoRoute);
                }
                if (runtime.PresentationSlaYielded) parts.Add("Audio continued while visuals caught up");
                if (runtime.Pinned) parts.Add("Pinned");
                if (runtime.SharedMedia) parts.Add("Prepared media is shared");
            }
            else if (meta != null && meta.DuplicateCount > 1)
            {
                parts.Add(String.Format(CultureInfo.InvariantCulture, "Duplicate {0} of {1}", meta.DuplicateOrdinal, meta.DuplicateCount));
            }
            return String.Join(" · ", parts.ToArray());
        }

        private static bool IsAdmissionDeferred(string value)
        {
            return !String.IsNullOrWhiteSpace(value) && value.StartsWith("DEFER", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsFaultIsolated(string value)
        {
            return String.Equals(value, "DEFERRED_CIRCUIT", StringComparison.OrdinalIgnoreCase);
        }

        private static bool IsCacheAnomaly(string value)
        {
            if (String.IsNullOrWhiteSpace(value)) return false;
            return !(String.Equals(value, "OK", StringComparison.OrdinalIgnoreCase) ||
                     String.Equals(value, "ADOPTED", StringComparison.OrdinalIgnoreCase) ||
                     String.Equals(value, "MISSING", StringComparison.OrdinalIgnoreCase) ||
                     String.Equals(value, "NOT_REQUIRED", StringComparison.OrdinalIgnoreCase));
        }

        private static string CompactSeconds(double seconds)
        {
            if (seconds < 0) return "-";
            if (seconds < 60) return Math.Round(seconds).ToString(CultureInfo.InvariantCulture) + "s";
            return Math.Floor(seconds / 60).ToString(CultureInfo.InvariantCulture) + "m" + Math.Round(seconds % 60).ToString("00", CultureInfo.InvariantCulture) + "s";
        }

        private static string CompactStage(string stage)
        {
            switch ((stage ?? "").ToUpperInvariant())
            {
                case "READY": return "READY";
                case "ACTIVE": return "ACTIVE";
                case "QUEUED": return "QUEUED";
                case "WAITING": return "WAIT";
                case "FAILED_OPTIONAL": return "SKIP";
                case "DEFERRED_ADMISSION": return "DEFER";
                case "DEFERRED_CIRCUIT": return "ISOLATED";
                case "DEFERRED_RESOURCE": return "RESOURCE";
                case "DEFERRED_NETWORK": return "NETWORK";
                case "FAILED_PERMANENT": return "FAIL";
                default: return stage ?? "";
            }
        }

        private void UpdateMediaStateOverlay(string art, string video)
        {
            // R61.94 calm presentation: optional media readiness is communicated by the media itself.
            // Preparation remains available in Operations Center/logs but never covers Now Playing with chatter.
            if (_mediaStateOverlay != null) _mediaStateOverlay.Visibility = Visibility.Collapsed;
        }

        private void RefreshMediaIfNeeded(Dictionary<string, object> current)
        {
            long now = _clock.ElapsedMilliseconds;
            bool evidenceChanged = !Object.ReferenceEquals(current, _lastMediaCurrentSnapshot) ||
                                   _lastMediaResolveOccurrence != _currentOccurrence ||
                                   _lastMediaResolveMode != _mediaMode ||
                                   _lastMediaResolveVisualizerEnabled != _visualizerEnabled ||
                                   _lastMediaOccurrence != _currentOccurrence;
            bool safetyProbeDue = now - _lastMediaResolveMs >= 1800;
            if (!evidenceChanged && !safetyProbeDue) return;

            _lastMediaResolveMs = now;
            _lastMediaCurrentSnapshot = current;
            _lastMediaResolveOccurrence = _currentOccurrence;
            _lastMediaResolveMode = _mediaMode;
            _lastMediaResolveVisualizerEnabled = _visualizerEnabled;
            RefreshMedia(current);
        }

        private void RefreshMedia(Dictionary<string, object> current)
        {
            if (!_window.IsVisible || _window.WindowState == WindowState.Minimized || !_running || _currentOccurrence <= 0)
            {
                StopPreviewProcesses();
                return;
            }

            TrackMeta meta;
            _trackMeta.TryGetValue(_currentOccurrence, out meta);
            var request = new MediaResolveRequest
            {
                Generation = Interlocked.Increment(ref _mediaResolveGeneration),
                Occurrence = _currentOccurrence,
                ArtworkReference = GetString(current, "artwork", ""),
                VideoReference = GetString(current, "video", ""),
                VisualizerReference = GetString(current, "visualizer", ""),
                SourceKey = meta != null ? (meta.SourceKey ?? "") : ""
            };
            if (String.IsNullOrWhiteSpace(request.SourceKey) && meta != null) request.SourceKey = ComputeSourceKey(meta.YoutubeId, meta.Url);
            lock (_mediaResolveSync)
            {
                _pendingMediaResolve = request;
                if (_mediaResolveWorkerActive) return;
                _mediaResolveWorkerActive = true;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored) { DrainMediaResolveQueue(); });
        }

        private void DrainMediaResolveQueue()
        {
            try
            {
                while (true)
                {
                    MediaResolveRequest request;
                    lock (_mediaResolveSync)
                    {
                        request = _pendingMediaResolve;
                        _pendingMediaResolve = null;
                    }
                    if (request == null) break;
                    request.ArtworkPath = ResolveMediaSnapshot(request.ArtworkReference, "artwork", request.Occurrence, request.SourceKey);
                    request.VideoPath = ResolveMediaSnapshot(request.VideoReference, "video", request.Occurrence, request.SourceKey);
                    request.VisualizerPath = ResolveMediaSnapshot(request.VisualizerReference, "visualizer", request.Occurrence, request.SourceKey);
                    request.ArtworkGeneration = MediaFileGeneration(request.ArtworkPath);
                    request.VideoGeneration = MediaFileGeneration(request.VideoPath);
                    request.VisualizerGeneration = MediaFileGeneration(request.VisualizerPath);
                    request.PreviewFfmpegPath = ResolvePreviewFfmpeg();
                    try
                    {
                        TryBeginInvokeUi(DispatcherPriority.Background, delegate
                        {
                            if (_disposed || request.Generation != _mediaResolveGeneration || request.Occurrence != _currentOccurrence) return;
                            _previewFfmpegPath = request.PreviewFfmpegPath ?? "";
                            ApplyResolvedMedia(request.Occurrence, request.ArtworkPath, request.VideoPath, request.VisualizerPath, request.ArtworkGeneration, request.VideoGeneration, request.VisualizerGeneration);
                        });
                    }
                    catch { }
                }
            }
            finally
            {
                lock (_mediaResolveSync)
                {
                    _mediaResolveWorkerActive = false;
                    if (_pendingMediaResolve != null)
                    {
                        _mediaResolveWorkerActive = true;
                        ThreadPool.QueueUserWorkItem(delegate(object nested) { DrainMediaResolveQueue(); });
                    }
                }
            }
        }

        private static string MediaFileGeneration(string path)
        {
            if (String.IsNullOrWhiteSpace(path)) return "";
            try
            {
                var f = new FileInfo(path);
                if (!f.Exists) return "";
                return f.Length.ToString(CultureInfo.InvariantCulture) + "|" + f.LastWriteTimeUtc.Ticks.ToString(CultureInfo.InvariantCulture);
            }
            catch { return ""; }
        }

        private string ResolveMediaSnapshot(string direct, string kind, int occurrence, string sourceKey)
        {
            // R61.77.1: current.json is the authoritative READY projection. An empty reference
            // means the engine has deliberately not published this optional medium yet. Never
            // bypass that decision by scavenging track-N/object-cache files: those may be the
            // poisoned legacy bytes the producer is currently rebuilding at the same path.
            if (String.IsNullOrWhiteSpace(direct)) return "";
            return ResolveMediaReferenceSnapshot(direct, kind, occurrence, sourceKey);
        }

        private string ResolveMediaReferenceSnapshot(string value, string kind, int occurrence, string sourceKey)
        {
            if (String.IsNullOrWhiteSpace(value)) return "";
            value = value.Trim();
            if (Path.IsPathRooted(value) && File.Exists(value))
            {
                // R61.82: current.json is already the producer's READY projection. Do not reject a
                // live authoritative media file merely because a consumer-side sidecar read races
                // publication. The fast path is still provenance constrained to this occurrence's
                // expected YOMI cache lane; arbitrary paths never bypass validation.
                if (IsAuthoritativeCurrentMediaPath(kind, occurrence, value)) return value;
                return ValidatePublishedMediaFile(kind, occurrence, value) ? value : "";
            }
            if (value.StartsWith("/object/", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = value.Trim('/').Split('/');
                if (parts.Length >= 3)
                {
                    string path = Path.Combine(_objectRoot, parts[1], Uri.UnescapeDataString(parts[2]));
                    if (File.Exists(path) && ValidatePublishedMediaFile(kind, occurrence, path)) return path;
                }
            }
            if (value.StartsWith("/media/", StringComparison.OrdinalIgnoreCase))
            {
                string[] parts = value.Trim('/').Split('/');
                int index;
                if (parts.Length >= 3 && Int32.TryParse(parts[2], NumberStyles.Integer, CultureInfo.InvariantCulture, out index))
                    return ResolvePublishedPositionalMedia(parts[1], index);
            }
            return "";
        }

        private bool IsAuthoritativeCurrentMediaPath(string kind, int occurrence, string media)
        {
            if (occurrence < 1 || String.IsNullOrWhiteSpace(media)) return false;
            try
            {
                string normalized = (kind ?? "").Trim().ToLowerInvariant();
                string lane = normalized == "artwork" ? "artwork" : normalized == "video" ? "video" : normalized == "visualizer" ? "visualizer" : "";
                if (lane.Length == 0) return false;
                string root = Path.GetFullPath(Path.Combine(_cacheRoot, lane)).TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) + Path.DirectorySeparatorChar;
                string full = Path.GetFullPath(media);
                if (!full.StartsWith(root, StringComparison.OrdinalIgnoreCase)) return false;
                string name = Path.GetFileName(full).ToLowerInvariant();
                string prefix = "track-" + occurrence.ToString(CultureInfo.InvariantCulture) + ".";
                if (!name.StartsWith(prefix, StringComparison.Ordinal)) return false;
                string ext = Path.GetExtension(name).ToLowerInvariant();
                if (normalized == "video" || normalized == "visualizer") return ext == ".mp4";
                return ext == ".png" || ext == ".jpg" || ext == ".jpeg" || ext == ".webp";
            }
            catch { return false; }
        }

        private string ResolvePublishedPositionalMedia(string kind, int occurrence)
        {
            if (occurrence < 1) return "";
            string normalized = (kind ?? "").Trim().ToLowerInvariant();
            string media = "";
            if (normalized == "video") media = Path.Combine(_cacheRoot, "video", "track-" + occurrence + ".mp4");
            else if (normalized == "visualizer") media = Path.Combine(_cacheRoot, "visualizer", "track-" + occurrence + ".mp4");
            else if (normalized == "artwork")
            {
                foreach (string ext in new[] { "png", "jpg", "jpeg", "webp" })
                {
                    string candidate = Path.Combine(_cacheRoot, "artwork", "track-" + occurrence + "." + ext);
                    if (File.Exists(candidate)) { media = candidate; break; }
                }
            }
            return ValidatePublishedMediaFile(normalized, occurrence, media) ? media : "";
        }

        private bool ValidatePublishedMediaFile(string kind, int occurrence, string media)
        {
            if (occurrence < 1 || String.IsNullOrWhiteSpace(media) || !File.Exists(media)) return false;
            string normalized = (kind ?? "").Trim().ToLowerInvariant();
            string stampKind = normalized == "artwork" ? "art" : normalized == "visualizer" ? "viz" : normalized == "video" ? "video" : "";
            if (String.IsNullOrWhiteSpace(stampKind)) return false;
            long length;
            try { length = new FileInfo(media).Length; } catch { return false; }
            if (length <= 0) return false;
            string sidecar = Path.Combine(_cacheRoot, "status", "track-" + occurrence + "." + stampKind + ".decode-ok");
            string stamp = "";
            try { if (File.Exists(sidecar)) stamp = File.ReadAllText(sidecar).Trim(); } catch { return false; }
            string decodedStamp = "r6176-decode1|" + length.ToString(CultureInfo.InvariantCulture);
            string sourcePassStamp = "r6178-source-pass|" + length.ToString(CultureInfo.InvariantCulture);
            bool decoded = String.Equals(stamp, decodedStamp, StringComparison.Ordinal);
            bool sourcePass = normalized != "visualizer" && String.Equals(stamp, sourcePassStamp, StringComparison.Ordinal);
            if (!decoded && !sourcePass) return false;
            if (normalized == "visualizer")
            {
                string profile = Path.Combine(_cacheRoot, "status", "track-" + occurrence + ".visualizer.profile");
                try { if (!File.Exists(profile) || String.IsNullOrWhiteSpace(File.ReadAllText(profile))) return false; } catch { return false; }
            }
            return true;
        }

        private void ApplyResolvedMedia(int occurrence, string art, string video, string viz, string artGeneration, string videoGeneration, string vizGeneration)
        {
            if (occurrence != _currentOccurrence) return;
            UpdateMediaStateOverlay(art, video);
            int previousMediaOccurrence = _lastMediaOccurrence > 0 ? _lastMediaOccurrence : _pendingTransportOutgoingMediaOccurrence;
            bool trackChanged = previousMediaOccurrence != occurrence;
            bool occurrenceHandoff = trackChanged && previousMediaOccurrence > 0;
            double previewStart = Math.Max(0.0, _timePosition);
            if (trackChanged)
            {
                // R61.104.1: a new track request is not permission to destroy the frame that is
                // currently on screen. Freeze that presentation as a bridge, retire only the
                // track-specific decoders, and let the incoming generation commit atomically.
                CaptureCurrentVideoBridge();
                StopVideoPreview(false);
                // Visualizer teardown is deferred until we know whether a replacement file exists.
                // If it does, the old raw frame becomes a short-lived bridge instead of flashing blank.
                _lastMediaOccurrence = occurrence;
                _pendingTransportOutgoingMediaOccurrence = 0;
                _lastArtworkPath = "";
                _lastVideoPath = "";
                _lastVizPath = "";
                _lastArtworkGeneration = ""; _lastVideoGeneration = ""; _lastVizGeneration = "";
                _videoRequestedPath = "";
                _videoRequestedGeneration = "";
                _videoRequestedOccurrence = occurrence;
                _videoAuthoritativelyAbsent = false;
            }

            if (_mediaMode == MediaMode.Artwork || _mediaMode == MediaMode.Both)
            {
                if (trackChanged || !String.Equals(art, _lastArtworkPath, StringComparison.OrdinalIgnoreCase) || !String.Equals(artGeneration ?? "", _lastArtworkGeneration ?? "", StringComparison.Ordinal))
                {
                    _lastArtworkPath = art;
                    _lastArtworkGeneration = artGeneration ?? "";
                    if (String.IsNullOrWhiteSpace(art) && !ArtworkIsAuthoritativelyAbsent(occurrence))
                        HoldArtworkBridge();
                    else
                        ShowArtwork(art);
                }
                else ApplyArtworkCropPreference();
            }
            else
            {
                _artworkBridgeHold = false;
                _artworkDecodedOriginal = null; _artworkDecodedSmartCrop = null;
                _artworkImage.Source = null;
                if (_artworkCropSurface != null) { _artworkCropSurface.Fill = null; _artworkCropSurface.Visibility = Visibility.Collapsed; }
                _lastArtworkPath = ""; _lastArtworkGeneration = "";
            }

            if (_mediaMode == MediaMode.Video || _mediaMode == MediaMode.Both)
            {
                if (!VideoPreparationEnabled())
                {
                    // Hard Settings authority: ignore even a previously published/cache-valid
                    // path. Off means no stale frame resurrection and no hidden decoder.
                    _lastVideoPath = ""; _lastVideoGeneration = "";
                    _videoAuthoritativelyAbsent = true;
                    _videoRequestedPath = ""; _videoRequestedGeneration = ""; _videoRequestedOccurrence = 0;
                    _videoPresentedPath = ""; _videoPresentedGeneration = ""; _videoPresentedOccurrence = 0;
                    StopVideoPreview(true);
                    if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                    ApplyMediaMode(false);
                }
                else if (String.IsNullOrWhiteSpace(video))
                {
                    _lastVideoPath = ""; _lastVideoGeneration = "";
                    bool absent = !VideoPreparationEnabled() || VideoIsAuthoritativelyAbsent(occurrence);
                    if (absent)
                    {
                        _videoAuthoritativelyAbsent = true;
                        _videoRequestedPath = "";
                        _videoRequestedGeneration = "";
                        _videoRequestedOccurrence = occurrence;
                        StopVideoPreview(true);
                        _videoPresentedPath = "";
                        _videoPresentedGeneration = "";
                        _videoPresentedOccurrence = 0;
                        if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                        ApplyMediaMode(false);
                    }
                    else
                    {
                        // Preparing is deliberately non-destructive. The outgoing bridge stays
                        // visible until this occurrence publishes and commits a real frame.
                        _videoAuthoritativelyAbsent = false;
                        if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                        if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "";
                        ApplyMediaMode(false);
                    }
                }
                else if (!String.Equals(video, _lastVideoPath, StringComparison.OrdinalIgnoreCase) || !String.Equals(videoGeneration ?? "", _lastVideoGeneration ?? "", StringComparison.Ordinal))
                {
                    CaptureCurrentVideoBridge();
                    StopVideoPreview(false);
                    _lastVideoPath = video; _lastVideoGeneration = videoGeneration ?? "";
                    _videoRequestedPath = video;
                    _videoRequestedGeneration = videoGeneration ?? "";
                    _videoRequestedOccurrence = occurrence;
                    _videoAuthoritativelyAbsent = false;
                    _videoPreviewReady = false; _videoPreviewFailed = false; _videoPreviewFailure = "";
                    if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                    if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "";
                    ApplyMediaMode(false);
                    if (!_paused && !_previewPauseState) StartFramePreview(video, previewStart, false);
                }
                else if (_videoPreviewFailed)
                {
                    if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                    if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "";
                }
                else if (!_videoPreviewReady)
                {
                    if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                    if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "";
                }
                else if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
            }
            else
            {
                StopVideoPreview(true);
                _lastVideoPath = ""; _lastVideoGeneration = "";
                _videoRequestedPath = ""; _videoRequestedGeneration = ""; _videoRequestedOccurrence = 0;
                _videoPresentedPath = ""; _videoPresentedGeneration = ""; _videoPresentedOccurrence = 0;
                _videoAuthoritativelyAbsent = true;
                ApplyMediaMode(false);
            }

            if (_visualizerEnabled)
            {
                if (String.IsNullOrWhiteSpace(viz))
                {
                    // A blank snapshot during preparation is not proof that the new occurrence has
                    // no visualizer. Keep the outgoing frame until absence is authoritative.
                    StopVisualizerPreview(!VisualizerIsAuthoritativelyAbsent(occurrence));
                    _lastVizPath = ""; _lastVizGeneration = "";
                    if (_visualizerWaitingText != null) _visualizerWaitingText.Text = "";
                    _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                }
                else if (!String.Equals(viz, _lastVizPath, StringComparison.OrdinalIgnoreCase) || !String.Equals(vizGeneration ?? "", _lastVizGeneration ?? "", StringComparison.Ordinal))
                {
                    StopVisualizerPreview(true);
                    _lastVizPath = viz; _lastVizGeneration = vizGeneration ?? "";
                    _visualizerPreviewReady = false; _visualizerPreviewFailed = false; _visualizerPreviewFailure = "";
                    if (_visualizerWaitingText != null) _visualizerWaitingText.Text = "";
                    _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                    if (!_paused && !_previewPauseState) StartFramePreview(viz, previewStart, true);
                }
                else if (_visualizerPreviewFailed || !_visualizerPreviewReady)
                {
                    if (_visualizerWaitingText != null) _visualizerWaitingText.Text = "";
                    _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                }
                else _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
            }
            else { StopVisualizerPreview(); _lastVizGeneration = ""; _visualizerWaitingOverlay.Visibility = Visibility.Collapsed; }
        }

        private bool VideoIsAuthoritativelyAbsent(int occurrence)
        {
            RuntimeQueueItem runtime;
            if (!_runtimeQueue.TryGetValue(occurrence, out runtime) || runtime == null) return false;
            string stage = (runtime.Video ?? "").Trim().ToUpperInvariant();
            if (stage == "NOT_REQUIRED" || stage == "FAILED_OPTIONAL" || stage == "FAILED_PERMANENT") return true;
            if (runtime.PresentationComplete && stage.StartsWith("DEFERRED_", StringComparison.Ordinal)) return true;
            return false;
        }

        private bool ArtworkIsAuthoritativelyAbsent(int occurrence)
        {
            RuntimeQueueItem runtime;
            if (!_runtimeQueue.TryGetValue(occurrence, out runtime) || runtime == null) return false;
            string stage = (runtime.Artwork ?? "").Trim().ToUpperInvariant();
            if (stage == "NOT_REQUIRED" || stage == "FAILED_OPTIONAL" || stage == "FAILED_PERMANENT") return true;
            if (runtime.PresentationComplete && stage.StartsWith("DEFERRED_", StringComparison.Ordinal)) return true;
            return false;
        }

        private bool VisualizerIsAuthoritativelyAbsent(int occurrence)
        {
            RuntimeQueueItem runtime;
            if (!_runtimeQueue.TryGetValue(occurrence, out runtime) || runtime == null) return false;
            string stage = (runtime.Visualizer ?? "").Trim().ToUpperInvariant();
            if (stage == "NOT_REQUIRED" || stage == "FAILED_OPTIONAL" || stage == "FAILED_PERMANENT") return true;
            if (runtime.PresentationComplete && stage.StartsWith("DEFERRED_", StringComparison.Ordinal)) return true;
            return false;
        }

        private bool VideoRequestMatches(string path, string generation, int occurrence)
        {
            if (occurrence <= 0 || occurrence != _currentOccurrence || occurrence != _videoRequestedOccurrence) return false;
            if (!String.Equals(generation ?? "", _videoRequestedGeneration ?? "", StringComparison.Ordinal)) return false;
            try
            {
                return !String.IsNullOrWhiteSpace(path) && !String.IsNullOrWhiteSpace(_videoRequestedPath) &&
                    String.Equals(Path.GetFullPath(path), Path.GetFullPath(_videoRequestedPath), StringComparison.OrdinalIgnoreCase);
            }
            catch { return String.Equals(path ?? "", _videoRequestedPath ?? "", StringComparison.OrdinalIgnoreCase); }
        }

        private static double NormalizeVideoAspect(double aspect)
        {
            if (Double.IsNaN(aspect) || Double.IsInfinity(aspect) || aspect <= 0.05) return 16.0 / 9.0;
            return Math.Max(0.20, Math.Min(5.0, aspect));
        }

        private void CommitVideoPresentation(string path, string generation, int occurrence, double aspect)
        {
            if (!VideoRequestMatches(path, generation, occurrence)) return;
            _videoPresentedPath = path ?? "";
            _videoPresentedGeneration = generation ?? "";
            _videoPresentedOccurrence = occurrence;
            if (aspect > 0.05) _videoPresentedAspect = NormalizeVideoAspect(aspect);
            _videoAuthoritativelyAbsent = false;
            ApplyMediaMode(false);
            SyncHostedMediaAirspace();
            ClearVideoBridge();
        }

        private void CaptureCurrentVideoBridge()
        {
            if (_videoBridgeHost == null || _videoAuthoritativelyAbsent) return;
            try
            {
                // If a rapid skip arrives while an earlier bridge is already covering warmup,
                // preserve that last committed frame rather than replacing it with transparent input.
                if (_videoBridgeHost.Source != null && _videoBridgeHost.Visibility == Visibility.Visible) return;
                ImageSource snapshot = null;
                if (_videoFrameHost != null && _videoFrameHost.Source != null && _videoFrameHost.Visibility == Visibility.Visible)
                    snapshot = _videoFrameHost.Source;
                else if (_videoHost != null && _videoHost.Visibility == Visibility.Visible && _videoHost.Opacity > 0.5 && _videoHost.ActualWidth >= 2 && _videoHost.ActualHeight >= 2)
                {
                    int w = Math.Max(2, (int)Math.Round(_videoHost.ActualWidth));
                    int h = Math.Max(2, (int)Math.Round(_videoHost.ActualHeight));
                    var bitmap = new RenderTargetBitmap(w, h, 96, 96, PixelFormats.Pbgra32);
                    bitmap.Render(_videoHost);
                    if (bitmap.CanFreeze) bitmap.Freeze();
                    snapshot = bitmap;
                }
                if (snapshot != null)
                {
                    _videoBridgeHost.Source = snapshot;
                    _videoBridgeHost.Visibility = Visibility.Visible;
                }
            }
            catch { }
        }

        private void ClearVideoBridge()
        {
            if (_videoBridgeHost == null) return;
            _videoBridgeHost.Source = null;
            _videoBridgeHost.Visibility = Visibility.Collapsed;
        }

        private static BitmapSource CreateDetachedArtworkBitmap(BitmapSource source)
        {
            if (source == null) return null;
            try
            {
                int width = source.PixelWidth;
                int height = source.PixelHeight;
                if (width <= 0 || height <= 0) return null;
                double dpiX = source.DpiX > 0.0 ? source.DpiX : 96.0;
                double dpiY = source.DpiY > 0.0 ? source.DpiY : 96.0;

                BitmapSource bgra = source;
                if (source.Format != PixelFormats.Bgra32)
                    bgra = new FormatConvertedBitmap(source, PixelFormats.Bgra32, null, 0);

                int stride = checked(width * 4);
                byte[] pixels = new byte[checked(stride * height)];
                bgra.CopyPixels(pixels, stride, 0);

                BitmapSource detached = BitmapSource.Create(width, height, dpiX, dpiY, PixelFormats.Bgra32, null, pixels, stride);
                if (detached.CanFreeze) detached.Freeze();
                return detached;
            }
            catch
            {
                return null;
            }
        }

        private static ImageBrush CreateCenteredArtworkBrush(BitmapSource source, bool cropToFill)
        {
            if (source == null) return null;

            // R61.106.2: never let a UI brush retain a worker-owned WIC decoder/frame.
            // Normal decode now hands us a detached frozen BitmapSource. Keep this guard as
            // a fail-closed boundary so an unexpected apartment-bound source cannot crash
            // the Dispatcher while ImageBrush.Freeze recursively probes BitmapDecoder state.
            BitmapSource safe = source;
            if (!safe.IsFrozen)
            {
                try
                {
                    Dispatcher owner = safe.Dispatcher;
                    if (owner != null && !owner.CheckAccess()) return null;
                    safe = CreateDetachedArtworkBitmap(safe);
                }
                catch { return null; }
            }
            if (safe == null || !safe.IsFrozen) return null;

            var brush = new ImageBrush(safe)
            {
                Stretch = cropToFill ? Stretch.UniformToFill : Stretch.Uniform,
                AlignmentX = AlignmentX.Center,
                AlignmentY = AlignmentY.Center,
                TileMode = TileMode.None
            };
            if (brush.CanFreeze) brush.Freeze();
            return brush;
        }

        private void ApplyArtworkCropPreference()
        {
            if (_artworkImage == null || _artworkCropSurface == null) return;
            var config = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
            bool smartCrop = GetBool(config, "smart_artwork_crop", true);
            bool cropPlayerArt = _artworkPresentation == ArtworkPresentation.Cropped;
            BitmapSource presented = cropPlayerArt && smartCrop && _artworkDecodedSmartCrop != null ? _artworkDecodedSmartCrop : _artworkDecodedOriginal;

            // Player framing is independent from broadcast Smart Crop. Cropped is the default:
            // confidently dead padding is removed and the remainder center-fills the pane.
            // Uncropped always shows the complete original artwork with aspect preserved.
            _artworkSmartCropApplied = cropPlayerArt && smartCrop && _artworkDecodedSmartCrop != null;
            _artworkImage.Source = null;
            _artworkImage.Visibility = Visibility.Collapsed;
            _artworkCropSurface.Fill = CreateCenteredArtworkBrush(presented, cropPlayerArt);
            _artworkCropSurface.Visibility = presented != null ? Visibility.Visible : Visibility.Collapsed;
        }

        private static BitmapSource BuildFlatEdgeArtworkCrop(BitmapSource source, out Int32Rect cropRect)
        {
            string ignored;
            return BuildFlatEdgeArtworkCrop(source, out cropRect, out ignored);
        }

        private static BitmapSource BuildFlatEdgeArtworkCrop(BitmapSource source, out Int32Rect cropRect, out string decision)
        {
            // R61.106.5: Smart Crop is an evidence-based padding detector, not a generic
            // "dark edge = disposable" heuristic. Each side first discovers a flat candidate
            // run, then scores (a) whole-band purity and (b) the actual transition into content.
            // Opposing sides are preferred, but a single side may be removed only when its
            // confidence is extremely high and the opposite edge has no meaningful band.
            //
            // This deliberately fixes both classes seen in the 2026-09-13 recorder:
            // - deep portrait/square padding such as track 220, which the old 42% retention
            //   veto refused to remove even though both black bands were essentially perfect;
            // - designed edge furniture such as the OC ReMix rail on track 223, which the old
            //   90%-flat column rule could mistakenly swallow as padding.
            cropRect = Int32Rect.Empty;
            decision = "none";
            if (source == null || source.PixelWidth < 80 || source.PixelHeight < 40) return null;
            try
            {
                BitmapSource bgra = source;
                if (source.Format != PixelFormats.Bgra32)
                {
                    var converted = new FormatConvertedBitmap(source, PixelFormats.Bgra32, null, 0);
                    if (converted.CanFreeze) converted.Freeze();
                    bgra = converted;
                }

                int width = bgra.PixelWidth, height = bgra.PixelHeight;
                int stride = width * 4;
                byte[] pixels = new byte[stride * height];
                bgra.CopyPixels(pixels, stride, 0);

                Func<int, int, int, int[]> flatColumnColor = delegate(int x, int columnY0, int columnY1)
                {
                    columnY0 = Math.Max(0, Math.Min(height - 1, columnY0));
                    columnY1 = Math.Max(columnY0, Math.Min(height - 1, columnY1));
                    int step = Math.Max(1, (columnY1 - columnY0 + 1) / 180);
                    var rs = new List<int>(); var gs = new List<int>(); var bs = new List<int>();
                    for (int y = columnY0; y <= columnY1; y += step)
                    {
                        int i = y * stride + x * 4;
                        bs.Add(pixels[i]); gs.Add(pixels[i + 1]); rs.Add(pixels[i + 2]);
                    }
                    if (rs.Count < 8) return null;
                    rs.Sort(); gs.Sort(); bs.Sort();
                    int mid = rs.Count / 2;
                    int mr = rs[mid], mg = gs[mid], mb = bs[mid];
                    int near = 0;
                    for (int y = columnY0; y <= columnY1; y += step)
                    {
                        int i = y * stride + x * 4;
                        int db = Math.Abs(pixels[i] - mb), dg = Math.Abs(pixels[i + 1] - mg), dr = Math.Abs(pixels[i + 2] - mr);
                        if (Math.Max(dr, Math.Max(dg, db)) <= 18) near++;
                    }
                    if (near < (int)Math.Ceiling(rs.Count * 0.90)) return null;
                    return new[] { mr, mg, mb };
                };

                Func<int, int, int, int[]> flatRowColor = delegate(int y, int rowX0, int rowX1)
                {
                    rowX0 = Math.Max(0, Math.Min(width - 1, rowX0));
                    rowX1 = Math.Max(rowX0, Math.Min(width - 1, rowX1));
                    int step = Math.Max(1, (rowX1 - rowX0 + 1) / 180);
                    var rs = new List<int>(); var gs = new List<int>(); var bs = new List<int>();
                    for (int x = rowX0; x <= rowX1; x += step)
                    {
                        int i = y * stride + x * 4;
                        bs.Add(pixels[i]); gs.Add(pixels[i + 1]); rs.Add(pixels[i + 2]);
                    }
                    if (rs.Count < 8) return null;
                    rs.Sort(); gs.Sort(); bs.Sort();
                    int mid = rs.Count / 2;
                    int mr = rs[mid], mg = gs[mid], mb = bs[mid];
                    int near = 0;
                    for (int x = rowX0; x <= rowX1; x += step)
                    {
                        int i = y * stride + x * 4;
                        int db = Math.Abs(pixels[i] - mb), dg = Math.Abs(pixels[i + 1] - mg), dr = Math.Abs(pixels[i + 2] - mr);
                        if (Math.Max(dr, Math.Max(dg, db)) <= 18) near++;
                    }
                    if (near < (int)Math.Ceiling(rs.Count * 0.90)) return null;
                    return new[] { mr, mg, mb };
                };

                Func<int[], int[], bool> colorsNear = delegate(int[] a, int[] b)
                {
                    if (a == null || b == null) return false;
                    return Math.Max(Math.Abs(a[0] - b[0]), Math.Max(Math.Abs(a[1] - b[1]), Math.Abs(a[2] - b[2]))) <= 20;
                };

                Func<bool, int, int, int, int[], double[]> scoreVerticalBand =
                    delegate(bool fromLeft, int run, int columnY0, int columnY1, int[] baseColor)
                {
                    if (run <= 0 || baseColor == null) return new[] { 0.0, 0.0 };
                    int xStep = Math.Max(1, run / 180);
                    int yStep = Math.Max(1, (columnY1 - columnY0 + 1) / 240);
                    long total = 0, near = 0;
                    int xStart = fromLeft ? 0 : width - run;
                    int xEnd = fromLeft ? run - 1 : width - 1;
                    for (int x = xStart; x <= xEnd; x += xStep)
                    {
                        for (int y = columnY0; y <= columnY1; y += yStep)
                        {
                            int i = y * stride + x * 4;
                            int db = Math.Abs(pixels[i] - baseColor[2]);
                            int dg = Math.Abs(pixels[i + 1] - baseColor[1]);
                            int dr = Math.Abs(pixels[i + 2] - baseColor[0]);
                            total++;
                            if (Math.Max(dr, Math.Max(dg, db)) <= 20) near++;
                        }
                    }

                    int transitionWidth = Math.Max(4, Math.Min(24, (int)Math.Round(width * 0.012)));
                    int tx0 = fromLeft ? run : Math.Max(0, width - run - transitionWidth);
                    int tx1 = fromLeft ? Math.Min(width - 1, run + transitionWidth - 1) : Math.Max(0, width - run - 1);
                    long transitionTotal = 0, transitionFar = 0;
                    if (tx0 <= tx1)
                    {
                        int txStep = Math.Max(1, (tx1 - tx0 + 1) / 24);
                        for (int x = tx0; x <= tx1; x += txStep)
                        {
                            for (int y = columnY0; y <= columnY1; y += yStep)
                            {
                                int i = y * stride + x * 4;
                                int db = Math.Abs(pixels[i] - baseColor[2]);
                                int dg = Math.Abs(pixels[i + 1] - baseColor[1]);
                                int dr = Math.Abs(pixels[i + 2] - baseColor[0]);
                                transitionTotal++;
                                if (Math.Max(dr, Math.Max(dg, db)) > 35) transitionFar++;
                            }
                        }
                    }
                    return new[] {
                        total <= 0 ? 0.0 : (double)near / (double)total,
                        transitionTotal <= 0 ? 0.0 : (double)transitionFar / (double)transitionTotal
                    };
                };

                Func<bool, int, int, int, int[], double[]> scoreHorizontalBand =
                    delegate(bool fromTop, int run, int rowX0, int rowX1, int[] baseColor)
                {
                    if (run <= 0 || baseColor == null) return new[] { 0.0, 0.0 };
                    int yStep = Math.Max(1, run / 180);
                    int xStep = Math.Max(1, (rowX1 - rowX0 + 1) / 240);
                    long total = 0, near = 0;
                    int yStart = fromTop ? 0 : height - run;
                    int yEnd = fromTop ? run - 1 : height - 1;
                    for (int y = yStart; y <= yEnd; y += yStep)
                    {
                        for (int x = rowX0; x <= rowX1; x += xStep)
                        {
                            int i = y * stride + x * 4;
                            int db = Math.Abs(pixels[i] - baseColor[2]);
                            int dg = Math.Abs(pixels[i + 1] - baseColor[1]);
                            int dr = Math.Abs(pixels[i + 2] - baseColor[0]);
                            total++;
                            if (Math.Max(dr, Math.Max(dg, db)) <= 20) near++;
                        }
                    }

                    int transitionHeight = Math.Max(4, Math.Min(24, (int)Math.Round(height * 0.012)));
                    int ty0 = fromTop ? run : Math.Max(0, height - run - transitionHeight);
                    int ty1 = fromTop ? Math.Min(height - 1, run + transitionHeight - 1) : Math.Max(0, height - run - 1);
                    long transitionTotal = 0, transitionFar = 0;
                    if (ty0 <= ty1)
                    {
                        int tyStep = Math.Max(1, (ty1 - ty0 + 1) / 24);
                        for (int y = ty0; y <= ty1; y += tyStep)
                        {
                            for (int x = rowX0; x <= rowX1; x += xStep)
                            {
                                int i = y * stride + x * 4;
                                int db = Math.Abs(pixels[i] - baseColor[2]);
                                int dg = Math.Abs(pixels[i + 1] - baseColor[1]);
                                int dr = Math.Abs(pixels[i + 2] - baseColor[0]);
                                transitionTotal++;
                                if (Math.Max(dr, Math.Max(dg, db)) > 35) transitionFar++;
                            }
                        }
                    }
                    return new[] {
                        total <= 0 ? 0.0 : (double)near / (double)total,
                        transitionTotal <= 0 ? 0.0 : (double)transitionFar / (double)transitionTotal
                    };
                };

                int scanY0 = Math.Max(0, (int)Math.Round(height * 0.03));
                int scanY1 = Math.Min(height - 1, (int)Math.Round(height * 0.97));
                int horizontalLimit = Math.Max(1, (int)Math.Floor(width * 0.40));
                int horizontalMinimum = Math.Max(6, (int)Math.Ceiling(width * 0.02));
                int leftRaw = 0, rightRaw = 0;
                int[] leftBase = flatColumnColor(0, scanY0, scanY1);
                int[] rightBase = flatColumnColor(width - 1, scanY0, scanY1);
                if (leftBase != null)
                    while (leftRaw < horizontalLimit && colorsNear(flatColumnColor(leftRaw, scanY0, scanY1), leftBase)) leftRaw++;
                if (rightBase != null)
                    while (rightRaw < horizontalLimit && colorsNear(flatColumnColor(width - 1 - rightRaw, scanY0, scanY1), rightBase)) rightRaw++;

                double[] leftScore = scoreVerticalBand(true, leftRaw, scanY0, scanY1, leftBase);
                double[] rightScore = scoreVerticalBand(false, rightRaw, scanY0, scanY1, rightBase);
                bool horizontalPair =
                    leftRaw >= horizontalMinimum && rightRaw >= horizontalMinimum &&
                    leftScore[0] >= 0.985 && rightScore[0] >= 0.985 &&
                    leftScore[1] >= 0.18 && rightScore[1] >= 0.18;
                // R61.106.27 field regression: some true pillarbox artwork contains a dark
                // design rail immediately inside one real content edge. That can make one
                // transition score look weak even when BOTH opposing outer bands are perfectly
                // pure, same-color and almost exactly symmetric. Accept that narrow case only
                // when the bars are deep, balanced and the opposite boundary supplies strong
                // transition evidence. One-sided/decorative rails remain governed by the strict
                // single-edge rules below.
                int horizontalBalanceTolerance = Math.Max(4, (int)Math.Ceiling(width * 0.025));
                bool symmetricDeepPair =
                    leftRaw >= Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.08)) &&
                    rightRaw >= Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.08)) &&
                    Math.Abs(leftRaw - rightRaw) <= horizontalBalanceTolerance &&
                    colorsNear(leftBase, rightBase) &&
                    leftScore[0] >= 0.995 && rightScore[0] >= 0.995 &&
                    Math.Max(leftScore[1], rightScore[1]) >= 0.60 &&
                    (width - leftRaw - rightRaw) >= Math.Max(48, (int)Math.Ceiling(width * 0.18));
                bool leftSingle =
                    leftRaw >= Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.06)) &&
                    leftScore[0] >= 0.995 && leftScore[1] >= 0.60 &&
                    rightRaw < Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.03));
                bool rightSingle =
                    rightRaw >= Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.06)) &&
                    rightScore[0] >= 0.995 && rightScore[1] >= 0.60 &&
                    leftRaw < Math.Max(horizontalMinimum, (int)Math.Ceiling(width * 0.03));

                int left = horizontalPair || symmetricDeepPair || leftSingle ? leftRaw : 0;
                int right = horizontalPair || symmetricDeepPair || rightSingle ? rightRaw : 0;
                int horizontalContent = width - left - right;
                if (horizontalContent < Math.Max(48, (int)Math.Ceiling(width * 0.18)))
                {
                    left = 0; right = 0; horizontalContent = width;
                }

                int contentX0 = left;
                int contentX1 = width - 1 - right;
                int innerPad = Math.Max(1, (int)Math.Round(horizontalContent * 0.03));
                int scanX0 = Math.Min(contentX1, contentX0 + innerPad);
                int scanX1 = Math.Max(scanX0, contentX1 - innerPad);

                int verticalLimit = Math.Max(1, (int)Math.Floor(height * 0.40));
                int verticalMinimum = Math.Max(5, (int)Math.Ceiling(height * 0.02));
                int topRaw = 0, bottomRaw = 0;
                int[] topBase = flatRowColor(0, scanX0, scanX1);
                int[] bottomBase = flatRowColor(height - 1, scanX0, scanX1);
                if (topBase != null)
                    while (topRaw < verticalLimit && colorsNear(flatRowColor(topRaw, scanX0, scanX1), topBase)) topRaw++;
                if (bottomBase != null)
                    while (bottomRaw < verticalLimit && colorsNear(flatRowColor(height - 1 - bottomRaw, scanX0, scanX1), bottomBase)) bottomRaw++;

                double[] topScore = scoreHorizontalBand(true, topRaw, scanX0, scanX1, topBase);
                double[] bottomScore = scoreHorizontalBand(false, bottomRaw, scanX0, scanX1, bottomBase);
                bool verticalPair =
                    topRaw >= verticalMinimum && bottomRaw >= verticalMinimum &&
                    topScore[0] >= 0.985 && bottomScore[0] >= 0.985 &&
                    topScore[1] >= 0.18 && bottomScore[1] >= 0.18;
                bool topSingle =
                    topRaw >= Math.Max(verticalMinimum, (int)Math.Ceiling(height * 0.06)) &&
                    topScore[0] >= 0.995 && topScore[1] >= 0.60 &&
                    bottomRaw < Math.Max(verticalMinimum, (int)Math.Ceiling(height * 0.03));
                bool bottomSingle =
                    bottomRaw >= Math.Max(verticalMinimum, (int)Math.Ceiling(height * 0.06)) &&
                    bottomScore[0] >= 0.995 && bottomScore[1] >= 0.60 &&
                    topRaw < Math.Max(verticalMinimum, (int)Math.Ceiling(height * 0.03));

                int top = verticalPair || topSingle ? topRaw : 0;
                int bottom = verticalPair || bottomSingle ? bottomRaw : 0;
                int verticalContent = height - top - bottom;
                if (verticalContent < Math.Max(36, (int)Math.Ceiling(height * 0.18)))
                {
                    top = 0; bottom = 0; verticalContent = height;
                }

                decision =
                    "L=" + leftRaw.ToString(CultureInfo.InvariantCulture) +
                    " p=" + leftScore[0].ToString("0.000", CultureInfo.InvariantCulture) +
                    " t=" + leftScore[1].ToString("0.000", CultureInfo.InvariantCulture) +
                    (left > 0 ? " keep" : " no") +
                    ";R=" + rightRaw.ToString(CultureInfo.InvariantCulture) +
                    " p=" + rightScore[0].ToString("0.000", CultureInfo.InvariantCulture) +
                    " t=" + rightScore[1].ToString("0.000", CultureInfo.InvariantCulture) +
                    (right > 0 ? " keep" : " no") +
                    (symmetricDeepPair ? " pair=symmetric-deep" : "") +
                    ";T=" + topRaw.ToString(CultureInfo.InvariantCulture) +
                    " p=" + topScore[0].ToString("0.000", CultureInfo.InvariantCulture) +
                    " t=" + topScore[1].ToString("0.000", CultureInfo.InvariantCulture) +
                    (top > 0 ? " keep" : " no") +
                    ";B=" + bottomRaw.ToString(CultureInfo.InvariantCulture) +
                    " p=" + bottomScore[0].ToString("0.000", CultureInfo.InvariantCulture) +
                    " t=" + bottomScore[1].ToString("0.000", CultureInfo.InvariantCulture) +
                    (bottom > 0 ? " keep" : " no");

                if (left == 0 && right == 0 && top == 0 && bottom == 0) return null;

                cropRect = new Int32Rect(left, top, width - left - right, height - top - bottom);
                var crop = new CroppedBitmap(bgra, cropRect);
                if (crop.CanFreeze) crop.Freeze();
                return crop;
            }
            catch (Exception ex)
            {
                cropRect = Int32Rect.Empty;
                decision = "error=" + ex.GetType().Name + ":" + ex.Message;
                return null;
            }
        }

        private static BitmapSource DecodeArtworkBitmap(string path, out string failure)
        {
            failure = "";
            try
            {
                using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
                {
                    BitmapDecoder decoder = BitmapDecoder.Create(stream, BitmapCreateOptions.PreservePixelFormat | BitmapCreateOptions.IgnoreColorProfile, BitmapCacheOption.OnLoad);
                    if (decoder == null || decoder.Frames == null || decoder.Frames.Count == 0)
                    {
                        failure = "WIC returned no image frame";
                        return null;
                    }

                    // R61.106.2: BitmapCacheOption.OnLoad closes the file stream but a BitmapFrame
                    // can still retain apartment-bound decoder state. Copy pixels into a fresh
                    // BitmapSource and freeze THAT object on the decode STA before crossing threads.
                    BitmapSource detached = CreateDetachedArtworkBitmap(decoder.Frames[0]);
                    if (detached == null)
                    {
                        failure = "WIC frame could not be detached from decoder ownership";
                        return null;
                    }
                    return detached;
                }
            }
            catch (Exception ex)
            {
                failure = ex.GetType().Name + ": " + ex.Message;
                return null;
            }
        }

        private void HoldArtworkBridge()
        {
            // Cancel any prior worker's authority without destroying its already-committed brush.
            Interlocked.Increment(ref _artworkDecodeGeneration);
            _artworkDecodeRequestedPath = "";
            _artworkDecodeFailure = "";
            _artworkDecodeCompletedMs = -1;
            _artworkBridgeHold = _artworkCropSurface != null && _artworkCropSurface.Fill != null;
            _artworkDecodeBackend = _artworkBridgeHold ? "bridge" : "none";
            if (_artworkCropSurface != null && _artworkBridgeHold) _artworkCropSurface.Visibility = Visibility.Visible;
            if (_artworkPlaceholder != null) _artworkPlaceholder.Visibility = Visibility.Collapsed;
            if (_artworkPlaceholderText != null) _artworkPlaceholderText.Text = "";
        }

        private void ShowArtwork(string path)
        {
            int generation = Interlocked.Increment(ref _artworkDecodeGeneration);
            _artworkDecodeRequestedPath = path ?? "";
            _artworkDecodeFailure = "";
            _artworkBridgeHold = !String.IsNullOrWhiteSpace(path) && _artworkCropSurface != null && _artworkCropSurface.Fill != null;
            _artworkDecodeBackend = _artworkBridgeHold ? "bridge-warming" : "none";
            _artworkDecodeCompletedMs = -1;
            if (String.IsNullOrWhiteSpace(path))
            {
                _artworkBridgeHold = false;
                _artworkDecodedOriginal = null;
                _artworkDecodedSmartCrop = null;
                _artworkSmartCropRect = Int32Rect.Empty;
                _artworkSmartCropApplied = false;
                _artworkSmartCropDecision = "";
                _artworkImage.Source = null;
                _artworkCropSurface.Fill = null;
                ApplyArtworkCropPreference();
                _artworkPlaceholder.Visibility = Visibility.Collapsed;
                _artworkPlaceholderText.Text = "";
                return;
            }
            _artworkPlaceholder.Visibility = Visibility.Collapsed;
            _artworkPlaceholderText.Text = "";

            // WPF/WIC image decode is apartment-sensitive on some Windows stacks. All file I/O
            // and fallback retries stay on this dedicated STA worker; the WPF dispatcher only
            // receives already-detached/frozen pixel sources.
            Thread decodeThread = new Thread(delegate()
            {
                BitmapSource bitmap = null;
                string failure = "";
                for (int attempt = 0; attempt < 4 && bitmap == null; attempt++)
                {
                    if (!File.Exists(path)) failure = "Cached artwork is not ready";
                    else bitmap = DecodeArtworkBitmap(path, out failure);
                    if (bitmap == null && attempt < 3) Thread.Sleep(35 * (attempt + 1));
                }
                Int32Rect smartCropRect;
                string smartCropDecision;
                BitmapSource smartCrop = BuildFlatEdgeArtworkCrop(bitmap, out smartCropRect, out smartCropDecision);
                TryBeginInvokeUi(DispatcherPriority.Render, delegate
                {
                        if (generation != _artworkDecodeGeneration || !String.Equals(path, _artworkDecodeRequestedPath, StringComparison.OrdinalIgnoreCase)) return;
                        BitmapSource finalBitmap = bitmap;
                        string finalFailure = failure;
                        string backend = bitmap != null ? "sta-wic" : "none";
                        BitmapSource finalSmartCrop = smartCrop;
                        Int32Rect finalSmartCropRect = smartCropRect;
                        string finalSmartCropDecision = smartCropDecision;

                        _artworkCropSurface.Fill = null;
                        _artworkDecodedOriginal = finalBitmap;
                        _artworkDecodedSmartCrop = finalSmartCrop;
                        _artworkSmartCropRect = finalSmartCrop != null ? finalSmartCropRect : Int32Rect.Empty;
                        _artworkSmartCropDecision = finalSmartCropDecision ?? "";
                        ApplyArtworkCropPreference();
                        ApplyMediaMode(false);
                        _artworkBridgeHold = false;
                        _artworkDecodeBackend = backend;
                        _artworkDecodeCompletedMs = _clock.ElapsedMilliseconds;
                        _artworkDecodeFailure = finalBitmap != null ? "" : finalFailure;
                        if (finalBitmap != null)
                        {
                            _artworkPlaceholder.Visibility = Visibility.Collapsed;
                            string cropNote = finalSmartCrop != null ?
                                " crop=" + finalSmartCropRect.X.ToString(CultureInfo.InvariantCulture) + "," + finalSmartCropRect.Y.ToString(CultureInfo.InvariantCulture) + "," + finalSmartCropRect.Width.ToString(CultureInfo.InvariantCulture) + "x" + finalSmartCropRect.Height.ToString(CultureInfo.InvariantCulture) : " crop=none";
                            WritePreviewRendererLog("ARTWORK OPEN " + path + " backend=" + backend +
                                " size=" + finalBitmap.PixelWidth.ToString(CultureInfo.InvariantCulture) + "x" + finalBitmap.PixelHeight.ToString(CultureInfo.InvariantCulture) + cropNote);
                        }
                        else
                        {
                            // Keep retry authority explicit. Clearing the remembered path makes the
                            // next media-state safety probe re-enter the decoder instead of leaving a
                            // valid producer file permanently unbound.
                            _lastArtworkPath = ""; _lastArtworkGeneration = "";
                            _artworkPlaceholder.Visibility = Visibility.Collapsed;
                            _artworkPlaceholderText.Text = "";
                            WritePreviewRendererLog("ARTWORK DECODE FAILURE " + path + " " + (finalFailure ?? ""));
                        }
                        SchedulePresentationStatusWrite(true);
                });
            });
            decodeThread.IsBackground = true;
            decodeThread.Name = "YOMI Thumbnail Decode";
            try { decodeThread.SetApartmentState(ApartmentState.STA); } catch { }
            decodeThread.Start();
        }

        private string ResolvePreviewMpv()
        {
            foreach (string candidate in new[]
            {
                Path.Combine(_runtimeRoot, "mpv", "mpv.exe"),
                Path.Combine(_runtimeRoot, "mpv.exe")
            })
            {
                if (File.Exists(candidate))
                    return candidate;
            }
            return "";
        }

        private void LoadPreviewMedia(MediaElement media, string file, double start, bool visualizer)
        {
            if (media == null || String.IsNullOrWhiteSpace(file) || !File.Exists(file)) return;
            try
            {
                if (visualizer) _visualizerPreviewStartSeconds = Math.Max(0, start);
                else _videoPreviewStartSeconds = Math.Max(0, start);
                media.Stop();
                media.Source = new Uri(file, UriKind.Absolute);
                // Manual MediaElement playback opens the local file asynchronously.
                // MediaOpened performs the authoritative seek and pause/play projection.
                media.Play();
            }
            catch (Exception ex)
            {
                if (visualizer)
                {
                    _visualizerPreviewFailed = true; _visualizerPreviewReady = false; _visualizerPreviewFailure = ex.Message;
                    if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                }
                else
                {
                    _videoPreviewFailed = true; _videoPreviewReady = false; _videoPreviewFailure = ex.Message;
                    if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Visible;
                    if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "Video preview could not open | INFO has details";
                }
            }
        }

        private string ResolvePreviewFfmpeg()
        {
            foreach (string candidate in new[]
            {
                Path.Combine(_runtimeRoot, "ffmpeg", "ffmpeg.exe"),
                Path.Combine(_runtimeRoot, "ffmpeg.exe")
            })
            {
                if (File.Exists(candidate)) return candidate;
            }
            return "";
        }

        private string DiagnosticLogContext()
        {
            string runtime = String.IsNullOrWhiteSpace(_diagnosticRuntimeId) ? "-" : _diagnosticRuntimeId.Substring(0, Math.Min(12, _diagnosticRuntimeId.Length));
            string session = String.IsNullOrWhiteSpace(_sessionId) ? "-" : _sessionId.Substring(0, Math.Min(12, _sessionId.Length));
            string controller = _controllerDiagnosticSession.Substring(0, Math.Min(12, _controllerDiagnosticSession.Length));
            return "[runtime=" + runtime + " session=" + session + " controller=" + controller + "] ";
        }

        private void WritePreviewRendererLog(string text)
        {
            string line = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) + " " + DiagnosticLogContext() + (text ?? "") + Environment.NewLine;
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try
                {
                    string dir = Path.Combine(_dataRoot, "logs");
                    Directory.CreateDirectory(dir);
                    File.AppendAllText(Path.Combine(dir, "preview-renderer.log"), line, new UTF8Encoding(false));
                }
                catch { }
            });
        }

        private void WriteControllerPerformanceLogAsync(string text)
        {
            string line = DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) + " " + DiagnosticLogContext() + (text ?? "") + Environment.NewLine;
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try
                {
                    string dir = Path.Combine(_dataRoot, "logs");
                    Directory.CreateDirectory(dir);
                    File.AppendAllText(Path.Combine(dir, "controller-performance.log"), line, new UTF8Encoding(false));
                }
                catch { }
            });
        }

        private void StartFramePreview(string file, double start, bool visualizer)
        {
            StartFramePreview(file, start, visualizer, false);
        }

        private void StartFramePreview(string file, double start, bool visualizer, bool forceRestart)
        {
            if (_performanceWorkspace || String.IsNullOrWhiteSpace(file) || !File.Exists(file)) return;
            double fps = visualizer ? Math.Max(30, Math.Min(60, _visualizerFramePreviewFps)) : Math.Max(24, Math.Min(60, _videoFramePreviewFps));

            // R61.94: real cached video stays on native H.264. The tiny local visualizer does not.
            // Field R61.91 proved the second MediaElement/MF pipeline alone can consume roughly
            // 1.3-2.2 CPU cores even after all seek/play heartbeat bugs are removed.
            if (visualizer)
            {
                if (!String.IsNullOrWhiteSpace(_previewFfmpegPath) && File.Exists(_previewFfmpegPath) && _visualizerFrameHost != null)
                {
                    WritePreviewRendererLog("VISUALIZER RAW PREFERRED " +
                        _visualizerRawFrameWidth.ToString(CultureInfo.InvariantCulture) + "x" +
                        _visualizerRawFrameHeight.ToString(CultureInfo.InvariantCulture) + " @ " +
                        fps.ToString("0.###", CultureInfo.InvariantCulture) + " FPS");
                    StartRawFramePreviewCore(file, start, true, fps, forceRestart);
                    return;
                }
                // R61.94 binary-color invariant: never fall back to MediaElement for the visualizer.
                // Native H.264 presentation can synthesize gray/chroma edge shades; absence is
                // preferable to displaying a visualizer that violates its two-color contract.
                SetFramePreviewFailure(true, "Binary visualizer decoder is unavailable.");
                return;
            }

            if (TryStartNativePreview(file, start, false, fps, forceRestart)) return;
            StartRawPreviewWithRateProbe(file, start, false, fps, forceRestart);
        }

        private bool TryStartNativePreview(string file, double start, bool visualizer, double fps, bool forceSeek)
        {
            MediaElement media = visualizer ? _visualizerHost : _videoHost;
            if (media == null) return false;
            string full;
            try { full = Path.GetFullPath(file); } catch { return false; }
            string generationToken = visualizer ? (_lastVizGeneration ?? "") : (_lastVideoGeneration ?? "");
            string identity = (full + "|native|" + generationToken).ToLowerInvariant();
            string currentIdentity = visualizer ? _visualizerNativePreviewIdentity : _videoNativePreviewIdentity;
            bool active = visualizer ? _visualizerNativePreviewActive : _videoNativePreviewActive;
            string backend = visualizer ? _visualizerPreviewBackend : _videoPreviewBackend;
            if (String.Equals(currentIdentity, identity, StringComparison.Ordinal) &&
                (active || backend == "native-opening" || backend == "native-settling"))
            {
                if (visualizer) _visualizerPreviewStartSeconds = Math.Max(0, start); else _videoPreviewStartSeconds = Math.Max(0, start);
                if (active && String.Equals(backend, "native-media", StringComparison.Ordinal))
                {
                    if (visualizer) { _visualizerPreviewReady = true; _visualizerPreviewFailed = false; _visualizerPreviewFailure = ""; }
                    else { _videoPreviewReady = true; _videoPreviewFailed = false; _videoPreviewFailure = ""; }
                    try
                    {
                        double current = media.Position.TotalSeconds;
                        if (forceSeek || Math.Abs(current - start) > 0.75) SetPreviewPosition(media, start);
                    }
                    catch { }
                }
                // Opening/settling is a real state. Duplicate refreshes may update the desired
                // seek position, but may never promote a hidden warmup to presented media.
                SyncHostedMediaAirspace();
                return true;
            }

            int generation;
            if (visualizer)
            {
                generation = ++_visualizerNativePreviewGeneration;
                _visualizerNativePreviewIdentity = identity;
                _visualizerNativePreviewFile = full;
                _visualizerNativePreviewTargetFps = fps;
                _visualizerPreviewStartSeconds = Math.Max(0, start);
                _visualizerNativePreviewActive = false;
                _visualizerPreviewBackend = "native-opening";
                if (_visualizerFramePreview != null) { try { _visualizerFramePreview.Dispose(); } catch { } _visualizerFramePreview = null; }
                if (_visualizerFrameHost != null) { _visualizerFrameHost.Source = null; _visualizerFrameHost.Visibility = Visibility.Collapsed; }
            }
            else
            {
                generation = ++_videoNativePreviewGeneration;
                _videoNativePreviewIdentity = identity;
                _videoNativePreviewFile = full;
                _videoNativePreviewTargetFps = fps;
                _videoPreviewStartSeconds = Math.Max(0, start);
                _nativeVideoClockBadSamples = 0;
                _videoNativePreviewActive = false;
                _videoPreviewBackend = "native-opening";
                if (_videoFramePreview != null) { try { _videoFramePreview.Dispose(); } catch { } _videoFramePreview = null; }
                if (_videoFrameHost != null) { _videoFrameHost.Source = null; _videoFrameHost.Visibility = Visibility.Collapsed; }
            }
            try
            {
                DetachNativePreviewHandlers(media, visualizer);
                ClosePreviewElement(media);
                AttachNativePreviewHandlers(media, visualizer, full, generation);
                media.Visibility = Visibility.Visible;
                media.Opacity = visualizer ? 1.0 : 0.0;
                media.Source = new Uri(full, UriKind.Absolute);
                WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " NATIVE START " + full + " @ " + start.ToString("0.###", CultureInfo.InvariantCulture));
                media.Play();
                if (_paused || _previewPauseState || (_pauseIntentPending && _pauseIntentState)) media.Pause();
            }
            catch (Exception ex)
            {
                FallbackNativePreview(visualizer, generation, "native start: " + ex.GetType().Name + " " + ex.Message);
                return true;
            }

            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                Thread.Sleep(1800);
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                        int liveGeneration = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
                        bool liveActive = visualizer ? _visualizerNativePreviewActive : _videoNativePreviewActive;
                        string liveBackend = visualizer ? _visualizerPreviewBackend : _videoPreviewBackend;
                        if (generation == liveGeneration && !liveActive && liveBackend == "native-opening")
                            FallbackNativePreview(visualizer, generation, "native open timeout after 1800ms");
                    });
                }
                catch { }
            });
            return true;
        }

        private void ApplyNativePreviewPlayState(MediaElement media)
        {
            if (media == null) return;
            bool paused = _pauseIntentPending ? _pauseIntentState : (_paused || _previewPauseState);
            try { if (paused) media.Pause(); else media.Play(); } catch { }
        }

        private void FallbackNativePreview(bool visualizer, int generation, string reason)
        {
            int liveGeneration = visualizer ? _visualizerNativePreviewGeneration : _videoNativePreviewGeneration;
            if (generation != liveGeneration) return;
            string backend = visualizer ? _visualizerPreviewBackend : _videoPreviewBackend;
            if (backend == "ffmpeg-raw") return;
            string file = visualizer ? _visualizerNativePreviewFile : _videoNativePreviewFile;
            double start = visualizer ? _visualizerPreviewStartSeconds : _videoPreviewStartSeconds;
            double fps = visualizer ? _visualizerNativePreviewTargetFps : _videoNativePreviewTargetFps;
            MediaElement media = visualizer ? _visualizerHost : _videoHost;
            DetachNativePreviewHandlers(media, visualizer);
            if (visualizer) { _visualizerNativePreviewActive = false; _visualizerPreviewBackend = "ffmpeg-raw"; }
            else { _videoNativePreviewActive = false; _nativeVideoClockBadSamples = 0; _videoPreviewBackend = "ffmpeg-raw"; }
            ClosePreviewElement(media);
            if (media != null) { media.Visibility = Visibility.Collapsed; media.Opacity = 1.0; }
            WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " NATIVE FALLBACK " + reason);
            if (visualizer) StartRawFramePreviewCore(file, start, true, fps, true);
            else StartRawPreviewWithRateProbe(file, start, false, fps, true);
        }

        private void StartRawPreviewWithRateProbe(string file, double start, bool visualizer, double fallbackFps, bool forceRestart)
        {
            if (visualizer)
            {
                StartRawFramePreviewCore(file, start, true, fallbackFps, forceRestart);
                return;
            }
            int generation = Interlocked.Increment(ref _videoPreviewProbeGeneration);
            string requestedFile = file ?? "";
            double requestedStart = start;
            string ffmpeg = _previewFfmpegPath ?? "";
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                double sourceFps; double sourceAspect;
                ProbeSourceVideo(ffmpeg, requestedFile, out sourceFps, out sourceAspect);
                if (sourceFps < 1.0 || sourceFps > 120.0) sourceFps = fallbackFps;
                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    if (generation != _videoPreviewProbeGeneration || !String.Equals(requestedFile, _videoRequestedPath, StringComparison.OrdinalIgnoreCase)) return;
                    if (!VideoRequestMatches(requestedFile, _videoRequestedGeneration, _videoRequestedOccurrence)) return;
                    StartRawFramePreviewCore(requestedFile, requestedStart, false, sourceFps, forceRestart, sourceAspect);
                });
            });
        }

        private static bool TryParseFfprobeFraction(string token, out double value)
        {
            value = 0;
            if (String.IsNullOrWhiteSpace(token)) return false;
            string[] parts = token.Trim().Split('/');
            if (parts.Length == 2)
            {
                double a, b;
                if (Double.TryParse(parts[0], NumberStyles.Float, CultureInfo.InvariantCulture, out a) &&
                    Double.TryParse(parts[1], NumberStyles.Float, CultureInfo.InvariantCulture, out b) && Math.Abs(b) > 0.0000001)
                {
                    value = a / b;
                    return true;
                }
                return false;
            }
            return Double.TryParse(token.Trim(), NumberStyles.Float, CultureInfo.InvariantCulture, out value);
        }

        private static void ParseSourceVideoProbeText(string output, out double frameRate, out double aspect)
        {
            frameRate = 0; aspect = 0;
            double width = 0, height = 0;
            foreach (string raw in (output ?? "").Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries))
            {
                string line = raw.Trim();
                int eq = line.IndexOf('=');
                if (eq <= 0 || eq >= line.Length - 1) continue;
                string key = line.Substring(0, eq).Trim();
                string value = line.Substring(eq + 1).Trim();
                double parsed;
                if (String.Equals(key, "width", StringComparison.OrdinalIgnoreCase))
                {
                    if (Double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out parsed)) width = parsed;
                }
                else if (String.Equals(key, "height", StringComparison.OrdinalIgnoreCase))
                {
                    if (Double.TryParse(value, NumberStyles.Float, CultureInfo.InvariantCulture, out parsed)) height = parsed;
                }
                else if (String.Equals(key, "avg_frame_rate", StringComparison.OrdinalIgnoreCase))
                {
                    if (TryParseFfprobeFraction(value, out parsed) && parsed >= 1.0 && parsed <= 120.0) frameRate = parsed;
                }
            }
            if (width > 0 && height > 0) aspect = width / height;
        }

        private void ProbeSourceVideo(string ffmpegPath, string file, out double frameRate, out double aspect)
        {
            frameRate = 0; aspect = 0;
            try
            {
                string dir = Path.GetDirectoryName(ffmpegPath ?? "") ?? "";
                string ffprobe = Path.Combine(dir, "ffprobe.exe");
                if (!File.Exists(ffprobe) || !File.Exists(file)) return;
                var psi = new ProcessStartInfo
                {
                    FileName = ffprobe,
                    // Named fields avoid depending on ffprobe CSV column ordering. R61.106.14
                    // assumed fps,width,height and could therefore turn a 480x360 source into an
                    // unknown aspect, causing raw fallback to jump from 4:3 to 16:9.
                    Arguments = "-v error -select_streams v:0 -show_entries stream=width,height,avg_frame_rate -of default=noprint_wrappers=1:nokey=0 " + Quote(file),
                    UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true,
                    WorkingDirectory = dir
                };
                ConfigureContainedChildProcessStartInfo(psi);
                using (var process = Process.Start(psi))
                {
                    if (process == null) return;
                    string output = process.StandardOutput.ReadToEnd();
                    if (!process.WaitForExit(2200)) { try { process.Kill(); } catch { } return; }
                    ParseSourceVideoProbeText(output, out frameRate, out aspect);
                }
                if (aspect > 0.05)
                    WritePreviewRendererLog("VIDEO SOURCE PROBE " + file + " aspect=" + aspect.ToString("0.####", CultureInfo.InvariantCulture) + " fps=" + frameRate.ToString("0.###", CultureInfo.InvariantCulture));
            }
            catch { }
        }

        private void StartRawFramePreviewCore(string file, double start, bool visualizer, double fps, bool forceRestart)
        {
            StartRawFramePreviewCore(file, start, visualizer, fps, forceRestart, 0.0);
        }

        private void StartRawFramePreviewCore(string file, double start, bool visualizer, double fps, bool forceRestart, double videoAspectHint)
        {
            if (_performanceWorkspace) return;
            string ffmpeg = _previewFfmpegPath ?? "";
            Image target = visualizer ? _visualizerFrameHost : _videoFrameHost;
            if (target == null) return;
            if (visualizer)
            {
                _visualizerNativePreviewActive = false;
                _visualizerPreviewBackend = "ffmpeg-raw";
                ClosePreviewElement(_visualizerHost);
                if (_visualizerHost != null) _visualizerHost.Visibility = Visibility.Collapsed;
            }
            else
            {
                _videoNativePreviewActive = false;
                _videoPreviewBackend = "ffmpeg-raw";
                ClosePreviewElement(_videoHost);
                if (_videoHost != null) _videoHost.Visibility = Visibility.Collapsed;
            }
            if (String.IsNullOrWhiteSpace(ffmpeg))
            {
                string reason = "Bundled FFmpeg decoder is missing.";
                SetFramePreviewFailure(visualizer, reason);
                return;
            }
            if (String.IsNullOrWhiteSpace(file)) return;

            fps = Math.Max(1.0, Math.Min(120.0, fps));
            string generationToken = visualizer ? (_lastVizGeneration ?? "") : (_lastVideoGeneration ?? "");
            string previewIdentity = (Path.GetFullPath(file) + "|" + generationToken + "|" + fps.ToString("0.###", CultureInfo.InvariantCulture) + "|" + (visualizer ? "visualizer" : "video") + (visualizer ? "" : "|" + FfmpegScaleFlagFor(_videoScaleFilter))).ToLowerInvariant();
            long previewRequestMs = _clock.ElapsedMilliseconds;
            FfmpegFramePreview existingPreview = visualizer ? _visualizerFramePreview : _videoFramePreview;
            string existingIdentity = visualizer ? _visualizerPreviewIdentity : _videoPreviewIdentity;
            if (!forceRestart && existingPreview != null && existingPreview.CanCoalesce && String.Equals(existingIdentity, previewIdentity, StringComparison.Ordinal))
            {
                existingPreview.UpdateClock(start, _paused || (_pauseIntentPending && _pauseIntentState));
                return;
            }

            int visualizerRawGeneration = 0;
            int videoRawGeneration = 0;
            int videoRequestOccurrence = _videoRequestedOccurrence;
            string videoRequestGeneration = _videoRequestedGeneration ?? "";
            double committedAspect = 0.0;
            try
            {
                if (!visualizer && videoRequestOccurrence > 0 && videoRequestOccurrence == _videoPresentedOccurrence &&
                    !String.IsNullOrWhiteSpace(_videoPresentedPath) && !String.IsNullOrWhiteSpace(file) &&
                    String.Equals(Path.GetFullPath(file), Path.GetFullPath(_videoPresentedPath), StringComparison.OrdinalIgnoreCase))
                    committedAspect = NormalizeVideoAspect(_videoPresentedAspect);
            }
            catch { }
            double videoRequestAspect = videoAspectHint > 0.05 ? NormalizeVideoAspect(videoAspectHint)
                : (committedAspect > 0.05 ? committedAspect : 16.0 / 9.0);
            if (visualizer)
            {
                visualizerRawGeneration = ++_visualizerRawPreviewGeneration;
                if (_visualizerFramePreview != null) { try { _visualizerFramePreview.Dispose(); } catch { } }
                _visualizerFramePreview = null;
                _visualizerPreviewIdentity = previewIdentity;
                _visualizerPreviewLaunchMs = previewRequestMs;
                _visualizerPreviewStartSeconds = Math.Max(0, start);
            }
            else
            {
                videoRawGeneration = ++_videoRawPreviewGeneration;
                if (_videoFramePreview != null) { try { _videoFramePreview.Dispose(); } catch { } }
                _videoFramePreview = null;
                _videoPreviewIdentity = previewIdentity;
                _videoPreviewLaunchMs = previewRequestMs;
                _videoPreviewStartSeconds = Math.Max(0, start);
            }

            // Controller preview is deliberately lower-resolution than OBS output. WPF scales
            // these frames to the visible surface; keeping raw bitmap traffic small prevents
            // preview work from competing with operator input.
            int width;
            int height;
            if (visualizer)
            {
                width = Math.Max(16, _visualizerRawFrameWidth);
                height = Math.Max(4, _visualizerRawFrameHeight);
            }
            else
            {
                // Keep fallback raster proportional to the actual source. A fixed 256x144 bitmap
                // with black padding would reintroduce letterbox bars inside the independently
                // framed 4:3/portrait video rectangle. Keep roughly the same pixel budget instead.
                double rawAspect = videoRequestAspect > 0.05 ? NormalizeVideoAspect(videoRequestAspect) : 16.0 / 9.0;
                if (rawAspect <= 16.0 / 9.0)
                {
                    height = 144;
                    width = Math.Max(32, (int)Math.Round(height * rawAspect));
                }
                else
                {
                    width = 256;
                    height = Math.Max(32, (int)Math.Round(width / rawAspect));
                }
            }
            string visualizerColor = "#8A8A84";
            string visualizerColorMode = "Solid";
            if (visualizer)
            {
                try
                {
                    Dictionary<string, object> visualizerConfig = ReadJsonCached(Path.Combine(_dataRoot, "config.json"));
                    visualizerColor = GetString(visualizerConfig, "visualizer_solid_color", "#8A8A84");
                    visualizerColorMode = GetString(visualizerConfig, "visualizer_color_mode", "Solid");
                }
                catch { }
                if (String.IsNullOrWhiteSpace(visualizerColor) || !System.Text.RegularExpressions.Regex.IsMatch(visualizerColor, "^#[0-9A-Fa-f]{6}$")) visualizerColor = "#8A8A84";
            }
            int vizR = visualizer ? Int32.Parse(visualizerColor.Substring(1,2), NumberStyles.HexNumber, CultureInfo.InvariantCulture) : 0;
            int vizG = visualizer ? Int32.Parse(visualizerColor.Substring(3,2), NumberStyles.HexNumber, CultureInfo.InvariantCulture) : 0;
            int vizB = visualizer ? Int32.Parse(visualizerColor.Substring(5,2), NumberStyles.HexNumber, CultureInfo.InvariantCulture) : 0;
            // Solid retains the exact-color cleanup that removes H.264 chroma/edge shades.
            // Gradient/Rainbow are already fully colored by music.lua, so repainting them here
            // would destroy the palette and make Controller disagree with OBS.
            string visualizerPost = "";
            if (visualizer && String.Equals(visualizerColorMode, "Solid", StringComparison.OrdinalIgnoreCase))
                visualizerPost = ",format=gray,lut=y='if(gt(val,3),255,0)',format=rgb24,lutrgb=r='if(gt(val,0)," + vizR.ToString(CultureInfo.InvariantCulture) + ",0)':g='if(gt(val,0)," + vizG.ToString(CultureInfo.InvariantCulture) + ",0)':b='if(gt(val,0)," + vizB.ToString(CultureInfo.InvariantCulture) + ",0)',format=bgra";
            else if (visualizer)
                visualizerPost = ",format=bgra";
            string filter = visualizer
                ? "fps=" + Math.Round(fps).ToString(CultureInfo.InvariantCulture) + ",scale=" +
                    width.ToString(CultureInfo.InvariantCulture) + ":" + height.ToString(CultureInfo.InvariantCulture) +
                    ":flags=neighbor" + visualizerPost
                : "scale=" + width.ToString(CultureInfo.InvariantCulture) + ":" + height.ToString(CultureInfo.InvariantCulture) + ":flags=" + FfmpegScaleFlagFor(_videoScaleFilter) + ",format=bgra";

            // Do not use FFmpeg -re here. The frame reader owns realtime pacing and can
            // discard startup-late frames, which prevents process launch time from becoming
            // permanent preview lag.
            string args = "-hide_banner -loglevel error -nostdin -ss " + Math.Max(0, start).ToString("0.###", CultureInfo.InvariantCulture) +
                " -stream_loop -1 -i " + Quote(file) + " -an -sn -dn -vf " + Quote(filter) +
                " -fps_mode passthrough -threads 1 -filter_threads 1 -f rawvideo -pix_fmt bgra pipe:1";

            long previewStartedMs = _clock.ElapsedMilliseconds;
            WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " START " + file + " @ " + start.ToString("0.###", CultureInfo.InvariantCulture) + " | " + fps.ToString("0.###", CultureInfo.InvariantCulture) + " FPS");
            long lastCadenceLogMs = -5000;
            var preview = new FfmpegFramePreview(ffmpeg, args, target, width, height, fps, start, visualizer,
                delegate(PreviewCadenceMetrics metrics)
                {
                    double actualFps = metrics != null ? metrics.DeliveredFps : 0;
                    if (visualizer) _visualizerPreviewActualFps = actualFps; else _videoPreviewActualFps = actualFps;
                    string cadence = metrics == null ? "" : " | jitter " + metrics.JitterRmsMs.ToString("0.00", CultureInfo.InvariantCulture) + " ms RMS | p95 " + metrics.P95IntervalErrorMs.ToString("0.00", CultureInfo.InvariantCulture) + " ms";
                    if (visualizer && _visualizerFrameHost != null) _visualizerFrameHost.ToolTip = "Local controller preview | target " + fps.ToString("0.###", CultureInfo.InvariantCulture) + " FPS | delivered " + actualFps.ToString("0.0", CultureInfo.InvariantCulture) + " FPS" + cadence;
                    if (!visualizer && _videoFrameHost != null) _videoFrameHost.ToolTip = "Local controller preview | target " + fps.ToString("0.###", CultureInfo.InvariantCulture) + " FPS | delivered " + actualFps.ToString("0.0", CultureInfo.InvariantCulture) + " FPS" + cadence;
                    long cadenceNow = _clock.ElapsedMilliseconds;
                    if (metrics != null && cadenceNow - lastCadenceLogMs >= 5000)
                    {
                        lastCadenceLogMs = cadenceNow;
                        WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " CADENCE target=" + fps.ToString("0.###", CultureInfo.InvariantCulture) + " " + metrics.ToString());
                        SchedulePresentationStatusWrite(false);
                    }
                },
                delegate(ProcessStartInfo psi) { ConfigureContainedChildProcessStartInfo(psi); },
                delegate(Process process) { return OwnAuxiliaryProcessWithRuntimeJob(process); },
                delegate
                {
                    if (visualizer)
                    {
                        if (visualizerRawGeneration != _visualizerRawPreviewGeneration ||
                            !_visualizerEnabled ||
                            !String.Equals(file, _lastVizPath, StringComparison.OrdinalIgnoreCase)) return;
                        _visualizerBridgeHold = false;
                        _visualizerPreviewReady = true; _visualizerPreviewFailed = false; _visualizerPreviewFailure = "";
                        if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                    }
                    else
                    {
                        if (videoRawGeneration != _videoRawPreviewGeneration || !VideoRequestMatches(file, videoRequestGeneration, videoRequestOccurrence)) return;
                        _videoPreviewReady = true; _videoPreviewFailed = false; _videoPreviewFailure = "";
                        if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                        CommitVideoPresentation(file, videoRequestGeneration, videoRequestOccurrence, videoRequestAspect);
                    }
                    long firstFrameMs = Math.Max(0, _clock.ElapsedMilliseconds - previewStartedMs);
                    WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " FIRST FRAME +" + firstFrameMs.ToString(CultureInfo.InvariantCulture) + "ms");
                    SchedulePresentationStatusWrite(true);
                },
                delegate(string reason)
                {
                    if (visualizer &&
                        visualizerRawGeneration == _visualizerRawPreviewGeneration &&
                        _visualizerEnabled &&
                        String.Equals(file, _lastVizPath, StringComparison.OrdinalIgnoreCase))
                    {
                        // R61.94 binary-color invariant: a failed raw decode stays absent rather
                        // than falling through to MediaElement and displaying codec-created shades.
                        FfmpegFramePreview failedPreview = _visualizerFramePreview;
                        _visualizerFramePreview = null;
                        if (failedPreview != null) { try { failedPreview.Dispose(); } catch { } }
                        WritePreviewRendererLog("VISUALIZER BINARY RAW STOP " + (reason ?? ""));
                        SetFramePreviewFailure(true, reason);
                        return;
                    }
                    if (!visualizer && (videoRawGeneration != _videoRawPreviewGeneration || !VideoRequestMatches(file, videoRequestGeneration, videoRequestOccurrence))) return;
                    SetFramePreviewFailure(visualizer, reason);
                });

            if (visualizer) _visualizerFramePreview = preview; else _videoFramePreview = preview;
            preview.UpdateClock(start, _paused || (_pauseIntentPending && _pauseIntentState));
            preview.Start();
        }

        private void SetFramePreviewFailure(bool visualizer, string reason)
        {
            reason = String.IsNullOrWhiteSpace(reason) ? "FFmpeg preview renderer stopped before producing a frame." : reason.Trim();
            WritePreviewRendererLog((visualizer ? "VISUALIZER" : "VIDEO") + " FAIL " + reason);
            if (visualizer)
            {
                _visualizerPreviewFailed = true; _visualizerPreviewReady = false; _visualizerPreviewFailure = reason;
                _visualizerBridgeHold = false;
                if (_visualizerFrameHost != null) { _visualizerFrameHost.Source = null; _visualizerFrameHost.Visibility = Visibility.Collapsed; }
                if (_visualizerWaitingText != null) _visualizerWaitingText.Text = "";
                if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                AddActivity("Visualizer preview", "decoder failed | Operations Center has details");
            }
            else
            {
                _videoPreviewFailed = true; _videoPreviewReady = false; _videoPreviewFailure = reason;
                if (_videoPlaceholder != null) _videoPlaceholder.Visibility = Visibility.Collapsed;
                if (_videoPlaceholderText != null) _videoPlaceholderText.Text = "";
                AddActivity("Video preview", "decoder failed | Operations Center has details");
            }
            SchedulePresentationStatusWrite(true);
        }

        private void RestartFramePreviewsAt(double target)
        {
            RestartFramePreviewsAt(target, false);
        }

        private void RestartFramePreviewsAt(double target, bool allowWhileAuthoritativePauseStillSettles)
        {
            if (_paused && !allowWhileAuthoritativePauseStillSettles) return;
            if ((_mediaMode == MediaMode.Video || _mediaMode == MediaMode.Both) && !String.IsNullOrWhiteSpace(_lastVideoPath))
            {
                _videoPreviewReady = false; _videoPreviewFailed = false; _videoPreviewFailure = "";
                if (_videoPlaceholder != null) { _videoPlaceholder.Visibility = Visibility.Collapsed; _videoPlaceholderText.Text = ""; }
                StartFramePreview(_lastVideoPath, target, false, true);
            }
            if (_visualizerEnabled && !String.IsNullOrWhiteSpace(_lastVizPath))
            {
                _visualizerPreviewReady = false; _visualizerPreviewFailed = false; _visualizerPreviewFailure = "";
                if (_visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
                StartFramePreview(_lastVizPath, target, true, true);
            }
        }

        private void ApplyPreviewPauseProjection(bool paused)
        {
            // R61.89: Pause/Play is an edge, not a heartbeat. R61.88 projected the same
            // state through two adjacent refresh paths and could call MediaElement.Play()
            // several times per second for both native previews. That keeps Windows media
            // worker threads unnecessarily busy even while the WPF dispatcher itself is idle.
            bool changed = paused != _previewPauseState;
            _previewPauseState = paused;
            if (!changed) return;

            if (_videoFramePreview != null) _videoFramePreview.UpdateClock(_timePosition, paused);
            if (_visualizerFramePreview != null) _visualizerFramePreview.UpdateClock(_timePosition, paused);
            // Resume is an explicit synchronization edge. Reproject both native optional-media
            // clocks from the same mpv/audio timestamp before allowing either presenter to run.
            // This costs two position assignments only on a Play edge, not in the steady-state loop.
            if (!paused)
            {
                if (_videoNativePreviewActive && _videoHost != null) SetPreviewPosition(_videoHost, _timePosition);
                if (_visualizerNativePreviewActive && _visualizerHost != null) SetPreviewPosition(_visualizerHost, _timePosition);
            }
            ApplyNativePreviewPauseEdge(_videoHost, _videoNativePreviewActive, paused);
            ApplyNativePreviewPauseEdge(_visualizerHost, _visualizerNativePreviewActive, paused);
            WritePreviewRendererLog("NATIVE PLAY STATE " + (paused ? "PAUSE" : "PLAY") + " edge target=" + _timePosition.ToString("0.000", CultureInfo.InvariantCulture));

            if (!paused)
            {
                bool missingVideo = (_mediaMode == MediaMode.Video || _mediaMode == MediaMode.Both) && !_videoNativePreviewActive && _videoFramePreview == null && !String.IsNullOrWhiteSpace(_lastVideoPath);
                bool missingViz = _visualizerEnabled && !_visualizerNativePreviewActive && _visualizerFramePreview == null && !String.IsNullOrWhiteSpace(_lastVizPath);
                if (missingVideo || missingViz) RestartFramePreviewsAt(_timePosition, true);
            }
        }

        private static void ApplyNativePreviewPauseEdge(MediaElement media, bool active, bool paused)
        {
            if (!active || media == null) return;
            try { if (paused) media.Pause(); else media.Play(); } catch { }
        }

        private void UpdateFramePreviewClocks()
        {
            bool paused = _pauseIntentPending ? _pauseIntentState : _paused;
            if (_videoFramePreview != null) _videoFramePreview.UpdateClock(_timePosition, paused);
            if (_visualizerFramePreview != null) _visualizerFramePreview.UpdateClock(_timePosition, paused);

            // R61.106.8: mpv/audio time is the presentation master clock. Native video is sampled
            // often enough that a visible 0.6-2.3 s lag cannot accumulate between corrections.
            // Moderate error is converged smoothly with SpeedRatio; large error is hard-seeked.
            long now = _clock.ElapsedMilliseconds;
            if (now - _lastPreviewClockSyncMs < 80) return;
            _lastPreviewClockSyncMs = now;
            SyncNativePreviewClock(_videoHost, _videoNativePreviewActive, _timePosition, false, paused);
            // R61.91: native visualizer is intentionally free-running between explicit edges.
            // Target Windows reports MediaElement.Position unreliably for these tiny video-only
            // H.264 visualizers; treating that getter as authority caused a forced seek every
            // second and drove controller CPU back above one core. Track start, explicit seek,
            // pause/resume and recovery still project an authoritative visualizer position.
        }

        private void SyncNativePreviewClock(MediaElement media, bool active, double targetSeconds, bool visualizer, bool paused)
        {
            // Native visualizer remains unused for normal live visualization; ffmpeg-raw owns that
            // path. For native video, mpv/audio time is the non-negotiable master clock.
            if (visualizer || !active || media == null || targetSeconds < 0) return;
            try
            {
                double current = media.Position.TotalSeconds;
                double drift = current - targetSeconds;
                double absDrift = Math.Abs(drift);
                if (paused)
                {
                    media.SpeedRatio = 1.0;
                    if (absDrift > 0.025) SetPreviewPosition(media, targetSeconds);
                    _nativeVideoClockBadSamples = 0;
                    return;
                }

                // At normal viewing distance ~150-200 ms is already an obvious A/V offset.
                // Correct before that boundary, then abandon MediaElement if it repeatedly refuses
                // to stay locked. The raw presenter below is clock-gated frame-by-frame.
                if (absDrift > 0.120)
                {
                    _nativeVideoClockBadSamples++;
                    media.SpeedRatio = 1.0;
                    SetPreviewPosition(media, targetSeconds);
                    WritePreviewRendererLog("VIDEO NATIVE CLOCK SEEK drift=" + drift.ToString("0.000", CultureInfo.InvariantCulture) +
                        " target=" + targetSeconds.ToString("0.000", CultureInfo.InvariantCulture) +
                        " strike=" + _nativeVideoClockBadSamples.ToString(CultureInfo.InvariantCulture));
                    if (_nativeVideoClockBadSamples >= 3)
                    {
                        int generation = _videoNativePreviewGeneration;
                        _nativeVideoClockBadSamples = 0;
                        FallbackNativePreview(false, generation, "native video could not hold mpv/audio clock lock");
                    }
                    return;
                }

                if (absDrift < 0.045) _nativeVideoClockBadSamples = 0;
                if (absDrift > 0.025)
                {
                    // PLL-style convergence handles small decoder/compositor error without visible
                    // seek jumps. Negative drift means video is behind, so speed up; positive slows.
                    double ratio = Math.Max(0.90, Math.Min(1.10, 1.0 - drift * 0.32));
                    media.SpeedRatio = ratio;
                }
                else if (Math.Abs(media.SpeedRatio - 1.0) > 0.001) media.SpeedRatio = 1.0;
            }
            catch { }
        }

        private void UpdatePreviewPauseState()
        {
            bool paused = _pauseIntentPending ? _pauseIntentState : _paused;
            ApplyPreviewPauseProjection(paused);

            // R61.106.8 startup closure: explicit-play prewarm can optimistically project the
            // preview state to PLAY before engine-status.json/mpv have reported the matching
            // unpaused authority. If READY media is resolved during that short stale-paused
            // window, ApplyResolvedMedia remembers the paths but correctly declines to launch
            // decoders. When authoritative playback catches up there may be no preview-pause
            // edge left to fire, so the first track can sit artwork-only until an unrelated media
            // refresh happens. Reconcile missing decoders whenever playback is authoritatively
            // running. StartFramePreview coalesces native opening and live FFmpeg identities, so
            // this is a repair check, not a restart heartbeat. Failed previews remain failed until
            // their normal media-state retry path changes generation/evidence.
            if (!paused)
            {
                if ((_mediaMode == MediaMode.Video || _mediaMode == MediaMode.Both) &&
                    !_videoPreviewFailed && !_videoNativePreviewActive && _videoFramePreview == null &&
                    !String.IsNullOrWhiteSpace(_lastVideoPath))
                    StartFramePreview(_lastVideoPath, _timePosition, false, false);

                if (_visualizerEnabled && !_visualizerPreviewFailed &&
                    !_visualizerNativePreviewActive && _visualizerFramePreview == null &&
                    !String.IsNullOrWhiteSpace(_lastVizPath))
                    StartFramePreview(_lastVizPath, _timePosition, true, false);
            }
        }

        private void RetireOutgoingTimedVisualsAtAudioOccurrenceSwitch(int outgoingOccurrence, int incomingOccurrence)
        {
            // R61.106.8 strict A/V authority: once mpv/audio advances to a new occurrence,
            // a frame from the outgoing occurrence is no longer continuity; it is wrong-track
            // presentation. Retire timed visuals immediately. The fixed rack remains in place,
            // artwork may continue its independent preparation bridge, and the incoming video/viz
            // may commit only after they are clocked against the new authoritative mpv position.
            StopVideoPreview(true);
            StopVisualizerPreview(false);
            _lastVideoPath = "";
            _lastVideoGeneration = "";
            _lastVizPath = "";
            _lastVizGeneration = "";
            _videoRequestedPath = "";
            _videoRequestedGeneration = "";
            _videoRequestedOccurrence = incomingOccurrence;
            _videoPresentedPath = "";
            _videoPresentedGeneration = "";
            _videoPresentedOccurrence = 0;
            _videoAuthoritativelyAbsent = false;
            _visualizerBridgeHold = false;
        }

        private void StopPreviewProcesses()
        {
            StopVideoPreview();
            StopVisualizerPreview();
            _lastPreviewClockSyncMs = -10000;
        }

        private static void ClosePreviewElement(MediaElement media)
        {
            if (media == null) return;
            try { media.Stop(); } catch { }
            try { media.Close(); } catch { }
            try { media.Source = null; } catch { }
        }

        private void StopVideoPreview()
        {
            StopVideoPreview(true);
        }

        private void StopVideoPreview(bool clearBridge)
        {
            if (_videoFramePreview != null)
            {
                try { _videoFramePreview.Dispose(); } catch { }
                _videoFramePreview = null;
            }
            _videoPreviewIdentity = "";
            _videoPreviewLaunchMs = -10000;
            ++_videoRawPreviewGeneration;
            ++_videoNativePreviewGeneration;
            ++_videoPreviewProbeGeneration;
            _videoNativePreviewActive = false;
            _nativeVideoClockBadSamples = 0;
            _videoNativePreviewIdentity = "";
            _videoNativePreviewFile = "";
            _videoPreviewBackend = "none";
            DetachNativePreviewHandlers(_videoHost, false);
            ClosePreviewElement(_videoHost);
            if (_videoHost != null) _videoHost.Opacity = 1.0;
            if (_videoFrameHost != null)
            {
                _videoFrameHost.Source = null;
                _videoFrameHost.Visibility = Visibility.Collapsed;
            }
            _videoPreviewReady = false;
            _videoPreviewFailed = false;
            _videoPreviewFailure = "";
            if (clearBridge) ClearVideoBridge();
        }

        private void StopVisualizerPreview()
        {
            StopVisualizerPreview(false);
        }

        private void StopVisualizerPreview(bool preserveCommittedFrame)
        {
            if (_visualizerFramePreview != null)
            {
                try { _visualizerFramePreview.Dispose(); } catch { }
                _visualizerFramePreview = null;
            }
            _visualizerPreviewIdentity = "";
            _visualizerPreviewLaunchMs = -10000;
            ++_visualizerRawPreviewGeneration;
            ++_visualizerNativePreviewGeneration;
            _visualizerNativePreviewActive = false;
            _visualizerNativePreviewIdentity = "";
            _visualizerNativePreviewFile = "";
            _visualizerPreviewBackend = "none";
            DetachNativePreviewHandlers(_visualizerHost, true);
            ClosePreviewElement(_visualizerHost);
            bool canBridge = preserveCommittedFrame && _visualizerFrameHost != null && _visualizerFrameHost.Source != null;
            _visualizerBridgeHold = canBridge;
            if (_visualizerFrameHost != null)
            {
                if (canBridge) _visualizerFrameHost.Visibility = Visibility.Visible;
                else
                {
                    _visualizerFrameHost.Source = null;
                    _visualizerFrameHost.Visibility = Visibility.Collapsed;
                }
            }
            _visualizerPreviewReady = false;
            _visualizerPreviewFailed = false;
            _visualizerPreviewFailure = "";
        }

        private static BitmapScalingMode BitmapScalingModeFor(MediaScaleFilter filter)
        {
            switch (filter)
            {
                case MediaScaleFilter.NearestNeighbor: return BitmapScalingMode.NearestNeighbor;
                case MediaScaleFilter.FastBilinear:
                case MediaScaleFilter.Bilinear: return BitmapScalingMode.Linear;
                case MediaScaleFilter.Bicubic:
                case MediaScaleFilter.Bicublin:
                case MediaScaleFilter.Area:
                case MediaScaleFilter.Gauss:
                case MediaScaleFilter.Sinc:
                case MediaScaleFilter.Lanczos:
                case MediaScaleFilter.Spline: return BitmapScalingMode.HighQuality;
                default: return BitmapScalingMode.Unspecified;
            }
        }

        private static string FfmpegScaleFlagFor(MediaScaleFilter filter)
        {
            switch (filter)
            {
                case MediaScaleFilter.FastBilinear: return "fast_bilinear";
                case MediaScaleFilter.Bilinear: return "bilinear";
                case MediaScaleFilter.Bicublin: return "bicublin";
                case MediaScaleFilter.Area: return "area";
                case MediaScaleFilter.Gauss: return "gauss";
                case MediaScaleFilter.Sinc: return "sinc";
                case MediaScaleFilter.Lanczos: return "lanczos";
                case MediaScaleFilter.Spline: return "spline";
                case MediaScaleFilter.NearestNeighbor: return "neighbor";
                case MediaScaleFilter.Bicubic: return "bicubic";
                default: return "bicubic";
            }
        }

        private void ApplyMediaScaleFiltering()
        {
            BitmapScalingMode art = BitmapScalingModeFor(_artworkScaleFilter), video = BitmapScalingModeFor(_videoScaleFilter);
            if (_artworkImage != null) RenderOptions.SetBitmapScalingMode(_artworkImage, art);
            if (_artworkCropSurface != null) RenderOptions.SetBitmapScalingMode(_artworkCropSurface, art);
            if (_videoFrameHost != null) RenderOptions.SetBitmapScalingMode(_videoFrameHost, video);
            if (_videoBridgeHost != null) RenderOptions.SetBitmapScalingMode(_videoBridgeHost, video);
            if (_videoHost != null) RenderOptions.SetBitmapScalingMode(_videoHost, video);
            if (_playerVideoBackdropImage != null) RenderOptions.SetBitmapScalingMode(_playerVideoBackdropImage, video);
            if (_queueVideoBackdropImage != null) RenderOptions.SetBitmapScalingMode(_queueVideoBackdropImage, video);
            if (_mediaStageImage != null) RenderOptions.SetBitmapScalingMode(_mediaStageImage, _mediaStageKind == MediaStageKind.Thumbnail ? art : video);
            if (_mediaStageBackdropImage != null) RenderOptions.SetBitmapScalingMode(_mediaStageBackdropImage, _mediaStageKind == MediaStageKind.Thumbnail ? art : video);
        }

        private MenuItem MediaFilterMenu(string label, bool artwork)
        {
            var root = new MenuItem { Header = label };
            Action<string, MediaScaleFilter> add = delegate(string text, MediaScaleFilter filter)
            {
                var item = new MenuItem { Header = text, IsCheckable = true, IsChecked = (artwork ? _artworkScaleFilter : _videoScaleFilter) == filter, StaysOpenOnClick = true };
                item.Click += delegate
                {
                    if (artwork) _artworkScaleFilter = filter; else _videoScaleFilter = filter;
                    ApplyMediaScaleFiltering();
                    if (!artwork && !String.IsNullOrWhiteSpace(_lastVideoPath)) StartFramePreview(_lastVideoPath, _timePosition, false, true);
                    SaveUiState();
                };
                root.Items.Add(item);
            };
            add("Default", MediaScaleFilter.Default);
            add("Fast bilinear", MediaScaleFilter.FastBilinear);
            add("Bilinear", MediaScaleFilter.Bilinear);
            add("Bicubic", MediaScaleFilter.Bicubic);
            add("Bicublin (bicubic luma / bilinear chroma)", MediaScaleFilter.Bicublin);
            add("Area averaging", MediaScaleFilter.Area);
            add("Gaussian", MediaScaleFilter.Gauss);
            add("Sinc", MediaScaleFilter.Sinc);
            add("Lanczos", MediaScaleFilter.Lanczos);
            add("Spline", MediaScaleFilter.Spline);
            add("Nearest neighbor / Point", MediaScaleFilter.NearestNeighbor);
            return root;
        }

        private MenuItem MediaLayoutMenu()
        {
            var root = new MenuItem { Header = "Thumbnail + Video layout" };
            Action<string, MediaPairLayout> add = delegate(string text, MediaPairLayout layout)
            {
                var item = new MenuItem { Header = text, IsCheckable = true, IsChecked = _mediaPairLayout == layout, StaysOpenOnClick = true };
                item.Click += delegate { _mediaPairLayout = layout; ApplyMediaMode(false); SaveUiState(); }; root.Items.Add(item);
            };
            add("Left / Right", MediaPairLayout.LeftRight); add("Top / Bottom", MediaPairLayout.TopBottom); return root;
        }

        private MediaRackSize NativeMediaRackSizeFromConfig()
        {
            string quality = UnifiedVideoQualityFromConfig(ReadJsonCached(Path.Combine(_dataRoot, "config.json")));
            if (quality.StartsWith("240p", StringComparison.OrdinalIgnoreCase)) return MediaRackSize.P240;
            if (quality.StartsWith("360p", StringComparison.OrdinalIgnoreCase)) return MediaRackSize.P360;
            if (quality.StartsWith("480p", StringComparison.OrdinalIgnoreCase)) return MediaRackSize.P480;
            if (quality.StartsWith("720p", StringComparison.OrdinalIgnoreCase) || quality.StartsWith("Best", StringComparison.OrdinalIgnoreCase)) return MediaRackSize.P720;
            return MediaRackSize.P144;
        }

        private void MediaRackResolution(MediaRackSize size, out double width, out double height)
        {
            if (size == MediaRackSize.Native) size = NativeMediaRackSizeFromConfig();
            switch (size)
            {
                case MediaRackSize.P240: width = 426; height = 240; return;
                case MediaRackSize.P360: width = 640; height = 360; return;
                case MediaRackSize.P480: width = 854; height = 480; return;
                case MediaRackSize.P720: width = 1280; height = 720; return;
                case MediaRackSize.Fit: width = 1280; height = 720; return;
                default: width = 256; height = 144; return;
            }
        }

        private void EffectiveMediaCellGeometry(bool pair, bool verticalPair, out double cellWidth, out double cellHeight)
        {
            double nominalWidth, nominalHeight;
            MediaRackResolution(_mediaRackSize, out nominalWidth, out nominalHeight);
            double shellWidth = _nowPlayingSurface != null && _nowPlayingSurface.ActualWidth > 1.0 ? _nowPlayingSurface.ActualWidth : Math.Max(360.0, _window.ActualWidth > 1.0 ? _window.ActualWidth : _window.Width);
            double shellHeight = Math.Max(112.0, _window.ActualHeight > 1.0 ? _window.ActualHeight : _window.Height);
            bool honorFixedMediaSize = _mediaRackSize != MediaRackSize.Fit;
            double maxRackWidth = honorFixedMediaSize
                ? Math.Max(196.0, shellWidth - 300.0)
                : Math.Max(196.0, shellWidth * 0.46);
            double maxRackHeight = honorFixedMediaSize
                ? Math.Max(144.0, shellHeight - 58.0)
                : Math.Max(144.0, shellHeight * 0.58);
            if (_mediaRackSize == MediaRackSize.Fit)
            {
                // Fill the media allocation as completely as possible while keeping every cell
                // at the canonical 16:9 stage geometry. The whole rack scales as one unit.
                double pairW = pair && !verticalPair ? 2.0 : 1.0;
                double pairH = pair && verticalPair ? 2.0 : 1.0;
                double hByWidth = maxRackWidth / Math.Max(1.0, pairW) * 9.0 / 16.0;
                double hByHeight = maxRackHeight / Math.Max(1.0, pairH);
                cellHeight = Math.Max(36.0, Math.Min(hByWidth, hByHeight));
                cellWidth = Math.Max(64.0, cellHeight * 16.0 / 9.0);
                return;
            }
            double rackWidth = nominalWidth * (pair && !verticalPair ? 2.0 : 1.0);
            double rackHeight = nominalHeight * (pair && verticalPair ? 2.0 : 1.0);
            double scale = Math.Min(1.0, Math.Min(maxRackWidth / Math.Max(1.0, rackWidth), maxRackHeight / Math.Max(1.0, rackHeight)));
            cellWidth = Math.Max(64.0, nominalWidth * scale);
            cellHeight = Math.Max(36.0, nominalHeight * scale);
        }

