        private bool MediaStageVisible()
        {
            return _mediaStageKind != MediaStageKind.None && !_queueOpen && !_performanceWorkspace;
        }

        private void SetMediaStage(MediaStageKind kind, bool fullscreen, bool save)
        {
            if (kind == MediaStageKind.Video && !VideoPreparationEnabled()) kind = MediaStageKind.None;
            _mediaStageKind = kind;
            _mediaStageFullscreen = kind != MediaStageKind.None && fullscreen;
            _videoBackdropMode = kind == MediaStageKind.Video ? VideoBackdropMode.PlayerArea : VideoBackdropMode.Off;
            if (kind != MediaStageKind.None)
            {
                if (_queueOpen) SetQueueOpen(false, false);
            }
            ApplyMediaMode(false);
            ApplyQueueCanvasLayout(true);
            ApplyCompactLayoutForSize();
            RefreshMediaStagePresentation();
            if (kind != MediaStageKind.None) ScheduleMediaStageAspectSnap();
            if (save) SaveUiState();
        }

        private void RefreshMediaStagePresentation()
        {
            if (_mediaStageSurface == null) return;
            bool visible = MediaStageVisible();
            if (!visible)
            {
                _mediaStageSurface.Visibility = Visibility.Collapsed;
                return;
            }
            ImageSource source = null;
            ImageSource thumbnail = _artworkImage != null && _artworkImage.Source != null ? _artworkImage.Source : (ImageSource)(_artworkDecodedSmartCrop ?? _artworkDecodedOriginal);
            if (_mediaStageKind == MediaStageKind.Video)
                source = _videoFrameHost == null ? null : _videoFrameHost.Source;
            else
                source = thumbnail;
            // The ambient fill is deliberately driven by the static thumbnail whenever possible.
            // It gives pillar/letterbox space track-specific depth without applying an expensive
            // blur shader to every decoded video frame.
            ImageSource backdrop = thumbnail;
            if (_mediaStageImage != null) { _mediaStageImage.Source = source; _mediaStageImage.Stretch = Stretch.Uniform; }
            if (_mediaStageBackdropImage != null) { _mediaStageBackdropImage.Source = backdrop; _mediaStageBackdropImage.Stretch = Stretch.UniformToFill; }
            if (_mediaStageHintText != null)
            {
                _mediaStageHintText.Text = source == null ? (_mediaStageKind == MediaStageKind.Video ? "Video preparing" : "Thumbnail preparing") : "";
                _mediaStageHintText.Visibility = source == null ? Visibility.Visible : Visibility.Collapsed;
            }
            _mediaStageSurface.Visibility = Visibility.Visible;
            int panelRow = _queuePlayerDock == QueuePlayerDock.Top ? 2 : 0;
            Grid.SetRow(_mediaStageSurface, _mediaStageFullscreen ? 0 : panelRow);
            Grid.SetRowSpan(_mediaStageSurface, _mediaStageFullscreen ? 3 : 1);
            Panel.SetZIndex(_mediaStageSurface, _mediaStageFullscreen ? 50 : 1);
        }

        private void ScheduleMediaStageAspectSnap()
        {
            if (_window == null || !MediaStageVisible() || _window.WindowState != WindowState.Normal) return;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Loaded, new Action(delegate
            {
                if (!MediaStageVisible() || _window.WindowState != WindowState.Normal) return;
                FitWindowToMediaStageAspect();
            }));
        }

        private void FitWindowToMediaStageAspect()
        {
            if (_window == null || _mediaStageSurface == null || !MediaStageVisible() || _window.WindowState != WindowState.Normal) return;
            _window.UpdateLayout();
            double stageW = _mediaStageSurface.ActualWidth;
            double stageH = _mediaStageSurface.ActualHeight;
            double outerW = _window.ActualWidth > 1.0 ? _window.ActualWidth : _window.Width;
            double outerH = _window.ActualHeight > 1.0 ? _window.ActualHeight : _window.Height;
            if (stageW < 16.0 || outerW < 32.0) return;
            double fixedH = Math.Max(0.0, outerH - Math.Max(0.0, stageH));
            double targetH = fixedH + stageW * 9.0 / 16.0;
            Rect work = CurrentWorkAreaDips();
            targetH = Math.Max(_window.MinHeight, Math.Min(work.Height, targetH));
            if (Math.Abs(outerH - targetH) <= 1.0) return;
            _internalGeometryChange = true;
            try { _window.Height = targetH; }
            finally { _internalGeometryChange = false; }
            ConstrainWindowToVisibleWorkArea();
        }

        private void ToggleMediaStage(MediaStageKind kind)
        {
            if (_mediaStageKind == kind && !_mediaStageFullscreen) SetMediaStage(MediaStageKind.None, false, true);
            else SetMediaStage(kind, false, true);
        }

        private void ToggleMediaStageFullscreen(MediaStageKind kind)
        {
            if (_mediaStageFullscreen && _mediaStageKind == kind) SetMediaStage(kind, false, true);
            else SetMediaStage(kind, true, true);
        }

        private void ApplyVideoBackdropPresentation()
        {
            // R61.106.27: the old below-controller "background" is now a real media workplane.
            // Keep compatibility elements dark so no duplicate video can bleed behind controller/Queue.
            if (_playerVideoBackdropSurface != null) _playerVideoBackdropSurface.Visibility = Visibility.Collapsed;
            if (_queueVideoBackdropSurface != null) _queueVideoBackdropSurface.Visibility = Visibility.Collapsed;
            RefreshMediaStagePresentation();
        }

        private bool ApplyMediaStageAspectResize(IntPtr wParam, IntPtr lParam)
        {
            if (lParam == IntPtr.Zero || !MediaStageVisible() || _mediaStageSurface == null || _window == null) return false;
            double surfaceWidthDip = _mediaStageSurface.ActualWidth;
            double surfaceHeightDip = _mediaStageSurface.ActualHeight;
            if (surfaceWidthDip < 16.0 || surfaceHeightDip < 16.0) return false;
            RECT current;
            IntPtr hwnd = new WindowInteropHelper(_window).Handle;
            if (hwnd == IntPtr.Zero || !GetWindowRect(hwnd, out current)) return false;
            RECT proposed = (RECT)Marshal.PtrToStructure(lParam, typeof(RECT));
            double scale = 1.0;
            try
            {
                PresentationSource ps = PresentationSource.FromVisual(_window);
                if (ps != null && ps.CompositionTarget != null) scale = Math.Max(0.5, ps.CompositionTarget.TransformToDevice.M11);
            }
            catch { }
            double currentW = Math.Max(1.0, current.Right - current.Left), currentH = Math.Max(1.0, current.Bottom - current.Top);
            double fixedW = Math.Max(0.0, currentW - surfaceWidthDip * scale);
            double fixedH = Math.Max(0.0, currentH - surfaceHeightDip * scale);
            // Stable 16:9 stage policy: source aspect lives inside this rectangle with Uniform
            // letterboxing and a blurred media-derived backdrop. Track changes never move the window.
            double aspect = 16.0 / 9.0;
            int edge = wParam.ToInt32();
            bool horizontalAuthority = edge == 1 || edge == 2 || edge == 4 || edge == 5 || edge == 7 || edge == 8;
            double targetW = Math.Max(_window.MinWidth * scale, proposed.Right - proposed.Left);
            double targetH = Math.Max(_window.MinHeight * scale, proposed.Bottom - proposed.Top);
            if (horizontalAuthority)
            {
                double contentW = Math.Max(1.0, targetW - fixedW);
                targetH = Math.Max(_window.MinHeight * scale, fixedH + contentW / aspect);
            }
            else
            {
                double contentH = Math.Max(1.0, targetH - fixedH);
                targetW = Math.Max(_window.MinWidth * scale, fixedW + contentH * aspect);
            }
            int iw = Math.Max(1, (int)Math.Round(targetW));
            int ih = Math.Max(1, (int)Math.Round(targetH));
            bool fromLeft = edge == 1 || edge == 4 || edge == 7;
            bool fromTop = edge == 3 || edge == 4 || edge == 5;
            if (fromLeft) proposed.Left = proposed.Right - iw; else proposed.Right = proposed.Left + iw;
            if (fromTop) proposed.Top = proposed.Bottom - ih; else proposed.Bottom = proposed.Top + ih;
            Marshal.StructureToPtr(proposed, lParam, false);
            return true;
        }

