        private void RefreshWindowControllerMenuChecks(ItemCollection items)
        {
            if (items == null) return;
            foreach (object raw in items)
            {
                MenuItem item = raw as MenuItem;
                if (item == null) continue;
                string tag = item.Tag as string;
                if (String.Equals(tag, "mini-player-window", StringComparison.Ordinal)) item.IsChecked = _microMode;
                else if (String.Equals(tag, "show-queue", StringComparison.Ordinal)) item.IsChecked = _queueOpen;
                else if (String.Equals(tag, "operations-center", StringComparison.Ordinal)) item.IsChecked = _inspectorOpen;
                if (item.HasItems) RefreshWindowControllerMenuChecks(item.Items);
            }
        }

