        private void ApplyMediaMode(bool restartPreview)
        {
            if (restartPreview)
            {
                StopVideoPreview(true);
                _lastMediaOccurrence = 0;
                _lastVideoPath = ""; _lastVideoGeneration = "";
                _lastArtworkPath = ""; _lastArtworkGeneration = "";
                _videoRequestedPath = ""; _videoRequestedGeneration = ""; _videoRequestedOccurrence = 0;
                _videoPresentedPath = ""; _videoPresentedGeneration = ""; _videoPresentedOccurrence = 0;
                _videoPresentedAspect = 16.0 / 9.0;
                _videoAuthoritativelyAbsent = false;
            }

            ReparentVideoPresenter();
            ApplyCanonicalMediaGeometry();

            bool wantsArt = MediaModeHasArtwork(_mediaMode);
            bool wantsVideo = MediaModeHasVideo(_mediaMode);
            if (!VideoPreparationEnabled()) EnforceVideoAuthority();
            if (_mediaThumbnailToggle != null) _mediaThumbnailToggle.IsChecked = wantsArt;
            if (_mediaVideoToggle != null) _mediaVideoToggle.IsChecked = wantsVideo;
            bool effectiveArt = wantsArt;
            bool videoAuthority = VideoPreparationEnabled();
            bool effectiveVideo = wantsVideo && videoAuthority && !_videoAuthoritativelyAbsent;
            bool compactOrPerformance = _miniMode || _compactControllerMode || _performanceWorkspace;

            // R61.105: rack geometry follows operator configuration, never per-track media
            // metadata. Video keeps its true source aspect inside the fixed pane via Stretch=Uniform.
            // Missing/preparing video may disappear visually, but it cannot make the whole Now
            // Playing viewport lurch left/right or change size between tracks.
            bool reserveArt = wantsArt;
            bool backgroundVideoActive = _mediaStageKind == MediaStageKind.Video;
            bool reserveVideo = wantsVideo && !_largeVideoArea && !backgroundVideoActive;
            bool videoInRack = effectiveVideo && !_largeVideoArea && !backgroundVideoActive;
            bool rackConfigured = reserveArt || reserveVideo;

            bool localRackVisible = !compactOrPerformance;
            if (_artworkPane != null) _artworkPane.Visibility = effectiveArt && localRackVisible ? Visibility.Visible : Visibility.Collapsed;
            // The operator may keep the Video box in the rack while global Video is Off. In
            // that state the themed recessed frame remains as an intentionally empty stage, but no
            // decoder/frame is allowed to appear inside it.
            if (_videoPane != null) _videoPane.Visibility = reserveVideo && localRackVisible ? Visibility.Visible : Visibility.Collapsed;
            if (_artworkPane != null)
                _artworkPane.BorderThickness = new Thickness(0);

            // Narrow full-player widths sacrifice preview pixels before control topology. The
            // Art/Video toggles remain available, but the local rack yields completely rather
            // than forcing another controller row or covering Volume/Queue.
            bool showFrame = rackConfigured && !compactOrPerformance;
            double mediaGap = _adaptiveLayoutTier == AdaptiveLayoutTier.Constrained ? 8 : (_adaptiveLayoutTier == AdaptiveLayoutTier.Standard ? 10 : 12);
            double borderHorizontal = _mediaFrame == null ? 0.0 : Math.Max(0.0, _mediaFrame.BorderThickness.Left + _mediaFrame.BorderThickness.Right);
            double borderVertical = _mediaFrame == null ? 0.0 : Math.Max(0.0, _mediaFrame.BorderThickness.Top + _mediaFrame.BorderThickness.Bottom);
            bool pair = reserveArt && reserveVideo;
            bool verticalPair = pair && _mediaPairLayout == MediaPairLayout.TopBottom;
            double cellWidth, cellHeight;
            EffectiveMediaCellGeometry(pair, verticalPair, out cellWidth, out cellHeight);
            if (_queueCanvasActive && cellHeight > 180.0)
            {
                double queueScale = 180.0 / cellHeight;
                cellHeight *= queueScale; cellWidth *= queueScale;
            }
            double mediaWidth = (verticalPair ? cellWidth : ((reserveArt ? cellWidth : 0) + (reserveVideo ? cellWidth : 0))) + borderHorizontal;
            double mediaHeight = (verticalPair ? cellHeight * 2.0 : cellHeight) + borderVertical;
            double drawableHeight = verticalPair ? cellHeight : cellHeight;
            RowDefinition mediaTopRow = _window.FindName("MediaTopRow") as RowDefinition;
            RowDefinition mediaBottomRow = _window.FindName("MediaBottomRow") as RowDefinition;
            if (verticalPair)
            {
                _artworkColumn.Width = new GridLength(cellWidth); _mediaGapColumn.Width = new GridLength(0); _videoColumn.Width = new GridLength(0);
                if (mediaTopRow != null) mediaTopRow.Height = new GridLength(cellHeight); if (mediaBottomRow != null) mediaBottomRow.Height = new GridLength(cellHeight);
                Grid.SetColumn(_artworkPane, 0); Grid.SetRow(_artworkPane, 0); Grid.SetColumn(_videoPane, 0); Grid.SetRow(_videoPane, 1);
            }
            else
            {
                if (mediaTopRow != null) mediaTopRow.Height = new GridLength(cellHeight); if (mediaBottomRow != null) mediaBottomRow.Height = new GridLength(0);
                Grid.SetColumn(_artworkPane, 0); Grid.SetRow(_artworkPane, 0); Grid.SetColumn(_videoPane, 2); Grid.SetRow(_videoPane, 0);
                _artworkColumn.Width = new GridLength(reserveArt ? cellWidth : 0); _mediaGapColumn.Width = new GridLength(0); _videoColumn.Width = new GridLength(reserveVideo ? cellWidth : 0);
            }
            if (!reserveArt && !reserveVideo) mediaWidth = 0;
            ApplyVideoPresentationGeometry(reserveArt, reserveVideo, videoInRack, reserveVideo ? cellWidth : 0, drawableHeight);
            bool videoFillsCell = reserveVideo && Math.Abs(NormalizeVideoAspect(_videoPresentedAspect) - (16.0 / 9.0)) < 0.02;
            bool sharedSideSeam = pair && !verticalPair && videoFillsCell;
            if (_artworkPane != null)
            {
                _artworkPane.BorderBrush = (Brush)_window.FindResource("BorderStrong");
                _artworkPane.BorderThickness = reserveArt ? new Thickness(1, 1, sharedSideSeam ? 0 : 1, 1) : new Thickness(0);
                _artworkPane.CornerRadius = new CornerRadius(0);
            }
            if (_videoPresentationFrame != null) _videoPresentationFrame.CornerRadius = new CornerRadius(0);
            if (_artworkVideoDivider != null) _artworkVideoDivider.Visibility = Visibility.Collapsed;
            ApplyMediaScaleFiltering();
            ApplyVideoBackdropPresentation();

            if (_mediaFrame != null)
            {
                _mediaFrame.Visibility = showFrame ? Visibility.Visible : Visibility.Collapsed;
                _mediaFrame.Height = showFrame ? mediaHeight : 0;
            }
            if (_nowPlayingMediaColumn != null) _nowPlayingMediaColumn.Width = new GridLength(showFrame ? mediaWidth : 0);
            if (_nowPlayingGapColumn != null) _nowPlayingGapColumn.Width = new GridLength(showFrame ? mediaGap : 0);

            ApplyLargeVideoAreaGeometry(effectiveVideo, compactOrPerformance);
            ApplyVisualizerPresentation(false);

            switch (_mediaMode)
            {
                case MediaMode.Artwork:
                    _mediaModeBadge.Text = "Thumbnail";
                    break;
                case MediaMode.Video:
                    _mediaModeBadge.Text = "Video";
                    break;
                case MediaMode.Both:
                    _mediaModeBadge.Text = "Thumbnail + video";
                    break;
                default:
                    _mediaModeBadge.Text = "Off";
                    break;
            }
            RefreshMediaStagePresentation();
        }

        private void ApplyVideoPresentationGeometry(bool reserveArt, bool reserveVideo, bool videoInRack, double videoCellWidth, double drawableHeight)
        {
            if (_videoPresentationFrame == null) return;

            if (_largeVideoArea)
            {
                // Large Video is still source-aspect video, not a black rectangle with a
                // smaller picture floating inside it. Fit the bordered frame itself to the
                // source and let the surrounding host show normal YOMI atmosphere.
                double largeAspect = NormalizeVideoAspect(_videoPresentedAspect);
                double hostWidth = _largeVideoAreaHost != null && _largeVideoAreaHost.ActualWidth > 1.0
                    ? _largeVideoAreaHost.ActualWidth
                    : (_mainSurface != null && _mainSurface.ActualWidth > 1.0 ? _mainSurface.ActualWidth : Math.Max(1.0, _window.ActualWidth - 16.0));
                double windowHeight = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
                double hostHeight = _largeVideoAreaHost != null && _largeVideoAreaHost.ActualHeight > 1.0
                    ? _largeVideoAreaHost.ActualHeight
                    : Math.Max(150.0, Math.Min(420.0, windowHeight * 0.34));
                double availableWidth = Math.Max(1.0, hostWidth - 2.0);
                double availableHeight = Math.Max(1.0, hostHeight - 2.0);
                double frameWidth = availableWidth;
                double frameHeight = frameWidth / largeAspect;
                if (frameHeight > availableHeight)
                {
                    frameHeight = availableHeight;
                    frameWidth = frameHeight * largeAspect;
                }
                _videoPresentationFrame.Width = Math.Max(1.0, frameWidth);
                _videoPresentationFrame.Height = Math.Max(1.0, frameHeight);
                _videoPresentationFrame.HorizontalAlignment = HorizontalAlignment.Center;
                _videoPresentationFrame.VerticalAlignment = VerticalAlignment.Center;
                _videoPresentationFrame.BorderThickness = new Thickness(1);
                _videoPresentationFrame.BorderBrush = (Brush)_window.FindResource("BorderStrong");
                if (_videoPresentationBorderOverlay != null) _videoPresentationBorderOverlay.Visibility = Visibility.Collapsed;
                if (_artworkVideoDivider != null) _artworkVideoDivider.Visibility = Visibility.Collapsed;
                return;
            }

            if (!reserveVideo || videoCellWidth <= 0 || drawableHeight <= 0)
            {
                _videoPresentationFrame.Width = 0;
                _videoPresentationFrame.Height = Double.NaN;
                _videoPresentationFrame.HorizontalAlignment = HorizontalAlignment.Center;
                _videoPresentationFrame.VerticalAlignment = VerticalAlignment.Stretch;
                _videoPresentationFrame.BorderThickness = new Thickness(0);
                if (_videoPresentationBorderOverlay != null) _videoPresentationBorderOverlay.Visibility = Visibility.Collapsed;
                if (_artworkVideoDivider != null) _artworkVideoDivider.Visibility = Visibility.Collapsed;
                return;
            }

            // The reservation stays fixed, but the bordered rectangle itself matches the real
            // source aspect in BOTH dimensions. Portrait/4:3 therefore expose YOMI atmosphere
            // beside the frame; ultra-wide sources expose it above/below the frame. No black
            // letterbox belongs inside the bordered video rectangle.
            double aspect = NormalizeVideoAspect(_videoPresentedAspect);
            double cellAspect = videoCellWidth / Math.Max(1.0, drawableHeight);
            double presentedWidth, presentedHeight;
            if (aspect >= cellAspect)
            {
                presentedWidth = videoCellWidth;
                presentedHeight = Math.Max(1.0, videoCellWidth / aspect);
            }
            else
            {
                presentedHeight = drawableHeight;
                presentedWidth = Math.Max(1.0, drawableHeight * aspect);
            }
            _videoPresentationFrame.Width = presentedWidth;
            _videoPresentationFrame.Height = presentedHeight;
            _videoPresentationFrame.HorizontalAlignment = HorizontalAlignment.Center;
            _videoPresentationFrame.VerticalAlignment = VerticalAlignment.Center;
            _videoPresentationFrame.BorderThickness = new Thickness(1);
            _videoPresentationFrame.BorderBrush = (Brush)_window.FindResource("BorderStrong");
            if (_videoPresentationBorderOverlay != null) _videoPresentationBorderOverlay.Visibility = Visibility.Collapsed;
            if (_artworkVideoDivider != null) _artworkVideoDivider.Visibility = Visibility.Collapsed;
        }

        private void ApplyCanonicalMediaGeometry()
        {
            if (_artworkPane != null)
            {
                Grid.SetColumn(_artworkPane, 0);
                Grid.SetColumnSpan(_artworkPane, 1);
                _artworkPane.Width = Double.NaN;
                _artworkPane.Height = Double.NaN;
                _artworkPane.HorizontalAlignment = HorizontalAlignment.Stretch;
                _artworkPane.VerticalAlignment = VerticalAlignment.Stretch;
                _artworkPane.Margin = new Thickness(0);
                Panel.SetZIndex(_artworkPane, 0);
            }
            if (_videoPane != null)
            {
                bool inLarge = _largeVideoAreaHost != null && Object.ReferenceEquals(_videoPane.Parent, _largeVideoAreaHost.Child);
                Grid.SetColumn(_videoPane, inLarge ? 0 : 2);
                Grid.SetColumnSpan(_videoPane, 1);
                _videoPane.Width = Double.NaN;
                _videoPane.Height = Double.NaN;
                _videoPane.HorizontalAlignment = HorizontalAlignment.Stretch;
                _videoPane.VerticalAlignment = VerticalAlignment.Stretch;
                _videoPane.Margin = new Thickness(0);
                Panel.SetZIndex(_videoPane, 1);
            }
        }

        private Grid LargeVideoAreaSurface()
        {
            return _largeVideoAreaHost == null ? null : _largeVideoAreaHost.Child as Grid;
        }

        private void ReparentVideoPresenter()
        {
            if (_videoPane == null || _mediaContentGrid == null) return;
            Grid target = _largeVideoArea ? LargeVideoAreaSurface() : _mediaContentGrid;
            if (target == null || Object.ReferenceEquals(_videoPane.Parent, target)) return;
            Panel oldParent = _videoPane.Parent as Panel;
            if (oldParent != null) oldParent.Children.Remove(_videoPane);
            target.Children.Insert(0, _videoPane);
            Grid.SetColumn(_videoPane, _largeVideoArea ? 0 : 2);
            Grid.SetColumnSpan(_videoPane, 1);
        }

        private void ApplyLargeVideoAreaGeometry(bool effectiveVideo, bool compactOrPerformance)
        {
            bool show = _largeVideoArea && effectiveVideo && !compactOrPerformance;
            if (_largeVideoAreaHost != null)
            {
                double windowHeight = _window.ActualHeight > 0 ? _window.ActualHeight : _window.Height;
                double targetHeight = Math.Max(150.0, Math.Min(420.0, windowHeight * 0.34));
                _largeVideoAreaHost.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
                _largeVideoAreaHost.Height = show ? targetHeight : 0.0;
            }
            if (_largeVideoAreaRow != null) _largeVideoAreaRow.Height = show ? GridLength.Auto : new GridLength(0);
            if (_largeVideoAreaGapRow != null) _largeVideoAreaGapRow.Height = show ? new GridLength(5) : new GridLength(0);
        }

        private void SetLargeVideoArea(bool enabled, bool save)
        {
            if (enabled && !MediaModeHasVideo(_mediaMode))
            {
                ShowToast("Large video area", "Turn on Video first.");
                return;
            }
            if (_largeVideoArea == enabled)
            {
                ApplyMediaMode(false);
                return;
            }
            _largeVideoArea = enabled;
            ReparentVideoPresenter();
            ApplyMediaMode(false);
            if (save) SaveUiState();
        }

        private void ApplyVisualizerMode(bool restartPreview)
        {
            _visualizerToggle.IsChecked = _visualizerEnabled;
            // Off means absent, not a dead black panel announcing that it is off.
            if (!_visualizerEnabled && _visualizerWaitingOverlay != null) _visualizerWaitingOverlay.Visibility = Visibility.Collapsed;
            if (_visualizerHost != null) _visualizerHost.Visibility = (_visualizerEnabled && _visualizerNativePreviewActive && _visualizerPreviewReady) ? Visibility.Visible : Visibility.Collapsed;
            if (_visualizerFrameHost != null) _visualizerFrameHost.Visibility = (_visualizerEnabled && !_visualizerNativePreviewActive && _visualizerFramePreview != null && _visualizerPreviewReady) ? Visibility.Visible : Visibility.Collapsed;
            ApplyVisualizerPresentation(false);
            if (!_visualizerEnabled || restartPreview)
            {
                // R61.101: a visualizer-local restart must remain visualizer-local. Resetting
                // _lastMediaOccurrence made the next refresh impersonate a track handoff, which
                // called StopPreviewProcesses() and blacked an otherwise healthy video preview.
                StopVisualizerPreview();
                _lastVizPath = ""; _lastVizGeneration = "";
            }
        }

        private void OpenQueueFromCompact(WorkspaceProfile compactProfile)
        {
            _compactQueueReturnProfile = compactProfile;
            _compactQueueReturnFocus = Keyboard.FocusedElement;
            _compactQueueDetourEntering = true;
            try
            {
                SetMicroMode(false, false);
            }
            finally { _compactQueueDetourEntering = false; }
            SetQueueOpen(true, true);
            if (_queueList != null) _queueList.Focus();
        }

        private void ReturnToCompactAfterQueueClose()
        {
            WorkspaceProfile target = _compactQueueReturnProfile;
            _compactQueueReturnProfile = WorkspaceProfile.Custom;
            if (_queueOpen || target != WorkspaceProfile.Micro) return;
            // R61.67: called only after the Queue close transaction has actually completed.
            // Compact chrome therefore never races a still-live Full/Queue animation.
            SetMicroMode(true, true);
            IInputElement restore = _compactQueueReturnFocus;
            _compactQueueReturnFocus = null;
            _window.Dispatcher.BeginInvoke(DispatcherPriority.Input, new Action(delegate { RestoreKeyboardFocus(restore); }));
        }

        private double CompactControllerTargetHeight()
        {
            double desired = CompactControllerDefaultHeight;
            try
            {
                if (_nowPlayingSurface != null)
                {
                    double content = Math.Max(_nowPlayingSurface.ActualHeight, _nowPlayingSurface.DesiredSize.Height);
                    if (content > 0) desired = (_titleBarVisible ? 25.0 : 0.0) + (_classicMenuBar != null && _classicMenuBar.Visibility == Visibility.Visible ? 21.0 : 0.0) + content + 10.0;
                }
            }
            catch { }
            return Math.Max(FullPlayerMinHeight, desired);
        }

        private double FitControllerWindowHeight()
        {
            double desired = CompactControllerTargetHeight();
            try
            {
                FrameworkElement activeController = _compactControllerMode ? (FrameworkElement)_microSurface : (FrameworkElement)_mainSurface;
                if (activeController != null)
                {
                    double availableWidth = _workspaceHost != null && _workspaceHost.ActualWidth > 1.0 ? _workspaceHost.ActualWidth : Math.Max(1.0, _window.ActualWidth - 16.0);
                    activeController.Measure(new Size(availableWidth, Double.PositiveInfinity));
                    double content = activeController.DesiredSize.Height;
                    if (!_compactControllerMode && _nowPlayingSurface != null) content = Math.Max(content, _nowPlayingSurface.DesiredSize.Height);
                    double title = (_titleBarVisible && _titleBarRow != null) ? Math.Max(0.0, _titleBarRow.ActualHeight > 0 ? _titleBarRow.ActualHeight : 25.0) : 0.0;
                    double menu = _classicMenuBar != null && _classicMenuBar.Visibility == Visibility.Visible ? Math.Max(0.0, _classicMenuRow != null && _classicMenuRow.ActualHeight > 0 ? _classicMenuRow.ActualHeight : 21.0) : 0.0;
                    double status = _statusBarSurface != null && _statusBarSurface.Visibility == Visibility.Visible ? Math.Max(0.0, _statusBarRow != null && _statusBarRow.ActualHeight > 0 ? _statusBarRow.ActualHeight : 23.0) : 0.0;
                    double hostMargins = _workspaceHost == null ? 0.0 : Math.Max(0.0, _workspaceHost.Margin.Top + _workspaceHost.Margin.Bottom);
                    if (content > 0.0) desired = Math.Ceiling(title + menu + status + hostMargins + content);
                }
            }
            catch { }
            double floor = FullPlayerMinHeight;
            return Math.Max(floor, desired);
        }

        private void ExpandWindowForSelectedMedia(MediaRackSize size)
        {
            if (_miniMode || _queueOpen || _window == null || _window.WindowState != WindowState.Normal || size == MediaRackSize.Fit) return;
            bool art = MediaModeHasArtwork(_mediaMode);
            bool video = MediaModeHasVideo(_mediaMode) && !_largeVideoArea && _videoBackdropMode == VideoBackdropMode.Off;
            if (!art && !video) return;
            double cellWidth, cellHeight;
            MediaRackResolution(size, out cellWidth, out cellHeight);
            bool pair = art && video;
            bool verticalPair = pair && _mediaPairLayout == MediaPairLayout.TopBottom;
            double rackWidth = cellWidth * (pair && !verticalPair ? 2.0 : 1.0);
            double rackHeight = cellHeight * (pair && verticalPair ? 2.0 : 1.0);
            // Reserve a compact but usable title/transport lane beside the media. If the selected
            // media physically fits on the monitor, YOMI expands the shell enough to present it at
            // its selected size rather than immediately scaling it back down inside the old shell.
            double desiredWidth = rackWidth + 318.0;
            double desiredHeight = rackHeight + 62.0;
            Rect work = CurrentWorkAreaDips();
            _internalGeometryChange = true;
            try
            {
                _window.Width = Math.Min(work.Width, Math.Max(_window.Width, desiredWidth));
                _window.Height = Math.Min(work.Height, Math.Max(_window.Height, desiredHeight));
            }
            finally { _internalGeometryChange = false; }
            ConstrainWindowToVisibleWorkArea();
            _window.UpdateLayout();
        }

        private void SnapWindowToControllerHeight()
        {
            if (_window == null || _window.WindowState != WindowState.Normal || _miniMode || _queueOpen || MediaStageVisible()) return;
            _window.UpdateLayout();
            double target = FitControllerWindowHeight();
            Rect work = CurrentWorkAreaDips();
            double floor = FullPlayerMinHeight;
            target = Math.Max(floor, Math.Min(work.Height, target));
            _internalGeometryChange = true;
            try { _window.Height = target; }
            finally { _internalGeometryChange = false; }
            _compactControllerHeight = target;
            ConstrainWindowToVisibleWorkArea();
        }

        private void ExpandWindowForQueue()
        {
            if (_window == null || _window.WindowState != WindowState.Normal || _miniMode) return;
            Rect work = CurrentWorkAreaDips();
            double remembered = Math.Max(QueueWorkbenchMinHeight, _queueWorkbenchHeight);
            double target = Math.Min(work.Height, Math.Max(_window.Height, remembered));
            _internalGeometryChange = true;
            try { _window.Height = target; }
            finally { _internalGeometryChange = false; }
            ConstrainWindowToVisibleWorkArea();
        }

        private void FinalizeQueueClose(int generation)
        {
            if (_queueOpen || generation != _queueTransitionGeneration) return;
            // Remove animation clocks before assigning the terminal geometry; otherwise WPF's
            // animated value can continue to mask Width/Opacity base values after completion.
            _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, null);
            _queueDrawer.BeginAnimation(UIElement.OpacityProperty, null);
            _queueDrawer.Width = 0;
            _queueDrawer.Opacity = 0;
            _queueDrawer.Visibility = Visibility.Collapsed;

            // R61.106.30: Queue owns a taller workbench while open. Closing returns the shell to
            // the controller's natural height unless detached media intentionally owns the lower plane.
            _queueExpansionWidth = 0;
            _queueExpansionShiftX = 0;

            ApplyQueueCanvasLayout(true);
            if (_compactQueueReturnProfile != WorkspaceProfile.Custom)
                ReturnToCompactAfterQueueClose();
            else
                ApplyAdaptiveLayout(true);

            ScheduleQueueHorizonMarker();
            if (!MediaStageVisible()) SnapWindowToControllerHeight();
            SaveUiState();
        }

        private void SetQueueOpen(bool open, bool animate)
        {
            // If the operator explicitly changes Queue while an automatic Micro detour is active,
            // that newer choice supersedes the intent captured on entry. The automatic profile
            // transition itself runs with _automaticScaleApplying and therefore cannot overwrite it.
            if (_microMode && _responsiveQueueIntentValid && !_automaticScaleApplying)
                _responsiveQueueIntentOpen = open;

            if (_queueOpen == open && _queueDrawer.Visibility == (open ? Visibility.Visible : Visibility.Collapsed))
            {
                if (open) { EnsureQueueUiMaterialized("open-reuse"); ExpandWindowForQueue(); }
                else if (!MediaStageVisible()) SnapWindowToControllerHeight();
                return;
            }

            int transitionGeneration = ++_queueTransitionGeneration;
            _queueOpen = open;
            _queueToggle.IsChecked = open;
            ApplyVideoBackdropPresentation();
            if (open) ExpandWindowForQueue();
            ApplyCompactLayoutForSize();

            var duration = _reduceMotion ? TimeSpan.Zero : TimeSpan.FromMilliseconds(170);

            if (open)
            {
                // R61.88: opening the Queue is the demand signal for WPF row materialization.
                // The drawer can animate immediately while rows arrive in Background slices.
                EnsureQueueUiMaterialized("open");
                if (ShouldUseQueueCanvasLayout())
                {
                    // R61.106.30: Queue is a vertical workbench. ExpandWindowForQueue has already
                    // made enough shell height available before this reflow is composed.
                    _queueExpansionWidth = 0;
                    _queueExpansionShiftX = 0;
                    ApplyQueueCanvasLayout(true);
                    _lastQueueFollowOccurrence = 0;
                    QueueRow openingCurrentCanvas;
                    if (_queueFollowCurrent && _currentOccurrence > 0 && _queueByOccurrence.TryGetValue(_currentOccurrence, out openingCurrentCanvas) && QueueFilter(openingCurrentCanvas))
                        ScrollQueueRowToTop(openingCurrentCanvas);
                    ScheduleQueueHorizonMarker();
                    RestorePendingQueueContextAnchor();
                    RestorePendingQueueInteractionContext();
                    SaveUiState();
                    return;
                }
                // Cancel a closing clock before measuring the base player. CaptureNormalWindowGeometry
                // subtracts the remembered Queue expansion, so a rapid close->open cannot inflate
                // the persisted Full-player width.
                _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, null);
                _queueDrawer.BeginAnimation(UIElement.OpacityProperty, null);
                _queueDrawer.Visibility = Visibility.Visible;
                if (_window.WindowState == WindowState.Normal)
                {
                    if (_legacyQueueGeometryLoaded)
                    {
                        // R47 migration: schema-10 builds persisted the already-expanded width.
                        double baseHint = Math.Max(_window.MinWidth, _normalWidth);
                        _queueExpansionWidth = Math.Min(452, Math.Max(0, _window.Width - baseHint));
                        _legacyQueueGeometryLoaded = false;
                    }
                    CaptureNormalWindowGeometry();
                    _queueExpansionWidth = 0;
                    _queueExpansionShiftX = 0;
                }
                else
                {
                    _queueExpansionWidth = 0;
                    _queueExpansionShiftX = 0;
                    _queueDrawer.Width = 438;
                }

                double drawerWidth = Math.Max(280, _queueDrawer.Width);
                if (animate && duration > TimeSpan.Zero)
                {
                    _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, new DoubleAnimation(0, drawerWidth, duration) { EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseOut } });
                    _queueDrawer.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(0, 1, duration));
                }
                else
                {
                    _queueDrawer.Width = drawerWidth;
                    _queueDrawer.Opacity = 1;
                }

                _lastQueueFollowOccurrence = 0;
                QueueRow openingCurrent;
                if (_queueFollowCurrent && _currentOccurrence > 0 && _queueByOccurrence.TryGetValue(_currentOccurrence, out openingCurrent) && QueueFilter(openingCurrent))
                    ScrollQueueRowToTop(openingCurrent);

                ScheduleQueueHorizonMarker();
                RestorePendingQueueContextAnchor();
                RestorePendingQueueInteractionContext();
                SaveUiState();
                return;
            }

            if (_queueCanvasActive || !animate || duration <= TimeSpan.Zero)
            {
                FinalizeQueueClose(transitionGeneration);
                ApplyQueueCanvasLayout(true);
                return;
            }

            double fromWidth = Math.Max(0, _queueDrawer.ActualWidth > 0 ? _queueDrawer.ActualWidth : _queueDrawer.Width);
            var widthAnimation = new DoubleAnimation(fromWidth, 0, duration) { EasingFunction = new QuadraticEase { EasingMode = EasingMode.EaseIn } };
            widthAnimation.Completed += delegate { FinalizeQueueClose(transitionGeneration); };
            _queueDrawer.BeginAnimation(FrameworkElement.WidthProperty, widthAnimation);
            _queueDrawer.BeginAnimation(UIElement.OpacityProperty, new DoubleAnimation(_queueDrawer.Opacity, 0, duration));
            // Persistence and base-window geometry commit at animation completion, not at request time.
            // This removes the old race where Queue=false was persisted against an expanded window.
        }

        private bool QueueDragEditingAllowed()
        {
            return _queueScope == QueueScope.All && String.IsNullOrWhiteSpace(_queueSearchBox.Text);
        }

        private void SetQueueDropIndicator(QueueRow row, bool after)
        {
            if (_queueDropRow == row && _queueDropAfter == after)
                return;
            ClearQueueDropIndicator();
            _queueDropRow = row;
            _queueDropAfter = after;
            if (row == null) return;
            row.DropBorderBrush = Brush("Accent");
            row.DropBorderThickness = after ? new Thickness(0, 0, 0, 2) : new Thickness(0, 2, 0, 0);
        }

        private void ClearQueueDropIndicator()
        {
            if (_queueDropRow != null)
            {
                _queueDropRow.DropBorderBrush = Brushes.Transparent;
                _queueDropRow.DropBorderThickness = new Thickness(0);
            }
            _queueDropRow = null;
            _queueDropAfter = false;
            _queueDropToEnd = false;
            if (_queueDropEndIndicator != null) _queueDropEndIndicator.Visibility = Visibility.Collapsed;
        }

        private string SelectedOccurrenceCsv(bool excludeCurrent)
        {
            var rows = SelectedQueueRows();
            if (excludeCurrent)
                rows = rows.Where(r => r.OccurrenceId != _currentOccurrence).ToList();
            return String.Join(",", rows.Select(r => r.OccurrenceId.ToString(CultureInfo.InvariantCulture)).ToArray());
        }

        private bool WouldBlockMoveChangeOrder(string occurrenceCsv, int targetBoundary)
        {
            var wanted = new HashSet<int>();
            foreach (string token in (occurrenceCsv ?? "").Split(','))
            {
                int occ;
                if (Int32.TryParse(token.Trim(), NumberStyles.Integer, CultureInfo.InvariantCulture, out occ) &&
                    occ > 0 && occ != _currentOccurrence && _order.Contains(occ))
                    wanted.Add(occ);
            }
            if (wanted.Count == 0) return false;

            var block = new List<int>();
            var remaining = new List<int>();
            int removedBefore = 0;
            for (int i = 0; i < _order.Count; i++)
            {
                int occ = _order[i];
                int slot = i + 1;
                if (wanted.Contains(occ))
                {
                    block.Add(occ);
                    if (slot < targetBoundary) removedBefore++;
                }
                else remaining.Add(occ);
            }

            int adjusted = Math.Max(1, Math.Min(remaining.Count + 1, targetBoundary - removedBefore));
            remaining.InsertRange(adjusted - 1, block);
            return !remaining.SequenceEqual(_order);
        }

        private bool OrderMutationBusy
        {
            get { return _orderMutationRequestPending || _pendingOrderMutationSerial >= 0 || _pendingOrderMutationRevision >= 0; }
        }

        private void UpdateOrderMutationControls()
        {
            bool enabled = !OrderMutationBusy;
            if (_previousAgainButton != null) _previousAgainButton.IsEnabled = enabled;
            if (_nextLaterButton != null) _nextLaterButton.IsEnabled = enabled;
            if (_queueSelectionPlayNextButton != null) _queueSelectionPlayNextButton.IsEnabled = enabled;
            if (_queueSelectionLaterButton != null) _queueSelectionLaterButton.IsEnabled = enabled;
            if (_queueSelectionRemoveButton != null) _queueSelectionRemoveButton.IsEnabled = enabled;
        }

        private bool TryBeginOrderMutationRequest(string kind)
        {
            if (!_running) return false;
            if (OrderMutationBusy)
            {
                ShowToast("Queue updating", "Wait for the current order change to finish committing.");
                return false;
            }
            _orderMutationRequestPending = true;
            _orderMutationRequestKind = kind ?? "";
            _orderMutationRequestBaseRevision = Math.Max(0, _orderRevision);
            _orderMutationRequestBaseSerial = Math.Max(0, _orderCommandSerial);
            UpdateOrderMutationControls();
            return true;
        }

        private void EndOrderMutationRequest()
        {
            _orderMutationRequestPending = false;
            _orderMutationRequestKind = "";
            UpdateOrderMutationControls();
        }

        private void BeginPendingOrderMutation(string description, string kind)
        {
            _pendingOrderMutationRevision = Math.Max(0, _orderMutationRequestBaseRevision);
            _pendingOrderMutationSerial = Math.Max(0, _orderMutationRequestBaseSerial);
            _pendingOrderMutationStartedMs = _clock.ElapsedMilliseconds;
            _pendingOrderMutationDescription = description ?? "";
            _pendingOrderMutationKind = kind ?? "";
            _lastQueueRefreshMs = 0;
            UpdateOrderMutationControls();
            if (_queueRevisionText != null)
                _queueRevisionText.Text = Math.Max(0, _orderRevision).ToString(CultureInfo.InvariantCulture) + " | UPDATING";
        }

        private void ClearPendingOrderMutation()
        {
            _pendingOrderMutationRevision = -1;
            _pendingOrderMutationSerial = -1;
            _pendingOrderMutationDescription = "";
            _pendingOrderMutationKind = "";
            UpdateOrderMutationControls();
        }

        private void DispatchOrderMutation(object[] command, string kind, string description, string activity, string requestedTitle, string requestedBody, Action acceptedUi)
        {
            if (command == null || command.Length == 0) return;
            if (!TryBeginOrderMutationRequest(kind)) return;
            DispatchTransportCommand(command, delegate(bool accepted)
            {
                if (!accepted)
                {
                    EndOrderMutationRequest();
                    ShowToast(requestedTitle, "The engine did not accept the queue change.");
                    return;
                }
                BeginPendingOrderMutation(description, kind);
                EndOrderMutationRequest();
                if (acceptedUi != null)
                {
                    try { acceptedUi(); } catch { }
                }
                AddActivity("Queue order", activity);
                ShowToast(requestedTitle, requestedBody);
                ScheduleFastQueueRefresh();
            });
        }

        private void UndoQueueOrder()
        {
            DispatchOrderMutation(new object[] { "script-message", "yomi-order-undo" }, "undo", "undo order change", "undo requested", "Undo requested", "Waiting for authoritative queue confirmation...", null);
        }

        private void RedoQueueOrder()
        {
            DispatchOrderMutation(new object[] { "script-message", "yomi-order-redo" }, "redo", "redo order change", "redo requested", "Redo requested", "Waiting for authoritative queue confirmation...", null);
        }

        private void ReshuffleQueueTail()
        {
            if (_currentSlot <= 0 || _currentSlot >= _order.Count)
            {
                ShowToast("Reshuffle tail", "There is no upcoming tail to reshuffle.");
                return;
            }
            DispatchOrderMutation(new object[] { "script-message", "yomi-order-reshuffle-unprepared" }, "reshuffle-tail", "reshuffle upcoming tail", "reshuffle requested", "Reshuffle requested", "Waiting for authoritative queue confirmation...", null);
        }

        private void RestoreOriginalQueueOrder()
        {
            DispatchOrderMutation(new object[] { "script-message", "yomi-order-restore" }, "restore-original", "restore original order", "restore original requested", "Restore requested", "Waiting for authoritative queue confirmation...", null);
        }

        private void MoveOccurrenceBlock(string occurrenceCsv, int targetBoundary, string source)
        {
            if (!_running || String.IsNullOrWhiteSpace(occurrenceCsv) || _order.Count == 0)
                return;
            targetBoundary = Math.Max(1, Math.Min(_order.Count + 1, targetBoundary));
            if (!WouldBlockMoveChangeOrder(occurrenceCsv, targetBoundary))
            {
                ShowToast("Queue reorder", "Selection is already at that position.");
                return;
            }
            int requestedBoundary = targetBoundary;
            string requestedSource = source ?? "reorder";
            DispatchOrderMutation(
                new object[] { "script-message", "yomi-order-move-block", occurrenceCsv, requestedBoundary.ToString(CultureInfo.InvariantCulture) },
                "move-block",
                requestedSource + " -> boundary " + requestedBoundary.ToString(CultureInfo.InvariantCulture),
                "reorder requested | " + requestedSource,
                "Reorder requested",
                "Waiting for authoritative queue confirmation...",
                null);
        }

        private void MoveSelectedBlockToBoundary(int targetBoundary, string source)
        {
            string csv = SelectedOccurrenceCsv(true);
            if (String.IsNullOrWhiteSpace(csv))
            {
                ShowToast("Queue reorder", "Select one or more non-playing occurrences.");
                return;
            }
            MoveOccurrenceBlock(csv, targetBoundary, source);
        }

        private void MoveSelectedBlockByOne(int direction)
        {
            if (!_running || direction == 0)
                return;
            var rows = SelectedQueueRows().Where(r => r.OccurrenceId != _currentOccurrence).OrderBy(r => r.Slot).ToList();
            if (rows.Count == 0)
            {
                ShowToast("Queue reorder", "Select one or more non-playing occurrences.");
                return;
            }
            int target;
            if (direction < 0)
            {
                if (rows.First().Slot <= 1) return;
                target = rows.First().Slot - 1;
            }
            else
            {
                if (rows.Last().Slot >= _order.Count) return;
                target = rows.Last().Slot + 2;
            }
            string csv = String.Join(",", rows.Select(r => r.OccurrenceId.ToString(CultureInfo.InvariantCulture)).ToArray());
            MoveOccurrenceBlock(csv, target, direction < 0 ? "keyboard-up" : "keyboard-down");
        }

        private void UpdateQueueSelectionBar()
        {
            if (_queueSelectionBar == null || _queueSelectionCountText == null)
                return;
            List<QueueRow> rows = SelectedQueueRows();
            int count = rows.Count;
            _queueSelectionBar.Visibility = count > 1 ? Visibility.Visible : Visibility.Collapsed;
            if (count <= 1)
            {
                _queueSelectionCountText.Text = "";
                return;
            }

            double duration = rows.Where(r => r.DurationSeconds > 0).Sum(r => r.DurationSeconds);
            int knownDurations = rows.Count(r => r.DurationSeconds > 0);
            int favorites = rows.Count(r => r.IsFavorite);
            int plays = rows.Sum(r => Math.Max(0, r.PlayCount));
            var parts = new List<string>
            {
                count.ToString(CultureInfo.InvariantCulture) + " SELECTED"
            };
            if (duration > 0)
                parts.Add(FormatTime(duration) + (knownDurations < count ? "+" : ""));
            if (favorites > 0)
                parts.Add(favorites.ToString(CultureInfo.InvariantCulture) + " favorites");
            if (plays > 0)
                parts.Add(plays.ToString(CultureInfo.InvariantCulture) + " PLAYS");
            _queueSelectionCountText.Text = String.Join("  |  ", parts.ToArray());
        }

        private List<QueueRow> SelectedQueueRows()
        {
            var rows = new List<QueueRow>();
            if (_queueList == null) return rows;
            foreach (var item in _queueList.SelectedItems)
            {
                var row = item as QueueRow;
                if (row != null && QueueFilter(row) && !rows.Contains(row)) rows.Add(row);
            }
            if (rows.Count == 0)
            {
                var row = _queueList.SelectedItem as QueueRow;
                if (row != null && QueueFilter(row)) rows.Add(row);
            }
            return rows.OrderBy(r => r.Slot).ToList();
        }

        private void QueueTemplateActionClick(object sender, RoutedEventArgs e)
        {
            var button = e.OriginalSource as Button;
            if (button == null) return;
            string action = button.Tag as string;
            if (String.IsNullOrWhiteSpace(action) || !action.StartsWith("queue-row-", StringComparison.Ordinal))
                return;
            var row = button.DataContext as QueueRow;
            if (row == null) return;

            if (action == "queue-row-play")
            {
                if (row.OccurrenceId == _currentOccurrence && _running)
                {
                    string intent = _paused ? "resume" : (_audioActive ? "pause" : "play");
                    TogglePlayPause();
                    AddActivity("Queue inline", intent + " current | ITEM " + row.OccurrenceId.ToString(CultureInfo.InvariantCulture));
                }
                else if (_running)
                {
                    int occurrence = row.OccurrenceId;
                    DispatchTransportCommand(new object[] { "script-message", "yomi-jump", occurrence.ToString(CultureInfo.InvariantCulture) }, delegate(bool accepted)
                    {
                        if (!accepted) { ShowToast("Play now", "The engine did not accept the play request."); return; }
                        BeginPlaybackTransitionProjection();
                        AddActivity("Queue inline", "play | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture));
                        ScheduleFastPlaybackRefresh();
                    });
                }
            }
            else if (action == "queue-row-next")
            {
                if (row.OccurrenceId == _currentOccurrence && _running)
                {
                    NavigateRelative(1);
                    AddActivity("Queue inline", "skip current | ITEM " + row.OccurrenceId.ToString(CultureInfo.InvariantCulture));
                }
                else if (_running)
                {
                    int occurrence = row.OccurrenceId;
                    bool moveLater = row.Slot == _currentSlot + 1;
                    object[] command = moveLater
                        ? new object[] { "script-message", "yomi-order-move-later", occurrence.ToString(CultureInfo.InvariantCulture), "5" }
                        : new object[] { "script-message", "yomi-order-play-next", occurrence.ToString(CultureInfo.InvariantCulture) };
                    DispatchOrderMutation(
                        command,
                        moveLater ? "inline-move-later" : "inline-play-next",
                        (moveLater ? "move later +5" : "play next") + " | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture),
                        (moveLater ? "later +5" : "play-next") + " | ITEM " + occurrence.ToString(CultureInfo.InvariantCulture),
                        moveLater ? "Move later requested" : "Play next requested",
                        row.Title,
                        null);
                }
            }
            else if (action == "queue-row-favorite")
            {
                TrackMeta meta;
                if (_trackMeta.TryGetValue(row.OccurrenceId, out meta))
                    ToggleFavorite(meta);
            }
            else if (action == "queue-row-inspect")
            {
                if (_queueList != null)
                {
                    _queueList.SelectedItems.Clear();
                    _queueList.SelectedItem = row;
                    _queueList.ScrollIntoView(row);
                }
                SetInspectorOpen(true, true);
                RefreshInspector();
                AddActivity("Queue inline", "inspect readiness | ITEM " + row.OccurrenceId.ToString(CultureInfo.InvariantCulture));
            }
            e.Handled = true;
        }

        private void BatchPrepareSelected()
        {
            if (!_running) return;
            var rows = SelectedQueueRows();
            if (rows.Count == 0) return;
            int sent = 0;
            foreach (var row in rows.Take(20))
