        private void CopySelectedQueueRows(bool urlsOnly)
        {
            var rows = SelectedQueueRows();
            if (rows.Count == 0) return;
            var lines = new List<string>();
            foreach (var row in rows)
            {
                TrackMeta meta;
                _trackMeta.TryGetValue(row.OccurrenceId, out meta);
                if (urlsOnly)
                {
                    if (meta != null && !String.IsNullOrWhiteSpace(meta.Url)) lines.Add(meta.Url);
                }
                else
                {
                    string channel = meta != null ? meta.Channel : row.Channel;
                    lines.Add(String.IsNullOrWhiteSpace(channel) ? row.Title : row.Title + " - " + channel);
                }
            }
            if (lines.Count == 0) return;
            try
            {
                Clipboard.SetText(String.Join(Environment.NewLine, lines.ToArray()));
                ShowToast("Copied selection", lines.Count.ToString(CultureInfo.InvariantCulture) + " item" + (lines.Count == 1 ? "" : "s"));
            }
            catch { }
        }

