        {
            return NewIntent("Queue Triage", trigger, false, false, false,
                ShellStep("Enter Library workspace", "shell.workspace", delegate { ApplyWorkspaceProfile(WorkspaceProfile.Library, true); }, delegate(IntentExecution r) { RestoreShellSnapshot(r.Snapshot); }),
                ShellStep("Open queue", "shell.queue-view", delegate { SetQueueOpen(true, true); }),
