        private bool IsBroadcastFreezeActive()
        {
            var queue = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
            return GetBool(GetMap(queue, "freeze"), "active", false);
        }

        private void RequestFreezeWhenRehearsalVisible(int attemptsRemaining)
        {
            if (!_running) return;
            var queue = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
            if (GetBool(GetMap(queue, "freeze"), "active", false))
            {
                AddActivity("Operator", "Lock Window already frozen");
                ShowToast("Lock Window", "Broadcast Freeze is already active.");
                return;
            }
            if (GetBool(GetMap(queue, "rehearsal"), "active", false))
            {
                ToggleBroadcastFreeze();
                AddActivity("Operator", "Lock Window freeze requested after rehearsal confirmation");
                ShowToast("Lock Window", "Rehearsal confirmed | Broadcast Freeze requested");
                return;
            }
            if (attemptsRemaining <= 0)
            {
                AddActivity("Operator", "Lock Window aborted | rehearsal not confirmed");
                ShowToast("Lock Window", "Rehearsal was not confirmed; Freeze was not toggled.");
                return;
            }
            ScheduleUiAction(300, delegate { RequestFreezeWhenRehearsalVisible(attemptsRemaining - 1); });
        }

        private void ScheduleUiAction(int milliseconds, Action action)
        {
            var delayed = new DispatcherTimer(DispatcherPriority.Background)
            {
                Interval = TimeSpan.FromMilliseconds(Math.Max(1, milliseconds))
            };
            EventHandler tick = null;
            tick = delegate
            {
                delayed.Tick -= tick;
                delayed.Stop();
                try { action(); } catch { }
            };
            delayed.Tick += tick;
            delayed.Start();
        }

        private void SetOperatorChip(Border chip, TextBlock text, string label, string state)
        {
            text.Text = label;
            string normalized = (state ?? "").ToUpperInvariant();
            if (normalized == "OK" || normalized == "HEALTHY" || normalized == "NOMINAL" || normalized == "NORMAL" || normalized == "READY" || normalized == "LIVE")
            {
                chip.Background = Brush("AccentSoft");
                chip.BorderBrush = Brush("AccentBorder");
                text.Foreground = Brush("Accent");
            }
            else if (normalized == "WARN" || normalized == "WATCH" || normalized == "THIN" || normalized == "CONSERVE" || normalized == "REHEARSE")
            {
                chip.Background = Brush("WarningSoft");
                chip.BorderBrush = Brush("Warning");
                text.Foreground = Brush("Warning");
            }
            else if (normalized == "FAIL" || normalized == "ATTENTION" || normalized == "AT_RISK" || normalized == "BROWNOUT" || normalized == "EMERGENCY" || normalized == "SAFE_MODE")
            {
                chip.Background = Brush("DangerSoft");
                chip.BorderBrush = Brush("Danger");
                text.Foreground = Brush("Danger");
            }
            else
            {
                chip.Background = Brush("SurfaceRaised");
                chip.BorderBrush = Brush("Border");
                text.Foreground = Brush("TextMuted");
            }
        }

        private void UpdateOperatorIntelligence(Dictionary<string, object> queue, Dictionary<string, object> engine)
        {
            bool broadcastAttention = _workspaceProfile == WorkspaceProfile.Broadcast && BroadcastSurfaceNeedsAttention(queue, engine);
            bool show = !_miniMode && (_informationDensity == InformationDensity.Technical || broadcastAttention);
            _operatorHealthRail.Visibility = show ? Visibility.Visible : Visibility.Collapsed;
            // The health rail lives inside RuntimeSurface. In calm Broadcast mode that parent is normally
            // collapsed, so only an actual exception is allowed to bring the whole strip back.
            if (_workspaceProfile == WorkspaceProfile.Broadcast && _informationDensity != InformationDensity.Technical)
            {
                if (broadcastAttention && _runtimeSurface != null) _runtimeSurface.Visibility = Visibility.Visible;
                else UpdateRuntimeSurfaceVisibility(_lastObservedPhase);
            }
            if (!show) return;

            string health = GetString(queue, "buffer_health", "-").ToUpperInvariant();
            int ready = GetInt(queue, "ready_ahead", 0);
            int target = GetInt(queue, "target_ahead", 0);
            int readySeconds = (int)Math.Max(0, Math.Round(GetDouble(queue, "ready_time_seconds", 0)));
            SetOperatorChip(_operatorBufferChip, _operatorBufferText,
                "Buffer " + FriendlyStateWord(health) + " " + ready.ToString(CultureInfo.InvariantCulture) + "/" + target.ToString(CultureInfo.InvariantCulture) + (readySeconds > 0 ? " | " + FormatTime(readySeconds) : ""), health);

            var oracle = GetMap(queue, "oracle");
            string oracleVerdict = GetString(oracle, "verdict", "-").ToUpperInvariant();
            int oracleAverage = GetInt(oracle, "confidence_average", -1);
            string oracleLabel = "Forecast " + FriendlyStateWord(oracleVerdict) + (oracleAverage >= 0 ? " " + oracleAverage.ToString(CultureInfo.InvariantCulture) + "%" : "");
            SetOperatorChip(_operatorOracleChip, _operatorOracleText, oracleLabel, oracleVerdict);

            var resource = GetMap(queue, "resource");
            string governor = GetString(resource, "governor_mode", "-").ToUpperInvariant();
            int effective = GetInt(resource, "effective_workers", -1);
            int configured = GetInt(resource, "configured_workers", -1);
            string aegisLabel = "Protection " + FriendlyStateWord(governor) + (effective >= 0 && configured >= 0 ? " " + effective.ToString(CultureInfo.InvariantCulture) + "/" + configured.ToString(CultureInfo.InvariantCulture) : "");
            SetOperatorChip(_operatorAegisChip, _operatorAegisText, aegisLabel, governor);

            string orderLabel = _orderRevision >= 0 ? "Queue " + _orderRevision.ToString(CultureInfo.InvariantCulture) : "Queue —";
            if (OrderMutationBusy) orderLabel += " · pending";
            SetOperatorChip(_operatorOrderChip, _operatorOrderText, orderLabel, OrderMutationBusy ? "WATCH" : (_orderRevision >= 0 ? "OK" : ""));

            var rehearsal = GetMap(queue, "rehearsal");
            var freeze = GetMap(queue, "freeze");
            bool rehearsalActive = GetBool(rehearsal, "active", false);
            bool freezeActive = GetBool(freeze, "active", false);
            string broadcastLabel = "Broadcast idle";
            string broadcastState = "";
            if (freezeActive)
            {
                broadcastLabel = "Prepared window " + GetInt(freeze, "count", 0).ToString(CultureInfo.InvariantCulture);
                broadcastState = "READY";
            }
            else if (rehearsalActive)
            {
                broadcastLabel = "Broadcast check " + GetInt(rehearsal, "sync_ready", 0).ToString(CultureInfo.InvariantCulture) + "/" + GetInt(rehearsal, "target", 0).ToString(CultureInfo.InvariantCulture);
                broadcastState = "REHEARSE";
            }
            SetOperatorChip(_operatorBroadcastChip, _operatorBroadcastText, broadcastLabel, broadcastState);
            UpdateIntentRailChip();
            UpdateOperatorDeckStatus(queue, engine);
        }

        private void UpdateIntentRailChip()
        {
            if (_operatorIntentChip == null || _operatorIntentText == null) return;
            string label = "No action in progress";
            string state = "";
            if (_activeIntent != null && !IsTerminalIntentState(_activeIntent.State))
            {
                label = "Action " + FriendlyStateWord(_activeIntent.State) + " · " + ShortIntentId(_activeIntent.Id);
                state = _activeIntent.State == "AWAITING_AUTHORITY" ? "WATCH" : "READY";
            }
            else if (!_intentJournalHealthy)
            {
                label = "Action recovery needed";
                state = "ATTENTION";
            }
            SetOperatorChip(_operatorIntentChip, _operatorIntentText, label, state);
        }

        private void UpdateOperatorDeckStatus(Dictionary<string, object> queue, Dictionary<string, object> engine)
        {
            if (_operatorDeckStatusText == null) return;
            if (queue == null) queue = ReadJsonCached(Path.Combine(_stateRoot, "queue-runtime.json"));
            if (engine == null) engine = ReadJsonCached(Path.Combine(_stateRoot, "engine.json"));
            string health = GetString(queue, "buffer_health", "-").ToUpperInvariant();
            string oracle = GetString(GetMap(queue, "oracle"), "verdict", "-").ToUpperInvariant();
            string governor = GetString(GetMap(queue, "resource"), "governor_mode", "-").ToUpperInvariant();
            string runtime = _running ? (_paused ? "paused" : (_audioActive ? "playing" : "ready")) : "stopped";
            string revision = _orderRevision >= 0 ? "R" + _orderRevision.ToString(CultureInfo.InvariantCulture) : "-";
            string last = String.IsNullOrWhiteSpace(_lastOperatorAction) ? "" : " · Last: " + _lastOperatorAction;
            string intent = _activeIntent == null ? "none" : FriendlyStateWord(_activeIntent.State) + "/" + ShortIntentId(_activeIntent.Id);
            _operatorDeckStatusText.Text = "Player: " + runtime + " · Buffer: " + FriendlyStateWord(health) + " · Forecast: " + FriendlyStateWord(oracle) + " · Protection: " + FriendlyStateWord(governor) + " · Queue: " + revision + " · Action: " + intent + last;
        }

        private void OpenSystemActivity()
        {
            if (_miniMode) SetMiniMode(false, true);
            SetInspectorOpen(true, true);
            RefreshInspector();
        }

        private void OpenPlaybackHistory()
        {
            if (_miniMode) SetMiniMode(false, true);
            SetQueueOpen(true, true);
            SetQueueScope(QueueScope.History);
            SetInspectorOpen(true, true);
            FollowCurrentQueueRow();
        }

        private static string FriendlyStateWord(string value)
        {
            string text = (value ?? "").Trim().Replace('_', ' ').ToLowerInvariant();
            if (String.IsNullOrWhiteSpace(text) || text == "-") return "unknown";
            return Char.ToUpperInvariant(text[0]) + text.Substring(1);
        }

        private static string FriendlyGovernorText(string mode, string reason)
        {
            string normalized = (mode ?? "").Trim().ToUpperInvariant();
            if (normalized == "CONSERVE") return "Background work is reduced to protect foreground performance.";
            if (normalized == "BROWNOUT" || normalized == "EMERGENCY" || normalized == "SAFE_MODE")
                return "Optional background work is sharply reduced to protect playback and foreground performance.";
            if (normalized == "NORMAL" || normalized == "NOMINAL" || normalized == "HEALTHY" || normalized == "READY")
                return "Resource protection is not currently limiting background work.";
            if (normalized == "" || normalized == "-" || normalized == "UNKNOWN")
                return "Resource protection status is not available yet.";
            if (!String.IsNullOrWhiteSpace(reason)) return "Resource protection is active: " + reason.Trim() + ".";
            return "Resource protection state is " + normalized.ToLowerInvariant().Replace('_', ' ') + ".";
        }

        private static string BuildSystemActivitySummary(Dictionary<string, object> queue, Dictionary<string, object> engine, bool running, bool audioActive, bool paused)
        {
            if (queue == null) queue = EmptyMap();
            if (engine == null) engine = EmptyMap();
            var resource = GetMap(queue, "resource");
            var performance = GetMap(queue, "performance");
            string health = GetString(queue, "buffer_health", "").ToUpperInvariant();
            int ready = GetInt(queue, "ready_ahead", 0);
            int target = GetInt(queue, "target_ahead", 0);
            int workers = GetInt(queue, "workers", GetInt(engine, "workers", 0));
            int active = GetInt(queue, "active_jobs", 0);
            int queued = GetInt(queue, "queued_jobs", 0);
            string governor = GetString(resource, "governor_mode", "");
            string governorReason = GetString(resource, "governor_reason", "");
            int anomalies = GetInt(performance, "anomalies", 0);
            int samples = GetInt(performance, "samples", 0);

            string load;
            string gov = (governor ?? "").ToUpperInvariant();
            if (gov == "BROWNOUT" || gov == "EMERGENCY" || gov == "SAFE_MODE" || health == "AT_RISK") load = "PROTECTED";
            else if (gov == "CONSERVE" || health == "THIN" || active > Math.Max(2, workers)) load = "REDUCED";
            else if (active > 0 || queued > 0) load = "ACTIVE";
            else load = "QUIET";

            var parts = new List<string>();
            parts.Add(FriendlyStateWord(load));
            parts.Add(!running ? "Playback is stopped" : (paused ? "Playback is paused" : (audioActive ? "Audio playback is active" : "Playback engine is ready; no active audio stream is confirmed")));
            if (workers <= 0 || (active == 0 && queued == 0))
                parts.Add("Background preparation is idle");
            else
            {
                string work = active.ToString(CultureInfo.InvariantCulture) + " background " + (active == 1 ? "job is" : "jobs are") + " preparing media";
                if (workers > 0) work += " across " + workers.ToString(CultureInfo.InvariantCulture) + " " + (workers == 1 ? "worker" : "workers");
                if (queued > 0) work += ", with " + queued.ToString(CultureInfo.InvariantCulture) + " waiting";
                parts.Add(work);
            }
            if (target > 0)
            {
                if (health == "HEALTHY") parts.Add("Upcoming audio is prepared " + ready.ToString(CultureInfo.InvariantCulture) + "/" + target.ToString(CultureInfo.InvariantCulture));
                else if (health == "THIN") parts.Add("The upcoming audio buffer is thin at " + ready.ToString(CultureInfo.InvariantCulture) + "/" + target.ToString(CultureInfo.InvariantCulture));
                else parts.Add("Upcoming audio readiness is " + ready.ToString(CultureInfo.InvariantCulture) + "/" + target.ToString(CultureInfo.InvariantCulture));
            }
            parts.Add(FriendlyGovernorText(governor, governorReason).TrimEnd('.'));
            if (anomalies > 0)
                parts.Add(anomalies.ToString(CultureInfo.InvariantCulture) + " recent preparation timing " + (anomalies == 1 ? "anomaly" : "anomalies") + " recorded");
            else if (samples > 0)
                parts.Add("No recent preparation timing anomaly is recorded");
            return String.Join(". ", parts.ToArray()) + ".";
        }

        public bool SelfTestSurfaceLanguage()
        {
            _selfTestFailureDetail = "";
            try
            {
                if (QueueRow.ProductStatus("POLICY READY") != "Ready · protected") return SelfTestFail("SelfTestSurfaceLanguage assertion 1");
                if (QueueRow.ProductStatus("ISOLATED READY") != "Ready · contained") return SelfTestFail("SelfTestSurfaceLanguage assertion 2");
                if (QueueRow.ProductStatus("BUILDING") != "PREPARING") return SelfTestFail("SelfTestSurfaceLanguage assertion 3");
                if (QueueRow.ProductSafety("AUDIO WON SLA") != "AUDIO FIRST") return SelfTestFail("SelfTestSurfaceLanguage assertion 4");
                if (QueueRow.ProductSafety("SLACK -8s") != "MARGIN -8s") return SelfTestFail("SelfTestSurfaceLanguage assertion 5");
                if (QueueRow.ProductSafety("POLICY READY") != "RESOURCES PROTECTED") return SelfTestFail("SelfTestSurfaceLanguage assertion 6");
                if (StageDisplay("DEFERRED_CIRCUIT") != "CONTAINED") return SelfTestFail("SelfTestSurfaceLanguage assertion 7");
                if (StageDisplay("DEFERRED_ADMISSION") != "DEFERRED") return SelfTestFail("SelfTestSurfaceLanguage assertion 8");
                if (StatusNeedsAttention("HEALTHY") || StatusNeedsAttention("NORMAL") || StatusNeedsAttention("UNKNOWN")) return SelfTestFail("SelfTestSurfaceLanguage assertion 9");
                if (!StatusNeedsAttention("THIN") || !StatusNeedsAttention("CONSERVE") || !StatusNeedsAttention("AT_RISK")) return SelfTestFail("SelfTestSurfaceLanguage assertion 10");
                var calmBroadcast = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "buffer_health", "healthy" },
                    { "resource", new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "governor_mode", "normal" } } }
                };
                if (BroadcastSurfaceNeedsAttention(calmBroadcast, new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "phase", "playing" } })) return SelfTestFail("SelfTestSurfaceLanguage assertion 11");
                var thinBroadcast = new Dictionary<string, object>(calmBroadcast, StringComparer.OrdinalIgnoreCase);
                thinBroadcast["buffer_health"] = "thin";
                if (!BroadcastSurfaceNeedsAttention(thinBroadcast, EmptyMap())) return SelfTestFail("SelfTestSurfaceLanguage assertion 12");
                return true;
            }
            catch { return SelfTestFail("SelfTestSurfaceLanguage assertion 13"); }
        }

