                if (_nextUpStateText != null && _nextUpStateText.Visibility != Visibility.Collapsed)
                    return SelfTestFail("healthy NEXT readiness leaked into player chrome");
                bool oldQuiet = _quietSurface; string oldRepeat = _repeatMode; InformationDensity oldDensity = _informationDensity;
                try
                {
                    _quietSurface = true; _informationDensity = InformationDensity.Clean; _repeatMode = "all"; ApplyQuietSurface(false);
                    if (_footerHint != null && _footerHint.Visibility != Visibility.Collapsed) return SelfTestFail("quiet surface leaked shortcut wallpaper");
                    if (_repeatStatePill != null && _repeatStatePill.Visibility != Visibility.Collapsed) return SelfTestFail("Repeat controller button reappeared instead of remaining context-menu only");
                    if (_miniRepeatButton2 != null && !String.Equals(Convert.ToString(_miniRepeatButton2.Content, CultureInfo.InvariantCulture), "Repeat All", StringComparison.Ordinal)) return SelfTestFail("compact repeat affordance did not project Repeat All");
                    _repeatMode = "one"; UpdateRepeatPill();
                    if (_repeatStatePill != null && _repeatStatePill.Visibility != Visibility.Collapsed) return SelfTestFail("non-default repeat mode resurrected permanent controller chrome");
                }
                finally
                {
                    _quietSurface = oldQuiet; _repeatMode = oldRepeat; _informationDensity = oldDensity; ApplyQuietSurface(false);
                }
                return true;
            }
            catch (Exception ex) { return SelfTestFail("shell-fidelity exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public bool SelfTestTransportFidelity()
        {
            _selfTestFailureDetail = "";
            try
            {
                if (!ShouldShowPauseGlyph(true, true, false)) return SelfTestFail("SelfTestTransportFidelity assertion 1");
                if (ShouldShowPauseGlyph(true, false, false)) return SelfTestFail("SelfTestTransportFidelity assertion 2");
                if (ShouldShowPauseGlyph(true, true, true)) return SelfTestFail("SelfTestTransportFidelity assertion 3");
                if (ShouldShowPauseGlyph(false, true, false)) return SelfTestFail("SelfTestTransportFidelity assertion 4");
                if (ProductPlaybackPhase("preparing") != "PREPARING") return SelfTestFail("SelfTestTransportFidelity assertion 5");
                if (ProductPlaybackPhase("advancing") != "SKIPPING") return SelfTestFail("SelfTestTransportFidelity assertion 6");
                if (ProductPlaybackPhase("complete") != "COMPLETE") return SelfTestFail("SelfTestTransportFidelity assertion 7");
                if (ProductPlaybackPhase("error") != "ATTENTION") return SelfTestFail("SelfTestTransportFidelity assertion 8");
                string idleSummary = BuildSystemActivitySummary(EmptyMap(), EmptyMap(), true, false, false);
                if (idleSummary.IndexOf("no active audio stream is confirmed", StringComparison.Ordinal) < 0) return SelfTestFail("SelfTestTransportFidelity assertion 9");
                if (idleSummary.IndexOf("Audio playback is active", StringComparison.Ordinal) >= 0) return SelfTestFail("SelfTestTransportFidelity assertion 10");
                return true;
            }
            catch { return SelfTestFail("SelfTestTransportFidelity assertion 11"); }
        }

