        public bool SelfTestPlaylistPoolMixing()
        {
            _selfTestFailureDetail = "";
            try
            {
                var sources = new List<PoolSourceBuild>
                {
                    new PoolSourceBuild { Index = 1, Url = "https://example.invalid/a", Label = "A", Weight = 1 },
                    new PoolSourceBuild { Index = 2, Url = "https://example.invalid/b", Label = "B", Weight = 1 }
                };
                var tracks = new List<PoolTrackBuild>();
                for (int i = 0; i < 12; i++)
                {
                    var t = new PoolTrackBuild { Url = "https://example.invalid/a/" + i.ToString(CultureInfo.InvariantCulture), Id = "a" + i.ToString(CultureInfo.InvariantCulture) };
                    t.SourceIndexes.Add(1); t.SourceLabels.Add("A"); tracks.Add(t);
                }
                for (int i = 0; i < 3; i++)
                {
                    var t = new PoolTrackBuild { Url = "https://example.invalid/b/" + i.ToString(CultureInfo.InvariantCulture), Id = "b" + i.ToString(CultureInfo.InvariantCulture) };
                    t.SourceIndexes.Add(2); t.SourceLabels.Add("B"); tracks.Add(t);
                }
                ShufflePoolTracksBalanced(tracks, sources, 4208);
                if (tracks.Count != 15 || tracks.Select(x => x.Id).Distinct(StringComparer.Ordinal).Count() != 15) return SelfTestFail("playlist-pool balanced mix lost or duplicated tracks");
                int firstSixA = tracks.Take(6).Count(x => x.SourceIndexes.Contains(1));
                int firstSixB = tracks.Take(6).Count(x => x.SourceIndexes.Contains(2));
                if (firstSixA != 3 || firstSixB != 3) return SelfTestFail("playlist-pool equal-source balance expected 3/3 in first six; actual " + firstSixA.ToString(CultureInfo.InvariantCulture) + "/" + firstSixB.ToString(CultureInfo.InvariantCulture));
                sources[0].Weight = 2; sources[1].Weight = 1;
                tracks.Clear();
                for (int i = 0; i < 12; i++) { var t = new PoolTrackBuild { Id = "wa" + i.ToString(CultureInfo.InvariantCulture) }; t.SourceIndexes.Add(1); tracks.Add(t); }
                for (int i = 0; i < 6; i++) { var t = new PoolTrackBuild { Id = "wb" + i.ToString(CultureInfo.InvariantCulture) }; t.SourceIndexes.Add(2); tracks.Add(t); }
                ShufflePoolTracksBalanced(tracks, sources, 4208);
                int firstNineA = tracks.Take(9).Count(x => x.SourceIndexes.Contains(1));
                int firstNineB = tracks.Take(9).Count(x => x.SourceIndexes.Contains(2));
                if (firstNineA != 6 || firstNineB != 3) return SelfTestFail("playlist-pool 2x weighted balance expected 6/3 in first nine; actual " + firstNineA.ToString(CultureInfo.InvariantCulture) + "/" + firstNineB.ToString(CultureInfo.InvariantCulture));
                if (FormatPoolSourceSpec("https://example.invalid/list", 2) != "2x https://example.invalid/list") return SelfTestFail("playlist-pool source weight formatting mismatch");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("playlist-pool-mixing exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

        public bool SelfTestSessionSlots()
        {
            _selfTestFailureDetail = "";
            try
            {
                if (_slotSelector == null || _slotsManageButton == null || _slotsOverlay == null || _slotsList == null || _slotSwitchButton == null || _slotBroadcastPresetCombo == null || _slotBroadcastFollowCheck == null)
                    return SelfTestFail("session-slot controls are missing");
                if (String.IsNullOrWhiteSpace(_activeSlotId) || String.IsNullOrWhiteSpace(_activeSlotName))
                    return SelfTestFail("active slot identity was not initialized");
                SlotRecord active = ReadSlotRecord(_activeSlotId);
                if (active == null || !String.Equals(active.Id, _activeSlotId, StringComparison.OrdinalIgnoreCase))
                    return SelfTestFail("active slot manifest was not readable");
                Dictionary<string, object> descriptor = ReadJsonFresh(ActiveSlotDescriptorPath);
                if (!String.Equals(GetString(descriptor, "id", ""), _activeSlotId, StringComparison.OrdinalIgnoreCase))
                    return SelfTestFail("active-slot descriptor identity mismatch");
                if (!descriptor.ContainsKey("bookmark_occurrence") || !descriptor.ContainsKey("bookmark_seconds") || !descriptor.ContainsKey("paused") || !descriptor.ContainsKey("broadcast_preset"))
                    return SelfTestFail("active-slot descriptor lacks bookmark/broadcast state");
                if (GetInt(descriptor, "schema", 0) < 2) return SelfTestFail("active-slot descriptor schema did not advance for broadcast affinity");
                if (NormalizeSlotBroadcastPreset("visual FOCUS") != "Visual focus" || NormalizeSlotBroadcastPreset("nonsense") != "Keep current")
                    return SelfTestFail("slot broadcast preset normalization mismatch");
                var affinityConfig = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "director_mode", false },
                    { "director_outputs", new List<object> { new Dictionary<string, object> { { "id", 7 }, { "enabled", true }, { "modules", "history" }, { "layout", "Horizontal" }, { "custom", "preserve" } } } }
                };
                ApplyBroadcastPresetToConfig(affinityConfig, "Split sources");
                if (!GetBool(affinityConfig, "director_mode", false) || !String.Equals(GetString(affinityConfig, "overlay_preset", ""), "Split sources", StringComparison.OrdinalIgnoreCase))
                    return SelfTestFail("slot broadcast affinity did not activate Split sources");
                if (!String.Equals(GetString(DirectorOutput(affinityConfig, 1), "modules", ""), "artwork", StringComparison.OrdinalIgnoreCase) ||
                    !String.Equals(GetString(DirectorOutput(affinityConfig, 2), "modules", ""), "video", StringComparison.OrdinalIgnoreCase) ||
                    !String.Equals(GetString(DirectorOutput(affinityConfig, 3), "modules", ""), "title,channel", StringComparison.OrdinalIgnoreCase) ||
                    !String.Equals(GetString(DirectorOutput(affinityConfig, 4), "modules", ""), "visualizer", StringComparison.OrdinalIgnoreCase))
                    return SelfTestFail("slot broadcast affinity output map mismatch");
                Dictionary<string, object> preserved = DirectorOutput(affinityConfig, 7);
                if (!String.Equals(GetString(preserved, "custom", ""), "preserve", StringComparison.Ordinal)) return SelfTestFail("slot broadcast affinity discarded custom output fields");
                var normalized = new HashSet<string>(SlotSnapshotFiles.Select(x => x.Replace('/', '\\')), StringComparer.OrdinalIgnoreCase);
                foreach (string required in new[] { "playlist.txt", "pool-current.json", "state\\resume-track.txt", "state\\session.json", "state\\session-order.json", "state\\repeat-mode.txt", "state\\history.jsonl", "state\\controller-queue-checkpoints.json" })
                    if (!normalized.Contains(required)) return SelfTestFail("slot snapshot contract missing " + required);
                foreach (string forbidden in new[] { "config.json", "state\\controller-library.json", "state\\current.json", "state\\queue-runtime.json", "state\\listening-slot-switch.pending.json", "cache" })
                    if (normalized.Contains(forbidden)) return SelfTestFail("global/volatile state leaked into slot snapshot contract: " + forbidden);
                if (!SlotSwitchJournalPath.EndsWith(Path.Combine("state", "listening-slot-switch.pending.json"), StringComparison.OrdinalIgnoreCase))
                    return SelfTestFail("slot-switch journal path is outside global volatile state");
                string cacheKeyA = ComputeSourceKey("AbC_123-xy", "https://www.youtube.com/watch?v=AbC_123-xy");
                string cacheKeyB = ComputeSourceKey("AbC_123-xy", "https://youtu.be/AbC_123-xy");
                if (cacheKeyA.Length != 16 || !String.Equals(cacheKeyA, cacheKeyB, StringComparison.Ordinal))
                    return SelfTestFail("source-addressed cache key is not stable across equivalent YouTube URLs");
                if (FavoriteKey(new TrackMeta { YoutubeId = "AbC_123-xy", Url = "https://www.youtube.com/watch?v=AbC_123-xy", SourceKey = cacheKeyA }) != "yt:abc_123-xy")
                    return SelfTestFail("library identity changed with cache-key migration");
                Dictionary<string, object> ui = ReadJsonFresh(Path.Combine(_stateRoot, "controller-ui.json"));
                if (!ui.ContainsKey("slot_follow_broadcast_preset")) return SelfTestFail("slot broadcast follow preference is not persisted globally");
                if (!ui.ContainsKey("compact_controller_width") || !ui.ContainsKey("compact_controller_height")) return SelfTestFail("compact controller geometry memory is not persisted");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("session-slots exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

