                obsFixture.Diagnostics = true; obsFixture.ServerRevision = ObsExpectedRevision; obsFixture.ServerAuthority = ObsExpectedAuthority; obsFixture.GenerationMatches = true;
                if (_classicMenuBar != null && _miniMode && _classicMenuBar.Visibility != Visibility.Collapsed)
