                    return SelfTestFail("controller-ui.json missing R61.67 Settings place memory");
                if (!persisted.ContainsKey("normal_left") || !persisted.ContainsKey("normal_top") || !persisted.ContainsKey("window_maximized")) return SelfTestFail("controller-ui.json missing normal_left/normal_top/window_maximized");
                if (!persisted.ContainsKey("theme_intensity") || !persisted.ContainsKey("appearance_accent_enabled") || !persisted.ContainsKey("appearance_accent_preset") || !persisted.ContainsKey("theme_blend_strength")) return SelfTestFail("controller-ui.json missing R61.106.33 theme composition state");
                if (!persisted.ContainsKey("workspace_contexts")) return SelfTestFail("controller-ui.json missing R61.56 workspace_contexts");
                if (!persisted.ContainsKey("last_full_workspace")) return SelfTestFail("controller-ui.json missing R61.56 last_full_workspace");
                if (!persisted.ContainsKey("previous_full_workspace")) return SelfTestFail("controller-ui.json missing R61.57 previous_full_workspace");
                if (persisted.ContainsKey("media_balance") || persisted.ContainsKey("media_stage_layout")) return SelfTestFail("controller-ui.json still persists retired media presentation state");
                SaveUiState();
                byte[] stableStateA = File.ReadAllBytes(uiState);
                SaveUiState();
                byte[] stableStateB = File.ReadAllBytes(uiState);
                if (!stableStateA.SequenceEqual(stableStateB)) return SelfTestFail("semantic UI-state dedupe rewrote an unchanged snapshot");
                BeginUiStateTransaction();
                SaveUiState();
                if (!_uiStateSavePending || _uiStateTransactionDepth != 1) return SelfTestFail("UI-state transaction did not defer an internal save");
                EndUiStateTransaction(false);
                if (_uiStateSavePending || _uiStateTransactionDepth != 0) return SelfTestFail("UI-state transaction did not close cleanly without flush");
                return true;
            }
            catch (Exception ex) { return SelfTestFail("window-state-fidelity exception: " + ex.GetType().Name + ": " + ex.Message); }
        }

