            {
                { "buffer_health", "healthy" }, { "ready_ahead", 4 }, { "target_ahead", 4 },
                { "workers", 2 }, { "active_jobs", 1 }, { "queued_jobs", 0 },
                { "resource", new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "governor_mode", "normal" } } },
                { "performance", new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "samples", 12 }, { "anomalies", 0 } } }
            };
            string a = BuildSystemActivitySummary(healthy, EmptyMap(), true, true, false);
            if (a.IndexOf("ACTIVE.", StringComparison.Ordinal) < 0 || a.IndexOf("Audio playback is active", StringComparison.Ordinal) < 0 || a.IndexOf("prepared 4/4", StringComparison.Ordinal) < 0) return SelfTestFail("SelfTestSystemActivitySummary assertion 1");
            var conserve = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
            {
                { "buffer_health", "thin" }, { "ready_ahead", 1 }, { "target_ahead", 4 }, { "workers", 3 }, { "active_jobs", 0 }, { "queued_jobs", 2 },
                { "resource", new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "governor_mode", "conserve" } } },
                { "performance", new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase) { { "samples", 8 }, { "anomalies", 2 } } }
            };
            string b = BuildSystemActivitySummary(conserve, EmptyMap(), true, true, false);
            if (b.IndexOf("REDUCED.", StringComparison.Ordinal) < 0 ||
