        private static string MediaModeLabel(MediaMode mode)
        {
            if (mode == MediaMode.Both) return "Thumbnail + Video";
            if (mode == MediaMode.Off) return "Off";
            return mode.ToString();
        }

        private void LaunchViaYomiLauncher(string mode)
        {
            if (String.Equals(mode, "settings", StringComparison.OrdinalIgnoreCase))
            {
                OpenIntegratedSettings();
                return;
            }
            string launcher = Path.Combine(_appDir, "YomiLauncher.exe");
            if (!File.Exists(launcher))
                return;
            SafeStart(launcher, mode);
        }

        private void LaunchPowerShellScript(string fileName, bool hidden = true)
        {
            string script = Path.Combine(_appDir, fileName);
            if (!File.Exists(script))
                return;
            string powershell = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
            var psi = new ProcessStartInfo
            {
                FileName = powershell,
                Arguments = "-NoProfile -ExecutionPolicy Bypass -STA -File " + Quote(script),
                WorkingDirectory = _appDir,
                UseShellExecute = false,
                CreateNoWindow = true,
                WindowStyle = ProcessWindowStyle.Hidden
            };
            try
            {
                Process child = Process.Start(psi);
                if (child == null)
                {
                    ShowToast("Launch failed", fileName + " did not start.");
                    return;
                }

                // Launcher actions must never make the WPF thread wait for a child process, even
                // for the old 500 ms "quick failure" check. Observe completion asynchronously.
                ThreadPool.QueueUserWorkItem(delegate(object ignored)
                {
                    int exitCode = 0;
                    bool failed = false;
                    try
                    {
                        child.WaitForExit();
                        exitCode = child.ExitCode;
                        failed = exitCode != 0;
                    }
                    catch { }
                    finally { try { child.Dispose(); } catch { } }
                    if (!failed) return;
                    try
                    {
                        TryBeginInvokeUi(DispatcherPriority.Background, delegate
                        {
                            ShowToast("Launch failed", fileName + " exited with code " + exitCode.ToString(CultureInfo.InvariantCulture) + ".");
                        });
                    }
                    catch { }
                });
            }
            catch (Exception ex) { ShowToast("Launch failed", fileName + ": " + ex.Message); }
        }

        private static string TryGetClipboardText()
        {
            try { return Clipboard.ContainsText() ? Clipboard.GetText() : ""; }
            catch { return ""; }
        }

        private void ShowNativeReportWindow(string title, string text)
        {
            double workWidth = Math.Max(640.0, SystemParameters.WorkArea.Width - 80.0);
            double workHeight = Math.Max(460.0, SystemParameters.WorkArea.Height - 80.0);
            var reportWindow = new Window
            {
                Owner = _window,
                Title = "YOMI - " + title,
                Width = Math.Min(920.0, workWidth),
                Height = Math.Min(680.0, workHeight),
                MinWidth = Math.Min(560.0, workWidth),
                MinHeight = Math.Min(400.0, workHeight),
                WindowStartupLocation = WindowStartupLocation.CenterOwner,
                ResizeMode = ResizeMode.CanResize,
                ShowInTaskbar = false,
                Background = Brush("AppBg"),
                Foreground = Brush("TextPrimary")
            };

            var root = new Grid { Margin = new Thickness(16) };
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
            root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });

            var heading = new TextBlock
            {
                Text = title,
                FontSize = 18,
                FontWeight = FontWeights.SemiBold,
                Foreground = Brush("TextPrimary"),
                Margin = new Thickness(0, 0, 0, 10)
            };

            var body = new TextBox
            {
                Text = text ?? "",
                IsReadOnly = true,
                AcceptsReturn = true,
                AcceptsTab = true,
                TextWrapping = TextWrapping.NoWrap,
                HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
                VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
                FontFamily = new FontFamily("Consolas"),
                FontSize = 13.5,
                Background = Brush("SurfaceRaised"),
                Foreground = Brush("TextPrimary"),
                BorderBrush = Brush("Border"),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(12)
            };

            var buttons = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                HorizontalAlignment = HorizontalAlignment.Right,
                Margin = new Thickness(0, 12, 0, 0)
            };
            var copy = new Button { Content = "Copy all", MinWidth = 90, Height = 32, Margin = new Thickness(0, 0, 8, 0), Background = Brush("SurfaceRaised"), Foreground = Brush("TextPrimary"), BorderBrush = Brush("BorderStrong"), BorderThickness = new Thickness(1), Padding = new Thickness(10, 0, 10, 0) };
            var close = new Button { Content = "Close", MinWidth = 80, Height = 32, Background = Brush("SurfaceRaised"), Foreground = Brush("TextPrimary"), BorderBrush = Brush("BorderStrong"), BorderThickness = new Thickness(1), Padding = new Thickness(10, 0, 10, 0) };
            copy.Click += delegate
            {
                try
                {
                    Clipboard.SetText(body.Text ?? "");
                    ShowToast(title, "Report copied.");
                }
                catch { ShowToast(title, "Could not copy the report."); }
            };
            close.Click += delegate { reportWindow.Close(); };
            buttons.Children.Add(copy);
            buttons.Children.Add(close);

            Grid.SetRow(heading, 0);
            Grid.SetRow(body, 1);
            Grid.SetRow(buttons, 2);
            root.Children.Add(heading);
            root.Children.Add(body);
            root.Children.Add(buttons);
            reportWindow.Content = root;
            reportWindow.Show();
            reportWindow.Activate();
            body.Focus();
        }

        private void RunReportInYomi(string title, string scriptName, string scriptArguments, string startMessage)
        {
            string script = Path.Combine(_appDir, scriptName);
            if (!File.Exists(script))
            {
                ShowToast(title, scriptName + " is not installed.");
                return;
            }

            string powershell = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
            string clipboardBefore = TryGetClipboardText();
            ShowToast(title, startMessage);

            ThreadPool.QueueUserWorkItem(delegate
            {
                var stdout = new StringBuilder();
                var stderr = new StringBuilder();
                object stdoutLock = new object();
                object stderrLock = new object();
                int exitCode = -1;
                string failure = "";

                try
                {
                    var psi = new ProcessStartInfo
                    {
                        FileName = powershell,
                        Arguments = "-NoProfile -ExecutionPolicy Bypass -STA -File " + Quote(script) + (String.IsNullOrWhiteSpace(scriptArguments) ? "" : " " + scriptArguments),
                        WorkingDirectory = _appDir,
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        WindowStyle = ProcessWindowStyle.Hidden,
                        RedirectStandardOutput = true,
                        RedirectStandardError = true
                    };

                    using (var process = new Process { StartInfo = psi })
                    {
                        process.OutputDataReceived += delegate(object sender, DataReceivedEventArgs e)
                        {
                            if (e.Data == null) return;
                            lock (stdoutLock) stdout.AppendLine(e.Data);
                        };
                        process.ErrorDataReceived += delegate(object sender, DataReceivedEventArgs e)
                        {
                            if (e.Data == null) return;
                            lock (stderrLock) stderr.AppendLine(e.Data);
                        };
                        if (!process.Start()) throw new InvalidOperationException("The report process could not be started.");
                        process.BeginOutputReadLine();
                        process.BeginErrorReadLine();
                        process.WaitForExit();
                        exitCode = process.ExitCode;
                    }
                }
                catch (Exception ex) { failure = ex.Message; }

                string outText;
                string errText;
                lock (stdoutLock) outText = stdout.ToString().Trim();
                lock (stderrLock) errText = stderr.ToString().Trim();
                int finalExitCode = exitCode;
                string finalFailure = failure;

                TryBeginInvokeUi(DispatcherPriority.Background, delegate
                {
                    string clipboardAfter = TryGetClipboardText();
                    string report = "";
                    if (!String.IsNullOrWhiteSpace(clipboardAfter) && !String.Equals(clipboardAfter, clipboardBefore, StringComparison.Ordinal))
                        report = clipboardAfter.Trim();
                    else if (!String.IsNullOrWhiteSpace(outText))
                        report = outText;

                    if (!String.IsNullOrWhiteSpace(errText))
                        report = (String.IsNullOrWhiteSpace(report) ? "" : report + "\r\n\r\n") + "ERROR OUTPUT\r\n" + errText;
                    if (!String.IsNullOrWhiteSpace(finalFailure))
                        report = (String.IsNullOrWhiteSpace(report) ? "" : report + "\r\n\r\n") + "Could not run the report: " + finalFailure;
                    if (String.IsNullOrWhiteSpace(report))
                        report = finalExitCode == 0 ? "Completed. The tool returned no report text." : "The report finished without readable output.";
                    if (finalExitCode > 0)
                        report = "Exit code " + finalExitCode.ToString(CultureInfo.InvariantCulture) + "\r\n\r\n" + report;

                    ShowNativeReportWindow(title, report);
                    ShowToast(title, finalExitCode == 0 && String.IsNullOrWhiteSpace(finalFailure) ? "Report ready." : "Report finished with errors.");
                });
            });
        }

        private void CreateDiagnosticBundle()
        {
            if (_diagnosticBundleWorkerActive)
            {
                ShowToast("Diagnostics", "A diagnostic bundle is already being created.");
                return;
            }
            string script = Path.Combine(_appDir, "YomiDiagnosticBundle.ps1");
            if (!File.Exists(script))
            {
                ShowToast("Diagnostics unavailable", "YOMI diagnostic bundle script is missing from the installation.");
                return;
            }
            _diagnosticBundleWorkerActive = true;
            AddActivity("Diagnostics", "collecting support bundle");
            ShowToast("Diagnostics", "Collecting logs, runtime truth, OBS state and current media evidence...");
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                int exitCode = -1;
                string failure = "";
                try
                {
                    string powershell = Path.Combine(Environment.SystemDirectory, @"WindowsPowerShell\v1.0\powershell.exe");
                    if (!File.Exists(powershell)) powershell = "powershell.exe";
                    var psi = new ProcessStartInfo
                    {
                        FileName = powershell,
                        Arguments = "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File " + Quote(script),
                        WorkingDirectory = _appDir,
                        UseShellExecute = false,
                        CreateNoWindow = true,
                        WindowStyle = ProcessWindowStyle.Hidden
                    };
                    using (Process proc = Process.Start(psi))
                    {
                        if (proc == null) throw new InvalidOperationException("PowerShell did not start.");
                        if (!proc.WaitForExit(180000))
                        {
                            try { proc.Kill(); } catch { }
                            throw new TimeoutException("Diagnostic collection exceeded the 3-minute safety ceiling.");
                        }
                        exitCode = proc.ExitCode;
                    }
                }
                catch (Exception ex) { failure = ex.Message; }
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        _diagnosticBundleWorkerActive = false;
                        if (exitCode == 0 && String.IsNullOrWhiteSpace(failure))
                        {
                            AddActivity("Diagnostics", "support bundle ready on Desktop");
                            ShowToast("Diagnostic bundle ready", "Explorer opened the ZIP and its path was copied to the clipboard.");
                        }
                        else
                        {
                            AddActivity("Diagnostics", "bundle failed | " + (String.IsNullOrWhiteSpace(failure) ? "exit " + exitCode.ToString(CultureInfo.InvariantCulture) : failure));
                            ShowToast("Diagnostic bundle failed", "YOMI preserved the collected folder and failure details on the Desktop.");
                        }
                    });
                }
                catch { _diagnosticBundleWorkerActive = false; }
            });
        }

