        private string ObsCacheKey(Dictionary<string, object> config)
        {
            string version = GetString(config, "version", "4.2.0.9.9.1");
            string digits = new string(version.Where(Char.IsDigit).ToArray());
            return String.IsNullOrWhiteSpace(digits) ? "4208" : digits;
        }

        private string ObsBaseUrl(Dictionary<string, object> config)
        {
            int port = Math.Max(1, GetInt(config, "server_port", 8876));
            return "http://127.0.0.1:" + port.ToString(CultureInfo.InvariantCulture);
        }

        private string ObsClassicDefaultUrl(Dictionary<string, object> config)
        {
            // Public 4.2.0.7 advertised the server root itself. Keep that literal, stable URL as
            // the default rather than inventing a version query or requiring a newer alias.
            return ObsBaseUrl(config) + "/";
        }

        private string ObsSourceUrl(Dictionary<string, object> config, int outputId)
        {
            if (outputId <= 0) return ObsLegacyOverlayUrl(config);
            return ObsBaseUrl(config) + "/source/" + outputId.ToString(CultureInfo.InvariantCulture) + "?v=" + ObsCacheKey(config);
        }

        private string ObsLegacyOverlayUrl(Dictionary<string, object> config)
        {
            int port = Math.Max(1, GetInt(config, "server_port", 8876));
            if (_obsResolvedClassicPort == port && !String.IsNullOrWhiteSpace(_obsResolvedClassicUrl)) return _obsResolvedClassicUrl;
            return ObsClassicDefaultUrl(config);
        }

        private int GetObsResolvedFps(Dictionary<string, object> config)
        {
            string fpsMode = GetString(config, "browser_fps_mode", "Auto");
            if (fpsMode.StartsWith("60", StringComparison.OrdinalIgnoreCase)) return 60;
            if (fpsMode.StartsWith("30", StringComparison.OrdinalIgnoreCase)) return 30;
            if (fpsMode.StartsWith("15", StringComparison.OrdinalIgnoreCase)) return 15;

            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            if (!streamer) return 15;

            bool videoOn = GetBool(config, "video_enabled", true);
            bool vizOn = GetBool(config, "visualizer_enabled", true);
            if (GetBool(config, "director_mode", false))
            {
                foreach (object raw in GetList(config, "director_outputs"))
                {
                    Dictionary<string, object> output = AsMap(raw);
                    if (!GetBool(output, "enabled", false)) continue;
                    string modules = GetString(output, "modules", "").ToLowerInvariant();
                    foreach (string token in modules.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        string module = token.Trim();
                        if (module == "video") videoOn = true;
                        if (module == "visualizer") vizOn = true;
                    }
                }
            }

            // Main video is source-paced. Auto Browser Source FPS therefore leaves enough
            // headroom for a 60-FPS source instead of silently capping it at 30. Generated
            // visualizer media remains explicit CFR 30/60.
            if (videoOn) return 60;
            bool sixty = vizOn && GetString(config, "visualizer_fps", "30 FPS").StartsWith("60", StringComparison.OrdinalIgnoreCase);
            return sixty ? 60 : (vizOn ? 30 : 15);
        }

        private Tuple<int,int,int> GetClassicObsGeometry(Dictionary<string, object> config)
        {
            int cw = Math.Max(320, GetInt(config, "canvas_width", 2560));
            int mh = Math.Max(20, GetInt(config, "media_height", 90));
            int textSize = Math.Max(8, GetInt(config, "text_size", DefaultOverlayTextSize));
            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            bool artOn = streamer && GetBool(config, "artwork_enabled", true);
            bool vidOn = streamer && GetBool(config, "video_enabled", true);
            bool vizOn = streamer && GetBool(config, "visualizer_enabled", true);
            int lines = 0;
            if (streamer && GetBool(config, "title_enabled", true)) lines++;
            if (streamer && GetBool(config, "channel_enabled", true)) lines++;

            int outline = Math.Max(0, GetInt(config, "text_outline", DefaultOverlayTextOutline));
            int safeY = (int)Math.Ceiling(outline / 2.0) + 2;
            int textHeight = lines > 0 ? (lines * textSize) + ((lines + 1) * safeY) : 1;
            int visualHeight = (artOn || vidOn || vizOn) ? mh : 1;
            int requiredHeight = Math.Max(24, Math.Max(visualHeight, textHeight));
            string canvasMode = GetString(config, "canvas_height_mode", "Auto");
            int requestedHeight = Math.Max(24, GetInt(config, "canvas_height", requiredHeight));
            int overlayHeight = String.Equals(canvasMode, "Manual", StringComparison.OrdinalIgnoreCase) ? Math.Max(requiredHeight, requestedHeight) : requiredHeight;

            return Tuple.Create(cw, overlayHeight, GetObsResolvedFps(config));
        }

        private Tuple<int,int,string> GetDirectorOutputGeometry(Dictionary<string, object> config, int outputId)
        {
            foreach (object raw in GetList(config, "director_outputs"))
            {
                var output = AsMap(raw);
                if (GetInt(output, "id", 0) != outputId) continue;
                return Tuple.Create(Math.Max(1, GetInt(output, "width", 2560)), Math.Max(1, GetInt(output, "height", 90)), GetString(output, "name", "Output " + outputId.ToString(CultureInfo.InvariantCulture)));
            }
            return Tuple.Create(2560, 90, "Output " + outputId.ToString(CultureInfo.InvariantCulture));
        }

