            config["video_enabled"] = Checked(_settingsVideo);
            config["title_enabled"] = Checked(_settingsTitle);
            config["channel_enabled"] = Checked(_settingsChannel);
            config["visualizer_enabled"] = Checked(_settingsVisualizerEnabled);
            config["canvas_width"] = ComboInt(_settingsCanvasWidth, 2560);
            string draftCanvasHeight = ComboText(_settingsCanvasHeight, "Auto");
            config["canvas_height_mode"] = String.Equals(draftCanvasHeight, "Auto", StringComparison.OrdinalIgnoreCase) ? "Auto" : "Manual";
            config["canvas_height"] = String.Equals(draftCanvasHeight, "Auto", StringComparison.OrdinalIgnoreCase) ? ComboInt(_settingsMediaHeight, 90) : ComboInt(_settingsCanvasHeight, 90);
            config["media_width"] = ComboInt(_settingsMediaWidth, 160);
            config["media_height"] = ComboInt(_settingsMediaHeight, 90);
            config["smart_artwork_crop"] = Checked(_settingsSmartArtworkCrop);
            config["overlay_safe_margin_px"] = ComboInt(_settingsSafeMargin, 8);
            config["overlay_text_gap_px"] = ComboInt(_settingsTextGap, 14);
            config["overlay_auto_fit_text"] = Checked(_settingsAutoFitText);
            config["overlay_min_text_size"] = ComboInt(_settingsMinTextSize, 18);
            config["text_size"] = ComboInt(_settingsTextSize, DefaultOverlayTextSize);
            config["text_font"] = ComboText(_settingsTextFont, DefaultOverlayTextFont); config["text_color"] = NamedColorValueFromCombo(_settingsTextColor, DefaultOverlayTextColor); config["text_outline"] = ComboInt(_settingsTextOutline, DefaultOverlayTextOutline); config["outline_color"] = NamedColorValueFromCombo(_settingsOutlineColor, DefaultOverlayOutlineColor); config["text_opacity"] = ComboDouble(_settingsTextOpacity, DefaultOverlayTextOpacity); config["text_alignment"] = ComboText(_settingsTextAlignment, DefaultOverlayTextAlignment); config["title_channel_spacing"] = "Normal"; config["text_glow"] = Checked(_settingsTextGlow); config["media_border_enabled"] = Checked(_settingsMediaBorderEnabled); config["media_border_px"] = ComboInt(_settingsMediaBorderPx, 2); config["media_border_color"] = NamedColorValueFromCombo(_settingsMediaBorderColor, "#252525"); config["media_corner_style"] = ComboText(_settingsMediaCornerStyle, "Square");
            config["visualizer_match_text_overhang"] = Checked(_settingsVisualizerMatchText);
            config["visualizer_adaptive_fill"] = ComboText(_settingsVisualizerFill, "Adaptive"); config["visualizer_activity"] = ComboText(_settingsVisualizerActivity, "Active"); config["visualizer_opacity"] = ComboDouble(_settingsVisualizerOpacity, 0.3); config["visualizer_color_mode"] = ComboText(_settingsVisualizerColorMode, "Solid"); config["visualizer_solid_color"] = VisualizerColorFromCombo(_settingsVisualizerSolidColor); config["visualizer_gradient_preset"] = ComboText(_settingsVisualizerGradientPreset, "Sunset"); config["visualizer_gradient_orientation"] = ComboText(_settingsVisualizerGradientOrientation, "Horizontal"); config["visualizer_frequency_scale"] = ComboText(_settingsVisualizerFrequencyScale, "Logarithmic"); config["visualizer_high_frequency_trim"] = ComboInt(_settingsVisualizerTrim, 0); config["visualizer_high_frequency_lift_db"] = ComboInt(_settingsVisualizerLift, 4); config["visualizer_shape"] = ComboText(_settingsVisualizerShape, "Spectrum"); config["visualizer_bar_spacing"] = ComboText(_settingsVisualizerSpacing, "None"); config["visualizer_length_multiplier"] = ComboDouble(_settingsVisualizerLength, 4.0); config["visualizer_direction"] = ComboText(_settingsVisualizerDirection, "Normal"); config["visualizer_vertical_anchor"] = ComboText(_settingsVisualizerAnchor, "Source"); config["visualizer_layer"] = ComboText(_settingsVisualizerLayer, "Behind text");
            int previewVizW, previewVizH; VisualizerPixelSizeDimensions(ComboText(_settingsVisualizerPixelSize, "Chunky"), out previewVizW, out previewVizH); config["visualizer_internal_width"] = previewVizW; config["visualizer_internal_height"] = previewVizH;
            config["video_fps"] = ComboText(_settingsVideoFps, "Source FPS");
            config["visualizer_fps"] = ComboText(_settingsVisualizerFps, "30 FPS");
            config["browser_fps_mode"] = ComboText(_settingsBrowserFps, "Auto");
            config["director_mode"] = Checked(_settingsDirectorMode);
            config["director_outputs"] = BuildDirectorOutputs(config);
            return config;
        }

        private static string ObsModuleLabel(string modules)
        {
            if (String.IsNullOrWhiteSpace(modules)) return "empty";
            return modules.Replace(",", " + ").Replace("artwork", "thumbnail").Replace("visualizer", "visualizer");
        }

        private static string ObsSourceName(int outputId, string outputName)
        {
            if (outputId <= 0) return "YOMI | Now Playing";
            string clean = String.IsNullOrWhiteSpace(outputName) ? "Output " + outputId.ToString(CultureInfo.InvariantCulture) : outputName.Trim();
            if (clean.StartsWith("YOMI", StringComparison.OrdinalIgnoreCase)) return clean;
            return "YOMI | O" + outputId.ToString(CultureInfo.InvariantCulture) + " | " + clean;
        }

        private int ObsPrimaryOutputId(Dictionary<string, object> config)
        {
            if (!GetBool(config, "director_mode", false)) return 0;
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                int id = GetInt(output, "id", 0);
                if (id > 0 && GetBool(output, "enabled", false)) return id;
            }
            return -1;
        }

        private string ObsPrimarySourceName(Dictionary<string, object> config)
        {
            int primaryId = ObsPrimaryOutputId(config);
            if (primaryId == 0) return ObsSourceName(0, "Now Playing");
            if (primaryId < 0) return "No active Browser Source";
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                if (GetInt(output, "id", 0) == primaryId)
                    return ObsSourceName(primaryId, GetString(output, "name", "Output " + primaryId.ToString(CultureInfo.InvariantCulture)));
            }
            return ObsSourceName(primaryId, "Output " + primaryId.ToString(CultureInfo.InvariantCulture));
        }

        private string ObsLayoutDiagram(Dictionary<string, object> config)
        {
            int fps = GetObsResolvedFps(config);
            if (!GetBool(config, "director_mode", false))
            {
                var cells = new List<string>();
                if (GetBool(config, "artwork_enabled", true)) cells.Add("[ ARTWORK ]");
                if (GetBool(config, "video_enabled", true)) cells.Add("[ VIDEO ]");
                if (GetBool(config, "title_enabled", true) || GetBool(config, "channel_enabled", true)) cells.Add("[ TITLE / CHANNEL ]");
                if (GetBool(config, "visualizer_enabled", true)) cells.Add("[ VISUALIZER ]");
                return cells.Count == 0 ? "[ EMPTY ]" : String.Join(" ", cells);
            }
            var lines = new List<string>();
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                int id = GetInt(output, "id", 0);
                if (id <= 0 || !GetBool(output, "enabled", false)) continue;
                string modules = GetString(output, "modules", "");
                var cells = new List<string>();
                foreach (string token in modules.Split(new[] { ',' }, StringSplitOptions.RemoveEmptyEntries))
                {
                    string m = token.Trim().ToUpperInvariant();
                    if (m == "ARTWORK") m = "ARTWORK";
                    if (m == "VISUALIZER") m = "VISUALIZER";
                    cells.Add("[ " + m + " ]");
                }
                int width = Math.Max(1, GetInt(output, "width", 2560));
                int height = Math.Max(1, GetInt(output, "height", 90));
                lines.Add("Output " + id.ToString(CultureInfo.InvariantCulture) + "  " + width.ToString(CultureInfo.InvariantCulture) + "x" + height.ToString(CultureInfo.InvariantCulture) + " @" + fps.ToString(CultureInfo.InvariantCulture) + "  " + (cells.Count == 0 ? "[ EMPTY ]" : String.Join(" ", cells)));
            }
            return lines.Count == 0 ? "NO ACTIVE OUTPUTS" : String.Join("\r\n", lines);
        }

        private string BuildObsPrimarySetupBlock(Dictionary<string, object> config)
        {
            int primaryId = ObsPrimaryOutputId(config);
            if (primaryId < 0) return "No active Browser Source\r\nEnable an output below, then save Settings.";

            int width, height;
            string name;
            if (primaryId == 0)
            {
                var g = GetClassicObsGeometry(config);
                width = g.Item1;
                height = g.Item2;
                name = ObsSourceName(0, "Now Playing");
            }
            else
            {
                var g = GetDirectorOutputGeometry(config, primaryId);
                width = g.Item1;
                height = g.Item2;
                name = ObsSourceName(primaryId, g.Item3);
            }

            int fps = GetObsResolvedFps(config);
            var lines = new List<string>();
            lines.Add("NAME:   " + name);
            lines.Add("URL:    " + ObsSourceUrl(config, primaryId));
            lines.Add("WIDTH:  " + width.ToString(CultureInfo.InvariantCulture));
            lines.Add("HEIGHT: " + height.ToString(CultureInfo.InvariantCulture));
            lines.Add("BROWSER FPS: " + fps.ToString(CultureInfo.InvariantCulture));
            return String.Join("\r\n", lines);
        }

        private string BuildObsSetupBlock(Dictionary<string, object> config)
        {
            if (!GetBool(config, "director_mode", false)) return BuildObsPrimarySetupBlock(config);

            var lines = new List<string>();
            int count = 0;
            int fps = GetObsResolvedFps(config);
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                int id = GetInt(output, "id", 0);
                if (id <= 0 || !GetBool(output, "enabled", false)) continue;
                count++;
                if (lines.Count > 0) lines.Add("");
                string name = GetString(output, "name", "Output " + id.ToString(CultureInfo.InvariantCulture));
                string modules = GetString(output, "modules", "");
                int width = Math.Max(1, GetInt(output, "width", 2560));
                int height = Math.Max(1, GetInt(output, "height", 90));
                lines.Add("OUTPUT " + id.ToString(CultureInfo.InvariantCulture) + " | " + name);
                lines.Add("NAME:    " + ObsSourceName(id, name));
                lines.Add("URL:     " + ObsSourceUrl(config, id));
                lines.Add("WIDTH:   " + width.ToString(CultureInfo.InvariantCulture));
                lines.Add("HEIGHT:  " + height.ToString(CultureInfo.InvariantCulture));
                lines.Add("BROWSER FPS: " + fps.ToString(CultureInfo.InvariantCulture));
                lines.Add("MODULES: " + ObsModuleLabel(modules).ToUpperInvariant());
            }
            if (count == 0)
            {
                lines.Add("MULTI-OUTPUT IS ON, BUT NO OUTPUTS ARE ENABLED");
                lines.Add("Enable at least one output below, then Save settings.");
            }
            return String.Join("\r\n", lines);
        }

        private string ObsPrimaryUrl(Dictionary<string, object> config)
        {
            int primaryId = ObsPrimaryOutputId(config);
            return primaryId < 0 ? "" : ObsSourceUrl(config, primaryId);
        }

        private string ObsPrimaryPreviewUrl(Dictionary<string, object> config)
        {
            int primaryId = ObsPrimaryOutputId(config);
            if (primaryId < 0) return "";
            return ObsBaseUrl(config) + "/preview?source=" + primaryId.ToString(CultureInfo.InvariantCulture);
        }

        private string ObsPreviewSummary(Dictionary<string, object> config)
        {
            if (!GetBool(config, "director_mode", false))
            {
                var parts = new List<string>();
                if (GetBool(config, "artwork_enabled", true)) parts.Add("THUMBNAIL");
                if (GetBool(config, "video_enabled", true)) parts.Add("VIDEO");
                if (GetBool(config, "title_enabled", true) || GetBool(config, "channel_enabled", true)) parts.Add("TITLE / CHANNEL");
                if (GetBool(config, "visualizer_enabled", true)) parts.Add("VIZ");
                return parts.Count == 0 ? "EMPTY CLASSIC STRIP" : String.Join("  |  ", parts);
            }
            var outputs = new List<string>();
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                int id = GetInt(output, "id", 0);
                if (id > 0 && GetBool(output, "enabled", false)) outputs.Add("O" + id.ToString(CultureInfo.InvariantCulture) + " " + ObsModuleLabel(GetString(output, "modules", "")).ToUpperInvariant());
            }
            return outputs.Count == 0 ? "NO ACTIVE OUTPUTS" : String.Join("   |   ", outputs);
        }

        private bool ObsSetupNeedsAttention(Dictionary<string, object> config)
        {
            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            if (!streamer) return true;
            if (!GetBool(config, "director_mode", false))
            {
                return !(GetBool(config, "artwork_enabled", true) || GetBool(config, "video_enabled", true) || GetBool(config, "title_enabled", true) || GetBool(config, "channel_enabled", true) || GetBool(config, "visualizer_enabled", true));
            }
            int active = 0;
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                if (!GetBool(output, "enabled", false)) continue;
                active++;
                if (String.IsNullOrWhiteSpace(GetString(output, "modules", ""))) return true;
            }
            return active == 0;
        }

        private string ObsReadinessText(Dictionary<string, object> config)
        {
            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            if (!streamer) return "Broadcast output is off · choose Streamer / OBS";
            if (!GetBool(config, "director_mode", false))
            {
                bool any = GetBool(config, "artwork_enabled", true) || GetBool(config, "video_enabled", true) || GetBool(config, "title_enabled", true) || GetBool(config, "channel_enabled", true) || GetBool(config, "visualizer_enabled", true);
                return any ? "Ready for OBS" : "CLASSIC STRIP IS EMPTY";
            }
            int active = 0, empty = 0;
            foreach (object raw in GetList(config, "director_outputs"))
            {
                Dictionary<string, object> output = AsMap(raw);
                if (!GetBool(output, "enabled", false)) continue;
                active++;
                if (String.IsNullOrWhiteSpace(GetString(output, "modules", ""))) empty++;
            }
            if (active == 0) return "NO ACTIVE OUTPUTS";
            if (empty > 0) return empty.ToString(CultureInfo.InvariantCulture) + " ENABLED OUTPUT" + (empty == 1 ? "" : "S") + " HAVE NO MODULES";
            return "Ready: " + active.ToString(CultureInfo.InvariantCulture) + " SOURCE" + (active == 1 ? "" : "S") + " TO OBS";
        }

        private void RefreshObsQuickSetup()
        {
            if (_settingsObsClassicUrl == null) return;
            var config = GetObsQuickSetupConfig();
            bool director = GetBool(config, "director_mode", false);
            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            int primaryId = ObsPrimaryOutputId(config);
            int fps = GetObsResolvedFps(config);
            var classicGeometry = GetClassicObsGeometry(config);
            _settingsObsClassicUrl.Text = ObsLegacyOverlayUrl(config);
            if (_settingsObsPrimaryName != null) _settingsObsPrimaryName.Text = ObsPrimarySourceName(config);

            // Fast setup is deliberately the legacy-compatible one-source overlay. Director output
            // geometry belongs under Advanced and must never silently replace the default URL.
            int width = classicGeometry.Item1;
            int height = classicGeometry.Item2;
            if (_settingsObsClassicSizeText != null)
            {
                _settingsObsClassicSizeText.Text = primaryId < 0
                    ? "Enable an output below to create a Browser Source"
                    : width.ToString(CultureInfo.InvariantCulture) + " × " + height.ToString(CultureInfo.InvariantCulture) + " · " + fps.ToString(CultureInfo.InvariantCulture) + " FPS";
            }

            if (_settingsObsSetupBlock != null) _settingsObsSetupBlock.Text = BuildObsSetupBlock(config);
            if (_settingsObsActiveSetPanel != null) _settingsObsActiveSetPanel.Visibility = director ? Visibility.Visible : Visibility.Collapsed;
            bool primaryAvailable = streamer && primaryId >= 0;
            if (_settingsObsCopyPrimaryButton != null) _settingsObsCopyPrimaryButton.IsEnabled = streamer;
            if (_settingsObsCopyNameButton != null) _settingsObsCopyNameButton.IsEnabled = primaryAvailable;
            if (_settingsObsCopyClassicButton != null) _settingsObsCopyClassicButton.IsEnabled = primaryAvailable;
            if (_settingsObsOpenClassicButton != null) _settingsObsOpenClassicButton.IsEnabled = primaryAvailable;
            if (_settingsObsCopySetupButton != null) _settingsObsCopySetupButton.IsEnabled = streamer && (!director || primaryId >= 0);

            int active = director ? 0 : 1;
            if (director)
            {
                foreach (object raw in GetList(config, "director_outputs")) if (GetBool(AsMap(raw), "enabled", false)) active++;
            }
            if (_settingsObsSetupModeText != null)
                _settingsObsSetupModeText.Text = (director ? active.ToString(CultureInfo.InvariantCulture) + " Browser Source" + (active == 1 ? "" : "s") : "One Browser Source") + (_settingsDirty ? " · unsaved" : " · saved");

            if (_settingsObsReadinessText != null)
            {
                _settingsObsReadinessText.Text = ObsReadinessText(config);
                Brush statusBrush = _window.TryFindResource(ObsSetupNeedsAttention(config) ? "Warning" : "TextSecondary") as Brush;
                if (statusBrush != null) _settingsObsReadinessText.Foreground = statusBrush;
            }
            if (_settingsObsPreviewText != null) _settingsObsPreviewText.Text = ObsPreviewSummary(config);
            if (_settingsObsDiagramText != null) _settingsObsDiagramText.Text = ObsLayoutDiagram(config);
            RefreshObsCompatibilityHealth(config);
        }

