        private void OpenObsPrimarySourceInBrowser()
        {
            var config = GetObsQuickSetupConfig();
            if (!String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase)) { ShowToast("OBS", "OBS integration is off. Turn OBS Integration + Media Prep on first."); return; }
            if (ObsPrimaryOutputId(config) < 0) { ShowToast("OBS", "Enable at least one Browser Source output first."); return; }
            int port = Math.Max(1, GetInt(config, "server_port", 8876));
            string previewUrl = ObsPrimaryPreviewUrl(config);
            ShowToast("OBS preview", "Checking the local Browser Source...");
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                ObsProbeResult probe = null;
                bool healthy = false;
                bool repairRequested = false;
                try
                {
                    probe = ProbeObsOutputForCurrentRuntime(port);
                    healthy = probe != null && probe.Service && !String.IsNullOrWhiteSpace(probe.RouteUrl) && probe.State && probe.Config;
                    if (!healthy)
                    {
                        repairRequested = RequestObsServerRepair(port, "Preview Source requested while local Browser Source was unavailable");
                        if (repairRequested)
                        {
                            Thread.Sleep(1900);
                            probe = ProbeObsOutputForCurrentRuntime(port);
                            healthy = probe != null && probe.Service && !String.IsNullOrWhiteSpace(probe.RouteUrl) && probe.State && probe.Config;
                        }
                    }
                }
                catch { }
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                        if (healthy)
                        {
                            ApplyResolvedObsRoute(port, probe, config);
                            SafeStart(previewUrl, "");
                            ShowToast("OBS preview", "Browser Source preview opened.");
                        }
                        else
                        {
                            ShowToast("OBS preview", repairRequested ? "The local OBS output is still unavailable; YOMI did not open a broken page." : "The local OBS output is unavailable; YOMI did not open a broken page.");
                        }
                    });
                }
                catch { }
            });
        }

