        private sealed class ObsProbeResult
        {
            public bool Service;
            public bool State;
            public bool Config;
            public bool Diagnostics;
            public string ServerRevision = "";
            public string ServerAuthority = "";
            public string ServerRuntimeId = "";
            public int ServerSupervisorPid;
            public int ServerPid;
            public string ExpectedRuntimeId = "";
            public int ExpectedSupervisorPid;
            public bool GenerationMatches;
            public bool TrackProjected;
            public bool Root;
            public bool Overlay;
            public bool OverlayHtml;
            public int RootBytes;
            public int OverlayBytes;
            public int OverlayHtmlBytes;
            public int MediaRoutesChecked;
            public int MediaRoutesPassed;
            public bool MediaRoutesOk = true;
            public string MediaFailure = "";
            public int BrowserClientCount;
            public long FreshestBrowserClientAgeMs = -1;
            public string FreshestBrowserClientKind = "";
            public string FreshestBrowserClientRoute = "";
            public double PresentedVideoFps = -1;
            public double PresentedVisualizerFps = -1;
            public long PresentationAgeMs = -1;
            public string PresentationRoute = "";
            public string RouteUrl = "";
            public string RouteLabel = "";
            public string StateRoute = "";
        }

        private static bool ProbeLocalUrl(string url, int timeoutMs, bool requireHtml, out int bytes, out string sample)
        {
            bytes = 0; sample = "";
            try
            {
                var request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "GET"; request.Timeout = timeoutMs; request.ReadWriteTimeout = timeoutMs; request.Proxy = null;
                request.UserAgent = "YOMI-Controller-Probe/" + ObsExpectedRevision;
                request.CachePolicy = new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);
                using (var response = (HttpWebResponse)request.GetResponse())
                using (var stream = response.GetResponseStream())
                {
                    if (response.StatusCode != HttpStatusCode.OK) return false;
                    if (stream == null) return !requireHtml;
                    byte[] buffer = new byte[16384]; int read = stream.Read(buffer, 0, buffer.Length); bytes = Math.Max(0, read);
                    if (read > 0) sample = Encoding.UTF8.GetString(buffer, 0, read);
                    if (!requireHtml) return true;
                    if (bytes < 64) return false;
                    string type = response.ContentType ?? "";
                    return type.IndexOf("html", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           sample.IndexOf("<!doctype", StringComparison.OrdinalIgnoreCase) >= 0 ||
                           sample.IndexOf("<html", StringComparison.OrdinalIgnoreCase) >= 0;
                }
            }
            catch { return false; }
        }

        private static bool ProbeHeadUrl(string url, int timeoutMs)
        {
            try
            {
                var request = (HttpWebRequest)WebRequest.Create(url);
                request.Method = "HEAD"; request.Timeout = timeoutMs; request.ReadWriteTimeout = timeoutMs; request.Proxy = null;
                request.UserAgent = "YOMI-Controller-Probe/" + ObsExpectedRevision;
                request.CachePolicy = new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);
                using (var response = (HttpWebResponse)request.GetResponse())
                    return response.StatusCode == HttpStatusCode.OK || response.StatusCode == HttpStatusCode.PartialContent;
            }
            catch { return false; }
        }

        private static bool ProbeStateRoute(string baseUrl, string path, int timeoutMs, out bool trackProjected, out string stateSample)
        {
            trackProjected = false; stateSample = "";
            int bytes; string sample;
            string sep = path.IndexOf('?') >= 0 ? "&" : "?";
            string url = baseUrl + path + sep + "client=controller-probe&t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture);
            if (!ProbeLocalUrl(url, timeoutMs, false, out bytes, out sample) || bytes < 16) return false;
            bool state = sample.IndexOf("\"clock\"", StringComparison.OrdinalIgnoreCase) >= 0 &&
                         sample.IndexOf("\"track\"", StringComparison.OrdinalIgnoreCase) >= 0;
            if (!state) return false;
            stateSample = sample;
            trackProjected = sample.IndexOf("\"track\":null", StringComparison.OrdinalIgnoreCase) < 0 &&
                             sample.IndexOf("\"track\":{}", StringComparison.OrdinalIgnoreCase) < 0;
            return true;
        }

        private static bool ProbeConfigRoute(string baseUrl, int timeoutMs)
        {
            int bytes; string sample;
            if (!ProbeLocalUrl(baseUrl + "/config?client=controller-probe&t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), timeoutMs, false, out bytes, out sample) || bytes < 16) return false;
            return sample.TrimStart().StartsWith("{", StringComparison.Ordinal) &&
                   sample.IndexOf("\"server_port\"", StringComparison.OrdinalIgnoreCase) >= 0;
        }

        // R61.82 OBS generation contract: Settings, auto-heal and the supervisor must
        // agree on revision + authority + runtime ID + supervisor PID. Merely answering
        // the HTTP routes is not enough to claim ownership of the configured port.
        private static bool ProbeDiagnosticsRoute(string baseUrl, int timeoutMs, ObsProbeResult result, string expectedRuntimeId, int expectedSupervisorPid)
        {
            int bytes; string sample;
            if (!ProbeLocalUrl(baseUrl + "/v1/obs?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), timeoutMs, false, out bytes, out sample) || bytes < 16) return false;
            try
            {
                var serializer = new JavaScriptSerializer();
                var map = AsMap(serializer.DeserializeObject(sample));
                string revision = GetString(map, "revision", "");
                string authority = GetString(map, "authority", "");
                string runtimeId = GetString(map, "runtime_id", "");
                int supervisorPid = GetInt(map, "supervisor_pid", 0);
                int serverPid = GetInt(map, "pid", 0);
                bool structural = String.Equals(revision, ObsExpectedRevision, StringComparison.OrdinalIgnoreCase) &&
                                  String.Equals(authority, ObsExpectedAuthority, StringComparison.OrdinalIgnoreCase) &&
                                  sample.IndexOf("\"overlay_file\"", StringComparison.OrdinalIgnoreCase) >= 0;
                bool generation = structural && !String.IsNullOrWhiteSpace(expectedRuntimeId) && expectedSupervisorPid > 0 &&
                                  String.Equals(runtimeId, expectedRuntimeId, StringComparison.Ordinal) && supervisorPid == expectedSupervisorPid;
                if (result != null)
                {
                    result.ServerRevision = revision;
                    result.ServerAuthority = authority;
                    result.ServerRuntimeId = runtimeId;
                    result.ServerSupervisorPid = supervisorPid;
                    result.ServerPid = serverPid;
                    result.ExpectedRuntimeId = expectedRuntimeId ?? "";
                    result.ExpectedSupervisorPid = expectedSupervisorPid;
                    result.GenerationMatches = generation;
                    var presentation = GetMap(map, "presentation");
                    result.PresentedVideoFps = GetDouble(presentation, "video_fps", -1);
                    result.PresentedVisualizerFps = GetDouble(presentation, "visualizer_fps", -1);
                    result.PresentationAgeMs = GetInt64(presentation, "age_ms", -1);
                    result.PresentationRoute = GetString(presentation, "route", "");
                }
                return generation;
            }
            catch { return false; }
        }

        private static void ProbeProjectedMedia(string baseUrl, string stateSample, ObsProbeResult result)
        {
            if (result == null || String.IsNullOrWhiteSpace(stateSample)) return;
            try
            {
                var serializer = new JavaScriptSerializer();
                var root = AsMap(serializer.DeserializeObject(stateSample));
                var track = GetMap(root, "track");
                foreach (string key in new[] { "artwork", "video", "visualizer" })
                {
                    string value = GetString(track, key, "").Trim();
                    if (String.IsNullOrWhiteSpace(value)) continue;
                    result.MediaRoutesChecked++;
                    string url;
                    if (value.StartsWith("/", StringComparison.Ordinal)) url = baseUrl + value;
                    else if (value.StartsWith(baseUrl, StringComparison.OrdinalIgnoreCase)) url = value;
                    else
                    {
                        result.MediaRoutesOk = false;
                        if (String.IsNullOrWhiteSpace(result.MediaFailure)) result.MediaFailure = key.ToUpperInvariant() + " projected a non-HTTP path";
                        continue;
                    }
                    if (ProbeHeadUrl(url, 1300)) result.MediaRoutesPassed++;
                    else
                    {
                        result.MediaRoutesOk = false;
                        if (String.IsNullOrWhiteSpace(result.MediaFailure)) result.MediaFailure = key.ToUpperInvariant() + " route did not answer";
                    }
                }
            }
            catch
            {
                result.MediaRoutesOk = false;
                if (String.IsNullOrWhiteSpace(result.MediaFailure)) result.MediaFailure = "projected media state could not be inspected";
            }
        }

        private static void ProbeBrowserClients(string baseUrl, ObsProbeResult result)
        {
            if (result == null) return;
            int bytes; string sample;
            if (!ProbeLocalUrl(baseUrl + "/clients?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), 1200, false, out bytes, out sample) || bytes < 8) return;
            try
            {
                var serializer = new JavaScriptSerializer();
                var root = AsMap(serializer.DeserializeObject(sample));
                foreach (object raw in GetList(root, "clients"))
                {
                    var row = AsMap(raw);
                    string kind = GetString(row, "kind", "client");
                    string id = GetString(row, "id", "");
                    if (String.Equals(kind, "probe", StringComparison.OrdinalIgnoreCase) || id.IndexOf("controller-probe", StringComparison.OrdinalIgnoreCase) >= 0) continue;
                    long age = GetInt64(row, "age_ms", Int64.MaxValue);
                    if (age > 30000) continue;
                    result.BrowserClientCount++;
                    if (result.FreshestBrowserClientAgeMs < 0 || age < result.FreshestBrowserClientAgeMs)
                    {
                        result.FreshestBrowserClientAgeMs = age;
                        result.FreshestBrowserClientKind = kind;
                        result.FreshestBrowserClientRoute = GetString(row, "route", "");
                    }
                }
            }
            catch { }
        }

        private static ObsProbeResult ProbeObsOutput(int port, string expectedRuntimeId, int expectedSupervisorPid)
        {
            var result = new ObsProbeResult
            {
                ExpectedRuntimeId = expectedRuntimeId ?? "",
                ExpectedSupervisorPid = expectedSupervisorPid
            };
            string baseUrl = "http://127.0.0.1:" + port.ToString(CultureInfo.InvariantCulture);
            int bytes; string sample;
            result.Service = ProbeLocalUrl(baseUrl + "/health?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), 1100, false, out bytes, out sample);
            result.Diagnostics = ProbeDiagnosticsRoute(baseUrl, 1200, result, expectedRuntimeId, expectedSupervisorPid);
            bool trackProjected; string stateSample;
            if (ProbeStateRoute(baseUrl, "/state", 1400, out trackProjected, out stateSample)) { result.State = true; result.StateRoute = "/state"; result.TrackProjected = trackProjected; }
            else if (ProbeStateRoute(baseUrl, "/v1/state", 1400, out trackProjected, out stateSample)) { result.State = true; result.StateRoute = "/v1/state"; result.TrackProjected = trackProjected; }
            else stateSample = "";
            result.Config = ProbeConfigRoute(baseUrl, 1400);

            result.Root = ProbeLocalUrl(baseUrl + "/?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), 1700, true, out result.RootBytes, out sample);
            result.Overlay = ProbeLocalUrl(baseUrl + "/overlay?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), 1700, true, out result.OverlayBytes, out sample);
            result.OverlayHtml = ProbeLocalUrl(baseUrl + "/overlay.html?t=" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture), 1700, true, out result.OverlayHtmlBytes, out sample);

            if (result.Root) { result.RouteUrl = baseUrl + "/"; result.RouteLabel = "ROOT /"; }
            else if (result.Overlay) { result.RouteUrl = baseUrl + "/overlay"; result.RouteLabel = "/overlay fallback"; }
            else if (result.OverlayHtml) { result.RouteUrl = baseUrl + "/overlay.html"; result.RouteLabel = "/overlay.html fallback"; }

            if (result.State && result.TrackProjected) ProbeProjectedMedia(baseUrl, stateSample, result);
            ProbeBrowserClients(baseUrl, result);
            return result;
        }

        private ObsProbeResult ProbeObsOutputForCurrentRuntime(int port)
        {
            Dictionary<string, object> runtime = ReadJsonUncached(Path.Combine(_stateRoot, "runtime-instance.json"));
            string runtimeId = GetString(runtime, "runtime_id", "").Trim();
            int supervisorPid = GetInt(runtime, "supervisor_pid", 0);
            return ProbeObsOutput(port, runtimeId, supervisorPid);
        }

        private void ApplyResolvedObsRoute(int port, ObsProbeResult probe, Dictionary<string, object> config)
        {
            if (probe != null && !String.IsNullOrWhiteSpace(probe.RouteUrl))
            {
                _obsResolvedClassicPort = port;
                _obsResolvedClassicUrl = probe.RouteUrl;
                _obsResolvedClassicRoute = probe.RouteLabel ?? "";
            }
            else if (_obsResolvedClassicPort != port)
            {
                _obsResolvedClassicPort = port;
                _obsResolvedClassicUrl = "";
                _obsResolvedClassicRoute = "";
            }
            if (_settingsObsClassicUrl != null) _settingsObsClassicUrl.Text = ObsLegacyOverlayUrl(config);
            if (_settingsObsSetupBlock != null) _settingsObsSetupBlock.Text = BuildObsSetupBlock(config);
        }

        private static string ObsProbeRealityLine(ObsProbeResult probe)
        {
            if (probe == null) return "Browser ?   Media ?   Server ?";
            string client = probe.BrowserClientCount > 0
                ? "CLIENT " + probe.BrowserClientCount.ToString(CultureInfo.InvariantCulture) + " " + (String.IsNullOrWhiteSpace(probe.FreshestBrowserClientKind) ? "BROWSER" : probe.FreshestBrowserClientKind.ToUpperInvariant()) + " | " + Math.Max(0, probe.FreshestBrowserClientAgeMs).ToString(CultureInfo.InvariantCulture) + "ms"
                : "CLIENT NONE <30s";
            string media = probe.MediaRoutesChecked > 0
                ? "MEDIA " + probe.MediaRoutesPassed.ToString(CultureInfo.InvariantCulture) + "/" + probe.MediaRoutesChecked.ToString(CultureInfo.InvariantCulture)
                : "MEDIA NO PROJECTED ASSETS";
            if (probe.BrowserClientCount > 0 && !String.IsNullOrWhiteSpace(probe.FreshestBrowserClientRoute))
                client += " " + probe.FreshestBrowserClientRoute;
            string server = probe.Diagnostics ? "SERVER " + ObsExpectedRevision + " OWNED" :
                (String.IsNullOrWhiteSpace(probe.ServerRevision) ? "SERVER LEGACY/UNKNOWN" : "SERVER " + probe.ServerRevision.ToUpperInvariant() + " FOREIGN/STALE");
            string presented = probe.PresentationAgeMs >= 0 && probe.PresentationAgeMs < 8000
                ? "PRESENT VIDEO " + (probe.PresentedVideoFps >= 0 ? probe.PresentedVideoFps.ToString("0.0", CultureInfo.InvariantCulture) : "?") + " | VIZ " + (probe.PresentedVisualizerFps >= 0 ? probe.PresentedVisualizerFps.ToString("0.0", CultureInfo.InvariantCulture) : "?") + " FPS"
                : "PRESENT ?";
            return client + "   " + media + "   " + presented + "   " + server;
        }

        private static string ObsProbeStatus(ObsProbeResult probe)
        {
            if (probe == null) return "Local OBS output probe did not complete.";
            bool page = !String.IsNullOrWhiteSpace(probe.RouteUrl);
            if (page && probe.State && probe.Config && probe.MediaRoutesOk && probe.Diagnostics)
            {
                string status = "LOCAL OUTPUT PASS | " + probe.RouteLabel + " serves HTML; " + probe.StateRoute + " serves state; /config serves browser configuration; server generation is " + ObsExpectedRevision + " and belongs to the current runtime." +
                                (probe.TrackProjected ? " Current track projection is present." : " No current track is projected yet.");
                if (probe.MediaRoutesChecked > 0) status += " Projected media routes " + probe.MediaRoutesPassed.ToString(CultureInfo.InvariantCulture) + "/" + probe.MediaRoutesChecked.ToString(CultureInfo.InvariantCulture) + " answer.";
                status += probe.BrowserClientCount > 0
                    ? " A browser client is actively polling YOMI."
                    : " No non-probe Browser Source activity has been seen in the last 30 seconds.";
                if (probe.PresentationAgeMs >= 0 && probe.PresentationAgeMs < 8000)
                    status += " Browser presentation measured: video " + probe.PresentedVideoFps.ToString("0.0", CultureInfo.InvariantCulture) + " FPS, visualizer " + probe.PresentedVisualizerFps.ToString("0.0", CultureInfo.InvariantCulture) + " FPS.";
                return status;
            }
            if (page && probe.State && probe.Config && probe.MediaRoutesOk && !probe.Diagnostics)
                return "STALE SERVER LIVE | page/state/config/media answer, but the listener on this port does not belong to the current " + ObsExpectedRevision + " runtime generation. Press Check status; the supervisor will repair only a listener it can safely prove belongs to this runtime.";
            if (page && probe.State && probe.Config && !probe.MediaRoutesOk)
                return "DATA LIVE | page/state/config are healthy, but a projected media route is broken: " + (String.IsNullOrWhiteSpace(probe.MediaFailure) ? "unknown media route failure" : probe.MediaFailure) + ". Press Check status; YOMI will retry or repair the local output.";
            if (page && probe.State && !probe.Config)
                return "PAGE + STATE LIVE | overlay HTML and live state are available, but /config is missing or invalid. The Browser Source cannot compose the saved layout. Press Check status; YOMI will retry or repair the local output.";
            if (page && !probe.State)
                return "PAGE LIVE | " + probe.RouteLabel + " returned HTML, but the state/data route is unavailable. The Browser Source can load the page but cannot receive Now Playing data.";
            if (probe.Service)
                return "SERVICE LIVE | HTTP is running, but none of /, /overlay, or /overlay.html returned usable overlay HTML. Press Check status; YOMI will retry or repair the local output.";
            return "LOCAL OUTPUT OFFLINE | no YOMI HTTP service is answering on the configured port. Press Check status; YOMI will retry or repair the local output.";
        }

        private void CopyObsDiagnostics()
        {
            try
            {
                ObsProbeResult probe = _lastObsProbeResult;
                string text = "YOMI OBS diagnosis" + Environment.NewLine +
                              ObsProbeStatus(probe) + Environment.NewLine +
                              ObsProbeRealityLine(probe) + Environment.NewLine +
                              "SERVER_REVISION " + (probe != null ? probe.ServerRevision : "") + Environment.NewLine +
                              "SERVER_AUTHORITY " + (probe != null ? probe.ServerAuthority : "") + Environment.NewLine +
                              "SERVER_RUNTIME " + (probe != null ? probe.ServerRuntimeId : "") + Environment.NewLine +
                              "SERVER_SUPERVISOR_PID " + (probe != null ? probe.ServerSupervisorPid.ToString(CultureInfo.InvariantCulture) : "0") + Environment.NewLine +
                              "SERVER_PID " + (probe != null ? probe.ServerPid.ToString(CultureInfo.InvariantCulture) : "0") + Environment.NewLine +
                              "GENERATION_MATCH " + (probe != null && probe.GenerationMatches ? "true" : "false") + Environment.NewLine +
                              "URL " + (_settingsObsClassicUrl != null ? _settingsObsClassicUrl.Text : "") + Environment.NewLine +
                              "PORT " + GetInt(GetObsQuickSetupConfig(), "server_port", 8876).ToString(CultureInfo.InvariantCulture);
                Clipboard.SetText(text);
                ShowToast("OBS", "Output diagnosis copied");
            }
            catch (Exception ex) { ShowToast("OBS", "Could not copy diagnosis: " + ex.Message); }
        }

        private void RefreshObsCompatibilityHealth(Dictionary<string, object> config)
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive || _settingsObsCompatibilityText == null || config == null) return;
            bool streamer = String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase);
            if (!streamer)
            {
                _lastObsProbeResult = null;
                _settingsObsCompatibilityText.Text = "OBS output is off. Choose Streamer / OBS under General and save.";
                if (_settingsObsRealityText != null) _settingsObsRealityText.Text = "Browser —   Media —   Server off";
                return;
            }
            int port = Math.Max(1, GetInt(config, "server_port", 8876)); int generation = ++_obsHealthGeneration;
            _settingsObsCompatibilityText.Text = "Checking Browser Source, media paths, and local server...";
            if (_settingsObsRealityText != null) _settingsObsRealityText.Text = "Browser …   Media …   Server …";
            ThreadPool.QueueUserWorkItem(delegate
            {
                ObsProbeResult probe = ProbeObsOutputForCurrentRuntime(port);
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (generation != _obsHealthGeneration || _settingsObsCompatibilityText == null) return;
                        _lastObsProbeResult = probe;
                        ApplyResolvedObsRoute(port, probe, config);
                        _settingsObsCompatibilityText.Text = ObsProbeStatus(probe);
                        if (_settingsObsRealityText != null) _settingsObsRealityText.Text = ObsProbeRealityLine(probe);
                    });
                }
                catch { }
            });
        }

        private void MaybeSelfHealPlaybackEngine(long now)
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive || !_running || _engineLaunchMonitorActive) return;
            lock (_engineSelfHealSync)
            {
                if (_engineSelfHealWorkerActive || now - _lastEngineSelfHealProbeMs < 6000) return;
                _engineSelfHealWorkerActive = true;
                _lastEngineSelfHealProbeMs = now;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                bool restart = false;
                bool restarted = false;
                double leaseAgeSeconds = -1.0;
                string leaseRuntimeId = "";
                string runtimeId = "";
                try
                {
                    string leasePath = Path.Combine(_stateRoot, "runtime-lease.json");
                    string runtimePath = Path.Combine(_stateRoot, "runtime-instance.json");
                    Dictionary<string, object> lease = ReadJsonUncached(leasePath);
                    Dictionary<string, object> runtime = ReadJsonUncached(runtimePath);
                    leaseRuntimeId = GetString(lease, "runtime_id", "");
                    runtimeId = GetString(runtime, "runtime_id", "");
                    bool coherent = lease.Count > 0 && runtime.Count > 0 &&
                        !String.IsNullOrWhiteSpace(leaseRuntimeId) && !String.IsNullOrWhiteSpace(runtimeId) &&
                        String.Equals(leaseRuntimeId, runtimeId, StringComparison.Ordinal);
                    bool engineLive = ProbePidFileLive(Path.Combine(_stateRoot, "engine.pid"));
                    bool supervisorLive = ProbePidFileLive(Path.Combine(_stateRoot, "supervisor.pid"));
                    try
                    {
                        if (File.Exists(leasePath))
                            leaseAgeSeconds = Math.Max(0.0, (DateTime.UtcNow - File.GetLastWriteTimeUtc(leasePath)).TotalSeconds);
                    }
                    catch { leaseAgeSeconds = -1.0; }
                    bool stale = coherent && engineLive && supervisorLive && leaseAgeSeconds >= 16.0;
                    lock (_engineSelfHealSync)
                    {
                        if (stale) _engineSelfHealConsecutiveStale++;
                        else _engineSelfHealConsecutiveStale = 0;
                        long restartNow = _clock.ElapsedMilliseconds;
                        if (_engineSelfHealConsecutiveStale >= 2 && restartNow - _lastEngineSelfHealRestartMs >= 60000)
                        {
                            _lastEngineSelfHealRestartMs = restartNow;
                            _engineSelfHealConsecutiveStale = 0;
                            restart = true;
                        }
                    }
                    if (restart && !_disposed && !_shutdownRequested && !_slotSwitchActive)
                    {
                        WriteControllerPerformanceLogAsync("ENGINE SELF-HEAL stale lease=" + leaseAgeSeconds.ToString("0.0", CultureInfo.InvariantCulture) +
                            "s runtime=" + runtimeId + " | restarting owned runtime");
                        if (!_disposed && !_shutdownRequested && !_slotSwitchActive) restarted = StopOwnedYomiRuntime();
                    }
                }
                catch { }
                finally
                {
                    lock (_engineSelfHealSync) _engineSelfHealWorkerActive = false;
                }
                if (restarted)
                {
                    try
                    {
                        TryBeginInvokeUi(DispatcherPriority.Background, delegate
                        {
                            if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                            AddActivity("Playback engine", "recovered after stale Lua runtime lease");
                            ShowToast("Playback recovered", "YOMI detected a stalled playback engine and restarted it.");
                            StartEngine();
                        });
                    }
                    catch { }
                }
            });
        }

        private bool RequestObsServerRepair(int port, string reason)
        {
            try
            {
                Dictionary<string, object> runtime = ReadJsonUncached(Path.Combine(_stateRoot, "runtime-instance.json"));
                string runtimeId = GetString(runtime, "runtime_id", "").Trim();
                int supervisorPid = GetInt(runtime, "supervisor_pid", 0);
                if (runtimeId.Length == 0 || supervisorPid <= 0) return false;
                try
                {
                    using (Process supervisor = Process.GetProcessById(supervisorPid))
                    {
                        if (supervisor.HasExited) return false;
                    }
                }
                catch { return false; }

                string requestId = Guid.NewGuid().ToString("N");
                var request = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "schema", 1 }, { "revision", "R61.94" }, { "request_id", requestId },
                    { "runtime_id", runtimeId }, { "supervisor_pid", supervisorPid },
                    { "port", Math.Max(1, port) }, { "requester_pid", Process.GetCurrentProcess().Id },
                    { "requester_session", _controllerDiagnosticSession }, { "reason", reason ?? "" },
                    { "utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) }
                };
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 64 };
                WriteUtf8NoBom(Path.Combine(_stateRoot, "obs-repair-request.json"), serializer.Serialize(request));
                WriteControllerPerformanceLogAsync("OBS REPAIR REQUEST id=" + requestId.Substring(0, 12) + " port=" + port.ToString(CultureInfo.InvariantCulture) + " reason=" + (reason ?? ""));
                return true;
            }
            catch { return false; }
        }

        private void MaybeSelfHealObsOutput(long now, Dictionary<string, object> config)
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive || !_running || config == null || !String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase)) return;
            lock (_obsSelfHealSync)
            {
                if (_obsSelfHealWorkerActive || now - _lastObsSelfHealProbeMs < 12000) return;
                _obsSelfHealWorkerActive = true;
                _lastObsSelfHealProbeMs = now;
            }
            int port = Math.Max(1, GetInt(config, "server_port", 8876));
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                bool repaired = false;
                ObsProbeResult probe = null;
                try
                {
                    probe = ProbeObsOutputForCurrentRuntime(port);
                    bool healthy = probe != null && probe.Service && !String.IsNullOrWhiteSpace(probe.RouteUrl) && probe.State && probe.Config && probe.Diagnostics;
                    if (healthy) _obsSelfHealConsecutiveFailures = 0;
                    else
                    {
                        _obsSelfHealConsecutiveFailures++;
                        // One failed sample may be startup timing. Two consecutive failures means the
                        // browser-output half has genuinely disappeared; repair only that child.
                        if (_obsSelfHealConsecutiveFailures >= 2)
                        {
                            long restartNow = _clock.ElapsedMilliseconds;
                            if (restartNow - _lastObsSelfHealRestartMs >= 30000)
                            {
                                _lastObsSelfHealRestartMs = restartNow;
                                if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                                bool requested = RequestObsServerRepair(port, "automatic health probe failed twice");
                                if (requested)
                                {
                                    Thread.Sleep(1800);
                                    if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                                    ObsProbeResult verification = ProbeObsOutputForCurrentRuntime(port);
                                    repaired = verification != null && verification.Service && !String.IsNullOrWhiteSpace(verification.RouteUrl) && verification.State && verification.Config && verification.Diagnostics;
                                }
                                if (repaired) _obsSelfHealConsecutiveFailures = 0;
                            }
                        }
                    }
                }
                catch { }
                finally
                {
                    lock (_obsSelfHealSync) _obsSelfHealWorkerActive = false;
                }
                if (repaired)
                {
                    try { TryBeginInvokeUi(DispatcherPriority.Background, delegate { if (_disposed || _shutdownRequested || _slotSwitchActive) return; AddActivity("OBS output", "local server recovered without restarting audio"); }); } catch { }
                }
            });
        }

        private void RepairObsOutput()
        {
            if (_disposed || _shutdownRequested || _slotSwitchActive) { ShowToast("OBS status", "Finish the current YOMI transition before repairing Browser Source output."); return; }
            Dictionary<string, object> config = GetObsQuickSetupConfig();
            if (!String.Equals(GetString(config, "app_mode", "Streamer / OBS"), "Streamer / OBS", StringComparison.OrdinalIgnoreCase))
            {
                _settingsObsCompatibilityText.Text = "Enable Streamer / OBS first, then save."; return;
            }
            int port = Math.Max(1, GetInt(config, "server_port", 8876));
            if (_settingsObsRepairButton != null) { _settingsObsRepairButton.IsEnabled = false; _settingsObsRepairButton.Content = "Checking..."; }
            _settingsObsCompatibilityText.Text = "Checking Browser Source, projected media, browser activity, and measured frame presentation...";
            if (_settingsObsRealityText != null) _settingsObsRealityText.Text = "Checking now...";
            ShowToast("OBS status", "Checking Browser Source and presentation...");
            ThreadPool.QueueUserWorkItem(delegate
            {
                if (_disposed || _shutdownRequested || _slotSwitchActive) return;
                ObsProbeResult probe = ProbeObsOutputForCurrentRuntime(port);
                bool healthy = probe != null && !String.IsNullOrWhiteSpace(probe.RouteUrl) && probe.State && probe.Config && probe.MediaRoutesOk && probe.Diagnostics;
                bool repairRequested = healthy ? false : (!_disposed && !_shutdownRequested && !_slotSwitchActive && RequestObsServerRepair(port, "manual OBS status repair"));
                try
                {
                    TryBeginInvokeUi(DispatcherPriority.Background, delegate
                    {
                        if (_settingsObsRepairButton != null) { _settingsObsRepairButton.IsEnabled = true; _settingsObsRepairButton.Content = "Check status"; }
                        _lastObsProbeResult = probe;
                        if (_settingsObsRealityText != null) _settingsObsRealityText.Text = ObsProbeRealityLine(probe);
                        if (healthy)
                        {
                            ApplyResolvedObsRoute(port, probe, config);
                            _settingsObsCompatibilityText.Text = ObsProbeStatus(probe) + (probe.BrowserClientCount > 0
                                ? " YOMI can see browser activity; if OBS is visually blank, inspect the Browser Source transform/visibility next."
                                : " YOMI cannot see an external Browser Source polling yet; refresh or re-enable the OBS Browser Source using the exact URL shown above.");
                            ShowToast("OBS status", probe.BrowserClientCount > 0 ? "Browser Source is connected. Frame presentation is shown in Settings." : "Local output is healthy, but no OBS Browser Source is polling it right now.");
                            return;
                        }
                        if (!repairRequested)
                        {
                            _settingsObsCompatibilityText.Text = "OBS repair request could not reach the active supervisor. Audio playback was deliberately left untouched."; ShowToast("OBS status", "Supervisor repair request could not be written."); return;
                        }
                        _settingsObsCompatibilityText.Text = "OBS repair requested from the runtime supervisor; audio playback was not interrupted. Verifying output...";
                        var wait = new DispatcherTimer(DispatcherPriority.Background) { Interval = TimeSpan.FromSeconds(2.2) };
                        wait.Tick += delegate { wait.Stop(); if (_disposed || _shutdownRequested || _slotSwitchActive) return; RefreshObsCompatibilityHealth(GetObsQuickSetupConfig()); };
                        wait.Start();
                    });
                }
                catch { }
            });
        }

        private static void SafeStart(string file, string args)
        {
            try
            {
                Process.Start(new ProcessStartInfo
                {
                    FileName = file,
                    Arguments = args ?? "",
                    UseShellExecute = true
                });
            }
            catch { }
        }

        private static Dictionary<string, object> ReadJsonUncached(string path)
        {
            try
            {
                if (!File.Exists(path)) return EmptyMap();
                var serializer = new JavaScriptSerializer();
                return AsMap(serializer.DeserializeObject(ReadTextShared(path)));
            }
            catch { return EmptyMap(); }
        }

        private Dictionary<string, object> ReadJsonCached(string path)
        {
            FileJsonCache cached;
            if (!_jsonCache.TryGetValue(path, out cached))
            {
                cached = new FileJsonCache();
                _jsonCache[path] = cached;
            }

            // R61.69 responsiveness rule: after the first hydration, the WPF dispatcher never
            // performs filesystem metadata/read/JSON work for runtime snapshots. Defender, disk,
            // network-backed folders, or a writer holding a file may be slow; the UI consumes the
            // last complete immutable snapshot while a single latest-wins worker refreshes it.
            if (_window != null && _window.Dispatcher.CheckAccess())
            {
                Dictionary<string, object> existing;
                lock (cached.Sync) existing = cached.Value;
                if (existing != null)
                {
                    QueueJsonCacheRefresh(path, cached);
                    return existing;
                }
            }
            return RefreshJsonCacheBlocking(path, cached);
        }

        private void QueueJsonCacheRefresh(string path, FileJsonCache cached)
        {
            if (cached == null || String.IsNullOrWhiteSpace(path)) return;
            long now = _clock.ElapsedMilliseconds;
            lock (cached.Sync)
            {
                if (cached.RefreshPending || now - cached.LastRefreshRequestedMs < 150) return;
                cached.LastRefreshRequestedMs = now;
                cached.RefreshPending = true;
            }
            ThreadPool.QueueUserWorkItem(delegate(object ignored)
            {
                try { RefreshJsonCacheBlocking(path, cached); }
                finally { lock (cached.Sync) cached.RefreshPending = false; }
            });
        }

        private Dictionary<string, object> PresentationElementState(FrameworkElement element, Image image)
        {
            var state = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
            if (element == null)
            {
                state["exists"] = false;
                return state;
            }
            state["exists"] = true;
            state["visibility"] = element.Visibility.ToString();
            state["is_visible"] = element.IsVisible;
            state["width"] = Math.Round(Math.Max(0, element.ActualWidth), 2);
            state["height"] = Math.Round(Math.Max(0, element.ActualHeight), 2);
            state["connected"] = PresentationSource.FromVisual(element) != null;
            if (image != null) state["source"] = image.Source != null;
            return state;
        }

        private Dictionary<string, object> PresentationArtworkState()
        {
            var state = PresentationElementState(_artworkCropSurface, null);
            ImageBrush brush = _artworkCropSurface == null ? null : _artworkCropSurface.Fill as ImageBrush;
            state["source"] = brush != null && brush.ImageSource != null;
            state["pane_visible"] = _artworkPane != null && _artworkPane.IsVisible;
            state["pane_width"] = _artworkPane == null ? 0.0 : Math.Round(Math.Max(0, _artworkPane.ActualWidth), 2);
            state["pane_height"] = _artworkPane == null ? 0.0 : Math.Round(Math.Max(0, _artworkPane.ActualHeight), 2);
            state["brush_stretch"] = brush == null ? "none" : brush.Stretch.ToString();
            state["brush_alignment_x"] = brush == null ? "none" : brush.AlignmentX.ToString();
            state["brush_alignment_y"] = brush == null ? "none" : brush.AlignmentY.ToString();
            state["smart_crop_available"] = _artworkDecodedSmartCrop != null;
            state["smart_crop_applied"] = _artworkSmartCropApplied;
            state["smart_crop_decision"] = _artworkSmartCropDecision ?? "";
            state["smart_crop_rect"] = (_artworkSmartCropRect.Width <= 0 || _artworkSmartCropRect.Height <= 0) ? "" :
                _artworkSmartCropRect.X.ToString(CultureInfo.InvariantCulture) + "," +
                _artworkSmartCropRect.Y.ToString(CultureInfo.InvariantCulture) + "," +
                _artworkSmartCropRect.Width.ToString(CultureInfo.InvariantCulture) + "x" +
                _artworkSmartCropRect.Height.ToString(CultureInfo.InvariantCulture);
            return state;
        }

        private Dictionary<string, object> PresentationMediaElementState(MediaElement media)
        {
            var state = PresentationElementState(media, null);
            if (media == null) return state;
            try { state["source"] = media.Source != null ? media.Source.ToString() : ""; } catch { state["source"] = ""; }
            try { state["natural_width"] = media.NaturalVideoWidth; state["natural_height"] = media.NaturalVideoHeight; } catch { state["natural_width"] = 0; state["natural_height"] = 0; }
            try { state["position_seconds"] = Math.Round(media.Position.TotalSeconds, 3); } catch { state["position_seconds"] = -1.0; }
            try { state["can_pause"] = media.CanPause; } catch { state["can_pause"] = false; }
            return state;
        }

        private void SchedulePresentationStatusWrite(bool force)
        {
            if (_disposed || _window == null) return;
            long now = _clock.ElapsedMilliseconds;
            if (!force && now - _lastPresentationStatusCaptureMs < 2000) return;
            _lastPresentationStatusCaptureMs = now;
            try
            {
                var root = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "schema", 5 }, { "revision", ControllerBuildRevision },
                    { "utc", DateTime.UtcNow.ToString("O", CultureInfo.InvariantCulture) },
                    { "runtime_id", _diagnosticRuntimeId ?? "" }, { "session_id", _sessionId ?? "" },
                    { "controller_session", _controllerDiagnosticSession }, { "controller_pid", Process.GetCurrentProcess().Id },
                    { "occurrence", _currentOccurrence }, { "running", _running }, { "paused", _paused },
                    { "media_mode", _mediaMode.ToString() }, { "visualizer_enabled", _visualizerEnabled },
                    { "performance_workspace", _performanceWorkspace }, { "mini_mode", _miniMode }, { "micro_mode", _microMode },
                    { "queue_open", _queueOpen }, { "queue_model_rows", _order.Count }, { "queue_ui_rows", _queueRows.Count },
                    { "queue_ui_materialized", QueueUiRowsReady }, { "queue_ui_materializing", _queueUiMaterializationActive },
                    { "queue_ui_remaining", _queueUiMaterializationRemaining }
                };
                root["performance_budget"] = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase)
                {
                    { "refresh_budget_ms", UiRefreshBudgetMs }, { "last_refresh_ms", _lastRefreshDurationMs },
                    { "refresh_ema_ms", Math.Round(_uiRefreshEmaMs, 2) },
                    { "pressure", _clock.ElapsedMilliseconds < _uiBudgetPressureUntilMs },
                    { "pressure_remaining_ms", Math.Max(0, _uiBudgetPressureUntilMs - _clock.ElapsedMilliseconds) },
                    { "overrun_count", _uiBudgetOverrunCount },
                    { "queue_batch_active", _queueProjectionApplyActive },
                    { "queue_batch_pending_rows", _queueProjectionApplyPendingRows },
                    { "queue_slice_rows", _queueProjectionAdaptiveSlice },
                    { "queue_slice_max", QueueProjectionApplySlice }, { "queue_immediate_limit", QueueProjectionImmediateLimit },
