                frame["video_column"] = _videoColumn == null ? 0.0 : Math.Round(Math.Max(0, _videoColumn.Width.Value), 2);
                frame["seam"] = _mediaGapColumn == null ? 0.0 : Math.Round(Math.Max(0, _mediaGapColumn.Width.Value), 2);
                frame["queue_canvas"] = _queueCanvasActive;
                frame["adaptive_tier"] = _adaptiveLayoutTier.ToString();
                root["media_frame"] = frame;
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 64 };
                string payload = serializer.Serialize(root);
                lock (_presentationStatusWriteSync)
                {
                    _pendingPresentationStatusPayload = payload;
                    if (_presentationStatusWriteWorkerActive) return;
                    _presentationStatusWriteWorkerActive = true;
                }
                ThreadPool.QueueUserWorkItem(delegate(object ignored)
                {
                    while (true)
                    {
                        string writePayload;
                        lock (_presentationStatusWriteSync)
                        {
                            writePayload = _pendingPresentationStatusPayload;
                            _pendingPresentationStatusPayload = "";
                        }
                        try { WriteUtf8NoBom(Path.Combine(_stateRoot, "presentation-status.json"), writePayload); }
                        catch { }
                        lock (_presentationStatusWriteSync)
                        {
                            if (_pendingPresentationStatusPayload.Length > 0) continue;
                            _presentationStatusWriteWorkerActive = false;
                            break;
                        }
                    }
                });
            }
            catch { }
        }

        private Dictionary<string, object> RefreshJsonCacheBlocking(string path, FileJsonCache cached)
        {
            try
            {
                if (!File.Exists(path))
                {
                    lock (cached.Sync)
                    {
                        cached.Stamp = 0;
                        cached.Value = EmptyMap();
                        return cached.Value;
                    }
                }
                long stamp = File.GetLastWriteTimeUtc(path).Ticks;
                lock (cached.Sync)
                {
                    if (stamp == cached.Stamp && cached.Value != null) return cached.Value;
                }
                string text = ReadTextShared(path);
                var serializer = new JavaScriptSerializer { MaxJsonLength = Int32.MaxValue, RecursionLimit = 128 };
                var value = AsMap(serializer.DeserializeObject(text));
                lock (cached.Sync)
                {
                    cached.Stamp = stamp;
                    cached.Value = value;
                    return cached.Value;
                }
            }
            catch
            {
                lock (cached.Sync) return cached.Value ?? EmptyMap();
            }
        }

        private static string ReadTextShared(string path)
        {
            using (var stream = new FileStream(path, FileMode.Open, FileAccess.Read, FileShare.ReadWrite | FileShare.Delete))
            using (var reader = new StreamReader(stream, Encoding.UTF8, true))
                return reader.ReadToEnd();
        }

        private static void WriteUtf8NoBom(string path, string text)
        {
            string temp = path + ".tmp." + Process.GetCurrentProcess().Id.ToString(CultureInfo.InvariantCulture) + "." +
                Thread.CurrentThread.ManagedThreadId.ToString(CultureInfo.InvariantCulture) + "." + Guid.NewGuid().ToString("N");
            File.WriteAllText(temp, text ?? "", new UTF8Encoding(false));
            Exception last = null;
            try
            {
                // R61.106.8: never implement atomic replacement as Delete(destination)+Move(temp).
                // That creates a real missing-file window for the recorder and for peer processes.
                // A destination can also appear between Exists and Move, so retry against the new
                // filesystem state instead of deleting someone else's just-published state.
                for (int attempt = 0; attempt < 4; attempt++)
                {
                    try
                    {
                        if (File.Exists(path))
                            File.Replace(temp, path, path + ".previous", true);
                        else
                            File.Move(temp, path);
                        return;
                    }
                    catch (IOException ex)
                    {
                        last = ex;
                        if (attempt < 3) Thread.Sleep(2 << attempt);
                    }
                    catch (UnauthorizedAccessException ex)
                    {
                        last = ex;
                        if (attempt < 3) Thread.Sleep(2 << attempt);
                    }
                }
                if (last != null) throw last;
            }
            finally
            {
                try { if (File.Exists(temp)) File.Delete(temp); } catch { }
            }
        }

        private Brush Brush(string key)
        {
            return _window.TryFindResource(key) as Brush ?? Brushes.Gray;
        }

        private static Dictionary<string, object> EmptyMap()
        {
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        }

        private static Dictionary<string, object> AsMap(object raw)
        {
            var map = raw as Dictionary<string, object>;
            if (map != null)
                return map;
            var generic = raw as IDictionary<string, object>;
            if (generic != null)
                return new Dictionary<string, object>(generic, StringComparer.OrdinalIgnoreCase);
            var result = EmptyMap();
            var dictionary = raw as IDictionary;
            if (dictionary != null)
            {
                foreach (DictionaryEntry entry in dictionary)
                    result[Convert.ToString(entry.Key, CultureInfo.InvariantCulture)] = entry.Value;
            }
            return result;
        }

        private static Dictionary<string, object> GetMap(Dictionary<string, object> map, string key)
        {
            if (map == null)
                return EmptyMap();
            object value;
            return map.TryGetValue(key, out value) ? AsMap(value) : EmptyMap();
        }

        private static string GetStringListSummary(Dictionary<string, object> map, string key)
        {
            var values = new List<string>();
            foreach (object raw in GetList(map, key))
            {
                string text = Convert.ToString(raw, CultureInfo.InvariantCulture) ?? "";
                text = text.Trim();
                if (text.Length > 0 && !values.Any(x => String.Equals(x, text, StringComparison.OrdinalIgnoreCase))) values.Add(text);
            }
            if (values.Count == 0) return "";
            string summary = String.Join(" + ", values.Take(2).ToArray());
            if (values.Count > 2) summary += " +" + (values.Count - 2).ToString(CultureInfo.InvariantCulture);
            return summary;
        }

        private static List<object> GetList(Dictionary<string, object> map, string key)
        {
            if (map == null)
                return new List<object>();
            object raw;
            if (!map.TryGetValue(key, out raw) || raw == null)
                return new List<object>();
            var list = raw as object[];
            if (list != null)
                return list.ToList();
            var array = raw as ArrayList;
            if (array != null)
                return array.Cast<object>().ToList();
            var enumerable = raw as IEnumerable;
            if (enumerable != null && !(raw is string))
            {
                var output = new List<object>();
                foreach (var item in enumerable)
                    output.Add(item);
                return output;
            }
            return new List<object>();
        }

        private static string GetString(Dictionary<string, object> map, string key, string fallback)
        {
            if (map == null)
                return fallback;
            object value;
            if (!map.TryGetValue(key, out value) || value == null)
                return fallback;
            return Convert.ToString(value, CultureInfo.InvariantCulture) ?? fallback;
        }

        private static int GetInt(Dictionary<string, object> map, string key, int fallback)
        {
            if (map == null)
                return fallback;
            object value;
            return map.TryGetValue(key, out value) ? ToInt(value, fallback) : fallback;
        }

        private static long GetInt64(Dictionary<string, object> map, string key, long fallback)
        {
            if (map == null)
                return fallback;
            object value;
            if (!map.TryGetValue(key, out value) || value == null)
                return fallback;
            try { return Convert.ToInt64(value, CultureInfo.InvariantCulture); }
            catch { return fallback; }
        }

        private static double GetDouble(Dictionary<string, object> map, string key, double fallback)
        {
            if (map == null)
                return fallback;
            object value;
            return map.TryGetValue(key, out value) ? ToDouble(value, fallback) : fallback;
        }

        private static bool GetBool(Dictionary<string, object> map, string key, bool fallback)
        {
            if (map == null)
                return fallback;
            object value;
            if (!map.TryGetValue(key, out value) || value == null)
                return fallback;
            if (value is bool)
                return (bool)value;
            bool parsed;
            if (Boolean.TryParse(Convert.ToString(value, CultureInfo.InvariantCulture), out parsed))
                return parsed;
            return ToInt(value, fallback ? 1 : 0) != 0;
        }

        private static int ToInt(object value, int fallback)
        {
            if (value == null)
                return fallback;
            try { return Convert.ToInt32(value, CultureInfo.InvariantCulture); }
            catch
            {
                double d;
                return Double.TryParse(Convert.ToString(value, CultureInfo.InvariantCulture), NumberStyles.Float, CultureInfo.InvariantCulture, out d)
                    ? (int)d
                    : fallback;
            }
        }

        private static double ToDouble(object value, double fallback)
        {
            if (value == null)
                return fallback;
            try { return Convert.ToDouble(value, CultureInfo.InvariantCulture); }
            catch
            {
                double d;
                return Double.TryParse(Convert.ToString(value, CultureInfo.InvariantCulture), NumberStyles.Float, CultureInfo.InvariantCulture, out d)
                    ? d
                    : fallback;
            }
        }

        private static string ComputeSourceKey(string youtubeId, string url)
        {
            if (!String.IsNullOrWhiteSpace(youtubeId))
                return IdentityHash("youtube:" + youtubeId);
            if (!String.IsNullOrWhiteSpace(url))
                return IdentityHash("url:" + url);
            return "";
        }

        private static string IdentityHash(string text)
        {
            return Hash32(text, 2166136261u).ToString("x8", CultureInfo.InvariantCulture) +
                   Hash32(text, 2246822519u).ToString("x8", CultureInfo.InvariantCulture);
        }

        private static uint Hash32(string text, uint seed)
        {
            uint h = seed;
            byte[] bytes = Encoding.UTF8.GetBytes(text ?? "");
            unchecked
            {
                foreach (byte b in bytes)
                    h = h * 65599u + b + 17u;
            }
            return h;
        }

        // R61.106.10: controller-owned extractor children stay inside the YOMI data tree.
        // This contains yt-dlp cache, Deno cache, TEMP and TMP instead of spilling them into
        // roaming/global temporary roots during discovery and metadata hydration.
        private string YtDlpCacheDirectory()
        {
            string path = Path.Combine(_dataRoot, "tool-cache", "yt-dlp");
            try { Directory.CreateDirectory(path); } catch { }
            return path;
        }

        private void ConfigureContainedChildProcessStartInfo(ProcessStartInfo psi)
        {
            if (psi == null) return;
            string temp = Path.Combine(_dataRoot, "runtime-temp");
            string denoCache = Path.Combine(_dataRoot, "tool-cache", "deno");
            string toolCache = Path.Combine(_dataRoot, "tool-cache");
            try { Directory.CreateDirectory(temp); } catch { }
            try { Directory.CreateDirectory(denoCache); } catch { }
            try { Directory.CreateDirectory(toolCache); } catch { }
            try { psi.EnvironmentVariables["TEMP"] = temp; } catch { }
            try { psi.EnvironmentVariables["TMP"] = temp; } catch { }
            try { psi.EnvironmentVariables["DENO_DIR"] = denoCache; } catch { }
            try { psi.EnvironmentVariables["XDG_CACHE_HOME"] = toolCache; } catch { }
        }

        private void ConfigureYtDlpProcessStartInfo(ProcessStartInfo psi)
        {
            ConfigureContainedChildProcessStartInfo(psi);
        }

        private static string Quote(string value)
        {
            return "\"" + (value ?? "").Replace("\"", "\\\"") + "\"";
        }

        private bool TryBeginInvokeUi(DispatcherPriority priority, Action action)
        {
            if (action == null || _disposed || _window == null) return false;
            Dispatcher dispatcher = _window.Dispatcher;
            if (dispatcher == null || dispatcher.HasShutdownStarted || dispatcher.HasShutdownFinished) return false;
            try
            {
                dispatcher.BeginInvoke(priority, new Action(delegate
                {
                    if (_disposed || dispatcher.HasShutdownStarted || dispatcher.HasShutdownFinished) return;
                    action();
                }));
                return true;
            }
            catch { return false; }
        }

        private static string PsQuote(string value)
        {
            return "'" + (value ?? "").Replace("'", "''") + "'";
        }

        private void RestoreKeyboardFocus(IInputElement target)
        {
            try
            {
                var element = target as UIElement;
                if (target != null && (element == null || (element.IsVisible && element.IsEnabled)))
                {
                    Keyboard.Focus(target);
                    return;
                }
            }
            catch { }
            try { _window.Focus(); } catch { }
        }

        private void CaptureNormalWindowGeometry()
        {
            if (_window.WindowState != WindowState.Normal || _applyingWorkspaceProfile || _internalGeometryChange)
                return;

            double logicalLeft = _window.Left + (_queueOpen ? _queueExpansionShiftX : 0);
            if (!Double.IsNaN(logicalLeft) && !Double.IsInfinity(logicalLeft)) _normalLeft = logicalLeft;
            if (!Double.IsNaN(_window.Top) && !Double.IsInfinity(_window.Top)) _normalTop = _window.Top;

            // Mini shares desktop position with the full player but has intentionally separate size.
            if (_miniMode) return;

            double logicalWidth = _window.Width;
            if (_queueOpen && _queueExpansionWidth > 0)
                logicalWidth = Math.Max(FullPlayerMinWidth, logicalWidth - _queueExpansionWidth);
            if (!Double.IsNaN(logicalWidth) && !Double.IsInfinity(logicalWidth) && logicalWidth >= FullPlayerMinWidth)
            {
                // The rectangle the operator actually leaves on screen is the normal geometry.
                // Queue-open/closed keep separate convenience memories, but neither may replace
                // the last real window width with an old/default workbench width at shutdown.
                _normalWidth = logicalWidth;
                if (_queueOpen) _queueWorkbenchWidth = logicalWidth;
                else _compactControllerWidth = Math.Max(FullPlayerMinWidth, Math.Min(1600.0, logicalWidth));
            }
            if (!Double.IsNaN(_window.Height) && !Double.IsInfinity(_window.Height) && _window.Height >= FullPlayerMinHeight)
            {
                _normalHeight = _window.Height;
                if (_queueOpen) _queueWorkbenchHeight = _window.Height;
                else _compactControllerHeight = _window.Height;
            }
        }

        private Rect CurrentWorkAreaDips()
        {
            double scaleX = 1.0, scaleY = 1.0;
            try
            {
                var dpi = VisualTreeHelper.GetDpi(_window);
                scaleX = Math.Max(0.1, dpi.DpiScaleX);
                scaleY = Math.Max(0.1, dpi.DpiScaleY);
            }
            catch { }

            Forms.Screen screen = null;
            try
            {
                IntPtr hwnd = new WindowInteropHelper(_window).Handle;
                if (hwnd != IntPtr.Zero) screen = Forms.Screen.FromHandle(hwnd);
            }
            catch { }
            if (screen == null)
            {
                double left = Double.IsNaN(_window.Left) ? 0 : _window.Left;
                double top = Double.IsNaN(_window.Top) ? 0 : _window.Top;
                double width = Double.IsNaN(_window.Width) ? FullPlayerDefaultWidth : _window.Width;
                double height = Double.IsNaN(_window.Height) ? FullPlayerDefaultHeight : _window.Height;
                var probe = new Drawing.Rectangle(
                    (int)Math.Round(left * scaleX), (int)Math.Round(top * scaleY),
                    Math.Max(1, (int)Math.Round(width * scaleX)), Math.Max(1, (int)Math.Round(height * scaleY)));
                screen = Forms.Screen.FromRectangle(probe);
            }
            var work = screen.WorkingArea;
            return new Rect(work.Left / scaleX, work.Top / scaleY, work.Width / scaleX, work.Height / scaleY);
        }

        private void RestoreLogicalNormalGeometry()
        {
            if (_window.WindowState != WindowState.Normal || _miniMode) return;
            Rect work = CurrentWorkAreaDips();
            double fullWidthFloor = EffectiveFullWidthFloor(work);
            double fullHeightFloor = EffectiveFullHeightFloor(work);
            _normalWidth = Math.Max(fullWidthFloor, Math.Min(_normalWidth, Math.Max(fullWidthFloor, work.Width)));
            _normalHeight = Math.Max(fullHeightFloor, Math.Min(_normalHeight, Math.Max(fullHeightFloor, work.Height)));
            if (Double.IsNaN(_normalLeft)) _normalLeft = !Double.IsNaN(_window.Left) ? _window.Left : work.Left + Math.Max(0, (work.Width - _normalWidth) / 2);
            if (Double.IsNaN(_normalTop)) _normalTop = !Double.IsNaN(_window.Top) ? _window.Top : work.Top + Math.Max(0, (work.Height - _normalHeight) / 2);
            _normalLeft = Math.Max(work.Left, Math.Min(_normalLeft, work.Right - _normalWidth));
            _normalTop = Math.Max(work.Top, Math.Min(_normalTop, work.Bottom - _normalHeight));
            _internalGeometryChange = true;
            try
            {
                _window.Left = _normalLeft;
                _window.Top = _normalTop;
                _window.Width = _normalWidth;
                _window.Height = _normalHeight;
            }
            finally { _internalGeometryChange = false; }
            _queueExpansionWidth = 0;
            _queueExpansionShiftX = 0;
        }

        private void ConstrainWindowToVisibleWorkArea()
        {
            try
            {
                Rect work = CurrentWorkAreaDips();
                double width = Math.Max(_window.MinWidth, Math.Min(_window.Width, Math.Max(_window.MinWidth, work.Width)));
                double height = Math.Max(_window.MinHeight, Math.Min(_window.Height, Math.Max(_window.MinHeight, work.Height)));
                double left = Double.IsNaN(_window.Left) ? work.Left + Math.Max(0, (work.Width - width) / 2) : _window.Left;
                double top = Double.IsNaN(_window.Top) ? work.Top + Math.Max(0, (work.Height - height) / 2) : _window.Top;
                left = Math.Max(work.Left, Math.Min(left, work.Right - width));
                top = Math.Max(work.Top, Math.Min(top, work.Bottom - height));

                _internalGeometryChange = true;
                try
                {
                    _window.Width = width;
                    _window.Height = height;
                    _window.Left = left;
                    _window.Top = top;
                }
                finally { _internalGeometryChange = false; }

                if (!_miniMode)
                {
                    double fullWidthFloor = EffectiveFullWidthFloor(work);
                    double fullHeightFloor = EffectiveFullHeightFloor(work);
                    _normalWidth = Math.Max(fullWidthFloor, Math.Min(_normalWidth, Math.Max(fullWidthFloor, work.Width)));
                    _normalHeight = Math.Max(fullHeightFloor, Math.Min(_normalHeight, Math.Max(fullHeightFloor, work.Height)));
                    if (Double.IsNaN(_normalLeft)) _normalLeft = left;
                    if (Double.IsNaN(_normalTop)) _normalTop = top;
                    _normalLeft = Math.Max(work.Left, Math.Min(_normalLeft, work.Right - _normalWidth));
                    _normalTop = Math.Max(work.Top, Math.Min(_normalTop, work.Bottom - _normalHeight));
                }
            }
            catch { }
        }

        private void SyncWindowCompositionBackground()
        {
            try
            {
                if (_window != null) _window.Opacity = 1.0;
                if (_windowSource == null || _windowSource.CompositionTarget == null) return;

                // RootWindow is a borderless layered WPF window (AllowsTransparency=True). Its
                // alpha-bearing theme brushes can therefore reveal the actual desktop. Keep the
                // HWND itself at full opacity so text/icons are never faded with the background.
                if (_window != null && _window.AllowsTransparency)
                {
                    _windowSource.CompositionTarget.BackgroundColor = Colors.Transparent;
                    return;
                }

                IntPtr hwnd = new WindowInteropHelper(_window).Handle;
                bool translucent = _windowTransparencyPercent > 0.01;
                MARGINS margins = translucent
                    ? new MARGINS { cxLeftWidth = -1, cxRightWidth = -1, cyTopHeight = -1, cyBottomHeight = -1 }
                    : new MARGINS { cxLeftWidth = 0, cxRightWidth = 0, cyTopHeight = 0, cyBottomHeight = 0 };
                if (hwnd != IntPtr.Zero) DwmExtendFrameIntoClientArea(hwnd, ref margins);
                if (translucent) _windowSource.CompositionTarget.BackgroundColor = Colors.Transparent;
                else
                {
                    var brush = _window.TryFindResource("AppBg") as SolidColorBrush;
                    _windowSource.CompositionTarget.BackgroundColor = brush != null ? Color.FromRgb(brush.Color.R, brush.Color.G, brush.Color.B) : Colors.Black;
                }
            }
            catch { }
        }

        private void TryEnableModernWindowChrome()
        {
            TryEnableModernWindowChrome(_window);
        }

        private void TryEnableModernWindowChrome(Window target)
        {
            if (target == null) return;
            try
            {
                var hwnd = new WindowInteropHelper(target).Handle;
                int dark = 1;
                DwmSetWindowAttribute(hwnd, 20, ref dark, Marshal.SizeOf(typeof(int)));
                int corner = 2;
                DwmSetWindowAttribute(hwnd, 33, ref corner, Marshal.SizeOf(typeof(int)));
            }
            catch { }
        }

