        public void Dispose()
        {
            if (_disposed)
                return;
            try { SaveUiState(); } catch { }
            try { PersistActiveSlotState(false); } catch { }
            try { FinalizeListeningVisit(true, false); } catch { }
            try { FlushLibraryStateIfDue(true); } catch { }
            // Final controller/library state is write-behind during normal operation. Once the WPF
            // run loop is ending, give the already-queued final snapshots a bounded durability window
            // before process teardown. Ordinary resize/click paths never pay this wait.
            try { _uiStateWriteIdle.WaitOne(1500); } catch { }
            try { _libraryWriteIdle.WaitOne(2000); } catch { }
            _disposed = true;
            _engineLaunchMonitorActive = false;
            _engineLaunchGeneration++;
            _orderMutationRequestPending = false;
            _contextOrderCommandPending = false;
            ClearPendingOrderMutation();
            lock (_transportCommandSync) { _transportCommandQueue.Clear(); }
            try { _timer.Stop(); } catch { }
            try { _uiHeartbeatTimer.Stop(); } catch { }
            if (_uiWatchdogTimer != null) { try { _uiWatchdogTimer.Dispose(); } catch { } _uiWatchdogTimer = null; }
            if (_toastTimer != null) try { _toastTimer.Stop(); } catch { }
            ReleaseIntentLease();
            try { _intentLeaseMutex.Dispose(); } catch { }
            StopPreviewProcesses();
            try { if (_runtimeJobOwnsSupervisor) TerminateOwnedRuntimeJob(); } catch { }
            CloseRuntimeJobHandle();
            if (_tray != null)
            {
                try { _tray.Visible = false; } catch { }
                try { _tray.Dispose(); } catch { }
                _tray = null;
            }
            if (_applicationIcon != null)
            {
                try { _applicationIcon.Dispose(); } catch { }
                _applicationIcon = null;
            }
        }
    }

