    internal sealed class RuntimeQueueItem
    {
        public int Occurrence;
        public int Slot;
        public string Phase = "";
        public string Audio = "";
        public string Artwork = "";
        public string Video = "";
        public string Visualizer = "";
        public bool TransitionReady;
        public bool SyncReady;
        public bool PresentationComplete;
        public bool Pinned;
        public bool SharedMedia;
        public double EtaSeconds = -1;
        public double EstimatedPrepareSeconds = -1;
        public double SlackSeconds = -1;
        public bool HasSlack;
        public string Risk = "";
        public string DecisionReason = "";
        public int OracleConfidence = -1;
        public int PredictiveConfidence = -1;
        public double PredictiveTailSeconds = -1;
        public double PredictiveAudioSlackSeconds = -1;
        public bool HasPredictiveAudioSlack;
        public string PredictiveAction = "";
        public string AdmissionPolicy = "";
        public int AdmissionScore = -1;
        public string AdmissionArtwork = "";
        public string AdmissionVideo = "";
        public string AdmissionVisualizer = "";
        public string FaultArtwork = "";
        public string FaultVideo = "";
        public string FaultVisualizer = "";
        public string CacheAudio = "";
        public string CacheArtwork = "";
        public string CacheVideo = "";
        public string CacheVisualizer = "";
        public string PerfBottleneck = "";
        public int PerfQueueMs = -1;
        public int PerfServiceMs = -1;
        public int PerfTotalMs = -1;
        public bool PerfAnomaly;
        public double PerfP95Seconds = -1;
        public int VideoActualHeight;
        public bool VideoFallback;
        public string VideoRouteLabel = "";
        public double PresentationSlaSeconds = -1;
        public double PresentationWaitSeconds = -1;
        public bool PresentationSlaYielded;

        public bool HasActiveWork
        {
            get
            {
                return IsBusy(Audio) || IsBusy(Artwork) || IsBusy(Video) || IsBusy(Visualizer) ||
                       String.Equals(Phase, "BUILDING", StringComparison.OrdinalIgnoreCase);
            }
        }

        private static bool IsBusy(string value)
        {
            return String.Equals(value, "ACTIVE", StringComparison.OrdinalIgnoreCase) ||
                   String.Equals(value, "QUEUED", StringComparison.OrdinalIgnoreCase);
        }

        public bool ProjectionEquals(RuntimeQueueItem other, bool timingSensitive)
        {
            if (other == null) return false;
            bool coreEqual = Occurrence == other.Occurrence && Slot == other.Slot &&
                String.Equals(Phase, other.Phase, StringComparison.Ordinal) && String.Equals(Audio, other.Audio, StringComparison.Ordinal) &&
                String.Equals(Artwork, other.Artwork, StringComparison.Ordinal) && String.Equals(Video, other.Video, StringComparison.Ordinal) &&
                String.Equals(Visualizer, other.Visualizer, StringComparison.Ordinal) && TransitionReady == other.TransitionReady &&
                SyncReady == other.SyncReady && PresentationComplete == other.PresentationComplete && Pinned == other.Pinned && SharedMedia == other.SharedMedia &&
                String.Equals(Risk, other.Risk, StringComparison.Ordinal) && String.Equals(DecisionReason, other.DecisionReason, StringComparison.Ordinal) &&
                OracleConfidence == other.OracleConfidence && PredictiveConfidence == other.PredictiveConfidence &&
                String.Equals(PredictiveAction, other.PredictiveAction, StringComparison.Ordinal) && String.Equals(AdmissionPolicy, other.AdmissionPolicy, StringComparison.Ordinal) &&
                AdmissionScore == other.AdmissionScore && String.Equals(AdmissionArtwork, other.AdmissionArtwork, StringComparison.Ordinal) &&
                String.Equals(AdmissionVideo, other.AdmissionVideo, StringComparison.Ordinal) && String.Equals(AdmissionVisualizer, other.AdmissionVisualizer, StringComparison.Ordinal) &&
                String.Equals(FaultArtwork, other.FaultArtwork, StringComparison.Ordinal) && String.Equals(FaultVideo, other.FaultVideo, StringComparison.Ordinal) &&
                String.Equals(FaultVisualizer, other.FaultVisualizer, StringComparison.Ordinal) && String.Equals(CacheAudio, other.CacheAudio, StringComparison.Ordinal) &&
                String.Equals(CacheArtwork, other.CacheArtwork, StringComparison.Ordinal) && String.Equals(CacheVideo, other.CacheVideo, StringComparison.Ordinal) &&
                String.Equals(CacheVisualizer, other.CacheVisualizer, StringComparison.Ordinal) && String.Equals(PerfBottleneck, other.PerfBottleneck, StringComparison.Ordinal) &&
                PerfAnomaly == other.PerfAnomaly && VideoActualHeight == other.VideoActualHeight && VideoFallback == other.VideoFallback &&
                String.Equals(VideoRouteLabel, other.VideoRouteLabel, StringComparison.Ordinal) && PresentationSlaYielded == other.PresentationSlaYielded;
            if (!coreEqual) return false;
            // R61.80: volatile countdown/performance timing is useful near NOW, but repainting
            // thousands of distant rows every time those numbers tick directly steals WPF frame
            // time. The authoritative values are still replaced in _runtimeQueue; this gate only
            // decides whether the row needs immediate visual invalidation.
            if (!timingSensitive) return true;
            return DisplaySecondEquals(EtaSeconds, other.EtaSeconds) && DisplaySecondEquals(EstimatedPrepareSeconds, other.EstimatedPrepareSeconds) &&
                DisplaySecondEquals(SlackSeconds, other.SlackSeconds) && HasSlack == other.HasSlack &&
                DisplaySecondEquals(PredictiveTailSeconds, other.PredictiveTailSeconds) &&
                DisplaySecondEquals(PredictiveAudioSlackSeconds, other.PredictiveAudioSlackSeconds) && HasPredictiveAudioSlack == other.HasPredictiveAudioSlack &&
                PerfQueueMs == other.PerfQueueMs && PerfServiceMs == other.PerfServiceMs && PerfTotalMs == other.PerfTotalMs &&
                DisplaySecondEquals(PerfP95Seconds, other.PerfP95Seconds) && DisplaySecondEquals(PresentationSlaSeconds, other.PresentationSlaSeconds) &&
                DisplaySecondEquals(PresentationWaitSeconds, other.PresentationWaitSeconds);
        }

        private static bool DisplaySecondEquals(double left, double right)
        {
            if (left < 0 || right < 0) return left < 0 && right < 0;
            return Math.Round(left) == Math.Round(right);
        }

        public static RuntimeQueueItem From(Dictionary<string, object> map)
        {
            return new RuntimeQueueItem
            {
                Occurrence = ToIntLocal(map, "index"),
                Slot = ToIntLocal(map, "order_slot"),
                Phase = StringLocal(map, "phase"),
                Audio = StringLocal(map, "audio"),
                Artwork = StringLocal(map, "artwork"),
                Video = StringLocal(map, "video"),
                Visualizer = StringLocal(map, "visualizer"),
                TransitionReady = BoolLocal(map, "transition_ready"),
                SyncReady = BoolLocal(map, "sync_ready"),
                PresentationComplete = BoolLocal(map, "presentation_complete"),
                Pinned = BoolLocal(map, "pinned"),
                SharedMedia = BoolLocal(map, "shared_media"),
                EtaSeconds = DoubleLocal(map, "eta_seconds", -1),
                EstimatedPrepareSeconds = DoubleLocal(map, "estimated_prepare_seconds", -1),
                SlackSeconds = DoubleLocal(map, "slack_seconds", -1),
                HasSlack = map != null && map.ContainsKey("slack_seconds"),
                Risk = StringLocal(map, "risk"),
                DecisionReason = StringLocal(map, "decision_reason"),
                OracleConfidence = ToIntLocal(map, "oracle_confidence", -1),
                PredictiveConfidence = ToIntLocal(map, "predictive_confidence", -1),
                PredictiveTailSeconds = DoubleLocal(map, "predictive_tail_seconds", -1),
                PredictiveAudioSlackSeconds = DoubleLocal(map, "predictive_audio_slack_seconds", -1),
                HasPredictiveAudioSlack = BoolLocal(map, "predictive_audio_slack_known"),
                PredictiveAction = StringLocal(map, "predictive_action"),
                AdmissionPolicy = StringLocal(map, "admission_policy"),
                AdmissionScore = ToIntLocal(map, "admission_score", -1),
                AdmissionArtwork = StringLocal(map, "admission_artwork"),
                AdmissionVideo = StringLocal(map, "admission_video"),
                AdmissionVisualizer = StringLocal(map, "admission_visualizer"),
                FaultArtwork = StringLocal(map, "fault_artwork"),
                FaultVideo = StringLocal(map, "fault_video"),
                FaultVisualizer = StringLocal(map, "fault_visualizer"),
                CacheAudio = StringLocal(map, "cache_audio"),
                CacheArtwork = StringLocal(map, "cache_artwork"),
                CacheVideo = StringLocal(map, "cache_video"),
                CacheVisualizer = StringLocal(map, "cache_visualizer"),
                PerfBottleneck = StringLocal(map, "perf_bottleneck"),
                PerfQueueMs = ToIntLocal(map, "perf_queue_ms", -1),
                PerfServiceMs = ToIntLocal(map, "perf_service_ms", -1),
                PerfTotalMs = ToIntLocal(map, "perf_total_ms", -1),
                PerfAnomaly = BoolLocal(map, "perf_anomaly"),
                PerfP95Seconds = DoubleLocal(map, "perf_p95_seconds", -1),
                VideoActualHeight = ToIntLocal(map, "video_actual_height", 0),
                VideoFallback = BoolLocal(map, "video_fallback"),
                VideoRouteLabel = StringLocal(map, "video_route_label"),
                PresentationSlaSeconds = DoubleLocal(map, "presentation_sla_seconds", -1),
                PresentationWaitSeconds = DoubleLocal(map, "presentation_wait_seconds", -1),
                PresentationSlaYielded = BoolLocal(map, "presentation_sla_yielded")
            };
        }

        private static string StringLocal(Dictionary<string, object> map, string key)
        {
            object value;
            return map != null && map.TryGetValue(key, out value) && value != null
                ? Convert.ToString(value, CultureInfo.InvariantCulture) ?? ""
                : "";
        }

        private static int ToIntLocal(Dictionary<string, object> map, string key, int fallback = 0)
        {
            object value;
            if (map == null || !map.TryGetValue(key, out value) || value == null)
                return fallback;
            try { return Convert.ToInt32(value, CultureInfo.InvariantCulture); } catch { return fallback; }
        }

        private static double DoubleLocal(Dictionary<string, object> map, string key, double fallback)
        {
            object value;
            if (map == null || !map.TryGetValue(key, out value) || value == null)
                return fallback;
            try { return Convert.ToDouble(value, CultureInfo.InvariantCulture); } catch { return fallback; }
        }

        private static bool BoolLocal(Dictionary<string, object> map, string key)
        {
            object value;
            if (map == null || !map.TryGetValue(key, out value) || value == null)
                return false;
            if (value is bool)
                return (bool)value;
            bool b;
            return Boolean.TryParse(Convert.ToString(value, CultureInfo.InvariantCulture), out b) && b;
        }
    }

