        public Visibility TimeColumnVisibility { get { return _timeColumnVisibility; } private set { Set(ref _timeColumnVisibility, value); } }
        public Visibility StateColumnVisibility { get { return _stateColumnVisibility; } private set { Set(ref _stateColumnVisibility, value); } }
        public Visibility MediaColumnVisibility { get { return _mediaColumnVisibility; } private set { Set(ref _mediaColumnVisibility, value); } }
        public Visibility PlaysColumnVisibility { get { return _playsColumnVisibility; } private set { Set(ref _playsColumnVisibility, value); } }

        public void SetColumnVisibility(bool favorite, bool number, bool channel, bool time, bool state, bool media, bool plays)
        {
            FavoriteColumnVisibility = favorite ? Visibility.Visible : Visibility.Collapsed;
            NumberColumnVisibility = number ? Visibility.Visible : Visibility.Collapsed;
            ChannelColumnVisibility = channel ? Visibility.Visible : Visibility.Collapsed;
            TimeColumnVisibility = time ? Visibility.Visible : Visibility.Collapsed;
            StateColumnVisibility = state ? Visibility.Visible : Visibility.Collapsed;
            MediaColumnVisibility = media ? Visibility.Visible : Visibility.Collapsed;
            PlaysColumnVisibility = plays ? Visibility.Visible : Visibility.Collapsed;
        }

