        public void SetStatus(Brush background, Brush border, Brush foreground)
        {
            StatusBackground = background;
            StatusBorder = border;
            StatusForeground = foreground;
        }

        internal static string ProductStatus(string value)
        {
            switch ((value ?? "").Trim().ToUpperInvariant())
            {
                case "WAITING": return "";
                case "QUEUED": return "";
                case "POLICY READY": return "Ready · protected";
                case "ISOLATED READY": return "Ready · contained";
                case "BUILDING": return "PREPARING";
                case "FAILED": return "AUDIO FAILED";
                default: return value ?? "";
            }
        }

        internal static string ProductSafety(string value)
        {
            string raw = (value ?? "").Trim();
            string upper = raw.ToUpperInvariant();
            if (upper.StartsWith("SLACK +", StringComparison.Ordinal)) return "MARGIN +" + raw.Substring(7);
            if (upper.StartsWith("SLACK -", StringComparison.Ordinal) || upper.StartsWith("SLACK -", StringComparison.Ordinal)) return "MARGIN -" + raw.Substring(7).TrimStart('-','-');
            if (upper.StartsWith("ETA ", StringComparison.Ordinal)) return "PREP ~" + raw.Substring(4);
            switch (upper)
            {
                case "FULL READY": return "READY";
                case "POLICY READY": return "RESOURCES PROTECTED";
                case "ISOLATED READY": return "VISUAL CONTAINED";
                case "AUDIO WON SLA": return "AUDIO FIRST";
                case "NOT PROFILED": return "CHECKING";
                case "NOT READY": return "WAITING";
                default: return raw;
            }
        }

        public event PropertyChangedEventHandler PropertyChanged;

        private bool SetValue<T>(ref T field, T value, string propertyName)
        {
            if (EqualityComparer<T>.Default.Equals(field, value)) return false;
            field = value;
            OnPropertyChanged(propertyName);
            return true;
        }

        private void OnPropertyChanged(string propertyName)
        {
            var handler = PropertyChanged;
            if (handler != null) handler(this, new PropertyChangedEventArgs(propertyName));
        }

        private void Set<T>(ref T field, T value, [CallerMemberName] string propertyName = null)
        {
            SetValue(ref field, value, propertyName);
        }
    }
}
